[Serializable]
public class AlliancePact
{
	public string PactId;

	public string PactName;

	public int ColorIndex;

	public int LeaderGangId;

	public List<int> MemberIds = new List<int>();

	public float ColorR;

	public float ColorG;

	public float ColorB;

	public int FormedDays;

	public bool PlayerInvited;

	public bool IsPending;

	public float EarningRate = 0.05f;

	public int CrewCapacityBonus;

	public int LastVoteDay = -1;

	public int LastVoteType;

	public Dictionary<int, float> BossHappiness = new Dictionary<int, float>();

	public Dictionary<int, int> VotePreferences = new Dictionary<int, int>();

	public int PlayerProposedVote = -1;

	public int PendingVoteCycleDay = -1;

	public bool VotePromptShown;

	public bool VotePromptAnswered;

	public bool PlayerColorConfirmed = true;

	public float GetBossHappiness(int gangId)
	{
		if (BossHappiness.TryGetValue(gangId, out float val))
			return val;
		return 1f;
	}

	public void SetBossHappiness(int gangId, float value)
	{
		BossHappiness[gangId] = Mathf.Clamp01(value);
	}

	public string DisplayName
	{
		get
		{
			if (!string.IsNullOrEmpty(PactName))
			{
				return PactName;
			}
			return $"Pact {ColorIndex + 1}";
		}
	}

	public Color SharedColor
	{
		get
		{
			return new Color(ColorR, ColorG, ColorB);
		}
		set
		{

			ColorR = value.r;
			ColorG = value.g;
			ColorB = value.b;
		}
	}

	public SimTime Formed
	{
		get
		{
			return new SimTime(FormedDays);
		}
		set
		{
			FormedDays = value.days;
		}
	}

	public bool IsActive
	{
		get
		{
			if (!IsPending)
			{
				return MemberIds.Count > 0;
			}
			return false;
		}
	}

	public bool IsMember(PlayerID pid)
	{

		if (!MemberIds.Contains(pid.id))
		{
			return LeaderGangId == pid.id;
		}
		return true;
	}
}

