[Serializable]
public class InterPactAlliance
{
	public string AllianceId = string.Empty;

	public string LeftPactId = string.Empty;

	public string RightPactId = string.Empty;

	public int CreatedDay = -1;

	public bool Active = true;

	public bool Involves(string pactId)
	{
		if (string.IsNullOrEmpty(pactId))
		{
			return false;
		}
		return string.Equals(LeftPactId, pactId, StringComparison.Ordinal) || string.Equals(RightPactId, pactId, StringComparison.Ordinal);
	}

	public string GetOtherPactId(string pactId)
	{
		if (string.IsNullOrEmpty(pactId))
		{
			return string.Empty;
		}
		if (string.Equals(LeftPactId, pactId, StringComparison.Ordinal))
		{
			return RightPactId ?? string.Empty;
		}
		if (string.Equals(RightPactId, pactId, StringComparison.Ordinal))
		{
			return LeftPactId ?? string.Empty;
		}
		return string.Empty;
	}
}
