	internal static bool IsCrewCurrentlyJailed(EntityID peepId)
	{
		if (peepId.IsNotValid)
		{
			return false;
		}
		try
		{
			return ReconcileCrewJailState(peepId, "query");
		}
		catch
		{
			return false;
		}
	}

	internal static bool ReconcileCrewJailState(EntityID peepId, string source)
	{
		if (peepId.IsNotValid)
		{
			return false;
		}

		CrewModState state = GetCrewStateOrNull(peepId);
		if (!JailSystem.HasCustodyRuntime())
		{
			return state != null && state.InJail;
		}

		bool pendingSafeFederalArrest = TryGetSafeFederalArrestPendingInfo(peepId, out SafeFederalArrestPendingInfo pendingInfo);
		bool pendingLocalImportantWitnessCustody = TryGetLocalImportantWitnessCustodyPendingInfo(peepId, out LocalImportantWitnessCustodyPendingInfo localPendingInfo);
		bool baseInJail = JailSystem.IsInJail(peepId);
		if (state == null && (pendingSafeFederalArrest || pendingLocalImportantWitnessCustody))
		{
			state = GetOrCreateCrewState(peepId);
		}
		if (state == null)
		{
			return baseInJail || pendingSafeFederalArrest;
		}

		Entity peep = null;
		try
		{
			peep = peepId.FindEntity();
		}
		catch
		{
		}

		bool pendingLocalWitnessOnly = pendingLocalImportantWitnessCustody && !baseInJail && !pendingSafeFederalArrest;
		if (pendingLocalWitnessOnly)
		{
			int pendingTrialDays = Mathf.Max(Mathf.Max(0, localPendingInfo.TrialDaysRemaining), state.TrialDaysRemaining);
			state.InJail = false;
			state.DaysInJail = 0;
			state.TrialDaysRemaining = Mathf.Max(0, pendingTrialDays);
			state.CaseDismissed = false;
			state.ExtraJailYears = Mathf.Max(state.ExtraJailYears, localPendingInfo.ExtraJailYears);
			state.FedsIncoming = false;
			state.FedArrivalCountdown = 0;
			VerificationLog("Jail", $"local-important-witness-pending-state peep={peepId.id} source={source} trialDays={state.TrialDaysRemaining} pendingDay={localPendingInfo.Day}");
			return false;
		}

		bool effectiveInJail = baseInJail || pendingSafeFederalArrest;
		if (!effectiveInJail)
		{
			if (state.InJail || state.DaysInJail > 0 || state.TrialDaysRemaining > 0 || state.CaseDismissed)
			{
				state.InJail = false;
				state.DaysInJail = 0;
				state.TrialDaysRemaining = 0;
				state.CaseDismissed = false;
				VerificationLog("Jail", $"reconciled peep={peepId.id} source={source} state=cleared");
			}
			return false;
		}

		var (daysToTrial, _, _) = JailSystem.GetArrestInfo(peepId);
		if (pendingSafeFederalArrest && daysToTrial <= 0)
		{
			daysToTrial = Mathf.Max(0, pendingInfo.TrialDate.days - G.GetNow().days);
		}
		if (pendingLocalImportantWitnessCustody && !baseInJail)
		{
			int pendingTrialDays = Mathf.Max(Mathf.Max(0, localPendingInfo.TrialDaysRemaining), state.TrialDaysRemaining);
			daysToTrial = Mathf.Max(daysToTrial, pendingTrialDays);
			state.ExtraJailYears = Mathf.Max(state.ExtraJailYears, localPendingInfo.ExtraJailYears);
		}
		else if (pendingLocalImportantWitnessCustody)
		{
			state.ExtraJailYears = Mathf.Max(state.ExtraJailYears, localPendingInfo.ExtraJailYears);
		}
		var (daysRemaining, _) = JailSystem.GetImprisonmentInfo(peepId);
		state.InJail = true;
		state.TrialDaysRemaining = Mathf.Max(0, daysToTrial);
		state.DaysInJail = pendingSafeFederalArrest ? 0 : Mathf.Max(0, daysRemaining);
		state.CaseDismissed = false;
		if (pendingLocalImportantWitnessCustody)
		{
			state.FedsIncoming = false;
			state.FedArrivalCountdown = 0;
		}
		ClearJailBlockedAwayStates(peep, state, "reconcile-" + source, custodyAlreadyConfirmed: true);
		if (pendingSafeFederalArrest)
		{
			LogJailReconcileOncePerFrame(
				"safe-federal-reconcile-pending-custody",
				peepId,
				source,
				$"safe-federal-reconcile-pending-custody peep={peepId.id} source={source} trialDays={state.TrialDaysRemaining}");
		}
		if (pendingLocalImportantWitnessCustody)
		{
			LogJailReconcileOncePerFrame(
				"local-important-witness-reconcile-custody",
				peepId,
				source,
				$"local-important-witness-reconcile-custody peep={peepId.id} source={source} trialDays={state.TrialDaysRemaining} pendingDay={localPendingInfo.Day}");
			if (baseInJail)
			{
				ClearLocalImportantWitnessCustodyPending(peepId, "base-jail");
			}
		}
		return true;
	}

	private static void LogJailReconcileOncePerFrame(string eventName, EntityID peepId, string source, string message)
	{
		try
		{
			string normalizedSource = string.IsNullOrEmpty(source) ? "unknown" : source;
			string key = eventName + ":" + peepId.id + ":" + normalizedSource;
			int frame = Time.frameCount;
			if (_lastJailReconcileLogFrameByKey.TryGetValue(key, out int lastFrame) && lastFrame == frame)
			{
				return;
			}
			_lastJailReconcileLogFrameByKey[key] = frame;
		}
		catch
		{
		}

		VerificationLog("Jail", message);
	}

	internal static void ReconcileAllCrewJailStates(string source)
	{
		if (SaveData?.CrewStates == null || SaveData.CrewStates.Count == 0)
		{
			return;
		}

		foreach (long rawPeepId in SaveData.CrewStates.Keys.ToList())
		{
			try
			{
				ReconcileCrewJailState(EntityID.FromID((ulong)rawPeepId), source);
			}
			catch
			{
			}
		}
	}

	private static bool IsCrewEffectivelyInCustodyWithoutReconcile(EntityID peepId, CrewModState state)
	{
		if (peepId.IsNotValid)
		{
			return false;
		}

		if (state?.InJail == true)
		{
			return true;
		}

		try
		{
			if (JailSystem.HasCustodyRuntime() && JailSystem.IsInJail(peepId))
			{
				return true;
			}
		}
		catch
		{
		}

		if (IsSafeFederalArrestPendingToday(peepId))
		{
			return true;
		}

		return IsLocalImportantWitnessCustodyPendingToday(peepId);
	}

	internal static bool ClearJailBlockedAwayStates(Entity peep, CrewModState state, string source, bool custodyAlreadyConfirmed = false)
	{
		if (peep == null || state == null)
		{
			return false;
		}

		bool effectiveCustody = custodyAlreadyConfirmed || IsCrewEffectivelyInCustodyWithoutReconcile(peep.Id, state);
		if (!effectiveCustody)
		{
			return false;
		}

		bool changed = state.OnVacation || state.VacationPending || state.OnHideout || state.HideoutPending;
		if (!changed)
		{
			return false;
		}
		if (custodyAlreadyConfirmed)
		{
			VerificationLog("Jail", $"blocked-away-custody-confirmed peep={peep.Id.id} source={source} mode=confirmed");
		}
		else
		{
			VerificationLog("Jail", $"blocked-away-custody-confirmed peep={peep.Id.id} source={source} mode=effective");
		}
		state.OnVacation = false;
		state.VacationPending = false;
		state.VacationReturnsRaw = 0L;
		state.OnHideout = false;
		state.HideoutPending = false;
		state.HideoutReturnsRaw = 0L;
		state.HideoutLastUpkeepDay = -1;
		state.HideoutMissedPayments = 0;
		state.HideoutForcedReturn = false;
		state.FedsIncoming = false;
		state.FedArrivalCountdown = 0;
		VerificationLog("Jail", $"blocked-away-state-cleared source={source} peep={peep.Id.id}");
		return true;
	}

	private static void EnsureCrewRemovedFromBoardAfterArrest(PlayerInfo player, CrewAssignment arrestedCrew, Entity peep, string source)
	{
		if (player?.crew == null || peep == null || !arrestedCrew.IsValid || !peep.Id.IsValid)
		{
			return;
		}
		try
		{
			if (!player.crew.IsOnBoard(peep.Id))
			{
				return;
			}
			player.crew.RemoveCrewFromBoard(arrestedCrew, (PlayerCrewData.OffBoardReason)0, false, 7);
			Debug.Log("[GameplayTweaks] " + (peep.data?.person?.FullName ?? "crew") + $" removed from board ({source})");
			if (player.PID.IsHumanPlayer)
			{
				RefreshCrewHudUi(source + "-board-remove", rebuildCards: true);
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] EnsureCrewRemovedFromBoardAfterArrest failed: " + ex.Message);
		}
	}

	private static bool ExecuteLocalImportantWitnessArrest(PlayerInfo player, Entity peep, string source)
	{
		if (player?.crew == null || peep == null || peep.Id.IsNotValid)
		{
			return false;
		}

		CrewAssignment pendingCrew = player.crew.GetCrewForPeep(peep.Id);
		if (!pendingCrew.IsValid)
		{
			return false;
		}

		CrewModState state = GetOrCreateCrewState(peep.Id);
		int pendingTrialDays = 7;
		int extraJailYears = 0;
		if (state != null)
		{
			state.InJail = false;
			state.DaysInJail = 0;
			state.TrialDaysRemaining = Mathf.Max(state.TrialDaysRemaining, 7);
			state.FedsIncoming = false;
			state.FedArrivalCountdown = 0;
			state.CaseDismissed = false;
			pendingTrialDays = state.TrialDaysRemaining;
			extraJailYears = state.ExtraJailYears;
		}

		MarkLocalImportantWitnessCustodyPending(peep.Id, NATIONAL_HEAT_SOURCE_COP_ASSAULT, pendingTrialDays, extraJailYears);
		VerificationLog("Jail", $"local-important-witness-custody-staged peep={peep.Id.id}{FormatHumanCrewIndexTag(peep.Id)} source={source} trialDays={pendingTrialDays} extraYears={extraJailYears}");
		VerificationLog("DeathAttribution", $"source=raid peep={peep.Id.id} action=pending-custody");
		return true;
	}

	private static void EnsureHumanPrecinctRaidTransientStateForCurrentDay()
	{
		int day = G.GetNow().days;
		if (_lastHumanPrecinctRaidTransientDay == day)
		{
			ClearStaleSafeFederalArrestPendingEntriesForCurrentDay();
			ClearStaleLocalImportantWitnessCustodyPendingEntriesForCurrentDay();
			return;
		}

		_lastHumanPrecinctRaidTransientDay = day;
		_directArrestVehicleSnapshotsByPeep.Clear();
		_consumedHumanPrecinctRaidEventKeys.Clear();
		_deferredDirectArrestRefreshByVehicle.Clear();
		_deferredCrewVehicleReassignedEventsByVehicle.Clear();
		_deferredSafeFederalArrestFollowupsByPeep.Clear();
		_safeFederalArrestPendingByPeep.Clear();
		_localImportantWitnessCustodyPendingByPeep.Clear();
	}

	private static bool TryGetVehicleArrestSurvivorState(PlayerInfo player, EntityID vehicleId, out Entity vehicleEntity, out EntityID activeDriverId, out int liveOccupants)
	{
		vehicleEntity = null;
		activeDriverId = EntityID.INVALID;
		liveOccupants = 0;
		if (player?.crew == null || !vehicleId.IsValid)
		{
			return false;
		}

		liveOccupants = MultiCrewVehicleHelper.GetLiveVehicleCrewCount(player.crew, vehicleId);
		if (liveOccupants <= 0)
		{
			return false;
		}

		vehicleEntity = vehicleId.FindEntity();
		activeDriverId = MultiCrewVehicleHelper.GetDriverPeepId(player.crew, vehicleId);
		return vehicleEntity != null;
	}

	private static bool TryGetVehicleArrestSurvivorState(PlayerInfo player, CrewAssignment arrestedCrew, out Entity vehicleEntity, out EntityID activeDriverId, out int liveOccupants)
	{
		vehicleEntity = null;
		activeDriverId = EntityID.INVALID;
		liveOccupants = 0;
		if (player?.crew == null || !arrestedCrew.IsValid || !arrestedCrew.IsInVehicle || !arrestedCrew.VehicleID.IsValid)
		{
			return false;
		}

		return TryGetVehicleArrestSurvivorState(player, arrestedCrew.VehicleID, out vehicleEntity, out activeDriverId, out liveOccupants);
	}

	internal static void CaptureDirectArrestVehicleSnapshot(PlayerInfo player, CrewAssignment crew, Node arrestNode, string source)
	{
		if (player?.crew == null || !player.PID.IsHumanPlayer || !crew.IsValid || !crew.peepId.IsValid || !crew.IsInVehicle || !crew.VehicleID.IsValid)
		{
			return;
		}

		try
		{
			EnsureHumanPrecinctRaidTransientStateForCurrentDay();
			var snapshot = new DirectArrestVehicleSnapshot
			{
				Day = G.GetNow().days,
				PeepId = crew.peepId,
				VehicleId = crew.VehicleID,
				DriverPeepId = MultiCrewVehicleHelper.GetDriverPeepId(player.crew, crew.VehicleID),
				VehicleNodeId = arrestNode?.id ?? NodeID.INVALID,
				VehicleNodeSource = arrestNode != null ? source : string.Empty
			};
			if (MultiCrewVehicleHelper.TryGetAuthoritativeVehicleNodeId(crew.VehicleID, out NodeID vehicleNodeId, out string nodeSource) && vehicleNodeId.IsValid)
			{
				snapshot.VehicleNodeId = vehicleNodeId;
				snapshot.VehicleNodeSource = nodeSource ?? string.Empty;
			}

			foreach (CrewAssignment assignment in player.crew.AllCrew)
			{
				if (assignment.VehicleID != crew.VehicleID || !MultiCrewVehicleHelper.IsActiveVehicleOccupant(player.crew, assignment))
				{
					continue;
				}

				snapshot.OccupantIds.Add(assignment.peepId);
			}

			SelectionManager selection = global::Game.Game.ctx?.selection;
			Entity currentActive = selection?.CurrentActive;
			if (currentActive != null && (currentActive.Id == crew.peepId || currentActive.Id == crew.VehicleID))
			{
				snapshot.WasSelected = true;
				snapshot.SelectedEntityId = currentActive.Id;
			}

			_directArrestVehicleSnapshotsByPeep[unchecked((long)crew.peepId.id)] = snapshot;
			string occupants = snapshot.OccupantIds.Count > 0
				? string.Join(",", snapshot.OccupantIds.Select(id => id.id.ToString()))
				: "none";
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-vehicle-snapshot peep={crew.peepId.id} vehicle={crew.VehicleID.id} driver={snapshot.DriverPeepId.id} node={snapshot.VehicleNodeId} nodeSource={snapshot.VehicleNodeSource} selected={snapshot.WasSelected} occupants={occupants} source={source}");
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] CaptureDirectArrestVehicleSnapshot failed: " + ex.Message);
		}
	}

	private static bool TryGetDirectArrestVehicleSnapshot(EntityID peepId, out DirectArrestVehicleSnapshot snapshot)
	{
		snapshot = null;
		if (peepId.IsNotValid)
		{
			return false;
		}

		EnsureHumanPrecinctRaidTransientStateForCurrentDay();
		return _directArrestVehicleSnapshotsByPeep.TryGetValue(unchecked((long)peepId.id), out snapshot) && snapshot != null;
	}

	private static bool TryBuildHumanPrecinctRaidEventKey(EntityID peepId, Node arrestNode, out string eventKey, out NodeID eventNodeId, out string keySource)
	{
		eventKey = string.Empty;
		eventNodeId = arrestNode?.id ?? NodeID.INVALID;
		keySource = arrestNode != null ? "arrest-node" : "none";
		if (peepId.IsNotValid)
		{
			return false;
		}

		EnsureHumanPrecinctRaidTransientStateForCurrentDay();
		if (!eventNodeId.IsValid && _pendingHumanCornerHeatPrecinctRaidActive && _pendingHumanCornerHeatPrecinctRaidDay == G.GetNow().days && _pendingHumanCornerHeatRaidNodeId.IsValid)
		{
			eventNodeId = _pendingHumanCornerHeatRaidNodeId;
			keySource = "pending-node";
		}
		if (!eventNodeId.IsValid && TryGetDirectArrestVehicleSnapshot(peepId, out DirectArrestVehicleSnapshot snapshot) && snapshot.VehicleNodeId.IsValid)
		{
			eventNodeId = snapshot.VehicleNodeId;
			keySource = "snapshot-node";
		}
		if (!eventNodeId.IsValid)
		{
			return false;
		}

		eventKey = G.GetNow().days + ":" + eventNodeId + ":" + peepId.id;
		return true;
	}

	internal static bool IsHumanPrecinctRaidEventConsumed(EntityID peepId, Node arrestNode, string source)
	{
		if (!TryBuildHumanPrecinctRaidEventKey(peepId, arrestNode, out string eventKey, out NodeID eventNodeId, out _))
		{
			return false;
		}

		if (!_consumedHumanPrecinctRaidEventKeys.Contains(eventKey))
		{
			return false;
		}

		VerificationLog("CornerHeatRaid", $"precinct-raid-event-deduped peep={peepId.id} node={eventNodeId} source={source}");
		return true;
	}

	internal static void MarkHumanPrecinctRaidEventConsumed(EntityID peepId, Node arrestNode, string source)
	{
		if (!TryBuildHumanPrecinctRaidEventKey(peepId, arrestNode, out string eventKey, out NodeID eventNodeId, out string keySource))
		{
			VerificationLog("CornerHeatRaid", $"precinct-raid-event-forced-close peep={peepId.id} node={NodeID.INVALID} source={source} reason=no-key");
			if (_pendingHumanCornerHeatPrecinctRaidActive)
			{
				VerificationLog("CornerHeatRaid", $"precinct-raid-context-resolved-early peep={peepId.id} node={_pendingHumanCornerHeatRaidNodeId} source={source} keySource=none");
				ResolvePendingHumanCornerHeatPrecinctRaid(true);
			}
			return;
		}

		if (!_consumedHumanPrecinctRaidEventKeys.Add(eventKey))
		{
			VerificationLog("CornerHeatRaid", $"precinct-raid-event-deduped peep={peepId.id} node={eventNodeId} source={source}");
			return;
		}

		if (!string.Equals(keySource, "arrest-node", StringComparison.Ordinal))
		{
			VerificationLog("CornerHeatRaid", $"precinct-raid-event-forced-close peep={peepId.id} node={eventNodeId} source={source} keySource={keySource}");
		}
		VerificationLog("CornerHeatRaid", $"precinct-raid-event-consumed peep={peepId.id} node={eventNodeId} source={source}");
		if (_pendingHumanCornerHeatPrecinctRaidActive)
		{
			VerificationLog("CornerHeatRaid", $"precinct-raid-context-resolved-early peep={peepId.id} node={_pendingHumanCornerHeatRaidNodeId} source={source} keySource={keySource}");
			ResolvePendingHumanCornerHeatPrecinctRaid(true);
		}
	}

