	private static bool TryGetSafeFederalArrestPendingInfo(EntityID peepId, out SafeFederalArrestPendingInfo info)
	{
		info = null;
		if (peepId.IsNotValid)
		{
			return false;
		}

		if (!_safeFederalArrestPendingByPeep.TryGetValue(unchecked((long)peepId.id), out info) || info == null)
		{
			info = null;
			return false;
		}

		if (info.Day != G.GetNow().days)
		{
			_safeFederalArrestPendingByPeep.Remove(unchecked((long)peepId.id));
			info = null;
			return false;
		}

		return true;
	}

	private static bool TryGetLocalImportantWitnessCustodyPendingInfo(EntityID peepId, out LocalImportantWitnessCustodyPendingInfo info)
	{
		info = null;
		if (peepId.IsNotValid)
		{
			return false;
		}

		long key = unchecked((long)peepId.id);
		if (!_localImportantWitnessCustodyPendingByPeep.TryGetValue(key, out info) || info == null)
		{
			info = null;
			return false;
		}

		if (info.Day != G.GetNow().days)
		{
			ClearLocalImportantWitnessCustodyPending(peepId, "stale-day");
			info = null;
			return false;
		}

		return true;
	}

