	private static void ClearStaleSafeFederalArrestPendingEntriesForCurrentDay()
	{
		if (_safeFederalArrestPendingByPeep.Count == 0)
		{
			return;
		}

		int today = G.GetNow().days;
		foreach (long key in _safeFederalArrestPendingByPeep
			.Where(pair => pair.Value == null || pair.Value.Day != today)
			.Select(pair => pair.Key)
			.ToList())
		{
			_safeFederalArrestPendingByPeep.Remove(key);
		}
	}

	private static void ClearStaleLocalImportantWitnessCustodyPendingEntriesForCurrentDay()
	{
		if (_localImportantWitnessCustodyPendingByPeep.Count == 0)
		{
			return;
		}

		int today = G.GetNow().days;
		foreach (long key in _localImportantWitnessCustodyPendingByPeep
			.Where(pair => pair.Value == null || pair.Value.Day != today)
			.Select(pair => pair.Key)
			.ToList())
		{
			EntityID peepId = EntityID.FromID(unchecked((ulong)key));
			ClearLocalImportantWitnessCustodyPending(peepId, "stale-day");
		}
	}

	internal static bool ShouldSuppressVanillaStartHumanArrestForLocalImportantWitness(EntityID peepId, out int pendingDay, out int sourceType)
	{
		pendingDay = -1;
		sourceType = -1;
		LocalImportantWitnessCustodyPendingInfo info = null;
		if (!TryGetLocalImportantWitnessCustodyPendingInfo(peepId, out info) || info == null)
		{
			return false;
		}

		if (info.SourceType != NATIONAL_HEAT_SOURCE_COP_ASSAULT)
		{
			return false;
		}

		if (IsFederalImportantWitnessSource(_currentNationalHeatArrestSourceType) || WasSafeFederalArrestHandledToday(peepId))
		{
			return false;
		}

		pendingDay = info.Day;
		sourceType = info.SourceType;
		return true;
	}

	internal static bool HasSafeFederalArrestPendingForVehicleToday(EntityID vehicleId, EntityID exceptPeepId, out EntityID pendingPeepId)
	{
		pendingPeepId = EntityID.INVALID;
		if (vehicleId.IsNotValid || _safeFederalArrestPendingByPeep.Count == 0)
		{
			return false;
		}

		int today = G.GetNow().days;
		foreach (SafeFederalArrestPendingInfo info in _safeFederalArrestPendingByPeep.Values)
		{
			if (info == null || info.Day != today || info.VehicleId != vehicleId || info.PeepId == exceptPeepId)
			{
				continue;
			}

			pendingPeepId = info.PeepId;
			return true;
		}

		return false;
	}

	private static void QueueDeferredSafeFederalArrestFollowup(EntityID peepId, EntityID vehicleId, NodeID nodeId, PlayerID playerId, SimTime trialDate, int bribeCost, string source, int sourceType, int witnessDueDay)
	{
		if (peepId.IsNotValid || vehicleId.IsNotValid || !playerId.IsValid)
		{
			return;
		}

		long peepKey = unchecked((long)peepId.id);
		_deferredSafeFederalArrestFollowupsByPeep[peepKey] = new DeferredSafeFederalArrestFollowup
		{
			Day = G.GetNow().days,
			QueuedFrame = Time.frameCount,
			PeepId = peepId,
			VehicleId = vehicleId,
			NodeId = nodeId,
			PlayerId = playerId,
			TrialDate = trialDate,
			BribeCost = bribeCost,
			SourceType = sourceType,
			WitnessDueDay = witnessDueDay,
			Source = source ?? string.Empty
		};
		VerificationLog("VehicleNodeAuthority", $"federal-arrest-followup-deferred peep={peepId.id} vehicle={vehicleId.id} node={nodeId} trialDay={trialDate.days} bribe={bribeCost} source={source}");
	}

	private static ImportantWitnessEntry FindActiveImportantWitnessEntry(EntityID peepId, int sourceType, int dueDay = -1)
	{
		if (peepId.IsNotValid || SaveData.NationalHeat?.WitnessEntries == null)
		{
			return null;
		}

		long peepLongId = (long)peepId.id;
		return SaveData.NationalHeat.WitnessEntries.FirstOrDefault(e => e != null
			&& !e.ArrestProcessed
			&& e.CrewPeepId == peepLongId
			&& e.SourceType == sourceType
			&& (dueDay < 0 || e.ArrestDueDay == dueDay));
	}

	private static void ClearDeferredFederalWitnessFinalization(ImportantWitnessEntry entry)
	{
		if (entry == null)
		{
			return;
		}

		entry.DeferredFederalFinalizationPending = false;
		entry.DeferredFederalFinalizationDay = -1;
	}

	private static void MarkImportantWitnessEntryProcessed(ImportantWitnessEntry entry)
	{
		if (entry == null)
		{
			return;
		}

		ClearDeferredFederalWitnessFinalization(entry);
		entry.ArrestProcessed = true;
	}

	private static bool TryMarkImportantWitnessSafeFederalPending(EntityID peepId, int sourceType, SimTime now, int dueDay)
	{
		if (sourceType != NATIONAL_HEAT_SOURCE_COP_KILL)
		{
			return false;
		}

		ImportantWitnessEntry entry = FindActiveImportantWitnessEntry(peepId, sourceType, dueDay)
			?? FindActiveImportantWitnessEntry(peepId, sourceType);
		if (entry == null)
		{
			return false;
		}

		entry.DeferredFederalFinalizationPending = true;
		entry.DeferredFederalFinalizationDay = now.days;
		VerificationLog("NationalHeat", $"important-witness-safe-federal-pending peep={peepId.id} dueDay={entry.ArrestDueDay} source={sourceType} pendingDay={entry.DeferredFederalFinalizationDay}");
		return true;
	}

	private static bool FinalizeImportantWitnessAfterSafeFederalFollowup(PlayerInfo humanPlayer, EntityID peepId, int sourceType, SimTime now, string sourceTag)
	{
		if (sourceType != NATIONAL_HEAT_SOURCE_COP_KILL)
		{
			return true;
		}

		ImportantWitnessEntry entry = FindActiveImportantWitnessEntry(peepId, sourceType);
		if (entry == null)
		{
			bool alreadyProcessed = SaveData.NationalHeat?.WitnessEntries?.Any(e => e != null
				&& e.CrewPeepId == (long)peepId.id
				&& e.SourceType == sourceType
				&& e.ArrestProcessed) == true;
			VerificationLog("NationalHeat", $"important-witness-safe-federal-finalization-noop peep={peepId.id} source={sourceType} trigger={sourceTag} reason={(alreadyProcessed ? "already-processed" : "missing-entry")}");
			return true;
		}

		CrewModState state = GetOrCreateCrewState(peepId);
		ApplyImportantWitnessSentenceBoost(peepId, state, entry);
		ResolveGroupedCopIncidentSnitchOutcome(humanPlayer, peepId, entry, now);
		MarkImportantWitnessEntryProcessed(entry);
		VerificationLog("NationalHeat", $"Important witness arrest executed peep={peepId.id} dueDay={entry.ArrestDueDay} extraYears={GetImportantWitnessSentenceBoostYears(entry.SourceType)} source={entry.SourceType}");
		if (IsGroupedCopWitnessSource(entry.SourceType))
		{
			VerificationLog("NationalHeat", $"grouped-cop-case-closeout peep={peepId.id} source={entry.SourceType} dueDay={entry.ArrestDueDay} reason=executed");
		}
		RecalculateNationalHeatState(now.days);
		VerificationLog("NationalHeat", $"important-witness-safe-federal-finalized peep={peepId.id} dueDay={entry.ArrestDueDay} source={entry.SourceType} trigger={sourceTag}");
		return true;
	}

	private static void FlushPendingSafeFederalArrestBookkeeping(DeferredSafeFederalArrestFollowup followup, string sourceTag)
	{
		if (followup == null || followup.PendingBookkeepingFlushed)
		{
			return;
		}

		CrewModState safeState = GetOrCreateCrewState(followup.PeepId);
		if (safeState != null)
		{
			int pendingTrialDays = Mathf.Max(0, followup.TrialDate.days - G.GetNow().days);
			safeState.InJail = true;
			safeState.DaysInJail = 0;
			safeState.TrialDaysRemaining = pendingTrialDays;
			safeState.CaseDismissed = false;
			safeState.FedsIncoming = false;
			Entity peep = followup.PeepId.FindEntity();
			if (peep != null)
			{
				ClearJailBlockedAwayStates(peep, safeState, "safe-federal-arrest-followup", custodyAlreadyConfirmed: true);
			}
		}

		VerificationLog("Jail", $"federal-arrest-pending-bookkeeping-flushed peep={followup.PeepId.id} vehicle={followup.VehicleId.id} trialDay={followup.TrialDate.days} source={followup.Source} trigger={sourceTag}");
		VerificationLog("DeathAttribution", $"source=raid peep={followup.PeepId.id} action=arrest");
		RecordDeathSource(followup.PeepId, "raid");
		followup.PendingBookkeepingFlushed = true;
	}

	internal static bool TryHandleSafeFederalHumanArrest(PlayerInfo player, CrewAssignment crew, string sourceTag)
	{
		if (player == null || !player.PID.IsHumanPlayer || !crew.IsValid || HasPendingHumanCornerHeatRaidContext())
		{
			return false;
		}
		if (ShouldDeferArrestForHideout(crew.peepId, sourceTag))
		{
			return false;
		}

		if (TryGetCurrentNationalHeatArrestSourceType(out int nationalHeatSourceType)
			&& nationalHeatSourceType != NATIONAL_HEAT_SOURCE_COP_KILL)
		{
			return false;
		}

		if (!TryGetDirectArrestVehicleSnapshot(crew.peepId, out DirectArrestVehicleSnapshot snapshot)
			|| snapshot == null
			|| !snapshot.VehicleId.IsValid
			|| snapshot.OccupantIds.Count <= 1)
		{
			return false;
		}

		if (!JailSystem.TryBuildFederalArrestRecord(player, crew, snapshot.VehicleNodeId.FindNode(), out ArrestEntry arrestEntry))
		{
			return false;
		}

		try
		{
			player.commands?.FlushQueue(crew.peepId, cancelActive: false);
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Safe federal arrest FlushQueue failed: " + ex.Message);
		}

		try
		{
			player.automation?.TryClearAutomationCrew(crew);
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Safe federal arrest automation clear failed: " + ex.Message);
		}

		if (!TrySuppressFederalArrestVehicleUnassign(player.crew, crew.peepId, out EntityID vehicleId) || vehicleId.IsNotValid)
		{
			return false;
		}

		Entity arrestedPeep = crew.peepId.FindEntity();
		if (arrestedPeep != null)
		{
			EnsureCrewRemovedFromBoardAfterArrest(player, crew, arrestedPeep, sourceTag + "-safe-federal");
		}

		MarkSafeFederalArrestHandled(crew.peepId);
		VerificationLog("VehicleNodeAuthority", $"federal-arrest-vanilla-start-skipped peep={crew.peepId.id} vehicle={vehicleId.id} node={snapshot.VehicleNodeId} source={sourceTag}");
		VerificationLog("VehicleNodeAuthority", $"federal-arrest-safe-lane-armed peep={crew.peepId.id} vehicle={vehicleId.id} node={snapshot.VehicleNodeId} source={sourceTag}");
		MarkSafeFederalArrestPending(crew.peepId, vehicleId, player.PID, arrestEntry.trialDate);
		int witnessSourceType = TryGetCurrentNationalHeatArrestSourceType(out int currentSourceType) ? currentSourceType : NATIONAL_HEAT_SOURCE_COP_KILL;
		ImportantWitnessEntry activeWitnessEntry = FindActiveImportantWitnessEntry(crew.peepId, witnessSourceType);
		int witnessDueDay = activeWitnessEntry?.ArrestDueDay ?? G.GetNow().days;
		QueueDeferredSafeFederalArrestFollowup(crew.peepId, vehicleId, snapshot.VehicleNodeId, player.PID, arrestEntry.trialDate, arrestEntry.payOffCost.cash.RoundCoarse(), sourceTag, witnessSourceType, witnessDueDay);
		VerificationLog("VehicleNodeAuthority", $"federal-arrest-safe-lane-returning peep={crew.peepId.id} vehicle={vehicleId.id} node={snapshot.VehicleNodeId} source={sourceTag}");
		return true;
	}

	private static bool CanBypassCornerRaidGateForFederalTurnEndFlush(DeferredDirectArrestVehicleRefresh refresh)
	{
		return refresh != null
			&& refresh.FederalArrestLane
			&& string.Equals(refresh.Reason, "federal-arrest", StringComparison.Ordinal)
			&& EnumerateDeferredDirectArrestAffectedPeepKeys(refresh).Any(peepKey => HasFederalArrestTerminalCloseoutToday(EntityID.FromID(unchecked((ulong)peepKey))));
	}

	private static IEnumerable<long> EnumerateDeferredDirectArrestAffectedPeepKeys(DeferredDirectArrestVehicleRefresh refresh)
	{
		if (refresh == null)
		{
			yield break;
		}

		HashSet<long> yieldedPeepKeys = new HashSet<long>();
		if (refresh.PeepId.IsValid)
		{
			long primaryPeepKey = unchecked((long)refresh.PeepId.id);
			yieldedPeepKeys.Add(primaryPeepKey);
			yield return primaryPeepKey;
		}

		foreach (long affectedPeepKey in refresh.AffectedPeepIds)
		{
			if (yieldedPeepKeys.Add(affectedPeepKey))
			{
				yield return affectedPeepKey;
			}
		}
	}

	private static bool DeferredDirectArrestRefreshHasPeep(DeferredDirectArrestVehicleRefresh refresh, EntityID peepId)
	{
		if (refresh == null || peepId.IsNotValid)
		{
			return false;
		}

		return EnumerateDeferredDirectArrestAffectedPeepKeys(refresh).Any(affectedPeepKey => affectedPeepKey == unchecked((long)peepId.id));
	}

	private static void TrackDeferredDirectArrestPeepArtifacts(DeferredDirectArrestVehicleRefresh refresh, EntityID peepId)
	{
		if (refresh == null || peepId.IsNotValid)
		{
			return;
		}

		long peepKey = unchecked((long)peepId.id);
		refresh.AffectedPeepIds.Add(peepKey);
		if (refresh.PeepId.IsNotValid)
		{
			refresh.PeepId = peepId;
		}

		if (_deferredCrewFedArrestEventsByPeep.TryGetValue(peepKey, out SessionEvent deferredEvent))
		{
			refresh.PendingCrewFedArrestEventsByPeep[peepKey] = deferredEvent;
			if (refresh.PendingCrewFedArrestEvent.type != SessionEventType.CrewFedArrest)
			{
				refresh.PendingCrewFedArrestEvent = deferredEvent;
			}
		}

		if (_deferredFederalArrestPresentationsByPeep.TryGetValue(peepKey, out DeferredFederalArrestPresentation deferredPresentation))
		{
			refresh.PendingFederalArrestPresentationsByPeep[peepKey] = deferredPresentation;
			if (refresh.PendingFederalArrestPresentation == null)
			{
				refresh.PendingFederalArrestPresentation = deferredPresentation;
			}
		}
	}

	private static void ClearDeferredDirectArrestPeepArtifacts(DeferredDirectArrestVehicleRefresh refresh)
	{
		if (refresh == null)
		{
			return;
		}

		foreach (long affectedPeepKey in EnumerateDeferredDirectArrestAffectedPeepKeys(refresh).ToList())
		{
			_deferredCrewFedArrestEventsByPeep.Remove(affectedPeepKey);
			_deferredFederalArrestPresentationsByPeep.Remove(affectedPeepKey);
		}

		refresh.PendingCrewFedArrestEventsByPeep.Clear();
		refresh.PendingFederalArrestPresentationsByPeep.Clear();
	}

	private static void ClearDeferredDirectArrestAffectedCopFedPickTargets(object pickManager, DeferredDirectArrestVehicleRefresh refresh, string sourceTag)
	{
		if (pickManager == null || refresh == null)
		{
			return;
		}

		try
		{
			int removedCount = 0;
			HashSet<int> processedPids = new HashSet<int>();
			foreach (long affectedPeepKey in EnumerateDeferredDirectArrestAffectedPeepKeys(refresh))
			{
				Entity peep = EntityID.FromID(unchecked((ulong)affectedPeepKey)).FindEntity();
				PlayerID pid = peep?.data?.agent?.pid ?? PlayerID.INVALID;
				if (pid.id < 0 || !processedPids.Add(pid.id))
				{
					continue;
				}

				if (CrewPickAggroRefreshStabilityPatch.TryClearCopOrFedCrewPickTargets(pickManager, pid, out int removedForPid))
				{
					removedCount += removedForPid;
				}
			}

			if (removedCount > 0)
			{
				VerificationLog("VehicleNodeAuthority", $"direct-arrest-copfed-picks-cleared vehicle={refresh.VehicleId.id} removed={removedCount} source={refresh.Source} trigger={sourceTag}");
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] ClearDeferredDirectArrestAffectedCopFedPickTargets failed: " + ex.Message);
		}
	}

	private static bool TryResolveFederalArrestCornerRaidGate(EntityID peepId, Node arrestNode, string source, string reason)
	{
		if (peepId.IsNotValid)
		{
			return false;
		}

		int today = G.GetNow().days;
		bool clearedCornerRaidContext = false;
		bool clearedPrecinctRaidContext = false;
		if (_pendingCornerHeatRaidActive && _pendingCornerHeatRaidDay == today)
		{
			ClearPendingCornerHeatRaidContext();
			clearedCornerRaidContext = true;
		}

		bool arrestNodeValid = arrestNode?.id.IsValid == true;
		bool nodeMatchesPrecinctRaid = arrestNodeValid
			&& _pendingHumanCornerHeatRaidNodeId.IsValid
			&& _pendingHumanCornerHeatRaidNodeId == arrestNode.id;
		if (_pendingHumanCornerHeatPrecinctRaidActive
			&& _pendingHumanCornerHeatPrecinctRaidDay == today
			&& (!arrestNodeValid || !_pendingHumanCornerHeatRaidNodeId.IsValid || nodeMatchesPrecinctRaid))
		{
			ResolvePendingHumanCornerHeatPrecinctRaid(true);
			clearedPrecinctRaidContext = true;
		}

		if (!clearedCornerRaidContext && !clearedPrecinctRaidContext)
		{
			return false;
		}

		VerificationLog("CornerHeatRaid", $"federal-arrest-raid-context-resolved peep={peepId.id} node={arrestNode?.id ?? NodeID.INVALID} source={source} reason={reason} clearedCornerRaid={clearedCornerRaidContext} clearedPrecinctRaid={clearedPrecinctRaidContext}");
		return true;
	}

	internal static bool HasPendingDeferredDirectArrestRepair()
	{
		if (_deferredDirectArrestRefreshByVehicle.Count == 0)
		{
			return false;
		}

		int today = G.GetNow().days;
		return _deferredDirectArrestRefreshByVehicle.Values.Any(refresh =>
			refresh != null
			&& refresh.Day == today
			&& (refresh.RepairVehicleAuthority || refresh.SyncVehicleNode || refresh.FederalArrestLane));
	}

	internal static bool ShouldSuppressSelectionFocusForDeferredArrest(Entity hoveredEntity, out EntityID vehicleId, out EntityID peepId, out string source)
	{
		vehicleId = EntityID.INVALID;
		peepId = EntityID.INVALID;
		source = string.Empty;
		if (hoveredEntity == null || _deferredDirectArrestRefreshByVehicle.Count == 0)
		{
			return false;
		}

		EntityID hoveredId = hoveredEntity.Id;
		if (hoveredId.IsNotValid)
		{
			return false;
		}

		int today = G.GetNow().days;
		foreach (DeferredDirectArrestVehicleRefresh refresh in _deferredDirectArrestRefreshByVehicle.Values)
		{
			if (refresh == null || refresh.Day != today || !refresh.FederalArrestLane)
			{
				continue;
			}
			if (!refresh.RepairVehicleAuthority && !refresh.SyncVehicleNode)
			{
				continue;
			}

			if (!DeferredDirectArrestRefreshHasPeep(refresh, hoveredId) && hoveredId != refresh.VehicleId)
			{
				continue;
			}

			vehicleId = refresh.VehicleId;
			peepId = refresh.PeepId;
			source = refresh.Source ?? string.Empty;
			return true;
		}

		return false;
	}

	internal static Node TryResolveDirectArrestSnapshotNode(EntityID peepId)
	{
		if (!TryGetDirectArrestVehicleSnapshot(peepId, out DirectArrestVehicleSnapshot snapshot) || !snapshot.VehicleNodeId.IsValid)
		{
			return null;
		}

		return snapshot.VehicleNodeId.FindNode();
	}

	private static bool TryGetDirectArrestVehicleSnapshotForVehicle(EntityID vehicleId, out DirectArrestVehicleSnapshot snapshot)
	{
		snapshot = null;
		if (!vehicleId.IsValid)
		{
			return false;
		}

		EnsureHumanPrecinctRaidTransientStateForCurrentDay();
		int today = G.GetNow().days;
		foreach (DirectArrestVehicleSnapshot candidate in _directArrestVehicleSnapshotsByPeep.Values)
		{
			if (candidate == null || candidate.Day != today || candidate.VehicleId != vehicleId)
			{
				continue;
			}

			snapshot = candidate;
			return true;
		}

		return false;
	}

	internal static bool TrySuppressFederalArrestVehicleUnassign(PlayerCrew crew, EntityID peepId, out EntityID vehicleId)
	{
		vehicleId = EntityID.INVALID;
		if (crew == null || !crew.PID.IsHumanPlayer || peepId.IsNotValid || HasPendingHumanCornerHeatRaidContext())
		{
			return false;
		}

		if (!TryGetDirectArrestVehicleSnapshot(peepId, out DirectArrestVehicleSnapshot snapshot)
			|| snapshot == null
			|| !snapshot.VehicleId.IsValid
			|| snapshot.OccupantIds.Count <= 1)
		{
			return false;
		}

		if (!MultiCrewVehicleHelper.TryUnassignHumanVehicleCrewMetadataOnly(crew, peepId, out vehicleId) || !vehicleId.IsValid)
		{
			return false;
		}

		global::Game.Game.ctx?.events?.EnqueueOnce(new SessionEvent(SessionEventType.CrewVehicleReassigned, vehicleId, crew.PID));
		VerificationLog("VehicleNodeAuthority", $"federal-arrest-unassign-teleport-suppressed peep={peepId.id} vehicle={vehicleId.id} source=snapshot");
		VerificationLog("VehicleNodeAuthority", $"federal-arrest-unassign-event-deferred peep={peepId.id} vehicle={vehicleId.id} source=snapshot");
		VerificationLog("VehicleNodeAuthority", $"federal-arrest-unassign-metadata-only peep={peepId.id} vehicle={vehicleId.id} source=snapshot");
		return true;
	}

	internal static bool ShouldDeferHumanCrewVehicleReassignedEvent(SessionEvent sev, out EntityID peepId, out NodeID nodeId, out string source)
	{
		peepId = EntityID.INVALID;
		nodeId = NodeID.INVALID;
		source = string.Empty;
		if (sev.type != SessionEventType.CrewVehicleReassigned || !sev.pid.IsHumanPlayer || sev.eid.IsNotValid)
		{
			return false;
		}

		if (TryGetDirectArrestVehicleSnapshotForVehicle(sev.eid, out DirectArrestVehicleSnapshot snapshot)
			&& snapshot.VehicleId.IsValid
			&& snapshot.OccupantIds.Count > 1)
		{
			peepId = snapshot.PeepId;
			nodeId = snapshot.VehicleNodeId;
			source = "snapshot";
			return true;
		}

		if (_deferredDirectArrestRefreshByVehicle.TryGetValue(unchecked((long)sev.eid.id), out DeferredDirectArrestVehicleRefresh refresh)
			&& refresh != null
			&& refresh.Day == G.GetNow().days
			&& refresh.FederalArrestLane)
		{
			peepId = refresh.PeepId;
			nodeId = refresh.NodeId;
			source = refresh.Source ?? "deferred";
			return true;
		}

		return false;
	}

	internal static bool ShouldDeferHumanCrewVehicleReassignedUi(SessionEvent sev, out EntityID peepId, out NodeID nodeId, out string source)
	{
		return ShouldDeferHumanCrewVehicleReassignedEvent(sev, out peepId, out nodeId, out source);
	}

