	internal static void DeferHumanFederalArrestTicker(PlayerID pid, EntityID peepId, string tickerKey, int years, string source)
	{
		if (!pid.IsHumanPlayer || peepId.IsNotValid || string.IsNullOrWhiteSpace(tickerKey))
		{
			return;
		}

		long peepKey = unchecked((long)peepId.id);
		bool hadExisting = _deferredFederalArrestPresentationsByPeep.TryGetValue(peepKey, out DeferredFederalArrestPresentation presentation) && presentation != null;
		if (!hadExisting)
		{
			presentation = new DeferredFederalArrestPresentation
			{
				PlayerId = pid,
				PeepId = peepId,
				Source = source ?? string.Empty
			};
			_deferredFederalArrestPresentationsByPeep[peepKey] = presentation;
		}

		presentation.PlayerId = pid;
		presentation.PeepId = peepId;
		presentation.Source = source ?? presentation.Source ?? string.Empty;
		presentation.TickerKey = tickerKey;
		presentation.TickerYears = years;
		VerificationLog("VehicleNodeAuthority", $"{(hadExisting ? "crewfedarrest-presentation-coalesced" : "crewfedarrest-presentation-deferred")} peep={peepId.id} type=ticker key={tickerKey} source={presentation.Source}");
	}

