	private static void ReplayDeferredFederalArrestPresentation(DeferredFederalArrestPresentation presentation, EntityID vehicleId, NodeID nodeId, string sourceTag)
	{
		if (presentation == null || !presentation.PlayerId.IsHumanPlayer || presentation.PeepId.IsNotValid)
		{
			return;
		}

		Entity peep = presentation.PeepId.FindEntity();
		string crewName = peep?.data?.person?.FullName ?? "?";
		PlayerInfo player = presentation.PlayerId.FindPlayer() ?? G.GetHumanPlayer();
		if (!string.IsNullOrWhiteSpace(presentation.TickerKey))
		{
			string message = Loc.Get(presentation.TickerKey, "crewname", crewName, "years", presentation.TickerYears);
			global::Game.Game.ctx?.hud?.tickers?.AddTextTicker(TickerIcon.COP_UPDATE, TickerTitle.COP_UPDATE, message, default(TickerTarget), TickerPersistType.Persist);
		}
		if (!string.IsNullOrWhiteSpace(presentation.NewspaperKey) && player != null)
		{
			PhotoConfig? photo = global::Game.Game.serv.globals.settings.people.social.police.feds.trialPhotos.FirstOrDefaultFast();
			string header = Loc.Get(presentation.NewspaperKey, "crewname", crewName, "groupname", player.social.PlayerGroupName, "years", presentation.NewspaperYears, "date", Loc.FormatDateShort(presentation.NewspaperDate));
			global::Game.Game.serv.ui.AddPopup(new global::Game.UI.Session.NewspaperPopup(header, photo));
		}
		VerificationLog("VehicleNodeAuthority", $"crewfedarrest-presentation-flushed peep={presentation.PeepId.id} vehicle={vehicleId.id} node={nodeId} source={presentation.Source} trigger={sourceTag} ticker={!string.IsNullOrWhiteSpace(presentation.TickerKey)} newspaper={!string.IsNullOrWhiteSpace(presentation.NewspaperKey)}");
	}

	private static bool TryPreserveInlineDirectArrestSelection(DirectArrestVehicleSnapshot snapshot, string source)
	{
		if (snapshot == null || !snapshot.WasSelected || !snapshot.VehicleId.IsValid)
		{
			return false;
		}

		try
		{
			SelectionManager selection = global::Game.Game.ctx?.selection;
			Entity vehicle = snapshot.VehicleId.FindEntity();
			if (selection == null || vehicle == null)
			{
				return false;
			}

			Entity currentActive = selection.CurrentActive;
			if (currentActive != null && currentActive.Id == snapshot.VehicleId)
			{
				VerificationLog("VehicleNodeAuthority", $"federal-arrest-inline-selection-preserved peep={snapshot.PeepId.id} vehicle={snapshot.VehicleId.id} mode=already-vehicle source={source}");
				return true;
			}

			if (currentActive != null
				&& currentActive.Id != snapshot.PeepId
				&& currentActive.Id != snapshot.SelectedEntityId)
			{
				return false;
			}

			selection.HandleDeselect();
			selection.SetActive(vehicle);
			VerificationLog("VehicleNodeAuthority", $"federal-arrest-inline-selection-preserved peep={snapshot.PeepId.id} vehicle={snapshot.VehicleId.id} mode=retargeted source={source}");
			return true;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryPreserveInlineDirectArrestSelection failed: " + ex.Message);
			return false;
		}
	}

	private static void EnqueueDeferredDirectArrestVisualRefresh(DirectArrestVehicleSnapshot snapshot, Node effectiveNode, string source, bool syncVehicleNode = false, bool repairVehicleAuthority = false, bool federalArrestLane = false, bool deferredOffBoardCleanup = false, string reason = "")
	{
		if (snapshot == null || !snapshot.VehicleId.IsValid)
		{
			return;
		}

		EnsureHumanPrecinctRaidTransientStateForCurrentDay();
		long vehicleKey = unchecked((long)snapshot.VehicleId.id);
		var refresh = new DeferredDirectArrestVehicleRefresh
		{
			Day = G.GetNow().days,
			QueuedFrame = Time.frameCount,
			PeepId = snapshot.PeepId,
			VehicleId = snapshot.VehicleId,
			NodeId = effectiveNode?.id ?? snapshot.VehicleNodeId,
			RepairVehicleAuthority = repairVehicleAuthority,
			SyncVehicleNode = syncVehicleNode,
			FederalArrestLane = federalArrestLane,
			DeferredOffBoardCleanup = deferredOffBoardCleanup,
			Reason = reason ?? string.Empty,
			RetargetSelection = snapshot.WasSelected,
			Source = source ?? string.Empty
		};
		TrackDeferredDirectArrestPeepArtifacts(refresh, refresh.PeepId);

		if (_deferredDirectArrestRefreshByVehicle.TryGetValue(vehicleKey, out DeferredDirectArrestVehicleRefresh existing))
		{
			existing.Day = refresh.Day;
			existing.QueuedFrame = refresh.QueuedFrame;
			if (existing.PeepId.IsNotValid)
			{
				existing.PeepId = refresh.PeepId;
			}
			existing.NodeId = refresh.NodeId.IsValid ? refresh.NodeId : existing.NodeId;
			existing.RepairVehicleAuthority |= refresh.RepairVehicleAuthority;
			existing.SyncVehicleNode |= refresh.SyncVehicleNode;
			existing.FederalArrestLane |= refresh.FederalArrestLane;
			existing.DeferredOffBoardCleanup |= refresh.DeferredOffBoardCleanup;
			if (!string.IsNullOrEmpty(refresh.Reason))
			{
				existing.Reason = refresh.Reason;
			}
			existing.RetargetSelection |= refresh.RetargetSelection;
			existing.Source = refresh.Source;
			TrackDeferredDirectArrestPeepArtifacts(existing, refresh.PeepId);
			if (_deferredCrewVehicleReassignedEventsByVehicle.TryGetValue(vehicleKey, out SessionEvent deferredVehicleEvent))
			{
				existing.PendingCrewVehicleReassignedEvent = deferredVehicleEvent;
			}
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-refresh-coalesced peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={existing.NodeId} peepCount={existing.AffectedPeepIds.Count} source={refresh.Source}");
			return;
		}

		if (_deferredCrewVehicleReassignedEventsByVehicle.TryGetValue(vehicleKey, out SessionEvent pendingVehicleEvent))
		{
			refresh.PendingCrewVehicleReassignedEvent = pendingVehicleEvent;
		}
		_deferredDirectArrestRefreshByVehicle[vehicleKey] = refresh;
		VerificationLog("VehicleNodeAuthority", $"direct-arrest-refresh-deferred peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} peepCount={refresh.AffectedPeepIds.Count} frame={refresh.QueuedFrame} source={refresh.Source}");
		if (syncVehicleNode)
		{
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-node-sync-deferred peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} source={refresh.Source}");
		}
		if (repairVehicleAuthority)
		{
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-full-repair-deferred peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} source={refresh.Source} reason={refresh.Reason}");
		}
		if (refresh.DeferredOffBoardCleanup)
		{
			VerificationLog("VehicleNodeAuthority", $"federal-arrest-offboard-cleanup-deferred peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} source={refresh.Source}");
		}
	}

	private static void ArmDeferredFederalArrestState(EntityID vehicleId, PlayerID playerId, ArrestEntry arrestEntry, string source)
	{
		if (vehicleId.IsNotValid)
		{
			return;
		}

		long vehicleKey = unchecked((long)vehicleId.id);
		if (!_deferredDirectArrestRefreshByVehicle.TryGetValue(vehicleKey, out DeferredDirectArrestVehicleRefresh refresh) || refresh == null)
		{
			return;
		}

		refresh.DeferredFederalArrestEntry = true;
		refresh.DeferredFederalTrialDate = arrestEntry.trialDate;
		refresh.DeferredFederalBribeCost = arrestEntry.payOffCost.cash.RoundCoarse();
		refresh.DeferredOffBoardState = true;
		refresh.DeferredArrestPlayerId = playerId;
		VerificationLog("VehicleNodeAuthority", $"federal-arrest-entry-deferred peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} trialDay={refresh.DeferredFederalTrialDate.days} bribe={refresh.DeferredFederalBribeCost} source={source}");
	}

	private static void FlushDeferredFederalArrestOffBoardState(DeferredDirectArrestVehicleRefresh refresh, PlayerInfo humanPlayer, string sourceTag)
	{
		if (refresh == null || !refresh.DeferredOffBoardState || humanPlayer?.crew == null || refresh.PeepId.IsNotValid)
		{
			return;
		}

		List<OffBoardInfo> crewOffBoard = humanPlayer.crew.GetCrewOffBoardUnsafe();
		if (crewOffBoard != null && !crewOffBoard.Any(info => info.crew == refresh.PeepId))
		{
			crewOffBoard.Add(new OffBoardInfo(refresh.PeepId, Label.NULL, PlayerCrewData.OffBoardReason.Arrested));
		}

		refresh.DeferredOffBoardState = false;
		VerificationLog("VehicleNodeAuthority", $"federal-arrest-offboard-state-flushed peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} source={refresh.Source} trigger={sourceTag}");
	}

	private static void FlushDeferredFederalArrestEntry(DeferredDirectArrestVehicleRefresh refresh, string sourceTag)
	{
		if (refresh == null || !refresh.DeferredFederalArrestEntry || refresh.PeepId.IsNotValid || !refresh.DeferredArrestPlayerId.IsValid)
		{
			return;
		}

		if (JailSystem.TryAddDeferredFederalArrestRecord(refresh.DeferredArrestPlayerId, refresh.PeepId, refresh.DeferredFederalTrialDate, refresh.DeferredFederalBribeCost))
		{
			ClearSafeFederalArrestPending(refresh.PeepId);
			refresh.DeferredFederalArrestEntry = false;
			VerificationLog("VehicleNodeAuthority", $"federal-arrest-entry-flushed peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} trialDay={refresh.DeferredFederalTrialDate.days} bribe={refresh.DeferredFederalBribeCost} source={refresh.Source} trigger={sourceTag}");
		}
	}

	private static void FlushDeferredFederalArrestOffBoardCleanup(DeferredDirectArrestVehicleRefresh refresh, PlayerInfo humanPlayer, string sourceTag)
	{
		if (refresh == null || !refresh.DeferredOffBoardCleanup || humanPlayer == null || refresh.PeepId.IsNotValid)
		{
			return;
		}

		if (refresh.VehicleId.IsValid
			&& TryGetVehicleArrestSurvivorState(humanPlayer, refresh.VehicleId, out _, out EntityID activeDriverId, out int liveOccupants)
			&& liveOccupants > 0)
		{
			refresh.DeferredOffBoardCleanup = false;
			VerificationLog("VehicleNodeAuthority", $"federal-arrest-offboard-cleanup-suppressed peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} activeDriver={activeDriverId.id} liveOccupants={liveOccupants} source={refresh.Source} trigger={sourceTag} reason=survivor-vehicle");
			return;
		}

		Node headquartersNode = humanPlayer.territory?.GetHeadquartersNode();
		Entity peep = refresh.PeepId.FindEntity();
		if (headquartersNode?.id.IsValid == true && peep != null)
		{
			global::Game.Game.ctx?.transit?.SetAgentAtNode(headquartersNode.id, peep);
		}
		VerificationLog("VehicleNodeAuthority", $"federal-arrest-offboard-cleanup-flushed peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={headquartersNode?.id ?? NodeID.INVALID} source={refresh.Source} trigger={sourceTag}");
	}

	internal static void FlushDeferredSafeFederalArrestFollowups(string sourceTag)
	{
		if (_deferredSafeFederalArrestFollowupsByPeep.Count == 0)
		{
			return;
		}

		EnsureHumanPrecinctRaidTransientStateForCurrentDay();
		int today = G.GetNow().days;
		var readyKeys = _deferredSafeFederalArrestFollowupsByPeep
			.Where(pair => pair.Value != null
				&& pair.Value.Day == today
				&& pair.Value.QueuedFrame < Time.frameCount)
			.Select(pair => pair.Key)
			.ToList();
		foreach (long peepKey in readyKeys)
		{
			if (!_deferredSafeFederalArrestFollowupsByPeep.TryGetValue(peepKey, out DeferredSafeFederalArrestFollowup followup) || followup == null)
			{
				continue;
			}

			try
			{
				FlushPendingSafeFederalArrestBookkeeping(followup, sourceTag);
				Node federalNode = followup.NodeId.IsValid ? followup.NodeId.FindNode() : TryResolveDirectArrestSnapshotNode(followup.PeepId);
				DeferHumanCrewFedArrestEvent(new SessionEvent(SessionEventType.CrewFedArrest, followup.PeepId, followup.PlayerId));
				VerificationLog("VehicleNodeAuthority", $"crewfedarrest-event-deferred peep={followup.PeepId.id} vehicle={followup.VehicleId.id} node={followup.NodeId} source={followup.Source}");
				DeferHumanFederalArrestTicker(followup.PlayerId, followup.PeepId, "ui.tickers.feds-raid-humancrew", 0, followup.Source);
				DeferHumanFederalArrestNewspaper(followup.PlayerId, followup.PeepId, "newspaper-headline.trial-human", followup.TrialDate, 0, followup.Source);
				CloseFederalHumanArrest(followup.PeepId, federalNode, followup.Source, "federal-arrest");
				if (!TryDeferDirectArrestVehicleStateRepairFromSnapshot(followup.PeepId, federalNode, followup.Source, "federal-arrest", federalArrestLane: true))
				{
					VerificationLog("VehicleNodeAuthority", $"federal-arrest-followup-skipped peep={followup.PeepId.id} vehicle={followup.VehicleId.id} node={followup.NodeId} source={followup.Source} reason=defer-state-repair-failed trigger={sourceTag}");
					continue;
				}

				ArmDeferredFederalArrestState(followup.VehicleId, followup.PlayerId, new ArrestEntry
				{
					peepId = followup.PeepId,
					playerId = followup.PlayerId,
					trialDate = followup.TrialDate,
					payOffCost = new Price((Fixnum)followup.BribeCost),
					paidOff = false
				}, followup.Source);
				if (!FinalizeImportantWitnessAfterSafeFederalFollowup(G.GetHumanPlayer(), followup.PeepId, followup.SourceType, G.GetNow(), sourceTag))
				{
					VerificationLog("NationalHeat", $"important-witness-safe-federal-finalization-deferred peep={followup.PeepId.id} source={followup.SourceType} trigger={sourceTag}");
					continue;
				}
				VerificationLog("VehicleNodeAuthority", $"federal-arrest-followup-flushed peep={followup.PeepId.id} vehicle={followup.VehicleId.id} node={followup.NodeId} source={followup.Source} trigger={sourceTag}");
				_deferredSafeFederalArrestFollowupsByPeep.Remove(peepKey);
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] FlushDeferredSafeFederalArrestFollowups failed: " + ex.Message);
			}
		}
	}

	internal static void FlushDeferredDirectArrestTurnEndRepairs(string sourceTag)
	{
		if (_deferredDirectArrestRefreshByVehicle.Count == 0)
		{
			return;
		}

		EnsureHumanPrecinctRaidTransientStateForCurrentDay();

		var pendingEntries = _deferredDirectArrestRefreshByVehicle
			.Where(pair => pair.Value != null
				&& pair.Value.PendingTurnEndRepair
				&& !pair.Value.TurnEndRepairCompleted)
			.Select(pair => pair.Value)
			.ToList();
		if (pendingEntries.Count == 0)
		{
			if (!string.Equals(sourceTag, "update", StringComparison.Ordinal))
			{
				VerificationLog("VehicleNodeAuthority", $"direct-arrest-turnend-phase-skipped source={sourceTag} reason=no-pending-turnend queuedEntries={_deferredDirectArrestRefreshByVehicle.Count}");
			}
			return;
		}

		int today = G.GetNow().days;
		var todayEntries = pendingEntries
			.Where(refresh => refresh.Day == today)
			.ToList();
		if (todayEntries.Count == 0)
		{
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-turnend-phase-skipped source={sourceTag} reason=day-mismatch pendingEntries={pendingEntries.Count} today={today}");
			return;
		}

		var frameReadyEntries = todayEntries
			.Where(refresh => refresh.QueuedFrame < Time.frameCount)
			.ToList();
		if (frameReadyEntries.Count == 0)
		{
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-turnend-phase-skipped source={sourceTag} reason=queued-frame pendingEntries={todayEntries.Count} frame={Time.frameCount}");
			return;
		}

		bool pendingCornerRaid = _pendingCornerHeatRaidActive || _pendingHumanCornerHeatPrecinctRaidActive;
		if (pendingCornerRaid)
		{
			frameReadyEntries = frameReadyEntries
				.Where(CanBypassCornerRaidGateForFederalTurnEndFlush)
				.ToList();
			if (frameReadyEntries.Count == 0)
			{
				VerificationLog("VehicleNodeAuthority", $"direct-arrest-turnend-phase-skipped source={sourceTag} reason=pending-corner-raid cornerRaid={_pendingCornerHeatRaidActive} precinctRaid={_pendingHumanCornerHeatPrecinctRaidActive} pendingEntries={todayEntries.Count}");
				return;
			}
		}

		var readyKeys = frameReadyEntries
			.Select(refresh => unchecked((long)refresh.VehicleId.id))
			.ToList();
		foreach (long vehicleKey in readyKeys)
		{
			if (!_deferredDirectArrestRefreshByVehicle.TryGetValue(vehicleKey, out DeferredDirectArrestVehicleRefresh refresh) || refresh == null)
			{
				continue;
			}

			try
			{
				if ((_pendingCornerHeatRaidActive || _pendingHumanCornerHeatPrecinctRaidActive) && CanBypassCornerRaidGateForFederalTurnEndFlush(refresh))
				{
					VerificationLog("VehicleNodeAuthority", $"federal-arrest-turnend-flush-unblocked peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} source={refresh.Source} trigger={sourceTag} cornerRaid={_pendingCornerHeatRaidActive} precinctRaid={_pendingHumanCornerHeatPrecinctRaidActive}");
				}

				Entity vehicle = refresh.VehicleId.FindEntity();
				PlayerInfo humanPlayer = G.GetHumanPlayer();
				if (vehicle == null || humanPlayer?.crew == null)
				{
					_deferredCrewVehicleReassignedEventsByVehicle.Remove(vehicleKey);
					ClearDeferredDirectArrestPeepArtifacts(refresh);
					_deferredDirectArrestRefreshByVehicle.Remove(vehicleKey);
					continue;
				}

				if (refresh.RepairVehicleAuthority)
				{
					MultiCrewVehicleHelper.ResetHumanVehicleAuthorityAfterArrest(humanPlayer.crew, refresh.VehicleId, refresh.PeepId, refresh.Source + "-deferred-repair", deferNodeSync: false, federalArrestLane: refresh.FederalArrestLane);
					if (TryGetVehicleArrestSurvivorState(humanPlayer, refresh.VehicleId, out _, out EntityID survivorDriverId, out int survivorCount))
					{
						VerificationLog("VehicleNodeAuthority", $"direct-arrest-survivor-repair peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} liveOccupants={survivorCount} node={refresh.NodeId} reason={refresh.Reason} source={refresh.Source}-deferred-repair");
						if (survivorDriverId.IsValid)
						{
							VerificationLog("VehicleNodeAuthority", $"direct-arrest-safehouse-rebase-skipped peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} arrestNode={refresh.NodeId} activeDriver={survivorDriverId.id} liveOccupants={survivorCount} source={refresh.Source}-deferred-repair");
						}
					}
					VerificationLog("VehicleNodeAuthority", $"direct-arrest-full-repair-flushed peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} source={refresh.Source} reason={refresh.Reason} trigger={sourceTag}");
				}

				FlushDeferredFederalArrestOffBoardState(refresh, humanPlayer, sourceTag);
				FlushDeferredFederalArrestOffBoardCleanup(refresh, humanPlayer, sourceTag);
				FlushDeferredFederalArrestEntry(refresh, sourceTag);

				if (refresh.PendingCrewVehicleReassignedEvent.type == SessionEventType.CrewVehicleReassigned)
				{
					global::Game.Game.ctx?.events?.EnqueueOnce(refresh.PendingCrewVehicleReassignedEvent);
					_deferredCrewVehicleReassignedEventsByVehicle.Remove(vehicleKey);
					refresh.PendingCrewVehicleReassignedEvent = default(SessionEvent);
					VerificationLog("VehicleNodeAuthority", $"crewvehiclereassigned-event-flushed peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} source={refresh.Source} trigger={sourceTag}");
				}
				int flushedFedArrestEvents = 0;
				if (refresh.PendingCrewFedArrestEventsByPeep.Count > 0)
				{
					foreach (KeyValuePair<long, SessionEvent> pendingFedArrestEvent in refresh.PendingCrewFedArrestEventsByPeep.ToArray())
					{
						if (pendingFedArrestEvent.Value.type != SessionEventType.CrewFedArrest)
						{
							continue;
						}

						global::Game.Game.ctx?.events?.EnqueueOnce(pendingFedArrestEvent.Value);
						_deferredCrewFedArrestEventsByPeep.Remove(pendingFedArrestEvent.Key);
						flushedFedArrestEvents++;
					}
					refresh.PendingCrewFedArrestEventsByPeep.Clear();
					refresh.PendingCrewFedArrestEvent = default(SessionEvent);
				}
				else if (refresh.PendingCrewFedArrestEvent.type == SessionEventType.CrewFedArrest)
				{
					global::Game.Game.ctx?.events?.EnqueueOnce(refresh.PendingCrewFedArrestEvent);
					_deferredCrewFedArrestEventsByPeep.Remove(unchecked((long)refresh.PeepId.id));
					refresh.PendingCrewFedArrestEvent = default(SessionEvent);
					flushedFedArrestEvents = 1;
				}
				if (flushedFedArrestEvents > 0)
				{
					VerificationLog("VehicleNodeAuthority", $"crewfedarrest-event-flushed peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} eventCount={flushedFedArrestEvents} source={refresh.Source} trigger={sourceTag}");
				}

				refresh.PendingTurnEndRepair = false;
				refresh.TurnEndRepairCompleted = true;
				VerificationLog("VehicleNodeAuthority", $"direct-arrest-turnend-phase-flushed peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} source={refresh.Source} trigger={sourceTag}");
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] FlushDeferredDirectArrestTurnEndRepairs failed: " + ex.Message);
			}
		}
	}

	internal static void FlushDeferredDirectArrestInteractiveUi(string sourceTag)
	{
		if (_deferredDirectArrestRefreshByVehicle.Count == 0)
		{
			return;
		}

		EnsureHumanPrecinctRaidTransientStateForCurrentDay();
		var pendingEntries = _deferredDirectArrestRefreshByVehicle
			.Where(pair => pair.Value != null
				&& pair.Value.TurnEndRepairCompleted
				&& pair.Value.PendingInteractiveUi
				&& !pair.Value.InteractiveUiCompleted)
			.Select(pair => pair.Value)
			.ToList();
		if (pendingEntries.Count == 0)
		{
			if (!string.Equals(sourceTag, "update", StringComparison.Ordinal))
			{
				VerificationLog("VehicleNodeAuthority", $"direct-arrest-interactive-phase-skipped source={sourceTag} reason=no-pending-interactive queuedEntries={_deferredDirectArrestRefreshByVehicle.Count}");
			}
			return;
		}

		if (global::Game.Game.ctx?.IsInteractive != true)
		{
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-interactive-phase-skipped source={sourceTag} reason=non-interactive pendingEntries={pendingEntries.Count}");
			return;
		}
		if (_pendingCornerHeatRaidActive || _pendingHumanCornerHeatPrecinctRaidActive)
		{
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-interactive-phase-skipped source={sourceTag} reason=pending-corner-raid cornerRaid={_pendingCornerHeatRaidActive} precinctRaid={_pendingHumanCornerHeatPrecinctRaidActive} pendingEntries={pendingEntries.Count}");
			return;
		}

		int today = G.GetNow().days;
		var todayEntries = pendingEntries
			.Where(refresh => refresh.Day == today)
			.ToList();
		if (todayEntries.Count == 0)
		{
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-interactive-phase-skipped source={sourceTag} reason=day-mismatch pendingEntries={pendingEntries.Count} today={today}");
			return;
		}

		var frameReadyEntries = todayEntries
			.Where(refresh => refresh.QueuedFrame < Time.frameCount)
			.ToList();
		if (frameReadyEntries.Count == 0)
		{
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-interactive-phase-skipped source={sourceTag} reason=queued-frame pendingEntries={todayEntries.Count} frame={Time.frameCount}");
			return;
		}

		var readyKeys = frameReadyEntries
			.Select(refresh => unchecked((long)refresh.VehicleId.id))
			.ToList();
		foreach (long vehicleKey in readyKeys)
		{
			if (!_deferredDirectArrestRefreshByVehicle.TryGetValue(vehicleKey, out DeferredDirectArrestVehicleRefresh refresh) || refresh == null)
			{
				continue;
			}

			try
			{
				Entity vehicle = refresh.VehicleId.FindEntity();
				PlayerInfo humanPlayer = G.GetHumanPlayer();
				if (vehicle == null || humanPlayer?.crew == null)
				{
					_deferredCrewVehicleReassignedEventsByVehicle.Remove(vehicleKey);
					ClearDeferredDirectArrestPeepArtifacts(refresh);
					_deferredDirectArrestRefreshByVehicle.Remove(vehicleKey);
					continue;
				}

				if (refresh.SyncVehicleNode)
				{
					MultiCrewVehicleHelper.TrySyncVehicleOccupantsToVehicleNode(humanPlayer.crew, refresh.VehicleId, refresh.Source + "-deferred-node-sync");
				}
				if (refresh.RetargetSelection)
				{
					SelectionManager selection = global::Game.Game.ctx?.selection;
					if (selection != null)
					{
						selection.HandleDeselect();
						selection.SetActive(vehicle);
					}
				}

				Node finalNode = refresh.NodeId.IsValid ? refresh.NodeId.FindNode() : null;
				if (finalNode?.id.IsValid == true)
				{
					MultiCrewVehicleHelper.HideCornerInfoIfShowingNode(finalNode.id);
					RefreshBuildingPickStateAfterHumanVehicleTravel(finalNode, finalNode, refresh.Source + "-deferred", refresh.VehicleId);
				}
				int replayedFederalArrestPresentations = 0;
				if (refresh.PendingFederalArrestPresentationsByPeep.Count > 0)
				{
					foreach (DeferredFederalArrestPresentation pendingPresentation in refresh.PendingFederalArrestPresentationsByPeep.Values.ToList())
					{
						if (pendingPresentation == null)
						{
							continue;
						}

						ReplayDeferredFederalArrestPresentation(pendingPresentation, refresh.VehicleId, refresh.NodeId, sourceTag);
						replayedFederalArrestPresentations++;
					}
					refresh.PendingFederalArrestPresentationsByPeep.Clear();
					refresh.PendingFederalArrestPresentation = null;
				}
				else if (refresh.PendingFederalArrestPresentation != null)
				{
					ReplayDeferredFederalArrestPresentation(refresh.PendingFederalArrestPresentation, refresh.VehicleId, refresh.NodeId, sourceTag);
					refresh.PendingFederalArrestPresentation = null;
					replayedFederalArrestPresentations = 1;
				}

				MultiCrewVehicleHelper.TryRefreshCrewHudCardsForVehicle(refresh.VehicleId);
				if (refresh.FederalArrestLane || refresh.AffectedPeepIds.Count > 1)
				{
					RefreshCrewHudUi("direct-arrest-ui-" + sourceTag, rebuildCards: true);
					VerificationLog("VehicleNodeAuthority", $"crewfedarrest-ui-refresh-flushed peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} peepCount={refresh.AffectedPeepIds.Count} source={refresh.Source} trigger={sourceTag}");
				}
				if (TryResolveHudPickManager(out object pickManager))
				{
					ClearDeferredDirectArrestAffectedCopFedPickTargets(pickManager, refresh, sourceTag);
				}
				ResetTransientPolicePortraitState("direct-arrest-ui-" + sourceTag, clearDeferredPresentations: false);
				FlushCrewPickAggroRefreshes("direct-arrest-ui-" + sourceTag);
				if (MultiCrewVehicleHelper.HasBlockedCrewAssignmentsInVehicle(G.GetHumanCrew(), refresh.VehicleId))
				{
					ClearSelectedVehicleUiFinalNode(refresh.VehicleId, "direct-arrest-custody-preview");
				}

				refresh.PendingInteractiveUi = false;
				refresh.InteractiveUiCompleted = true;
				VerificationLog("VehicleNodeAuthority", $"direct-arrest-refresh-flushed peep={refresh.PeepId.id} vehicle={refresh.VehicleId.id} node={refresh.NodeId} peepCount={refresh.AffectedPeepIds.Count} presentationCount={replayedFederalArrestPresentations} source={refresh.Source} trigger={sourceTag}");
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] FlushDeferredDirectArrestInteractiveUi failed: " + ex.Message);
			}
			finally
			{
				ClearDeferredDirectArrestPeepArtifacts(refresh);
				_deferredDirectArrestRefreshByVehicle.Remove(vehicleKey);
			}
		}
	}

	internal static void CloseFederalHumanArrest(EntityID peepId, Node arrestNode, string source, string reason)
	{
		if (peepId.IsNotValid)
		{
			return;
		}

		NoteCornerRaidArrestPostfixApplied(peepId);
		NoteCornerRaidArrestRefreshApplied(peepId);
		int closedCount = MarkCornerRaidHumanCloseout(peepId, source, reason);
		RecalculateNationalHeatState(G.GetNow().days);
		LogNationalHeatTerminalCloseout(peepId, source, reason, closedCount);
		_lastFederalArrestTerminalCloseoutDayByPeep[unchecked((long)peepId.id)] = G.GetNow().days;
		TryResolveFederalArrestCornerRaidGate(peepId, arrestNode, source, reason);
		VerificationLog("CornerHeatRaid", $"federal-arrest-terminal-finished peep={peepId.id} node={arrestNode?.id ?? NodeID.INVALID} source={source} reason={reason} closedEntries={closedCount}");
	}

	internal static bool TryDeferDirectArrestVehicleStateRepairFromSnapshot(EntityID peepId, Node arrestNode, string source, string reason, bool federalArrestLane = false)
	{
		if (!TryGetDirectArrestVehicleSnapshot(peepId, out DirectArrestVehicleSnapshot snapshot) || !snapshot.VehicleId.IsValid)
		{
			return false;
		}

		Node effectiveNode = arrestNode;
		if (effectiveNode == null && snapshot.VehicleNodeId.IsValid)
		{
			effectiveNode = snapshot.VehicleNodeId.FindNode();
		}

		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (federalArrestLane && humanPlayer?.crew != null)
		{
			int repairedAssignments = MultiCrewVehicleHelper.RepairHumanVehicleAssignmentsFromSnapshot(humanPlayer.crew, snapshot.VehicleId, snapshot.OccupantIds, peepId, source + "-inline-assignment");
			int liveOccupants = MultiCrewVehicleHelper.GetLiveVehicleCrewCount(humanPlayer.crew, snapshot.VehicleId);
			bool arrestedWasDriver = snapshot.DriverPeepId.IsValid && snapshot.DriverPeepId == peepId;
			if (liveOccupants > 0)
			{
				if (arrestedWasDriver)
				{
					VerificationLog("VehicleNodeAuthority", $"federal-arrest-driver-vacancy-detected peep={peepId.id} vehicle={snapshot.VehicleId.id} priorDriver={snapshot.DriverPeepId.id} liveOccupants={liveOccupants} source={source}");
				}

				MultiCrewVehicleHelper.ResetHumanVehicleAuthorityAfterArrest(humanPlayer.crew, snapshot.VehicleId, peepId, source + "-inline-driver", deferNodeSync: true, federalArrestLane: true);
				EntityID activeDriverId = MultiCrewVehicleHelper.GetDriverPeepId(humanPlayer.crew, snapshot.VehicleId);
				if (arrestedWasDriver && activeDriverId.IsValid && activeDriverId != peepId)
				{
					VerificationLog("VehicleNodeAuthority", $"federal-arrest-inline-driver-reassigned peep={peepId.id} vehicle={snapshot.VehicleId.id} priorDriver={snapshot.DriverPeepId.id} newDriver={activeDriverId.id} source={source}");
				}
				TryPreserveInlineDirectArrestSelection(snapshot, source + "-inline-selection");
				VerificationLog("VehicleNodeAuthority", $"federal-arrest-inline-vehicle-valid peep={peepId.id} vehicle={snapshot.VehicleId.id} node={effectiveNode?.id ?? NodeID.INVALID} activeDriver={activeDriverId.id} liveOccupants={liveOccupants} repairedAssignments={repairedAssignments} source={source}");
				VerificationLog("VehicleNodeAuthority", $"federal-arrest-inline-authority-preserved peep={peepId.id} vehicle={snapshot.VehicleId.id} node={effectiveNode?.id ?? NodeID.INVALID} activeDriver={activeDriverId.id} liveOccupants={liveOccupants} source={source}");
			}
		}

		bool deferOffBoardCleanup = federalArrestLane && snapshot.OccupantIds.Count > 1;
		EnqueueDeferredDirectArrestVisualRefresh(snapshot, effectiveNode, source + "-survivor", syncVehicleNode: false, repairVehicleAuthority: true, federalArrestLane: federalArrestLane, deferredOffBoardCleanup: deferOffBoardCleanup, reason: reason);
		ClearDirectArrestVehicleSnapshot(peepId);
		return true;
	}

	internal static bool TryRepairDirectArrestVehicleStateFromSnapshot(EntityID peepId, Node arrestNode, string source, string reason, bool deferNodeSync = false, bool federalArrestLane = false)
	{
		if (!TryGetDirectArrestVehicleSnapshot(peepId, out DirectArrestVehicleSnapshot snapshot) || !snapshot.VehicleId.IsValid)
		{
			return false;
		}

		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (humanPlayer?.crew == null)
		{
			return false;
		}

		try
		{
			MultiCrewVehicleHelper.ResetHumanVehicleAuthorityAfterArrest(humanPlayer.crew, snapshot.VehicleId, peepId, source, deferNodeSync, federalArrestLane);
			if (!TryGetVehicleArrestSurvivorState(humanPlayer, snapshot.VehicleId, out Entity survivorVehicle, out EntityID survivorDriverId, out int survivorCount))
			{
				ClearDirectArrestVehicleSnapshot(peepId);
				return false;
			}

			Node effectiveNode = arrestNode;
			if (effectiveNode == null && snapshot.VehicleNodeId.IsValid)
			{
				effectiveNode = snapshot.VehicleNodeId.FindNode();
			}

			VerificationLog("VehicleNodeAuthority", $"direct-arrest-survivor-repair peep={peepId.id} vehicle={snapshot.VehicleId.id} liveOccupants={survivorCount} node={effectiveNode?.id ?? NodeID.INVALID} reason={reason} source={source}");
			if (survivorDriverId.IsValid && survivorDriverId != snapshot.DriverPeepId && survivorDriverId != peepId)
			{
				VerificationLog("VehicleNodeAuthority", $"direct-arrest-driver-reassigned peep={peepId.id} vehicle={snapshot.VehicleId.id} priorDriver={snapshot.DriverPeepId.id} newDriver={survivorDriverId.id} source={source}");
			}
			VerificationLog("VehicleNodeAuthority", $"direct-arrest-safehouse-rebase-skipped peep={peepId.id} vehicle={snapshot.VehicleId.id} arrestNode={effectiveNode?.id ?? NodeID.INVALID} activeDriver={survivorDriverId.id} liveOccupants={survivorCount} source={source}");
			EnqueueDeferredDirectArrestVisualRefresh(snapshot, effectiveNode, source + "-survivor", deferNodeSync);
			ClearDirectArrestVehicleSnapshot(peepId);
			return true;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryRepairDirectArrestVehicleStateFromSnapshot failed: " + ex.Message);
			return false;
		}
	}

	private static Entity ResolveHumanSafehouseEntity(PlayerInfo humanPlayer)
	{
		if (humanPlayer == null || humanPlayer.territory == null)
		{
			return null;
		}
		EntityID safehouse = humanPlayer.territory.Safehouse;
		return safehouse.IsValid ? EntityIDExtensions.FindEntity(safehouse) : null;
	}

	private static bool TryResolveHumanSafehouseNode(PlayerInfo humanPlayer, out Node node)
	{
		node = null;
		try
		{
			Entity safehouseEntity = ResolveHumanSafehouseEntity(humanPlayer);
			NodeID nodeId = safehouseEntity?.data?.board?.bead.nodeId ?? NodeID.INVALID;
			if (!nodeId.IsValid && safehouseEntity != null)
			{
				object board = safehouseEntity.components?.board;
				MethodInfo getNodeId = board?.GetType().GetMethod("GetNodeID", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (getNodeId != null)
				{
					nodeId = (NodeID)getNodeId.Invoke(board, null);
				}
			}
			if (!nodeId.IsValid)
			{
				return false;
			}
			node = nodeId.FindNode();
			return node != null;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryResolveHumanSafehouseNode failed: " + ex.Message);
			return false;
		}
	}

	internal static bool IsHumanPeepAtSafehouseCorner(PlayerInfo humanPlayer, Entity peep)
	{
		if (humanPlayer?.crew == null || peep == null || !TryResolveHumanSafehouseNode(humanPlayer, out Node safehouseNode) || safehouseNode?.id.IsValid != true)
		{
			return false;
		}

		try
		{
			CrewAssignment crew = humanPlayer.crew.GetCrewForPeep(peep.Id);
			if (!crew.IsValid || !humanPlayer.crew.IsOnBoard(crew.peepId) || IsCrewCurrentlyJailed(crew.peepId))
			{
				return false;
			}

			if (crew.IsInVehicle && crew.VehicleID.IsValid)
			{
				return MultiCrewVehicleHelper.IsHumanVehicleAtOwnedBuildingAccessNode(crew.VehicleID, safehouseNode.id, out _)
					|| MultiCrewVehicleHelper.TryGetVehicleLiveAuthorityNodeId(crew.VehicleID, out NodeID vehicleNodeId, out _) && vehicleNodeId == safehouseNode.id;
			}

			return peep.data?.agent?.nid == safehouseNode.id;
		}
		catch
		{
			return false;
		}
	}

	private static void FlushRegularArrestOffBoardCleanup(PlayerInfo humanPlayer, EntityID peepId, EntityID vehicleId, string sourceTag)
	{
		if (humanPlayer == null || peepId.IsNotValid)
		{
			return;
		}

		Entity peep = peepId.FindEntity();
		if (peep == null)
		{
			return;
		}

		Node offBoardNode = TryResolveHumanSafehouseNode(humanPlayer, out Node safehouseNode)
			? safehouseNode
			: humanPlayer.territory?.GetHeadquartersNode();
		if (offBoardNode?.id.IsValid == true)
		{
			global::Game.Game.ctx?.transit?.SetAgentAtNode(offBoardNode.id, peep);
		}

		VerificationLog(
			"VehicleNodeAuthority",
			$"regular-arrest-offboard-cleanup-flushed peep={peepId.id} vehicle={vehicleId.id} node={offBoardNode?.id ?? NodeID.INVALID} source={sourceTag}");
	}

	internal static void RefreshHumanStateAfterArrest(PlayerInfo player, CrewAssignment arrestedCrew)
	{
		if (player?.PID.IsHumanPlayer != true || player.crew == null || !arrestedCrew.IsValid)
		{
			return;
		}
		try
		{
			Entity safehouseEntity = ResolveHumanSafehouseEntity(player);
			Node safehouseNode = TryResolveHumanSafehouseNode(player, out Node resolvedSafehouseNode) ? resolvedSafehouseNode : null;
			Node arrestNode = null;
			bool vehicleHasSurvivors = false;
			Entity survivorVehicle = null;
			EntityID survivorDriverId = EntityID.INVALID;
			int survivorCount = 0;
			if (arrestedCrew.IsInVehicle && arrestedCrew.VehicleID.IsValid)
			{
				if (MultiCrewVehicleHelper.TryGetAuthoritativeVehicleNodeId(arrestedCrew.VehicleID, out NodeID arrestNodeId, out _))
				{
					arrestNode = arrestNodeId.FindNode();
				}
				MultiCrewVehicleHelper.ResetHumanVehicleAuthorityAfterArrest(player.crew, arrestedCrew.VehicleID, arrestedCrew.peepId, "regular-arrest");
				MultiCrewVehicleHelper.HandleCrewDepartureFromGang(player, arrestedCrew.peepId, arrestedCrew.VehicleID, "regular-arrest");
				FlushRegularArrestOffBoardCleanup(player, arrestedCrew.peepId, arrestedCrew.VehicleID, "regular-arrest");
				ResetTransientPolicePortraitState("regular-arrest", clearDeferredPresentations: false);
				MultiCrewVehicleHelper.TryRefreshCrewHudCardsForVehicle(arrestedCrew.VehicleID);
				RefreshCrewHudUi("regular-arrest", rebuildCards: true);
				vehicleHasSurvivors = TryGetVehicleArrestSurvivorState(player, arrestedCrew, out survivorVehicle, out survivorDriverId, out survivorCount);
				ClearStaleCrewPicksAfterArrest(arrestedCrew.peepId, arrestedCrew.VehicleID, !vehicleHasSurvivors, "regular-arrest");
				if (vehicleHasSurvivors)
				{
					VerificationLog("VehicleNodeAuthority", $"vehicle-arrest-survivors-preserved peep={arrestedCrew.peepId.id} vehicle={arrestedCrew.VehicleID.id} activeDriver={survivorDriverId.id} liveOccupants={survivorCount} source=regular-arrest");
					if (survivorDriverId.IsValid && survivorDriverId != arrestedCrew.peepId)
					{
						VerificationLog("VehicleNodeAuthority", $"vehicle-arrest-driver-reassigned peep={arrestedCrew.peepId.id} vehicle={arrestedCrew.VehicleID.id} newDriver={survivorDriverId.id} source=regular-arrest");
					}
				}
			}
			SelectionManager selection = global::Game.Game.ctx?.selection;
			Entity currentActive = selection?.CurrentActive;
			bool shouldRebaseSelection = currentActive != null && (currentActive.Id == arrestedCrew.peepId || (arrestedCrew.IsInVehicle && currentActive.Id == arrestedCrew.VehicleID));
			if (shouldRebaseSelection)
			{
				selection.HandleDeselect();
				if (vehicleHasSurvivors && survivorVehicle != null)
				{
					selection.SetActive(survivorVehicle);
				}
				else if (safehouseEntity != null)
				{
					selection.SetActive(safehouseEntity);
				}
			}
			if (arrestNode?.id.IsValid == true)
			{
				MultiCrewVehicleHelper.HideCornerInfoIfShowingNode(arrestNode.id);
			}
			if (vehicleHasSurvivors)
			{
				if (arrestNode != null)
				{
					RefreshBuildingPickStateAfterHumanVehicleTravel(arrestNode, arrestNode, "regular-arrest-survivor", arrestedCrew.VehicleID);
				}
				VerificationLog("VehicleNodeAuthority", $"vehicle-arrest-safehouse-rebase-skipped peep={arrestedCrew.peepId.id} vehicle={arrestedCrew.VehicleID.id} arrestNode={arrestNode?.id ?? NodeID.INVALID} activeDriver={survivorDriverId.id} liveOccupants={survivorCount} source=regular-arrest");
			}
			else if (safehouseNode != null)
			{
				RefreshBuildingPickStateAfterHumanVehicleTravel(arrestNode, safehouseNode, "regular-arrest");
				VerificationLog("VehicleNodeAuthority", $"arrest-rebase peep={arrestedCrew.peepId.id} vehicle={arrestedCrew.VehicleID.id} arrestNode={arrestNode?.id ?? NodeID.INVALID} homeNode={safehouseNode.id} source=regular-arrest");
			}
			else
			{
				VerificationLog("VehicleNodeAuthority", $"arrest-rebase peep={arrestedCrew.peepId.id} vehicle={arrestedCrew.VehicleID.id} arrestNode={arrestNode?.id ?? NodeID.INVALID} homeNode={NodeID.INVALID} source=regular-arrest fallback=authority-cleared");
			}
			MarkCrewPickAggroDirty(player.PID, "regular-arrest");
			FlushCrewPickAggroRefreshes("regular-arrest");
			ClearDirectArrestVehicleSnapshot(arrestedCrew.peepId);
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] RefreshHumanStateAfterArrest failed: " + ex.Message);
		}
	}

	internal static int GetHumanCrewIndex(EntityID peepId)
	{
		if (peepId.IsNotValid)
		{
			return -1;
		}
		try
		{
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (humanPlayer?.crew == null)
			{
				return -1;
			}
			int num = 0;
			foreach (CrewAssignment living in humanPlayer.crew.GetLiving())
			{
				if (!living.IsValid || living.peepId.IsNotValid)
				{
					continue;
				}
				if (living.peepId == peepId)
				{
					return num;
				}
				num++;
			}
		}
		catch
		{
		}
		return -1;
	}

	internal static string FormatHumanCrewIndexTag(EntityID peepId)
	{
		int humanCrewIndex = GetHumanCrewIndex(peepId);
		return (humanCrewIndex >= 0) ? $" crewIndex={humanCrewIndex}" : " crewIndex=unknown";
	}

	private static bool TryShouldSkipCornerRaidArrestRefresh(EntityID peepId, string source, out string reason, out bool deduped)
	{
		reason = "allow";
		deduped = false;
		if (peepId.IsNotValid)
		{
			reason = "invalid-peep";
			return true;
		}

		long key = unchecked((long)peepId.id);
		int day = G.GetNow().days;
		if (_lastCornerHeatArrestRefreshDayByPeep.TryGetValue(key, out int lastDay) && lastDay == day)
		{
			reason = "duplicate-turn";
			deduped = true;
			return true;
		}

		if (ShouldSuppressVanillaStartHumanArrestForLocalImportantWitness(peepId, out _, out _))
		{
			reason = "local-important-witness-custody";
			return true;
		}

		if (IsCrewHiddenOrHideoutPending(peepId))
		{
			reason = "hideout";
			return true;
		}

		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (humanPlayer?.crew == null)
		{
			reason = "no-human-crew";
			return true;
		}

		CrewAssignment arrestedCrew = humanPlayer.crew.GetCrewForPeep(peepId);
		if (!arrestedCrew.IsValid)
		{
			reason = "missing-crew";
			return true;
		}

		Entity arrestedPeep = peepId.FindEntity();
		if (arrestedPeep?.components?.agent != null && !arrestedPeep.components.agent.HasHealthPointsLeft)
		{
			reason = "dead";
			return true;
		}

		if (!humanPlayer.crew.IsOnBoard(peepId) && (!arrestedCrew.IsInVehicle || !arrestedCrew.VehicleID.IsValid))
		{
			reason = "already-normalized";
			return true;
		}

		return false;
	}

	internal static bool TryBeginCornerRaidArrestPostfix(EntityID peepId, Node arrestNode, string source)
	{
		if (TryShouldSkipCornerRaidArrestPostfix(peepId, source, out string reason, out bool deduped))
		{
			if (!deduped && IsTerminalCornerRaidArrestSkipReason(reason))
			{
				CloseTerminalCornerRaidArrestSkip(peepId, arrestNode, source, reason);
			}
			VerificationLog("CornerHeatRaid", $"{(deduped ? "corner-raid-postfix-deduped" : "corner-raid-postfix-skipped")} peep={peepId.id} node={arrestNode?.id ?? NodeID.INVALID} source={source} reason={reason}");
			return false;
		}

		NoteCornerRaidArrestPostfixApplied(peepId);
		return true;
	}

	private static bool TryShouldSkipCornerRaidArrestPostfix(EntityID peepId, string source, out string reason, out bool deduped)
	{
		reason = "allow";
		deduped = false;
		if (peepId.IsNotValid)
		{
			reason = "invalid-peep";
			return true;
		}

		long key = unchecked((long)peepId.id);
		int day = G.GetNow().days;
		if (_lastCornerHeatArrestPostfixDayByPeep.TryGetValue(key, out int lastDay) && lastDay == day)
		{
			reason = "duplicate-turn";
			deduped = true;
			return true;
		}

		if (_lastCornerHeatArrestRefreshDayByPeep.TryGetValue(key, out int refreshDay) && refreshDay == day)
		{
			reason = "refresh-already-applied";
			deduped = true;
			return true;
		}

		if (ShouldSuppressVanillaStartHumanArrestForLocalImportantWitness(peepId, out _, out _))
		{
			reason = "local-important-witness-custody";
			return true;
		}

		if (IsCrewHiddenOrHideoutPending(peepId))
		{
			reason = "hideout";
			return true;
		}

		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (humanPlayer?.crew == null)
		{
			reason = "no-human-crew";
			return true;
		}

		CrewAssignment arrestedCrew = humanPlayer.crew.GetCrewForPeep(peepId);
		if (!arrestedCrew.IsValid)
		{
			reason = "missing-crew";
			return true;
		}

		Entity arrestedPeep = peepId.FindEntity();
		if (arrestedPeep?.components?.agent != null && !arrestedPeep.components.agent.HasHealthPointsLeft)
		{
			reason = "dead";
			return true;
		}

		if (!humanPlayer.crew.IsOnBoard(peepId) && (!arrestedCrew.IsInVehicle || !arrestedCrew.VehicleID.IsValid))
		{
			reason = "already-normalized";
			return true;
		}

		return false;
	}

	private static bool IsTerminalCornerRaidArrestSkipReason(string reason)
	{
		return string.Equals(reason, "already-normalized", StringComparison.Ordinal)
			|| string.Equals(reason, "missing-crew", StringComparison.Ordinal)
			|| string.Equals(reason, "dead", StringComparison.Ordinal)
			|| string.Equals(reason, "hideout", StringComparison.Ordinal);
	}

	private static void CloseTerminalCornerRaidArrestSkip(EntityID peepId, Node arrestNode, string source, string reason)
	{
		if (peepId.IsNotValid)
		{
			return;
		}

		bool clearedCornerRaidContext = false;
		bool clearedPrecinctRaidContext = false;
		VerificationLog("CornerHeatRaid", $"corner-raid-skip-terminal peep={peepId.id} node={arrestNode?.id ?? NodeID.INVALID} source={source} reason={reason}");
		if (_pendingCornerHeatRaidActive)
		{
			ClearPendingCornerHeatRaidContext();
			clearedCornerRaidContext = true;
			VerificationLog("CornerHeatRaid", $"corner-raid-context-cleared-on-skip peep={peepId.id} node={arrestNode?.id ?? NodeID.INVALID} source={source} reason={reason}");
		}
		if (_pendingHumanCornerHeatPrecinctRaidActive)
		{
			ResolvePendingHumanCornerHeatPrecinctRaid(false);
			clearedPrecinctRaidContext = true;
			VerificationLog("CornerHeatRaid", $"corner-raid-context-cleared-on-skip peep={peepId.id} node={arrestNode?.id ?? NodeID.INVALID} source={source} reason={reason} kind=precinct-human");
		}

		NoteCornerRaidArrestPostfixApplied(peepId);
		NoteCornerRaidArrestRefreshApplied(peepId);
		int closedCount = MarkCornerRaidHumanCloseout(peepId, source, reason);
		RecalculateNationalHeatState(G.GetNow().days);
		LogNationalHeatTerminalCloseout(peepId, source, reason, closedCount);
		VerificationLog("CornerHeatRaid", $"corner-raid-terminal-finished peep={peepId.id} node={arrestNode?.id ?? NodeID.INVALID} source={source} reason={reason} clearedCornerRaid={clearedCornerRaidContext} clearedPrecinctRaid={clearedPrecinctRaidContext}");
	}

	private static int MarkCornerRaidHumanCloseout(EntityID peepId, string source, string reason)
	{
		if (peepId.IsNotValid || SaveData.NationalHeat?.WitnessEntries == null)
		{
			return 0;
		}

		long peepLongId = (long)peepId.id;
		int closedCount = 0;
		int pendingFederalCount = 0;
		foreach (ImportantWitnessEntry entry in SaveData.NationalHeat.WitnessEntries)
		{
			if (entry == null || entry.ArrestProcessed || entry.CrewPeepId != peepLongId)
			{
				continue;
			}

			if (entry.DeferredFederalFinalizationPending)
			{
				pendingFederalCount++;
				continue;
			}

			MarkImportantWitnessEntryProcessed(entry);
			closedCount++;
		}

		VerificationLog("CornerHeatRaid", $"corner-raid-human-closeout peep={peepId.id} source={source} reason={reason} entriesClosed={closedCount} pendingFederalFinalization={pendingFederalCount}");
		return closedCount;
	}

	private static void LogNationalHeatTerminalCloseout(EntityID peepId, string source, string reason, int closedCount)
	{
		int activeWitnesses = CountActiveImportantWitnessEntries();
		VerificationLog("NationalHeat", $"national-heat-terminal-finished peep={peepId.id} source={source} reason={reason} closedEntries={closedCount} activeWitnesses={activeWitnesses}");
	}

	private static void NoteCornerRaidArrestPostfixApplied(EntityID peepId)
	{
		if (peepId.IsNotValid)
		{
			return;
		}

		_lastCornerHeatArrestPostfixDayByPeep[unchecked((long)peepId.id)] = G.GetNow().days;
	}

	private static void NoteCornerRaidArrestRefreshApplied(EntityID peepId)
	{
		if (peepId.IsNotValid)
		{
			return;
		}

		_lastCornerHeatArrestRefreshDayByPeep[unchecked((long)peepId.id)] = G.GetNow().days;
	}

	internal static void RefreshHumanStateAfterDirectArrest(EntityID peepId, Node arrestNode, string source)
	{
		if (peepId.IsNotValid)
		{
			return;
		}
		try
		{
			if (TryShouldSkipCornerRaidArrestRefresh(peepId, source, out string skipReason, out bool deduped))
			{
				if (!deduped && IsTerminalCornerRaidArrestSkipReason(skipReason) && TryRepairDirectArrestVehicleStateFromSnapshot(peepId, arrestNode, source, skipReason))
				{
					NoteCornerRaidArrestRefreshApplied(peepId);
					VerificationLog("CornerHeatRaid", $"corner-raid-arrest-refresh-recovered peep={peepId.id} node={arrestNode?.id ?? NodeID.INVALID} source={source} reason={skipReason}");
					return;
				}
				VerificationLog("CornerHeatRaid", $"{(deduped ? "corner-raid-arrest-refresh-deduped" : "corner-raid-arrest-refresh-skipped")} peep={peepId.id} node={arrestNode?.id ?? NodeID.INVALID} source={source} reason={skipReason}");
				return;
			}

			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (humanPlayer?.crew == null)
			{
				return;
			}
			CrewAssignment arrestedCrew = humanPlayer.crew.GetCrewForPeep(peepId);
			if (!arrestedCrew.IsValid)
			{
				return;
			}
			Entity arrestedPeep = peepId.FindEntity();
			EnsureCrewRemovedFromBoardAfterArrest(humanPlayer, arrestedCrew, arrestedPeep, source);
			RefreshHumanStateAfterArrest(humanPlayer, arrestedCrew);
			NoteCornerRaidArrestRefreshApplied(peepId);
			VerificationLog("VehicleNodeAuthority", $"arrest-direct-refresh peep={peepId.id} vehicle={arrestedCrew.VehicleID.id} arrestNode={arrestNode?.id ?? NodeID.INVALID} source={source}");
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] RefreshHumanStateAfterDirectArrest failed: " + ex.Message);
		}
	}

	internal const float GANG_MEETING_HAPPINESS_GAIN_LOW = 0.08f;

	internal const float GANG_MEETING_HAPPINESS_GAIN_STANDARD = 0.16f;

	internal const float GANG_MEETING_HAPPINESS_GAIN_LUXURY = 0.24f;

	internal const float PACTOPS_WARHEAT_THRESHOLD_REVENGE = 40f;

	internal const float PACTOPS_WARHEAT_THRESHOLD_COORD_ATTACK = 70f;

	internal const int GANG_WAR_MEDIATION_COOLDOWN_DAYS = 28;

