	private static float GetWarHeatThresholdForRevenge(GangOpsChannel channel)
	{
		return channel == GangOpsChannel.Independent ? 20f : PACTOPS_WARHEAT_THRESHOLD_REVENGE;
	}

	private static float GetWarHeatThresholdForCoordAttack(GangOpsChannel channel)
	{
		return channel == GangOpsChannel.Independent ? 20f : PACTOPS_WARHEAT_THRESHOLD_COORD_ATTACK;
	}

	private static int GetGangOpsTerritoryTakeoverAggressionPercent(GangOpsChannel channel)
	{
		return Mathf.Clamp(EnsureGangOpsSettings(channel)?.TerritoryTakeoverAggressionPercent ?? 100, 10, 300);
	}

	private static float GetEffectiveWarHeatThresholdForRevenge(GangOpsChannel channel)
	{
		PactOpsSettings settings = EnsureGangOpsSettings(channel);
		return ScaleWarHeatThresholdByAggression(GetWarHeatThresholdForRevenge(channel), settings?.OverallAggroPercent ?? 100);
	}

	private static float GetEffectiveWarHeatThresholdForCoordAttack(GangOpsChannel channel)
	{
		PactOpsSettings settings = EnsureGangOpsSettings(channel);
		return ScaleWarHeatThresholdByAggression(GetWarHeatThresholdForCoordAttack(channel), settings?.FrontClosureAggressionPercent ?? 100);
	}

	private static float ScaleWarHeatThresholdByAggression(float baseThreshold, int aggressionPercent)
	{
		int clampedPercent = Mathf.Clamp(aggressionPercent <= 0 ? 100 : aggressionPercent, 10, 300);
		return Mathf.Clamp(baseThreshold * 100f / clampedPercent, 1f, 999f);
	}

