	private static bool TryGetHotVerificationBucket(string scope, string message, out string bucket, out int minIntervalFrames, out bool dedupeExactPerDay)
	{
		bucket = null;
		minIntervalFrames = 0;
		dedupeExactPerDay = false;
		string eventTag = GetVerificationEventTag(message);
		if (!string.IsNullOrEmpty(scope) && scope.StartsWith("GangOps.", StringComparison.Ordinal))
		{
			bucket = string.Equals(eventTag, "turn", StringComparison.Ordinal)
				? $"{scope}:turn"
				: $"{scope}:{eventTag}";
			minIntervalFrames = string.Equals(eventTag, "turn", StringComparison.Ordinal) ? 600 : 300;
			dedupeExactPerDay = string.Equals(eventTag, "turn", StringComparison.Ordinal);
			return true;
		}
		switch (scope)
		{
		case "ScopeOut":
			if (string.Equals(eventTag, "scope-transient-selected-filtered", StringComparison.Ordinal)
				|| string.Equals(eventTag, "building-presence-scope-preview", StringComparison.Ordinal)
				|| string.Equals(eventTag, "building-presence-scope-preview-route", StringComparison.Ordinal)
				|| string.Equals(eventTag, "building-presence-scope-preview-physical", StringComparison.Ordinal)
				|| string.Equals(eventTag, "building-presence-scope-preview-blocked", StringComparison.Ordinal)
				|| string.Equals(eventTag, "scope-feedback-preview-refresh", StringComparison.Ordinal)
				|| string.Equals(eventTag, "scope-feedback-refresh", StringComparison.Ordinal)
				|| string.Equals(eventTag, "preview-scope-direct", StringComparison.Ordinal)
				|| string.Equals(eventTag, "preview-scope-direct-authorized", StringComparison.Ordinal))
			{
				bucket = $"ScopeOut:{eventTag}";
				minIntervalFrames = 120;
				return true;
			}
			if (string.Equals(eventTag, "scope-node-resolve", StringComparison.Ordinal))
			{
				bucket = "ScopeOut:scope-node-resolve";
				minIntervalFrames = 600;
				dedupeExactPerDay = true;
				return true;
			}
			if (string.Equals(eventTag, "scope-building-node-match", StringComparison.Ordinal))
			{
				bucket = "ScopeOut:scope-building-node-match";
				minIntervalFrames = 300;
				return true;
			}
			if (string.Equals(eventTag, "scope-driver-bypass", StringComparison.Ordinal))
			{
				bucket = "ScopeOut:scope-driver-bypass";
				minIntervalFrames = 300;
				return true;
			}
			if (string.Equals(eventTag, "scope-selector-bypassed", StringComparison.Ordinal)
				|| string.Equals(eventTag, "preview-scope-direct", StringComparison.Ordinal)
				|| string.Equals(eventTag, "scope-driver-required", StringComparison.Ordinal))
			{
				bucket = $"ScopeOut:{eventTag}";
				minIntervalFrames = 300;
				return true;
			}
			if (eventTag.StartsWith("scope-feedback-", StringComparison.Ordinal))
			{
				bucket = "ScopeOut:scope-feedback-runtime";
				minIntervalFrames = 300;
				return true;
			}
			break;
		case "VehicleNodeAuthority":
			if (!_verboseVehicleAuthorityRuntimeVerificationLogs)
			{
				if (string.Equals(eventTag, "path-redirect-resolved", StringComparison.Ordinal)
					|| string.Equals(eventTag, "command-path-start", StringComparison.Ordinal)
					|| string.Equals(eventTag, "recent-finalize-cleared", StringComparison.Ordinal)
					|| string.Equals(eventTag, "human-start-preserved", StringComparison.Ordinal)
					|| string.Equals(eventTag, "travel-segment-start", StringComparison.Ordinal)
					|| string.Equals(eventTag, "travel-logical-commit-deferred", StringComparison.Ordinal)
					|| string.Equals(eventTag, "route-mode-label", StringComparison.Ordinal)
					|| string.Equals(eventTag, "selected-segment-authority-source", StringComparison.Ordinal)
					|| string.Equals(eventTag, "crew-display-refresh", StringComparison.Ordinal)
					|| string.Equals(eventTag, "travel-start-business-preview-skipped", StringComparison.Ordinal)
					|| string.Equals(eventTag, "pre-drive-agent-skip", StringComparison.Ordinal)
					|| string.Equals(eventTag, "vehicle-node-reached", StringComparison.Ordinal))
				{
					bucket = "VehicleNodeAuthority:move-start-runtime";
					minIntervalFrames = 60;
					return true;
				}
				if (string.Equals(eventTag, "delivery-route-arrival-confirmed", StringComparison.Ordinal)
					|| string.Equals(eventTag, "delivery-route-pump-wait", StringComparison.Ordinal)
					|| string.Equals(eventTag, "delivery-route-queue-pump", StringComparison.Ordinal)
					|| string.Equals(eventTag, "delivery-route-automation-pump", StringComparison.Ordinal)
					|| string.Equals(eventTag, "delivery-route-pump-summary", StringComparison.Ordinal)
					|| string.Equals(eventTag, "route-requeue-allowed", StringComparison.Ordinal)
					|| string.Equals(eventTag, "route-owned", StringComparison.Ordinal)
					|| string.Equals(eventTag, "route-command-deferred", StringComparison.Ordinal)
					|| string.Equals(eventTag, "route-canactivate-deferred", StringComparison.Ordinal)
					|| string.Equals(eventTag, "route-command-queued-after-arrival", StringComparison.Ordinal)
					|| string.Equals(eventTag, "command-path-deferred", StringComparison.Ordinal)
					|| string.Equals(eventTag, "delivery-route-command-deferred", StringComparison.Ordinal)
					|| string.Equals(eventTag, "delivery-route-start-deferred", StringComparison.Ordinal)
					|| string.Equals(eventTag, "delivery-route-pump-guard-cleared", StringComparison.Ordinal)
					|| string.Equals(eventTag, "route-same-command-allowed", StringComparison.Ordinal)
					|| string.Equals(eventTag, "route-vanilla-clear", StringComparison.Ordinal)
					|| string.Equals(eventTag, "route-vanilla-turnstart-skip", StringComparison.Ordinal)
					|| string.Equals(eventTag, "route-duplicate-command-discarded", StringComparison.Ordinal)
					|| string.Equals(eventTag, "command-path-duplicate-discarded", StringComparison.Ordinal)
					|| string.Equals(eventTag, "travel-conflict-same-route-active", StringComparison.Ordinal))
				{
					bucket = "VehicleNodeAuthority:route-pump-runtime";
					minIntervalFrames = 120;
					return true;
				}
				if (string.Equals(eventTag, "selected-ui-refresh-deferred", StringComparison.Ordinal)
					|| string.Equals(eventTag, "selected-ui-refresh-flushed", StringComparison.Ordinal)
					|| string.Equals(eventTag, "selected-ui-stale-picks-cleared", StringComparison.Ordinal)
					|| string.Equals(eventTag, "selected-final-goal-memory-preserved", StringComparison.Ordinal)
					|| string.Equals(eventTag, "crew-display-refresh-flushed", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-refresh-selected", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-refresh-travel-finalize-deferred-continue", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-refresh-preview-start-cleanup", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-refresh-preview-start-cleanup-skipped", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-refresh-preview-final-node-forced", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-refresh-preview-preserved", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-refresh-preview-corners", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-visibility-grace", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-refresh-other-crews", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-container-refresh-skipped", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-node-refresh-skipped", StringComparison.Ordinal)
					|| string.Equals(eventTag, "crew-dialog-selection-card-state-skipped", StringComparison.Ordinal)
					|| string.Equals(eventTag, "crew-dialog-selection-grace-flush-skipped", StringComparison.Ordinal)
					|| string.Equals(eventTag, "crew-dialog-selection-already-current-skipped", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-selection-grace-direct", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-refresh-skip", StringComparison.Ordinal)
					|| string.Equals(eventTag, "building-pick-refresh", StringComparison.Ordinal))
				{
					bucket = "VehicleNodeAuthority:travel-finalize-ui";
					minIntervalFrames = 120;
					return true;
				}
			}
			switch (eventTag)
			{
			case "building-interaction-scope":
				bucket = "VehicleNodeAuthority:building-interaction-scope";
				minIntervalFrames = 300;
				dedupeExactPerDay = true;
				return true;
			case "building-node-source":
			case "arrival-node":
				bucket = $"VehicleNodeAuthority:{eventTag}";
				minIntervalFrames = 300;
				dedupeExactPerDay = true;
				return true;
			case "building-node-selected-goal":
			case "building-node-suppressed":
			case "startup-authority-stable":
				bucket = $"VehicleNodeAuthority:{eventTag}";
				minIntervalFrames = 300;
				return true;
			case "ambient-spawn-policy":
			case "ambient-spawn":
			case "ambient-spawn-skip":
				bucket = $"VehicleNodeAuthority:{eventTag}";
				minIntervalFrames = 300;
				return true;
			case "selected-scope-node-fallback":
				bucket = "VehicleNodeAuthority:selected-scope-node-fallback";
				minIntervalFrames = 300;
				return true;
			case "crew-pick-driver-portrait":
				bucket = "VehicleNodeAuthority:crew-pick-driver-portrait";
				minIntervalFrames = 300;
				return true;
			case "heal-validate-hidden":
			case "heal-validate-disabled":
			case "heal-validate-enabled":
			case "heal-skip":
				bucket = $"VehicleNodeAuthority:{eventTag}";
				minIntervalFrames = 300;
				return true;
			case "owned-building-preview-fallback-miss":
			case "owned-building-preview-fallback":
				bucket = $"VehicleNodeAuthority:{eventTag}";
				minIntervalFrames = 300;
				return true;
			case "route-sim-access":
				bucket = "VehicleNodeAuthority:route-preview-access";
				minIntervalFrames = 300;
				return true;
			case "building-presence-preview-ignored":
			case "scope-preview-source":
			case "scope-preview-source-bypassed":
			case "travel-conflict-same-route":
			case "route-vanilla-turnstart-skip":
			case "building-pick-refresh-preview-start-cleanup":
			case "building-pick-refresh-preview-start-cleanup-skipped":
			case "building-pick-refresh-preview-final-node-forced":
			case "building-pick-refresh-preview-preserved":
			case "building-pick-refresh-coalesced":
			case "building-pick-refresh-coalesced-flush":
			case "selected-scope-preview-preferred":
			case "selected-scope-old-node-blocked":
			case "preview-scope-stale-start-blocked":
			case "selected-scope-physical-node-source":
				bucket = $"VehicleNodeAuthority:{eventTag}";
				minIntervalFrames = 120;
				return true;
			case "crew-display-refresh":
			case "building-pick-refresh-selected":
			case "building-pick-refresh-preview-suppressed":
			case "building-pick-refresh-preview-corners":
			case "building-pick-refresh-other-crews":
			case "building-pick-refresh":
			case "final-goal-preview-source":
			case "route-cleared":
			case "pending-travel-cleared":
			case "travel-segment-start":
			case "travel-segment-finalize":
			case "travel-finalize-source":
			case "travel-finalize-override":
			case "travel-end-sync":
			case "resume-authority-preserved":
			case "command-path-start":
			case "pre-drive-agent-skip":
			case "interactive-node":
			case "VehicleArrivalPresence":
			case "selected-segment-authority-source":
			case "actual-action-source":
			case "attack-node-reroute":
			case "fallback-sync-skip":
			case "driver-switch-refresh":
			case "driver-switch-context":
			case "driver-switch-mp":
			case "selected-ui-refresh-coalesced":
			case "same-node-ui-picks-cleared":
				bucket = $"VehicleNodeAuthority:{eventTag}";
				minIntervalFrames = 300;
				return true;
			}
			if (eventTag.StartsWith("ai-", StringComparison.Ordinal) || string.Equals(eventTag, "repair", StringComparison.Ordinal))
			{
				bucket = "VehicleNodeAuthority:ai-runtime";
				minIntervalFrames = 600;
				return true;
			}
			break;
		case "Compat":
			if (string.Equals(eventTag, "ai-outpost-territory-pass", StringComparison.Ordinal)
				|| string.Equals(eventTag, "territory-neutral-claim", StringComparison.Ordinal)
				|| eventTag.StartsWith("deferred-human-territory-", StringComparison.Ordinal)
				|| eventTag.StartsWith("deferred-illegal-backroom-visual-refresh", StringComparison.Ordinal))
			{
				bucket = $"Compat:{eventTag}";
				minIntervalFrames = 600;
				dedupeExactPerDay = string.Equals(eventTag, "ai-outpost-territory-pass", StringComparison.Ordinal);
				return true;
			}
			break;
		case "GangMoneyIn":
			if (string.Equals(eventTag, "deduped", StringComparison.Ordinal)
				|| string.Equals(eventTag, "deduped-day", StringComparison.Ordinal)
				|| string.Equals(eventTag, "blocked", StringComparison.Ordinal)
				|| string.Equals(eventTag, "applied", StringComparison.Ordinal))
			{
				bucket = $"GangMoneyIn:{eventTag}";
				minIntervalFrames = 120;
				dedupeExactPerDay = string.Equals(eventTag, "deduped-day", StringComparison.Ordinal);
				return true;
			}
			break;
		case "CornerHeatRaid":
			if (string.Equals(eventTag, "trySellOutToFeds-skipped", StringComparison.Ordinal))
			{
				bucket = "CornerHeatRaid:trySellOutToFeds-skipped";
				minIntervalFrames = 180;
				return true;
			}
			break;
		case "AttackAdvisor":
			if (string.Equals(eventTag, "attackadvisor-coord-skipped", StringComparison.Ordinal)
				|| string.Equals(eventTag, "attackadvisor-coord-prereqs-bypassed", StringComparison.Ordinal))
			{
				bucket = $"AttackAdvisor:{eventTag}";
				minIntervalFrames = 180;
				return true;
			}
			break;
		case "AmbientTraffic":
			if (string.Equals(eventTag, "spawn", StringComparison.Ordinal))
			{
				bucket = "AmbientTraffic:spawn";
				minIntervalFrames = 30;
				return true;
			}
			break;
		case "PactColorUI":
			if (string.Equals(eventTag, "full", StringComparison.Ordinal))
			{
				bucket = "PactColorUI:full-refresh";
				minIntervalFrames = 300;
				return true;
			}
			break;
		case "RelationshipCleanup":
			if (string.Equals(eventTag, "dead-peep", StringComparison.Ordinal))
			{
				bucket = "RelationshipCleanup:dead-peep";
				minIntervalFrames = 45;
				return true;
			}
			break;
		case "VehicleGroupCombat.AI":
			if (string.Equals(eventTag, "mode-skip", StringComparison.Ordinal))
			{
				bucket = "VehicleGroupCombat.AI:mode-skip";
				minIntervalFrames = 300;
				return true;
			}
			if (string.Equals(eventTag, "entry", StringComparison.Ordinal)
				|| string.Equals(eventTag, "ai-vehicle-combat", StringComparison.Ordinal)
				|| string.Equals(eventTag, "mode", StringComparison.Ordinal)
				|| string.Equals(eventTag, "round", StringComparison.Ordinal)
				|| string.Equals(eventTag, "result", StringComparison.Ordinal)
				|| string.Equals(eventTag, "split", StringComparison.Ordinal)
				|| string.Equals(eventTag, "driveby", StringComparison.Ordinal))
			{
				bucket = $"VehicleGroupCombat.AI:{eventTag}";
				minIntervalFrames = 120;
				return true;
			}
			break;
		case "VehicleGroupCombat":
			if (string.Equals(eventTag, "execute", StringComparison.Ordinal)
				|| string.Equals(eventTag, "driveby-attackers", StringComparison.Ordinal)
				|| string.Equals(eventTag, "defender-split", StringComparison.Ordinal))
			{
				bucket = $"VehicleGroupCombat:{eventTag}";
				minIntervalFrames = 120;
				return true;
			}
			break;
		}
		return false;
	}

	private static bool TryPrepareVerificationLog(string scope, string message, out string effectiveMessage)
	{
		effectiveMessage = message ?? string.Empty;
		if (!ShouldEmitVerificationLog(scope, effectiveMessage))
		{
			return false;
		}
		if (!TryGetHotVerificationBucket(scope, effectiveMessage, out string bucket, out int minIntervalFrames, out bool dedupeExactPerDay))
		{
			return true;
		}

		int day = G.GetNow().days;
		if (_hotVerificationSeenMessageDay != day)
		{
			_hotVerificationSeenMessageDay = day;
			_hotVerificationSeenMessageKeys.Clear();
		}

		if (dedupeExactPerDay)
		{
			string exactKey = $"{scope}:{effectiveMessage}";
			if (!_hotVerificationSeenMessageKeys.Add(exactKey))
			{
				IncrementHotVerificationSuppressedCount(bucket);
				return false;
			}
		}

		int currentFrame = Time.frameCount;
		if (_hotVerificationLastFrameByBucket.TryGetValue(bucket, out int lastFrame) && currentFrame - lastFrame < minIntervalFrames)
		{
			IncrementHotVerificationSuppressedCount(bucket);
			return false;
		}

		_hotVerificationLastFrameByBucket[bucket] = currentFrame;
		if (_hotVerificationSuppressedCountsByBucket.TryGetValue(bucket, out int suppressedCount) && suppressedCount > 0)
		{
			_hotVerificationSuppressedCountsByBucket.Remove(bucket);
			if (!string.Equals(bucket, "RelationshipCleanup:dead-peep", StringComparison.Ordinal))
			{
				effectiveMessage += $" suppressed={suppressedCount}";
			}
		}
		return true;
	}

	internal static void RecordDeathSource(EntityID peepId, string source)
	{
		if (!peepId.IsValid || string.IsNullOrWhiteSpace(source))
		{
			return;
		}
		LastDeathSourceByPeepId[(long)peepId.id] = source;
	}

	internal static bool TryGetDeathSourceLabel(EntityID peepId, out string label)
	{
		label = null;
		if (!peepId.IsValid || !LastDeathSourceByPeepId.TryGetValue((long)peepId.id, out string source) || string.IsNullOrWhiteSpace(source))
		{
			return false;
		}
		switch (source)
		{
		case "grouped-combat":
			label = "combat";
			break;
		case "raid":
			label = "raid";
			break;
		case "snitch":
			label = "hit";
			break;
		case "natural-external":
			label = "natural causes";
			break;
		case "natural-gameplaytweaks":
			label = "natural causes";
			break;
		default:
			label = source.Replace("-", " ").Trim();
			break;
		}
		return !string.IsNullOrWhiteSpace(label);
	}

	internal static Vector2 ScalePopupSize(float width, float height)
	{
		if (!_popupScaleLogged)
		{
			_popupScaleLogged = true;
			VerificationLog("PopupScale", $"applied factor={ModPopupScaleFactor:0.00}");
		}
		return new Vector2(width * ModPopupScaleFactor, height * ModPopupScaleFactor);
	}

	internal static void ForceDockPopupFarLeft(GameObject popup, float leftMarginPx = 16f)
	{
		if ((UnityEngine.Object)(object)popup == (UnityEngine.Object)null)
		{
			return;
		}
		RectTransform component = popup.GetComponent<RectTransform>();
		if ((UnityEngine.Object)(object)component == (UnityEngine.Object)null)
		{
			return;
		}
		Vector2 targetAnchor = new Vector2(0f, 0.5f);
		Vector2 targetPosition = new Vector2(leftMarginPx, 0f);
		Transform parent = popup.transform.parent;
		bool alreadyLastSibling = parent == null || popup.transform.GetSiblingIndex() >= parent.childCount - 1;
		bool alreadyDocked =
			Vector2.Distance(component.anchorMin, targetAnchor) < 0.01f &&
			Vector2.Distance(component.anchorMax, targetAnchor) < 0.01f &&
			Vector2.Distance(component.pivot, targetAnchor) < 0.01f &&
			Vector2.Distance(component.anchoredPosition, targetPosition) < 0.5f;

		if (alreadyDocked && alreadyLastSibling)
		{
			return;
		}

		if (!alreadyDocked)
		{
			component.anchorMin = targetAnchor;
			component.anchorMax = targetAnchor;
			component.pivot = targetAnchor;
			component.anchoredPosition = targetPosition;
		}
		if (!alreadyLastSibling)
		{
			popup.transform.SetAsLastSibling();
		}

		int instanceId = popup.GetInstanceID();
		string signature = ((UnityEngine.Object)popup).name + "|" + leftMarginPx.ToString("0", CultureInfo.InvariantCulture) + "|" + Time.frameCount;
		if (!_lastPopupDockSignatureByInstanceId.TryGetValue(instanceId, out string lastSignature) || !string.Equals(lastSignature, signature, StringComparison.Ordinal))
		{
			_lastPopupDockSignatureByInstanceId[instanceId] = signature;
			VerificationLog("PopupDock", $"popup={((UnityEngine.Object)popup).name} x={leftMarginPx:0}");
		}
	}

