	internal static void RunVerificationChecklist10()
	{
		VerificationStats verificationStats = EnsureVerifyStats();
		int days = -1;
		try
		{
			days = G.GetNow().days;
		}
		catch
		{
		}
		VerificationLog("Checklist10", $"begin day={days}");
		LogChecklistLine(1, (verificationStats.BossLoyaltyChecks > 0 && verificationStats.BossLoyaltyViolations == 0) ? "PASS" : ((verificationStats.BossLoyaltyChecks > 0) ? "WARN" : "PENDING"), "Boss loyalty lock", $"checks={verificationStats.BossLoyaltyChecks} violations={verificationStats.BossLoyaltyViolations}");
		LogChecklistLine(2, (verificationStats.LoyaltyCapInitCount > 0) ? "PASS" : "PENDING", "Trait cap init", $"capInits={verificationStats.LoyaltyCapInitCount}");
		LogChecklistLine(3, (verificationStats.LoyaltyDecayEvents > 0) ? "PASS" : "PENDING", "Low happiness loyalty decay", $"decayEvents={verificationStats.LoyaltyDecayEvents}");
		LogChecklistLine(4, (verificationStats.ZeroLoyaltyDefections > 0) ? "PASS" : "PENDING", "Zero loyalty defection gate", $"defections={verificationStats.ZeroLoyaltyDefections}");
		LogChecklistLine(5, (verificationStats.PepTalkLoyaltyGainEvents > 0 || verificationStats.GiftLoyaltyGainEvents > 0 || verificationStats.VacationLoyaltyGainEvents > 0) ? "PASS" : "PENDING", "Support loyalty gains", $"pep={verificationStats.PepTalkLoyaltyGainEvents} gift={verificationStats.GiftLoyaltyGainEvents} vacation={verificationStats.VacationLoyaltyGainEvents}");
		LogChecklistLine(6, (verificationStats.SnitchIntakeRuns > 0) ? "PASS" : "PENDING", "Snitch intake cadence", $"runs={verificationStats.SnitchIntakeRuns} cadence={SNITCH_COLLECTION_TURNS}d");
		LogChecklistLine(7, (verificationStats.SnitchRaidTriggers > 0) ? "PASS" : "PENDING", "Case 100 federal raid", $"raids={verificationStats.SnitchRaidTriggers}");
		LogChecklistLine(8, (verificationStats.RetainerUpkeepTicks > 0) ? "PASS" : "PENDING", "Retainer burn", $"upkeepTicks={verificationStats.RetainerUpkeepTicks}");
		LogChecklistLine(9, (verificationStats.RetainerTrialAssistRolls > 0) ? "PASS" : "PENDING", "Retainer trial assist", $"rolls={verificationStats.RetainerTrialAssistRolls} wins={verificationStats.RetainerTrialAssistWins}");
		LogChecklistLine(10, "PENDING", "System regression sweep", "manual combat/pact/national-heat checks required");
		VerificationLog("Checklist10", "end");
	}

	internal static void RunRuntimeVerificationChecklist()
	{
		int days = -1;
		try
		{
			days = G.GetNow().days;
		}
		catch
		{
		}
		PactOpsSettings pactOpsSettings = EnsureGangOpsSettings(GangOpsChannel.Pact);
		PactOpsSettings pactOpsSettings2 = EnsureGangOpsSettings(GangOpsChannel.Independent);
		int num = GetEligibleGangIdsForChannel(GangOpsChannel.Pact).Count;
		int num2 = GetEligibleGangIdsForChannel(GangOpsChannel.Independent).Count;
		int count = GetWarHeatStore(GangOpsChannel.Pact).Count;
		int count2 = GetWarHeatStore(GangOpsChannel.Independent).Count;
		int num3 = GetRevengeStore(GangOpsChannel.Pact).Count((KeyValuePair<string, RevengeEntry> kv) => kv.Value != null && !kv.Value.Executed);
		int num4 = GetRevengeStore(GangOpsChannel.Independent).Count((KeyValuePair<string, RevengeEntry> kv) => kv.Value != null && !kv.Value.Executed);
		VerificationLog("RuntimeChecklist", $"begin day={days}");
		VerificationLog("RuntimeChecklist", $"1. {(ConnectionsTabNullFixPatch.PatchedMethodCount > 0 ? "PASS" : "WARN")} connections-tab patchMethods={ConnectionsTabNullFixPatch.PatchedMethodCount}");
		VerificationLog("RuntimeChecklist", $"2. {(GangPanelBuffDebugPatch.HookedMethodCount > 0 ? "PASS" : "WARN")} gang-panel buffHookMethods={GangPanelBuffDebugPatch.HookedMethodCount}");
		VerificationLog("RuntimeChecklist", $"3. {(CrewPeepInspectModButtonsPatch.PatchedMethodCount > 0 ? "PASS" : "WARN")} crew-inspect buttons patchMethods={CrewPeepInspectModButtonsPatch.PatchedMethodCount}");
		VerificationLog("RuntimeChecklist", $"4. {(OrgChartGangOpsButtonPatch.PatchedMethodCount > 0 ? "PASS" : "WARN")} orgchart gangops patchMethods={OrgChartGangOpsButtonPatch.PatchedMethodCount}");
		VerificationLog("RuntimeChecklist", $"5. {(EnableAIAlliances.Value ? "PASS" : "WARN")} gangops masterEnabled={EnableAIAlliances.Value}");
		VerificationLog("RuntimeChecklist", $"6. {(pactOpsSettings.Enabled ? "PASS" : "PENDING")} pact enabled={pactOpsSettings.Enabled} gangs={num} warHeat={count} revengePending={num3}");
		VerificationLog("RuntimeChecklist", $"7. {(pactOpsSettings2.Enabled ? "PASS" : "PENDING")} independent enabled={pactOpsSettings2.Enabled} gangs={num2} warHeat={count2} revengePending={num4}");
		VerificationLog("RuntimeChecklist", $"8. {(SaveData.GangOpsDefaultsProfileVersion >= GangOpsDefaultsProfileVersionCurrent ? "PASS" : "WARN")} defaultsSeed version={SaveData.GangOpsDefaultsProfileVersion}");
		VerificationLog("RuntimeChecklist", "end");
	}

