		private static List<CrewSideQuestEntry> GetPendingCrewSideQuestStore()
		{
			if (SaveData == null)
			{
				SaveData = new ModSaveData();
			}
			if (SaveData.PendingCrewSideQuests == null)
			{
				SaveData.PendingCrewSideQuests = new List<CrewSideQuestEntry>();
			}
			return SaveData.PendingCrewSideQuests;
		}

		private static List<PactSideQuestEntry> GetPendingPactSideQuestStore()
		{
			if (SaveData == null)
			{
				SaveData = new ModSaveData();
			}
			if (SaveData.PendingPactSideQuests == null)
			{
				SaveData.PendingPactSideQuests = new List<PactSideQuestEntry>();
			}
			return SaveData.PendingPactSideQuests;
		}

		private const int CrewQuestMinWindowDays = 28;

		private const int CrewQuestMaxWindowDays = 84;

		private const int CrewQuestSecondOfferMinGapDays = 14;

		private static int GetPendingCrewSideQuestCount()
		{
			EnsureCrewSideQuestsSeededForHumanBoss();
			return GetPendingCrewSideQuestStore().Count;
		}

		private static int GetPendingPactSideQuestCount()
		{
			EnsurePactSideQuestsSeededForHumanBoss();
			return GetPendingPactSideQuestStore().Count;
		}

		private static void EnsureCrewSideQuestsSeededForHumanBoss()
		{
			try
			{
				if (_activeCrewPepTalkPrompt != null)
				{
					return;
				}
				List<CrewSideQuestEntry> pending = GetPendingCrewSideQuestStore();
				if (pending.Count > 0)
				{
					return;
				}
				int day = G.GetNow().days;
				if (SaveData.NextCrewSideQuestGlobalEligibleDay > day)
				{
					VerificationLog("CrewRelations", $"quest-cadence-skip peep=0 reason=global-not-due day={day} nextDay={SaveData.NextCrewSideQuestGlobalEligibleDay}");
					return;
				}
				PlayerInfo humanPlayer = G.GetHumanPlayer();
				PlayerCrew crew = humanPlayer?.crew;
				if (crew == null)
				{
					return;
				}
				foreach (CrewAssignment assignment in crew.GetLiving())
				{
					if (!assignment.IsValid || !assignment.peepId.IsValid || !assignment.IsNotDead || !crew.IsOnBoard(assignment.peepId) || IsCrewCurrentlyJailed(assignment.peepId))
					{
						continue;
					}
					Entity peep = assignment.GetPeep();
					if (peep == null)
					{
						continue;
					}
					CrewModState state = GetOrCreateCrewState(peep.Id);
					if (!TryPrepareCrewSideQuestCadence(peep, state, humanPlayer, out string cadenceReason))
					{
						VerificationLog("CrewRelations", $"quest-cadence-skip peep={peep.Id.id} reason={cadenceReason}");
						continue;
					}
					if (TryQueueCrewPepTalkPrompt(peep, state, humanPlayer, requireChance: false))
					{
						MarkCrewSideQuestQueuedByCadence(peep, state, humanPlayer);
						SaveData.NextCrewSideQuestGlobalEligibleDay = day + 7;
						VerificationLog("CrewRelations", $"quest-global-cooldown-set peep={peep.Id.id} nextDay={SaveData.NextCrewSideQuestGlobalEligibleDay}");
						break;
					}
				}
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] EnsureCrewSideQuestsSeededForHumanBoss failed: " + ex.Message);
			}
		}

		private static bool TryPrepareCrewSideQuestCadence(Entity peep, CrewModState state, PlayerInfo humanPlayer, out string reason)
		{
			reason = "none";
			if (peep == null || state == null || humanPlayer == null)
			{
				reason = "missing-state";
				return false;
			}

			if (GetManualPepTalksRemaining(peep) <= 0)
			{
				reason = "manual-pep-talk-used-today";
				return false;
			}

			int day = G.GetNow().days;
			bool isBoss = IsHumanBoss(peep, humanPlayer);
			if (state.CrewQuestWindowEndDay <= day || state.NextCrewQuestEligibleDay < 0 || state.NextCrewQuestEligibleDay > state.CrewQuestWindowEndDay)
			{
				RollCrewSideQuestWindow(peep, state, isBoss, day);
			}

			if (state.CrewQuestOffersRemainingInWindow <= 0)
			{
				reason = "window-empty nextDay=" + state.NextCrewQuestEligibleDay;
				return false;
			}

			if (day < state.NextCrewQuestEligibleDay)
			{
				reason = "not-due day=" + day + " nextDay=" + state.NextCrewQuestEligibleDay;
				return false;
			}

			return true;
		}

		private static void RollCrewSideQuestWindow(Entity peep, CrewModState state, bool isBoss, int day)
		{
			int weeks = SharedRng.Next(4, 13);
			int windowEnd = day + Mathf.Clamp(weeks * 7, CrewQuestMinWindowDays, CrewQuestMaxWindowDays);
			double roll = SharedRng.NextDouble();
			double noOfferChance = isBoss ? 0.2 : 0.38;
			double oneOfferChance = isBoss ? 0.55 : 0.5;
			int maxOffers = roll < noOfferChance ? 0 : (roll < noOfferChance + oneOfferChance ? 1 : 2);

			state.CrewQuestWindowEndDay = windowEnd;
			state.CrewQuestOffersRemainingInWindow = maxOffers;
			state.NextCrewQuestEligibleDay = maxOffers > 0 ? day : windowEnd;

			if (maxOffers <= 0)
			{
				VerificationLog("CrewRelations", $"quest-window-skipped peep={peep.Id.id} boss={isBoss} weeks={weeks} nextDay={state.NextCrewQuestEligibleDay}");
			}
			else
			{
				VerificationLog("CrewRelations", $"quest-window-rolled peep={peep.Id.id} boss={isBoss} weeks={weeks} maxOffers={maxOffers} nextDay={state.NextCrewQuestEligibleDay} endDay={windowEnd}");
			}
		}

		private static void MarkCrewSideQuestQueuedByCadence(Entity peep, CrewModState state, PlayerInfo humanPlayer)
		{
			if (peep == null || state == null)
			{
				return;
			}

			int day = G.GetNow().days;
			bool isBoss = IsHumanBoss(peep, humanPlayer);
			state.CrewQuestOffersRemainingInWindow = Math.Max(0, state.CrewQuestOffersRemainingInWindow - 1);
			int nextDay = state.CrewQuestWindowEndDay;
			if (state.CrewQuestOffersRemainingInWindow > 0)
			{
				int earliest = day + CrewQuestSecondOfferMinGapDays;
				if (earliest < state.CrewQuestWindowEndDay)
				{
					nextDay = SharedRng.Next(earliest, state.CrewQuestWindowEndDay + 1);
				}
			}

			state.NextCrewQuestEligibleDay = nextDay;
			VerificationLog("CrewRelations", $"quest-available peep={peep.Id.id} boss={isBoss} remainingInWindow={state.CrewQuestOffersRemainingInWindow} nextDay={state.NextCrewQuestEligibleDay} endDay={state.CrewQuestWindowEndDay}");
		}

		private static void EnsurePactSideQuestsSeededForHumanBoss()
		{
			try
			{
				if (_activePactSupportPrompt != null)
				{
					return;
				}
				List<PactSideQuestEntry> pending = GetPendingPactSideQuestStore();
				if (pending.Count > 0)
				{
					return;
				}
				AlliancePact pact = ResolveDisplayedMyPact();
				if (pact == null)
				{
					return;
				}
				foreach (int gangId in GetPactMemberGangIds(pact).Where(id => id >= 0).Distinct())
				{
					if (GetPactPepTalksRemaining(gangId) <= 0)
					{
						continue;
					}
					if (TryQueuePactSupportPrompt(pact, gangId, GetGangDisplayName(gangId), requireChance: false))
					{
						break;
					}
				}
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] EnsurePactSideQuestsSeededForHumanBoss failed: " + ex.Message);
			}
		}

		private static bool EnqueueCrewSideQuest(CrewPepTalkPromptEvent prompt)
		{
			if (prompt == null || !prompt.PeepId.IsValid)
			{
				return false;
			}

			List<CrewSideQuestEntry> pending = GetPendingCrewSideQuestStore();
			if (pending.Any(item => item != null && item.PeepIdRaw == (long)prompt.PeepId.id && string.Equals(item.Title, prompt.Title, StringComparison.Ordinal)))
			{
				return false;
			}

			if (pending.Count >= 12)
			{
				pending.RemoveAt(0);
			}

			pending.Add(new CrewSideQuestEntry
			{
				PeepIdRaw = (long)prompt.PeepId.id,
				PeepName = prompt.PeepName ?? string.Empty,
				IsBoss = prompt.IsBoss,
				Title = prompt.Title ?? string.Empty,
				Body = prompt.Body ?? string.Empty,
				AcceptLabel = prompt.AcceptLabel ?? string.Empty,
				DeclineLabel = prompt.DeclineLabel ?? string.Empty,
				Cost = prompt.Cost,
				HappinessDeltaOnAccept = prompt.HappinessDeltaOnAccept,
				LoyaltyDeltaOnAccept = prompt.LoyaltyDeltaOnAccept,
				HappinessDeltaOnDecline = prompt.HappinessDeltaOnDecline,
				LoyaltyDeltaOnDecline = prompt.LoyaltyDeltaOnDecline,
				SpecialActionKey = prompt.SpecialActionKey ?? string.Empty,
				AcceptTickerText = prompt.AcceptTickerText ?? string.Empty,
				DeclineTickerText = prompt.DeclineTickerText ?? string.Empty
			});
			return true;
		}

		private static bool EnqueuePactSideQuest(PactSupportPromptEvent prompt)
		{
			if (prompt == null || prompt.BossGangId < 0)
			{
				return false;
			}

			List<PactSideQuestEntry> pending = GetPendingPactSideQuestStore();
			if (pending.Any(item => item != null && item.BossGangId == prompt.BossGangId && string.Equals(item.Title, prompt.Title, StringComparison.Ordinal)))
			{
				return false;
			}

			if (pending.Count >= 12)
			{
				pending.RemoveAt(0);
			}

			pending.Add(new PactSideQuestEntry
			{
				PactId = prompt.Pact?.PactId ?? string.Empty,
				PactColorIndex = prompt.Pact?.ColorIndex ?? -1,
				BossGangId = prompt.BossGangId,
				BossName = prompt.BossName ?? string.Empty,
				Title = prompt.Title ?? string.Empty,
				Body = prompt.Body ?? string.Empty,
				AcceptLabel = prompt.AcceptLabel ?? string.Empty,
				DeclineLabel = prompt.DeclineLabel ?? string.Empty,
				Cost = prompt.Cost,
				HappinessDeltaOnAccept = prompt.HappinessDeltaOnAccept,
				HappinessDeltaOnDecline = prompt.HappinessDeltaOnDecline,
				RelationBuffId = prompt.RelationBuffId ?? string.Empty,
				AcceptTickerText = prompt.AcceptTickerText ?? string.Empty,
				DeclineTickerText = prompt.DeclineTickerText ?? string.Empty
			});
			return true;
		}

		private static CrewPepTalkPromptEvent DequeueNextCrewSideQuest()
		{
			List<CrewSideQuestEntry> pending = GetPendingCrewSideQuestStore();
			while (pending.Count > 0)
			{
				CrewSideQuestEntry entry = pending[0];
				pending.RemoveAt(0);
				EntityID peepId = (EntityID)(ulong)Math.Max(0L, entry?.PeepIdRaw ?? 0L);
				Entity peep = peepId.FindEntity();
				if (entry == null || peep == null || peep.data?.person == null || GetCrewStateOrNull(peep.Id) == null)
				{
					continue;
				}

				return new CrewPepTalkPromptEvent
				{
					PeepId = peep.Id,
					PeepName = string.IsNullOrWhiteSpace(entry.PeepName) ? (peep.data.person.ShortName ?? peep.data.person.FullName ?? "Crew Member") : entry.PeepName,
					IsBoss = entry.IsBoss,
					Title = entry.Title ?? string.Empty,
					Body = entry.Body ?? string.Empty,
					AcceptLabel = string.IsNullOrWhiteSpace(entry.AcceptLabel) ? "Accept" : entry.AcceptLabel,
					DeclineLabel = string.IsNullOrWhiteSpace(entry.DeclineLabel) ? "Decline" : entry.DeclineLabel,
					Cost = entry.Cost,
					HappinessDeltaOnAccept = entry.HappinessDeltaOnAccept,
					LoyaltyDeltaOnAccept = entry.LoyaltyDeltaOnAccept,
					HappinessDeltaOnDecline = entry.HappinessDeltaOnDecline,
					LoyaltyDeltaOnDecline = entry.LoyaltyDeltaOnDecline,
					SpecialActionKey = entry.SpecialActionKey ?? string.Empty,
					AcceptTickerText = entry.AcceptTickerText ?? string.Empty,
					DeclineTickerText = entry.DeclineTickerText ?? string.Empty
				};
			}

			return null;
		}

		private static PactSupportPromptEvent DequeueNextPactSideQuest()
		{
			List<PactSideQuestEntry> pending = GetPendingPactSideQuestStore();
			while (pending.Count > 0)
			{
				PactSideQuestEntry entry = pending[0];
				pending.RemoveAt(0);
				AlliancePact pact = null;
				if (SaveData?.Pacts != null)
				{
					pact = SaveData.Pacts.FirstOrDefault(item => item != null && !string.IsNullOrEmpty(entry?.PactId) && string.Equals(item.PactId, entry.PactId, StringComparison.Ordinal))
						?? SaveData.Pacts.FirstOrDefault(item => item != null && item.ColorIndex == (entry?.PactColorIndex ?? -1));
				}
				if (entry == null || pact == null || entry.BossGangId < 0 || G.FindPlayerById(entry.BossGangId) == null)
				{
					continue;
				}

				return new PactSupportPromptEvent
				{
					Pact = pact,
					BossGangId = entry.BossGangId,
					BossName = string.IsNullOrWhiteSpace(entry.BossName) ? GetGangDisplayName(entry.BossGangId) : entry.BossName,
					Title = entry.Title ?? string.Empty,
					Body = entry.Body ?? string.Empty,
					AcceptLabel = string.IsNullOrWhiteSpace(entry.AcceptLabel) ? "Accept" : entry.AcceptLabel,
					DeclineLabel = string.IsNullOrWhiteSpace(entry.DeclineLabel) ? "Decline" : entry.DeclineLabel,
					Cost = entry.Cost,
					HappinessDeltaOnAccept = entry.HappinessDeltaOnAccept,
					HappinessDeltaOnDecline = entry.HappinessDeltaOnDecline,
					RelationBuffId = entry.RelationBuffId ?? string.Empty,
					AcceptTickerText = entry.AcceptTickerText ?? string.Empty,
					DeclineTickerText = entry.DeclineTickerText ?? string.Empty
				};
			}

			return null;
		}

		private static string FormatPromptBody(string speakerName, string body, string fallbackHeader)
		{
			string header = !string.IsNullOrWhiteSpace(speakerName) ? (speakerName + " sent word.") : (fallbackHeader ?? string.Empty);
			string trimmedBody = string.IsNullOrWhiteSpace(body) ? string.Empty : body.Trim();
			if (string.IsNullOrWhiteSpace(trimmedBody))
			{
				return header;
			}
			if (string.IsNullOrWhiteSpace(header))
			{
				return trimmedBody;
			}
			return header + "\n\n" + trimmedBody;
		}

