		private static bool TryQueuePactSupportPrompt(AlliancePact pact, int bossGangId, string bossName, bool requireChance = true)
		{
			if (pact == null || bossGangId < 0)
			{
				VerificationLog("PepTalkPact", $"prompt-skip gang={bossGangId} boss={bossName ?? "Unknown"} reason=invalid-pact");
				return false;
			}
			int nowDay = G.GetNow().days;
			if (_pactSupportLastPromptDayByGang.TryGetValue(bossGangId, out int lastPromptDay) && nowDay - lastPromptDay < 10)
			{
				VerificationLog("PepTalkPact", $"prompt-skip gang={bossGangId} boss={bossName} day={nowDay} reason=cooldown lastDay={lastPromptDay}");
				return false;
			}
			if (requireChance && SharedRng.NextDouble() >= 0.45)
			{
				VerificationLog("PepTalkPact", $"prompt-skip gang={bossGangId} boss={bossName} day={nowDay} reason=chance");
				return false;
			}
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			PlayerInfo bossGang = G.FindPlayerById(bossGangId);
			if (humanPlayer == null || bossGang == null)
			{
				VerificationLog("PepTalkPact", $"prompt-skip gang={bossGangId} boss={bossName} day={nowDay} reason=missing-player");
				return false;
			}
			List<PactSupportPromptEvent> list = new List<PactSupportPromptEvent>
			{
				new PactSupportPromptEvent
				{
					Pact = pact,
					BossGangId = bossGangId,
					BossName = bossName,
					Title = "Pact Favor",
					Body = bossName + " says payroll is running short after a rough week. Cover $75 so their people stay quiet?",
					AcceptLabel = "Cover $75",
					DeclineLabel = "Not Now",
					Cost = 75,
					HappinessDeltaOnAccept = 0.12f,
					HappinessDeltaOnDecline = -0.04f,
					RelationBuffId = "relbuff-gangs-truce",
					AcceptTickerText = "PACT: You covered payroll pressure for " + bossName + ".",
					DeclineTickerText = "PACT: You passed on " + bossName + "'s payroll favor."
				},
				new PactSupportPromptEvent
				{
					Pact = pact,
					BossGangId = bossGangId,
					BossName = bossName,
					Title = "Keep the Lawyers Busy",
					Body = bossName + " wants $110 to keep a quiet lawyer on retainer for one of their runners. Do you front it?",
					AcceptLabel = "Pay $110",
					DeclineLabel = "Decline",
					Cost = 110,
					HappinessDeltaOnAccept = 0.13f,
					HappinessDeltaOnDecline = -0.05f,
					RelationBuffId = "relbuff-gangs-hideout-shared",
					AcceptTickerText = "PACT: You helped " + bossName + " keep a lawyer paid.",
					DeclineTickerText = "PACT: You left " + bossName + " to sort out legal trouble."
				},
				new PactSupportPromptEvent
				{
					Pact = pact,
					BossGangId = bossGangId,
					BossName = bossName,
					Title = "Smooth Things Over",
					Body = bossName + " says one of their captains needs a respectable dinner and a few bottles to cool a dispute. Spend $60?",
					AcceptLabel = "Spend $60",
					DeclineLabel = "Skip It",
					Cost = 60,
					HappinessDeltaOnAccept = 0.1f,
					HappinessDeltaOnDecline = -0.03f,
					RelationBuffId = "relbuff-gangs-friends",
					AcceptTickerText = "PACT: You helped " + bossName + " smooth over a dispute.",
					DeclineTickerText = "PACT: You stayed out of " + bossName + "'s dispute."
				},
				new PactSupportPromptEvent
				{
					Pact = pact,
					BossGangId = bossGangId,
					BossName = bossName,
					Title = "Move a Family",
					Body = bossName + " needs $140 to quietly move a family tied to one of their shooters. Will your pact shoulder it?",
					AcceptLabel = "Pay $140",
					DeclineLabel = "Not This Time",
					Cost = 140,
					HappinessDeltaOnAccept = 0.15f,
					HappinessDeltaOnDecline = -0.05f,
					RelationBuffId = "relbuff-gangs-protected",
					AcceptTickerText = "PACT: You helped " + bossName + " relocate a family in trouble.",
					DeclineTickerText = "PACT: You refused to help " + bossName + " move a family out of danger."
				}
			};
			PactSupportPromptEvent prompt = list[SharedRng.Next(list.Count)];
			bool queued = EnqueuePactSideQuest(prompt);
			if (queued)
			{
				_pactSupportLastPromptDayByGang[bossGangId] = nowDay;
				VerificationLog("PepTalkPact", $"prompt-queued gang={bossGangId} boss={bossName} day={nowDay} title={prompt.Title} pending={GetPendingPactSideQuestCount()}");
			}
			return queued;
		}

