		public static void ApplyPatch(Harmony harmony)
		{

			try
			{
				Type type = typeof(GameClock).Assembly.GetType("Game.UI.Session.Crew.CrewManagementPopup");
				if (!(type == null))
				{
					_selectedField = type.GetField("_selected", BindingFlags.Instance | BindingFlags.NonPublic);
					_goField = type.BaseType.GetField("_go", BindingFlags.Instance | BindingFlags.NonPublic);
					Type nestedType = type.GetNestedType("Entry", BindingFlags.NonPublic);
					if (nestedType != null)
					{
						_entryCrewField = nestedType.GetField("crew");
						_entryBuildingField = nestedType.GetField("building");
					}
					MethodInfo method = type.GetMethod("RefreshInfoPanel", BindingFlags.Instance | BindingFlags.NonPublic);
					if (method != null)
					{
						harmony.Patch((MethodBase)method, (HarmonyMethod)null, new HarmonyMethod(typeof(CrewRelationshipHandlerPatch), "RefreshInfoPanelPostfix", (Type[])null), (HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
						Debug.Log("[GameplayTweaks] Crew Relationship Handler initialized");
					}
				}
			}
			catch (Exception arg)
			{
				Debug.LogError($"[GameplayTweaks] CrewRelationshipHandlerPatch failed: {arg}");
			}
		}

		private static Entity GetSelectedPeep()
		{

			if (_popupInstance == null || _selectedField == null || _entryCrewField == null)
			{
				return null;
			}
			object value = _selectedField.GetValue(_popupInstance);
			if (value == null)
			{
				return null;
			}
			object value2 = _entryCrewField.GetValue(value);
			if (value2 == null)
			{
				return null;
			}
			CrewAssignment val = (CrewAssignment)value2;
			if (val.IsDead)
			{
				return null;
			}
			return val.GetPeep();
		}

		private static void RefreshInfoPanelPostfix(object __instance)
		{

			try
			{
				if (_popupInstance != null && !ReferenceEquals(_popupInstance, __instance))
				{
					ForceCloseAllMenus(clearPopupInstance: false);
				}
				_popupInstance = __instance;
				_selectedPeep = GetSelectedPeep();
				EnsureHandlerButtonCreated();
				if (_popupVisible)
				{
					if (_selectedPeep != null)
					{
						RefreshHandlerUI();
					}
					else
					{
						_popupVisible = false;
						if ((UnityEngine.Object)(object)_handlerPopup != (UnityEngine.Object)null)
						{
							_handlerPopup.SetActive(false);
						}
					}
				}
			}
			catch (Exception arg)
			{
				Debug.LogError($"[GameplayTweaks] RefreshInfoPanelPostfix: {arg}");
			}
		}

		private static void EnsureHandlerButtonCreated()
		{
			object obj = _goField?.GetValue(_popupInstance);
			GameObject val = obj as GameObject;
			if ((UnityEngine.Object)(object)val == (UnityEngine.Object)null)
			{
				return;
			}
			Transform val2 = val.transform.Find("Panel/Info/Viewport/Content") ?? val.transform.Find("Info/Viewport/Content");
			if ((UnityEngine.Object)(object)val2 == (UnityEngine.Object)null)
			{
				return;
			}
			CleanupDuplicateMenuButtons(val2);
			_crewRelBtnGo = null;
			_gangPactsBtnGo = null;
			_myPactBtnGo = null;
			_grapevineBtnGo = null;
			_safeboxBtnGo = null;
			if (!_navSuppressionLogged)
			{
				_navSuppressionLogged = true;
				VerificationLog("CrewInfoButtons", "crew-management nav suppression active");
			}
		}

		private static void ApplyCrewManagementNavButtonTheme(GameObject buttonGo, Text providedText, Color textColor, Color? baseColor = null)
		{
			if ((UnityEngine.Object)(object)buttonGo == (UnityEngine.Object)null)
			{
				return;
			}
			Color valueOrDefault = baseColor.GetValueOrDefault(UI_BUTTON_DARK_GRAY);
			float num = Mathf.Clamp01((valueOrDefault.r + valueOrDefault.g + valueOrDefault.b) / 3f);
			float num2 = Mathf.Lerp(0.2f, 0.3f, num);
			valueOrDefault = new Color(num2, num2 + 0.01f, num2 + 0.03f, 0.98f);
			LayoutElement layout = buttonGo.GetComponent<LayoutElement>();
			if ((UnityEngine.Object)(object)layout != (UnityEngine.Object)null)
			{
				layout.minHeight = 34f;
				layout.preferredHeight = 34f;
			}
			Image image = buttonGo.GetComponent<Image>();
			if ((UnityEngine.Object)(object)image != (UnityEngine.Object)null)
			{
				((Graphic)image).color = valueOrDefault;
			}
			Outline outline = buttonGo.GetComponent<Outline>();
			if ((UnityEngine.Object)(object)outline == (UnityEngine.Object)null)
			{
				outline = buttonGo.AddComponent<Outline>();
			}
			((Shadow)outline).effectColor = new Color(0.82f, 0.86f, 0.92f, 0.42f);
			((Shadow)outline).effectDistance = new Vector2(1.2f, -1.2f);
			Text text = providedText ?? buttonGo.GetComponentInChildren<Text>();
			if ((UnityEngine.Object)(object)text != (UnityEngine.Object)null)
			{
				text.font = Resources.GetBuiltinResource<Font>("Arial.ttf");
				text.fontSize = 14;
				text.fontStyle = (FontStyle)1;
				text.supportRichText = false;
				text.resizeTextForBestFit = false;
				text.alignByGeometry = true;
				((Graphic)text).color = textColor;
				Outline textOutline = ((Component)text).GetComponent<Outline>();
				if ((UnityEngine.Object)(object)textOutline == (UnityEngine.Object)null)
				{
					textOutline = ((Component)text).gameObject.AddComponent<Outline>();
				}
				((Shadow)textOutline).effectColor = new Color(0f, 0f, 0f, 0.5f);
				((Shadow)textOutline).effectDistance = new Vector2(1f, -1f);
			}
			Button button = buttonGo.GetComponent<Button>();
			if ((UnityEngine.Object)(object)button != (UnityEngine.Object)null)
			{
				ColorBlock colors = ((Selectable)button).colors;
				colors.normalColor = valueOrDefault;
				colors.highlightedColor = Color.Lerp(valueOrDefault, Color.white, 0.16f);
				colors.pressedColor = Color.Lerp(valueOrDefault, Color.black, 0.24f);
				colors.selectedColor = colors.highlightedColor;
				colors.disabledColor = UI_BUTTON_DARK_GRAY_DISABLED;
				((Selectable)button).colors = colors;
			}
		}

