		private static void CleanupDuplicateMenuButtons(Transform parent)
		{
			DestroyNamedChildren(parent, "BtnCrewRelations");
			DestroyNamedChildren(parent, "BtnGangPacts");
			DestroyNamedChildren(parent, "BtnMyPact");
			DestroyNamedChildren(parent, "BtnGrapevine");
			DestroyNamedChildren(parent, "BtnSafebox");
		}

		private static void DestroyNamedChildren(Transform parent, string childName)
		{
			if ((UnityEngine.Object)(object)parent == (UnityEngine.Object)null || string.IsNullOrEmpty(childName))
			{
				return;
			}
			List<GameObject> list = new List<GameObject>();
			for (int i = 0; i < parent.childCount; i++)
			{
				Transform child = parent.GetChild(i);
				if ((UnityEngine.Object)(object)child != (UnityEngine.Object)null && child.name == childName)
				{
					list.Add(child.gameObject);
				}
			}
			for (int j = 0; j < list.Count; j++)
			{
				UnityEngine.Object.Destroy((UnityEngine.Object)(object)list[j]);
			}
		}

