				object obj = _goField?.GetValue(_popupInstance);
				GameObject val = obj as GameObject;
				if ((UnityEngine.Object)(object)val != (UnityEngine.Object)null)
				{
					return val.transform;
				}
			}
			catch
			{
			}
			Canvas orCreateOverlayCanvas = GetOrCreateOverlayCanvas();
			if ((UnityEngine.Object)(object)orCreateOverlayCanvas != (UnityEngine.Object)null)
			{
				return ((Component)orCreateOverlayCanvas).transform;
			}
			return null;
		}

		private static void ToggleHandlerPopup()
		{
			_popupVisible = !_popupVisible;
			if (_popupVisible)
			{
				_handlerPopup.SetActive(true);
				ForceDockPopupFarLeft(_handlerPopup);
				RefreshHandlerUI();
			}
			else
			{
				ForceCloseAllMenus(clearPopupInstance: false);
			}
		}

		internal static void ToggleCrewRelationsPopup()
		{

			if ((UnityEngine.Object)(object)_handlerPopup == (UnityEngine.Object)null)
			{
				try
				{
					Canvas overlayCanvas = GetOrCreateOverlayCanvas();
					if ((UnityEngine.Object)(object)overlayCanvas == (UnityEngine.Object)null)
					{
						Debug.LogWarning("[GameplayTweaks] Cannot create crew popup - no overlay canvas");
						return;
					}
					CreateHandlerPopup(((Component)overlayCanvas).gameObject);
					Debug.Log("[GameplayTweaks] Created crew relations popup via P key (standalone)");
				}
				catch (Exception ex)
				{
					Debug.LogError("[GameplayTweaks] Failed to create standalone crew popup: " + ex.Message);
					return;
				}
			}
			RefreshCrewList();
			if (_selectedPeep == null && _crewList != null && _crewList.Count > 0)
			{
				CrewAssignment val = _crewList.FirstOrDefault((CrewAssignment c) => c.IsValid);
				if (val.IsValid)
				{
					_selectedPeep = val.GetPeep();
					_currentCrewIndex = 0;
				}
			}
			ToggleHandlerPopup();
		}

		internal static void OpenCrewRelationsForPeep(Entity peep)
		{
			if (peep == null)
			{
				return;
			}
			_selectedPeep = peep;
			RefreshCrewList();
			if (_selectedPeep != null && _crewList != null)
			{
				for (int i = 0; i < _crewList.Count; i++)
				{
					CrewAssignment val = _crewList[i];
					if (!val.IsValid)
					{
						continue;
					}
					Entity peep2 = val.GetPeep();
					if (peep2 != null && peep2.Id == _selectedPeep.Id)
					{
						_currentCrewIndex = i;
						break;
					}
				}
			}
			if ((UnityEngine.Object)(object)_handlerPopup == (UnityEngine.Object)null)
			{
				Transform transform = ResolvePopupParentTransform();
				if ((UnityEngine.Object)(object)transform == (UnityEngine.Object)null)
				{
					Debug.LogWarning("[GameplayTweaks] OpenCrewRelationsForPeep: no popup parent available");
					return;
				}
				CreateHandlerPopup(((Component)transform).gameObject);
			}
			_popupVisible = true;
			if ((UnityEngine.Object)(object)_handlerPopup != (UnityEngine.Object)null)
			{
				_handlerPopup.SetActive(true);
				ForceDockPopupFarLeft(_handlerPopup);
			}
			RefreshHandlerUI();
		}

