			if (peepId.IsNotValid || !_popupVisible || (UnityEngine.Object)(object)_handlerPopup == (UnityEngine.Object)null)
			{
				return;
			}
			if (_selectedPeep != null && _selectedPeep.Id == peepId)
			{
				RefreshHandlerUI();
			}
		}

