		private static void SetStatBarTarget(Image fillImage, ref float target, float value)
		{
			if ((UnityEngine.Object)(object)fillImage == (UnityEngine.Object)null)
			{
				target = -1f;
				return;
			}
			float num = Mathf.Clamp01(value);
			if (target < 0f)
			{
				fillImage.fillAmount = num;
			}
			target = num;
		}

		private static Color GetBarFillColor(float value, Color normalColor, bool warnAt70 = true)
		{
			float num = Mathf.Clamp01(value);
			if (warnAt70 && num <= UI_WARN_THRESHOLD)
			{
				return UI_BAR_WARN_COLOR;
			}
			return normalColor;
		}

		private static void AnimateStatBar(Image fillImage, ref float target, float speed)
		{
			if ((UnityEngine.Object)(object)fillImage == (UnityEngine.Object)null || target < 0f)
			{
				return;
			}
			float maxDelta = Mathf.Max(0.01f, speed * Time.unscaledDeltaTime);
			fillImage.fillAmount = Mathf.MoveTowards(fillImage.fillAmount, target, maxDelta);
		}

		private static AlliancePact ResolveDisplayedMyPact()
		{
			if (SaveData?.Pacts == null)
			{
				return null;
			}
			AlliancePact alliancePact = null;
			if (_activeMyPactColorIndex >= 0)
			{
				alliancePact = SaveData.Pacts.FirstOrDefault((AlliancePact p) => p.ColorIndex == _activeMyPactColorIndex);
			}
			if (alliancePact == null)
			{
				alliancePact = SaveData.Pacts.FirstOrDefault((AlliancePact p) => p.ColorIndex == PLAYER_PACT_SLOT_INDEX);
			}
			if (alliancePact == null && SaveData.PlayerJoinedPactIndex >= 0)
			{
				alliancePact = SaveData.Pacts.FirstOrDefault((AlliancePact p) => p.ColorIndex == SaveData.PlayerJoinedPactIndex);
			}
			if (alliancePact != null)
			{
				_activeMyPactColorIndex = alliancePact.ColorIndex;
			}
			return alliancePact;
		}

		private static void TickMyPactBarAnimations()
		{
			if (!_myPactVisible || (UnityEngine.Object)(object)_myPactPopup == (UnityEngine.Object)null || (UnityEngine.Object)(object)_myPactContent == (UnityEngine.Object)null || _myPactBarBindings.Count == 0)
			{
				return;
			}
			AlliancePact alliancePact = ResolveDisplayedMyPact();
			if (alliancePact == null)
			{
				_myPactBarBindings.Clear();
				return;
			}
			float num = Mathf.Max(0.01f, STAT_BAR_ANIM_SPEED * Time.unscaledDeltaTime);
			float num2 = 0f;
			int num3 = 0;
			bool flag = false;
			for (int num4 = _myPactBarBindings.Count - 1; num4 >= 0; num4--)
			{
				MyPactBarBinding myPactBarBinding = _myPactBarBindings[num4];
				if (myPactBarBinding == null || (UnityEngine.Object)(object)myPactBarBinding.Fill == (UnityEngine.Object)null || (UnityEngine.Object)(object)myPactBarBinding.Label == (UnityEngine.Object)null)
				{
					_myPactBarBindings.RemoveAt(num4);
					continue;
				}
				float bossHappiness = Mathf.Clamp01(alliancePact.GetBossHappiness(myPactBarBinding.GangId));
				myPactBarBinding.Target = bossHappiness;
				myPactBarBinding.Fill.fillAmount = Mathf.MoveTowards(myPactBarBinding.Fill.fillAmount, myPactBarBinding.Target, num);
				((Graphic)myPactBarBinding.Fill).color = GetBarFillColor(bossHappiness, myPactBarBinding.NormalColor, warnAt70: true);
				myPactBarBinding.Label.text = $"Mood: {(int)(bossHappiness * 100f)}%";
				((Graphic)myPactBarBinding.Label).color = (bossHappiness <= UI_WARN_THRESHOLD) ? UI_BAR_WARN_COLOR : new Color(0.72f, 0.85f, 0.72f);
				num2 += bossHappiness;
				num3++;
				if (bossHappiness <= UI_WARN_THRESHOLD)
				{
					flag = true;
				}
			}
			SimTime now = G.GetNow();
			if (now.days != _lastMyPactBarLogDay)
			{
				_lastMyPactBarLogDay = now.days;
				float num5 = (num3 > 0) ? (num2 / (float)num3) : 0f;
				VerificationLog("Bars", $"mypact tick bars={num3} avg={num5:0.000} warn={flag}");
			}
		}

		internal static void TickUiAnimations()
		{
			if (_popupVisible && (UnityEngine.Object)(object)_handlerPopup != (UnityEngine.Object)null)
			{
				AnimateStatBar(_streetCreditFill, ref _streetCreditFillTarget, STAT_BAR_ANIM_SPEED);
				AnimateStatBar(_happinessFill, ref _happinessFillTarget, STAT_BAR_ANIM_SPEED);
				AnimateStatBar(_loyaltyFill, ref _loyaltyFillTarget, STAT_BAR_ANIM_SPEED);
			}
			TickMyPactBarAnimations();
		}

		private static bool ShouldShowHideoutAction(EntityID peepId, CrewModState state)
		{
			if (state == null)
			{
				return false;
			}
			if (state.OnHideout || state.HideoutPending)
			{
				return true;
			}
			SyncLocalHeatFromLegacyFields(state);
			return state.LocalHeatLevel >= WantedLevel.High
				|| state.LocalHeatProgress >= HIDEOUT_ACTION_MIN_HEAT_PROGRESS
				|| state.FedsIncoming
				|| state.FedArrivalCountdown > 0
				|| HasActiveImportantWitnessForCrewAndSource(peepId, NATIONAL_HEAT_SOURCE_COP_KILL);
		}

		private static void SetHideoutRowVisible(bool visible)
		{
			if ((UnityEngine.Object)(object)_hideoutRow != (UnityEngine.Object)null)
			{
				_hideoutRow.SetActive(visible);
				return;
			}
			if ((UnityEngine.Object)(object)_btnHideout != (UnityEngine.Object)null)
			{
				Transform parent = ((Component)_btnHideout).transform.parent;
				if ((UnityEngine.Object)(object)parent != (UnityEngine.Object)null)
				{
					parent.gameObject.SetActive(visible);
				}
				else
				{
					((Component)_btnHideout).gameObject.SetActive(visible);
				}
			}
		}

