			bool flag4 = val2 != null && val2.Id == _selectedPeep.Id;
			if (!flag4 && (_outfitSitDownVisible || ((UnityEngine.Object)(object)_outfitSitDownPopup != (UnityEngine.Object)null && _outfitSitDownPopup.activeSelf)))
			{
