	internal static void ShowDefectionOffer(Entity peep, PlayerInfo fromGang)
	{
		if (peep == null || peep.data?.person == null)
		{
			VerificationLog("Loyalty", "defection-offer-skipped reason=missing-peep");
			return;
		}
		if (_defectionOfferActive)
		{
			VerificationLog("Loyalty", $"defection-offer-skipped peep={peep.Id.id} fromGang={fromGang?.PID.id ?? -1} reason=already-active");
			return;
		}
		int days = G.GetNow().days;
		if (_lastDefectionOfferDay >= 0 && days == _lastDefectionOfferDay)
		{
			VerificationLog("Loyalty", $"defection-offer-skipped peep={peep.Id.id} fromGang={fromGang?.PID.id ?? -1} reason=same-day-throttle day={days}");
			return;
		}
		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (humanPlayer == null || humanPlayer.crew == null || humanPlayer.crew.IsCrewDefeated)
		{
			VerificationLog("Loyalty", $"defection-offer-skipped peep={peep.Id.id} fromGang={fromGang?.PID.id ?? -1} reason=invalid-human-player");
			return;
		}
		Canvas overlay = GetOrCreateOverlayCanvas();
		if ((UnityEngine.Object)(object)overlay == (UnityEngine.Object)null)
		{
			VerificationLog("Loyalty", $"defection-offer-skipped peep={peep.Id.id} fromGang={fromGang?.PID.id ?? -1} reason=missing-overlay");
			return;
		}
		GameObject popup = new GameObject("DefectionOfferPopup", new Type[5]
		{
			typeof(RectTransform),
			typeof(Image),
			typeof(VerticalLayoutGroup),
			typeof(Canvas),
			typeof(GraphicRaycaster)
		});
		popup.transform.SetParent(((Component)overlay).transform, false);
		Canvas popupCanvas = popup.GetComponent<Canvas>();
		popupCanvas.overrideSorting = true;
		popupCanvas.sortingOrder = 1006;
		RectTransform rt = popup.GetComponent<RectTransform>();
		rt.anchorMin = new Vector2(0.5f, 0.6f);
		rt.anchorMax = new Vector2(0.5f, 0.6f);
		rt.pivot = new Vector2(0.5f, 0.5f);
		rt.sizeDelta = ScalePopupSize(420f, 200f);
		ApplyPopupPanelTheme(popup, new Color(0.13f, 0.11f, 0.11f, 0.98f));
		VerticalLayoutGroup layout = popup.GetComponent<VerticalLayoutGroup>();
		((LayoutGroup)layout).padding = new RectOffset(12, 12, 10, 10);
		((HorizontalOrVerticalLayoutGroup)layout).spacing = 6f;
		((HorizontalOrVerticalLayoutGroup)layout).childForceExpandWidth = true;
		((HorizontalOrVerticalLayoutGroup)layout).childForceExpandHeight = false;
		string name = peep.data.person.FullName;
		string fromName = fromGang?.social?.PlayerGroupName ?? "another gang";
		Text title = CreateLabel(popup.transform, "Defect_Title", "Crew Defection Offer", 15, (FontStyle)1);
		title.alignment = (TextAnchor)4;
		((Graphic)title).color = new Color(0.9f, 0.8f, 0.4f);
		Text body = CreateLabel(popup.transform, "Defect_Body", $"{name} from {fromName} wants to defect to your outfit.\n\nDo you want to recruit them?", 12, (FontStyle)0);
		((Graphic)body).color = new Color(0.95f, 0.9f, 0.82f);
		ConfigureWrappedPopupBodyText(body, 68);
		GameObject row = CreateHorizontalRow(popup.transform, "Defect_Row");
		_defectionOfferActive = true;
		_lastDefectionOfferDay = days;
		VerificationLog("Loyalty", $"defection-offer-shown peep={peep.Id.id} fromGang={fromGang?.PID.id ?? -1} day={days}");
		Button acceptBtn = CreateButton(row.transform, "Defect_Accept", "Accept", delegate
		{
			try
			{
				EntityID priorVehicleId = EntityID.INVALID;
				if (fromGang != null && fromGang.crew != null)
				{
					CrewAssignment priorAssignment = fromGang.crew.GetCrewForPeep(peep.Id);
					if (priorAssignment.IsValid && priorAssignment.IsInVehicle)
					{
						priorVehicleId = priorAssignment.VehicleID;
					}
					if (_defectRemoveCrewMethod == null)
					{
						_defectRemoveCrewMethod = typeof(PlayerCrew).GetMethod("RemoveFromCrewCompletely", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					}
					_defectRemoveCrewMethod?.Invoke(fromGang.crew, new object[1] { peep });
					MultiCrewVehicleHelper.HandleCrewDepartureFromGang(fromGang, peep.Id, priorVehicleId, "defection-offer-accepted");
				}
				if (_defectAddToCrewMethod == null)
				{
					_defectAddToCrewMethod = typeof(PlayerCrew).GetMethod("AddToCrew", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				}
				_defectAddToCrewMethod?.Invoke(humanPlayer.crew, new object[2] { peep, null });
				Debug.Log($"[GameplayTweaks] {name} defected from {fromName} to player outfit (accepted).");
			}
			catch (Exception ex)
			{
				Debug.LogError("[GameplayTweaks] Defection accept failed: " + ex.Message);
			}
			popup.SetActive(false);
			_defectionOfferActive = false;
		});
		Button declineBtn = CreateButton(row.transform, "Defect_Decline", "Decline", delegate
		{
			popup.SetActive(false);
			_defectionOfferActive = false;
		});
		((Graphic)((Component)acceptBtn).GetComponent<Image>()).color = new Color(0.3f, 0.6f, 0.3f, 0.94f);
		((Graphic)((Component)declineBtn).GetComponent<Image>()).color = new Color(0.6f, 0.3f, 0.3f, 0.94f);
		RethemeMenuHierarchy(popup);
		popup.SetActive(true);
		ForceDockPopupFarLeft(popup);
		popup.transform.SetAsLastSibling();
	}

		internal static void TickRuntimePrompts()
		{
			if (_lowHappinessPromptPeepId.IsValid && (UnityEngine.Object)(object)_lowHappinessPopup != (UnityEngine.Object)null && _lowHappinessPopup.activeSelf)
			{
				RefreshLowHappinessPromptText();
				ForceDockPopupFarLeft(_lowHappinessPopup);
			}
			if (_crewDeparturePromptPeepId.IsValid && (UnityEngine.Object)(object)_crewDeparturePopup != (UnityEngine.Object)null && _crewDeparturePopup.activeSelf)
			{
				ForceDockPopupFarLeft(_crewDeparturePopup);
			}
		}

		internal static void TryQueueLowHappinessPrompt(Entity peep, CrewModState state, PlayerInfo humanPlayer, SimTime now)
		{
			if (peep?.data?.person == null || state == null || humanPlayer?.crew == null || !humanPlayer.PID.IsHumanPlayer || IsHumanBoss(peep, humanPlayer))
			{
				return;
			}

			long peepKey = (long)peep.Id.id;
			float happiness = Mathf.Clamp01(state.HappinessValue);
			if (happiness > 0.35f)
			{
				_lowHappinessPromptArmedPeepIds.Remove(peepKey);
				return;
			}

			if (happiness > 0.25f)
			{
				return;
			}

			int today = now.days;
			bool armed = _lowHappinessPromptArmedPeepIds.Contains(peepKey);
			int lastPromptDay = _lastLowHappinessPromptDayByPeep.TryGetValue(peepKey, out int cachedDay) ? cachedDay : int.MinValue;
			if (armed && today - lastPromptDay < 7)
			{
				return;
			}
			if (_lastLowHappinessPromptGlobalDay == today)
			{
				return;
			}

			_lowHappinessPromptArmedPeepIds.Add(peepKey);
			_lastLowHappinessPromptDayByPeep[peepKey] = today;
			_lastLowHappinessPromptGlobalDay = today;
			if (!ShowLowHappinessPrompt(peep, state))
			{
				LogGrapevine($"CREW: {peep.data.person.FullName} is unhappy ({Mathf.RoundToInt(happiness * 100f)}% happiness, {Mathf.RoundToInt(Mathf.Clamp01(state.LoyaltyValue) * 100f)}% loyalty). Open Crew Relations.");
			}
		}

