		private static void RefreshLowHappinessPromptText()
		{
			if ((UnityEngine.Object)(object)_lowHappinessText == (UnityEngine.Object)null || !_lowHappinessPromptPeepId.IsValid)
			{
				return;
			}

			Entity peep = _lowHappinessPromptPeepId.FindEntity();
			CrewModState state = peep != null ? GetCrewStateOrNull(peep.Id) : null;
			if (peep?.data?.person == null || state == null)
			{
				_lowHappinessText.text = "A crew member is struggling. Open Crew Relations for details.";
				return;
			}

			_lowHappinessText.text = $"{peep.data.person.FullName} is at risk of leaving.\nHappiness: {Mathf.RoundToInt(Mathf.Clamp01(state.HappinessValue) * 100f)}%\nLoyalty: {Mathf.RoundToInt(Mathf.Clamp01(state.LoyaltyValue) * 100f)}%\nRecommendation: open Crew Relations and stabilize morale.";
		}

