		private static void RefreshGrapevineTabs()
		{
			SetGrapevineTabButtonState(_grapevineAllTabButton, _grapevineTab == 0);
			SetGrapevineTabButtonState(_grapevineCrewTabButton, _grapevineTab == 1);
			SetGrapevineTabButtonState(_grapevinePactTabButton, _grapevineTab == 2);
			SetGrapevineTabButtonState(_grapevineStreetTabButton, _grapevineTab == 3);
		}

		private static void SetGrapevineTabButtonState(Button button, bool active)
		{
			if ((UnityEngine.Object)(object)button == (UnityEngine.Object)null)
			{
				return;
			}
			Image image = ((Component)button).GetComponent<Image>();
			if ((UnityEngine.Object)(object)image != (UnityEngine.Object)null)
			{
				((Graphic)image).color = active ? new Color(0.28f, 0.36f, 0.5f, 0.96f) : UI_BUTTON_DARK_GRAY;
			}
		}

		private static bool IsGrapevineOddJobEvent(string grapevineEvent)
		{
			return !string.IsNullOrWhiteSpace(grapevineEvent)
				&& grapevineEvent.StartsWith("CREW:", StringComparison.OrdinalIgnoreCase)
				&& grapevineEvent.IndexOf("worked an odd job", StringComparison.OrdinalIgnoreCase) >= 0;
		}

		private static bool IsGrapevinePactEvent(string grapevineEvent)
		{
			return !string.IsNullOrWhiteSpace(grapevineEvent)
				&& (grapevineEvent.StartsWith("PACT:", StringComparison.OrdinalIgnoreCase)
					|| grapevineEvent.StartsWith("TALK:", StringComparison.OrdinalIgnoreCase)
					|| grapevineEvent.StartsWith("TRADE:", StringComparison.OrdinalIgnoreCase));
		}

		private static bool IsGrapevineCrewEvent(string grapevineEvent)
		{
			return !string.IsNullOrWhiteSpace(grapevineEvent)
				&& (grapevineEvent.StartsWith("CREW:", StringComparison.OrdinalIgnoreCase)
					|| grapevineEvent.StartsWith("SNITCH:", StringComparison.OrdinalIgnoreCase)
					|| grapevineEvent.StartsWith("FEDS:", StringComparison.OrdinalIgnoreCase)
					|| grapevineEvent.StartsWith("LAW:", StringComparison.OrdinalIgnoreCase));
		}

		private static bool ShouldShowGrapevineEventForActiveTab(string grapevineEvent)
		{
			if (string.IsNullOrWhiteSpace(grapevineEvent))
			{
				return false;
			}
			switch (_grapevineTab)
			{
			case 1:
				return IsGrapevineCrewEvent(grapevineEvent);
			case 2:
				return IsGrapevinePactEvent(grapevineEvent);
			case 3:
				return !IsGrapevineCrewEvent(grapevineEvent) && !IsGrapevinePactEvent(grapevineEvent);
			default:
				return !IsGrapevineOddJobEvent(grapevineEvent);
			}
		}

		private static void RefreshGrapevine()
		{

			if ((UnityEngine.Object)(object)_grapevineContent == (UnityEngine.Object)null)
			{
				return;
			}
			RefreshGrapevineTabs();
			for (int num = _grapevineContent.childCount - 1; num >= 0; num--)
			{
				UnityEngine.Object.Destroy((UnityEngine.Object)(object)((Component)_grapevineContent.GetChild(num)).gameObject);
			}
			List<string> visibleEvents = (SaveData?.GrapevineEvents ?? new List<string>()).Where(ShouldShowGrapevineEventForActiveTab).ToList();
			if (visibleEvents.Count == 0)
			{
				((Graphic)CreateLabel(_grapevineContent, "Empty", _grapevineTab == 0 ? "No news yet. Check back later." : "No news in this section yet.", 12, (FontStyle)2)).color = new Color(0.5f, 0.5f, 0.55f);
				return;
			}
			Color color = default(Color);
			Color color2 = default(Color);
			foreach (string grapevineEvent in visibleEvents)
			{
				GameObject val = new GameObject("GV_Entry", new Type[4]
				{
					typeof(RectTransform),
					typeof(Image),
					typeof(LayoutElement),
					typeof(VerticalLayoutGroup)
				});
				val.transform.SetParent(_grapevineContent, false);
				LayoutElement entryLayout = val.GetComponent<LayoutElement>();
				entryLayout.minHeight = 46f;
				entryLayout.flexibleHeight = 0f;
				VerticalLayoutGroup entryGroup = val.GetComponent<VerticalLayoutGroup>();
				((LayoutGroup)entryGroup).padding = new RectOffset(12, 12, 8, 8);
				((HorizontalOrVerticalLayoutGroup)entryGroup).spacing = 1f;
				((HorizontalOrVerticalLayoutGroup)entryGroup).childControlWidth = true;
				((HorizontalOrVerticalLayoutGroup)entryGroup).childControlHeight = true;
				((HorizontalOrVerticalLayoutGroup)entryGroup).childForceExpandWidth = true;
				((HorizontalOrVerticalLayoutGroup)entryGroup).childForceExpandHeight = false;
				if (grapevineEvent.StartsWith("KILL:") || grapevineEvent.StartsWith("DEATH:"))
				{
					color = new Color(0.18f, 0.1f, 0.1f, 0.9f);
					color2 = new Color(0.9f, 0.6f, 0.6f);
				}
				else if (grapevineEvent.StartsWith("WAR:"))
				{
					color = new Color(0.2f, 0.12f, 0.08f, 0.9f);
					color2 = new Color(0.95f, 0.7f, 0.4f);
				}
				else if (grapevineEvent.StartsWith("PACT:"))
				{
					color = new Color(0.1f, 0.15f, 0.1f, 0.9f);
					color2 = new Color(0.6f, 0.9f, 0.6f);
				}
				else if (grapevineEvent.StartsWith("TALK:") || grapevineEvent.StartsWith("TRADE:"))
				{
					color = new Color(0.1f, 0.13f, 0.16f, 0.9f);
					color2 = new Color(0.65f, 0.82f, 0.95f);
				}
				else if (grapevineEvent.StartsWith("ROBBERY:"))
				{
					color = new Color(0.18f, 0.12f, 0.06f, 0.92f);
					color2 = new Color(0.95f, 0.72f, 0.42f);
				}
				else if (grapevineEvent.StartsWith("FRONT:"))
				{
					color = new Color(0.1f, 0.12f, 0.18f, 0.9f);
					color2 = new Color(0.5f, 0.7f, 0.95f);
				}
				else if (grapevineEvent.StartsWith("FIGHT:"))
				{
					color = new Color(0.18f, 0.1f, 0.1f, 0.9f);
					color2 = new Color(0.95f, 0.55f, 0.45f);
				}
				else if (grapevineEvent.StartsWith("SHOOTOUT:"))
				{
					color = new Color(0.2f, 0.08f, 0.08f, 0.92f);
					color2 = new Color(0.98f, 0.5f, 0.45f);
				}
				else
				{
					color = new Color(0.12f, 0.12f, 0.14f, 0.9f);
					color2 = new Color(0.75f, 0.75f, 0.7f);
				}
				((Graphic)val.GetComponent<Image>()).color = color;
				Outline entryOutline = val.AddComponent<Outline>();
				((Shadow)entryOutline).effectColor = new Color(0f, 0f, 0f, 0.34f);
				((Shadow)entryOutline).effectDistance = new Vector2(1f, -1f);
				// Strip prefix for display, add hanging indent for wrapped text
				string displayText = grapevineEvent;
				int colonIdx = grapevineEvent.IndexOf(':');
				if (colonIdx > 0 && colonIdx < 10)
				{
					string prefix = grapevineEvent.Substring(0, colonIdx + 1);
					string body = grapevineEvent.Substring(colonIdx + 1).TrimStart();
					displayText = prefix + " " + body;
				}
				Text obj = CreateLabel(val.transform, "Text", displayText, 13, (FontStyle)0);
				((Graphic)obj).color = color2;
				obj.horizontalOverflow = (HorizontalWrapMode)0;
				obj.verticalOverflow = (VerticalWrapMode)1;
				obj.lineSpacing = 1.1f;
				Outline textOutline = ((Component)obj).GetComponent<Outline>();
				if ((UnityEngine.Object)(object)textOutline != (UnityEngine.Object)null)
				{
					((Shadow)textOutline).effectColor = new Color(0f, 0f, 0f, 0.32f);
					((Shadow)textOutline).effectDistance = new Vector2(0.6f, -0.6f);
				}
				ContentSizeFitter textFitter = ((Component)obj).gameObject.AddComponent<ContentSizeFitter>();
				textFitter.verticalFit = (ContentSizeFitter.FitMode)2;
				textFitter.horizontalFit = (ContentSizeFitter.FitMode)0;
				LayoutElement textLayout = ((Component)obj).GetComponent<LayoutElement>();
				if (textLayout != null)
				{
					textLayout.minHeight = 0f;
					textLayout.preferredHeight = -1f;
					textLayout.flexibleHeight = 0f;
				}
				ContentSizeFitter entryFitter = val.AddComponent<ContentSizeFitter>();
				entryFitter.verticalFit = (ContentSizeFitter.FitMode)2;
				entryFitter.horizontalFit = (ContentSizeFitter.FitMode)0;
			}
		}

		private sealed class SafeboxEntryInfo
		{
			internal string DisplayName;
			internal Entity Entity;
			internal bool IsSafehouse;
			internal int CleanCash;
			internal int DirtyCash;
		}

		private static void ToggleSafeboxPopup()
		{
			if (GameplayTweaksPlugin.ShouldUseExternalSafeboxUI())
			{
				Debug.Log("[GameplayTweaks] External safebox UI detected - built-in safebox popup disabled.");
				return;
			}
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (!CanUseSafeboxAtSafehouse(humanPlayer, out string lockReason))
			{
				SetSafeboxStatus(lockReason);
				Debug.Log("[GameplayTweaks] Safebox access blocked: " + lockReason);
				return;
			}
			if ((UnityEngine.Object)(object)_safeboxPopup == (UnityEngine.Object)null)
			{
				CreateSafeboxPopup();
			}
			_safeboxVisible = !_safeboxVisible;
			_safeboxPopup.SetActive(_safeboxVisible);
			if (_safeboxVisible)
			{
				ForceDockPopupFarLeft(_safeboxPopup);
				RefreshSafeboxInfo();
			}
		}

