	private static Entity GetHumanSafehouseEntity(PlayerInfo humanPlayer)
	{
		if (humanPlayer == null || humanPlayer.territory == null)
		{
			return null;
			}
			EntityID safehouse = humanPlayer.territory.Safehouse;
			if (safehouse.IsNotValid)
			{
				return null;
		}
		return EntityIDExtensions.FindEntity(safehouse);
	}

	private static bool TryGetSafehouseNode(PlayerInfo humanPlayer, out Node node)
	{
		node = null;
		try
		{
			Entity safehouseEntity = GetHumanSafehouseEntity(humanPlayer);
			NodeID nodeId = safehouseEntity?.data?.board?.bead.nodeId ?? NodeID.INVALID;
			if (!nodeId.IsValid && safehouseEntity != null)
			{
				object board = safehouseEntity.components?.board;
				MethodInfo getNodeId = board?.GetType().GetMethod("GetNodeID", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (getNodeId != null)
				{
					nodeId = (NodeID)getNodeId.Invoke(board, null);
				}
			}
			if (!nodeId.IsValid)
			{
				return false;
			}
			node = nodeId.FindNode();
			return node != null;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryGetSafehouseNode failed: " + ex.Message);
			return false;
		}
	}

	internal static bool IsPeepAtHumanSafehouseCorner(PlayerInfo humanPlayer, Entity peep)
	{
		return GameplayTweaksPlugin.IsHumanPeepAtSafehouseCorner(humanPlayer, peep);
	}

	private static bool CanUseSafeboxAtSafehouse(PlayerInfo humanPlayer, out string reason)
	{
		reason = "Go to your safehouse corner to use the safebox.";
		if (humanPlayer?.crew == null)
		{
			reason = "No player crew found.";
			return false;
		}

		if (!TryGetSafehouseNode(humanPlayer, out Node safehouseNode) || safehouseNode?.id.IsValid != true)
		{
			reason = "No safehouse corner found.";
			return false;
		}

		try
		{
			CrewAssignment boss = humanPlayer.crew.GetCrewForIndex(0);
			Entity bossPeep = boss.IsValid ? boss.GetPeep() : null;
			if (IsPeepAtHumanSafehouseCorner(humanPlayer, bossPeep))
			{
				reason = null;
				return true;
			}
		}
		catch
		{
		}

		return false;
	}

	private static void SetSafeboxStatus(string text)
	{
		if ((UnityEngine.Object)(object)_safeboxStatusText != (UnityEngine.Object)null && !string.IsNullOrWhiteSpace(text))
		{
			_safeboxStatusText.text = text;
		}
	}

		private static int ReadStoredCleanCash(Entity entity)
		{
			if (entity == null)
			{
				return 0;
			}
			try
			{
				InventoryModule inventory = ModulesUtil.GetInventory(entity);
				if (((Module<InventoryModule, InventoryModuleConfig, InventoryModuleData>)(object)inventory)?.data == null)
				{
					return 0;
				}
				try
				{
					FieldInfo field = ((object)((Module<InventoryModule, InventoryModuleConfig, InventoryModuleData>)(object)inventory).data).GetType()
						.GetField("money", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					object value = field?.GetValue(((Module<InventoryModule, InventoryModuleConfig, InventoryModuleData>)(object)inventory).data);
					if (value != null)
					{
						FieldInfo field2 = value.GetType().GetField("cash", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
						if (field2 != null)
						{
							return Math.Max(0, ReadFixnum(field2.GetValue(value)));
						}
					}
				}
				catch
				{
				}
				return Math.Max(0, ReadInventoryAmount(entity, "cash"));
			}
			catch
			{
				return 0;
			}
		}

		private static int RemoveStoredCleanCash(Entity entity, int amount)
		{
			if (entity == null || amount <= 0)
			{
				return 0;
			}
			try
			{
				InventoryModule inventory = ModulesUtil.GetInventory(entity);
				if (((Module<InventoryModule, InventoryModuleConfig, InventoryModuleData>)(object)inventory)?.data == null)
				{
					return 0;
				}
				int available = ReadStoredCleanCash(entity);
				int toTake = Math.Min(available, amount);
				if (toTake <= 0)
				{
					return 0;
				}
				MethodInfo doChangeMoney = ((object)((Module<InventoryModule, InventoryModuleConfig, InventoryModuleData>)(object)inventory).data).GetType()
					.GetMethod("DoChangeMoney", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (doChangeMoney != null)
				{
					doChangeMoney.Invoke(((Module<InventoryModule, InventoryModuleConfig, InventoryModuleData>)(object)inventory).data, new object[2]
					{
						null,
						new Price((Fixnum)(-toTake))
					});
					int removed = Math.Max(0, available - ReadStoredCleanCash(entity));
					if (removed > 0)
					{
						return removed;
					}
				}
				int cashResourceBefore = ReadInventoryAmount(entity, "cash");
				if (cashResourceBefore > 0)
				{
					Label val = default(Label);
					val = new Label("cash");
					inventory.TryRemoveResourcesUpToAll(val, -toTake);
					int removed2 = Math.Max(0, cashResourceBefore - ReadInventoryAmount(entity, "cash"));
					if (removed2 > 0)
					{
						return removed2;
					}
				}
			}
			catch (Exception ex)
			{
				Debug.LogWarning(("[GameplayTweaks] RemoveStoredCleanCash failed: " + ex.Message));
			}
			return 0;
		}

		private static int CollectCleanToWallet(PlayerInfo humanPlayer, Entity source, int requestedAmount)
		{
			if (humanPlayer == null || source == null || requestedAmount <= 0)
			{
				return 0;
			}
			try
			{
				int moved = RemoveStoredCleanCash(source, requestedAmount);
				if (moved > 0)
				{
					humanPlayer.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(moved)), (MoneyReason)1);
				}
				return moved;
			}
			catch
			{
				return 0;
			}
		}

		private static int CollectDirtyToSafehouse(Entity source, Entity safehouseEntity, int requestedAmount)
		{
			if (source == null || safehouseEntity == null || requestedAmount <= 0 || source.Id == safehouseEntity.Id)
			{
				return 0;
			}
			try
			{
				int moved = RemoveDirtyCash(source, requestedAmount);
				if (moved > 0)
				{
					AddDirtyCash(safehouseEntity, moved, "safebox-collect");
				}
				return moved;
			}
			catch
			{
				return 0;
			}
		}

		private static List<SafeboxEntryInfo> BuildSafeboxEntries(PlayerInfo humanPlayer)
		{
			List<SafeboxEntryInfo> entries = new List<SafeboxEntryInfo>();
			if (humanPlayer == null)
			{
				return entries;
			}
			HashSet<EntityID> seen = new HashSet<EntityID>();
			EntityID safehouseId = ((humanPlayer.territory != null) ? humanPlayer.territory.Safehouse : EntityID.INVALID);
			foreach (Entity storageEntity in GetHumanStorageEntitiesForSafebox(humanPlayer))
			{
				if (storageEntity == null)
				{
					continue;
				}
				bool isSafehouse = storageEntity.Id == safehouseId;
				string display = isSafehouse ? "Safehouse" : ("Building: " + (((object)storageEntity).ToString() ?? "Unknown"));
				AddSafeboxEntry(entries, seen, storageEntity, display, isSafehouse);
			}
			try
			{
				PlayerCrew crew = humanPlayer.crew;
				if (crew != null)
				{
					foreach (EntityID item in crew.AllVehicles)
					{
						Entity vehicle = EntityIDExtensions.FindEntity(item);
						if (vehicle != null)
						{
							AddSafeboxEntry(entries, seen, vehicle, "Vehicle: " + (((object)vehicle).ToString() ?? "Unknown"), isSafehouse: false);
						}
					}
					foreach (CrewAssignment item2 in crew.GetLiving())
					{
						Entity peep = item2.GetPeep();
						if (peep != null)
						{
							AddSafeboxEntry(entries, seen, peep, "Crew: " + (((object)peep).ToString() ?? "Unknown"), isSafehouse: false);
						}
					}
				}
			}
			catch
			{
			}
			return entries;
		}

		private static List<Entity> GetHumanStorageEntitiesForSafebox(PlayerInfo humanPlayer)
		{
			List<Entity> storage = new List<Entity>();
			if (humanPlayer == null || humanPlayer.territory == null)
			{
				return storage;
			}
			try
			{
				EntityID safehouseId = humanPlayer.territory.Safehouse;
				if (!safehouseId.IsNotValid)
				{
					Entity safehouse = EntityIDExtensions.FindEntity(safehouseId);
					if (safehouse != null)
					{
						storage.Add(safehouse);
					}
				}
				FieldInfo bldgField = humanPlayer.territory.GetType().GetField("_buildings", BindingFlags.Instance | BindingFlags.NonPublic)
					?? humanPlayer.territory.GetType().GetField("buildings", BindingFlags.Instance | BindingFlags.NonPublic);
				PropertyInfo bldgProp = humanPlayer.territory.GetType().GetProperty("OwnedBuildings", BindingFlags.Instance | BindingFlags.Public)
					?? humanPlayer.territory.GetType().GetProperty("Buildings", BindingFlags.Instance | BindingFlags.Public);
				object bldgList = bldgField?.GetValue(humanPlayer.territory) ?? bldgProp?.GetValue(humanPlayer.territory);
				if (bldgList is IEnumerable<EntityID> buildings)
				{
					foreach (EntityID bldgId in buildings)
					{
						if (bldgId.IsNotValid || bldgId == safehouseId)
						{
							continue;
						}
						Entity bldgEntity = EntityIDExtensions.FindEntity(bldgId);
						if (bldgEntity != null)
						{
							storage.Add(bldgEntity);
						}
					}
				}
			}
			catch
			{
			}
			return storage;
		}

		private static void AddSafeboxEntry(List<SafeboxEntryInfo> entries, HashSet<EntityID> seen, Entity entity, string displayName, bool isSafehouse)
		{
			if (entity == null || entity.Id.IsNotValid || !seen.Add(entity.Id))
			{
				return;
			}
			entries.Add(new SafeboxEntryInfo
			{
				DisplayName = displayName,
				Entity = entity,
				IsSafehouse = isSafehouse,
				CleanCash = ReadStoredCleanCash(entity),
				DirtyCash = ReadInventoryAmount(entity, ModConstants.DIRTY_CASH_LABEL)
			});
		}

		private static void RefreshSafeboxInfo()
		{

			try
			{
				PlayerInfo humanPlayer = G.GetHumanPlayer();
				if (humanPlayer == null)
				{
					return;
				}
				List<SafeboxEntryInfo> list = BuildSafeboxEntries(humanPlayer);
				int walletClean = GetPlayerCleanCash();
				int storedClean = list.Sum((SafeboxEntryInfo x) => Math.Max(0, x.CleanCash));
				int storedDirty = list.Sum((SafeboxEntryInfo x) => Math.Max(0, x.DirtyCash));
				_safeboxCleanText.text = $"Wallet Clean: ${walletClean} | Stored: ${storedClean}";
				_safeboxDirtyText.text = $"Dirty Stored: ${storedDirty}";
				_safeboxTotalText.text = $"Total Reachable: ${walletClean + storedClean + storedDirty}";
				if ((UnityEngine.Object)(object)_safeboxContent != (UnityEngine.Object)null)
				{
					for (int num = _safeboxContent.childCount - 1; num >= 0; num--)
					{
						UnityEngine.Object.Destroy((UnityEngine.Object)(object)((Component)_safeboxContent.GetChild(num)).gameObject);
					}
				}
				Entity safehouseEntity = GetHumanSafehouseEntity(humanPlayer);
				foreach (SafeboxEntryInfo item in list)
				{
					CreateSafeboxEntry(item, safehouseEntity);
				}
				if (_safeboxContent.childCount == 0)
				{
					((Graphic)CreateLabel(_safeboxContent, "Empty", "No safebox locations found.", 11, (FontStyle)2)).color = new Color(0.5f, 0.5f, 0.5f);
				}
			}
			catch (Exception arg)
			{
				Debug.LogError($"[GameplayTweaks] RefreshSafeboxInfo: {arg}");
			}
		}

