			Text val3 = CreateLabel(val.transform, "Clean", $"C:${Math.Max(0, entry.CleanCash)}", 12, (FontStyle)1);
			MakeTextCrisp(val3, 12, (FontStyle)1, new Color(0.38f, 0.95f, 0.38f));
			val3.alignment = (TextAnchor)5;
			((Component)val3).GetComponent<LayoutElement>().preferredWidth = 92f;
