				int moved = CollectDirtyToSafehouse(entry.Entity, safehouseEntity, Math.Max(0, entry.DirtyCash));
				if ((UnityEngine.Object)(object)_safeboxStatusText != (UnityEngine.Object)null)
				{
					_safeboxStatusText.text = ((moved > 0) ? $"{entry.DisplayName}: moved ${moved} dirty." : $"{entry.DisplayName}: no dirty cash to move.");
				}
