		private static List<PactTradeTargetEntry> BuildPactTradeTargets(AlliancePact pact)
		{
			List<PactTradeTargetEntry> list = new List<PactTradeTargetEntry>();
			if (pact == null || !pact.IsActive)
			{
				return list;
			}
			foreach (int item in GetPactMemberGangIds(pact))
			{
				if (item >= 0)
				{
					PlayerInfo playerById = G.FindPlayerById(item);
					if (playerById != null && !playerById.PID.IsHumanPlayer && playerById.crew != null && !playerById.crew.IsCrewDefeated)
					{
						list.Add(new PactTradeTargetEntry
						{
							Pact = pact,
							GangId = item,
							IsOwnPact = true,
							IsAlliedPact = false
						});
					}
				}
			}
			foreach (AlliancePact interPactAlliancePartner in GetInterPactAlliancePartners(pact))
			{
				foreach (int item2 in GetPactMemberGangIds(interPactAlliancePartner))
				{
					PlayerInfo playerById2 = G.FindPlayerById(item2);
					if (playerById2 != null && !playerById2.PID.IsHumanPlayer && playerById2.crew != null && !playerById2.crew.IsCrewDefeated)
					{
						list.Add(new PactTradeTargetEntry
						{
							Pact = interPactAlliancePartner,
							GangId = item2,
							IsOwnPact = false,
							IsAlliedPact = true
						});
					}
				}
			}
			return list.GroupBy((PactTradeTargetEntry x) => x.GangId).Select((IGrouping<int, PactTradeTargetEntry> g) => g.First()).OrderBy((PactTradeTargetEntry x) => x.IsOwnPact ? 0 : 1).ThenBy((PactTradeTargetEntry x) => GetGangDisplayName(x.GangId)).ToList();
		}

		private static bool TryGetHumanPactTradeCrew(out CrewAssignment crew, out string error)
		{
			crew = default(CrewAssignment);
			error = string.Empty;
			PlayerCrew humanCrew = G.GetHumanCrew();
			if (humanCrew == null)
			{
				error = "No crew available.";
				return false;
			}
			try
			{
				foreach (CrewAssignment item in humanCrew.GetLiving())
				{
					if (item.IsValid && item.peepId.IsValid)
					{
						crew = item;
						return true;
					}
				}
			}
			catch
			{
			}
			crew = humanCrew.GetCrewForIndex(0);
			if (crew.IsValid && crew.peepId.IsValid)
			{
				return true;
			}
			error = "No living crew available.";
			return false;
		}

		private static string ResolvePactLoanConvoState(PlayerInfo humanPlayer, PlayerInfo targetGang)
		{
			if (humanPlayer != null && targetGang != null && (RelationshipHasBuff(targetGang, humanPlayer, "relbuff-gangs-loan-unpaid") || RelationshipHasBuff(humanPlayer, targetGang, "relbuff-gangs-loan-unpaid")))
			{
				return "gang-trade-loan-payback";
			}
			return "gang-trade-loan-offer";
		}

		private static bool TryBuildGangConversationVisitState(PlayerInfo targetGang, out VisitState visitState, out string error)
		{
			visitState = null;
			error = string.Empty;
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (humanPlayer == null || targetGang == null || targetGang.social == null)
			{
				error = "Missing gang target.";
				return false;
			}
			if (!TryGetHumanPactTradeCrew(out CrewAssignment crewAssignment, out error))
			{
				return false;
			}
			EntityID crewPeepForPlayer = GetCrewPeepForPlayer(targetGang);
			Entity entity = crewPeepForPlayer.IsValid ? crewPeepForPlayer.FindEntity() : null;
			if (entity == null)
			{
				error = "Target boss not found.";
				return false;
			}
			visitState = new VisitState(crewAssignment, entity, G.GetNow(), PlayerID.HumanPlayer);
			return true;
		}

		private static bool ShouldUseGangTopLevelStarterForPactTrade(string convoStateLabel)
		{
			if (string.IsNullOrEmpty(convoStateLabel))
			{
				return false;
			}
			switch (convoStateLabel)
			{
			case "gang-leisure":
			case "gang-money-in":
			case "gang-trade-drugs-low":
			case "gang-trade-liquor-low":
			case "gang-trade-loan-offer":
				return true;
			default:
				return false;
			}
		}

		private static bool TryFindGangTopLevelStarterButton(string convoStateLabel, out global::Game.Services.ConvoButtonDef buttonDef, out int buttonIndex)
		{
			buttonDef = null;
			buttonIndex = -1;
			UISettings ui = global::Game.Game.serv?.globals?.ui;
			if (ui?.convos == null)
			{
				return false;
			}
			if (!ui.convos.TryGetValue(new Label("gang-toplevel"), out ConvoStateDef convoStateDef) || convoStateDef?.buttons == null)
			{
				return false;
			}
			Label targetLabel = new Label(convoStateLabel);
			for (int i = 0; i < convoStateDef.buttons.Count; i++)
			{
				global::Game.Services.ConvoButtonDef convoButtonDef = convoStateDef.buttons[i];
				if (convoButtonDef?.next == null || !convoButtonDef.next.@goto.IsSet || convoButtonDef.next.@goto != targetLabel)
				{
					continue;
				}
				buttonDef = convoButtonDef;
				buttonIndex = i;
				return true;
			}
			return false;
		}

		private static bool TryResolvePactTradeConversationState(VisitState visitState, string convoStateLabel, out string resolvedStateLabel, out string error)
		{
			resolvedStateLabel = convoStateLabel;
			error = string.Empty;
			if (visitState == null || !ShouldUseGangTopLevelStarterForPactTrade(convoStateLabel))
			{
				return true;
			}
			if (!TryFindGangTopLevelStarterButton(convoStateLabel, out global::Game.Services.ConvoButtonDef buttonDef, out int buttonIndex))
			{
				return true;
			}
			var convoButton = new global::Game.UI.Session.Convo.ConvoButton(buttonIndex, buttonDef, null);
			if (!convoButton.IsVisible(visitState) || !convoButton.IsEnabled(visitState))
			{
				error = "That option is not available from the starting conversation right now.";
				return false;
			}
			Label? nextState = convoButton.state.def.next?.Evaluate(visitState, convoButton.state);
			if (!nextState.HasValue || nextState.Value.IsNotSet)
			{
				error = "Starting conversation route could not be resolved.";
				return false;
			}
			resolvedStateLabel = nextState.Value.ToString();
			return true;
		}

		private static bool TryStartPactTradeConversation(PlayerInfo targetGang, string convoStateLabel, string actionLabel, out string error)
		{
			error = string.Empty;
			EnsureGangTradeConvoStateFixes("pact-trade-launch");
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (!TryBuildGangConversationVisitState(targetGang, out VisitState visitState, out error))
			{
				return false;
			}
			if (!TryResolvePactTradeConversationState(visitState, convoStateLabel, out string resolvedStateLabel, out error))
			{
				return false;
			}
			try
			{
				CloseBossOnlyMenusIfOpen();
				ForceCloseAllMenus(clearPopupInstance: false);
				global::Game.Game.ctx?.hud?.convoDialog?.Controller?.SpecialStartConvoHelper(new Label(resolvedStateLabel), visitState, targetGang, global::Game.UI.Session.Convo.ConversationModel.Source.Peep, requireCrew: false, null);
				LogGrapevine($"PACT: {humanPlayer.social?.PlayerGroupName ?? "Your outfit"} opened {actionLabel} talks with {targetGang.social?.PlayerGroupName ?? ("Gang#" + targetGang.PID.id)}.");
				return true;
			}
			catch (Exception ex)
			{
				error = ex.Message;
				return false;
			}
		}

