		private static void OpenPactTradePopup(AlliancePact pact)
		{
			if ((UnityEngine.Object)(object)_pactTradePopup == (UnityEngine.Object)null)
			{
				CreatePactTradePopup();
			}
			if ((UnityEngine.Object)(object)_pactTradePopup == (UnityEngine.Object)null)
			{
				return;
			}
			_pactTradeVisible = true;
			_pactTradePopup.SetActive(true);
			ForceDockPopupFarLeft(_pactTradePopup);
			RefreshPactTradePopup(pact);
		}

