		private static void OnGiftPactBoss(AlliancePact pact, int bossGangId, string bossName)
		{
			try
			{
				PlayerInfo humanPlayer = G.GetHumanPlayer();
				if (humanPlayer == null || pact == null || bossGangId < 0)
				{
					return;
				}
				int giftCost = 50;
				if (!humanPlayer.finances.CanChangeMoneyOnSafehouse(new Price((Fixnum)(-giftCost))))
				{
					Debug.Log("[GameplayTweaks] Not enough cash for pact boss gift");
					return;
				}
				humanPlayer.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(-giftCost)), (MoneyReason)1);
				float before = pact.GetBossHappiness(bossGangId);
				float after = Mathf.Clamp01(before + 0.2f);
				pact.SetBossHappiness(bossGangId, after);
				LogGrapevine($"PACT: Gift sent to {bossName} (${giftCost}) - mood {((int)(before * 100f))}% -> {((int)(after * 100f))}%");
				RefreshMyPactInfo();
			}
			catch (Exception ex)
			{
				Debug.LogWarning($"[GameplayTweaks] OnGiftPactBoss failed: {ex.Message}");
			}
		}

		private static int GetPactPepTalksRemaining(int bossGangId)
		{
			int nowDay = G.GetNow().days;
			if (_pactPepTalkWeekStartDay < 0 || nowDay - _pactPepTalkWeekStartDay >= 7)
			{
				_pactPepTalkWeekStartDay = nowDay;
				_pactPepTalkUses.Clear();
			}
			_pactPepTalkUses.TryGetValue(bossGangId, out int used);
			return Math.Max(0, 1 - used);
		}

		private static bool TryConsumePactPepTalk(int bossGangId, string source)
		{
			int remaining = GetPactPepTalksRemaining(bossGangId);
			if (remaining <= 0)
			{
				VerificationLog("PepTalkPact", $"consume-blocked gang={bossGangId} day={G.GetNow().days} source={source ?? "unknown"} reason=no-uses");
				return false;
			}
			_pactPepTalkUses.TryGetValue(bossGangId, out int used);
			_pactPepTalkUses[bossGangId] = used + 1;
			VerificationLog("PepTalkPact", $"consume gang={bossGangId} day={G.GetNow().days} source={source ?? "unknown"} used={_pactPepTalkUses[bossGangId]}");
			return true;
		}

		private static string FormatSignedRelationText(int relationScore)
		{
			if (relationScore > 0)
			{
				return "+" + relationScore.ToString(CultureInfo.InvariantCulture);
			}
			return relationScore.ToString(CultureInfo.InvariantCulture);
		}

		private static bool TryShowPactSupportPrompt(AlliancePact pact, int bossGangId, string bossName)
		{
			if (pact == null || bossGangId < 0)
			{
				VerificationLog("PepTalkPact", $"prompt-skip gang={bossGangId} boss={bossName ?? "Unknown"} reason=invalid-pact");
				return false;
			}
			int nowDay = G.GetNow().days;
			if (_pactSupportLastPromptDayByGang.TryGetValue(bossGangId, out int lastPromptDay) && nowDay - lastPromptDay < 10)
			{
				VerificationLog("PepTalkPact", $"prompt-skip gang={bossGangId} boss={bossName} day={nowDay} reason=cooldown lastDay={lastPromptDay}");
				return false;
			}
			if (SharedRng.NextDouble() >= 0.45)
			{
				VerificationLog("PepTalkPact", $"prompt-skip gang={bossGangId} boss={bossName} day={nowDay} reason=chance");
				return false;
			}
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			PlayerInfo bossGang = G.FindPlayerById(bossGangId);
			if (humanPlayer == null || bossGang == null)
			{
				VerificationLog("PepTalkPact", $"prompt-skip gang={bossGangId} boss={bossName} day={nowDay} reason=missing-player");
				return false;
			}
			List<PactSupportPromptEvent> list = new List<PactSupportPromptEvent>
			{
				new PactSupportPromptEvent
				{
					Pact = pact,
					BossGangId = bossGangId,
					BossName = bossName,
					Title = "Pact Favor",
					Body = bossName + " says payroll is running short after a rough week. Cover $75 so their people stay quiet?",
					AcceptLabel = "Cover $75",
					DeclineLabel = "Not Now",
					Cost = 75,
					HappinessDeltaOnAccept = 0.12f,
					HappinessDeltaOnDecline = -0.04f,
