					AcceptTickerText = "PACT: You floated payroll money to " + bossName + ".",
					DeclineTickerText = "PACT: You turned down " + bossName + "'s payroll ask."
				},
				new PactSupportPromptEvent
				{
					Pact = pact,
					BossGangId = bossGangId,
					BossName = bossName,
					Title = "Pact Favor",
					Body = bossName + " has trouble at home and needs $60 to keep things calm. Do you help?",
					AcceptLabel = "Help for $60",
					DeclineLabel = "Pass",
					Cost = 60,
					HappinessDeltaOnAccept = 0.1f,
					HappinessDeltaOnDecline = -0.03f,
					RelationBuffId = "relbuff-pact-support-cash",
					AcceptTickerText = "PACT: You quietly helped " + bossName + " handle things at home.",
					DeclineTickerText = "PACT: " + bossName + " did not get the help they asked for."
				},
				new PactSupportPromptEvent
				{
					Pact = pact,
					BossGangId = bossGangId,
					BossName = bossName,
					Title = "Trade Introduction",
					Body = bossName + " knows a driver with steady hands and a truck. Pay $150 to bring them into the fold for future trade runs?",
					AcceptLabel = "Bring Them In",
					DeclineLabel = "Leave It",
					Cost = 150,
					HappinessDeltaOnAccept = 0.08f,
					HappinessDeltaOnDecline = -0.01f,
					RelationBuffId = "relbuff-pact-support-intro",
					AcceptTickerText = "PACT: " + bossName + " now owes you for backing a trade runner.",
					DeclineTickerText = "PACT: You passed on " + bossName + "'s trade-runner introduction."
				},
				new PactSupportPromptEvent
				{
					Pact = pact,
					BossGangId = bossGangId,
					BossName = bossName,
					Title = "New Muscle",
					Body = bossName + " has a pal who wants in and knows how to work. Front $200 to vouch for the hire?",
					AcceptLabel = "Front $200",
					DeclineLabel = "Decline",
					Cost = 200,
					HappinessDeltaOnAccept = 0.14f,
					HappinessDeltaOnDecline = -0.02f,
					RelationBuffId = "relbuff-pact-support-intro",
					AcceptTickerText = "PACT: You backed " + bossName + "'s new hire and earned some trust.",
					DeclineTickerText = "PACT: You declined to back " + bossName + "'s new hire."
				}
			};
			if (list.Count == 0)
			{
				return false;
			}
			PactSupportPromptEvent pactSupportPromptEvent = list[SharedRng.Next(list.Count)];
			Canvas orCreateOverlayCanvas = GetOrCreateOverlayCanvas();
			if ((UnityEngine.Object)(object)orCreateOverlayCanvas == (UnityEngine.Object)null)
			{
				return false;
			}
			if ((UnityEngine.Object)(object)_pactSupportPopup == (UnityEngine.Object)null)
			{
				_pactSupportPopup = new GameObject("PactSupportPopup", new Type[5]
				{
					typeof(RectTransform),
					typeof(Image),
					typeof(VerticalLayoutGroup),
					typeof(Canvas),
