		private static string GetPactHappinessText(AlliancePact pact)
		{
			if (pact == null || pact.BossHappiness.Count == 0) return "";
			List<PlayerInfo> allPlayers = G.GetAllPlayers().ToList();
			StringBuilder sb = new StringBuilder();
			List<int> allMembers = new List<int>();
			if (pact.LeaderGangId >= 0) allMembers.Add(pact.LeaderGangId);
			allMembers.AddRange(pact.MemberIds);
			allMembers = allMembers.Distinct().ToList();
			foreach (int memberId in allMembers)
			{
				PlayerInfo member = allPlayers.FirstOrDefault(p => p.PID.id == memberId);
				if (member == null || member.IsHuman) continue;
				float hap = pact.GetBossHappiness(memberId);
				string gangName = member.social?.PlayerGroupName ?? $"Gang#{memberId}";
				if (sb.Length > 0) sb.Append(" | ");
				sb.Append($"{gangName} mood {(int)(hap * 100f)}%");
			}
			return sb.ToString();
		}

		private static void RefreshPactSlots()
		{

			NormalizePactSlots();
			int num = PLAYER_PACT_SLOT_INDEX;
			bool flag = SaveData.PlayerJoinedPactIndex >= 0;
			SimTime now = G.GetNow();
			int maxAIPacts = GetUnlockedAIPactSlots(now);
			PlayerInfo selectedEditorGang = _pactEditorMode ? GetSelectedPactEditorGang() : null;
			AlliancePact selectedEditorGangPact = (selectedEditorGang != null) ? GetPactForPlayer(selectedEditorGang.PID) : null;
			int i;
			for (i = 0; i < TOTAL_PACT_SLOT_COUNT; i++)
			{
				if ((UnityEngine.Object)(object)_pactSlotRows[i] == (UnityEngine.Object)null)
				{
					continue;
				}
				AlliancePact alliancePact = SaveData.Pacts.FirstOrDefault((AlliancePact p) => p.ColorIndex == i);
				bool flag2 = _selectedPactSlot == i;
				bool isLocked = i < num && i >= maxAIPacts && alliancePact == null;
				// Show all slots (including locked) instead of hiding them
				_pactSlotRows[i].SetActive(true);
				if (isLocked)
				{
					int daysUntilUnlock = Math.Max(0, GetOrInitPactEpochDay(now) + i * PACT_UNLOCK_INTERVAL_DAYS - now.days);
					float yearsLeft = (float)daysUntilUnlock / 365f;
					_pactSlotNameTexts[i].text = ModConstants.PACT_COLOR_NAMES[i] + " - Locked";
					_pactSlotMemberTexts[i].text = $"Unlocks in ~{yearsLeft:0.0} years";
					((Component)_pactSlotSelectBtns[i]).GetComponentInChildren<Text>().text = "Locked";
					((Component)_pactSlotSelectBtns[i]).GetComponent<Button>().interactable = false;
					((Component)_pactSlotDeleteBtns[i]).gameObject.SetActive(false);
				}
				else if (i == num)
				{
					if (alliancePact != null)
					{
						bool flag3 = alliancePact.MemberIds.Count > 0 || alliancePact.LeaderGangId >= 0;
						_pactSlotNameTexts[i].text = (flag3 ? alliancePact.DisplayName : (alliancePact.DisplayName + " (Need 1 gang)"));
						int num2 = alliancePact.MemberIds.Count + ((alliancePact.LeaderGangId >= 0) ? 1 : 0);
						string hapText = GetPactHappinessText(alliancePact);
						string founderLine = alliancePact.LeaderGangId >= 0 ? ("\nFounder: " + GetGangDisplayName(alliancePact.LeaderGangId)) : "";
						string confirmColorLine = alliancePact.PlayerColorConfirmed ? "" : "\nConfirm color to unlock invites";
						string capLine = $"\nCap: {num2}/{PACT_MAX_TOTAL_GANGS} gangs";
						_pactSlotMemberTexts[i].text = $"{num2} gang(s) | {(int)(GetEffectivePactEarningRate(alliancePact) * 100f)}% | +{GetEffectivePactCrewCapacityBonus(alliancePact)}crew" +
							capLine +
							confirmColorLine +
							founderLine +
							(hapText.Length > 0 ? $"\n{hapText}" : "");
						((Component)_pactSlotSelectBtns[i]).GetComponentInChildren<Text>().text = (flag2 ? "Active" : "Select");
						((Component)_pactSlotSelectBtns[i]).GetComponent<Button>().interactable = true;
						((Component)_pactSlotDeleteBtns[i]).gameObject.SetActive(true);
					}
					else
					{
						_pactSlotNameTexts[i].text = "Your Pact - Awaiting First Ally";
						_pactSlotMemberTexts[i].text = IsPlayerPactColorReady()
							? "Color locked in. Add one gang to form it."
							: $"{24}T+{2}SC | Choose imported color first, then confirm";
						((Component)_pactSlotSelectBtns[i]).GetComponentInChildren<Text>().text = "Select";
						((Component)_pactSlotSelectBtns[i]).GetComponent<Button>().interactable = true;
						((Component)_pactSlotDeleteBtns[i]).gameObject.SetActive(false);
					}
				}
				else if (alliancePact != null)
				{
					_pactSlotNameTexts[i].text = alliancePact.DisplayName;
					int num3 = alliancePact.MemberIds.Count + ((alliancePact.LeaderGangId >= 0) ? 1 : 0);
					string hapText2 = (SaveData.PlayerJoinedPactIndex == i) ? GetPactHappinessText(alliancePact) : "";
					string founderLine2 = alliancePact.LeaderGangId >= 0 ? ("\nFounder: " + GetGangDisplayName(alliancePact.LeaderGangId)) : "";
					string capLine2 = $"\nCap: {num3}/{PACT_MAX_TOTAL_GANGS} gangs";
						_pactSlotMemberTexts[i].text = $"{num3} gang(s) | {(int)(GetEffectivePactEarningRate(alliancePact) * 100f)}% | +{GetEffectivePactCrewCapacityBonus(alliancePact)}crew" +
						capLine2 +
						founderLine2 +
						(hapText2.Length > 0 ? $"\n{hapText2}" : "");
					bool canJoinPact = SaveData.PlayerJoinedPactIndex == i || !IsPactAtMemberCap(alliancePact);
					((Component)_pactSlotSelectBtns[i]).GetComponent<Button>().interactable = _pactEditorMode || canJoinPact;
					if (_pactEditorMode)
					{
						((Component)_pactSlotSelectBtns[i]).GetComponentInChildren<Text>().text = (flag2 ? "Active" : "Select");
					}
					else if (SaveData.PlayerJoinedPactIndex == i)
					{
						((Component)_pactSlotSelectBtns[i]).GetComponentInChildren<Text>().text = "Joined";
					}
					else
					{
						SaveData.PactJoinCooldowns.TryGetValue(i, out var value);
						bool flag4 = ((value > 0) ? (now.days - value) : 9999) >= 180;
						((Component)_pactSlotSelectBtns[i]).GetComponentInChildren<Text>().text = !canJoinPact ? "Full" : (flag4 ? "Join" : "Wait");
					}
					((Component)_pactSlotDeleteBtns[i]).gameObject.SetActive(_pactEditorMode);
