				else
				{
					_pactSlotNameTexts[i].text = ModConstants.PACT_COLOR_NAMES[i] + " - Empty";
					_pactSlotMemberTexts[i].text = "";
					((Component)_pactSlotSelectBtns[i]).GetComponentInChildren<Text>().text = (_pactEditorMode ? "Create" : "--");
					((Component)_pactSlotSelectBtns[i]).GetComponent<Button>().interactable = _pactEditorMode;
					((Component)_pactSlotDeleteBtns[i]).gameObject.SetActive(false);
				}
				if (_pactEditorMode && !isLocked)
				{
					Button slotButton = _pactSlotSelectBtns[i];
					Text slotButtonText = ((Component)slotButton).GetComponentInChildren<Text>();
					bool selectedGangInThisPact = selectedEditorGangPact != null && selectedEditorGangPact.ColorIndex == i;
					bool selectedGangInOtherPact = selectedEditorGangPact != null && selectedEditorGangPact.ColorIndex != i;
					bool canUsePlayerSlotForSelectedGang = selectedEditorGang != null && !(i == PLAYER_PACT_SLOT_INDEX && selectedEditorGang.PID.IsHumanPlayer);
					bool slotHasCapacity = alliancePact == null || CanGangJoinPact(alliancePact, selectedEditorGang?.PID.id ?? -1);
					if (selectedEditorGang == null)
					{
						slotButtonText.text = "Pick Gang";
						((Selectable)slotButton).interactable = false;
					}
					else if (selectedGangInThisPact)
					{
						slotButtonText.text = "Member";
						((Selectable)slotButton).interactable = false;
					}
					else if (selectedGangInOtherPact)
					{
						slotButtonText.text = "In Pact";
						((Selectable)slotButton).interactable = false;
					}
					else if (!canUsePlayerSlotForSelectedGang)
					{
						slotButtonText.text = "Pick Ally";
						((Selectable)slotButton).interactable = false;
					}
					else if (i == PLAYER_PACT_SLOT_INDEX && !IsPlayerPactColorReady())
					{
						slotButtonText.text = "Color";
						((Selectable)slotButton).interactable = true;
					}
					else if (alliancePact == null)
					{
						slotButtonText.text = "Create";
						((Selectable)slotButton).interactable = true;
					}
					else if (!slotHasCapacity)
					{
						slotButtonText.text = "Full";
						((Selectable)slotButton).interactable = false;
					}
					else
					{
						slotButtonText.text = "Assign";
						((Selectable)slotButton).interactable = true;
					}
				}
				bool flag5 = flag2 || (SaveData.PlayerJoinedPactIndex == i && !_pactEditorMode);
				((Graphic)_pactSlotRows[i].GetComponent<Image>()).color = isLocked
					? new Color(0.1f, 0.1f, 0.1f, 0.6f)
					: (flag5 ? new Color(0.25f, 0.2f, 0.15f, 0.95f) : new Color(0.16f, 0.14f, 0.1f, 0.9f));
				Color swatchColor = (alliancePact != null) ? alliancePact.SharedColor : (i == PLAYER_PACT_SLOT_INDEX ? _playerPactColor : ModConstants.PACT_COLORS[i]);
				((Graphic)_pactSlotColorSwatches[i]).color = isLocked ? new Color(0.3f, 0.3f, 0.3f, 0.5f) : swatchColor;
			}
			AlliancePact playerPact = SaveData.Pacts.FirstOrDefault((AlliancePact p) => p.ColorIndex == PLAYER_PACT_SLOT_INDEX);
			bool showColorPicker = (_selectedPactSlot == PLAYER_PACT_SLOT_INDEX || SaveData.PlayerJoinedPactIndex == PLAYER_PACT_SLOT_INDEX) &&
				((playerPact == null && IsPendingPlayerPactSelectionActive()) || (playerPact != null && !playerPact.PlayerColorConfirmed));
			if ((UnityEngine.Object)(object)_colorPickerRow != (UnityEngine.Object)null)
			{
				_colorPickerRow.SetActive(showColorPicker);
			}
			RefreshColorPickerConfirmUi();
			if (_pactEditorMode && selectedEditorGang != null)
			{
				if (selectedEditorGangPact != null)
