				}
				else if (_selectedPactSlot == PLAYER_PACT_SLOT_INDEX && !IsPlayerPactColorReady())
				{
					_selectedPactLabel.text = "Selected gang: " + GetPactEditorGangName(selectedEditorGang) + " | Choose and confirm Your Pact color.";
