				}
			}
			else if (_pactEditorMode)
			{
				_selectedPactLabel.text = "Select a gang below, then choose that gang's pact color above.";
				((Graphic)_selectedPactLabel).color = new Color(0.7f, 0.7f, 0.6f);
			}
			else if (flag && SaveData.PlayerPactId >= 0 && SaveData.PlayerJoinedPactIndex == PLAYER_PACT_SLOT_INDEX)
			{
				AlliancePact alliancePact2 = SaveData.Pacts.FirstOrDefault((AlliancePact p) => p.ColorIndex == SaveData.PlayerJoinedPactIndex);
				_selectedPactLabel.text = "Leader of: " + (alliancePact2?.DisplayName ?? "Your Pact");
				Color leaderColor = (alliancePact2 != null) ? alliancePact2.SharedColor : _playerPactColor;
