		private static bool IsPendingPlayerPactSelectionActive()
		{
			return _selectedPactSlot == PLAYER_PACT_SLOT_INDEX && SaveData.Pacts.All((AlliancePact p) => p.ColorIndex != PLAYER_PACT_SLOT_INDEX);
		}

		private static bool IsPlayerPresetColorAvailable(int presetIndex)
		{
			if (presetIndex < 0 || presetIndex >= ModConstants.PLAYER_PACT_PRESET_COLORS.Length)
			{
				return false;
			}
			Color presetColor = ModConstants.PLAYER_PACT_PRESET_COLORS[presetIndex];
			foreach (AlliancePact pact in SaveData.Pacts)
			{
				if (pact == null || pact.ColorIndex == PLAYER_PACT_SLOT_INDEX)
				{
					continue;
				}
				if (ApproximatelySameColor(pact.SharedColor, presetColor) || ApproximatelySameColor(ModConstants.PACT_COLORS[Mathf.Clamp(pact.ColorIndex, 0, AI_PACT_SLOT_COUNT - 1)], presetColor))
				{
					return false;
				}
			}
			return true;
		}

		private static bool ApproximatelySameColor(Color a, Color b)
		{
			return Mathf.Abs(a.r - b.r) < 0.01f && Mathf.Abs(a.g - b.g) < 0.01f && Mathf.Abs(a.b - b.b) < 0.01f;
		}

		private static bool IsPlayerPactColorReady()
		{
			AlliancePact playerPact = SaveData.Pacts.FirstOrDefault((AlliancePact p) => p.ColorIndex == PLAYER_PACT_SLOT_INDEX);
			if (playerPact != null)
			{
				return playerPact.PlayerColorConfirmed;
			}
			return _pendingPlayerPactColorConfirmed;
		}

		private static bool PreparePendingPlayerPactSelection(bool openColorPicker, string successMessage = null)
		{
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (humanPlayer == null)
			{
				return false;
			}
			int territoryCount = 0;
			int streetCreditLevel = 0;
			if (!_pactEditorMode)
			{
				try
				{
					PlayerTerritory territory = humanPlayer.territory;
					if (territory != null)
					{
						territoryCount = territory.OwnedNodeCount;
					}
				}
				catch
				{
				}
				try
				{
					CrewAssignment crewForIndex = humanPlayer.crew.GetCrewForIndex(0);
					if (crewForIndex.IsValid)
					{
						Entity peep = crewForIndex.GetPeep();
						if (peep != null)
						{
							CrewModState crewStateOrNull = GetCrewStateOrNull(peep.Id);
							if (crewStateOrNull != null)
							{
								streetCreditLevel = crewStateOrNull.StreetCreditLevel;
							}
						}
					}
				}
				catch
				{
				}
				if (territoryCount < ModConstants.PLAYER_PACT_TERRITORY_COST || streetCreditLevel < ModConstants.PLAYER_PACT_SC_COST)
				{
					if ((UnityEngine.Object)(object)_selectedPactLabel != (UnityEngine.Object)null)
					{
						_selectedPactLabel.text = $"Need {ModConstants.PLAYER_PACT_TERRITORY_COST} territories (have {territoryCount}) and {ModConstants.PLAYER_PACT_SC_COST} SC levels (have {streetCreditLevel})!";
						((Graphic)_selectedPactLabel).color = new Color(0.9f, 0.3f, 0.3f);
					}
					return false;
				}
			}
			_selectedPactSlot = PLAYER_PACT_SLOT_INDEX;
			if (_playerPactPresetIndex < 0 || _playerPactPresetIndex >= ModConstants.PLAYER_PACT_PRESET_COLORS.Length)
			{
				_playerPactPresetIndex = 0;
			}
			if (!IsPlayerPresetColorAvailable(_playerPactPresetIndex))
			{
				for (int presetIndex = 0; presetIndex < ModConstants.PLAYER_PACT_PRESET_COLORS.Length; presetIndex++)
				{
					if (IsPlayerPresetColorAvailable(presetIndex))
					{
						_playerPactPresetIndex = presetIndex;
						break;
					}
				}
			}
			_playerPactColor = ModConstants.PLAYER_PACT_PRESET_COLORS[_playerPactPresetIndex];
			if (!string.IsNullOrEmpty(successMessage) && (UnityEngine.Object)(object)_selectedPactLabel != (UnityEngine.Object)null)
			{
				_selectedPactLabel.text = successMessage;
				((Graphic)_selectedPactLabel).color = _playerPactColor;
			}
			else if ((UnityEngine.Object)(object)_selectedPactLabel != (UnityEngine.Object)null)
			{
				_selectedPactLabel.text = openColorPicker
					? (_pactEditorMode ? "Choose an imported player color, confirm it, then add one gang." : "Choose a pact hex color, confirm it, then invite a gang.")
					: (_pactEditorMode ? "Your color is set. Add one gang to form the pact." : "Your color is set. Invite a gang to form the pact.");
				((Graphic)_selectedPactLabel).color = _playerPactColor;
			}
			UpdateColorPickerPreview();
			return true;
		}

		private static AlliancePact CreatePlayerPactFromPendingSelection(PlayerInfo humanPlayer, PlayerInfo joinedGang)
		{
			if (humanPlayer == null || !IsPlayerPactColorReady())
			{
				return null;
			}
			if (SaveData.PlayerJoinedPactIndex >= 0 && SaveData.PlayerJoinedPactIndex != PLAYER_PACT_SLOT_INDEX)
			{
				LeaveCurrentAIPact();
			}
			AlliancePact priorPlayerPact = SaveData.Pacts.FirstOrDefault((AlliancePact p) => p.ColorIndex == PLAYER_PACT_SLOT_INDEX);
			if (priorPlayerPact != null)
			{
				SaveData.Pacts.Remove(priorPlayerPact);
			}
			int pactId = SaveData.NextPactId++;
			AlliancePact playerPact = new AlliancePact
			{
				PactId = $"pact_{pactId}",
				PactName = "Your Pact",
				ColorIndex = PLAYER_PACT_SLOT_INDEX,
				LeaderGangId = humanPlayer.PID.id,
				MemberIds = new List<int>(),
				SharedColor = _playerPactColor,
				Formed = G.GetNow(),
				IsPending = false,
				PlayerColorConfirmed = true
			};
			if (joinedGang != null && joinedGang.PID.id != humanPlayer.PID.id)
			{
				playerPact.MemberIds.Add(joinedGang.PID.id);
			}
			SaveData.Pacts.Add(playerPact);
			SaveData.PlayerPactId = pactId;
			SaveData.PlayerJoinedPactIndex = PLAYER_PACT_SLOT_INDEX;
			SaveData.PlayerPactWarStartDay = -1;
			SaveData.PlayerPactWarTargetId = -1;
			_pendingPlayerPactColorConfirmed = false;
			_pendingConversationPactGangId = -1;
			NormalizePactSlots();
			RefreshPactCache();
			TerritoryColorPatch.RefreshAllTerritoryColors();
			if ((UnityEngine.Object)(object)_myPactBtnGo != (UnityEngine.Object)null)
			{
				_myPactBtnGo.SetActive(true);
			}
			return playerPact;
		}

		internal static bool QueueConversationPlayerPactInvite(PlayerInfo gang, string sourceTag)
		{
			if (gang == null || gang.PID.IsHumanPlayer)
			{
				return false;
			}
			if (!PreparePendingPlayerPactSelection(openColorPicker: true, $"Choose a pact color to finalize the deal with {gang.social?.PlayerGroupName ?? ("Gang#" + gang.PID.id)}."))
			{
				return false;
			}
			_pendingConversationPactGangId = gang.PID.id;
			_pendingPlayerPactColorConfirmed = false;
			OpenGangPactsFromExternalUi();
			Debug.Log($"[GameplayTweaks] queued conversation pact invite gang={gang.PID.id} source={sourceTag}");
			return true;
		}

		private static bool TryFinalizePendingConversationPlayerPact()
		{
			if (_pendingConversationPactGangId < 0 || !IsPlayerPactColorReady())
			{
				return false;
			}
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			PlayerInfo gang = G.FindPlayerById(_pendingConversationPactGangId);
			if (humanPlayer == null || gang == null || gang.PID.IsHumanPlayer || GetPactForPlayer(gang.PID) != null)
			{
				_pendingConversationPactGangId = -1;
				return false;
			}
			AlliancePact playerPact = CreatePlayerPactFromPendingSelection(humanPlayer, gang);
			if (playerPact == null)
			{
				return false;
			}
			ApplyPactJoinRelationshipBoost(playerPact, gang.PID.id, gang.social?.PlayerGroupName ?? ("Gang#" + gang.PID.id));
			LogGrapevine($"PACT: {gang.social?.PlayerGroupName ?? ("Gang#" + gang.PID.id)} joined {playerPact.DisplayName}.");
			if ((UnityEngine.Object)(object)_selectedPactLabel != (UnityEngine.Object)null)
			{
				_selectedPactLabel.text = $"{gang.social?.PlayerGroupName ?? ("Gang#" + gang.PID.id)} joined {playerPact.DisplayName}!";
				((Graphic)_selectedPactLabel).color = playerPact.SharedColor;
			}
			RefreshGangPactsList();
			return true;
		}

		internal static void ApplyStreetCreditProgressGain(CrewModState state, PlayerInfo owner, EntityID peepId, float gain, string source)
		{
			if (state == null || owner == null || gain <= 0f)
			{
				return;
			}
			state.StreetCreditProgress = Mathf.Max(0f, state.StreetCreditProgress) + gain;
			ResolveStreetCreditProgressLevelUps(state, owner, peepId, source);
		}

		internal static bool TryAwardCrewStreetCreditProgress(PlayerInfo owner, EntityID peepId, float minGain, float maxGain, string source)
		{
			if (owner == null)
			{
				owner = G.GetHumanPlayer();
			}
			if (owner == null)
			{
				return false;
			}
			if (!peepId.IsValid)
			{
				peepId = GetCrewPeepForPlayer(owner);
			}
			if (!peepId.IsValid)
			{
				return false;
			}

			CrewModState state = GetOrCreateCrewState(peepId);
			if (state == null)
			{
				return false;
			}

			float gain = GetRandomStreetCreditGain(minGain, maxGain);
			if (gain <= 0f)
			{
				return false;
			}

			float progressBefore = Mathf.Clamp01(state.StreetCreditProgress);
			state.StreetCreditProgress = Mathf.Max(0f, state.StreetCreditProgress) + gain;
			int levelsGained = ResolveStreetCreditProgressLevelUps(state, owner, peepId, source);
			VerificationLog("StreetCredit", $"source={source} peep={peepId.id} gain={gain:0.000} progressBefore={progressBefore:0.000} progressAfter={state.StreetCreditProgress:0.000} levels={levelsGained}");
			if (_selectedPeep != null && _selectedPeep.Id == peepId)
			{
				RefreshHandlerUI();
			}
			return true;
		}

