			{
				_colorPickerRText.text = ModConstants.PLAYER_PACT_PRESET_HEX[_playerPactPresetIndex];
			}
			if ((UnityEngine.Object)(object)_colorPickerGText != (UnityEngine.Object)null)
			{
				_colorPickerGText.text = "Imported";
			}
			if ((UnityEngine.Object)(object)_colorPickerBText != (UnityEngine.Object)null)
			{
				_colorPickerBText.text = ModConstants.PLAYER_PACT_PRESET_NAMES[_playerPactPresetIndex];
			}
			if (_pactSlotColorSwatches[PLAYER_PACT_SLOT_INDEX] != null)
			{
				((Graphic)_pactSlotColorSwatches[PLAYER_PACT_SLOT_INDEX]).color = _playerPactColor;
			}
			for (int i = 0; i < _playerPactPresetButtons.Length; i++)
			{
				Button presetButton = _playerPactPresetButtons[i];
				if ((UnityEngine.Object)(object)presetButton != (UnityEngine.Object)null)
