		private static void RequestPactWithGang(PlayerInfo gang, float acceptance, int slotIndex)
		{

			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (humanPlayer == null)
			{
				return;
			}
			AlliancePact alliancePact = SaveData.Pacts.FirstOrDefault((AlliancePact p) => p.ColorIndex == slotIndex);
			bool creatingPlayerPact = slotIndex == PLAYER_PACT_SLOT_INDEX && alliancePact == null;
			if (alliancePact == null && !creatingPlayerPact)
			{
				return;
			}
			if (slotIndex == PLAYER_PACT_SLOT_INDEX && !IsPlayerPactColorReady() && gang.PID.id != humanPlayer.PID.id)
			{
				if ((UnityEngine.Object)(object)_selectedPactLabel != (UnityEngine.Object)null)
				{
					_selectedPactLabel.text = "Confirm your imported pact color before inviting gangs.";
					((Graphic)_selectedPactLabel).color = new Color(0.95f, 0.65f, 0.3f);
				}
				return;
			}
			if (!creatingPlayerPact && !CanGangJoinPact(alliancePact, gang.PID.id))
			{
				if ((UnityEngine.Object)(object)_selectedPactLabel != (UnityEngine.Object)null)
				{
					_selectedPactLabel.text = $"{alliancePact.DisplayName} is already at the {PACT_MAX_TOTAL_GANGS}-gang cap.";
					((Graphic)_selectedPactLabel).color = new Color(0.95f, 0.55f, 0.3f);
				}
				return;
			}
			bool flag = gang.PID == humanPlayer.PID;
			SimTime now = G.GetNow();
			if (!flag && !_pactEditorMode)
			{
				SaveData.PactInviteCooldowns.TryGetValue(gang.PID.id, out var lastInviteDay);
				int daysSinceInvite = (lastInviteDay > 0) ? (now.days - lastInviteDay) : 9999;
				if (daysSinceInvite < ModConstants.PACT_JOIN_COOLDOWN_DAYS)
				{
					int waitDays = ModConstants.PACT_JOIN_COOLDOWN_DAYS - daysSinceInvite;
					if ((UnityEngine.Object)(object)_selectedPactLabel != (UnityEngine.Object)null)
					{
						_selectedPactLabel.text = $"You can ask {gang.social?.PlayerGroupName ?? ("Gang#" + gang.PID.id)} again in {waitDays} days.";
						((Graphic)_selectedPactLabel).color = new Color(0.95f, 0.55f, 0.3f);
					}
					return;
				}
			}
			if (flag || SharedRng.NextDouble() < (double)acceptance)
			{
				if (flag)
				{
					if (SaveData.PlayerJoinedPactIndex >= 0 && SaveData.PlayerJoinedPactIndex != slotIndex)
					{
						Debug.Log("[GameplayTweaks] Player leaving old pact to join new one");
					}
					SaveData.PlayerJoinedPactIndex = slotIndex;
					if (!alliancePact.MemberIds.Contains(gang.PID.id))
					{
						alliancePact.MemberIds.Add(gang.PID.id);
					}
					alliancePact.IsPending = false;
					Debug.Log(("[GameplayTweaks] Human player joined " + alliancePact.DisplayName + " via editor!"));
					LogGrapevine("PACT: Your outfit joined " + alliancePact.DisplayName + "!");
					ApplyPactJoinRelationshipBoost(alliancePact, gang.PID.id, humanPlayer.social?.PlayerGroupName ?? "Your outfit");
					if ((UnityEngine.Object)(object)_myPactBtnGo != (UnityEngine.Object)null)
					{
						_myPactBtnGo.SetActive(true);
					}
					RefreshPactCache();
				}
				else
				{
					if (creatingPlayerPact)
					{
						alliancePact = CreatePlayerPactFromPendingSelection(humanPlayer, gang);
						if (alliancePact == null)
						{
							return;
						}
						LogGrapevine("PACT: Your outfit established a new alliance!");
					}
					else if (alliancePact.LeaderGangId < 0)
					{
						alliancePact.LeaderGangId = gang.PID.id;
					}
					else
					{
						if (gang.PID.id != alliancePact.LeaderGangId && !alliancePact.MemberIds.Contains(gang.PID.id))
						{
							alliancePact.MemberIds.Add(gang.PID.id);
						}
					}
					alliancePact.IsPending = false;
					string[] obj = new string[5] { "[GameplayTweaks] ", null, null, null, null };
					PlayerSocial social = gang.social;
					obj[1] = ((social != null) ? social.PlayerGroupName : null);
					obj[2] = " joined ";
					obj[3] = alliancePact.DisplayName;
					obj[4] = "!";
					Debug.Log(string.Concat(obj));
					ApplyPactJoinRelationshipBoost(alliancePact, gang.PID.id, gang.social?.PlayerGroupName ?? ("Gang#" + gang.PID.id));
				}
				TerritoryColorPatch.RefreshAllTerritoryColors();
			}
			else
			{
				if (!flag && !_pactEditorMode)
				{
					SaveData.PactInviteCooldowns[gang.PID.id] = now.days;
				}
				string[] obj2 = new string[5] { "[GameplayTweaks] ", null, null, null, null };
				PlayerSocial social2 = gang.social;
				obj2[1] = ((social2 != null) ? social2.PlayerGroupName : null);
				obj2[2] = " declined invite to ";
				obj2[3] = alliancePact.DisplayName;
				obj2[4] = ".";
				Debug.Log(string.Concat(obj2));
			}
			RefreshGangPactsList();
		}

		private static void OnHireFamily()
		{
			if ((UnityEngine.Object)(object)_familyHirePopup == (UnityEngine.Object)null && (UnityEngine.Object)(object)_handlerPopup != (UnityEngine.Object)null)
			{
				Transform parentTransform = _handlerPopup.transform.parent;
				if ((UnityEngine.Object)(object)parentTransform != (UnityEngine.Object)null)
				{
					GameObject parent = ((Component)parentTransform).gameObject;
					CreateFamilyHirePopup(parent);
				}
			}
			if (_selectedPeep == null)
			{
				RefreshCrewList();
				if (_crewList != null && _crewList.Count > 0)
				{
					CrewAssignment firstCrew = _crewList.FirstOrDefault((CrewAssignment c) => c.IsValid);
					if (firstCrew.IsValid)
					{
						_selectedPeep = firstCrew.GetPeep();
					}
				}
			}
			ToggleFamilyHirePopup();
		}

		private static void ToggleFamilyHirePopup()
		{
			if ((UnityEngine.Object)(object)_familyHirePopup == (UnityEngine.Object)null)
			{
				return;
			}
			// Sync state with actual active state to prevent stuck button
			_familyHireVisible = _familyHirePopup.activeSelf;
			_familyHireVisible = !_familyHireVisible;
			_familyHirePopup.SetActive(_familyHireVisible);
			if (_familyHireVisible)
			{
				_familyHirePopup.transform.SetAsLastSibling();
				_filterEthnicity = "All";
				_filterTrait = "All";
				_ethFilterIndex = 0;
				_traitFilterIndex = 0;
				_filterMinAge = Mathf.FloorToInt(GetEffectiveHireableMinAge());
				_filterMaxAge = 100;
				if ((UnityEngine.Object)(object)_traitDropdownPanel != (UnityEngine.Object)null)
				{
					_traitDropdownPanel.SetActive(false);
				}
				try
				{
					RefreshFamilyHireList();
				}
				catch (Exception ex)
				{
					Debug.LogWarning($"[GameplayTweaks] RefreshFamilyHireList failed: {ex.Message}");
					if ((UnityEngine.Object)(object)_familyHireStatusText != (UnityEngine.Object)null)
					{
						_familyHireStatusText.text = "Unable to load relatives for this selection.";
					}
				}
			}
		}

		private static void CloseFamilyHirePopup()
		{
			_familyHireVisible = false;
			if ((UnityEngine.Object)(object)_traitDropdownPanel != (UnityEngine.Object)null)
			{
				_traitDropdownPanel.SetActive(false);
			}
			if ((UnityEngine.Object)(object)_familyHirePopup != (UnityEngine.Object)null)
			{
				_familyHirePopup.SetActive(false);
			}
		}

		private static void CycleEthnicityFilter()
		{
			_ethFilterIndex = (_ethFilterIndex + 1) % ETHNICITY_FILTERS.Length;
			_filterEthnicity = ETHNICITY_FILTERS[_ethFilterIndex];
			RefreshFamilyHireList();
		}

		private static void CycleTraitFilter()
		{
			SetTraitFilterByIndex((_traitFilterIndex + 1) % TRAIT_FILTERS.Length, closeDropdown: false);
		}

		private static void ToggleTraitDropdown()
		{
			if ((UnityEngine.Object)(object)_traitDropdownPanel == (UnityEngine.Object)null)
			{
				return;
			}
			_traitDropdownPanel.SetActive(!_traitDropdownPanel.activeSelf);
		}

		private static void SetTraitFilterByIndex(int index, bool closeDropdown)
		{
			if (index < 0 || index >= TRAIT_FILTERS.Length)
			{
				index = 0;
			}
			_traitFilterIndex = index;
			_filterTrait = TRAIT_FILTERS[_traitFilterIndex];
			if ((UnityEngine.Object)(object)_txtTraitDropdown != (UnityEngine.Object)null)
			{
				string display = (_filterTrait == "All") ? "All" : _filterTrait.Replace("trait-", "");
				_txtTraitDropdown.text = "Trait: " + display + " ▼";
			}
			if (closeDropdown && (UnityEngine.Object)(object)_traitDropdownPanel != (UnityEngine.Object)null)
			{
				_traitDropdownPanel.SetActive(false);
			}
			RefreshFamilyHireList();
		}

		private static void RefreshFamilyHireList()
		{

			if ((UnityEngine.Object)(object)_familyHireContent == (UnityEngine.Object)null)
			{
				return;
			}
			for (int num = _familyHireContent.childCount - 1; num >= 0; num--)
			{
				UnityEngine.Object.Destroy((UnityEngine.Object)(object)((Component)_familyHireContent.GetChild(num)).gameObject);
			}
			if (_selectedPeep == null)
			{
				_familyHireStatusText.text = "No crew member selected";
				return;
			}
			List<Entity> list = new List<Entity>();
			foreach (Entity rel in FindAllRelatives(_selectedPeep))
			{
				if (!list.Any((Entity r) => r.Id == rel.Id))
				{
					list.Add(rel);
				}
			}
			int hireableRelativeCount = list.Count;
			SimTime now = G.GetNow();
			_filteredRelatives = (from r in list.Where(delegate(Entity r)
				{

					PersonData person = r.data.person;
					if (!CrewHireEligibilityPatch.IsAllowedCrewHireCandidate(r, out _))
					{
						return false;
					}
					SimTimeSpan age = person.GetAge(now);
					float yearsFloat = age.YearsFloat;
					if (yearsFloat < (float)_filterMinAge || yearsFloat > (float)_filterMaxAge)
					{
						return false;
					}
					if (_filterEthnicity != "All" && !person.eth.ToString().Equals(_filterEthnicity, StringComparison.OrdinalIgnoreCase))
					{
						return false;
					}
					if (_filterTrait != "All")
					{
						string traitId = _filterTrait.ToLower();
						bool flag = false;
						try
						{
							TagList traitIds = r.data.person.traitIds;
							if (traitIds != null)
							{
								foreach (Label trait in traitIds)
								{
									string traitStr = trait.ToString().ToLower();
									if (traitStr == traitId || traitStr.Contains(traitId))
									{
										flag = true;
										break;
									}
								}
							}
							if (!flag)
							{
								XP xp = r.data.agent.xp;
								if (xp != null && xp.crewRole != Label.NULL)
								{
									string roleStr = xp.crewRole.ToString().ToLower();
									if (roleStr == traitId || roleStr.Contains(traitId))
									{
										flag = true;
									}
								}
							}
						}
						catch
						{
							flag = true;
						}
						if (!flag)
						{
							return false;
						}
					}
					return true;
				})
				orderby GetFamilyHireAgeBucket(r, now), r.data.person.FullName
				select r).ToList();
			string traitDisplay = _filterTrait == "All" ? "All" : _filterTrait.Replace("trait-", "");
			string arg = $"Eth: {_filterEthnicity} | Trait: {traitDisplay} | Age: {_filterMinAge}-{_filterMaxAge}";
			_familyHireStatusText.text = $"{_filteredRelatives.Count} shown / {hireableRelativeCount} hireable for selected crew\n{arg}";
			if (_filteredRelatives.Count != hireableRelativeCount)
			{
				VerificationLog("CrewHire", $"family-hire-filtered selected={_selectedPeep.Id.id} shown={_filteredRelatives.Count} hireable={hireableRelativeCount} ethnicity={_filterEthnicity} trait={traitDisplay} minAge={_filterMinAge} maxAge={_filterMaxAge}");
			}
			Transform val = _familyHirePopup.transform.Find("FH_FilterRow1");
			if ((UnityEngine.Object)(object)val != (UnityEngine.Object)null)
			{
				Transform val2 = val.Find("FH_EthFilter");
				if ((UnityEngine.Object)(object)val2 != (UnityEngine.Object)null)
				{
					((Component)val2).GetComponentInChildren<Text>().text = "Eth: " + _filterEthnicity;
				}
				Transform val3 = val.Find("FH_TraitDropdownBtn");
				if ((UnityEngine.Object)(object)val3 != (UnityEngine.Object)null)
				{
					((Component)val3).GetComponentInChildren<Text>().text = "Trait: " + (_filterTrait == "All" ? "All" : _filterTrait.Replace("trait-", "")) + " ▼";
				}
			}
			Transform val4 = _familyHirePopup.transform.Find("FH_FilterRow2");
			if ((UnityEngine.Object)(object)val4 != (UnityEngine.Object)null)
			{
				Transform val5 = val4.Find("FH_AgeDown");
				if ((UnityEngine.Object)(object)val5 != (UnityEngine.Object)null)
				{
					((Component)val5).GetComponentInChildren<Text>().text = $"Min:{_filterMinAge}";
				}
				Transform val6 = val4.Find("FH_MaxUp");
				if ((UnityEngine.Object)(object)val6 != (UnityEngine.Object)null)
				{
					((Component)val6).GetComponentInChildren<Text>().text = $"Max:{_filterMaxAge}";
				}
			}
			foreach (Entity filteredRelative in _filteredRelatives)
			{
				CreateFamilyHireEntry(filteredRelative, now);
			}
		}

		private static int GetFamilyHireAgeBucket(Entity relative, SimTime now)
		{
			try
			{
				float age = relative?.data?.person?.GetAge(now).YearsFloat ?? 0f;
				if (age >= GetEffectiveHireableMinAge() && age <= 35f)
				{
					return 0;
				}
				if (age < 50f)
				{
					return 1;
				}
				return 2;
			}
			catch
			{
				return 3;
			}
		}

		private static string FormatFamilyHireTraitSummary(Entity relative)
		{
			try
			{
				TagList traitIds = relative?.data?.person?.traitIds;
				if (traitIds == null)
				{
					return "Traits: none";
				}
				List<string> traits = new List<string>();
				foreach (Label trait in traitIds)
				{
					string label = FormatFamilyHireTraitLabel(trait.ToString());
					if (!string.IsNullOrWhiteSpace(label) && !traits.Contains(label))
					{
						traits.Add(label);
					}
				}
				return traits.Count > 0 ? "Traits: " + string.Join(", ", traits.Take(4)) : "Traits: none";
			}
			catch
			{
				return "Traits: unknown";
			}
		}

		private static string FormatFamilyHireTraitLabel(string traitId)
		{
			if (string.IsNullOrWhiteSpace(traitId))
			{
				return string.Empty;
			}
			string cleaned = traitId.Replace("trait-", string.Empty).Replace("-", " ").Trim();
			if (cleaned.Length == 0)
			{
				return string.Empty;
			}
			return CultureInfo.InvariantCulture.TextInfo.ToTitleCase(cleaned.ToLowerInvariant());
		}

