		private static void HireSpecificRelative(Entity relative)
		{

			if (relative == null)
			{
				return;
			}
			PlayerCrew humanCrew = G.GetHumanCrew();
			if (humanCrew == null)
			{
				Debug.LogWarning("[GameplayTweaks] HireSpecificRelative: Could not get player crew");
				return;
			}
			if (!humanCrew.CanAddCrew(1))
			{
				Debug.Log("[GameplayTweaks] Crew is full, cannot hire more");
				return;
			}
			if (!CrewHireEligibilityPatch.IsAllowedCrewHireCandidate(relative, out string blockedReason))
			{
				if ((UnityEngine.Object)(object)_familyHireStatusText != (UnityEngine.Object)null)
				{
					_familyHireStatusText.text = "Cannot hire: " + blockedReason.Replace("-", " ");
				}
				VerificationLog("CrewHire", $"family-hire-blocked peep={relative.Id.id} reason={blockedReason}");
				RefreshFamilyHireList();
				return;
			}
			try
			{
				Entity val = _selectedPeep;
				if (val == null)
				{
					foreach (CrewAssignment item in humanCrew.GetLiving())
					{
						CrewAssignment current = item;
						Entity peep = current.GetPeep();
						if (peep == null)
						{
							continue;
						}
						RelationshipTracker rels = G.GetRels();
						RelationshipList val2 = ((rels != null) ? rels.GetListOrNull(peep.Id) : null);
						if (val2 != null)
						{
							foreach (Relationship datum in val2.data)
							{
								if (datum.to == relative.Id)
								{
									val = peep;
									break;
								}
							}
						}
						if (val != null)
						{
							break;
						}
					}
				}
				humanCrew.HireNewCrewMemberUnassigned(relative, val ?? _selectedPeep);
				Debug.Log(("[GameplayTweaks] Hired " + relative.data.person.FullName + " as new crew member"));
				RefreshFamilyHireList();
				RefreshHandlerUI();
			}
			catch (Exception arg)
			{
				Debug.LogError($"[GameplayTweaks] Failed to hire relative: {arg}");
			}
		}

		private static void OnVacation()
		{

			if (_selectedPeep == null)
			{
				return;
			}
			CrewModState orCreateCrewState = GetOrCreateCrewState(_selectedPeep.Id);
			if (orCreateCrewState == null || orCreateCrewState.OnVacation || orCreateCrewState.VacationPending || orCreateCrewState.OnHideout || orCreateCrewState.HideoutPending)
			{
				return;
			}
			if (orCreateCrewState.InJail || IsCrewCurrentlyJailed(_selectedPeep.Id))
			{
				return;
			}
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (humanPlayer != null)
			{
				try
				{
					humanPlayer.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(-1500)), (MoneyReason)1);
				}
				catch
				{
					return;
				}
				orCreateCrewState.VacationPending = true;
				orCreateCrewState.VacationDuration = 7;
				orCreateCrewState.HappinessValue = 1f;
				orCreateCrewState.TurnsUnhappy = 0;
				Debug.Log(("[GameplayTweaks] " + _selectedPeep.data.person.FullName + " will go on vacation ($1500)"));
				RefreshHandlerUI();
			}
		}

		private static void OnHideOut()
		{
			if (_selectedPeep == null)
			{
				return;
			}
			CrewModState state = GetOrCreateCrewState(_selectedPeep.Id);
			if (state == null || state.OnHideout || state.HideoutPending || state.OnVacation || state.VacationPending)
			{
				return;
			}
			if (state.InJail || JailSystem.IsInJail(_selectedPeep.Id))
			{
				return;
			}
			if (!ShouldShowHideoutAction(_selectedPeep.Id, state))
			{
				VerificationLog("NationalHeat", $"Hideout blocked peep={_selectedPeep.Id.id} heat={state.LocalHeatLevel} progress={state.LocalHeatProgress:0.000} feds={state.FedsIncoming}");
				RefreshHandlerUI();
				return;
			}
			state.HideoutPending = true;
			state.HideoutDuration = Mathf.Max(1, HIDEOUT_DURATION_DAYS);
			state.FedsIncoming = false;
			state.FedArrivalCountdown = 0;
			VerificationLog("NationalHeat", $"Hideout requested peep={_selectedPeep.Id.id} duration={state.HideoutDuration}");
			RefreshHandlerUI();
		}

		private static void OnMakeDisappear()
		{
			if (_selectedPeep == null)
			{
				return;
			}
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (humanPlayer == null || IsHumanBoss(_selectedPeep, humanPlayer))
			{
				return;
			}
			CrewModState state = GetOrCreateCrewState(_selectedPeep.Id);
			if (state == null || !state.SnitchExposed || state.SnitchDisappearPending)
			{
				return;
			}
			state.SnitchDisappearPending = true;
			state.SnitchDisappearDueDay = G.GetNow().days + 1;
			VerificationLog("SnitchDisappear", $"armed peep={_selectedPeep.Id.id} dueDay={state.SnitchDisappearDueDay}");
			RefreshHandlerUI();
		}

