		private static void OnToggleRobberyResponseMode()
		{
			if (_selectedPeep == null)
			{
				return;
			}
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (!IsHumanBoss(_selectedPeep, humanPlayer))
			{
