		private static Entity ResolveOddJobPayContainer(PlayerInfo humanPlayer, Entity peep)
		{
			if (humanPlayer == null)
			{
				return null;
			}
			try
			{
				CrewAssignment crew = humanPlayer.crew?.GetCrewForPeep(peep.Id) ?? CrewAssignment.EMPTY;
				if (crew.IsValid && crew.IsInVehicle && crew.VehicleID.IsValid)
				{
					Entity vehicle = crew.GetVehicle();
					if (vehicle != null)
					{
						return vehicle;
					}
				}
			}
			catch
			{
			}
			try
			{
				return humanPlayer.territory.Safehouse.FindEntity();
			}
			catch
			{
				return null;
			}
		}

		private static void OnOddJob()
		{
			if (_selectedPeep == null || !(EnableCrewOddJobs?.Value ?? true))
			{
				return;
			}
			CrewModState state = GetOrCreateCrewState(_selectedPeep.Id);
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (state == null || humanPlayer == null)
			{
				return;
			}
			NormalizeOddJobCooldownState(state, G.GetNow(), "toggle", _selectedPeep.Id);
			bool nextEnabled = !state.OddJobsEnabled;
			if (nextEnabled)
			{
				bool isAlive = _selectedPeep.data?.person != null && _selectedPeep.data.person.IsAlive;
				if (!isAlive || IsCrewCurrentlyJailed(_selectedPeep.Id))
				{
					RefreshHandlerUI();
					return;
				}
				if (state.LastOddJobDay < 0)
				{
					state.LastOddJobDay = G.GetNow().days - ODD_JOB_COOLDOWN_DAYS;
				}
			}
			state.OddJobsEnabled = nextEnabled;
			string name = _selectedPeep.data?.person?.ShortName ?? "Crew";
			LogGrapevine(nextEnabled
				? $"CREW: {name} will work odd jobs weekly."
				: $"CREW: {name} stopped taking weekly odd jobs.");
			VerificationLog("OddJob", $"toggle peep={_selectedPeep.Id.id} enabled={state.OddJobsEnabled} lastDay={state.LastOddJobDay} total={state.TotalOddJobEarnings}");
			RefreshHandlerUI();
		}

