				_inputFirstName.text = _selectedPeep.data.person.first ?? "";
				_inputLastName.text = _selectedPeep.data.person.last ?? "";
			}
			catch
			{
			}
		}

		private static string SanitizeDisplayName(string raw, int maxLen, string sourceTag, out bool changed)
		{
			changed = false;
			if (raw == null)
			{
				return string.Empty;
			}
			string text = raw.Replace("\uFFFD", string.Empty);
			if (!ReferenceEquals(text, raw))
			{
				changed = true;
			}
			StringBuilder stringBuilder = new StringBuilder(text.Length);
			for (int i = 0; i < text.Length; i++)
			{
				char c = text[i];
				if (char.IsControl(c) && !char.IsWhiteSpace(c))
				{
					changed = true;
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			string text2 = stringBuilder.ToString().Trim();
			if (!string.Equals(text2, raw?.Trim(), StringComparison.Ordinal))
			{
				changed = true;
			}
			if (maxLen > 0 && text2.Length > maxLen)
			{
				text2 = text2.Substring(0, maxLen);
				changed = true;
			}
			if (changed)
			{
				VerificationLog("NameSanitize", $"sanitized=true source={sourceTag}");
			}
			return text2;
		}

		internal static string SanitizeRuntimePersonName(string raw)
		{
			if (string.IsNullOrEmpty(raw))
			{
				return string.Empty;
			}

			string sanitized = raw.Replace("\uFFFD", string.Empty).Trim();
			if (string.IsNullOrEmpty(sanitized))
			{
				return string.Empty;
			}

			if (LooksLikeMojibakeName(sanitized))
			{
				string repaired = TryRepairMojibakeName(sanitized);
				if (!string.IsNullOrEmpty(repaired))
				{
					sanitized = repaired;
				}
			}

			return sanitized.Replace("\uFFFD", string.Empty).Trim();
		}

		private static bool LooksLikeMojibakeName(string value)
		{
			if (string.IsNullOrEmpty(value))
			{
				return false;
			}

			for (int i = 0; i < value.Length; i++)
			{
				switch (value[i])
				{
				case 'Ã':
				case 'Å':
				case 'Ä':
				case 'Æ':
				case 'Ð':
				case 'Ñ':
				case 'Ø':
				case 'Þ':
					return true;
				}
			}

			return false;
		}

		private static string TryRepairMojibakeName(string value)
		{
			try
			{
				byte[] bytes = Encoding.GetEncoding(1252).GetBytes(value);
				string repaired = Encoding.UTF8.GetString(bytes);
				if (string.IsNullOrWhiteSpace(repaired))
				{
					return value;
				}

				int originalScore = GetRuntimeNameCorruptionScore(value);
				int repairedScore = GetRuntimeNameCorruptionScore(repaired);
				return repairedScore < originalScore ? repaired.Trim() : value;
			}
			catch
			{
				return value;
			}
		}

		private static int GetRuntimeNameCorruptionScore(string value)
		{
			if (string.IsNullOrEmpty(value))
			{
				return 0;
			}

			int score = 0;
			for (int i = 0; i < value.Length; i++)
			{
				char c = value[i];
				if (c == '\uFFFD')
				{
					score += 10;
					continue;
				}

				switch (c)
				{
				case 'Ã':
				case 'Å':
				case 'Ä':
				case 'Æ':
				case 'Ð':
				case 'Ñ':
				case 'Ø':
				case 'Þ':
					score += 3;
					break;
				}
			}

			return score;
		}

		internal static string SanitizeUiGlyphText(string raw, bool aggressive = false)
		{
			if (string.IsNullOrEmpty(raw))
			{
				return string.Empty;
			}

			string text = raw.Replace("\uFFFD", string.Empty);
			if (aggressive || ExternalCustomIconsDetected)
			{
				text = text.Replace("\u25A1", string.Empty);
			}
			return text;
		}

		internal static void SanitizeMissingGlyphsInHierarchy(GameObject root, bool aggressive = false)
		{
			if ((UnityEngine.Object)(object)root == (UnityEngine.Object)null)
			{
				return;
			}

			foreach (Text item in root.GetComponentsInChildren<Text>(true))
			{
				if ((UnityEngine.Object)(object)item == (UnityEngine.Object)null)
				{
					continue;
				}

				string sanitized = SanitizeUiGlyphText(item.text, aggressive);
				if (!string.Equals(sanitized, item.text, StringComparison.Ordinal))
				{
					item.text = sanitized;
				}
			}

			foreach (TMP_Text item2 in root.GetComponentsInChildren<TMP_Text>(true))
			{
				if ((UnityEngine.Object)(object)item2 == (UnityEngine.Object)null)
				{
					continue;
				}

				string sanitized2 = SanitizeUiGlyphText(item2.text, aggressive);
				if (!string.Equals(sanitized2, item2.text, StringComparison.Ordinal))
				{
					item2.text = sanitized2;
				}
			}
		}

		private static int GetManualPepTalksRemaining(Entity peep)
		{
			if (peep == null)
			{
				return 0;
			}
			CrewModState orCreateCrewState = GetOrCreateCrewState(peep.Id);
			if (orCreateCrewState == null)
			{
				return 0;
			}
			return (orCreateCrewState.LastManualPepTalkDay == G.GetNow().days) ? 0 : 1;
		}

		private static bool TryConsumeManualPepTalk(Entity peep, string source)
		{
			if (peep == null)
			{
				return false;
			}
			CrewModState state = GetOrCreateCrewState(peep.Id);
			if (state == null)
			{
				return false;
			}
			int day = G.GetNow().days;
			if (state.LastManualPepTalkDay == day)
			{
				VerificationLog("PepTalkManual", $"consume-blocked peep={peep.Id.id} day={day} source={source ?? "unknown"} reason=already-used");
				return false;
			}
			state.LastManualPepTalkDay = day;
			VerificationLog("PepTalkManual", $"consume peep={peep.Id.id} day={day} source={source ?? "unknown"}");
			return true;
		}

		private static void OnSaveRename()
		{
			if (_selectedPeep == null || (UnityEngine.Object)(object)_inputFirstName == (UnityEngine.Object)null || (UnityEngine.Object)(object)_inputLastName == (UnityEngine.Object)null)
			{
				return;
			}
			string text = SanitizeDisplayName(_inputFirstName.text, 20, "crew-firstname", out bool _);
			string text2 = SanitizeDisplayName(_inputLastName.text, 20, "crew-lastname", out bool _);
			if (string.IsNullOrEmpty(text) || string.IsNullOrEmpty(text2))
			{
				VerificationLog("NameSanitize", "sanitized-empty source=crew-rename ignored=true");
				return;
			}
			try
			{
				PersonData person = _selectedPeep.data.person;
				person.first = text;
				person.last = text2;
				Type type = ((object)person).GetType();
				string[] array = new string[4] { "_fullname", "_shortname", "_fullName", "_shortName" };
				foreach (string name in array)
				{
					FieldInfo field = type.GetField(name, BindingFlags.Instance | BindingFlags.NonPublic);
					if (field != null && field.FieldType == typeof(string))
					{
						field.SetValue(person, null);
					}
				}
				_renameRow.SetActive(false);
				RefreshHandlerUI();
			}
			catch (Exception arg)
			{
				Debug.LogError($"[GameplayTweaks] Rename failed: {arg}");
			}
		}

		private static void OnAgeUp()
		{

			if (_selectedPeep == null)
			{
				return;
			}
			try
			{
				PersonData person = _selectedPeep.data.person;
				string fullName = person.FullName;
				int days = person.born.days;
				person.born = new SimTime(days - 365);
				int num = 0;
				RelationshipTracker rels = G.GetRels();
				if (rels != null)
				{
					RelationshipList listOrNull = rels.GetListOrNull(_selectedPeep.Id);
					if (listOrNull != null)
					{
						foreach (Relationship datum in listOrNull.data)
						{
							if ((int)datum.type != 20 && (int)datum.type != 50 && (int)datum.type != 10 && (int)datum.type != 30 && (int)datum.type != 40 && (int)datum.type != 90)
							{
								continue;
							}
							Entity val = EntityIDExtensions.FindEntity(datum.to);
							if (val != null)
							{
								try
								{
									PersonData person2 = val.data.person;
									int days2 = person2.born.days;
									person2.born = new SimTime(days2 - 365);
									num++;
								}
								catch
								{
								}
							}
						}
					}
				}
				SimTimeSpan age = person.GetAge(G.GetNow());
				float yearsFloat = age.YearsFloat;
				string arg = ((num > 0) ? $" ({num} family members also aged)" : "");
				LogGrapevine($"CREW: {fullName}'s family aged by 1 year (now {(int)yearsFloat}){arg}");
				RefreshHandlerUI();
			}
			catch (Exception arg2)
			{
				Debug.LogError($"[GameplayTweaks] Age up failed: {arg2}");
			}
		}

		private static void OnXpMinus()
		{
			if (_selectedPeep == null)
			{
				return;
			}
			try
			{
				XP val = _selectedPeep.data.agent?.xp;
				if (val == null)
				{
					return;
				}
				int num = Math.Max(0, val.current - _xpAdjustAmount);
				val.current = num;
				Debug.Log($"[GameplayTweaks] Reduced XP by {_xpAdjustAmount} to {num}");
				RefreshHandlerUI();
			}
			catch (Exception arg)
			{
				Debug.LogError($"[GameplayTweaks] XP minus failed: {arg}");
			}
		}

		private static void OnXpPlus()
		{
			if (_selectedPeep == null)
			{
				return;
			}
			try
			{
				AgentComponent agent = _selectedPeep.components?.agent;
				if (agent != null)
				{
					agent.AddXP(_xpAdjustAmount);
					Debug.Log($"[GameplayTweaks] Added {_xpAdjustAmount} XP via AddXP");
				}
				else
				{
					XP val = _selectedPeep.data.agent?.xp;
					if (val != null)
					{
						val.current += _xpAdjustAmount;
						Debug.Log($"[GameplayTweaks] Added {_xpAdjustAmount} XP directly to {val.current}");
					}
				}
				RefreshHandlerUI();
			}
			catch (Exception arg)
			{
				Debug.LogError($"[GameplayTweaks] XP plus failed: {arg}");
			}
		}

		private static void OnXpCycleAmount()
		{
			if (_xpAdjustAmount == 100)
			{
				_xpAdjustAmount = 500;
			}
			else if (_xpAdjustAmount == 500)
			{
				_xpAdjustAmount = 1000;
			}
			else if (_xpAdjustAmount == 1000)
			{
				_xpAdjustAmount = 50;
			}
			else
			{
				_xpAdjustAmount = 100;
			}
			if ((UnityEngine.Object)(object)_btnXpMinus != (UnityEngine.Object)null)
			{
				((Component)_btnXpMinus).GetComponentInChildren<Text>().text = $"-{_xpAdjustAmount}";
			}
			if ((UnityEngine.Object)(object)_btnXpPlus != (UnityEngine.Object)null)
			{
				((Component)_btnXpPlus).GetComponentInChildren<Text>().text = $"+{_xpAdjustAmount}";
			}
			Debug.Log($"[GameplayTweaks] XP adjustment amount set to {_xpAdjustAmount}");
		}

