		private static void ApplyCrewPepTalkOutcome(CrewPepTalkPromptEvent prompt, bool accepted)
		{
			Entity entity = prompt?.PeepId.IsValid == true ? prompt.PeepId.FindEntity() : null;
			CrewModState orCreateCrewState = (prompt != null) ? GetOrCreateCrewState(prompt.PeepId) : null;
			if (entity == null || orCreateCrewState == null)
			{
				return;
			}
			float num = accepted ? prompt.HappinessDeltaOnAccept : prompt.HappinessDeltaOnDecline;
			float num2 = accepted ? prompt.LoyaltyDeltaOnAccept : prompt.LoyaltyDeltaOnDecline;
			float happinessValue = orCreateCrewState.HappinessValue;
			float loyaltyValue = orCreateCrewState.LoyaltyValue;
			orCreateCrewState.HappinessValue = Mathf.Clamp01(orCreateCrewState.HappinessValue + num);
			orCreateCrewState.LoyaltyValue = Mathf.Clamp(orCreateCrewState.LoyaltyValue + num2, 0f, Mathf.Max(0.1f, orCreateCrewState.LoyaltyCap));
			if (accepted)
			{
				bool hireProspect = string.Equals(prompt.SpecialActionKey, "hire-crew-prospect", StringComparison.Ordinal);
				float minGain = prompt.IsBoss || hireProspect ? 0.05f : 0.03f;
				float maxGain = prompt.IsBoss || hireProspect ? 0.06f : 0.04f;
				string source = prompt.IsBoss ? "boss-quest" : hireProspect ? "crew-quest-hire" : "crew-quest";
				TryAwardCrewStreetCreditProgress(G.GetHumanPlayer(), prompt.PeepId, minGain, maxGain, source);
			}
			VerificationLog("PepTalkManual", $"prompt-{(accepted ? "accept" : "decline")} peep={prompt.PeepId.id} boss={prompt.IsBoss} happinessBefore={happinessValue:0.000} happinessAfter={orCreateCrewState.HappinessValue:0.000} loyaltyBefore={loyaltyValue:0.000} loyaltyAfter={orCreateCrewState.LoyaltyValue:0.000}");
			if (_selectedPeep != null && _selectedPeep.Id == prompt.PeepId)
			{
				RefreshHandlerUI();
			}
		}

		private static bool TryResolveCrewPepTalkPreconditions(CrewPepTalkPromptEvent prompt, PlayerInfo humanPlayer, out string failureMessage)
		{
			failureMessage = null;
			if (prompt == null || humanPlayer == null)
			{
				failureMessage = "Crew prompt data is missing.";
				return false;
			}
			if (!string.Equals(prompt.SpecialActionKey, "hire-crew-prospect", StringComparison.Ordinal))
			{
				return true;
			}
			if (humanPlayer.crew == null || !humanPlayer.crew.CanAddCrew())
			{
				failureMessage = "Your outfit is at its crew cap, so there is no room for that prospect yet.";
				return false;
			}
			Entity introducer = prompt.PeepId.FindEntity();
			if (introducer == null)
			{
				failureMessage = "That prospect contact is no longer available.";
				return false;
			}
			EntityID candidateId = humanPlayer.crew.CrewGrowth.GetBestCrewCandidateFrom(introducer.Id);
			if (candidateId.IsNotValid || candidateId.FindEntity() == null)
			{
				failureMessage = "No crew prospect is available from that contact right now.";
				return false;
			}
			return true;
		}

		private static void TryExecuteCrewPepTalkSpecialAction(CrewPepTalkPromptEvent prompt, PlayerInfo humanPlayer)
		{
			if (prompt == null || humanPlayer == null)
			{
				return;
			}
			if (!string.Equals(prompt.SpecialActionKey, "hire-crew-prospect", StringComparison.Ordinal))
			{
				return;
			}
			try
			{
				Entity introducer = prompt.PeepId.FindEntity();
				Entity candidate = humanPlayer.crew?.CrewGrowth?.GetBestCrewCandidateFrom(introducer?.Id ?? EntityID.INVALID).FindEntity();
				if (introducer == null || candidate == null || humanPlayer.crew == null || !humanPlayer.crew.CanAddCrew())
				{
					return;
				}
				humanPlayer.crew.HireNewCrewMemberUnassigned(candidate, introducer);
				string fullName = candidate.data?.person?.FullName ?? candidate.data?.person?.ShortName ?? "New recruit";
				LogGrapevine("CREW: " + fullName + " joined your outfit through " + (prompt.PeepName ?? "a crew contact") + ".");
				VerificationLog("PepTalkManual", $"prompt-special-hire peep={prompt.PeepId.id} candidate={candidate.Id.id}");
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] TryExecuteCrewPepTalkSpecialAction failed: " + ex.Message);
			}
		}

		private static void OnAcceptCrewPepTalkPrompt()
		{
			try
			{
				CrewPepTalkPromptEvent crewPepTalkPromptEvent = _activeCrewPepTalkPrompt;
				PlayerInfo humanPlayer = G.GetHumanPlayer();
				if (crewPepTalkPromptEvent == null || humanPlayer == null)
				{
					CloseCrewPepTalkPrompt();
					return;
				}
				if (!TryResolveCrewPepTalkPreconditions(crewPepTalkPromptEvent, humanPlayer, out string failureMessage))
				{
					if ((UnityEngine.Object)(object)_crewPepTalkBodyText != (UnityEngine.Object)null)
					{
						_crewPepTalkBodyText.text = failureMessage;
					}
					return;
				}
				int num = Math.Max(0, crewPepTalkPromptEvent.Cost);
				if (num > 0 && !humanPlayer.finances.CanChangeMoneyOnSafehouse(new Price((Fixnum)(-num))))
				{
					if ((UnityEngine.Object)(object)_crewPepTalkBodyText != (UnityEngine.Object)null)
					{
						_crewPepTalkBodyText.text = "You do not have enough cash on hand for that favor.";
					}
					VerificationLog("PepTalkManual", $"prompt-accept-blocked peep={crewPepTalkPromptEvent.PeepId.id} boss={crewPepTalkPromptEvent.IsBoss} reason=not-enough-cash cost={num}");
					return;
				}
				Entity promptPeep = crewPepTalkPromptEvent.PeepId.FindEntity();
				if (!TryConsumeManualPepTalk(promptPeep, "quest-accept"))
				{
					if ((UnityEngine.Object)(object)_crewPepTalkBodyText != (UnityEngine.Object)null)
					{
						_crewPepTalkBodyText.text = "No pep talk is available for this crew member right now.";
					}
					return;
				}
				if (num > 0)
				{
					humanPlayer.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(-num)), (MoneyReason)1);
				}
				ApplyCrewPepTalkOutcome(crewPepTalkPromptEvent, accepted: true);
				TryExecuteCrewPepTalkSpecialAction(crewPepTalkPromptEvent, humanPlayer);
				if (!string.IsNullOrEmpty(crewPepTalkPromptEvent.AcceptTickerText))
				{
					LogGrapevine(crewPepTalkPromptEvent.AcceptTickerText);
				}
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] OnAcceptCrewPepTalkPrompt failed: " + ex.Message);
			}
			CloseCrewPepTalkPrompt();
		}

		private static void OnDeclineCrewPepTalkPrompt()
		{
			try
			{
				CrewPepTalkPromptEvent crewPepTalkPromptEvent = _activeCrewPepTalkPrompt;
