		private static void ApplyManualPepTalkFallback(Entity peep, CrewModState state, PlayerInfo humanPlayer, bool isBoss)
		{
			float happinessValue = state.HappinessValue;
			float loyaltyValue = state.LoyaltyValue;
			state.HappinessValue = Mathf.Clamp01(state.HappinessValue + 0.05f);
			TryRecoverLoyaltyTowardCap(peep, state, humanPlayer, "peptalk", 0.005f, 0.1f);
			VerificationLog("PepTalkManual", $"fallback peep={peep.Id.id} boss={isBoss} happinessBefore={happinessValue:0.000} happinessAfter={state.HappinessValue:0.000} loyaltyBefore={loyaltyValue:0.000} loyaltyAfter={state.LoyaltyValue:0.000}");
		}

		private static void OnPepTalk()
		{

			if (_selectedPeep == null)
			{
				return;
			}
			CrewModState orCreateCrewState = GetOrCreateCrewState(_selectedPeep.Id);
			if (orCreateCrewState != null)
			{
				int days = G.GetNow().days;
				PlayerInfo humanPlayer = G.GetHumanPlayer();
				bool flag = IsHumanBoss(_selectedPeep, humanPlayer);
				VerificationLog("PepTalkManual", $"click peep={_selectedPeep.Id.id} boss={flag} day={days}");
				if (orCreateCrewState.LastManualPepTalkDay == days)
				{
					VerificationLog("PepTalkManual", $"blocked peep={_selectedPeep.Id.id} boss={flag} day={days} reason=already-used");
					RefreshHandlerUI();
					return;
				}
				if (TryQueueCrewPepTalkPrompt(_selectedPeep, orCreateCrewState, humanPlayer, requireChance: false))
				{
					RefreshHandlerUI();
					return;
				}
				if (!TryConsumeManualPepTalk(_selectedPeep, "fallback"))
				{
					RefreshHandlerUI();
					return;
				}
				ApplyManualPepTalkFallback(_selectedPeep, orCreateCrewState, humanPlayer, flag);
				RefreshHandlerUI();
			}
		}

		private static void OnToggleNickname()
		{
			if ((UnityEngine.Object)(object)_nicknameRow == (UnityEngine.Object)null || _selectedPeep == null)
			{
