		private static void OnPoliticalFavor()
		{
			if (_pendingPoliticalFavorUse)
			{
				return;
			}
			if (Time.frameCount - _lastPoliticalFavorProcessedFrame < 30)
			{
				return;
			}
			if (!IsHumanPoliticalBribeActive() || !CanUsePoliticalFavor())
			{
				_pendingPoliticalFavorRefreshOnly = true;
				_pendingPoliticalFavorRequestFrame = Time.frameCount;
				return;
			}
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (!CanPayCleanSafehouse(humanPlayer, POLITICAL_FAVOR_COST))
			{
				VerificationLog("Political", $"favor-blocked amount={POLITICAL_FAVOR_COST} reason=insufficient-safehouse-cash clean={GetPlayerCleanCash()}");
				RefreshHandlerUI();
				return;
			}
			_pendingPoliticalFavorUse = true;
			_pendingPoliticalFavorRefreshOnly = false;
			_pendingPoliticalFavorRequestFrame = Time.frameCount;
			if ((UnityEngine.Object)(object)_btnPoliticalFavor != (UnityEngine.Object)null)
			{
				((Selectable)_btnPoliticalFavor).interactable = false;
			}
			if ((UnityEngine.Object)(object)_txtPoliticalFavor != (UnityEngine.Object)null)
			{
				_txtPoliticalFavor.text = "Call In Favor (Processing...)";
			}
			Debug.Log("[GameplayTweaks] Political favor queued.");
		}

		internal static void ProcessPendingPoliticalFavorUse()
		{
			if (!_pendingPoliticalFavorUse && !_pendingPoliticalFavorRefreshOnly)
			{
				return;
			}
			if (_pendingPoliticalFavorRequestFrame == Time.frameCount)
			{
				return;
			}
			bool flag = _pendingPoliticalFavorUse;
			_pendingPoliticalFavorUse = false;
			_pendingPoliticalFavorRefreshOnly = false;
			_pendingPoliticalFavorRequestFrame = -1;
			_lastPoliticalFavorProcessedFrame = Time.frameCount;
			if (!flag)
			{
				RefreshHandlerUI();
				return;
			}
			bool flag2 = false;
			string text = "unknown";
			try
			{
				if (!IsHumanPoliticalBribeActive())
				{
					text = "inactive-bribe";
				}
				else if (!CanUsePoliticalFavor())
				{
					text = "no-live-incident";
				}
				else
				{
					PlayerInfo humanPlayer = G.GetHumanPlayer();
					if (humanPlayer == null)
					{
						text = "missing-human";
					}
					else if (!CanPayCleanSafehouse(humanPlayer, POLITICAL_FAVOR_COST))
					{
						text = "insufficient-safehouse-cash";
						VerificationLog("Political", $"favor-blocked amount={POLITICAL_FAVOR_COST} reason=insufficient-safehouse-cash clean={GetPlayerCleanCash()}");
					}
					else
					{
						humanPlayer.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(-POLITICAL_FAVOR_COST)), (MoneyReason)1);
						flag2 = TryUsePoliticalFavor();
						text = (flag2 ? "resolved" : "no-resolution");
						if (!flag2)
						{
							Debug.LogWarning("[GameplayTweaks] Political favor payment made but no live cop incident could be resolved.");
						}
					}
				}
			}
			catch (Exception ex)
			{
				text = ex.GetType().Name + ":" + ex.Message;
				Debug.LogWarning("[GameplayTweaks] Political favor purchase failed: " + ex.Message);
			}
			finally
			{
				Debug.Log("[GameplayTweaks] Political favor processed success=" + flag2 + " result=" + text);
				RefreshHandlerUI();
			}
		}

		internal static bool IsHumanPoliticalBribeActive()
		{
			ExpireHumanPoliticalBribeIfNeeded(G.GetNow(), logExpiration: true);
			return _globalMayorBribeActive;
		}

		internal static void ExpireHumanPoliticalBribeIfNeeded(SimTime now, bool logExpiration)
		{
			if (!_globalMayorBribeActive)
			{
				return;
			}
			if (_globalMayorBribeExpireDay >= 0 && now.days >= _globalMayorBribeExpireDay)
			{
				_globalMayorBribeActive = false;
				_globalMayorBribeExpireDay = -1;
				if (logExpiration)
				{
					Debug.Log("[GameplayTweaks] Political bribe expired.");
				}
			}
		}

		private static bool TryActivateHumanPoliticalBribe()
		{
			if (IsHumanPoliticalBribeActive())
			{
				return false;
			}
			if (IsPoliticalBribeActivationLocked())
			{
				Debug.Log("[GameplayTweaks] Political bribe blocked until all cop-targeted crew are arrested.");
				return false;
			}
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (humanPlayer == null)
			{
				return false;
			}
			if (!CanPayCleanSafehouse(humanPlayer, POLITICAL_BRIBE_COST))
			{
				VerificationLog("Political", $"bribe-blocked amount={POLITICAL_BRIBE_COST} reason=insufficient-safehouse-cash clean={GetPlayerCleanCash()}");
				RefreshHandlerUI();
				return false;
			}
			try
			{
				humanPlayer.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(-POLITICAL_BRIBE_COST)), (MoneyReason)1);
				_globalMayorBribeActive = true;
				_globalMayorBribeExpireDay = G.GetNow().days + POLITICAL_BRIBE_DURATION_DAYS;
				Debug.Log("[GameplayTweaks] Political bribe paid. City Hall access active for 6 months.");
				VerificationLog("Political", $"bribe-paid amount={POLITICAL_BRIBE_COST} expiresDay={_globalMayorBribeExpireDay}");
				LogGrapevine("POLITICS: Political access is active. You can now pay favors to cool a precinct after cop trouble starts.");
				return true;
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] Political bribe purchase failed: " + ex.Message);
				return false;
			}
		}

		private static bool CanUsePoliticalFavor()
		{
			try
			{
				Type copWarSystemType = Type.GetType("CopKilling.CopWarSystem, CopKilling");
				MethodInfo method = copWarSystemType?.GetMethod("CanUsePoliticalFavorForHumanPlayer", BindingFlags.Static | BindingFlags.Public);
				return method != null && method.Invoke(null, null) is bool flag && flag;
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] Political favor availability check failed: " + ex.Message);
			}
			return false;
		}

