		private static void OnToggleRetainerConfirm()
		{
			if (_selectedPeep == null)
			{
				return;
			}
			CrewModState orCreateCrewState = GetOrCreateCrewState(_selectedPeep.Id);
			if (orCreateCrewState == null)
			{
				return;
			}
			if (!JailSystem.IsInJail(_selectedPeep.Id))
			{
				return;
			}
			if (orCreateCrewState.LawyerRetainer <= 0)
			{
				orCreateCrewState.LawyerRetainerConfirmed = false;
				RefreshHandlerUI();
				return;
			}
			orCreateCrewState.LawyerRetainerConfirmed = !orCreateCrewState.LawyerRetainerConfirmed;
			VerificationLog("Retainer", $"Confirm toggled peep={_selectedPeep.Id.id} confirmed={orCreateCrewState.LawyerRetainerConfirmed} retainer={orCreateCrewState.LawyerRetainer}");
			RefreshHandlerUI();
		}

		private static void OnOpenBoozeSell()
		{

			if (_selectedPeep == null || !JailSystem.IsInJail(_selectedPeep.Id))
			{
				return;
			}
			CrewModState orCreateCrewState = GetOrCreateCrewState(_selectedPeep.Id);
			if (orCreateCrewState == null)
			{
				return;
			}
			if ((UnityEngine.Object)(object)_boozeSellPopup == (UnityEngine.Object)null)
			{
				Transform transform = ResolvePopupParentTransform();
				if ((UnityEngine.Object)(object)transform == (UnityEngine.Object)null)
				{
					return;
				}
				CreateBoozeSellPopup(((Component)transform).gameObject);
			}
			_boozeSellVisible = !_boozeSellVisible;
			_boozeSellPopup.SetActive(_boozeSellVisible);
			if (_boozeSellVisible)
			{
				ForceDockPopupFarLeft(_boozeSellPopup);
				PopulateBoozeSellPopup();
			}
		}

