		private static void PopulateBoozeSellPopup()
		{

			if (!IsBoozeSellPopupReady())
			{
				return;
			}
			if ((UnityEngine.Object)(object)_boozeSellContent != (UnityEngine.Object)null)
			{
				for (int num = _boozeSellContent.childCount - 1; num >= 0; num--)
				{
					UnityEngine.Object.Destroy((UnityEngine.Object)(object)((Component)_boozeSellContent.GetChild(num)).gameObject);
				}
			}
			try
			{
				PlayerInfo humanPlayer = G.GetHumanPlayer();
				if (humanPlayer == null)
				{
					RefreshBoozeSellPopupControls(null, 0, hasAnyBooze: false);
					_boozeSellStatusText.text = "No player found";
					return;
				}
				CrewModState selectedBoozeCrewState = GetSelectedBoozeCrewState();
				if (selectedBoozeCrewState == null)
				{
					RefreshBoozeSellPopupControls(null, 0, hasAnyBooze: false);
					_boozeSellStatusText.text = "No jailed crew selected";
					return;
				}
				EntityID safehouse = humanPlayer.territory.Safehouse;
				if (safehouse.IsNotValid)
				{
					RefreshBoozeSellPopupControls(selectedBoozeCrewState, 0, hasAnyBooze: false);
					_boozeSellStatusText.text = "No safehouse found";
					return;
				}
				Entity val = EntityIDExtensions.FindEntity(safehouse);
				if (val == null)
				{
					RefreshBoozeSellPopupControls(selectedBoozeCrewState, 0, hasAnyBooze: false);
					_boozeSellStatusText.text = "Safehouse entity not found";
					return;
				}
				InventoryModule inventory = ModulesUtil.GetInventory(val);
				if (inventory == null)
				{
					RefreshBoozeSellPopupControls(selectedBoozeCrewState, 0, hasAnyBooze: false);
					_boozeSellStatusText.text = "No inventory found";
					return;
				}
				List<BoozeInventoryEntry> availableBoozeEntries = GetAvailableBoozeEntries(inventory);
				int boozeSmuggleCapacity = GetBoozeSmuggleCapacity(selectedBoozeCrewState);
				RefreshBoozeSellPopupControls(selectedBoozeCrewState, boozeSmuggleCapacity, availableBoozeEntries.Count > 0);
				int num2 = 0;
				foreach (BoozeInventoryEntry item in SortBoozeEntriesForDisplay(availableBoozeEntries, GetBoozeSellMode(selectedBoozeCrewState)))
				{
					num2 += item.UnitSellPrice * item.Qty;
					CreateBoozeSellEntry(item, boozeSmuggleCapacity);
				}
				if (availableBoozeEntries.Count == 0)
				{
					_boozeSellStatusText.text = $"No booze in safehouse. Cap {boozeSmuggleCapacity}.";
				}
				else
				{
					_boozeSellStatusText.text = $"{availableBoozeEntries.Count} types found - Total value: ${num2} - Cap {boozeSmuggleCapacity}";
				}
			}
			catch (Exception arg)
			{
				RefreshBoozeSellPopupControls(GetSelectedBoozeCrewState(), 0, hasAnyBooze: false);
				if ((UnityEngine.Object)(object)_boozeSellStatusText != (UnityEngine.Object)null)
				{
					_boozeSellStatusText.text = "Error reading inventory";
				}
				Debug.LogError($"[GameplayTweaks] PopulateBoozeSellPopup: {arg}");
			}
		}

		private static bool IsBoozeSellPopupReady()
		{
			return (UnityEngine.Object)(object)_boozeSellPopup != (UnityEngine.Object)null
				&& (UnityEngine.Object)(object)_boozeSellContent != (UnityEngine.Object)null
				&& (UnityEngine.Object)(object)_boozeSellStatusText != (UnityEngine.Object)null;
		}

		private static void RefreshBoozeSellPopupControls(CrewModState state, int cap, bool hasAnyBooze)
		{
			if (state == null)
			{
				if ((UnityEngine.Object)(object)_btnBoozePrimarySell != (UnityEngine.Object)null)
				{
					((Selectable)_btnBoozePrimarySell).interactable = false;
				}
				if ((UnityEngine.Object)(object)_txtBoozePrimarySell != (UnityEngine.Object)null)
				{
					_txtBoozePrimarySell.text = "Sell Booze";
				}
				if ((UnityEngine.Object)(object)_txtBoozeMode != (UnityEngine.Object)null)
				{
					_txtBoozeMode.text = "Mode: Best";
				}
				if ((UnityEngine.Object)(object)_txtBoozeAuto != (UnityEngine.Object)null)
				{
					_txtBoozeAuto.text = "Auto: Off";
				}
				return;
			}
			BoozeSellMode boozeSellMode = GetBoozeSellMode(state);
			int days = G.GetNow().days;
			bool flag = state.LastBoozeSellTurn == 0 || days - state.LastBoozeSellTurn >= BOOZE_SMUGGLE_COOLDOWN_DAYS;
			string text = ((boozeSellMode == BoozeSellMode.Best) ? "Best" : "Cheapest");
			if ((UnityEngine.Object)(object)_txtBoozePrimarySell != (UnityEngine.Object)null)
			{
				_txtBoozePrimarySell.text = flag ? ("Sell " + text + " Booze") : $"Sell ({Mathf.Max(1, BOOZE_SMUGGLE_COOLDOWN_DAYS - (days - state.LastBoozeSellTurn))}d)";
			}
			if ((UnityEngine.Object)(object)_btnBoozePrimarySell != (UnityEngine.Object)null)
			{
				((Selectable)_btnBoozePrimarySell).interactable = flag && hasAnyBooze;
			}
			if ((UnityEngine.Object)(object)_txtBoozeMode != (UnityEngine.Object)null)
			{
				_txtBoozeMode.text = "Mode: " + text;
			}
			if ((UnityEngine.Object)(object)_txtBoozeAuto != (UnityEngine.Object)null)
			{
				_txtBoozeAuto.text = "Auto: " + (state.BoozeAutoSmuggleEnabled ? "On" : "Off");
			}
		}

