		private static string ResolveBoozeDisplayName(string itemName, Label label, Resource resource = null)
		{
			if (!string.IsNullOrWhiteSpace(itemName) && _boozeDisplayNames.TryGetValue(itemName, out string value))
			{
				return value;
			}
			try
			{
				string resourceDisplayName = resource?.GetListName();
				if (!string.IsNullOrWhiteSpace(resourceDisplayName))
				{
					return resourceDisplayName;
				}
			}
			catch
			{
			}
			string text = null;
			try
			{
				text = ((object)label)?.ToString();
			}
			catch
			{
			}
			if (!string.IsNullOrWhiteSpace(text) && !string.Equals(text, itemName, StringComparison.OrdinalIgnoreCase))
			{
				return text;
			}
			string text2 = (itemName ?? string.Empty).Replace("-", " ");
			return CultureInfo.CurrentCulture.TextInfo.ToTitleCase(text2);
		}

		private static void SellBoozeItem(string itemKey, int basePrice, int maxQty = int.MaxValue, string sourceTag = "manual")
		{

			if (_selectedPeep == null)
			{
				return;
			}
			int soldQty;
			int totalEarned;
			if (TryExecuteBoozeSale(_selectedPeep.Id, itemKey, basePrice, maxQty, sourceTag, out soldQty, out totalEarned))
			{
				PopulateBoozeSellPopup();
				RefreshHandlerUI();
			}
		}

		private static CrewModState GetSelectedBoozeCrewState()
		{
			if (_selectedPeep == null || !JailSystem.IsInJail(_selectedPeep.Id))
			{
				return null;
			}
			return GetOrCreateCrewState(_selectedPeep.Id);
		}

		private static BoozeSellMode GetBoozeSellMode(CrewModState state)
		{
			if (state == null)
			{
				return BoozeSellMode.Best;
			}
			return (state.BoozeSellMode == 1) ? BoozeSellMode.Cheapest : BoozeSellMode.Best;
		}

		private static int GetBoozeSmuggleCapacity(CrewModState state)
		{
			return BOOZE_SMUGGLE_BASE_CAP + Mathf.Max(0, state?.StreetCreditLevel ?? 0) * BOOZE_SMUGGLE_PER_LEVEL;
		}

		private static bool IsAllowedJailSmuggleItemKey(string itemKey)
		{
			return !string.IsNullOrWhiteSpace(itemKey) && _jailSmuggleAllowedResourceKeys.Contains(itemKey);
		}

		internal static bool IsBoozeSmuggleItemKey(string itemKey)
		{
			if (string.IsNullOrWhiteSpace(itemKey))
			{
				return false;
			}
			if (_boozeResourceKeys.Contains(itemKey))
			{
				return true;
			}
			try
			{
				Label label = new Label(itemKey);
				Resource resource = Resource.Find(label);
				return IsRecognizedBoozeResource(label, resource, GetKnownBoozeCategories());
			}
			catch
			{
				return false;
			}
		}

		private static HashSet<ResourceCategory> GetKnownBoozeCategories()
		{
			HashSet<ResourceCategory> hashSet = new HashSet<ResourceCategory>();
			foreach (string boozeResourceKey in _boozeResourceKeys)
			{
				try
				{
					Resource resource = Resource.Find(new Label(boozeResourceKey));
					ResourceCategory category = resource?.GetCategory();
					if (category != null)
					{
						hashSet.Add(category);
					}
				}
				catch
				{
				}
			}
			return hashSet;
		}

		private static bool IsRecognizedBoozeResource(Label label, Resource resource, HashSet<ResourceCategory> boozeCategories)
		{
			if (resource == null || !resource.IsBasic)
			{
				return false;
			}
			string text = string.Empty;
			try
			{
				text = label.ToString();
			}
			catch
			{
			}
			if (!string.IsNullOrWhiteSpace(text) && _boozeResourceKeys.Contains(text))
			{
				return true;
			}
			try
			{
				ResourceCategory category = resource.GetCategory();
				return category != null && boozeCategories.Contains(category);
			}
			catch
			{
				return false;
			}
		}

		private static int ResolveBoozeBasePrice(string itemKey, Resource resource)
		{
			if (!string.IsNullOrWhiteSpace(itemKey) && _boozePrices.TryGetValue(itemKey, out int value))
			{
				return value;
			}
			try
			{
				int num = (int)resource.sell;
				if (num > 0)
				{
					return num;
				}
			}
			catch
			{
			}
			try
			{
				int num2 = (int)resource.GetPrice(playerBuying: false, PlayerID.INVALID);
				if (num2 > 0)
				{
					return num2;
				}
			}
			catch
			{
			}
			return 0;
		}

		private static List<BoozeInventoryEntry> GetAvailableBoozeEntries(InventoryModule inventory)
		{
			List<BoozeInventoryEntry> list = new List<BoozeInventoryEntry>();
			if (inventory == null)
			{
				return list;
			}
			foreach (string itemKey in _jailSmuggleAllowedResourceKeys)
			{
				try
				{
					Label key = new Label(itemKey);
					Resource value = null;
					try
					{
						value = Resource.Find(key);
					}
					catch
					{
					}
					int num = ResolveBoozeBasePrice(itemKey, value);
					if (num <= 0)
					{
						continue;
					}
					int num2 = ExtractFixnumAsInt(((Module<InventoryModule, InventoryModuleConfig, InventoryModuleData>)(object)inventory).data.Get(key).qty);
					if (num2 <= 0)
					{
						continue;
					}
					list.Add(new BoozeInventoryEntry
					{
						ItemKey = itemKey,
						Qty = num2,
						BasePrice = num,
						DisplayName = ResolveBoozeDisplayName(itemKey, key, value)
					});
				}
				catch
				{
				}
			}
			return list;
		}

		private static IEnumerable<BoozeInventoryEntry> SortBoozeEntriesForDisplay(IEnumerable<BoozeInventoryEntry> entries, BoozeSellMode mode)
		{
			return (mode == BoozeSellMode.Cheapest) ? entries.OrderBy((BoozeInventoryEntry x) => x.BasePrice).ThenBy((BoozeInventoryEntry x) => x.DisplayName, StringComparer.OrdinalIgnoreCase) : entries.OrderByDescending((BoozeInventoryEntry x) => x.BasePrice).ThenBy((BoozeInventoryEntry x) => x.DisplayName, StringComparer.OrdinalIgnoreCase);
		}

		private static BoozeInventoryEntry SelectPreferredBoozeEntry(List<BoozeInventoryEntry> entries, BoozeSellMode mode)
		{
			if (entries == null || entries.Count == 0)
			{
				return null;
			}
			return SortBoozeEntriesForDisplay(entries, mode).FirstOrDefault();
		}

		private static bool TryGetHumanSafehouseInventory(out PlayerInfo humanPlayer, out InventoryModule inventory, out string failureReason)
		{
			humanPlayer = G.GetHumanPlayer();
			inventory = null;
			failureReason = null;
			if (humanPlayer == null)
			{
				failureReason = "No player found.";
				return false;
			}
			EntityID safehouse = humanPlayer.territory.Safehouse;
			if (safehouse.IsNotValid)
			{
				failureReason = "No safehouse found.";
				return false;
			}
			Entity val = EntityIDExtensions.FindEntity(safehouse);
			if (val == null)
			{
				failureReason = "Safehouse entity not found.";
				return false;
			}
			inventory = ModulesUtil.GetInventory(val);
			if (inventory == null)
			{
				failureReason = "No safehouse inventory.";
				return false;
			}
			return true;
		}

		private static void OnSellPreferredBooze()
		{
			if (_selectedPeep == null)
			{
				return;
			}
			TrySellPreferredBoozeForPeep(_selectedPeep.Id, "manual-preferred");
		}

		private static void OnToggleBoozeSellMode()
		{
			CrewModState selectedBoozeCrewState = GetSelectedBoozeCrewState();
			if (selectedBoozeCrewState == null)
			{
				return;
			}
			selectedBoozeCrewState.BoozeSellMode = ((GetBoozeSellMode(selectedBoozeCrewState) == BoozeSellMode.Best) ? 1 : 0);
			VerificationLog("BoozeSell", $"mode peep={_selectedPeep.Id.id} mode={GetBoozeSellMode(selectedBoozeCrewState)}");
			PopulateBoozeSellPopup();
			RefreshHandlerUI();
		}

		private static void OnToggleBoozeAutoSmuggle()
		{
			CrewModState selectedBoozeCrewState = GetSelectedBoozeCrewState();
			if (selectedBoozeCrewState == null)
			{
				return;
			}
			selectedBoozeCrewState.BoozeAutoSmuggleEnabled = !selectedBoozeCrewState.BoozeAutoSmuggleEnabled;
			VerificationLog("BoozeSell", $"auto peep={_selectedPeep.Id.id} enabled={selectedBoozeCrewState.BoozeAutoSmuggleEnabled}");
			if (IsBoozeSellPopupReady())
			{
				PopulateBoozeSellPopup();
			}
			RefreshHandlerUI();
		}

		private static bool TrySellPreferredBoozeForPeep(EntityID peepId, string sourceTag)
		{
			CrewModState orCreateCrewState = GetOrCreateCrewState(peepId);
			if (orCreateCrewState == null)
			{
				return false;
			}
			if (!TryGetHumanSafehouseInventory(out PlayerInfo _, out InventoryModule inventory, out string failureReason))
			{
				if ((UnityEngine.Object)(object)_boozeSellStatusText != (UnityEngine.Object)null && !string.IsNullOrEmpty(failureReason))
				{
					_boozeSellStatusText.text = failureReason;
				}
				return false;
			}
			List<BoozeInventoryEntry> availableBoozeEntries = GetAvailableBoozeEntries(inventory);
			BoozeInventoryEntry boozeInventoryEntry = SelectPreferredBoozeEntry(availableBoozeEntries, GetBoozeSellMode(orCreateCrewState));
			if (boozeInventoryEntry == null)
			{
				if ((UnityEngine.Object)(object)_boozeSellStatusText != (UnityEngine.Object)null)
				{
					_boozeSellStatusText.text = "No booze found in safehouse.";
				}
				return false;
			}
			int boozeSmuggleCapacity = GetBoozeSmuggleCapacity(orCreateCrewState);
			bool flag = TryExecuteBoozeSale(peepId, boozeInventoryEntry.ItemKey, boozeInventoryEntry.BasePrice, boozeSmuggleCapacity, sourceTag, out int soldQty, out int totalEarned);
			if (flag)
			{
				if ((UnityEngine.Object)(object)_boozeSellStatusText != (UnityEngine.Object)null)
				{
					_boozeSellStatusText.text = $"Sold {soldQty} {boozeInventoryEntry.DisplayName} for ${totalEarned}.";
				}
				PopulateBoozeSellPopup();
				if (_selectedPeep != null && _selectedPeep.Id == peepId)
				{
					RefreshHandlerUI();
				}
			}
			return flag;
		}

		internal static void ProcessAutoSmuggleForJailedCrew(PlayerInfo humanPlayer)
		{
			if (humanPlayer?.crew == null)
			{
				return;
			}
			foreach (CrewAssignment item in humanPlayer.crew.GetLiving().ToList())
			{
				if (!item.IsValid || item.peepId.IsNotValid)
				{
					continue;
				}
				CrewModState crewStateOrNull = GetCrewStateOrNull(item.peepId);
				if (crewStateOrNull == null || !crewStateOrNull.BoozeAutoSmuggleEnabled)
				{
					continue;
				}
				if (!JailSystem.IsInJail(item.peepId) && !crewStateOrNull.InJail)
				{
					continue;
				}
				int days = G.GetNow().days;
				if (crewStateOrNull.LastBoozeSellTurn != 0 && days - crewStateOrNull.LastBoozeSellTurn < BOOZE_SMUGGLE_COOLDOWN_DAYS)
				{
					continue;
				}
				TrySellPreferredBoozeForPeep(item.peepId, "auto");
			}
		}

		private static bool TryExecuteBoozeSale(EntityID peepId, string itemKey, int basePrice, int maxQty, string sourceTag, out int soldQty, out int totalEarned)
		{
			soldQty = 0;
			totalEarned = 0;
			if (peepId.IsNotValid || string.IsNullOrWhiteSpace(itemKey) || basePrice <= 0 || maxQty <= 0)
			{
				return false;
			}
			CrewModState orCreateCrewState = GetOrCreateCrewState(peepId);
			if (orCreateCrewState == null)
			{
				return false;
			}
			try
			{
				if (!IsAllowedJailSmuggleItemKey(itemKey))
				{
					VerificationLog("BoozeSell", $"blocked item={itemKey} reason=not-allowlisted peep={peepId.id} source={sourceTag}");
					if ((UnityEngine.Object)(object)_boozeSellStatusText != (UnityEngine.Object)null)
					{
						_boozeSellStatusText.text = "That item cannot be smuggled to jail.";
					}
					return false;
				}
				if (!TryGetHumanSafehouseInventory(out PlayerInfo humanPlayer, out InventoryModule inventory, out string failureReason))
				{
					if ((UnityEngine.Object)(object)_boozeSellStatusText != (UnityEngine.Object)null && !string.IsNullOrEmpty(failureReason))
					{
						_boozeSellStatusText.text = failureReason;
					}
					return false;
				}
				int days = G.GetNow().days;
				if (orCreateCrewState.LastBoozeSellTurn != 0 && days - orCreateCrewState.LastBoozeSellTurn < BOOZE_SMUGGLE_COOLDOWN_DAYS)
				{
					int num = BOOZE_SMUGGLE_COOLDOWN_DAYS - (days - orCreateCrewState.LastBoozeSellTurn);
					if ((UnityEngine.Object)(object)_boozeSellStatusText != (UnityEngine.Object)null)
					{
						_boozeSellStatusText.text = $"Sell on cooldown: {num}d remaining.";
					}
					return false;
				}
				Label val2 = new Label(itemKey);
				int num2 = 0;
				try
				{
					num2 = ExtractFixnumAsInt(((Module<InventoryModule, InventoryModuleConfig, InventoryModuleData>)(object)inventory).data.Get(val2).qty);
				}
				catch (Exception ex)
				{
					Debug.LogError(("[GameplayTweaks] Could not check " + itemKey + " quantity: " + ex.Message));
					return false;
				}
				if (num2 <= 0)
				{
					return false;
				}
				int num3 = Mathf.Min(num2, Mathf.Max(1, maxQty));
				int num4 = 0;
				try
				{
					((Module<InventoryModule, InventoryModuleConfig, InventoryModuleData>)(object)inventory).data.Increment(val2, -num3);
					num4 = num3;
				}
				catch (Exception ex2)
				{
					Debug.LogWarning(("[GameplayTweaks] Increment removal failed: " + ex2.Message));
					try
					{
						int removed = inventory.TryRemoveResourcesUpToAll(val2, -num3);
						num4 = Math.Abs(removed);
					}
					catch (Exception ex3)
					{
						Debug.LogError(("[GameplayTweaks] Booze removal fallback failed: " + ex3.Message));
					}
				}
				if (num4 <= 0)
				{
					return false;
				}
				int num5 = basePrice * 3 * num4;
				Label val3 = new Label("dirty-cash");
				try
				{
					inventory.ForceAddResourcesRegardlessOfSpace(val3, num5);
				}
				catch
				{
					humanPlayer.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(num5)), (MoneyReason)1);
				}
				orCreateCrewState.LastBoozeSellTurn = days;
				orCreateCrewState.LastBoozeSoldCount = Math.Max(orCreateCrewState.LastBoozeSoldCount, TryGetObservedBoozeSoldCount(peepId));
				ApplyJailSmuggleStreetCred(orCreateCrewState, num4, humanPlayer, peepId, itemKey);
				soldQty = num4;
				totalEarned = num5;
				VerificationLog("BoozeSell", $"sell source={sourceTag} peep={peepId.id} item={itemKey} qty={num4} earned={num5} cap={maxQty}");
				return true;
			}
			catch (Exception arg)
			{
				Debug.LogError($"[GameplayTweaks] SellBoozeItem failed: {arg}");
				return false;
			}
		}

		private static int TryGetObservedBoozeSoldCount(EntityID peepId)
		{
			if (peepId.IsNotValid)
			{
				return 0;
			}
			try
			{
				Entity entity = peepId.FindEntity();
				if (entity?.data?.agent?.crewHistoryStats == null)
				{
					return 0;
				}
				entity.data.agent.crewHistoryStats.TryGetValue((CrewStats)1, out int value);
				return Math.Max(0, value);
			}
			catch
			{
				return 0;
			}
		}

		internal static void ReconcileObservedBoozeStreetCredForCrew(PlayerInfo owner, Entity peep, CrewModState state, SimTime now)
		{
			if (owner?.crew == null || peep == null || !peep.Id.IsValid || state == null)
			{
				return;
			}

			int observedSoldCount = TryGetObservedBoozeSoldCount(peep.Id);
			int deliveredDelta = observedSoldCount - state.LastBoozeSoldCount;
			if (deliveredDelta < 0)
			{
				deliveredDelta = observedSoldCount;
			}
			if (deliveredDelta <= 0)
			{
				state.LastBoozeSoldCount = Math.Max(state.LastBoozeSoldCount, observedSoldCount);
				return;
			}

			CrewAssignment assignment = owner.crew.GetCrewForPeep(peep.Id);
			if (assignment.IsValid && assignment.IsInVehicle && assignment.VehicleID.IsValid)
			{
				HashSet<long> seenOccupants = new HashSet<long>();
				List<CrewAssignment> occupants = MultiCrewVehicleHelper.GetAllCrewInVehicle(owner.crew, assignment.VehicleID)
					.Where(item => item.IsValid
						&& item.peepId.IsValid
						&& seenOccupants.Add((long)item.peepId.id)
						&& MultiCrewVehicleHelper.IsActiveVehicleOccupant(owner.crew, item))
					.ToList();
				if (occupants.Count > 0)
				{
					foreach (CrewAssignment occupant in occupants)
					{
						CrewModState occupantState = GetOrCreateCrewState(occupant.peepId);
					if (occupantState == null)
					{
						continue;
					}
					ApplyBoozeSoldForStreetCred(occupantState, deliveredDelta, owner, occupant.peepId, now, applyHeat: occupant.peepId == peep.Id);
					occupantState.LastBoozeSoldCount = Math.Max(occupantState.LastBoozeSoldCount, observedSoldCount);
				}
					VerificationLog("StreetCredit", $"source=booze-vehicle peep={peep.Id.id} vehicle={assignment.VehicleID.id} sold={deliveredDelta} occupants={occupants.Count}");
					return;
				}
			}

			ApplyBoozeSoldForStreetCred(state, deliveredDelta, owner, peep.Id, now);
			state.LastBoozeSoldCount = observedSoldCount;
		}

		private static int ExtractFixnumAsInt(object fixnum)
		{
			if (fixnum == null)
			{
				return 0;
			}
			try
			{
				return Convert.ToInt32(fixnum);
			}
			catch
			{
			}
			try
			{
				Type type = fixnum.GetType();
				MethodInfo method = type.GetMethod("op_Explicit", BindingFlags.Static | BindingFlags.Public, null, new Type[1] { type }, null);
				if (method != null && method.ReturnType == typeof(int))
				{
					return (int)method.Invoke(null, new object[1] { fixnum });
				}
			}
			catch
			{
			}
			Type type2 = fixnum.GetType();
			string[] array = new string[5] { "v", "_value", "raw", "value", "_v" };
			foreach (string name in array)
			{
				FieldInfo field = type2.GetField(name, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (field != null)
				{
					int num = Convert.ToInt32(field.GetValue(fixnum));
					if (num >= 1000 && num % 1000 == 0)
					{
						return num / 1000;
					}
					return num;
				}
			}
			try
			{
				string s = fixnum.ToString();
				if (int.TryParse(s, out var result))
				{
					return result;
				}
				if (float.TryParse(s, out var result2))
				{
					return (int)result2;
				}
			}
			catch
			{
			}
			return 0;
		}

		internal static Text CreateLabel(Transform parent, string name, string text, int size, FontStyle style)
		{

			GameObject val = new GameObject(name, new Type[3]
			{
				typeof(RectTransform),
				typeof(Text),
				typeof(LayoutElement)
			});
			val.transform.SetParent(parent, false);
			LayoutElement component = val.GetComponent<LayoutElement>();
			int resolvedSize = Math.Max(10, size);
			int scaledSize = Mathf.RoundToInt(resolvedSize * UiTextScale);
			component.minHeight = scaledSize + 9;
			component.preferredHeight = scaledSize + 9;
			Text component2 = val.GetComponent<Text>();
			component2.text = text;
			component2.font = Resources.GetBuiltinResource<Font>("Arial.ttf");
			component2.fontSize = scaledSize;
			((Graphic)component2).color = new Color(0.94f, 0.94f, 0.92f);
			component2.fontStyle = ResolveReadableFontStyle(style);
			component2.alignByGeometry = true;
			component2.supportRichText = false;
			component2.resizeTextForBestFit = false;
			component2.horizontalOverflow = (HorizontalWrapMode)1;
			component2.alignment = (TextAnchor)3;
			Outline outline = val.AddComponent<Outline>();
			((Shadow)outline).effectColor = new Color(0f, 0f, 0f, 0.45f);
			((Shadow)outline).effectDistance = new Vector2(1f, -1f);
			return component2;
		}

		internal static Button CreateButton(Transform parent, string name, string label, Action onClick)
		{

			GameObject val = new GameObject(name, new Type[4]
			{
				typeof(RectTransform),
				typeof(Image),
				typeof(Button),
				typeof(LayoutElement)
			});
			val.transform.SetParent(parent, false);
			LayoutElement component = val.GetComponent<LayoutElement>();
			bool isCloseButton = !string.IsNullOrEmpty(name) && name.IndexOf("close", StringComparison.OrdinalIgnoreCase) >= 0;
			component.minHeight = isCloseButton ? CLOSE_BUTTON_HEIGHT : 30f;
			component.preferredHeight = isCloseButton ? CLOSE_BUTTON_HEIGHT : 30f;
			component.flexibleWidth = isCloseButton ? 0f : 1f;
			if (isCloseButton)
			{
				component.minWidth = CLOSE_BUTTON_WIDTH;
				component.preferredWidth = CLOSE_BUTTON_WIDTH;
			}
			Image component2 = val.GetComponent<Image>();
			((Graphic)component2).color = isCloseButton ? new Color(0.29f, 0.23f, 0.24f, 0.99f) : UI_BUTTON_DARK_GRAY;
			Outline outline = val.AddComponent<Outline>();
			((Shadow)outline).effectColor = new Color(0.78f, 0.82f, 0.9f, 0.45f);
			((Shadow)outline).effectDistance = new Vector2(1f, -1f);
			Button component3 = val.GetComponent<Button>();
			((Selectable)component3).targetGraphic = (Graphic)(object)component2;
			((UnityEvent)component3.onClick).AddListener((UnityAction)delegate
			{
				if (onClick != null) onClick();
			});
			GameObject val2 = new GameObject("Text", new Type[2]
			{
				typeof(RectTransform),
				typeof(Text)
			});
			val2.transform.SetParent(val.transform, false);
			RectTransform component4 = val2.GetComponent<RectTransform>();
			component4.anchorMin = Vector2.zero;
			component4.anchorMax = Vector2.one;
			component4.offsetMin = Vector2.zero;
			component4.offsetMax = Vector2.zero;
			Text component5 = val2.GetComponent<Text>();
			component5.text = label;
			component5.font = Resources.GetBuiltinResource<Font>("Arial.ttf");
			int baseSize = isCloseButton ? 12 : 13;
			component5.fontSize = Mathf.RoundToInt(baseSize * UiTextScale);
			((Graphic)component5).color = isCloseButton ? new Color(0.97f, 0.92f, 0.9f) : new Color(0.96f, 0.96f, 0.95f);
			component5.alignment = (TextAnchor)4;
			component5.fontStyle = (FontStyle)1;
			component5.alignByGeometry = true;
			component5.supportRichText = false;
			component5.resizeTextForBestFit = false;
			Outline textOutline = val2.AddComponent<Outline>();
			((Shadow)textOutline).effectColor = new Color(0f, 0f, 0f, 0.5f);
			((Shadow)textOutline).effectDistance = new Vector2(1f, -1f);
			ApplyStandardButtonTheme(component3, isCloseButton ? UiButtonVariant.Close : ResolveButtonVariant(name));
			return component3;
		}

		internal static UiButtonVariant ResolveButtonVariant(string controlName)
		{
			if (string.IsNullOrEmpty(controlName))
			{
				return UiButtonVariant.Default;
			}
			string text = controlName.ToLowerInvariant();
			if (text.Contains("close"))
			{
				return UiButtonVariant.Close;
			}
			if (text.Contains("deny") || text.Contains("delete") || text.Contains("clear") || text.Contains("remove") || text.Contains("decline") || text.Contains("disappear"))
			{
				return UiButtonVariant.Danger;
			}
			if (text.Contains("accept") || text.Contains("save") || text.Contains("confirm") || text.Contains("collect") || text.Contains("take") || text.Contains("hire") || text.Contains("join") || text.Contains("create"))
			{
				return UiButtonVariant.Success;
			}
			if (text.Contains("toggle") || text.Contains("tier") || text.Contains("verify") || text.Contains("vote"))
			{
				return UiButtonVariant.Accent;
			}
			return UiButtonVariant.Default;
		}

		internal static void ApplyStandardButtonTheme(Button button, UiButtonVariant variant = UiButtonVariant.Default)
		{
			if ((UnityEngine.Object)(object)button == (UnityEngine.Object)null)
			{
				return;
			}
			Image component = ((Component)button).GetComponent<Image>();
			if ((UnityEngine.Object)(object)component == (UnityEngine.Object)null)
			{
				return;
			}
			Color color = UI_BUTTON_DARK_GRAY;
			switch (variant)
			{
			case UiButtonVariant.Accent:
				color = new Color(0.24f, 0.26f, 0.32f, 0.98f);
				break;
			case UiButtonVariant.Success:
				color = new Color(0.23f, 0.29f, 0.24f, 0.98f);
				break;
			case UiButtonVariant.Danger:
				color = new Color(0.31f, 0.23f, 0.24f, 0.98f);
				break;
			case UiButtonVariant.Close:
				color = new Color(0.3f, 0.22f, 0.23f, 0.99f);
				break;
			}
			((Graphic)component).color = color;
			ColorBlock colors = ((Selectable)button).colors;
			colors.normalColor = color;
			colors.highlightedColor = Color.Lerp(color, Color.white, 0.16f);
			colors.pressedColor = Color.Lerp(color, Color.black, 0.24f);
			colors.selectedColor = colors.highlightedColor;
			colors.disabledColor = UI_BUTTON_DARK_GRAY_DISABLED;
			((Selectable)button).colors = colors;
			Outline component2 = ((Component)button).GetComponent<Outline>();
			if ((UnityEngine.Object)(object)component2 == (UnityEngine.Object)null)
			{
				component2 = ((Component)button).gameObject.AddComponent<Outline>();
			}
			((Shadow)component2).effectColor = new Color(0.82f, 0.86f, 0.92f, 0.42f);
			((Shadow)component2).effectDistance = new Vector2(1f, -1f);
			Text componentInChildren = ((Component)button).GetComponentInChildren<Text>();
			if ((UnityEngine.Object)(object)componentInChildren != (UnityEngine.Object)null)
			{
				((Graphic)componentInChildren).color = (variant == UiButtonVariant.Danger || variant == UiButtonVariant.Close) ? new Color(0.99f, 0.94f, 0.93f) : new Color(0.96f, 0.96f, 0.95f);
			}
		}

		internal static void ApplyStandardPanelTheme(GameObject panel, UiPanelVariant variant = UiPanelVariant.Default)
		{
			if ((UnityEngine.Object)(object)panel == (UnityEngine.Object)null)
			{
				return;
			}
			Image component = panel.GetComponent<Image>();
			if ((UnityEngine.Object)(object)component != (UnityEngine.Object)null)
			{
				Color color = ((variant != UiPanelVariant.Header) ? ((variant != UiPanelVariant.Subtle) ? UI_PANEL_DARK_GRAY : UI_PANEL_DARK_GRAY_SUBTLE) : UI_PANEL_DARK_GRAY_HEADER);
				color.a = Mathf.Clamp(((Graphic)component).color.a, 0.78f, 0.99f);
				((Graphic)component).color = color;
			}
			Outline outline = panel.GetComponent<Outline>();
			if ((UnityEngine.Object)(object)outline == (UnityEngine.Object)null)
			{
				outline = panel.AddComponent<Outline>();
			}
			((Shadow)outline).effectColor = new Color(0.72f, 0.76f, 0.84f, 0.36f);
			((Shadow)outline).effectDistance = new Vector2(1f, -1f);
			Shadow shadow = panel.GetComponent<Shadow>();
			if ((UnityEngine.Object)(object)shadow == (UnityEngine.Object)null)
			{
				shadow = panel.AddComponent<Shadow>();
			}
			shadow.effectColor = new Color(0f, 0f, 0f, 0.42f);
			shadow.effectDistance = new Vector2(2f, -2f);
		}

		internal static void RethemeMenuHierarchy(GameObject root)
		{
			if ((UnityEngine.Object)(object)root == (UnityEngine.Object)null)
			{
				return;
			}
			if (TryDelegateMenuRethemeToAfterProhibitionUi(root, ExternalCustomIconsDetected))
			{
				VerificationLog("UITheme", $"delegated root={((UnityEngine.Object)root).name} owner=AfterProhibitionUI");
				return;
			}
			if (ShouldSkipUiRetheme())
			{
				VerificationLog("UITheme", $"external-ui-enhancer detected; keeping GameplayTweaks-owned retheme active root={((UnityEngine.Object)root).name}");
			}
			int num = 0;
			int num2 = 0;
			foreach (Button item in root.GetComponentsInChildren<Button>(true))
			{
				if ((UnityEngine.Object)(object)item != (UnityEngine.Object)null)
				{
					ApplyStandardButtonTheme(item, ResolveButtonVariant(((UnityEngine.Object)item).name));
					num++;
				}
			}
			foreach (Image item2 in root.GetComponentsInChildren<Image>(true))
			{
				if ((UnityEngine.Object)(object)item2 == (UnityEngine.Object)null || ((Component)item2).GetComponent<Button>() != null)
				{
					continue;
				}
				string text = ((UnityEngine.Object)((Component)item2).gameObject).name ?? string.Empty;
				if (text.IndexOf("Fill", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("Bar", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("Swatch", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("Icon", StringComparison.OrdinalIgnoreCase) >= 0)
				{
					continue;
				}
				UiPanelVariant variant = UiPanelVariant.Subtle;
				if (text.IndexOf("Header", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("Tab", StringComparison.OrdinalIgnoreCase) >= 0)
				{
					variant = UiPanelVariant.Header;
				}
				else if (text.IndexOf("Popup", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("Panel", StringComparison.OrdinalIgnoreCase) >= 0 || text == "Bg")
				{
					variant = UiPanelVariant.Default;
				}
				ApplyStandardPanelTheme(((Component)item2).gameObject, variant);
				num2++;
			}
			CrewRelationshipHandlerPatch.SanitizeMissingGlyphsInHierarchy(root, aggressive: ExternalCustomIconsDetected);
			VerificationLog("UITheme", $"rethemed root={((UnityEngine.Object)root).name} buttons={num} panels={num2}");
		}

		private static MethodInfo _afterProhibitionUiRethemeMethod;

		private static bool IsAfterProhibitionUiRethemeBridgeAvailable()
		{
			if (!IsAfterProhibitionUiInstalled())
			{
				return false;
			}

			try
			{
				EnsureAfterProhibitionUiRethemeMethod();
				return _afterProhibitionUiRethemeMethod != null;
			}
			catch
			{
				return false;
			}
		}

		private static void EnsureAfterProhibitionUiRethemeMethod()
		{
			if (_afterProhibitionUiRethemeMethod != null)
			{
				return;
			}

			Type bridgeType = AccessTools.TypeByName("AfterProhibitionUI.UiRethemeBridge");
			_afterProhibitionUiRethemeMethod = bridgeType?.GetMethod(
				"TryRethemeMenuHierarchy",
				BindingFlags.Static | BindingFlags.Public,
				null,
				new[] { typeof(GameObject), typeof(bool) },
				null);
		}

		private static bool TryDelegateMenuRethemeToAfterProhibitionUi(GameObject root, bool aggressiveGlyphCleanup)
		{
			if ((UnityEngine.Object)(object)root == (UnityEngine.Object)null || !IsAfterProhibitionUiInstalled())
			{
				return false;
			}

			try
			{
				EnsureAfterProhibitionUiRethemeMethod();
				if (_afterProhibitionUiRethemeMethod == null)
				{
					return false;
				}

				object result = _afterProhibitionUiRethemeMethod.Invoke(null, new object[] { root, aggressiveGlyphCleanup });
				return result is bool applied && applied;
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] AfterProhibitionUI retheme bridge failed: " + ex.Message);
				return false;
			}
		}

