			}
			LayoutElement layout = ((Component)text).GetComponent<LayoutElement>();
			if ((UnityEngine.Object)(object)layout != (UnityEngine.Object)null)
			{
				layout.minHeight = resolvedSize + 8;
				layout.preferredHeight = resolvedSize + 8;
			}
			Outline outline = ((Component)text).GetComponent<Outline>();
			if ((UnityEngine.Object)(object)outline != (UnityEngine.Object)null)
			{
				UnityEngine.Object.Destroy((UnityEngine.Object)(object)outline);
