		private static List<Entity> FindAllRelatives(Entity peep)
		{

			List<Entity> list = new List<Entity>();
			RelationshipTracker rels = G.GetRels();
			SimTime now = G.GetNow();
			if (rels == null)
			{
				return list;
			}
			HashSet<ulong> seen = new HashSet<ulong>();
			AddHireableRelativesForPeep(list, seen, rels, now, peep);
			VerificationLog("CrewHire", $"family-hire-scope selected={peep.Id.id} hireable={list.Count} scope=selected-crew");
			return list;
		}

		private static void AddHireableRelativesForPeep(List<Entity> relatives, HashSet<ulong> seen, RelationshipTracker rels, SimTime now, Entity sourcePeep)
		{
			if (relatives == null || seen == null || rels == null || sourcePeep == null || !sourcePeep.Id.IsValid)
			{
				return;
			}

			RelationshipList listOrNull = rels.GetListOrNull(sourcePeep.Id);
			if (listOrNull == null)
			{
				return;
			}

			foreach (Relationship datum in listOrNull.data)
			{
				if (datum == null || !datum.IsAnyFamily)
				{
					continue;
				}

				Entity relative = EntityIDExtensions.FindEntity(datum.to);
				if (relative != null && relative.Id.IsValid && !seen.Contains(relative.Id.id) && CanHireFamilyRelative(now, sourcePeep, relative))
				{
					seen.Add(relative.Id.id);
					relatives.Add(relative);
				}
			}
		}

		internal static float GetEffectiveHireableMinAge()
		{
			return Mathf.Max(18f, (HireableMinAge != null) ? HireableMinAge.Value : 18f);
		}

		private static bool CanHireFamilyRelative(SimTime now, Entity sourcePeep, Entity relative)
		{
			if (sourcePeep == null || relative == null || relative.Id == sourcePeep.Id || relative.data?.person == null || relative.data?.agent == null)
			{
				return false;
			}

			PersonData person = relative.data.person;
			if (!person.IsAlive || person.GetAge(now).YearsFloat < GetEffectiveHireableMinAge())
			{
				return false;
			}

			PlayerCrew humanCrew = G.GetHumanCrew();
			if (humanCrew != null && humanCrew.GetCrewForPeep(relative.Id).IsValid)
			{
				return false;
			}

			if (relative.data.agent.pid.id != 0)
			{
				return false;
			}

			if (!CrewHireEligibilityPatch.IsAllowedCrewHireCandidate(relative, out _))
			{
				return false;
			}

			if (G.GetPoliticianData(relative.Id) != null)
			{
				return false;
			}

			return !PotentialBizOwnerEligibilityPatch.IsGangAffiliatedCandidate(relative);
		}

