		private static void OnSaveGangRename()
		{
			if (_gangRenameTarget == null || (UnityEngine.Object)(object)_gangRenameInput == (UnityEngine.Object)null)
			{
				return;
			}
			string text = SanitizeDisplayName(_gangRenameInput.text, 50, "gang-rename", out bool _);
			if (string.IsNullOrEmpty(text))
			{
				VerificationLog("NameSanitize", "sanitized-empty source=gang-rename ignored=true");
				return;
			}
			try
			{
				PlayerSocial social = _gangRenameTarget.social;
				if (social != null)
				{
					MethodInfo method = ((object)social).GetType().GetMethod("ForceGroupNameIfValid", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					if (method != null)
					{
						method.Invoke(social, new object[1] { text });
						Debug.Log(("[GameplayTweaks] Renamed gang to: " + text));
					}
					else
					{
						FieldInfo field = ((object)social).GetType().GetField("_data", BindingFlags.Instance | BindingFlags.NonPublic);
						if (field != null)
						{
							object value = field.GetValue(social);
							FieldInfo field2 = value.GetType().GetField("social", BindingFlags.Instance | BindingFlags.Public);
							if (field2 != null)
							{
								object value2 = field2.GetValue(value);
								FieldInfo field3 = value2.GetType().GetField("groupname", BindingFlags.Instance | BindingFlags.Public);
								if (field3 != null)
								{
									field3.SetValue(value2, text);
									field2.SetValue(value, value2);
									field.SetValue(social, value);
									Debug.Log(("[GameplayTweaks] Renamed gang via fallback to: " + text));
								}
							}
						}
					}
				}
				if ((UnityEngine.Object)(object)_gangRenameNameText != (UnityEngine.Object)null)
				{
					_gangRenameNameText.text = text;
				}
			}
			catch (Exception arg)
			{
				Debug.LogError($"[GameplayTweaks] Gang rename failed: {arg}");
			}
			if ((UnityEngine.Object)(object)_gangRenameRow != (UnityEngine.Object)null)
			{
				UnityEngine.Object.Destroy((UnityEngine.Object)(object)_gangRenameRow);
				_gangRenameRow = null;
			}
			_gangRenameTarget = null;
			_gangRenameNameText = null;
		}
	}

	private static void EnforcePactPeace()
	{
		try
		{
			foreach (AlliancePact pact in SaveData.Pacts)
			{
				if (!pact.IsActive) continue;
				List<int> allMembers = new List<int>();
				if (pact.LeaderGangId >= 0) allMembers.Add(pact.LeaderGangId);
				allMembers.AddRange(pact.MemberIds);
				allMembers = allMembers.Distinct().ToList();
				for (int i = 0; i < allMembers.Count; i++)
				{
					PlayerInfo player1 = G.FindPlayerById(allMembers[i]);
					if (player1 == null || player1.IsHuman) continue;
					object combat1 = player1.ai?.combat;
					if (combat1 == null) continue;
					for (int j = i + 1; j < allMembers.Count; j++)
					{
						PlayerInfo player2 = G.FindPlayerById(allMembers[j]);
						if (player2 == null || player2.IsHuman) continue;
						try
						{
							MethodInfo removeAggro = combat1.GetType().GetMethod("RemoveAggroOn", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
							MethodInfo isAggro = combat1.GetType().GetMethod("IsAggroAnyType", BindingFlags.Instance | BindingFlags.Public);
							if (isAggro != null && (bool)isAggro.Invoke(combat1, new object[] { player2.PID }))
							{
								if (removeAggro != null)
								{
									removeAggro.Invoke(combat1, new object[] { player2.PID });
									MarkCrewPickAggroDirty(player1.PID, "pact-peace");
									MarkCrewPickAggroDirty(player2.PID, "pact-peace");
									// Boss happiness decreases when war is denied by pact
									pact.SetBossHappiness(allMembers[i], pact.GetBossHappiness(allMembers[i]) - 0.1f);
									Debug.Log($"[GameplayTweaks] Pact peace: removed aggro {player1.social?.PlayerGroupName} -> {player2.social?.PlayerGroupName} (happiness -{0.1f})");
								}
							}
							object combat2 = player2.ai?.combat;
							if (combat2 != null && isAggro != null)
							{
								MethodInfo removeAggro2 = combat2.GetType().GetMethod("RemoveAggroOn", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
								MethodInfo isAggro2 = combat2.GetType().GetMethod("IsAggroAnyType", BindingFlags.Instance | BindingFlags.Public);
								if (isAggro2 != null && (bool)isAggro2.Invoke(combat2, new object[] { player1.PID }))
								{
									if (removeAggro2 != null)
									{
										removeAggro2.Invoke(combat2, new object[] { player1.PID });
										MarkCrewPickAggroDirty(player1.PID, "pact-peace");
										MarkCrewPickAggroDirty(player2.PID, "pact-peace");
										// Boss happiness decreases when war is denied by pact
										pact.SetBossHappiness(allMembers[j], pact.GetBossHappiness(allMembers[j]) - 0.1f);
										Debug.Log($"[GameplayTweaks] Pact peace: removed aggro {player2.social?.PlayerGroupName} -> {player1.social?.PlayerGroupName} (happiness -{0.1f})");
									}
								}
							}
						}
						catch { }
					}
				}
			}
			foreach (InterPactAlliance activeInterPactAlliance in GetActiveInterPactAlliances().ToList())
			{
				AlliancePact pactById = GetPactById(activeInterPactAlliance.LeftPactId);
				AlliancePact pactById2 = GetPactById(activeInterPactAlliance.RightPactId);
				if (pactById == null || pactById2 == null)
				{
					continue;
				}
				foreach (int item in GetPactMemberGangIds(pactById))
				{
					PlayerInfo playerById = G.FindPlayerById(item);
					if (playerById == null || playerById.crew == null || playerById.crew.IsCrewDefeated)
					{
						continue;
					}
					foreach (int item2 in GetPactMemberGangIds(pactById2))
					{
						PlayerInfo playerById2 = G.FindPlayerById(item2);
						if (playerById2 == null || playerById2.crew == null || playerById2.crew.IsCrewDefeated)
						{
							continue;
						}
						ClearWarBetweenPlayers(playerById, playerById2);
					}
				}
			}
		}
		catch (Exception arg)
		{
			Debug.LogError($"[GameplayTweaks] EnforcePactPeace failed: {arg}");
		}
	}

		private static void CheckPlayerPactWarKick(SimTime now)
		{
		try
		{
			if (SaveData.PlayerJoinedPactIndex < 0) return;
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (humanPlayer == null) return;
			AlliancePact playerPact = GetPactForPlayer(humanPlayer.PID);
			if (playerPact == null || !playerPact.IsActive) return;
			List<int> allMembers = new List<int>();
			if (playerPact.LeaderGangId >= 0) allMembers.Add(playerPact.LeaderGangId);
			allMembers.AddRange(playerPact.MemberIds);
			allMembers = allMembers.Distinct().ToList();
			bool atWarWithPactMember = false;
			int warTargetId = -1;
			foreach (int memberId in allMembers)
			{
				if (memberId == humanPlayer.PID.id) continue;
				PlayerInfo member = G.FindPlayerById(memberId);
				if (member == null) continue;
				try
				{
					object combat = member.ai?.combat;
					if (combat != null)
					{
						MethodInfo isAggro = combat.GetType().GetMethod("IsAggroWithoutTruce", BindingFlags.Instance | BindingFlags.Public);
						if (isAggro != null && (bool)isAggro.Invoke(combat, new object[] { humanPlayer.PID }))
						{
							atWarWithPactMember = true;
							warTargetId = memberId;
							break;
						}
					}
				}
				catch { }
			}
			if (atWarWithPactMember)
			{
				int graceWeeks = 12;
				bool playerOwnsPact = playerPact.ColorIndex == PLAYER_PACT_SLOT_INDEX && playerPact.LeaderGangId == humanPlayer.PID.id;
				if (SaveData.PlayerPactWarStartDay < 0)
				{
					SaveData.PlayerPactWarStartDay = now.days;
					SaveData.PlayerPactWarTargetId = warTargetId;
					PlayerInfo warTarget = G.FindPlayerById(warTargetId);
					string targetName = warTarget?.social?.PlayerGroupName ?? "a pact member";
					string warningTarget = playerOwnsPact
						? $"PACT: WARNING - War with {targetName}! Make truce within {graceWeeks} weeks or the pact will expel someone."
						: $"PACT: WARNING - War with {targetName}! Make truce within {graceWeeks} weeks or be kicked from pact!";
					LogGrapevine(warningTarget);
					Debug.Log($"[GameplayTweaks] Player at war with pact member {targetName}, grace period started");
				}
				else
				{
					int turnsPassed = (now.days - SaveData.PlayerPactWarStartDay) / 7;
					if (turnsPassed >= graceWeeks)
					{
						PlayerInfo warTarget = G.FindPlayerById(SaveData.PlayerPactWarTargetId);
						string targetName = warTarget?.social?.PlayerGroupName ?? "a pact member";
						int expelledGangId = -1;
						if (playerOwnsPact)
						{
							List<int> pactMemberIds = GameplayTweaksPlugin.GetPactMemberGangIds(playerPact);
							if (SaveData.PlayerPactWarTargetId >= 0
								&& SaveData.PlayerPactWarTargetId != humanPlayer.PID.id
								&& pactMemberIds.Contains(SaveData.PlayerPactWarTargetId))
							{
								expelledGangId = SaveData.PlayerPactWarTargetId;
							}
							else
							{
								expelledGangId = pactMemberIds.FirstOrDefault(id => id >= 0 && id != humanPlayer.PID.id);
							}
						}
						if (playerOwnsPact && expelledGangId >= 0 && expelledGangId != humanPlayer.PID.id)
						{
							string expelledName = GetGangDisplayName(expelledGangId);
							LogGrapevine($"PACT: {expelledName} was expelled from {playerPact.DisplayName} after {graceWeeks} weeks of war with your outfit.");
							Debug.Log($"[GameplayTweaks] Pact war expulsion removed member {expelledName} after {turnsPassed} weeks");
							RemoveGangFromPactMembership(playerPact, expelledGangId, "player-pact-war-expel-member");
						}
						else
						{
							LogGrapevine($"PACT: Your outfit was kicked from {playerPact.DisplayName} for warring with {targetName}!");
							Debug.Log($"[GameplayTweaks] Player kicked from pact after {turnsPassed} weeks at war");
							if (playerPact.ColorIndex == PLAYER_PACT_SLOT_INDEX)
							{
								CrewRelationshipHandlerPatch.LeavePlayerPactForWar(playerPact);
							}
							else
							{
								CrewRelationshipHandlerPatch.LeaveCurrentAIPact();
							}
						}
						SaveData.PlayerPactWarStartDay = -1;
						SaveData.PlayerPactWarTargetId = -1;
						TerritoryColorPatch.RefreshAllTerritoryColors();
					}
				}
			}
			else
			{
				if (SaveData.PlayerPactWarStartDay >= 0)
				{
					Debug.Log("[GameplayTweaks] Player war with pact member resolved - truce achieved");
					LogGrapevine("PACT: Truce achieved! Your position in the pact is safe.");
				}
				SaveData.PlayerPactWarStartDay = -1;
				SaveData.PlayerPactWarTargetId = -1;
			}
		}
		catch (Exception arg)
		{
			Debug.LogError($"[GameplayTweaks] CheckPlayerPactWarKick failed: {arg}");
		}
	}

		private static readonly string[] _retaliationWarBuffIds = new string[3] { "relbuff-pact-leader-killed", "relbuff-pact-boss-killed", "relbuff-gang-death" };

		private static HashSet<int> TryApplyLeaderTruceCascadeForRetaliation(PlayerInfo humanPlayer)
		{
			HashSet<int> neutralizedGangIds = new HashSet<int>();
			if (humanPlayer == null || SaveData?.Pacts == null)
			{
				return neutralizedGangIds;
			}
			try
			{
				foreach (AlliancePact pact in SaveData.Pacts)
				{
					if (pact == null || !pact.IsActive || pact.LeaderGangId < 0)
					{
						continue;
					}
					PlayerInfo leader = G.FindPlayerById(pact.LeaderGangId);
					if (leader == null || leader.PID.id == humanPlayer.PID.id || leader.crew == null || leader.crew.IsCrewDefeated)
					{
						continue;
					}
					if (!HasMutualTruce(leader, humanPlayer))
					{
						continue;
					}
					VerificationLog("PactRetaliation", $"Leader truce detected leader={leader.PID.id} pact={pact.PactId}");
					foreach (int gangId in GetPactMemberGangIds(pact))
					{
						if (gangId < 0 || gangId == humanPlayer.PID.id)
						{
							continue;
						}
						PlayerInfo member = G.FindPlayerById(gangId);
						if (member == null || member.crew == null || member.crew.IsCrewDefeated)
						{
							continue;
						}
						bool hasRetaliationBuff = HasAnyRelationshipBuff(member, humanPlayer, _retaliationWarBuffIds)
							|| HasAnyRelationshipBuff(humanPlayer, member, _retaliationWarBuffIds);
						if (!hasRetaliationBuff)
						{
							continue;
						}
						ClearWarBetweenPlayers(member, humanPlayer);
						RemoveRetaliationBuffsBetween(member, humanPlayer, "leader-truce-cascade");
						neutralizedGangIds.Add(member.PID.id);
						VerificationLog("PactRetaliation", $"Neutralized by leader truce member={member.PID.id} buffReason=true");
					}
				}
			}
			catch (Exception ex)
			{
				Debug.LogWarning($"[GameplayTweaks] Leader-truce retaliation neutralization failed: {ex.Message}");
			}
			return neutralizedGangIds;
		}

		private static void EnforceGangWarFromRetaliationBuffs(PlayerInfo humanPlayer)
		{
			if (humanPlayer == null)
			{
				return;
			}
			if (ShouldDeferRetaliationWarReconciliation())
			{
				return;
			}
			try
			{
				HashSet<int> neutralizedByLeaderTruce = TryApplyLeaderTruceCascadeForRetaliation(humanPlayer);
				foreach (PlayerInfo playerInfo in G.GetAllPlayers())
				{
					if (playerInfo == null || playerInfo.PID.id == humanPlayer.PID.id || !playerInfo.IsJustGang || playerInfo.crew == null || playerInfo.crew.IsCrewDefeated)
					{
						continue;
					}
					bool hasRetaliationBuff = HasAnyRelationshipBuff(playerInfo, humanPlayer, _retaliationWarBuffIds)
						|| HasAnyRelationshipBuff(humanPlayer, playerInfo, _retaliationWarBuffIds);
					if (!hasRetaliationBuff)
					{
						continue;
					}
					if (neutralizedByLeaderTruce.Contains(playerInfo.PID.id))
					{
						VerificationLog("PactRetaliation", $"Re-aggro skipped due leader truce member={playerInfo.PID.id}");
						continue;
					}
					if (HasMutualTruce(playerInfo, humanPlayer))
					{
						ClearWarBetweenPlayers(playerInfo, humanPlayer);
						RemoveRetaliationBuffsBetween(playerInfo, humanPlayer, "direct-truce-active");
						VerificationLog("PactRetaliation", $"Re-aggro skipped due direct truce member={playerInfo.PID.id}");
						continue;
					}
					if (!HasRetaliationWarHeatAgainstHuman(playerInfo, humanPlayer))
					{
						VerificationLog("PactRetaliation", $"Re-aggro dormant; retaliation buffs preserved gang={playerInfo.PID.id} reason=no-warheat-evidence");
						continue;
					}
					ActivateWarBetweenPlayers(playerInfo, humanPlayer);
					VerificationLog("PactRetaliation", $"War reconciliation enforced gang={playerInfo.PID.id} via retaliation buff.");
					Debug.Log($"[GameplayTweaks] Enforced retaliation war for {GetGangDisplayName(playerInfo.PID.id)} due to hostile relationship buff.");
				}
			}
			catch (Exception ex)
			{
				Debug.LogWarning($"[GameplayTweaks] EnforceGangWarFromRetaliationBuffs failed: {ex.Message}");
			}
		}

		private static bool HasRetaliationWarHeatAgainstHuman(PlayerInfo gang, PlayerInfo humanPlayer)
		{
			if (gang == null || humanPlayer == null)
			{
				return false;
			}
			try
			{
				return GetHighestWarHeatForPair(gang.PID.id, humanPlayer.PID.id) > 0.1f;
			}
			catch
			{
				return false;
			}
		}

		private static void RemoveRetaliationBuffsBetween(PlayerInfo gang, PlayerInfo humanPlayer, string reason)
		{
			if (gang == null || humanPlayer == null)
			{
				return;
			}
			foreach (string buffId in _retaliationWarBuffIds)
			{
				RemoveDirectedRelationshipBuff(gang, humanPlayer, buffId);
				RemoveDirectedRelationshipBuff(humanPlayer, gang, buffId);
			}
			VerificationLog("PactRetaliation", $"stale-buffs-cleared gang={gang.PID.id} human={humanPlayer.PID.id} reason={reason}");
		}

	private static class AICrewCapPatch
	{
		private static readonly FieldInfo AiAdvisorPlayerField = AccessTools.Field(typeof(AIAdvisor), "_player");

		public static void ApplyPatch(Harmony harmony)
		{
			try
			{
				MethodInfo method = AccessTools.Method(typeof(UnitsAdvisor), "ShouldGrow");
				if (method != null)
				{
					harmony.Patch(method, postfix: new HarmonyMethod(typeof(AICrewCapPatch), nameof(ShouldGrowPostfix)));
					Debug.Log("[GameplayTweaks] AI crew cap enabled target=Game.Session.Player.AI.UnitsAdvisor.ShouldGrow");
				}
				else
				{
					Debug.LogWarning("[GameplayTweaks] AI crew cap patch skipped: UnitsAdvisor.ShouldGrow not found");
				}
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] AI crew cap patch setup failed: " + ex.Message);
			}
		}

		private static void ShouldGrowPostfix(UnitsAdvisor __instance, ref bool __result)
		{
			try
			{
				PlayerInfo val = AiAdvisorPlayerField?.GetValue(__instance) as PlayerInfo;
				if (val == null || val.crew == null)
				{
					return;
				}
				if (!EnableAIAlliances.Value)
				{
					return;
				}
				PlayerID pID = val.PID;
				if (pID.IsHumanPlayer)
				{
					return;
				}
				int days = G.GetNow().days;
				if (!TryGetNativeAiCrewCap(__instance, pID, out int nativeCap) || !TryBuildGangOpsCrewCapProfile(val, nativeCap, days, out GangOpsCrewCapProfile profile))
				{
					return;
				}
				if (!__result && profile.Deficit > 0 && val.crew.CanAddCrew())
				{
					__result = true;
				}
				Dictionary<int, int> hireCycleDayStore = GetHireCycleDayStore(profile.Channel);
				if (!hireCycleDayStore.TryGetValue(val.PID.id, out int value) || value != days)
				{
					hireCycleDayStore[val.PID.id] = days;
					VerificationLog($"GangOps.{GetGangOpsChannelTag(profile.Channel)}.Hire", $"gang={val.PID.id} tier={profile.Tier} current={profile.LivingCrew} nativeCap={profile.NativeCap} target={profile.TargetCap} deficit={profile.Deficit} baseBonus={profile.BaseBonus} pactBonus={profile.PactBonus} shouldGrow={__result}");
				}
			}
			catch
			{
			}
		}
	}

	private static class PlayerCrewCapPatch
	{
		private static FieldInfo _currentCapField;
		private static FieldInfo _debugCapModField;
		private static int _lastAppliedBonus;

		internal static void ResetRuntime()
		{
			_lastAppliedBonus = 0;
			_currentCapField = null;
			_debugCapModField = null;
		}

		public static void ApplyPatch(Harmony harmony)
		{
			try
			{
				Type type = typeof(GameClock).Assembly.GetType("Game.Session.Player.PlayerCrewGrowth");
				if (type == null)
				{
					Debug.LogWarning("[GameplayTweaks] PlayerCrewCapPatch: PlayerCrewGrowth type not found");
					return;
				}
				MethodInfo method = type.GetMethod("OnPlayerTurnStarted", BindingFlags.Instance | BindingFlags.Public);
				if (method != null)
				{
					harmony.Patch((MethodBase)method,
						new HarmonyMethod(typeof(PlayerCrewCapPatch), "OnPlayerTurnStartedPrefix", (Type[])null),
						new HarmonyMethod(typeof(PlayerCrewCapPatch), "OnPlayerTurnStartedPostfix", (Type[])null),
						(HarmonyMethod)null, (HarmonyMethod)null, (HarmonyMethod)null);
					Debug.Log("[GameplayTweaks] Player crew cap pact bonus patch applied (prefix+postfix)");
				}
			}
			catch (Exception ex) { Debug.LogError($"[GameplayTweaks] PlayerCrewCapPatch.ApplyPatch: {ex.Message}"); }
		}

		private static void OnPlayerTurnStartedPrefix(object __instance, PlayerCrew crew = null)
		{
			try
			{
				if (crew != null && !crew.PID.IsHumanPlayer)
				{
					return;
				}
				int bonusToRemove = Math.Max(0, _lastAppliedBonus);
				if (bonusToRemove == 0) return;
				if (_debugCapModField == null)
					_debugCapModField = __instance.GetType().GetField("_debugCapModifier", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
				if (_debugCapModField != null)
				{
					int current = (int)_debugCapModField.GetValue(__instance);
					int adjusted = Math.Max(0, current - bonusToRemove);
					_debugCapModField.SetValue(__instance, adjusted);
					_lastAppliedBonus = 0;
				}
			}
			catch { }
		}

		private static void OnPlayerTurnStartedPostfix(object __instance, PlayerCrew crew = null)
		{
			long totalTicks = StartPerfTimer();
			try
			{
				if (TryApplyAiGangOpsCrewCap(__instance as PlayerCrewGrowth, crew))
				{
					return;
				}
				PlayerInfo humanPlayer = G.GetHumanPlayer();
				long phaseTicks = StartPerfTimer();
				ShowDeferredHumanRetaliationFrontTickersOnTurnStart(humanPlayer, "player-turn-start");
				LogHumanTurnStartPhase("crew-cap:front-warning-prompts", phaseTicks);
				phaseTicks = StartPerfTimer();
				CleanupPendingRetaliationFrontTickersOnTurnStart("player-turn-start-front-cleanup");
				LogHumanTurnStartPhase("crew-cap:front-cleanup", phaseTicks);
				phaseTicks = StartPerfTimer();
				TurnUpdatePatch.ProcessDeferredAiHumanRobberyResponsesOnHumanTurnStart(humanPlayer, "player-turn-start");
				LogHumanTurnStartPhase("crew-cap:robbery-prompts", phaseTicks);
				phaseTicks = StartPerfTimer();
				CrewRelationshipHandlerPatch.ProcessAutoSmuggleForJailedCrew(humanPlayer);
				LogHumanTurnStartPhase("crew-cap:auto-smuggle", phaseTicks);
				phaseTicks = StartPerfTimer();
				ReconcilePersistentGangRelationshipBuffs("player-turn-start");
				LogHumanTurnStartPhase("crew-cap:reconcile-persistent-buffs", phaseTicks);
				phaseTicks = StartPerfTimer();
				if (!EnableAIAlliances.Value) return;
				AlliancePact playerPact = null;
				if (SaveData.PlayerJoinedPactIndex >= 0)
				{
					playerPact = SaveData.Pacts.FirstOrDefault(p => p.ColorIndex == SaveData.PlayerJoinedPactIndex);
				}
				if (playerPact == null)
				{
					if (humanPlayer != null)
					{
						playerPact = GetPactForPlayer(humanPlayer.PID);
					}
				}
				if (playerPact == null || GetEffectivePactCrewCapacityBonus(playerPact) <= 0) return;
				if (_debugCapModField == null)
					_debugCapModField = __instance.GetType().GetField("_debugCapModifier", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
				if (_debugCapModField != null)
				{
					int current = (int)_debugCapModField.GetValue(__instance);
					int bonus = GetEffectivePactCrewCapacityBonus(playerPact);
					_debugCapModField.SetValue(__instance, current + bonus);
					_lastAppliedBonus = bonus;
					// Recalculate currentCap since it was already computed from old _debugCapModifier
					if (_currentCapField == null)
						_currentCapField = __instance.GetType().GetField("currentCap", BindingFlags.Instance | BindingFlags.Public);
					if (_currentCapField != null)
					{
						object capVal = _currentCapField.GetValue(__instance);
						Type fixnumType = capVal.GetType();
						// Try Fixnum + int
						MethodInfo addOp = fixnumType.GetMethod("op_Addition", BindingFlags.Static | BindingFlags.Public, null,
							new Type[] { fixnumType, typeof(int) }, null);
						if (addOp != null)
						{
							object newCap = addOp.Invoke(null, new object[] { capVal, bonus });
							_currentCapField.SetValue(__instance, newCap);
						}
						else
						{
							// Fallback: try Fixnum + Fixnum with int->Fixnum conversion
							MethodInfo implicitOp = fixnumType.GetMethod("op_Implicit", BindingFlags.Static | BindingFlags.Public, null,
								new Type[] { typeof(int) }, null);
							MethodInfo addOp2 = fixnumType.GetMethod("op_Addition", BindingFlags.Static | BindingFlags.Public, null,
								new Type[] { fixnumType, fixnumType }, null);
							if (implicitOp != null && addOp2 != null)
							{
								object bonusFixnum = implicitOp.Invoke(null, new object[] { bonus });
								object newCap = addOp2.Invoke(null, new object[] { capVal, bonusFixnum });
								_currentCapField.SetValue(__instance, newCap);
							}
							else
							{
								// Last resort: explicit cast (Fixnum)(int)
								MethodInfo explicitOp = fixnumType.GetMethod("op_Explicit", BindingFlags.Static | BindingFlags.Public, null,
									new Type[] { typeof(int) }, null);
								if (explicitOp != null && addOp2 != null)
								{
									object bonusFixnum = explicitOp.Invoke(null, new object[] { bonus });
									object newCap2 = addOp2.Invoke(null, new object[] { capVal, bonusFixnum });
									_currentCapField.SetValue(__instance, newCap2);
								}
							}
						}
					}
					Debug.Log($"[GameplayTweaks] Player crew cap: +{bonus} from pact (debugMod now {current + bonus})");
				}
				LogHumanTurnStartPhase("crew-cap:pact-bonus", phaseTicks);
			}
			catch (Exception ex) { Debug.LogError($"[GameplayTweaks] PlayerCrewCapPatch postfix: {ex.Message}"); }
			finally
			{
				LogHumanTurnStartPhase("crew-cap:total", totalTicks);
			}
		}

		private static bool TryApplyAiGangOpsCrewCap(PlayerCrewGrowth growth, PlayerCrew crew)
		{
			try
			{
				if (growth == null || crew == null || crew.PID.IsHumanPlayer || !EnableAIAlliances.Value)
				{
					return false;
				}
				PlayerInfo gang = crew.PID.FindPlayer();
				UnitsAdvisor unitsAdvisor = gang?.ai?.units;
				if (gang == null || unitsAdvisor == null || !gang.IsJustGang || gang.crew == null || gang.crew.IsCrewDefeated)
				{
					return true;
				}
				int days = G.GetNow().days;
				if (!TryGetNativeAiCrewCap(unitsAdvisor, gang.PID, out int nativeUnitsCap) || !TryBuildGangOpsCrewCapProfile(gang, nativeUnitsCap, days, out GangOpsCrewCapProfile profile))
				{
					return true;
				}
				if (!IsGangOpsHirePressureCapOpen(profile.Channel, gang.PID.id, days, out int capOpenUntilDay))
				{
					return true;
				}
				int currentCrewGrowthCap = growth.currentCap.IntFloor();
				if (profile.TargetCap > currentCrewGrowthCap)
				{
					growth.currentCap = profile.TargetCap;
					growth.isDirty = true;
					Dictionary<int, int> crewCapLogStore = GetRuntimeGangOpsDayStore(GangOpsCrewCapLastLogDayByGang, profile.Channel);
					if (!crewCapLogStore.TryGetValue(gang.PID.id, out int lastLogDay) || days - lastLogDay >= GangOpsCrewCapLogIntervalDays)
					{
						crewCapLogStore[gang.PID.id] = days;
						VerificationLog($"GangOps.{GetGangOpsChannelTag(profile.Channel)}.CrewCap", $"gang={gang.PID.id} tier={profile.Tier} current={profile.LivingCrew} crewGrowthCap={currentCrewGrowthCap} nativeCap={profile.NativeCap} target={profile.TargetCap} deficit={profile.Deficit} baseBonus={profile.BaseBonus} pactBonus={profile.PactBonus} capOpenUntil={capOpenUntilDay} logCooldownDays={GangOpsCrewCapLogIntervalDays}");
					}
				}
				return true;
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] AI GangOps crew cap apply failed: " + ex.Message);
				return true;
			}
		}
	}

