		{
			return GetCopTracker() != null;
		}

		public static bool ArrestCrew(PlayerInfo player, Entity peep)
		{
			if (player?.crew == null || peep == null)
			{
				return false;
			}
			CrewAssignment crewForPeep = player.crew.GetCrewForPeep(peep.Id);
			if (!crewForPeep.IsValid)
			{
				return false;
			}
			if (GameplayTweaksPlugin.ShouldDeferArrestForHideout(peep.Id, "jailsystem-arrest"))
			{
				return false;
			}
			bool gameInvokeSucceeded = false;
			if (player.PID.IsHumanPlayer)
			{
				GameplayTweaksPlugin.CaptureDirectArrestVehicleSnapshot(player, crewForPeep, null, "jailsystem-safe-federal");
				if (GameplayTweaksPlugin.TryHandleSafeFederalHumanArrest(player, crewForPeep, "jailsystem-safe-federal"))
				{
					return true;
				}
			}
			try
			{
				object copTracker = GetCopTracker();
				if (copTracker != null && _startHumanArrestMethod != null)
				{
					_startHumanArrestMethod.Invoke(copTracker, new object[2] { player, crewForPeep });
					gameInvokeSucceeded = true;
				}
			}
			catch (Exception arg)
			{
				Debug.LogError($"[GameplayTweaks] ArrestCrew game invoke failed: {arg}");
			}
			bool safeFederalLaneHandled = GameplayTweaksPlugin.WasSafeFederalArrestHandledToday(peep.Id);
			if (safeFederalLaneHandled)
			{
				return true;
			}
			// Ensure arrested crew fully leaves board state even if the game arrest path only partially cleaned up.
			EnsureCrewRemovedFromBoardAfterArrest(player, crewForPeep, peep, (!gameInvokeSucceeded || !player.PID.IsHumanPlayer) ? "arrest-fallback" : "arrest-postgame");
			CrewModState orCreateCrewState = GetOrCreateCrewState(peep.Id);
			if (orCreateCrewState != null)
			{
				orCreateCrewState.InJail = true;
				orCreateCrewState.DaysInJail = 0;
				orCreateCrewState.TrialDaysRemaining = 7;
				orCreateCrewState.FedsIncoming = false;
				ClearJailBlockedAwayStates(peep, orCreateCrewState, "arrest", custodyAlreadyConfirmed: true);
			}
			VerificationLog("DeathAttribution", $"source=raid peep={peep.Id.id} action=arrest");
			RecordDeathSource(peep.Id, "raid");
			RefreshHumanStateAfterArrest(player, crewForPeep);
			if (gameInvokeSucceeded)
			{
				Debug.Log(("[GameplayTweaks] " + peep.data.person.FullName + " arrested via game system"));
			}
			return true;
		}

		internal static bool TryApplySentenceBoost(EntityID peepId, int extraYears)
		{
			return TryApplySentenceBoost(peepId, extraYears, out _);
		}

		internal static bool TryApplySentenceBoost(EntityID peepId, int extraYears, out string appliedDetails)
		{
			appliedDetails = "none";
			if (extraYears <= 0 || peepId.IsNotValid)
			{
				return false;
			}
			try
			{
				object copTracker = GetCopTracker();
				if (copTracker == null || _copTrackerType == null)
				{
					return false;
				}
				object data = _copTrackerType.GetField("data", BindingFlags.Instance | BindingFlags.Public)?.GetValue(copTracker);
				if (data == null)
				{
					return false;
				}
				List<string> appliedTargets = new List<string>();
				bool applied = false;
				applied |= TryApplySentenceBoostToRecordList(data, "fedImprisoned", peepId, extraYears, appliedTargets);
				appliedDetails = appliedTargets.Count > 0 ? string.Join(",", appliedTargets) : "none";
				return applied;
			}
			catch
			{
				appliedDetails = "error";
				return false;
			}
		}

		private static bool TryApplySentenceBoostToRecordList(object data, string fieldName, EntityID peepId, int extraYears, List<string> appliedTargets)
		{
			if (data == null || string.IsNullOrEmpty(fieldName))
			{
				return false;
			}
			FieldInfo listField = data.GetType().GetField(fieldName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (listField == null || !(listField.GetValue(data) is IList list))
			{
				return false;
			}
			foreach (object record in list)
			{
				if (record == null)
				{
					continue;
				}
				FieldInfo peepField = record.GetType().GetField("peepId", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (peepField == null)
				{
					continue;
				}
				object peepObj = peepField.GetValue(record);
				if (!(peepObj is EntityID recordPeepId) || recordPeepId != peepId)
				{
					continue;
				}
				bool boosted = false;
				FieldInfo trialDateField = record.GetType().GetField("trialDate", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (trialDateField != null && trialDateField.FieldType == typeof(SimTime))
				{
					SimTime currentTrialDate = (SimTime)trialDateField.GetValue(record);
					trialDateField.SetValue(record, currentTrialDate.IncrementDays(extraYears * 7));
					appliedTargets?.Add(fieldName + ".trialDate");
					boosted = true;
				}

				FieldInfo endDateField = record.GetType().GetField("endDate", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (endDateField != null && endDateField.FieldType == typeof(SimTime))
				{
					SimTime currentEndDate = (SimTime)endDateField.GetValue(record);
					endDateField.SetValue(record, currentEndDate.IncrementYears(extraYears));
					appliedTargets?.Add(fieldName + ".endDate");
					boosted = true;
				}

				foreach (FieldInfo intField in record.GetType().GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
				{
					if (intField.FieldType != typeof(int))
					{
						continue;
					}
					string fname = intField.Name ?? string.Empty;
					if (fname.IndexOf("year", StringComparison.OrdinalIgnoreCase) < 0 && fname.IndexOf("sentence", StringComparison.OrdinalIgnoreCase) < 0)
					{
						continue;
					}
					int currentYears = (int)intField.GetValue(record);
					intField.SetValue(record, currentYears + extraYears);
					appliedTargets?.Add(fieldName + "." + fname);
					boosted = true;
				}
				return boosted;
			}
			return false;
		}

		public static bool IsInJail(EntityID peepId)
		{
			if (GameplayTweaksPlugin.IsSafeFederalArrestPendingToday(peepId))
			{
				return true;
			}

			try
			{
				object copTracker = GetCopTracker();
				if (copTracker == null)
				{
					return false;
				}
				MethodInfo method = _copTrackerType.GetMethod("IsArrestedOrImprisoned", BindingFlags.Instance | BindingFlags.Public);
				if (method != null)
				{
					return (bool)method.Invoke(copTracker, new object[1] { peepId });
				}
			}
			catch
			{
			}
			return false;
		}

		public static (int daysToTrial, int bribeCost, bool isPaidOff) GetArrestInfo(EntityID peepId)
		{

			try
			{
				object copTracker = GetCopTracker();
				if (copTracker == null)
				{
					return (daysToTrial: 0, bribeCost: 0, isPaidOff: false);
				}
				object obj = _copTrackerType.GetField("data", BindingFlags.Instance | BindingFlags.Public)?.GetValue(copTracker);
				if (obj == null)
				{
					return (daysToTrial: 0, bribeCost: 0, isPaidOff: false);
				}
				if (!(obj.GetType().GetField("fedArrests", BindingFlags.Instance | BindingFlags.Public)?.GetValue(obj) is IList list))
				{
					return (daysToTrial: 0, bribeCost: 0, isPaidOff: false);
				}
				foreach (object item4 in list)
				{
					if ((EntityID)item4.GetType().GetField("peepId", BindingFlags.Instance | BindingFlags.Public).GetValue(item4) == peepId)
					{
						FieldInfo field = item4.GetType().GetField("trialDate", BindingFlags.Instance | BindingFlags.Public);
						FieldInfo field2 = item4.GetType().GetField("payOffCost", BindingFlags.Instance | BindingFlags.Public);
						FieldInfo field3 = item4.GetType().GetField("paidOff", BindingFlags.Instance | BindingFlags.Public);
						SimTime val = (SimTime)field.GetValue(item4);
						object value = field2.GetValue(item4);
						bool item = (bool)field3.GetValue(item4);
						int item2 = val.days - G.GetNow().days;
						int item3 = 0;
						try
						{
							item3 = (int)value.GetType().GetField("cash", BindingFlags.Instance | BindingFlags.Public).GetValue(value);
						}
						catch
						{
						}
						return (daysToTrial: item2, bribeCost: item3, isPaidOff: item);
					}
				}
			}
			catch
			{
			}
			return (daysToTrial: 0, bribeCost: 0, isPaidOff: false);
		}

		internal static bool TryBuildFederalArrestRecord(PlayerInfo player, CrewAssignment crew, Node node, out ArrestEntry arrestEntry)
		{
			arrestEntry = null;
			if (player == null || !crew.IsValid || node == null)
			{
				return false;
			}

			try
			{
				PoliceSettings.Feds fedsSettings = global::Game.Game.serv?.globals?.settings?.people?.social?.police?.feds;
				if (fedsSettings == null)
				{
					return false;
				}

				Fixnum arrestDays = fedsSettings.arrestDayz.Evaluate(player.PID, node);
				int bribeCost = fedsSettings.arrestBribe.Evaluate(player.PID, node).RoundCoarse();
				SimTime trialDate = global::Game.Game.ctx.clock.Now.IncrementDays(arrestDays.IntFloor());
				arrestEntry = new ArrestEntry
				{
					peepId = crew.peepId,
					playerId = player.PID,
					trialDate = trialDate,
					payOffCost = new Price((Fixnum)bribeCost),
					paidOff = false
				};
				return true;
			}
			catch
			{
				arrestEntry = null;
				return false;
			}
		}

		internal static bool TryAddDeferredFederalArrestRecord(PlayerID playerId, EntityID peepId, SimTime trialDate, int bribeCost)
		{
			if (!playerId.IsValid || peepId.IsNotValid)
			{
				return false;
			}

			try
			{
				object copTracker = GetCopTracker();
				if (copTracker == null || _copTrackerType == null)
				{
					return false;
				}

				object data = _copTrackerType.GetField("data", BindingFlags.Instance | BindingFlags.Public)?.GetValue(copTracker);
				if (data == null)
				{
					return false;
				}

				FieldInfo fedArrestsField = data.GetType().GetField("fedArrests", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (fedArrestsField == null || !(fedArrestsField.GetValue(data) is IList list))
				{
					return false;
				}

				foreach (object record in list)
				{
					if (record == null)
					{
						continue;
					}

					FieldInfo peepField = record.GetType().GetField("peepId", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
					if (peepField != null && peepField.GetValue(record) is EntityID existingPeepId && existingPeepId == peepId)
					{
						return true;
					}
				}

				list.Add(new ArrestEntry
				{
					peepId = peepId,
					playerId = playerId,
					trialDate = trialDate,
					payOffCost = new Price((Fixnum)bribeCost),
					paidOff = false
				});
				return true;
			}
			catch
			{
				return false;
			}
		}

		public static (int daysRemaining, int totalYears) GetImprisonmentInfo(EntityID peepId)
		{

			try
			{
				object copTracker = GetCopTracker();
				if (copTracker == null)
				{
					return (daysRemaining: 0, totalYears: 0);
				}
				object obj = _copTrackerType.GetField("data", BindingFlags.Instance | BindingFlags.Public)?.GetValue(copTracker);
				if (obj == null)
				{
					return (daysRemaining: 0, totalYears: 0);
				}
				if (!(obj.GetType().GetField("fedImprisoned", BindingFlags.Instance | BindingFlags.Public)?.GetValue(obj) is IList list))
				{
					return (daysRemaining: 0, totalYears: 0);
				}
				foreach (object item2 in list)
				{
					if ((EntityID)item2.GetType().GetField("peepId", BindingFlags.Instance | BindingFlags.Public).GetValue(item2) == peepId)
					{
						FieldInfo field = item2.GetType().GetField("endDate", BindingFlags.Instance | BindingFlags.Public);
						FieldInfo field2 = item2.GetType().GetField("years", BindingFlags.Instance | BindingFlags.Public);
						SimTime val = (SimTime)field.GetValue(item2);
						int item = (int)field2.GetValue(item2);
						return (daysRemaining: val.days - G.GetNow().days, totalYears: item);
					}
				}
			}
			catch
			{
			}
			return (daysRemaining: 0, totalYears: 0);
		}

		public static void PayLawyerRetainer(EntityID peepId, int amount)
		{
			if (amount <= 0)
			{
				VerificationLog("Retainer", $"payment-blocked peep={peepId.id} amount={amount} reason=non-positive-amount");
				return;
			}

			CrewModState orCreateCrewState = GetOrCreateCrewState(peepId);
			if (orCreateCrewState != null)
			{
				orCreateCrewState.LawyerRetainer += amount;
				Debug.Log($"[GameplayTweaks] Lawyer retainer paid: ${amount}, total: ${orCreateCrewState.LawyerRetainer}");
			}
		}

		public static string GetJailStatusString(EntityID peepId)
		{
			GameplayTweaksPlugin.ReconcileCrewJailState(peepId, "status-string");
			CrewModState state = GetCrewStateOrNull(peepId);
			int extraWitnessYears = Mathf.Max(0, state?.ExtraJailYears ?? 0);
			int visibleSentenceYears = GetVisibleImportantWitnessSentenceYears(NATIONAL_HEAT_SOURCE_COP_ASSAULT, extraWitnessYears);
			if (!IsInJail(peepId))
			{
				if (GameplayTweaksPlugin.TryGetLocalImportantWitnessCustodyPendingInfo(peepId, out LocalImportantWitnessCustodyPendingInfo pendingInfo) && pendingInfo != null)
				{
					int pendingTrialDays = Mathf.Max(Mathf.Max(0, pendingInfo.TrialDaysRemaining), state?.TrialDaysRemaining ?? 0);
					int pendingExtraYears = Mathf.Max(extraWitnessYears, Mathf.Max(0, pendingInfo.ExtraJailYears));
					int pendingVisibleSentenceYears = GetVisibleImportantWitnessSentenceYears(NATIONAL_HEAT_SOURCE_COP_ASSAULT, pendingExtraYears);
					if (pendingTrialDays > 0 && pendingExtraYears > 0)
					{
						VerificationLog("NationalHeat", $"sentence-boost-local-status-applied peep={peepId.id} trialDays={pendingTrialDays} extraYears={pendingExtraYears} totalYears={pendingVisibleSentenceYears} pendingOnly=True");
						return $"Awaiting Trial - {pendingTrialDays} days ({pendingVisibleSentenceYears} year sentence)";
					}
					if (pendingTrialDays > 0)
					{
						return $"Awaiting Trial - {pendingTrialDays} days";
					}
					if (pendingExtraYears > 0)
					{
						VerificationLog("NationalHeat", $"sentence-boost-local-status-applied peep={peepId.id} trialDays=0 extraYears={pendingExtraYears} totalYears={pendingVisibleSentenceYears} pendingOnly=True");
						return $"Awaiting Trial ({pendingVisibleSentenceYears} year sentence)";
					}
					return "Awaiting Trial";
				}
				return null;
			}
			var (num, num2, flag) = GetArrestInfo(peepId);
			if (num > 0)
			{
				if (flag)
				{
					return $"Arrested - Trial in {num} days (Bribed)";
				}
				if (extraWitnessYears > 0)
				{
					return $"Arrested - Trial in {num} days ({visibleSentenceYears} year sentence)";
				}
				return $"Arrested - Trial in {num} days (Bribe: ${num2})";
			}
			var (num3, num4) = GetImprisonmentInfo(peepId);
			if (num3 > 0)
			{
				return $"In Prison - {num3} days remaining ({num4} year sentence)";
			}
			if (num4 > 0)
			{
				return $"In Prison - release pending ({num4} year sentence)";
			}
			if (flag || num2 > 0)
			{
				return "Arrested - Trial pending";
			}
			if (state != null && state.InJail)
			{
				if (state.TrialDaysRemaining > 0 && extraWitnessYears > 0)
				{
					VerificationLog("NationalHeat", $"sentence-boost-local-status-applied peep={peepId.id} trialDays={state.TrialDaysRemaining} extraYears={extraWitnessYears} totalYears={visibleSentenceYears}");
					return $"Arrested - Trial in {state.TrialDaysRemaining} days ({visibleSentenceYears} year sentence)";
				}
				if (state.TrialDaysRemaining > 0)
				{
					return $"Arrested - Trial in {state.TrialDaysRemaining} days";
				}
				if (extraWitnessYears > 0)
				{
					VerificationLog("NationalHeat", $"sentence-boost-local-status-applied peep={peepId.id} trialDays=0 extraYears={extraWitnessYears} totalYears={visibleSentenceYears}");
					return $"In Jail ({visibleSentenceYears} year sentence)";
				}
			}
			return "In Jail";
		}
	}

