		internal static bool ShouldUseExternalSafeboxUI()
		{
			bool localDetection = ExternalSafeboxDetected || ExternalModLauncherSafeboxDetected;
			if (TryGetAfterProhibitionCompatibilitySafeboxUi(out bool bridgeDetection))
			{
				return bridgeDetection || localDetection;
			}

			return localDetection;
		}

	internal static bool ShouldDeferDirtyCashRuntime()
	{
		return ExternalDirtyCashEconomyDetected;
	}

	internal static bool ShouldDeferRetaliationWarReconciliation()
	{
		if (CompatDisableRetaliationWarWithGangWars == null || !CompatDisableRetaliationWarWithGangWars.Value)
		{
			return false;
		}
		return ExternalGangWarsDetected;
	}

	internal static bool ShouldDeferTerritoryVisualOverrides()
	{
		if (CompatDisableTerritoryVisualsWithExternalTerritoryMods == null || !CompatDisableTerritoryVisualsWithExternalTerritoryMods.Value)
		{
			return false;
		}
		return ExternalTerritoryExpansionDetected || ExternalMafiaHierarchyDetected || ExternalGangWarsDetected;
	}

