	internal static float GetNaturalCauseDeathChance(float yearsFloat)
	{
		if (yearsFloat < 72f)
		{
			return 0f;
		}
		float annualChance;
		if (yearsFloat < 76f)
		{
			annualChance = 0.01f + (yearsFloat - 72f) * 0.005f;
		}
		else if (yearsFloat < 81f)
		{
			annualChance = 0.03f + (yearsFloat - 76f) * 0.01f;
		}
		else if (yearsFloat < 86f)
		{
			annualChance = 0.08f + (yearsFloat - 81f) * 0.016f;
		}
		else if (yearsFloat < 91f)
		{
			annualChance = 0.16f + (yearsFloat - 86f) * 0.028f;
		}
		else
		{
			annualChance = Mathf.Min(0.45f, 0.30f + (yearsFloat - 91f) * 0.03f);
		}
		annualChance = Mathf.Clamp01(annualChance);
		return 1f - Mathf.Pow(1f - annualChance, 1f / 365f);
	}

	internal static void ApplyCoreCheatCompatibilityGuards()
	{
		if (CompatEnableCoreCheatMenuAdapter != null && !CompatEnableCoreCheatMenuAdapter.Value)
		{
			VerificationLog("Compat", "cheatCoreAdapter=inactive reason=config-disabled");
			return;
		}
		if (!ExternalCoreCheatMenuDetected)
		{
			VerificationLog("Compat", "cheatCoreAdapter=inactive reason=core-cheat-not-detected");
			return;
		}
		string authorityMode = ShouldKeepGameplayTweaksCheatAuthority() ? "gameplaytweaks" : "external";
		VerificationLog("Compat", $"cheatCoreAdapter=active authority={authorityMode}");
	}

	internal static GangMeetingMode GetGangMeetingMode()
	{
		if (SaveData == null)
		{
			return GangMeetingMode.Auto;
		}
		GangMeetingMode gangMeetingMode = SaveData.GangMeetingMode;
		if (gangMeetingMode < GangMeetingMode.Disabled || gangMeetingMode > GangMeetingMode.Auto)
		{
			gangMeetingMode = (SaveData.GangMeetingsEnabled ? GangMeetingMode.Auto : GangMeetingMode.Prompt);
			SaveData.GangMeetingMode = gangMeetingMode;
		}
		SaveData.GangMeetingsEnabled = gangMeetingMode == GangMeetingMode.Auto;
		return gangMeetingMode;
	}

	internal static GangMeetingMode CycleGangMeetingMode()
	{
		GangMeetingMode gangMeetingMode = GetGangMeetingMode();
		switch (gangMeetingMode)
		{
		case GangMeetingMode.Disabled:
			gangMeetingMode = GangMeetingMode.Prompt;
			break;
		case GangMeetingMode.Prompt:
			gangMeetingMode = GangMeetingMode.Auto;
			break;
		default:
			gangMeetingMode = GangMeetingMode.Disabled;
			break;
		}
		SaveData.GangMeetingMode = gangMeetingMode;
		SaveData.GangMeetingsEnabled = gangMeetingMode == GangMeetingMode.Auto;
		return gangMeetingMode;
	}

	internal static string GetGangMeetingModeUiLabel(GangMeetingMode mode)
	{
		switch (mode)
		{
		case GangMeetingMode.Disabled:
			return "Outings: Disabled";
		case GangMeetingMode.Prompt:
			return "Outings: Prompt";
		default:
			return "Outings: Auto";
		}
	}

	private static GangMeetingMode ResolveGangMeetingModeFromLegacy(int explicitModeRaw, bool legacyToggleValue, bool explicitModePresent)
	{
		if (explicitModePresent && explicitModeRaw >= 0 && explicitModeRaw <= 2)
		{
			return (GangMeetingMode)explicitModeRaw;
		}
		return legacyToggleValue ? GangMeetingMode.Auto : GangMeetingMode.Prompt;
	}

	internal static void NormalizeGangMeetingModeState()
	{
		GangMeetingMode gangMeetingMode = GetGangMeetingMode();
		SaveData.GangMeetingMode = gangMeetingMode;
		SaveData.GangMeetingsEnabled = gangMeetingMode == GangMeetingMode.Auto;
	}

	private static PactOpsSettings BuildGangOpsDefaultsFromConfig(GangOpsChannel channel)
	{
		PactOpsSettings pactOpsSettings = new PactOpsSettings();
		if (channel == GangOpsChannel.Independent)
		{
			pactOpsSettings.Enabled = GangOpsDefaultsIndependentEnabled?.Value ?? true;
			pactOpsSettings.AutoProtectEnabled = GangOpsDefaultsIndependentAutoProtectEnabled?.Value ?? true;
			pactOpsSettings.AutoProtectIntervalDays = GangOpsDefaultsIndependentAutoProtectIntervalDays?.Value ?? 4;
			pactOpsSettings.AutoProtectRange = GangOpsDefaultsIndependentAutoProtectRange?.Value ?? 1;
			pactOpsSettings.CoordinatedAttackAutoEnabled = (GangOpsDefaultsIndependentCoordinatedAttackAutoEnabled?.Value ?? false) || ShouldForceIndependentCoordAutoDefaults();
			pactOpsSettings.CoordinatedAttackCooldownDays = GangOpsDefaultsIndependentCoordinatedAttackCooldownDays?.Value ?? 16;
			pactOpsSettings.CoordinatedAttackMinCrew = GangOpsDefaultsIndependentCoordinatedAttackMinCrew?.Value ?? 1;
			pactOpsSettings.CoordinatedAttackMaxCrew = GangOpsDefaultsIndependentCoordinatedAttackMaxCrew?.Value ?? 2;
			pactOpsSettings.RevengeEnabled = GangOpsDefaultsIndependentRevengeEnabled?.Value ?? true;
			pactOpsSettings.RevengeDelayDays = GangOpsDefaultsIndependentRevengeDelayDays?.Value ?? 12;
			pactOpsSettings.WarHeatDecayPerWeek = GangOpsDefaultsIndependentWarHeatDecayPerWeek?.Value ?? 8f;
			pactOpsSettings.WarHeatAttackGain = GangOpsDefaultsIndependentWarHeatAttackGain?.Value ?? 16f;
			pactOpsSettings.WarHeatKillGain = GangOpsDefaultsIndependentWarHeatKillGain?.Value ?? 35f;
			pactOpsSettings.TerritoryTakeoverAggressionPercent = GangOpsDefaultsIndependentTerritoryTakeoverAggressionPercent?.Value ?? IndependentTerritoryTakeoverAggressionDefault;
			pactOpsSettings.FrontClosureAggressionPercent = GangOpsDefaultsIndependentFrontClosureAggressionPercent?.Value ?? IndependentFrontClosureAggressionDefault;
			pactOpsSettings.OverallAggroPercent = GangOpsDefaultsIndependentOverallAggroPercent?.Value ?? IndependentOverallAggroDefault;
			pactOpsSettings.HireAutomationEnabled = GangOpsDefaultsIndependentHireAutomationEnabled?.Value ?? IndependentHireAutomationDefault;
			pactOpsSettings.TopGangCrewBonusMin = GangOpsDefaultsIndependentTopGangCrewBonusMin?.Value ?? IndependentTopGangCrewBonusMinDefault;
			pactOpsSettings.TopGangCrewBonusMax = GangOpsDefaultsIndependentTopGangCrewBonusMax?.Value ?? IndependentTopGangCrewBonusMaxDefault;
			pactOpsSettings.MidGangCrewBonus = GangOpsDefaultsIndependentMidGangCrewBonus?.Value ?? IndependentMidGangCrewBonusDefault;
			pactOpsSettings.BottomGangCrewBonus = GangOpsDefaultsIndependentBottomGangCrewBonus?.Value ?? IndependentBottomGangCrewBonusDefault;
			pactOpsSettings.PactCrewBonus = GangOpsDefaultsIndependentPactCrewBonus?.Value ?? 0;
			return pactOpsSettings;
		}
		pactOpsSettings.Enabled = PactOpsDefaultsEnabled?.Value ?? true;
		pactOpsSettings.AutoProtectEnabled = PactOpsDefaultsAutoProtectEnabled?.Value ?? true;
		pactOpsSettings.AutoProtectIntervalDays = PactOpsDefaultsAutoProtectIntervalDays?.Value ?? 3;
		pactOpsSettings.AutoProtectRange = PactOpsDefaultsAutoProtectRange?.Value ?? 1;
		pactOpsSettings.CoordinatedAttackAutoEnabled = PactOpsDefaultsCoordinatedAttackAutoEnabled?.Value ?? true;
		pactOpsSettings.CoordinatedAttackCooldownDays = PactOpsDefaultsCoordinatedAttackCooldownDays?.Value ?? 10;
		pactOpsSettings.CoordinatedAttackMinCrew = PactOpsDefaultsCoordinatedAttackMinCrew?.Value ?? 3;
		pactOpsSettings.CoordinatedAttackMaxCrew = PactOpsDefaultsCoordinatedAttackMaxCrew?.Value ?? 5;
		pactOpsSettings.RevengeEnabled = PactOpsDefaultsRevengeEnabled?.Value ?? true;
		pactOpsSettings.RevengeDelayDays = PactOpsDefaultsRevengeDelayDays?.Value ?? 10;
		pactOpsSettings.WarHeatDecayPerWeek = PactOpsDefaultsWarHeatDecayPerWeek?.Value ?? 6f;
		pactOpsSettings.WarHeatAttackGain = PactOpsDefaultsWarHeatAttackGain?.Value ?? 22f;
		pactOpsSettings.WarHeatKillGain = PactOpsDefaultsWarHeatKillGain?.Value ?? 55f;
		pactOpsSettings.TerritoryTakeoverAggressionPercent = PactOpsDefaultsTerritoryTakeoverAggressionPercent?.Value ?? PactTerritoryTakeoverAggressionDefault;
		pactOpsSettings.FrontClosureAggressionPercent = PactOpsDefaultsFrontClosureAggressionPercent?.Value ?? PactFrontClosureAggressionDefault;
		pactOpsSettings.OverallAggroPercent = PactOpsDefaultsOverallAggroPercent?.Value ?? PactOverallAggroDefault;
		pactOpsSettings.HireAutomationEnabled = PactOpsDefaultsHireAutomationEnabled?.Value ?? true;
		pactOpsSettings.TopGangCrewBonusMin = PactOpsDefaultsTopGangCrewBonusMin?.Value ?? 18;
		pactOpsSettings.TopGangCrewBonusMax = PactOpsDefaultsTopGangCrewBonusMax?.Value ?? 28;
		pactOpsSettings.MidGangCrewBonus = PactOpsDefaultsMidGangCrewBonus?.Value ?? 8;
		pactOpsSettings.BottomGangCrewBonus = PactOpsDefaultsBottomGangCrewBonus?.Value ?? 3;
		pactOpsSettings.PactCrewBonus = PactOpsDefaultsPactCrewBonus?.Value ?? 4;
		return pactOpsSettings;
	}

