	internal static bool TrySaveGangOpsSettingsToConfig(GangOpsChannel channel, PactOpsSettings settings, out string message)
	{
		message = "No Gang Ops settings to save.";
		if (settings == null)
		{
			return false;
		}

		try
		{
			NormalizePactOpsSettings(settings);
			if (channel == GangOpsChannel.Independent)
			{
				SetConfigValue(GangOpsDefaultsIndependentEnabled, settings.Enabled);
				SetConfigValue(GangOpsDefaultsIndependentAutoProtectEnabled, settings.AutoProtectEnabled);
				SetConfigValue(GangOpsDefaultsIndependentAutoProtectIntervalDays, settings.AutoProtectIntervalDays);
				SetConfigValue(GangOpsDefaultsIndependentAutoProtectRange, settings.AutoProtectRange);
				SetConfigValue(GangOpsDefaultsIndependentCoordinatedAttackAutoEnabled, settings.CoordinatedAttackAutoEnabled);
				SetConfigValue(GangOpsDefaultsIndependentCoordinatedAttackCooldownDays, settings.CoordinatedAttackCooldownDays);
				SetConfigValue(GangOpsDefaultsIndependentCoordinatedAttackMinCrew, settings.CoordinatedAttackMinCrew);
				SetConfigValue(GangOpsDefaultsIndependentCoordinatedAttackMaxCrew, settings.CoordinatedAttackMaxCrew);
				SetConfigValue(GangOpsDefaultsIndependentRevengeEnabled, settings.RevengeEnabled);
				SetConfigValue(GangOpsDefaultsIndependentRevengeDelayDays, settings.RevengeDelayDays);
				SetConfigValue(GangOpsDefaultsIndependentWarHeatDecayPerWeek, settings.WarHeatDecayPerWeek);
				SetConfigValue(GangOpsDefaultsIndependentWarHeatAttackGain, settings.WarHeatAttackGain);
				SetConfigValue(GangOpsDefaultsIndependentWarHeatKillGain, settings.WarHeatKillGain);
				SetConfigValue(GangOpsDefaultsIndependentTerritoryTakeoverAggressionPercent, settings.TerritoryTakeoverAggressionPercent);
				SetConfigValue(GangOpsDefaultsIndependentFrontClosureAggressionPercent, settings.FrontClosureAggressionPercent);
				SetConfigValue(GangOpsDefaultsIndependentOverallAggroPercent, settings.OverallAggroPercent);
				SetConfigValue(GangOpsDefaultsIndependentHireAutomationEnabled, settings.HireAutomationEnabled);
				SetConfigValue(GangOpsDefaultsIndependentTopGangCrewBonusMin, settings.TopGangCrewBonusMin);
				SetConfigValue(GangOpsDefaultsIndependentTopGangCrewBonusMax, settings.TopGangCrewBonusMax);
				SetConfigValue(GangOpsDefaultsIndependentMidGangCrewBonus, settings.MidGangCrewBonus);
				SetConfigValue(GangOpsDefaultsIndependentBottomGangCrewBonus, settings.BottomGangCrewBonus);
				SetConfigValue(GangOpsDefaultsIndependentPactCrewBonus, settings.PactCrewBonus);
			}
			else
			{
				SetConfigValue(PactOpsDefaultsEnabled, settings.Enabled);
				SetConfigValue(PactOpsDefaultsAutoProtectEnabled, settings.AutoProtectEnabled);
				SetConfigValue(PactOpsDefaultsAutoProtectIntervalDays, settings.AutoProtectIntervalDays);
				SetConfigValue(PactOpsDefaultsAutoProtectRange, settings.AutoProtectRange);
				SetConfigValue(PactOpsDefaultsCoordinatedAttackAutoEnabled, settings.CoordinatedAttackAutoEnabled);
				SetConfigValue(PactOpsDefaultsCoordinatedAttackCooldownDays, settings.CoordinatedAttackCooldownDays);
				SetConfigValue(PactOpsDefaultsCoordinatedAttackMinCrew, settings.CoordinatedAttackMinCrew);
				SetConfigValue(PactOpsDefaultsCoordinatedAttackMaxCrew, settings.CoordinatedAttackMaxCrew);
				SetConfigValue(PactOpsDefaultsRevengeEnabled, settings.RevengeEnabled);
				SetConfigValue(PactOpsDefaultsRevengeDelayDays, settings.RevengeDelayDays);
				SetConfigValue(PactOpsDefaultsWarHeatDecayPerWeek, settings.WarHeatDecayPerWeek);
				SetConfigValue(PactOpsDefaultsWarHeatAttackGain, settings.WarHeatAttackGain);
				SetConfigValue(PactOpsDefaultsWarHeatKillGain, settings.WarHeatKillGain);
				SetConfigValue(PactOpsDefaultsTerritoryTakeoverAggressionPercent, settings.TerritoryTakeoverAggressionPercent);
				SetConfigValue(PactOpsDefaultsFrontClosureAggressionPercent, settings.FrontClosureAggressionPercent);
				SetConfigValue(PactOpsDefaultsOverallAggroPercent, settings.OverallAggroPercent);
				SetConfigValue(PactOpsDefaultsHireAutomationEnabled, settings.HireAutomationEnabled);
				SetConfigValue(PactOpsDefaultsTopGangCrewBonusMin, settings.TopGangCrewBonusMin);
				SetConfigValue(PactOpsDefaultsTopGangCrewBonusMax, settings.TopGangCrewBonusMax);
				SetConfigValue(PactOpsDefaultsMidGangCrewBonus, settings.MidGangCrewBonus);
				SetConfigValue(PactOpsDefaultsBottomGangCrewBonus, settings.BottomGangCrewBonus);
				SetConfigValue(PactOpsDefaultsPactCrewBonus, settings.PactCrewBonus);
			}

			Instance?.Config?.Save();
			string channelTag = GetGangOpsChannelTag(channel);
			message = $"Saved {channelTag} defaults to config.";
			VerificationLog($"GangOps.{channelTag}.Config", $"saved defaults ca={settings.CoordinatedAttackAutoEnabled} cd={settings.CoordinatedAttackCooldownDays} crew={settings.CoordinatedAttackMinCrew}-{settings.CoordinatedAttackMaxCrew} heat={settings.WarHeatAttackGain:0.0}/{settings.WarHeatKillGain:0.0}/{settings.WarHeatDecayPerWeek:0.0} aggro={settings.TerritoryTakeoverAggressionPercent}/{settings.FrontClosureAggressionPercent}/{settings.OverallAggroPercent} hire={settings.HireAutomationEnabled} top={settings.TopGangCrewBonusMin}-{settings.TopGangCrewBonusMax} mid={settings.MidGangCrewBonus} bottom={settings.BottomGangCrewBonus} bonus={settings.PactCrewBonus}");
			return true;
		}
		catch (Exception ex)
		{
			message = "Config save failed: " + ex.Message;
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Config", "save failed " + ex.Message);
			return false;
		}
	}

	private static void SetConfigValue<T>(ConfigEntry<T> entry, T value)
