	internal static string GetGangOpsConfigAndSavePathsText()
	{
		string configPath = GetGameplayTweaksConfigPath();
		string savesPath = GetCitySaveRootPath();
		string modDataPath = string.IsNullOrWhiteSpace(savesPath) ? string.Empty : Path.Combine(savesPath, "ModData");
		string latestSavePath = GetLatestCitySavePath(savesPath);
		return "Config: " + configPath
			+ "\nSaves: " + savesPath
			+ "\nMod data: " + modDataPath
			+ "\nLatest save: " + latestSavePath;
	}

	private static string GetGameplayTweaksConfigPath()
	{
		try
		{
			string path = Instance?.Config?.ConfigFilePath;
			if (!string.IsNullOrWhiteSpace(path))
			{
				return path;
			}
		}
		catch
		{
		}

		try
		{
			return Path.Combine(BepInEx.Paths.ConfigPath, "com.mods.gameplaytweaks.cfg");
		}
		catch
		{
			return "BepInEx/config/com.mods.gameplaytweaks.cfg";
		}
	}

	private static string GetCitySaveRootPath()
	{
		try
		{
			string persistentPath = Application.persistentDataPath;
			if (!string.IsNullOrWhiteSpace(persistentPath))
			{
				return Path.Combine(persistentPath, "saves");
			}
		}
		catch
		{
		}

		try
		{
			return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "AppData", "LocalLow", "SomaSim", "City of Gangsters", "saves");
		}
		catch
		{
			return "AppData/LocalLow/SomaSim/City of Gangsters/saves";
		}
	}

	private static string GetLatestCitySavePath(string savesPath)
	{
		try
		{
			if (string.IsNullOrWhiteSpace(savesPath) || !Directory.Exists(savesPath))
			{
				return "not found";
			}

			DirectoryInfo latest = new DirectoryInfo(savesPath)
				.GetDirectories()
				.OrderByDescending(d => d.LastWriteTimeUtc)
				.FirstOrDefault();
			if (latest == null)
			{
				return "none";
			}

			string saveZip = Path.Combine(latest.FullName, "savedata.sim.zip");
			return File.Exists(saveZip) ? saveZip : latest.FullName;
		}
		catch (Exception ex)
		{
			return "unavailable: " + ex.Message;
		}
	}

	private static bool ApplyGangOpsHireDefaultUpgrades()
	{
		bool changed = false;
		if (PactOpsDefaultsHireAutomationEnabled != null
			&& PactOpsDefaultsTopGangCrewBonusMin != null
			&& PactOpsDefaultsTopGangCrewBonusMax != null
			&& PactOpsDefaultsMidGangCrewBonus != null
			&& PactOpsDefaultsBottomGangCrewBonus != null
			&& PactOpsDefaultsPactCrewBonus != null
			&& PactOpsDefaultsHireAutomationEnabled.Value
			&& PactOpsDefaultsTopGangCrewBonusMin.Value == 15
			&& PactOpsDefaultsTopGangCrewBonusMax.Value == 25
			&& PactOpsDefaultsMidGangCrewBonus.Value == 6
			&& PactOpsDefaultsBottomGangCrewBonus.Value == 0
			&& PactOpsDefaultsPactCrewBonus.Value == 0)
		{
			PactOpsDefaultsTopGangCrewBonusMin.Value = 18;
			PactOpsDefaultsTopGangCrewBonusMax.Value = 28;
			PactOpsDefaultsMidGangCrewBonus.Value = 8;
			PactOpsDefaultsBottomGangCrewBonus.Value = 3;
			PactOpsDefaultsPactCrewBonus.Value = 4;
			VerificationLog("GangOpsDefaults", "upgrade pact hire defaults top=18-28 mid=8 bottom=3 pactBonus=4");
			changed = true;
		}

		if (GangOpsDefaultsIndependentHireAutomationEnabled == null
			|| GangOpsDefaultsIndependentTopGangCrewBonusMin == null
			|| GangOpsDefaultsIndependentTopGangCrewBonusMax == null
			|| GangOpsDefaultsIndependentMidGangCrewBonus == null
			|| GangOpsDefaultsIndependentBottomGangCrewBonus == null
			|| GangOpsDefaultsIndependentPactCrewBonus == null)
		{
			return changed;
		}

		bool matchesOldIndependentDisabledDefaults = !GangOpsDefaultsIndependentHireAutomationEnabled.Value
			&& GangOpsDefaultsIndependentTopGangCrewBonusMin.Value == 6
			&& GangOpsDefaultsIndependentTopGangCrewBonusMax.Value == 10
			&& GangOpsDefaultsIndependentMidGangCrewBonus.Value == 2
			&& GangOpsDefaultsIndependentBottomGangCrewBonus.Value == 0
			&& GangOpsDefaultsIndependentPactCrewBonus.Value == 0;
		bool matchesOldGenericHireDefaults = GangOpsDefaultsIndependentHireAutomationEnabled.Value
			&& GangOpsDefaultsIndependentTopGangCrewBonusMin.Value == 15
			&& GangOpsDefaultsIndependentTopGangCrewBonusMax.Value == 25
			&& GangOpsDefaultsIndependentMidGangCrewBonus.Value == 6
			&& GangOpsDefaultsIndependentBottomGangCrewBonus.Value == 0
			&& GangOpsDefaultsIndependentPactCrewBonus.Value == 0;
		if (!matchesOldIndependentDisabledDefaults && !matchesOldGenericHireDefaults)
		{
			return changed;
		}

		GangOpsDefaultsIndependentHireAutomationEnabled.Value = IndependentHireAutomationDefault;
		GangOpsDefaultsIndependentTopGangCrewBonusMin.Value = IndependentTopGangCrewBonusMinDefault;
		GangOpsDefaultsIndependentTopGangCrewBonusMax.Value = IndependentTopGangCrewBonusMaxDefault;
		GangOpsDefaultsIndependentMidGangCrewBonus.Value = IndependentMidGangCrewBonusDefault;
		GangOpsDefaultsIndependentBottomGangCrewBonus.Value = IndependentBottomGangCrewBonusDefault;
		VerificationLog("GangOpsDefaults", $"upgrade independent hire defaults top={IndependentTopGangCrewBonusMinDefault}-{IndependentTopGangCrewBonusMaxDefault} mid={IndependentMidGangCrewBonusDefault} bottom={IndependentBottomGangCrewBonusDefault} bonus=0");
		return true;
	}

	private static bool ApplyGangOpsTerritoryProtectionDefaultUpgrades()
	{
		bool changed = false;
		if (PactOpsDefaultsAutoProtectIntervalDays != null
			&& PactOpsDefaultsAutoProtectRange != null
			&& PactOpsDefaultsTerritoryTakeoverAggressionPercent != null
			&& (PactOpsDefaultsAutoProtectIntervalDays.Value == 3
				|| PactOpsDefaultsAutoProtectIntervalDays.Value == 6
				|| PactOpsDefaultsAutoProtectIntervalDays.Value == 7)
			&& (PactOpsDefaultsAutoProtectRange.Value == 1 || PactOpsDefaultsAutoProtectRange.Value == 2)
			&& (PactOpsDefaultsTerritoryTakeoverAggressionPercent.Value == 100
				|| PactOpsDefaultsTerritoryTakeoverAggressionPercent.Value == 150
				|| PactOpsDefaultsTerritoryTakeoverAggressionPercent.Value == PactTerritoryTakeoverAggressionDefault)
			&& (PactOpsDefaultsAutoProtectIntervalDays.Value != 3
				|| PactOpsDefaultsAutoProtectRange.Value != 1
				|| PactOpsDefaultsTerritoryTakeoverAggressionPercent.Value != PactTerritoryTakeoverAggressionDefault))
		{
			PactOpsDefaultsAutoProtectIntervalDays.Value = 3;
			PactOpsDefaultsAutoProtectRange.Value = 1;
			PactOpsDefaultsTerritoryTakeoverAggressionPercent.Value = PactTerritoryTakeoverAggressionDefault;
			VerificationLog("GangOpsDefaults", $"upgrade pact territory defaults protectDays=3 range=1 takeover={PactTerritoryTakeoverAggressionDefault}");
			changed = true;
		}

		if (GangOpsDefaultsIndependentAutoProtectIntervalDays != null
			&& GangOpsDefaultsIndependentAutoProtectRange != null
			&& GangOpsDefaultsIndependentTerritoryTakeoverAggressionPercent != null
			&& (GangOpsDefaultsIndependentAutoProtectIntervalDays.Value == 4
				|| GangOpsDefaultsIndependentAutoProtectIntervalDays.Value == 7
				|| GangOpsDefaultsIndependentAutoProtectIntervalDays.Value == 9)
			&& (GangOpsDefaultsIndependentAutoProtectRange.Value == 1 || GangOpsDefaultsIndependentAutoProtectRange.Value == 2)
			&& (GangOpsDefaultsIndependentTerritoryTakeoverAggressionPercent.Value == 100
				|| GangOpsDefaultsIndependentTerritoryTakeoverAggressionPercent.Value == 150
				|| GangOpsDefaultsIndependentTerritoryTakeoverAggressionPercent.Value == 175
				|| GangOpsDefaultsIndependentTerritoryTakeoverAggressionPercent.Value == IndependentTerritoryTakeoverAggressionDefault)
			&& (GangOpsDefaultsIndependentAutoProtectIntervalDays.Value != 4
				|| GangOpsDefaultsIndependentAutoProtectRange.Value != 1
				|| GangOpsDefaultsIndependentTerritoryTakeoverAggressionPercent.Value != IndependentTerritoryTakeoverAggressionDefault))
		{
			GangOpsDefaultsIndependentAutoProtectIntervalDays.Value = 4;
			GangOpsDefaultsIndependentAutoProtectRange.Value = 1;
			GangOpsDefaultsIndependentTerritoryTakeoverAggressionPercent.Value = IndependentTerritoryTakeoverAggressionDefault;
			VerificationLog("GangOpsDefaults", $"upgrade independent territory defaults protectDays=4 range=1 takeover={IndependentTerritoryTakeoverAggressionDefault}");
			changed = true;
		}

		return changed;
	}

	private static bool IsGenericUnseededGangOpsSettings(PactOpsSettings settings)
	{
		if (settings == null)
		{
			return true;
		}
		return settings.Enabled
			&& settings.AutoProtectEnabled
			&& settings.AutoProtectIntervalDays == 7
			&& settings.AutoProtectRange == 1
			&& !settings.CoordinatedAttackAutoEnabled
			&& settings.CoordinatedAttackCooldownDays == 14
			&& settings.CoordinatedAttackMinCrew == 2
			&& settings.CoordinatedAttackMaxCrew == 3
			&& settings.RevengeEnabled
			&& settings.RevengeDelayDays == 14
			&& Mathf.Approximately(settings.WarHeatDecayPerWeek, 8f)
			&& Mathf.Approximately(settings.WarHeatAttackGain, 20f)
			&& Mathf.Approximately(settings.WarHeatKillGain, 50f)
			&& settings.HireAutomationEnabled
			&& settings.TopGangCrewBonusMin == 15
			&& settings.TopGangCrewBonusMax == 25
			&& settings.MidGangCrewBonus == 6
			&& settings.BottomGangCrewBonus == 0
			&& settings.PactCrewBonus == 0;
	}

	private static bool MatchesLegacyProfileSeededGangOpsSettings(PactOpsSettings settings, GangOpsChannel channel)
	{
		if (settings == null)
		{
			return false;
		}

		if (channel == GangOpsChannel.Independent)
		{
			return settings.Enabled
				&& settings.AutoProtectEnabled
				&& settings.AutoProtectIntervalDays == 9
				&& settings.AutoProtectRange == 1
				&& !settings.CoordinatedAttackAutoEnabled
				&& settings.CoordinatedAttackCooldownDays == 20
				&& settings.CoordinatedAttackMinCrew == 1
				&& settings.CoordinatedAttackMaxCrew == 2
				&& settings.RevengeEnabled
				&& settings.RevengeDelayDays == 16
				&& Mathf.Approximately(settings.WarHeatDecayPerWeek, 10f)
				&& Mathf.Approximately(settings.WarHeatAttackGain, 14f)
				&& Mathf.Approximately(settings.WarHeatKillGain, 35f)
				&& !settings.HireAutomationEnabled
				&& settings.TopGangCrewBonusMin == 6
				&& settings.TopGangCrewBonusMax == 10
				&& settings.MidGangCrewBonus == 2
				&& settings.BottomGangCrewBonus == 0
				&& settings.PactCrewBonus == 0;
		}

		return settings.Enabled
			&& settings.AutoProtectEnabled
			&& settings.AutoProtectIntervalDays == 6
			&& settings.AutoProtectRange == 1
			&& settings.CoordinatedAttackAutoEnabled
			&& settings.CoordinatedAttackCooldownDays == 10
			&& settings.CoordinatedAttackMinCrew == 3
			&& settings.CoordinatedAttackMaxCrew == 5
			&& settings.RevengeEnabled
			&& settings.RevengeDelayDays == 10
			&& Mathf.Approximately(settings.WarHeatDecayPerWeek, 6f)
			&& Mathf.Approximately(settings.WarHeatAttackGain, 22f)
			&& Mathf.Approximately(settings.WarHeatKillGain, 55f)
			&& settings.HireAutomationEnabled
			&& settings.TopGangCrewBonusMin == 18
			&& settings.TopGangCrewBonusMax == 28
			&& settings.MidGangCrewBonus == 8
			&& settings.BottomGangCrewBonus == 3
			&& settings.PactCrewBonus == 4;
	}

	private static bool MatchesLegacyHybridIndependentGangOpsSettings(PactOpsSettings settings)
	{
		if (settings == null)
		{
			return false;
		}
		return settings.Enabled
			&& settings.AutoProtectEnabled
			&& settings.AutoProtectIntervalDays == 7
			&& settings.AutoProtectRange == 1
			&& settings.CoordinatedAttackAutoEnabled
			&& settings.CoordinatedAttackCooldownDays == 14
			&& settings.CoordinatedAttackMinCrew == 2
			&& settings.CoordinatedAttackMaxCrew == 3
			&& settings.RevengeEnabled
			&& settings.RevengeDelayDays == 14
			&& Mathf.Approximately(settings.WarHeatDecayPerWeek, 8f)
			&& Mathf.Approximately(settings.WarHeatAttackGain, 20f)
			&& Mathf.Approximately(settings.WarHeatKillGain, 50f)
			&& settings.HireAutomationEnabled
			&& settings.TopGangCrewBonusMin == 15
			&& settings.TopGangCrewBonusMax == 25
			&& settings.MidGangCrewBonus == 6
			&& settings.BottomGangCrewBonus == 0
			&& settings.PactCrewBonus == 0;
	}

	private static bool MatchesAccidentalPactMirroredIndependentGangOpsSettings(PactOpsSettings independentSettings, PactOpsSettings pactSettings)
	{
		if (independentSettings == null || pactSettings == null)
		{
			return false;
		}

		return independentSettings.HireAutomationEnabled == pactSettings.HireAutomationEnabled
			&& independentSettings.TopGangCrewBonusMin == pactSettings.TopGangCrewBonusMin
			&& independentSettings.TopGangCrewBonusMax == pactSettings.TopGangCrewBonusMax
			&& independentSettings.MidGangCrewBonus == pactSettings.MidGangCrewBonus
			&& independentSettings.BottomGangCrewBonus == pactSettings.BottomGangCrewBonus
			&& independentSettings.PactCrewBonus == pactSettings.PactCrewBonus
			&& independentSettings.CoordinatedAttackCooldownDays == pactSettings.CoordinatedAttackCooldownDays
			&& independentSettings.CoordinatedAttackMinCrew == pactSettings.CoordinatedAttackMinCrew
			&& independentSettings.CoordinatedAttackMaxCrew == pactSettings.CoordinatedAttackMaxCrew;
	}

	private static void EnsureGangOpsDefaultsSeeded()
	{
		if (SaveData == null)
		{
			return;
		}
		bool seededPact = false;
		bool seededIndependent = false;
		bool shouldSeedPact = SaveData.PactOps == null
			|| IsGenericUnseededGangOpsSettings(SaveData.PactOps)
			|| MatchesLegacyProfileSeededGangOpsSettings(SaveData.PactOps, GangOpsChannel.Pact);
		bool shouldSeedIndependent = SaveData.IndependentOps == null
			|| IsGenericUnseededGangOpsSettings(SaveData.IndependentOps)
			|| MatchesLegacyProfileSeededGangOpsSettings(SaveData.IndependentOps, GangOpsChannel.Independent)
			|| MatchesLegacyHybridIndependentGangOpsSettings(SaveData.IndependentOps)
			|| MatchesAccidentalPactMirroredIndependentGangOpsSettings(SaveData.IndependentOps, SaveData.PactOps);
		bool needsMigration = SaveData.GangOpsDefaultsProfileVersion < GangOpsDefaultsProfileVersionCurrent;
		if (!needsMigration && !shouldSeedPact && !shouldSeedIndependent)
		{
			return;
		}

		if (shouldSeedPact)
		{
			SaveData.PactOps = BuildGangOpsDefaultsFromConfig(GangOpsChannel.Pact);
			seededPact = true;
		}
		if (shouldSeedIndependent)
		{
			SaveData.IndependentOps = BuildGangOpsDefaultsFromConfig(GangOpsChannel.Independent);
			seededIndependent = true;
		}
		if (needsMigration && !seededPact)
		{
			ApplyGangOpsAggressionDefaultsIfUnset(SaveData.PactOps, GangOpsChannel.Pact);
			ApplyGangOpsTerritoryProtectionDefaultsIfLegacy(SaveData.PactOps, GangOpsChannel.Pact);
		}
		if (needsMigration && !seededIndependent)
		{
			ApplyGangOpsAggressionDefaultsIfUnset(SaveData.IndependentOps, GangOpsChannel.Independent);
			ApplyGangOpsTerritoryProtectionDefaultsIfLegacy(SaveData.IndependentOps, GangOpsChannel.Independent);
		}
		SaveData.GangOpsDefaultsProfileVersion = GangOpsDefaultsProfileVersionCurrent;
		VerificationLog("GangOpsDefaults", $"seed version={SaveData.GangOpsDefaultsProfileVersion} pactSeeded={seededPact} independentSeeded={seededIndependent} pactCoordAuto={SaveData.PactOps?.CoordinatedAttackAutoEnabled} independentCoordAuto={SaveData.IndependentOps?.CoordinatedAttackAutoEnabled} pactAggro={SaveData.PactOps?.TerritoryTakeoverAggressionPercent}/{SaveData.PactOps?.FrontClosureAggressionPercent}/{SaveData.PactOps?.OverallAggroPercent} independentAggro={SaveData.IndependentOps?.TerritoryTakeoverAggressionPercent}/{SaveData.IndependentOps?.FrontClosureAggressionPercent}/{SaveData.IndependentOps?.OverallAggroPercent}");
	}

	private static void ApplyGangOpsAggressionDefaultsIfUnset(PactOpsSettings settings, GangOpsChannel channel)
	{
		if (settings == null)
		{
			return;
		}
		bool hasLegacyUnsetAggro = settings.TerritoryTakeoverAggressionPercent <= 0
			|| settings.FrontClosureAggressionPercent <= 0
			|| settings.OverallAggroPercent <= 0
			|| (settings.TerritoryTakeoverAggressionPercent == 100
				&& settings.FrontClosureAggressionPercent == 100
				&& settings.OverallAggroPercent == 100);
		if (!hasLegacyUnsetAggro)
		{
			return;
		}

		PactOpsSettings defaults = BuildGangOpsDefaultsFromConfig(channel);
		settings.TerritoryTakeoverAggressionPercent = defaults.TerritoryTakeoverAggressionPercent;
		settings.FrontClosureAggressionPercent = defaults.FrontClosureAggressionPercent;
		settings.OverallAggroPercent = defaults.OverallAggroPercent;
	}

	private static void ApplyGangOpsTerritoryProtectionDefaultsIfLegacy(PactOpsSettings settings, GangOpsChannel channel)
	{
		if (settings == null)
		{
			return;
		}

		PactOpsSettings defaults = BuildGangOpsDefaultsFromConfig(channel);
		if (channel == GangOpsChannel.Independent)
		{
			bool changed = false;
			if (settings.AutoProtectIntervalDays == 7 || settings.AutoProtectIntervalDays == 9)
			{
				settings.AutoProtectIntervalDays = defaults.AutoProtectIntervalDays;
				changed = true;
			}
			if (settings.AutoProtectRange == 1 || settings.AutoProtectRange == 2)
			{
				settings.AutoProtectRange = defaults.AutoProtectRange;
				changed = true;
			}
			if (settings.TerritoryTakeoverAggressionPercent == 100
				|| settings.TerritoryTakeoverAggressionPercent == 150
				|| settings.TerritoryTakeoverAggressionPercent == 175)
			{
				settings.TerritoryTakeoverAggressionPercent = defaults.TerritoryTakeoverAggressionPercent;
				changed = true;
			}
			if (changed)
			{
				VerificationLog("GangOpsDefaults", $"migrate independent territory/protect defaults days={settings.AutoProtectIntervalDays} range={settings.AutoProtectRange} takeover={settings.TerritoryTakeoverAggressionPercent}");
			}
			return;
		}

		bool pactChanged = false;
		if (settings.AutoProtectIntervalDays == 6 || settings.AutoProtectIntervalDays == 7)
		{
			settings.AutoProtectIntervalDays = defaults.AutoProtectIntervalDays;
			pactChanged = true;
		}
		if (settings.AutoProtectRange == 1 || settings.AutoProtectRange == 2)
		{
			settings.AutoProtectRange = defaults.AutoProtectRange;
			pactChanged = true;
		}
		if (settings.TerritoryTakeoverAggressionPercent == 100 || settings.TerritoryTakeoverAggressionPercent == 150)
		{
			settings.TerritoryTakeoverAggressionPercent = defaults.TerritoryTakeoverAggressionPercent;
			pactChanged = true;
		}
		if (pactChanged)
		{
			VerificationLog("GangOpsDefaults", $"migrate pact territory/protect defaults days={settings.AutoProtectIntervalDays} range={settings.AutoProtectRange} takeover={settings.TerritoryTakeoverAggressionPercent}");
		}
	}

	private static void NormalizePactOpsSettings(PactOpsSettings settings)
	{
		if (settings == null)
		{
			return;
		}
		settings.AutoProtectIntervalDays = Mathf.Clamp(settings.AutoProtectIntervalDays, 1, 365);
		settings.AutoProtectRange = Mathf.Clamp(settings.AutoProtectRange, 1, 6);
		settings.CoordinatedAttackCooldownDays = Mathf.Clamp(settings.CoordinatedAttackCooldownDays, 1, 180);
		settings.CoordinatedAttackMinCrew = Mathf.Clamp(settings.CoordinatedAttackMinCrew, 1, 10);
		settings.CoordinatedAttackMaxCrew = Mathf.Clamp(settings.CoordinatedAttackMaxCrew, settings.CoordinatedAttackMinCrew, 12);
		settings.RevengeDelayDays = Mathf.Clamp(settings.RevengeDelayDays, 1, 180);
		settings.WarHeatDecayPerWeek = Mathf.Clamp(settings.WarHeatDecayPerWeek, 0f, 100f);
		settings.WarHeatAttackGain = Mathf.Clamp(settings.WarHeatAttackGain, 0f, 100f);
		settings.WarHeatKillGain = Mathf.Clamp(settings.WarHeatKillGain, 0f, 100f);
		settings.TerritoryTakeoverAggressionPercent = Mathf.Clamp(settings.TerritoryTakeoverAggressionPercent <= 0 ? 100 : settings.TerritoryTakeoverAggressionPercent, 10, 300);
		settings.FrontClosureAggressionPercent = Mathf.Clamp(settings.FrontClosureAggressionPercent <= 0 ? 100 : settings.FrontClosureAggressionPercent, 10, 300);
		settings.OverallAggroPercent = Mathf.Clamp(settings.OverallAggroPercent <= 0 ? 100 : settings.OverallAggroPercent, 10, 300);
		settings.TopGangCrewBonusMin = Mathf.Clamp(settings.TopGangCrewBonusMin, 0, 100);
		settings.TopGangCrewBonusMax = Mathf.Clamp(settings.TopGangCrewBonusMax, settings.TopGangCrewBonusMin, 150);
		settings.MidGangCrewBonus = Mathf.Clamp(settings.MidGangCrewBonus, 0, 100);
		settings.BottomGangCrewBonus = Mathf.Clamp(settings.BottomGangCrewBonus, 0, 100);
		settings.PactCrewBonus = Mathf.Clamp(settings.PactCrewBonus, 0, 100);
	}

	internal static PactOpsSettings EnsurePactOpsSettings()
	{
		if (SaveData == null)
		{
			SaveData = new ModSaveData();
		}
		EnsureGangOpsDefaultsSeeded();
		if (SaveData.PactOps == null)
		{
			SaveData.PactOps = BuildPactOpsDefaultsFromConfig();
		}
		NormalizePactOpsSettings(SaveData.PactOps);
		return SaveData.PactOps;
	}

	internal static PactOpsSettings EnsureIndependentOpsSettings()
	{
		if (SaveData == null)
		{
			SaveData = new ModSaveData();
		}
		EnsureGangOpsDefaultsSeeded();
		if (SaveData.IndependentOps == null)
		{
			SaveData.IndependentOps = BuildGangOpsDefaultsFromConfig(GangOpsChannel.Independent);
		}
		NormalizePactOpsSettings(SaveData.IndependentOps);
		return SaveData.IndependentOps;
	}

	internal static PactOpsSettings EnsureGangOpsSettings(GangOpsChannel channel)
	{
		return (channel == GangOpsChannel.Independent) ? EnsureIndependentOpsSettings() : EnsurePactOpsSettings();
	}

	internal static bool IsPactOpsEnabled()
	{
		return EnsurePactOpsSettings().Enabled;
	}

	internal static bool IsGangOpsEnabled(GangOpsChannel channel)
	{
		return EnsureGangOpsSettings(channel).Enabled;
	}

