	internal static void MarkPendingCornerHeatRaid(PlayerInfo player, string sourceTag)
	{
		if (player == null || !player.PID.IsHumanPlayer)
		{
			return;
		}
		_pendingCornerHeatRaidActive = true;
		_pendingCornerHeatRaidPlayerPid = player.PID.id;
		_pendingCornerHeatRaidDay = G.GetNow().days;
		_pendingCornerHeatRaidFrame = Time.frameCount;
		VerificationLog("CornerHeatRaid", $"trySellOutToFeds source={sourceTag} allow=True pid={player.PID.id}");
	}

	internal static void ClearPendingCornerHeatRaidContext()
	{
		_pendingCornerHeatRaidActive = false;
		_pendingCornerHeatRaidPlayerPid = -1;
		_pendingCornerHeatRaidDay = -1;
		_pendingCornerHeatRaidFrame = -1;
	}

	internal static void ArmPendingHumanCornerHeatPrecinctRaid(PlayerInfo precinctPlayer, PlayerInfo humanPlayer, Node node, int heatValue)
	{
		if (precinctPlayer == null || humanPlayer == null || node == null || !humanPlayer.PID.IsHumanPlayer)
		{
			return;
		}
		_pendingHumanCornerHeatPrecinctRaidActive = true;
		_pendingHumanCornerHeatPrecinctRaidDay = G.GetNow().days;
		_pendingHumanCornerHeatRaidNodeId = node.id;
		_pendingHumanCornerHeatRaidPrecinctPid = precinctPlayer.PID.id;
		_pendingHumanCornerHeatRaidHumanPid = humanPlayer.PID.id;
		_pendingHumanCornerHeatRaidHumanArrestCount = 0;
		VerificationLog("CornerHeatRaid", $"armed precinctPid={precinctPlayer.PID.id} humanPid={humanPlayer.PID.id} node={node.id} heat={heatValue}");
	}

	internal static void ClearPendingHumanCornerHeatPrecinctRaidContext()
	{
		_pendingHumanCornerHeatPrecinctRaidActive = false;
		_pendingHumanCornerHeatPrecinctRaidDay = -1;
		_pendingHumanCornerHeatRaidNodeId = NodeID.INVALID;
		_pendingHumanCornerHeatRaidPrecinctPid = -1;
		_pendingHumanCornerHeatRaidHumanPid = -1;
		_pendingHumanCornerHeatRaidHumanArrestCount = 0;
	}

	internal static void ResolvePendingHumanCornerHeatPrecinctRaid(bool result)
	{
		if (!_pendingHumanCornerHeatPrecinctRaidActive)
		{
			return;
		}
		NodeID resolvedNodeId = _pendingHumanCornerHeatRaidNodeId;
		VerificationLog("CornerHeatRaid", $"resolved precinctPid={_pendingHumanCornerHeatRaidPrecinctPid} node={resolvedNodeId} result={result} humanArrests={_pendingHumanCornerHeatRaidHumanArrestCount}");
		ClearPendingHumanCornerHeatPrecinctRaidContext();
		try
		{
			Node resolvedNode = resolvedNodeId.IsValid ? resolvedNodeId.FindNode() : null;
			if (resolvedNode != null)
			{
				MultiCrewVehicleHelper.HideCornerInfoIfShowingNode(resolvedNode.id);
				RefreshBuildingPickStateAfterHumanVehicleTravel(resolvedNode, resolvedNode, "precinct-raid-arrest-resolved");
				VerificationLog("CornerHeatRaid", $"resolved-ui-refresh node={resolvedNode.id} result={result}");
			}
			TerritoryColorPatch.RefreshAllTerritoryColors();
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] ResolvePendingHumanCornerHeatPrecinctRaid UI refresh failed: " + ex.Message);
		}
	}

	internal static bool AreRuntimePromptsReady()
	{
		return Time.frameCount >= RuntimePromptEarliestFrame;
	}

	internal static bool IsCrewHiddenOrHideoutPending(EntityID peepId)
	{
		if (peepId.IsNotValid)
		{
			return false;
		}
		CrewModState crewState = GetCrewStateOrNull(peepId);
		return crewState != null && (crewState.OnHideout || crewState.HideoutPending);
	}

	internal static bool ShouldDeferArrestForHideout(EntityID peepId, string sourceTag)
	{
		if (!IsCrewHiddenOrHideoutPending(peepId))
		{
			return false;
		}

		VerificationLog("Jail", $"hideout-arrest-deferred peep={peepId.id}{FormatHumanCrewIndexTag(peepId)} source={sourceTag}");
		return true;
	}

	internal static bool TryGetCrewAssignmentBlockReason(EntityID peepId, out string failureReason)
	{
		failureReason = null;
		if (peepId.IsNotValid)
		{
			return false;
		}

		try
		{
			if (IsCrewCurrentlyJailed(peepId))
			{
				failureReason = JailSystem.GetJailStatusString(peepId);
				if (string.IsNullOrWhiteSpace(failureReason))
				{
					failureReason = "Crew is in custody and cannot be assigned.";
				}
				return true;
			}
		}
		catch
		{
			failureReason = "Crew is in custody and cannot be assigned.";
			return true;
		}

		try
		{
			CrewModState crewState = GetCrewStateOrNull(peepId);
			if (crewState == null)
			{
				return false;
			}

			if (crewState.OnHideout)
			{
				failureReason = "Crew is in hideout and cannot be assigned.";
				return true;
			}

			if (crewState.HideoutPending)
			{
				failureReason = "Crew is entering hideout and cannot be assigned.";
				return true;
			}
		}
		catch
		{
			failureReason = "Crew is unavailable and cannot be assigned.";
			return true;
		}

		return false;
	}

	internal static bool TryHandleHumanCornerHeatPrecinctRaidArrest(EntityID peepId, Node node, out WantedLevel heatBefore, out WantedLevel heatAfter, out float progressBefore, out float progressAfter)
	{
		heatBefore = WantedLevel.None;
		heatAfter = WantedLevel.None;
		progressBefore = 0f;
		progressAfter = 0f;
		if (!_pendingHumanCornerHeatPrecinctRaidActive || peepId.IsNotValid || node == null)
		{
			return false;
		}
		if (_pendingHumanCornerHeatPrecinctRaidDay != G.GetNow().days)
		{
			ClearPendingHumanCornerHeatPrecinctRaidContext();
			return false;
		}
		if (_pendingHumanCornerHeatRaidNodeId != node.id)
		{
			return false;
		}
		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (humanPlayer == null || humanPlayer.PID.id != _pendingHumanCornerHeatRaidHumanPid || humanPlayer.crew == null)
		{
			return false;
		}
		if (IsCrewHiddenOrHideoutPending(peepId))
		{
			VerificationLog("CornerHeatRaid", $"raid-skip-hideout-pending peep={peepId.id} source=precinct-pending");
			return false;
		}
		CrewAssignment crewForPeep = humanPlayer.crew.GetCrewForPeep(peepId);
		if (!crewForPeep.IsValid)
		{
			return false;
		}
		if (!TryRaiseLocalHeatOneTierFromCornerRaid(peepId, out heatBefore, out heatAfter, out progressBefore, out progressAfter))
		{
			return false;
		}
		_pendingHumanCornerHeatRaidHumanArrestCount++;
		return true;
	}

	internal static bool TryRaiseLocalHeatFromDirectHumanPrecinctArrest(EntityID peepId, Node node, out WantedLevel heatBefore, out WantedLevel heatAfter, out float progressBefore, out float progressAfter)
	{
		heatBefore = WantedLevel.None;
		heatAfter = WantedLevel.None;
		progressBefore = 0f;
		progressAfter = 0f;
		if (peepId.IsNotValid || node == null)
		{
			return false;
		}
		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (humanPlayer?.crew == null)
		{
			return false;
		}
		Entity entity = peepId.FindEntity();
		PlayerID? pid = entity?.data?.agent?.pid;
		PlayerInfo player = pid.HasValue ? pid.Value.FindPlayer() : null;
		if (player == null || player.PID.id != humanPlayer.PID.id)
		{
			return false;
		}
		if (IsCrewHiddenOrHideoutPending(peepId))
		{
			VerificationLog("CornerHeatRaid", $"raid-skip-hideout-pending peep={peepId.id} source=direct-precinct");
			return false;
		}
		CrewAssignment crewForPeep = humanPlayer.crew.GetCrewForPeep(peepId);
		if (!crewForPeep.IsValid)
		{
			return false;
		}
		if (!PrecinctAdvisorRaidPatch.IsNodeAtHumanRaidThreshold(node, humanPlayer.PID, out int heatValue))
		{
			return false;
		}
		return TryRaiseLocalHeatOneTierFromCornerRaid(peepId, out heatBefore, out heatAfter, out progressBefore, out progressAfter);
	}

	internal static bool TryRaiseLocalHeatFromDirectHumanArrestAtHotNode(PlayerInfo player, CrewAssignment crew, out Node node, out int nodeHeat, out WantedLevel heatBefore, out WantedLevel heatAfter, out float progressBefore, out float progressAfter)
	{
		node = null;
		nodeHeat = 0;
		heatBefore = WantedLevel.None;
		heatAfter = WantedLevel.None;
		progressBefore = 0f;
		progressAfter = 0f;
		if (player == null || !player.PID.IsHumanPlayer || !crew.IsValid)
		{
			return false;
		}
		if (IsCrewHiddenOrHideoutPending(crew.peepId))
		{
			VerificationLog("CornerHeatRaid", $"raid-skip-hideout-pending peep={crew.peepId.id} source=direct-hot-node");
			return false;
		}
		if (!PrecinctAdvisorRaidPatch.TryGetCrewCurrentNode(crew, out node))
		{
			return false;
		}
		if (!PrecinctAdvisorRaidPatch.IsNodeAtHumanRaidThreshold(node, player.PID, out nodeHeat))
		{
			return false;
		}
		return TryRaiseLocalHeatOneTierFromCornerRaid(crew.peepId, out heatBefore, out heatAfter, out progressBefore, out progressAfter);
	}

	internal static bool TryRaiseLocalHeatFromAgentArrest(AgentComponent agent, out EntityID peepId, out Node node, out int nodeHeat, out WantedLevel heatBefore, out WantedLevel heatAfter, out float progressBefore, out float progressAfter)
	{
		peepId = EntityID.INVALID;
		node = null;
		nodeHeat = 0;
		heatBefore = WantedLevel.None;
		heatAfter = WantedLevel.None;
		progressBefore = 0f;
		progressAfter = 0f;
		if (agent == null)
		{
			return false;
		}
		Entity entity = agent.entity;
		if (entity == null || entity.Id.IsNotValid)
		{
			return false;
		}
		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (humanPlayer?.crew == null || entity.data?.agent?.pid.id != humanPlayer.PID.id)
		{
			return false;
		}
		CrewAssignment crewForPeep = humanPlayer.crew.GetCrewForPeep(entity.Id);
		if (!crewForPeep.IsValid)
		{
			return false;
		}
		if (!PrecinctAdvisorRaidPatch.TryGetCrewCurrentNode(crewForPeep, out node))
		{
			return false;
		}
		if (node == null || !PrecinctAdvisorRaidPatch.IsNodeAtHumanRaidThreshold(node, humanPlayer.PID, out nodeHeat))
		{
			return false;
		}
		if (!TryRaiseLocalHeatOneTierFromCornerRaid(entity.Id, out heatBefore, out heatAfter, out progressBefore, out progressAfter))
		{
			return false;
		}
		peepId = entity.Id;
		return true;
	}

	internal static bool TryConsumePendingCornerHeatRaid(PlayerInfo player)
	{
		if (!_pendingCornerHeatRaidActive || player == null || !player.PID.IsHumanPlayer)
		{
			return false;
		}
		if (_pendingCornerHeatRaidPlayerPid != player.PID.id)
		{
			return false;
		}
		int nowDay = G.GetNow().days;
		if (_pendingCornerHeatRaidDay != nowDay)
		{
			ClearPendingCornerHeatRaidContext();
			return false;
		}
		ClearPendingCornerHeatRaidContext();
		return true;
	}

	internal static bool WasCornerHeatRaidInvokedToday(PlayerInfo player)
	{
		if (player == null)
		{
			return false;
		}
		int days = G.GetNow().days;
		return _lastCornerHeatRaidInvokeDayByPid.TryGetValue(player.PID.id, out int value) && value == days;
	}

	internal static void NoteCornerHeatRaidInvocation(PlayerInfo player, string sourceTag)
	{
		if (player == null)
		{
			return;
		}
		int days = G.GetNow().days;
		_lastCornerHeatRaidInvokeDayByPid[player.PID.id] = days;
		if (player.PID.IsHumanPlayer)
		{
			VerificationLog("CornerHeatRaid", $"invoke source={sourceTag} pid={player.PID.id} human=True day={days}");
		}
	}

