	internal static string MakeGangPairKey(int attackerPid, int defenderPid)
	{
		return attackerPid.ToString(CultureInfo.InvariantCulture) + "_" + defenderPid.ToString(CultureInfo.InvariantCulture);
	}

	internal static bool TryParseGangPairKey(string key, out int attackerPid, out int defenderPid)
	{
		attackerPid = -1;
		defenderPid = -1;
		if (string.IsNullOrEmpty(key))
		{
			return false;
		}
		int num = key.IndexOf('_');
		if (num <= 0 || num >= key.Length - 1)
		{
			return false;
		}
		return int.TryParse(key.Substring(0, num), NumberStyles.Integer, CultureInfo.InvariantCulture, out attackerPid) && int.TryParse(key.Substring(num + 1), NumberStyles.Integer, CultureInfo.InvariantCulture, out defenderPid);
	}

	internal static void MarkCrewPickAggroDirty(PlayerID pid, string sourceTag)
	{
		if (pid.id < 0)
		{
			return;
		}
		if (TryDelegateCrewPickAggroDirtyToAfterProhibitionUi(pid.id, sourceTag))
		{
			return;
		}
		if (_dirtyCrewPickAggroPids.Add(pid.id))
		{
			VerificationLog("AggroUI", $"dirty pid={pid.id} source={sourceTag}");
		}
	}

	internal static void ResetTransientPolicePortraitState(string sourceTag, bool clearDeferredPresentations = true)
	{
		MultiCrewVehicleHelper.ResetTransientEnemyVehiclePresentationState(sourceTag);
		if (clearDeferredPresentations)
		{
			_deferredFederalArrestPresentationsByPeep.Clear();
		}
		if (ShouldSkipBroadPoliceAggroRefresh(sourceTag))
		{
			return;
		}
		try
		{
			IEnumerable<PlayerInfo> players = global::Game.Game.ctx?.players?.all;
			if (players != null)
			{
				foreach (PlayerInfo player in players)
				{
					if (player == null || (!player.IsCopOrFed && !player.IsJustCop))
					{
						continue;
					}

					MarkCrewPickAggroDirty(player.PID, sourceTag);
				}
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning($"[GameplayTweaks] ResetTransientPolicePortraitState failed: {ex.Message}");
		}
	}

	private static bool ShouldSkipBroadPoliceAggroRefresh(string sourceTag)
	{
		return !string.IsNullOrEmpty(sourceTag)
			&& sourceTag.StartsWith("direct-arrest-ui-", StringComparison.Ordinal);
	}

	public static void RefreshRelationshipAggroUi(IEnumerable<PlayerInfo> players, string sourceTag, bool refreshCrewHud = true)
	{
		int dirtyCount = 0;
		try
		{
			if (players != null)
			{
				foreach (PlayerInfo player in players)
				{
					if (player == null)
					{
						continue;
					}

					MarkCrewPickAggroDirty(player.PID, sourceTag);
					dirtyCount++;
				}
			}

			FlushCrewPickAggroRefreshes(sourceTag);
			if (refreshCrewHud)
			{
				RefreshCrewHudUi(sourceTag);
			}
			TerritoryColorPatch.RefreshAllTerritoryColors();
			if (dirtyCount > 0)
			{
				VerificationLog("AggroUI", $"external-refresh count={dirtyCount} source={sourceTag}");
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning($"[GameplayTweaks] RefreshRelationshipAggroUi failed: {ex.Message}");
		}
	}

	internal static void RefreshCrewHudUi(string sourceTag, bool rebuildCards = false)
	{
		try
		{
			if (TryDelegateCrewHudRefreshToAfterProhibitionUi(sourceTag, rebuildCards))
			{
				return;
			}

			CrewDialog crewHud = global::Game.Game.ctx?.hud?.crew;
			if (crewHud == null)
			{
				return;
			}

			if (rebuildCards)
			{
				MethodInfo recreateAllCards = typeof(CrewDialog).GetMethod("RecreateAllCards", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, Type.EmptyTypes, null);
				recreateAllCards?.Invoke(crewHud, null);
				MethodInfo refreshContents = typeof(CrewDialog).GetMethod("RefreshContents", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, Type.EmptyTypes, null);
				refreshContents?.Invoke(crewHud, null);
				MethodInfo forceRebuildLayout = typeof(CrewDialog).GetMethod("ForceRebuildLayoutImmediate", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, Type.EmptyTypes, null);
				forceRebuildLayout?.Invoke(crewHud, null);
				VerificationLog("CrewHUD", $"refresh rebuild={rebuildCards} source={sourceTag}");
				return;
			}

			crewHud.RefreshCards();
		}
		catch (Exception ex)
		{
			Debug.LogWarning($"[GameplayTweaks] RefreshCrewHudUi failed: {ex.Message}");
		}
	}

	private static MethodInfo _afterProhibitionUiCrewHudRefreshMethod;

	private static bool TryDelegateCrewHudRefreshToAfterProhibitionUi(string sourceTag, bool rebuildCards)
	{
		if (!IsAfterProhibitionUiInstalled())
		{
			return false;
		}

		try
		{
			EnsureAfterProhibitionUiCrewHudRefreshMethod();
			if (_afterProhibitionUiCrewHudRefreshMethod == null)
			{
				return false;
			}

			object result = _afterProhibitionUiCrewHudRefreshMethod.Invoke(null, new object[] { sourceTag ?? string.Empty, rebuildCards });
			return result is bool applied && applied;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] AfterProhibitionUI crew HUD refresh bridge failed: " + ex.Message);
			return false;
		}
	}

	private static void EnsureAfterProhibitionUiCrewHudRefreshMethod()
	{
		if (_afterProhibitionUiCrewHudRefreshMethod != null)
		{
			return;
		}

		Type bridgeType = AccessTools.TypeByName("AfterProhibitionUI.CrewHudRefreshBridge");
		_afterProhibitionUiCrewHudRefreshMethod = bridgeType?.GetMethod(
			"RequestCrewHudRefresh",
			BindingFlags.Static | BindingFlags.Public,
			null,
			new[] { typeof(string), typeof(bool) },
			null);
	}

	private static bool TryResolveHudPickManager(out object pickManager)
	{
		pickManager = null;
		try
		{
			object ctx = G.GetCtx();
			if (ctx == null)
			{
				return false;
			}
			object hud = ctx.GetType().GetField("hud", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(ctx);
			if (hud == null)
			{
				return false;
			}
			pickManager = hud.GetType().GetField("picks", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(hud);
			return pickManager != null;
		}
		catch
		{
			return false;
		}
	}

	private static void TryRemoveCrewPickForTarget(object pickManager, EntityID targetId, ref int removedCount)
	{
		if (pickManager == null || _removePickMethod == null || !targetId.IsValid)
		{
			return;
		}

		try
		{
			PickTarget target = new PickTarget(targetId);
			if ((bool)_removePickMethod.Invoke(pickManager, new object[] { target, PickType.CrewPick }))
			{
				removedCount++;
			}
			if (Enum.TryParse("MobilePick", out PickType mobilePickType)
				&& (bool)_removePickMethod.Invoke(pickManager, new object[] { target, mobilePickType }))
			{
				removedCount++;
			}
		}
		catch
		{
		}
	}

	internal static void BeginPickContainerRefresh()
	{
		_activePickContainerRefreshDepth++;
	}

	internal static void EndPickContainerRefresh()
	{
		if (_activePickContainerRefreshDepth > 0)
		{
			_activePickContainerRefreshDepth--;
		}
	}

	internal static bool IsPickContainerRefreshActive()
	{
		return _activePickContainerRefreshDepth > 0;
	}

	private static void QueueDeferredCrewPickClearTargets(string sourceTag, IEnumerable<EntityID> targetIds)
	{
		if (targetIds == null)
		{
			return;
		}

		int queued = 0;
		int frame = Time.frameCount;
		foreach (EntityID targetId in targetIds)
		{
			if (!targetId.IsValid)
			{
				continue;
			}

			_deferredCrewPickClearsByTarget[targetId.id] = new DeferredCrewPickClear
			{
				QueuedFrame = frame,
				Source = sourceTag ?? string.Empty,
				TargetId = targetId
			};
			queued++;
		}

		if (queued > 0)
		{
			VerificationLog("VehicleNodeAuthority", $"crew-picks-clear-deferred targets={queued} source={sourceTag} reason=pick-refresh-active frame={frame}");
		}
	}

	private static void FlushDeferredCrewPickClears(string sourceTag)
	{
		if (_deferredCrewPickClearsByTarget.Count == 0 || IsPickContainerRefreshActive())
		{
			return;
		}

		List<DeferredCrewPickClear> queued = _deferredCrewPickClearsByTarget.Values
			.Where(item => item != null && item.TargetId.IsValid)
			.OrderBy(item => item.QueuedFrame)
			.ToList();
		_deferredCrewPickClearsByTarget.Clear();
		if (queued.Count == 0)
		{
			return;
		}

		EntityID[] targetIds = queued
			.Select(item => item.TargetId)
			.GroupBy(id => id.id)
			.Select(group => group.First())
			.ToArray();
		string originalSources = string.Join(",", queued
			.Select(item => item.Source)
			.Where(source => !string.IsNullOrWhiteSpace(source))
			.Distinct()
			.Take(4));
		int removed = ClearCrewPicksForTargets("deferred-pick-refresh:" + sourceTag, targetIds);
		VerificationLog("VehicleNodeAuthority", $"crew-picks-clear-deferred-flush targets={targetIds.Length} removed={removed} sources={originalSources} trigger={sourceTag} frame={Time.frameCount}");
	}

	internal static int ClearCrewPicksForTargets(string sourceTag, params EntityID[] targetIds)
	{
		if (targetIds == null || targetIds.Length == 0)
		{
			return 0;
		}

		try
		{
			if (IsPickContainerRefreshActive())
			{
				QueueDeferredCrewPickClearTargets(sourceTag, targetIds);
				return 0;
			}

			if (!TryResolveHudPickManager(out object pickManager))
			{
				return 0;
			}

			if (_cachedHudPickManager != pickManager || _removePickMethod == null)
			{
				_cachedHudPickManager = pickManager;
				_removePickMethod = pickManager.GetType().GetMethod("Remove", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public, null, new[] { typeof(PickTarget), typeof(PickType) }, null);
			}

			if (_removePickMethod == null)
			{
				return 0;
			}

			int removedCount = 0;
			HashSet<ulong> seenTargets = new HashSet<ulong>();
			foreach (EntityID targetId in targetIds)
			{
				if (!targetId.IsValid || !seenTargets.Add(targetId.id))
				{
					continue;
				}

				TryRemoveCrewPickForTarget(pickManager, targetId, ref removedCount);
			}

			try
			{
				int bruteForceCleared = CrewPickAggroRefreshStabilityPatch.ForceClearCrewPickTargets(pickManager, targetIds);
				if (bruteForceCleared > 0)
				{
					removedCount += bruteForceCleared;
					VerificationLog("VehicleNodeAuthority", $"crew-picks-force-cleared targets=[{string.Join(",", targetIds.Where(id => id.IsValid).Select(id => id.id.ToString()).Distinct())}] removed={bruteForceCleared} source={sourceTag}");
				}
			}
			catch
			{
			}

			if (removedCount > 0)
			{
				string targetText = string.Join(",", targetIds.Where(id => id.IsValid).Select(id => id.id.ToString()).Distinct());
				VerificationLog("VehicleNodeAuthority", $"crew-picks-cleared targets=[{targetText}] removed={removedCount} source={sourceTag}");
			}

			return removedCount;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] ClearCrewPicksForTargets failed: " + ex.Message);
			return 0;
		}
	}

	private static void ClearStaleCrewPicksAfterArrest(EntityID peepId, EntityID vehicleId, bool clearVehiclePick, string sourceTag)
	{
		if (peepId.IsNotValid)
		{
			return;
		}

		try
		{
			int removedCount = clearVehiclePick
				? ClearCrewPicksForTargets(sourceTag, peepId, vehicleId)
				: ClearCrewPicksForTargets(sourceTag, peepId);
			if (removedCount > 0)
			{
				VerificationLog("VehicleNodeAuthority", $"regular-arrest-stale-crew-picks-cleared peep={peepId.id} vehicle={vehicleId.id} clearVehicle={clearVehiclePick} removed={removedCount} source={sourceTag}");
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] ClearStaleCrewPicksAfterArrest failed: " + ex.Message);
		}
	}

	internal static void FlushCrewPickAggroRefreshes(string sourceTag)
	{
		if (TryDelegateCrewPickAggroFlushToAfterProhibitionUi(sourceTag))
		{
			_dirtyCrewPickAggroPids.Clear();
			return;
		}
		if (_dirtyCrewPickAggroPids.Count == 0)
		{
			return;
		}
		if (Input.GetMouseButton(0))
		{
			if (_lastCrewPickAggroDeferredFrame != Time.frameCount)
			{
				_lastCrewPickAggroDeferredFrame = Time.frameCount;
				VerificationLog("AggroUI", $"flush deferred source={sourceTag} count={_dirtyCrewPickAggroPids.Count} reason=mouse-held");
			}
			return;
		}
		int num = 0;
		try
		{
			if (!TryResolveHudPickManager(out object pickManager))
			{
				return;
			}
			if (_cachedHudPickManager != pickManager || _refreshAllPlayerCrewPicksMethod == null)
			{
				_cachedHudPickManager = pickManager;
				_refreshAllPlayerCrewPicksMethod = pickManager.GetType().GetMethod("RefreshAllPlayerCrewPicks", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public, null, new Type[1] { typeof(PlayerID) }, null);
			}
			if (_refreshAllPlayerCrewPicksMethod == null)
			{
				return;
			}
			foreach (int dirtyCrewPickAggroPid in _dirtyCrewPickAggroPids)
			{
				PlayerID pID = ResolveCrewPickAggroPlayerId(dirtyCrewPickAggroPid);
				ExecuteCrewPickAggroRefresh(pickManager, pID, sourceTag, logDetails: true, out bool countedVanillaRefresh);
				if (countedVanillaRefresh)
				{
					num++;
				}
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning($"[GameplayTweaks] Crew pick aggro flush failed: {ex.Message}");
		}
		finally
		{
			_dirtyCrewPickAggroPids.Clear();
			if (num > 0)
			{
				VerificationLog("AggroUI", $"flush count={num} source={sourceTag}");
			}
		}
	}

	public static string ExecuteCrewPickAggroRefreshForExternalOwner(int pid, string sourceTag)
	{
		try
		{
			if (pid < 0)
			{
				return "skipped=invalid-pid";
			}
			if (!TryResolveHudPickManager(out object pickManager))
			{
				return "skipped=no-pick-manager";
			}
			if (_cachedHudPickManager != pickManager || _refreshAllPlayerCrewPicksMethod == null)
			{
				_cachedHudPickManager = pickManager;
				_refreshAllPlayerCrewPicksMethod = pickManager.GetType().GetMethod("RefreshAllPlayerCrewPicks", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public, null, new Type[1] { typeof(PlayerID) }, null);
			}
			if (_refreshAllPlayerCrewPicksMethod == null)
			{
				return "skipped=no-refresh-method";
			}

			PlayerID pID = ResolveCrewPickAggroPlayerId(pid);
			return ExecuteCrewPickAggroRefresh(pickManager, pID, sourceTag, logDetails: false, out _);
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] ExecuteCrewPickAggroRefreshForExternalOwner failed: " + ex.Message);
			return "skipped=exception";
		}
	}

	private static PlayerID ResolveCrewPickAggroPlayerId(int pid)
	{
		PlayerInfo playerInfo = G.FindPlayerById(pid);
		PlayerID pID = ((playerInfo != null) ? playerInfo.PID : default(PlayerID));
		if (playerInfo == null)
		{
			pID.id = (short)pid;
		}
		return pID;
	}

	private static string ExecuteCrewPickAggroRefresh(object pickManager, PlayerID pID, string sourceTag, bool logDetails, out bool countedVanillaRefresh)
	{
		countedVanillaRefresh = false;
		if (CrewPickAggroRefreshStabilityPatch.TryClearCopOrFedCrewPickTargets(pickManager, pID, out int removedCount))
		{
			if (logDetails && removedCount > 0)
			{
				VerificationLog("AggroUI", $"flush-clear-only pid={pID.id} removed={removedCount} source={sourceTag}");
			}
			return $"flush-clear-only pid={pID.id} removed={removedCount} source={sourceTag}";
		}
		if (CrewPickAggroRefreshStabilityPatch.TryReconcileCrewPickTargets(pickManager, pID, out int staleRemovedCount, out int staleRefreshedCount))
		{
			if (logDetails)
			{
				VerificationLog(
					"AggroUI",
					$"flush-reconcile pid={pID.id} removed={staleRemovedCount} refreshed={staleRefreshedCount} source={sourceTag}");
			}
			return $"flush-reconcile pid={pID.id} removed={staleRemovedCount} refreshed={staleRefreshedCount} source={sourceTag}";
		}
		_refreshAllPlayerCrewPicksMethod.Invoke(pickManager, new object[1] { pID });
		countedVanillaRefresh = true;
		return $"flush-refresh pid={pID.id} source={sourceTag}";
	}

