			return -1;
		}
	}

	private static bool IsMurderWitnessActionCooldownActive(CrewModState state)
	{
		int nowDay = GetCurrentDaySafe();
		return state != null && nowDay >= 0 && state.MurderWitnessLastActionDay == nowDay;
	}

