	private static void CountActiveMurderWitnessReliability(CrewModState state, out int reliableCount, out int unreliableCount)
	{
		reliableCount = 0;
		unreliableCount = 0;
		if (state?.MurderWitnesses == null)
		{
			return;
		}
		for (int i = 0; i < state.MurderWitnesses.Count; i++)
		{
			MurderWitnessRecord record = state.MurderWitnesses[i];
			if (!IsMurderWitnessRecordActive(record))
			{
				continue;
			}
			if (IsReliableMurderWitness(record))
			{
				reliableCount++;
			}
			else
			{
				unreliableCount++;
			}
		}
	}

	private static void NormalizeMurderWitnessRecordState(CrewModState state)
	{
		if (state == null)
		{
			return;
		}
		if (state.MurderWitnesses == null)
		{
			state.MurderWitnesses = new List<MurderWitnessRecord>();
		}
		int nextId = Math.Max(1, state.NextMurderWitnessId);
		for (int i = state.MurderWitnesses.Count - 1; i >= 0; i--)
		{
			MurderWitnessRecord record = state.MurderWitnesses[i];
			if (record == null)
			{
				state.MurderWitnesses.RemoveAt(i);
				continue;
			}
			if (record.WitnessId <= 0)
			{
				record.WitnessId = nextId++;
			}
			nextId = Math.Max(nextId, record.WitnessId + 1);
			if (record.Reliability != MurderWitnessReliabilityReliable && record.Reliability != MurderWitnessReliabilityUnreliable)
			{
				record.Reliability = RollMurderWitnessReliability();
			}
			if (string.IsNullOrWhiteSpace(record.CaseProfile))
			{
				record.CaseProfile = "murder";
			}
			record.CaseGainMultiplier = Mathf.Max(0.01f, record.CaseGainMultiplier);
			if (record.SilenceFailed
				&& !record.SilencedSuccessfully
				&& !record.ThreatenedSuccessfully
				&& string.Equals(record.CaseProfile ?? "murder", "murder", StringComparison.OrdinalIgnoreCase))
			{
				record.Closed = false;
				record.Found = false;
			}
		}
		state.NextMurderWitnessId = nextId;
		state.MurderCaseProgress = Mathf.Clamp(state.MurderCaseProgress, 0f, 100f);
		if (!state.MurderCaseActive && state.MurderCaseProgress > 0f)
		{
			state.MurderCaseActive = true;
		}
		EnsureMurderCaseMinimumBuildDaysLocked(state);
	}

	internal static void EnsureMurderWitnessRecordsForScalar(EntityID peepId, CrewModState state, string source)
	{
		if (state == null)
		{
			return;
		}
		NormalizeMurderWitnessRecordState(state);
		int targetCount = GetNonFederalMurderWitnessCount(state);
		int activeCount = CountActiveMurderWitnessRecords(state);
		if (targetCount <= activeCount)
		{
			return;
		}
		int addedDay = GetCurrentDaySafe();
		long owner = peepId.IsNotValid ? 0L : unchecked((long)peepId.id);
		string sourceTag = string.IsNullOrEmpty(source) ? "unknown" : source;
		while (activeCount < targetCount)
		{
			MurderWitnessRecord record = new MurderWitnessRecord();
			record.WitnessId = Math.Max(1, state.NextMurderWitnessId++);
			record.OwningCrewPeepId = owner;
			record.Reliability = RollMurderWitnessReliability();
			record.AddedDay = addedDay;
			record.CaseProfile = "murder";
			record.LegacyAnonymous = true;
			state.MurderWitnesses.Add(record);
			activeCount++;
			VerificationLog("MurderWitness", $"murder-witness-record-created peep={owner} witnessId={record.WitnessId} reliability={GetMurderWitnessReliabilityLabel(record)} activeRecords={activeCount} scalarWitnesses={targetCount} source={sourceTag} legacyAnonymous={record.LegacyAnonymous}");
		}
	}

	internal static void CloseOneMurderWitnessRecord(EntityID peepId, CrewModState state, string source)
	{
		if (state?.MurderWitnesses == null)
		{
			return;
		}
		NormalizeMurderWitnessRecordState(state);
		MurderWitnessRecord record = null;
		for (int i = 0; i < state.MurderWitnesses.Count; i++)
		{
			MurderWitnessRecord candidate = state.MurderWitnesses[i];
			if (IsMurderWitnessRecordActive(candidate))
			{
				record = candidate;
				break;
			}
		}
		if (record == null)
		{
			return;
		}
		CloseMurderWitnessRecord(peepId, state, record, source, "threat-success");
	}

	private static void CloseMurderWitnessRecord(EntityID peepId, CrewModState state, MurderWitnessRecord record, string source, string result)
	{
		if (state == null || record == null || !IsMurderWitnessRecordActive(record))
		{
			return;
		}
		record.Closed = true;
		record.ThreatenedSuccessfully = string.Equals(result, "threat-success", StringComparison.OrdinalIgnoreCase);
		record.ThreatAttempted = record.ThreatAttempted || record.ThreatenedSuccessfully;
		string sourceTag = string.IsNullOrEmpty(source) ? "unknown" : source;
		string resultTag = string.IsNullOrEmpty(result) ? "closed" : result;
		VerificationLog("MurderWitness", $"murder-witness-record-closed peep={(peepId.IsNotValid ? 0UL : peepId.id)} witnessId={record.WitnessId} reliability={GetMurderWitnessReliabilityLabel(record)} source={sourceTag} result={resultTag}");
	}

	private static bool TryResetMurderCaseIfNoActiveWitnesses(EntityID peepId, CrewModState state, string reason)
	{
		if (state == null)
		{
			return false;
		}
		NormalizeMurderWitnessRecordState(state);
		if (CountActiveMurderWitnessRecords(state) > 0)
		{
			return false;
		}
		if (!AreAllMurderWitnessesResolvedSuccessfully(state))
		{
			LogMurderCaseResetDeferred(peepId, reason);
			return false;
		}
		if (!state.MurderCaseActive && state.MurderCaseProgress <= 0f)
		{
			return false;
		}
		ResetMurderCaseState(peepId, state, GetCurrentDaySafe(), reason);
		return true;
	}

	private static void LogMurderCaseResetDeferred(EntityID peepId, string source)
	{
		int nowDay = GetCurrentDaySafe();
		string key = $"{(peepId.IsNotValid ? 0UL : peepId.id)}:{source ?? "unknown"}";
		if (nowDay >= 0
			&& MurderWitnessResetDeferredLastDayByPeep.TryGetValue(key, out int lastDay)
			&& nowDay - lastDay < 28)
		{
			return;
		}
		if (nowDay >= 0)
		{
			MurderWitnessResetDeferredLastDayByPeep[key] = nowDay;
		}
		VerificationLog("MurderWitness", $"murder-case-reset-deferred peep={(peepId.IsNotValid ? 0UL : peepId.id)} reason=unresolved-witness-evidence source={source}");
	}

	private static bool AreAllMurderWitnessesResolvedSuccessfully(CrewModState state)
	{
		if (state?.MurderWitnesses == null || state.MurderWitnesses.Count == 0)
		{
			return false;
		}
		bool sawMurderWitness = false;
		for (int i = 0; i < state.MurderWitnesses.Count; i++)
		{
			MurderWitnessRecord record = state.MurderWitnesses[i];
			if (record == null || !string.Equals(record.CaseProfile ?? "murder", "murder", StringComparison.OrdinalIgnoreCase))
			{
				continue;
			}
			sawMurderWitness = true;
			if (IsMurderWitnessRecordActive(record)
				|| record.SilenceFailed
				|| (!record.ThreatenedSuccessfully && !record.SilencedSuccessfully))
			{
				return false;
			}
		}
		return sawMurderWitness;
	}

	internal static void LogMurderWitnessCaseDryRun(EntityID peepId, CrewModState state, string source)
	{
		if (peepId.IsNotValid || state == null)
		{
			return;
		}
		EnsureMurderWitnessRecordsForScalar(peepId, state, source);
		int murderWitnesses = GetNonFederalMurderWitnessCount(state);
		int activeRecords = CountActiveMurderWitnessRecords(state);
		string sourceTag = string.IsNullOrEmpty(source) ? "unknown" : source;
		bool debugSource = sourceTag.StartsWith("debug", StringComparison.OrdinalIgnoreCase);
		if (murderWitnesses < MurderWitnessCaseThreshold)
		{
			if (debugSource)
			{
				VerificationLog("MurderWitness", $"murder-witness-action-current-state peep={peepId.id} murderWitnesses={murderWitnesses} activeRecords={activeRecords} totalWitnesses={state.WitnessCount} federal={state.FederalWitnessCount} threshold={MurderWitnessCaseThreshold} source={sourceTag} result=below-threshold");
			}
			return;
		}
		int nowDay = G.GetNow().days;
		string cooldownKey = $"{peepId.id}:{sourceTag}";
		if (MurderWitnessCaseDryRunLastDayByPeep.TryGetValue(cooldownKey, out int lastDay) && nowDay - lastDay < MurderWitnessCaseDryRunLogCooldownDays)
		{
			return;
		}
		MurderWitnessCaseDryRunLastDayByPeep[cooldownKey] = nowDay;
		CountActiveMurderWitnessReliability(state, out int reliableCount, out int unreliableCount);
		float minGain = CalculateMurderCaseGainBound(state, maxRoll: false);
		float maxGain = CalculateMurderCaseGainBound(state, maxRoll: true);
		int minCaseDays = GetMurderCaseMinimumBuildDays(state);
		VerificationLog("MurderWitness", $"murder-witness-case-threshold-check peep={peepId.id} murderWitnesses={murderWitnesses} activeRecords={activeRecords} reliable={reliableCount} unreliable={unreliableCount} totalWitnesses={state.WitnessCount} federal={state.FederalWitnessCount} threshold={MurderWitnessCaseThreshold} source={sourceTag} result=eligible casePolicy=single-per-crew");
		VerificationLog("MurderWitness", $"murder-witness-case-dryrun-start peep={peepId.id} source={sourceTag} result=projected-only");
		VerificationLog("MurderWitness", $"murder-witness-case-dryrun-gain peep={peepId.id} murderWitnesses={murderWitnesses} activeRecords={activeRecords} reliable={reliableCount} unreliable={unreliableCount} minGain={minGain:0.0} maxGain={maxGain:0.0} gainScale={MurderCaseProgressGainScale:0.00} minCaseDays={minCaseDays} source={sourceTag} result=projected-only");
	}

	private static void ProcessMurderCaseTurn(PlayerInfo humanPlayer, SimTime now)
	{
		if (humanPlayer?.crew == null || SaveData?.CrewStates == null || SaveData.CrewStates.Count == 0)
		{
			return;
		}
		foreach (KeyValuePair<long, CrewModState> pair in SaveData.CrewStates.ToList())
		{
			if (pair.Key <= 0L || pair.Value == null)
			{
				continue;
			}
			try
			{
				EntityID peepId = EntityID.FromID(unchecked((ulong)pair.Key));
				ProcessMurderCaseTurnForCrew(humanPlayer, peepId, pair.Value, now);
			}
			catch (Exception ex)
			{
				VerificationLog("MurderWitness", $"murder-case-turn-skipped peep={pair.Key} reason=exception error={ex.GetType().Name}:{ex.Message}");
			}
		}
	}

	private static void ProcessMurderCaseTurnForCrew(PlayerInfo humanPlayer, EntityID peepId, CrewModState state, SimTime now)
	{
		if (humanPlayer?.crew == null || peepId.IsNotValid || state == null)
		{
			return;
		}
		if (!humanPlayer.crew.GetCrewForPeep(peepId).IsValid)
		{
			return;
		}
		EnsureMurderWitnessRecordsForScalar(peepId, state, "murder-case-turn");
		int activeRecords = CountActiveMurderWitnessRecords(state);
		if (activeRecords <= 0)
		{
			TryResetMurderCaseIfNoActiveWitnesses(peepId, state, "all-witnesses-resolved-successfully");
			return;
		}

		bool thresholdEligible = activeRecords >= MurderWitnessCaseThreshold;
		if (!state.MurderCaseActive && !thresholdEligible)
		{
			return;
		}

		Entity peep = null;
		try
		{
			peep = peepId.FindEntity();
		}
		catch
		{
		}
		if (peep == null || peep.data?.person == null)
		{
			VerificationLog("MurderWitness", $"murder-case-gain-deferred peep={peepId.id} activeRecords={activeRecords} progress={state.MurderCaseProgress:0.0} reason=missing-peep");
			return;
		}
		if (!peep.data.person.IsAlive)
		{
			ResetMurderCaseState(peepId, state, now.days, "peep-dead");
			return;
		}
		bool inCustody = state.InJail || JailSystem.IsInJail(peepId) || IsLocalImportantWitnessCustodyPendingToday(peepId) || IsSafeFederalArrestPendingToday(peepId);
		if (inCustody)
		{
			VerificationLog("MurderWitness", $"murder-case-gain-deferred peep={peepId.id} activeRecords={activeRecords} progress={state.MurderCaseProgress:0.0} reason=in-custody");
			return;
		}
		if (state.OnHideout || state.HideoutPending || state.OnVacation || state.VacationPending)
		{
			StartMurderCaseIfNeeded(peepId, state, now.days, activeRecords, "deferred-away");
			VerificationLog("MurderWitness", $"murder-case-gain-deferred peep={peepId.id} activeRecords={activeRecords} progress={state.MurderCaseProgress:0.0} reason=away-state");
			return;
		}

		StartMurderCaseIfNeeded(peepId, state, now.days, activeRecords, thresholdEligible ? "threshold" : "existing");
		if (!state.MurderCaseActive)
		{
			return;
		}
		if (state.MurderCaseLastIntakeDay == now.days)
		{
			return;
		}

		float before = Mathf.Clamp(state.MurderCaseProgress, 0f, 100f);
		float gain = RollMurderCaseGain(state);
		state.MurderCaseProgress = Mathf.Clamp(before + gain, 0f, 100f);
		state.MurderCaseLastIntakeDay = now.days;
		CountActiveMurderWitnessReliability(state, out int reliableCount, out int unreliableCount);
		int caseAgeDays = GetMurderCaseAgeDays(state, now.days);
		int minCaseDays = GetMurderCaseMinimumBuildDays(state);
		VerificationLog("MurderWitness", $"murder-case-gain peep={peepId.id} activeRecords={activeRecords} reliable={reliableCount} unreliable={unreliableCount} gain={gain:0.0} gainScale={MurderCaseProgressGainScale:0.00} before={before:0.0} after={state.MurderCaseProgress:0.0} caseAgeDays={caseAgeDays} minCaseDays={minCaseDays} failedSilenceMultiplier={state.MurderCaseFailedSilenceMultiplierActive}");
		if (state.MurderCaseProgress < 100f)
		{
			return;
		}
		if (caseAgeDays < minCaseDays)
		{
			VerificationLog("MurderWitness", $"murder-case-threshold-deferred peep={peepId.id} activeRecords={activeRecords} reliable={reliableCount} unreliable={unreliableCount} progress={state.MurderCaseProgress:0.0} caseAgeDays={caseAgeDays} minCaseDays={minCaseDays} reason=case-age");
			return;
		}

		VerificationLog("MurderWitness", $"murder-case-threshold peep={peepId.id} activeRecords={activeRecords} reliable={reliableCount} unreliable={unreliableCount} progress={state.MurderCaseProgress:0.0} caseAgeDays={caseAgeDays} minCaseDays={minCaseDays}");
		StageMurderCaseCustody(humanPlayer, peep, state, now);
	}

	private static void StartMurderCaseIfNeeded(EntityID peepId, CrewModState state, int nowDay, int activeRecords, string source)
	{
		if (state == null || state.MurderCaseActive)
		{
			return;
		}
		state.MurderCaseActive = true;
		if (state.MurderCaseStartedDay < 0)
		{
			state.MurderCaseStartedDay = nowDay;
		}
		EnsureMurderCaseMinimumBuildDaysLocked(state);
		string sourceTag = string.IsNullOrEmpty(source) ? "unknown" : source;
		VerificationLog("MurderWitness", $"murder-case-started peep={(peepId.IsNotValid ? 0UL : peepId.id)} activeRecords={activeRecords} progress={state.MurderCaseProgress:0.0} minCaseDays={GetMurderCaseMinimumBuildDays(state)} source={sourceTag}");
	}

	private static int GetMurderCaseAgeDays(CrewModState state, int nowDay)
	{
		if (state == null)
		{
			return 0;
		}
		if (state.MurderCaseStartedDay < 0)
		{
			state.MurderCaseStartedDay = nowDay;
		}
		return Mathf.Max(0, nowDay - state.MurderCaseStartedDay);
	}

	private static int GetMurderCaseMinimumBuildDays(CrewModState state)
	{
		if (state?.MurderCaseActive == true && state.MurderCaseMinimumBuildDays > 0)
		{
			return state.MurderCaseMinimumBuildDays;
		}
		return CalculateMurderCaseMinimumBuildDaysFromActiveWitnesses(state);
	}

	private static int CalculateMurderCaseMinimumBuildDaysFromActiveWitnesses(CrewModState state)
	{
		CountActiveMurderWitnessReliability(state, out int reliableCount, out int unreliableCount);
		if (reliableCount > unreliableCount)
		{
			return MurderCaseReliableMinimumDays;
		}
		if (unreliableCount > reliableCount)
		{
			return MurderCaseUnreliableMinimumDays;
		}
		return MurderCaseMixedMinimumDays;
	}

	private static void EnsureMurderCaseMinimumBuildDaysLocked(CrewModState state)
	{
		if (state == null || !state.MurderCaseActive || state.MurderCaseMinimumBuildDays > 0)
		{
			return;
		}
		state.MurderCaseMinimumBuildDays = CalculateMurderCaseMinimumBuildDaysFromActiveWitnesses(state);
	}

	private static string GetMurderCaseButtonStatus(CrewModState state)
	{
		if (state == null || !state.MurderCaseActive)
		{
			return "Murder Case Pending";
		}
		int ageDays = GetMurderCaseAgeDays(state, G.GetNow().days);
		int minDays = GetMurderCaseMinimumBuildDays(state);
		return $"Case {state.MurderCaseProgress:0}% ({ageDays}/{minDays}d)";
	}

	private static string GetMurderWitnessCountStatus(CrewModState state)
	{
		if (state == null)
		{
			return $"Witnesses 0/{MurderWitnessCaseThreshold}";
		}
		int openRecords = CountOpenMurderWitnessRecords(state);
		int scalarWitnesses = GetNonFederalMurderWitnessCount(state);
		int witnessCount = Math.Max(openRecords, scalarWitnesses);
		return $"Witnesses {witnessCount}/{MurderWitnessCaseThreshold}";
	}

	private static float RollMurderCaseGain(CrewModState state)
	{
		if (state?.MurderWitnesses == null)
		{
			return 0f;
		}
		float gain = 0f;
		for (int i = 0; i < state.MurderWitnesses.Count; i++)
		{
			MurderWitnessRecord record = state.MurderWitnesses[i];
			if (!IsMurderWitnessRecordActive(record))
			{
				continue;
			}
			int baseGain = SharedRng.Next(1, 4);
			float multiplier = Mathf.Max(1f, record.CaseGainMultiplier);
			gain += baseGain * multiplier * GetMurderWitnessCaseGainWeight(record) * MurderCaseProgressGainScale;
		}
		return gain;
	}

	private static float CalculateMurderCaseGainBound(CrewModState state, bool maxRoll)
	{
		if (state?.MurderWitnesses == null)
		{
			return 0f;
		}
		float gain = 0f;
		int roll = maxRoll ? 3 : 1;
		for (int i = 0; i < state.MurderWitnesses.Count; i++)
		{
			MurderWitnessRecord record = state.MurderWitnesses[i];
			if (!IsMurderWitnessRecordActive(record))
			{
				continue;
			}
			float multiplier = Mathf.Max(1f, record.CaseGainMultiplier);
			gain += roll * multiplier * GetMurderWitnessCaseGainWeight(record) * MurderCaseProgressGainScale;
		}
		return gain;
	}

	private static void StageMurderCaseCustody(PlayerInfo humanPlayer, Entity peep, CrewModState state, SimTime now)
	{
		if (humanPlayer?.crew == null || peep == null || state == null)
		{
			return;
		}
		state.TrialDaysRemaining = Mathf.Max(state.TrialDaysRemaining, MurderCaseTrialDays);
		state.ExtraJailYears = Mathf.Max(state.ExtraJailYears, MurderCaseCustodySentenceYears);
		state.CaseDismissed = false;
		state.FedsIncoming = false;
		state.FedArrivalCountdown = 0;
		bool staged = ExecuteLocalImportantWitnessArrest(humanPlayer, peep, "murder-case");
		if (!staged)
		{
			VerificationLog("MurderWitness", $"murder-case-custody-deferred peep={peep.Id.id} progress={state.MurderCaseProgress:0.0} reason=stage-failed");
			return;
		}
		CloseMurderCaseAfterCustody(peep.Id, state, now.days);
		VerificationLog("MurderWitness", $"murder-case-custody-staged peep={peep.Id.id} trialDays={state.TrialDaysRemaining} sentenceYears={state.ExtraJailYears}");
	}

	private static void CloseMurderCaseAfterCustody(EntityID peepId, CrewModState state, int nowDay)
	{
		if (state == null)
		{
			return;
		}
		if (state.MurderWitnesses != null)
		{
			for (int i = 0; i < state.MurderWitnesses.Count; i++)
			{
				MurderWitnessRecord record = state.MurderWitnesses[i];
				if (IsMurderWitnessRecordActive(record))
				{
					record.Closed = true;
				}
			}
		}
		state.MurderCaseActive = false;
		state.MurderCaseProgress = 0f;
		state.MurderCaseStartedDay = -1;
		state.MurderCaseMinimumBuildDays = -1;
		state.MurderCaseLastIntakeDay = nowDay;
		state.MurderCaseFailedSilenceMultiplierActive = false;
		state.WitnessCount = Mathf.Max(0, state.FederalWitnessCount);
		state.HasWitness = state.WitnessCount > 0;
		VerificationLog("MurderWitness", $"murder-case-closed peep={(peepId.IsNotValid ? 0UL : peepId.id)} reason=custody-staged");
	}

	private static void ResetMurderCaseState(EntityID peepId, CrewModState state, int nowDay, string reason)
	{
		if (state == null)
		{
			return;
		}
		state.MurderCaseActive = false;
		state.MurderCaseProgress = 0f;
		state.MurderCaseStartedDay = -1;
		state.MurderCaseMinimumBuildDays = -1;
		state.MurderCaseLastIntakeDay = nowDay;
		state.MurderCaseFailedSilenceMultiplierActive = false;
		string reasonTag = string.IsNullOrEmpty(reason) ? "unknown" : reason;
		VerificationLog("MurderWitness", $"murder-case-closed peep={(peepId.IsNotValid ? 0UL : peepId.id)} reason={reasonTag}");
	}

	private static WantedLevel HeatLevelFromProgress(float progress)
	{
		if (progress >= 0.75f)
		{
			return WantedLevel.High;
		}
		if (progress >= 0.5f)
		{
			return WantedLevel.Medium;
		}
		if (progress >= 0.25f)
		{
			return WantedLevel.Low;
		}
		return WantedLevel.None;
	}

	private static void SyncLegacyWantedFields(CrewModState state)
	{
		if (state == null)
		{
			return;
		}
		state.LocalHeatProgress = Mathf.Clamp01(state.LocalHeatProgress);
		state.LocalHeatLevel = HeatLevelFromProgress(state.LocalHeatProgress);
		state.WantedProgress = state.LocalHeatProgress;
		state.WantedLevel = state.LocalHeatLevel;
	}

	private static void SyncLocalHeatFromLegacyFields(CrewModState state)
	{
		if (state == null)
		{
			return;
		}
		if (!state.LocalHeatInitialized)
		{
			bool hasExplicitLocal = state.LocalHeatProgress > 0f || state.LocalHeatLevel != WantedLevel.None;
			if (!hasExplicitLocal && (state.WantedProgress > 0f || state.WantedLevel != WantedLevel.None))
			{
				state.LocalHeatProgress = Mathf.Clamp01(state.WantedProgress);
				state.LocalHeatLevel = HeatLevelFromProgress(state.LocalHeatProgress);
			}
			else
			{
				state.LocalHeatProgress = Mathf.Clamp01(state.LocalHeatProgress);
				state.LocalHeatLevel = HeatLevelFromProgress(state.LocalHeatProgress);
			}
			state.LocalHeatInitialized = true;
		}
		else
		{
			float legacyProgress = Mathf.Clamp01(state.WantedProgress);
			if (Mathf.Abs(legacyProgress - state.LocalHeatProgress) > 0.001f)
			{
				if (legacyProgress == 0f || legacyProgress > state.LocalHeatProgress)
				{
					state.LocalHeatProgress = legacyProgress;
					state.LocalHeatLevel = HeatLevelFromProgress(state.LocalHeatProgress);
				}
			}
		}
		SyncLegacyWantedFields(state);
	}

	private static void SetLocalHeatProgress(CrewModState state, float progress, int nowDay, bool refreshDecayAnchor)
	{
		if (state == null)
		{
			return;
		}
		state.LocalHeatProgress = Mathf.Clamp01(progress);
		state.LocalHeatLevel = HeatLevelFromProgress(state.LocalHeatProgress);
		if (refreshDecayAnchor)
		{
			state.LocalHeatLastRefreshDay = nowDay;
		}
		SyncLegacyWantedFields(state);
	}

	internal static bool TryRaiseLocalHeatOneTierFromCornerRaid(EntityID peepId, out WantedLevel heatBefore, out WantedLevel heatAfter, out float progressBefore, out float progressAfter)
	{
		heatBefore = WantedLevel.None;
		heatAfter = WantedLevel.None;
		progressBefore = 0f;
		progressAfter = 0f;
		if (peepId.IsNotValid)
		{
			return false;
		}
		long key = unchecked((long)peepId.id);
		int frameCount = Time.frameCount;
		if (_lastCornerHeatArrestAppliedFrameByPeep.TryGetValue(key, out int value) && value == frameCount)
		{
			return false;
		}
		CrewModState orCreateCrewState = GetOrCreateCrewState(peepId);
		if (orCreateCrewState == null)
		{
			return false;
		}
		SyncLocalHeatFromLegacyFields(orCreateCrewState);
		progressBefore = Mathf.Clamp01(orCreateCrewState.LocalHeatProgress);
		heatBefore = orCreateCrewState.LocalHeatLevel;
		UpdateCornerRaidArrestWindow(orCreateCrewState, G.GetNow().days);
		int days = G.GetNow().days;
		float num = GetNextCornerRaidHeatProgress(orCreateCrewState, progressBefore);
		SetLocalHeatProgress(orCreateCrewState, num, days, refreshDecayAnchor: true);
		if (orCreateCrewState.CornerRaidArrestCountInWindow >= 4 && !orCreateCrewState.JudgeBribeActive)
		{
			orCreateCrewState.FedsIncoming = true;
			orCreateCrewState.FedArrivalCountdown = Math.Max(orCreateCrewState.FedArrivalCountdown, FED_SEARCH_TURNS);
		}
		progressAfter = Mathf.Clamp01(orCreateCrewState.LocalHeatProgress);
		heatAfter = orCreateCrewState.LocalHeatLevel;
		_lastCornerHeatArrestAppliedFrameByPeep[key] = frameCount;
		NotifyCrewHeatUiChanged(peepId);
		return true;
	}

	private static void UpdateCornerRaidArrestWindow(CrewModState state, int nowDay)
	{
		if (state == null)
		{
			return;
		}
		if (state.CornerRaidArrestWindowStartDay < 0 || nowDay - state.CornerRaidArrestWindowStartDay > CORNER_RAID_ARREST_WINDOW_DAYS)
		{
			state.CornerRaidArrestWindowStartDay = nowDay;
			state.CornerRaidArrestCountInWindow = 0;
		}
		state.CornerRaidArrestCountInWindow = Mathf.Max(0, state.CornerRaidArrestCountInWindow) + 1;
	}

	private static float GetNextCornerRaidHeatProgress(CrewModState state, float progressBefore)
	{
		float num = Mathf.Clamp(progressBefore + CORNER_RAID_ARREST_HEAT_GAIN, 0f, CORNER_RAID_ARREST_HEAT_CAP);
		int num2 = Mathf.Max(0, state?.CornerRaidArrestCountInWindow ?? 0);
		float num3 = 0f;
		if (num2 >= 4)
		{
			num3 = 0.75f;
		}
		else if (num2 == 3)
		{
			num3 = 0.56f;
		}
		else if (num2 == 2)
		{
			num3 = 0.36f;
		}
		else if (num2 == 1)
		{
			num3 = 0.18f;
		}
		return Mathf.Clamp(Mathf.Max(num, num3), 0f, CORNER_RAID_ARREST_HEAT_CAP);
	}

	internal static void RaiseLocalHeatFloor(EntityID peepId, float floorProgress, bool refreshDecayAnchor = true)
	{
		if (peepId.IsNotValid)
		{
			return;
		}
			CrewModState state = GetOrCreateCrewState(peepId);
			if (state == null)
			{
				return;
			}
		int nowDay = G.GetNow().days;
		float target = Mathf.Max(state.LocalHeatProgress, floorProgress);
		SetLocalHeatProgress(state, target, nowDay, refreshDecayAnchor);
	}

	internal static void ForceHardMaxLocalHeatAndFeds(EntityID peepId, int minWitnessCount = 3, int fedArrivalCountdown = FED_SEARCH_TURNS)
	{
		if (peepId.IsNotValid)
		{
			return;
		}
		CrewModState state = GetOrCreateCrewState(peepId);
		if (state == null)
		{
			return;
		}
		int nowDay = G.GetNow().days;
		state.HasWitness = true;
		state.FederalWitnessCount = Mathf.Max(1, state.FederalWitnessCount);
		state.WitnessCount = Mathf.Max(minWitnessCount, state.WitnessCount);
		state.WitnessCount = Mathf.Max(state.WitnessCount, state.FederalWitnessCount);
		state.WitnessThreatAttempted = false;
		state.WitnessThreatenedSuccessfully = false;
		state.CaseDismissed = false;
		SetLocalHeatProgress(state, 1f, nowDay, refreshDecayAnchor: true);
		state.FedsIncoming = true;
		state.FedArrivalCountdown = Mathf.Max(1, fedArrivalCountdown);
	}

	internal static void ForceHardMaxLocalHeat(EntityID peepId, int minWitnessCount = 1)
	{
		if (peepId.IsNotValid)
		{
			return;
		}
		CrewModState state = GetOrCreateCrewState(peepId);
		if (state == null)
		{
			return;
		}
		int nowDay = G.GetNow().days;
		state.HasWitness = true;
		state.WitnessCount = Mathf.Max(minWitnessCount, state.WitnessCount);
		state.WitnessThreatAttempted = false;
		state.WitnessThreatenedSuccessfully = false;
		state.CaseDismissed = false;
		SetLocalHeatProgress(state, 1f, nowDay, refreshDecayAnchor: true);
		state.FedsIncoming = false;
		state.FedArrivalCountdown = 0;
	}

	internal static void SpreadLowLocalHeatToCrew(PlayerInfo humanPlayer, EntityID offenderPeepId)
	{
		if (humanPlayer?.crew == null)
		{
			return;
		}
		int nowDay = G.GetNow().days;
		try
		{
			foreach (CrewAssignment assignment in humanPlayer.crew.GetLiving())
			{
				if (!assignment.IsValid || assignment.peepId.IsNotValid)
				{
					continue;
				}
				if (assignment.peepId == offenderPeepId)
				{
					continue;
				}
				CrewModState state = GetOrCreateCrewState(assignment.peepId);
				if (state == null)
				{
					continue;
				}
				float target = Mathf.Max(state.LocalHeatProgress, LOCAL_HEAT_LOW_FLOOR);
				SetLocalHeatProgress(state, target, nowDay, refreshDecayAnchor: true);
			}
		}
		catch
		{
		}
	}

	internal static void RegisterImportantWitness(EntityID peepId, int sourceType, int arrestDueDay)
	{
		if (peepId.IsNotValid)
		{
			return;
		}
		if (SaveData.NationalHeat == null)
		{
			SaveData.NationalHeat = new NationalHeatState();
		}
		long peepLongId = (long)peepId.id;
		ImportantWitnessEntry existing = SaveData.NationalHeat.WitnessEntries
			.FirstOrDefault(e => e != null && e.CrewPeepId == peepLongId && !e.ArrestProcessed && e.SourceType == sourceType);
		int nowDay = G.GetNow().days;
		if (existing == null)
		{
			existing = new ImportantWitnessEntry
			{
				CrewPeepId = peepLongId,
				PrimaryCrewPeepId = peepLongId,
				SourceType = sourceType,
				AddedDay = nowDay,
				ArrestDueDay = arrestDueDay,
				ArrestProcessed = false,
				SentenceBoostApplied = false
			};
			SaveData.NationalHeat.WitnessEntries.Add(existing);
		}
		else
		{
			existing.AddedDay = nowDay;
			existing.ArrestDueDay = arrestDueDay;
		}
		existing.PrimaryCrewPeepId = peepLongId;
		existing.GroupedIncidentKey = string.Empty;
		existing.GroupedCompanionPeepIds = string.Empty;
		existing.GroupedSnitchResolved = false;
		existing.GroupedSnitchExposedCompanions = false;
		existing.DeferredFederalFinalizationPending = false;
		existing.DeferredFederalFinalizationDay = -1;
		SaveData.NationalHeat.Active = true;
		SaveData.NationalHeat.Level = Mathf.Max(SaveData.NationalHeat.Level, 1);
		SaveData.NationalHeat.LastEscalationDay = nowDay;
		CrewModState state = GetOrCreateCrewState(peepId);
		if (IsFederalImportantWitnessSource(sourceType))
		{
			if (state != null)
			{
				state.HasWitness = true;
				state.FederalWitnessCount = Mathf.Max(1, state.FederalWitnessCount);
				state.WitnessCount = Mathf.Max(3, state.WitnessCount);
				state.WitnessCount = Mathf.Max(state.WitnessCount, state.FederalWitnessCount);
			}
		}
		else if (sourceType == NATIONAL_HEAT_SOURCE_COP_ASSAULT && state != null)
		{
			state.HasWitness = true;
			state.WitnessCount = Mathf.Max(1, state.WitnessCount);
			state.CaseDismissed = false;
		}
		VerificationLog("NationalHeat", $"Entry created peep={peepId.id} source={sourceType} dueDay={arrestDueDay}");
	}

	internal static void RegisterGroupedCopWitness(EntityID primaryPeepId, int sourceType, int arrestDueDay, string incidentKey, IEnumerable<EntityID> companionPeepIds)
	{
		if (primaryPeepId.IsNotValid)
		{
			return;
		}

		RegisterImportantWitness(primaryPeepId, sourceType, arrestDueDay);
		if (SaveData.NationalHeat?.WitnessEntries == null)
		{
			return;
		}

		long primaryLongId = (long)primaryPeepId.id;
		ImportantWitnessEntry entry = SaveData.NationalHeat.WitnessEntries
			.FirstOrDefault(e => e != null && !e.ArrestProcessed && e.CrewPeepId == primaryLongId && e.SourceType == sourceType);
		if (entry == null)
		{
			return;
		}

		List<long> companionIds = companionPeepIds?
			.Where(id => id.IsValid && id != primaryPeepId)
			.Select(id => (long)id.id)
			.Distinct()
			.ToList() ?? new List<long>();

		entry.PrimaryCrewPeepId = primaryLongId;
		entry.GroupedIncidentKey = incidentKey ?? string.Empty;
		entry.GroupedCompanionPeepIds = string.Join(",", companionIds);
		entry.GroupedSnitchResolved = false;
		entry.GroupedSnitchExposedCompanions = false;
		VerificationLog("NationalHeat", $"{GetGroupedCopWitnessLogPrefix(sourceType)}-primary-entry-created peep={primaryPeepId.id} dueDay={arrestDueDay} incident={entry.GroupedIncidentKey} companions={companionIds.Count}");
	}

	internal static void RegisterGroupedCopKillWitness(EntityID primaryPeepId, int arrestDueDay, string incidentKey, IEnumerable<EntityID> companionPeepIds)
	{
		RegisterGroupedCopWitness(primaryPeepId, NATIONAL_HEAT_SOURCE_COP_KILL, arrestDueDay, incidentKey, companionPeepIds);
	}

	internal static void RegisterGroupedCopAssaultWitness(EntityID primaryPeepId, int arrestDueDay, string incidentKey, IEnumerable<EntityID> companionPeepIds)
	{
		RegisterGroupedCopWitness(primaryPeepId, NATIONAL_HEAT_SOURCE_COP_ASSAULT, arrestDueDay, incidentKey, companionPeepIds);
	}

	private static List<EntityID> ParseGroupedCopKillCompanionIds(ImportantWitnessEntry entry)
	{
		List<EntityID> result = new List<EntityID>();
		if (entry == null || string.IsNullOrWhiteSpace(entry.GroupedCompanionPeepIds))
		{
			return result;
		}

		foreach (string token in entry.GroupedCompanionPeepIds.Split(new char[1] { ',' }, StringSplitOptions.RemoveEmptyEntries))
		{
			if (!long.TryParse(token, NumberStyles.Integer, CultureInfo.InvariantCulture, out long rawId) || rawId <= 0L)
			{
				continue;
			}
			try
			{
				EntityID peepId = EntityID.FromID((ulong)rawId);
				if (peepId.IsValid)
				{
					result.Add(peepId);
				}
			}
			catch
			{
			}
		}

		return result
			.Where(id => id.IsValid)
			.Distinct()
			.ToList();
	}

	private static void ResolveGroupedCopIncidentSnitchOutcome(PlayerInfo humanPlayer, EntityID peepId, ImportantWitnessEntry entry, SimTime now)
	{
		if (entry == null
			|| !IsGroupedCopWitnessSource(entry.SourceType)
			|| entry.GroupedSnitchResolved
			|| entry.PrimaryCrewPeepId <= 0L
			|| entry.PrimaryCrewPeepId != (long)peepId.id)
		{
			return;
		}

		string logPrefix = GetGroupedCopWitnessLogPrefix(entry.SourceType);
		List<EntityID> companionIds = ParseGroupedCopKillCompanionIds(entry);
		entry.GroupedSnitchResolved = true;
		if (companionIds.Count == 0)
		{
			entry.GroupedCompanionPeepIds = string.Empty;
			return;
		}

		Entity peep = null;
		try
		{
			peep = peepId.FindEntity();
		}
		catch
		{
		}
		PlayerInfo resolvedHumanPlayer = humanPlayer ?? G.GetHumanPlayer();
		if (peep == null || resolvedHumanPlayer == null)
		{
			entry.GroupedCompanionPeepIds = string.Empty;
			entry.GroupedSnitchExposedCompanions = false;
			VerificationLog("NationalHeat", $"{logPrefix}-snitch-kept-silent peep={peepId.id} companions={companionIds.Count} reason=missing-context incident={entry.GroupedIncidentKey}");
			return;
		}

		if (IsHumanBoss(peep, resolvedHumanPlayer) || IsCaptainCrewMember(peep))
		{
			entry.GroupedCompanionPeepIds = string.Empty;
			entry.GroupedSnitchExposedCompanions = false;
			VerificationLog("NationalHeat", $"{logPrefix}-snitch-blocked-rank peep={peepId.id} companions={companionIds.Count} incident={entry.GroupedIncidentKey}");
			return;
		}

		CrewModState state = GetOrCreateCrewState(peepId);
		EnsureLoyaltyInitialized(peep, state, resolvedHumanPlayer);
		float loyalty = Mathf.Clamp01(state?.LoyaltyValue ?? 0.5f);
		float snitchWeight = (state != null && state.SnitchWeightInitialized)
			? state.SnitchWeight
			: ComputeTraitSnitchWeight(peep);
		float snitchChance = Mathf.Clamp(snitchWeight + Mathf.Max(0f, 0.55f - loyalty) * 0.7f, 0.05f, 0.85f);
		bool exposedCompanions = SharedRng.NextDouble() < snitchChance;
		entry.GroupedSnitchExposedCompanions = exposedCompanions;
		VerificationLog("NationalHeat", $"{logPrefix}-snitch-roll peep={peepId.id} companions={companionIds.Count} loyalty={loyalty:0.000} traitWeight={snitchWeight:0.000} chance={snitchChance:0.000} exposed={exposedCompanions} incident={entry.GroupedIncidentKey}");
		if (!exposedCompanions)
		{
			entry.GroupedCompanionPeepIds = string.Empty;
			VerificationLog("NationalHeat", $"{logPrefix}-snitch-kept-silent peep={peepId.id} companions={companionIds.Count} incident={entry.GroupedIncidentKey}");
			return;
		}

		int baseDueDay = GetImportantWitnessArrestDueDay(entry.SourceType, now.days);
		int staggerDays = GetGroupedCopWitnessFollowupStaggerDays(entry.SourceType);
		for (int i = 0; i < companionIds.Count; i++)
		{
			EntityID companionId = companionIds[i];
			int dueDay = baseDueDay + (i * staggerDays);
			RegisterImportantWitness(companionId, entry.SourceType, dueDay);
			VerificationLog("NationalHeat", $"{logPrefix}-snitch-followup-scheduled peep={companionId.id} dueDay={dueDay} sourcePeep={peepId.id} incident={entry.GroupedIncidentKey}");
		}
		entry.GroupedCompanionPeepIds = string.Empty;
		VerificationLog("NationalHeat", $"{logPrefix}-snitch-exposed peep={peepId.id} companions={string.Join(",", companionIds.Select(id => id.id.ToString()))} incident={entry.GroupedIncidentKey}");
	}

	internal static bool HasActiveImportantWitnessForCrew(EntityID peepId)
	{
		if (peepId.IsNotValid || SaveData.NationalHeat?.WitnessEntries == null)
		{
			return false;
		}
		long peepLongId = (long)peepId.id;
		return SaveData.NationalHeat.WitnessEntries.Any(e => e != null && !e.ArrestProcessed && e.CrewPeepId == peepLongId);
	}

	internal static bool HasActiveImportantWitnessForCrewAndSource(EntityID peepId, int sourceType)
	{
		if (peepId.IsNotValid || SaveData.NationalHeat?.WitnessEntries == null)
		{
			return false;
		}
		long peepLongId = (long)peepId.id;
		return SaveData.NationalHeat.WitnessEntries.Any(e =>
			e != null
			&& !e.ArrestProcessed
			&& e.CrewPeepId == peepLongId
			&& e.SourceType == sourceType);
	}

	internal static void PromoteGroupedCopAssaultIncidentToKill(string incidentKey, EntityID promotedPeepId)
	{
		if (string.IsNullOrWhiteSpace(incidentKey) || SaveData.NationalHeat?.WitnessEntries == null)
		{
			return;
		}

		foreach (ImportantWitnessEntry entry in SaveData.NationalHeat.WitnessEntries)
		{
			if (entry == null
				|| entry.ArrestProcessed
				|| entry.SourceType != NATIONAL_HEAT_SOURCE_COP_ASSAULT
				|| !string.Equals(entry.GroupedIncidentKey, incidentKey, StringComparison.Ordinal))
			{
				continue;
			}

			MarkImportantWitnessEntryProcessed(entry);
			entry.GroupedCompanionPeepIds = string.Empty;
			entry.GroupedSnitchResolved = true;
			entry.GroupedSnitchExposedCompanions = false;
			VerificationLog("NationalHeat", $"grouped-cop-assault-promoted peep={entry.CrewPeepId} promotedPeep={promotedPeepId.id} incident={incidentKey}");
		}
	}

	private static void SetCurrentNationalHeatArrestSourceType(int sourceType)
	{
		_currentNationalHeatArrestSourceType = sourceType;
	}

	private static void ClearCurrentNationalHeatArrestSourceType()
	{
		_currentNationalHeatArrestSourceType = -1;
	}

	private static bool TryGetCurrentNationalHeatArrestSourceType(out int sourceType)
	{
		sourceType = _currentNationalHeatArrestSourceType;
		return sourceType >= 0;
	}

	internal static int GetThreatenableWitnessCount(CrewModState state)
	{
		if (state == null)
		{
			return 0;
		}
		int scalarWitnesses = Mathf.Max(0, state.WitnessCount - Mathf.Max(0, state.FederalWitnessCount));
		int openMurderWitnessRecords = CountOpenMurderWitnessRecords(state);
		return Mathf.Max(scalarWitnesses, openMurderWitnessRecords);
	}

	private static int CountActiveImportantWitnessEntries()
	{
		if (SaveData.NationalHeat?.WitnessEntries == null)
		{
			return 0;
		}
		return SaveData.NationalHeat.WitnessEntries.Count(e => e != null && !e.ArrestProcessed);
	}

	private static string GetNationalHeatUiLabel()
	{
		if (SaveData.NationalHeat == null || !SaveData.NationalHeat.Active)
		{
			return "National Heat: None | Important Witnesses: 0";
		}
		string levelText = (SaveData.NationalHeat.Level >= 3) ? "Critical" : ((SaveData.NationalHeat.Level == 2) ? "Elevated" : "Active");
		int activeWitnesses = CountActiveImportantWitnessEntries();
		return $"National Heat: {levelText} | Important Witnesses: {activeWitnesses}";
	}

	private static void ApplyLocalHeatDecay(CrewModState state, int nowDay)
	{
		if (state == null)
		{
			return;
		}
		if (state.LocalHeatProgress <= 0f)
		{
			state.LocalHeatLastRefreshDay = nowDay;
			SetLocalHeatProgress(state, 0f, nowDay, refreshDecayAnchor: false);
			return;
		}
		if (state.LocalHeatLastRefreshDay < 0)
		{
			state.LocalHeatLastRefreshDay = nowDay;
			return;
		}
		int elapsedDays = nowDay - state.LocalHeatLastRefreshDay;
		if (elapsedDays <= 0)
		{
			return;
		}
		float decayStep = (float)elapsedDays / (float)LOCAL_HEAT_DECAY_TURNS;
		float nextProgress = Mathf.Max(0f, state.LocalHeatProgress - decayStep);
		SetLocalHeatProgress(state, nextProgress, nowDay, refreshDecayAnchor: true);
	}

	/// <summary>Returns the PlayerInfo whose crew contains the given peep, or null if not in any crew.</summary>
	internal static PlayerInfo FindPlayerOwningCrewMember(EntityID peepId)
	{
		if (peepId.IsNotValid)
		{
			return null;
		}
		try
		{
			foreach (PlayerInfo p in G.GetAllPlayers())
			{
				if (p?.crew == null)
				{
					continue;
				}
				CrewAssignment assignment = p.crew.GetCrewForPeep(peepId);
				if (assignment.IsValid)
				{
					return p;
				}
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] FindPlayerOwningCrewMember failed: " + ex.Message);
		}
		return null;
	}

	private static void ProcessNationalHeatTurn(PlayerInfo humanPlayer, SimTime now)
	{
		if (SaveData.NationalHeat == null)
		{
			SaveData.NationalHeat = new NationalHeatState();
		}
		if (SaveData.NationalHeat.WitnessEntries == null)
		{
			SaveData.NationalHeat.WitnessEntries = new List<ImportantWitnessEntry>();
		}
		for (int i = SaveData.NationalHeat.WitnessEntries.Count - 1; i >= 0; i--)
		{
			ImportantWitnessEntry entry = SaveData.NationalHeat.WitnessEntries[i];
			if (entry == null)
			{
				SaveData.NationalHeat.WitnessEntries.RemoveAt(i);
				continue;
			}
			if (entry.ArrestProcessed)
			{
				continue;
			}
			if (entry.CrewPeepId <= 0L)
			{
				MarkImportantWitnessEntryProcessed(entry);
				continue;
			}
			try
			{
				EntityID peepId;
				try
				{
					peepId = EntityID.FromID((ulong)entry.CrewPeepId);
				}
				catch
				{
					MarkImportantWitnessEntryProcessed(entry);
					continue;
				}
				if (peepId.IsNotValid)
				{
					MarkImportantWitnessEntryProcessed(entry);
					continue;
				}
				if (entry.SourceType == NATIONAL_HEAT_SOURCE_COP_KILL && entry.DeferredFederalFinalizationPending)
				{
					if (entry.DeferredFederalFinalizationDay == now.days)
					{
						VerificationLog("NationalHeat", $"important-witness-safe-federal-awaiting-flush peep={peepId.id} dueDay={entry.ArrestDueDay} source={entry.SourceType} pendingDay={entry.DeferredFederalFinalizationDay}");
						continue;
					}

					ClearDeferredFederalWitnessFinalization(entry);
				}
				bool groupedCopWitness = IsGroupedCopWitnessSource(entry.SourceType);
				if (TryShouldSkipCornerRaidArrestRefresh(peepId, "national-heat-turn", out string refreshSkipReason, out bool refreshDeduped)
					&& (refreshDeduped || IsTerminalCornerRaidArrestSkipReason(refreshSkipReason)))
				{
					MarkImportantWitnessEntryProcessed(entry);
					VerificationLog("NationalHeat", $"Witness entry closed after prior arrest handling peep={peepId.id} reason={refreshSkipReason} deduped={refreshDeduped}");
					if (groupedCopWitness)
					{
						VerificationLog("NationalHeat", $"grouped-cop-case-closeout peep={peepId.id} source={entry.SourceType} dueDay={entry.ArrestDueDay} reason={refreshSkipReason}");
					}
					if (IsTerminalCornerRaidArrestSkipReason(refreshSkipReason))
					{
						LogNationalHeatTerminalCloseout(peepId, "national-heat-turn", refreshSkipReason, 1);
					}
					continue;
				}
				CrewModState state = GetOrCreateCrewState(peepId);
				bool inJail = JailSystem.IsInJail(peepId) || (state != null && state.InJail);
				bool isHidden = state != null && (state.OnHideout || state.HideoutPending);
				bool isCopKillWitness = HasActiveImportantWitnessForCrewAndSource(peepId, NATIONAL_HEAT_SOURCE_COP_KILL);
				if (state != null)
				{
					if (isCopKillWitness)
					{
						state.FederalWitnessCount = Mathf.Max(1, state.FederalWitnessCount);
						state.WitnessCount = Mathf.Max(3, state.WitnessCount);
						state.WitnessCount = Mathf.Max(state.WitnessCount, state.FederalWitnessCount);
						state.HasWitness = true;
					}
					else if (state.FederalWitnessCount > 0 && !HasActiveImportantWitnessForCrew(peepId))
					{
						state.FederalWitnessCount = 0;
					}
				}
				if (!inJail && !isHidden)
				{
					RaiseLocalHeatFloor(peepId, 1f, refreshDecayAnchor: true);
				}
				if (isHidden)
				{
					if (entry.ArrestDueDay <= now.days)
					{
						entry.ArrestDueDay = now.days + 1;
					}
					VerificationLog("NationalHeat", $"Arrest deferred while in hideout peep={peepId.id} dueDay={entry.ArrestDueDay}");
					continue;
				}
				if (now.days < entry.ArrestDueDay)
				{
					continue;
				}
				bool arrestProcessed = false;
				Entity peepEntity = null;
				try
				{
					peepEntity = peepId.FindEntity();
				}
				catch
				{
				}
				if (inJail)
				{
					arrestProcessed = true;
				}
				else if (peepEntity != null && peepEntity.data?.person != null && peepEntity.data.person.IsAlive)
				{
					if (peepEntity.components?.agent == null)
					{
						entry.ArrestDueDay = Math.Max(entry.ArrestDueDay, now.days + 1);
						VerificationLog("NationalHeat", $"Witness entry deferred for unstable peep={peepId.id} dueDay={entry.ArrestDueDay} reason=agent-missing");
						continue;
					}
					PlayerInfo owner = FindPlayerOwningCrewMember(peepId);
					if (owner?.crew != null)
					{
						if (entry.SourceType == NATIONAL_HEAT_SOURCE_COP_KILL)
						{
							CrewAssignment pendingCrew = owner.crew.GetCrewForPeep(peepId);
							EntityID pendingVehicleId = pendingCrew.IsValid ? pendingCrew.VehicleID : EntityID.INVALID;
							if (HasSafeFederalArrestPendingForVehicleToday(pendingVehicleId, peepId, out EntityID pendingPeepId))
							{
								entry.ArrestDueDay = Math.Max(entry.ArrestDueDay, now.days + 1);
								VerificationLog("NationalHeat", $"national-heat-safe-federal-pending peep={peepId.id} vehicle={pendingVehicleId.id} pendingPeep={pendingPeepId.id} dueDay={entry.ArrestDueDay}");
								VerificationLog("NationalHeat", $"grouped-cop-case-deferred-after-safe-arrest peep={peepId.id} vehicle={pendingVehicleId.id} pendingPeep={pendingPeepId.id} dueDay={entry.ArrestDueDay}");
								continue;
							}
						}
						try
						{
							if (entry.SourceType == NATIONAL_HEAT_SOURCE_COP_ASSAULT)
							{
								arrestProcessed = ExecuteLocalImportantWitnessArrest(owner, peepEntity, "important-witness-assault");
							}
							else
							{
								SetCurrentNationalHeatArrestSourceType(entry.SourceType);
								arrestProcessed = JailSystem.ArrestCrew(owner, peepEntity);
							}
						}
						catch (Exception arrestEx)
						{
							entry.ArrestDueDay = Math.Max(entry.ArrestDueDay, now.days + 1);
							VerificationLog("NationalHeat", $"Witness entry deferred after arrest failure peep={peepId.id} dueDay={entry.ArrestDueDay} ex={arrestEx.GetType().Name}");
							Debug.LogWarning($"[GameplayTweaks] National heat arrest deferred for peep={peepId.id}: {arrestEx.Message}");
							continue;
						}
						finally
						{
							if (entry.SourceType != NATIONAL_HEAT_SOURCE_COP_ASSAULT)
							{
								ClearCurrentNationalHeatArrestSourceType();
							}
						}
					}
					else
					{
						MarkImportantWitnessEntryProcessed(entry);
						VerificationLog("NationalHeat", $"Witness entry skipped - no owning crew for peep={peepId.id}");
					}
				}
				else if (peepEntity == null)
				{
					MarkImportantWitnessEntryProcessed(entry);
					VerificationLog("NationalHeat", $"Witness entry auto-closed for missing peep={entry.CrewPeepId}.");
					continue;
				}
				if (!arrestProcessed)
				{
					continue;
				}
				if (entry.SourceType == NATIONAL_HEAT_SOURCE_COP_KILL && WasSafeFederalArrestHandledToday(peepId))
				{
					if (!TryMarkImportantWitnessSafeFederalPending(peepId, entry.SourceType, now, entry.ArrestDueDay))
					{
						VerificationLog("NationalHeat", $"important-witness-safe-federal-pending-missed peep={peepId.id} dueDay={entry.ArrestDueDay} source={entry.SourceType}");
					}
					continue;
				}
				if (state == null)
				{
					state = GetOrCreateCrewState(peepId);
				}
				ApplyImportantWitnessSentenceBoost(peepId, state, entry);
				ResolveGroupedCopIncidentSnitchOutcome(humanPlayer, peepId, entry, now);
				MarkImportantWitnessEntryProcessed(entry);
				string witnessCloseout = (entry.SourceType == NATIONAL_HEAT_SOURCE_COP_ASSAULT)
					? "Important witness custody staged"
					: "Important witness arrest executed";
				VerificationLog("NationalHeat", $"{witnessCloseout} peep={peepId.id} dueDay={entry.ArrestDueDay} extraYears={GetImportantWitnessSentenceBoostYears(entry.SourceType)} source={entry.SourceType}");
				if (groupedCopWitness)
				{
					VerificationLog("NationalHeat", $"grouped-cop-case-closeout peep={peepId.id} source={entry.SourceType} dueDay={entry.ArrestDueDay} reason=executed");
				}
			}
			catch (Exception ex)
			{
				entry.ArrestDueDay = Math.Max(entry.ArrestDueDay, now.days + 1);
				VerificationLog("NationalHeat", $"Witness entry deferred after exception peep={entry.CrewPeepId} dueDay={entry.ArrestDueDay} ex={ex.GetType().Name}");
				Debug.LogWarning($"[GameplayTweaks] ProcessNationalHeatTurn entry failed for peep={entry.CrewPeepId}: {ex.Message}");
			}
		}
		RecalculateNationalHeatState(now.days);
	}

	private static void RecalculateNationalHeatState(int nowDay)
	{
		if (SaveData.NationalHeat == null)
		{
			SaveData.NationalHeat = new NationalHeatState();
		}
		if (SaveData.NationalHeat.WitnessEntries == null)
		{
			SaveData.NationalHeat.WitnessEntries = new List<ImportantWitnessEntry>();
		}
		int activeCount = SaveData.NationalHeat.WitnessEntries.Count(e => e != null && !e.ArrestProcessed);
		SaveData.NationalHeat.Active = activeCount > 0;
		SaveData.NationalHeat.Level = (activeCount >= 3) ? 3 : ((activeCount >= 2) ? 2 : ((activeCount == 1) ? 1 : 0));
		if (activeCount > 0)
		{
			SaveData.NationalHeat.LastEscalationDay = Mathf.Max(SaveData.NationalHeat.LastEscalationDay, nowDay);
		}
	}

	private static void ApplyImportantWitnessSentenceBoost(EntityID peepId, CrewModState state, ImportantWitnessEntry entry)
	{
		if (entry == null || entry.SentenceBoostApplied)
		{
			return;
		}
		int sentenceYears = GetImportantWitnessSentenceBoostYears(entry.SourceType);
		if (state != null)
		{
			state.ExtraJailYears += sentenceYears;
			state.TrialDaysRemaining = Mathf.Max(state.TrialDaysRemaining, 7) + sentenceYears * 7;
			state.WitnessCount = Mathf.Max(state.WitnessCount, 1);
		}
		bool reflectionBoost = false;
		string appliedDetails = "staged";
		if (entry.SourceType == NATIONAL_HEAT_SOURCE_COP_ASSAULT)
		{
			SyncLocalImportantWitnessCustodyPendingFromState(peepId, entry.SourceType, state, "sentence-boost");
		}
		else if (entry.SourceType == NATIONAL_HEAT_SOURCE_COP_KILL)
		{
			reflectionBoost = JailSystem.TryApplySentenceBoost(peepId, sentenceYears, out appliedDetails);
		}
		entry.SentenceBoostApplied = true;
		if (reflectionBoost)
		{
			VerificationLog("NationalHeat", $"sentence-boost-record-applied peep={peepId.id} source={entry.SourceType} details={appliedDetails}");
		}
		else if (entry.SourceType == NATIONAL_HEAT_SOURCE_COP_ASSAULT)
		{
			VerificationLog("NationalHeat", $"sentence-boost-local-status-applied peep={peepId.id} trialDays={state?.TrialDaysRemaining ?? 0} extraYears={state?.ExtraJailYears ?? 0}");
		}
		VerificationLog("NationalHeat", $"Sentence boost applied peep={peepId.id} years={sentenceYears} reflection={reflectionBoost} source={entry.SourceType}");
	}

	internal static int ScrubCopScavengeableVehicles(PlayerInfo player, string source)
	{
		if (player?.crew == null || !player.IsJustCop)
		{
			return 0;
		}

		int scrubbed = 0;
		try
		{
			List<EntityID> staleVehicleIds = player.crew.AllScavengeableCars
				.Where(id => id.IsValid)
				.Distinct()
				.ToList();
			foreach (EntityID vehicleId in staleVehicleIds)
			{
				bool hasLiveOccupants = player.crew.AllCrew.Any(assignment => assignment.IsValid && assignment.IsNotDead && assignment.IsInVehicle && assignment.VehicleID == vehicleId);
				RemoveScavengeableCarRecord(player.crew, vehicleId);
				bool destroyed = false;
				bool cleanedPresentation = false;
				if (!hasLiveOccupants)
				{
					cleanedPresentation = MultiCrewVehicleHelper.TryCleanupEmptyEnemyVehiclePresentation(player.crew, vehicleId, "cop-scavengeable-scrub", out _);
					destroyed = TryDestroyTrackedCopVehicle(player, vehicleId, "cop-scavengeable-scrub");
					ClearCrewPicksForTargets("cop-scavengeable-scrub", EntityID.INVALID, vehicleId);
				}
				scrubbed++;
				VerificationLog("CopVehicleCleanup", $"cop-scavengeable-vehicle-scrubbed vehicle={vehicleId.id} ownerPid={player.PID.id} source={source} hadLiveOccupants={hasLiveOccupants} cleanedPresentation={cleanedPresentation} destroyed={destroyed} persisted={(vehicleId.FindEntity() != null)}");
				VerificationLog("CopVehicleCleanup", $"cop-collect-vehicle-skipped vehicle={vehicleId.id} ownerPid={player.PID.id} source={source}");
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] ScrubCopScavengeableVehicles failed: " + ex.Message);
		}
		return scrubbed;
	}

	internal static int ScrubInvalidScavengeableVehiclesForAllPlayers(string source)
	{
		int frame = Time.frameCount;
		if (_lastGlobalScavengeableVehicleScrubFrame == frame)
		{
			return 0;
		}
		_lastGlobalScavengeableVehicleScrubFrame = frame;

		int scrubbed = 0;
		int owners = 0;
		try
		{
			IEnumerable<PlayerInfo> players = G.GetAllPlayers();
			if (players == null)
			{
				return 0;
			}

			foreach (PlayerInfo player in players)
			{
				if (player?.crew == null)
				{
					continue;
				}

				int ownerScrubbed = 0;
				List<EntityID> scavengeableCars;
				try
				{
					scavengeableCars = player.crew.AllScavengeableCars
						.ToList();
				}
				catch
				{
					continue;
				}

				for (int i = 0; i < scavengeableCars.Count; i++)
				{
					EntityID vehicleId = scavengeableCars[i];
					Entity vehicle = vehicleId.IsValid ? vehicleId.FindEntity() : null;
					if (vehicleId.IsNotValid || vehicle?.data?.mobile == null)
					{
						if (RemoveScavengeableCarRecord(player.crew, vehicleId))
						{
							ownerScrubbed++;
						}
					}
				}

				if (ownerScrubbed > 0)
				{
					owners++;
					scrubbed += ownerScrubbed;
				}
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] ScrubInvalidScavengeableVehiclesForAllPlayers failed: " + ex.Message);
		}

		if (scrubbed > 0)
		{
			VerificationLog("CopVehicleCleanup", $"stale-scavengeable-vehicles-scrubbed source={source} owners={owners} vehicles={scrubbed} frame={frame}");
		}
		return scrubbed;
	}

	internal static int ReconcileCopPrecinctOfficers(PlayerInfo player, string source)
	{
		if (player?.crew == null || player.ai?.precinct == null || !player.IsJustCop)
		{
			return 0;
		}

		try
		{
			EntityID stationId = player.ai.precinct.StationBuilding;
			Entity station = stationId.IsValid ? stationId.FindEntity() : null;
			List<EntityID> officers = station?.data?.police?.officers;
			if (officers == null)
			{
				return 0;
			}

			List<CrewAssignment> livingCops = player.crew.GetLiving()
				.Where(assignment => assignment.IsValid && assignment.IsNotDead && assignment.peepId.IsValid)
				.ToList();
			HashSet<EntityID> livingIds = new HashSet<EntityID>(livingCops.Select(assignment => assignment.peepId));
			int removed = 0;
			HashSet<EntityID> seen = new HashSet<EntityID>();
			for (int i = officers.Count - 1; i >= 0; i--)
			{
				EntityID officerId = officers[i];
				Entity officer = officerId.IsValid ? officerId.FindEntity() : null;
				bool keep = officerId.IsValid
					&& livingIds.Contains(officerId)
					&& seen.Add(officerId)
					&& officer?.data?.person?.IsAlive == true;
				if (!keep)
				{
					officers.RemoveAt(i);
					removed++;
				}
			}

			int added = 0;
			int beatsAssigned = 0;
			foreach (CrewAssignment assignment in livingCops)
			{
				if (!officers.Contains(assignment.peepId))
				{
					officers.Add(assignment.peepId);
					added++;
				}
				if (!HasUsableCopBeat(player, assignment.peepId))
				{
					List<NodeID> beatNodes = BuildFallbackCopBeatNodes(player, station);
					if (beatNodes.Count > 0)
					{
						PrecinctAdvisor.AssignBeatToOfficer(player.ai, assignment.peepId, beatNodes);
						beatsAssigned++;
					}
				}
			}

			int changed = removed + added + beatsAssigned;
			if (changed > 0)
			{
				VerificationLog("CopPrecinctRecovery", $"cop-precinct-officers-reconciled pid={player.PID.id} station={stationId.id} source={source} living={livingCops.Count} officers={officers.Count} removed={removed} added={added} beatsAssigned={beatsAssigned}");
			}
			return changed;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] ReconcileCopPrecinctOfficers failed: " + ex.Message);
			return 0;
		}
	}

	internal static bool TryGetRecoveredCopBeatNode(PlayerInfo player, EntityID officerId, string source, out NodeID nodeId)
	{
		nodeId = NodeID.INVALID;
		if (player?.ai?.Data?.precinct == null || officerId.IsNotValid)
		{
			return false;
		}

		try
		{
			ReconcileCopPrecinctOfficers(player, source);
			CopBeat beat = player.ai.Data.precinct.GetBeat(officerId);
			if (beat?.nodes == null)
			{
				return false;
			}
			foreach (NodeID candidate in beat.nodes)
			{
				if (candidate.IsValid)
				{
					nodeId = candidate;
					VerificationLog("CopPrecinctRecovery", $"cop-beat-node-recovered pid={player.PID.id} peep={officerId.id} node={nodeId} source={source} beatNodes={beat.nodes.Count}");
					return true;
				}
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryGetRecoveredCopBeatNode failed: " + ex.Message);
		}
		return false;
	}

	private static bool HasUsableCopBeat(PlayerInfo player, EntityID officerId)
	{
		try
		{
			CopBeat beat = player?.ai?.Data?.precinct?.GetBeat(officerId);
			return beat?.nodes != null && beat.nodes.Any(nodeId => nodeId.IsValid);
		}
		catch
		{
			return false;
		}
	}

	private static List<NodeID> BuildFallbackCopBeatNodes(PlayerInfo player, Entity station)
	{
		List<NodeID> nodes = new List<NodeID>();
		try
		{
			PrecinctAdvisorData data = player?.ai?.Data?.precinct;
			if (data?.copbeats != null)
			{
				foreach (CopBeat beat in data.copbeats)
				{
					if (beat?.nodes == null || beat.nodes.Count == 0)
					{
						continue;
					}
					foreach (NodeID nodeId in beat.nodes)
					{
						if (nodeId.IsValid && !nodes.Contains(nodeId))
						{
							nodes.Add(nodeId);
						}
					}
					if (nodes.Count > 0)
					{
						break;
					}
				}
			}
			if (nodes.Count == 0)
			{
				NodeID stationNode = station?.data?.board?.bead.nodeId ?? NodeID.INVALID;
				if (stationNode.IsValid)
				{
					nodes.Add(stationNode);
				}
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] BuildFallbackCopBeatNodes failed: " + ex.Message);
		}
		return nodes;
	}

	internal static bool TryHandleDeadCopVehicleCleanup(PlayerInfo owner, EntityID peepId, EntityID vehicleId, string source)
	{
		if (owner?.crew == null || !owner.IsJustCop || vehicleId.IsNotValid)
		{
			return false;
		}

		try
		{
			bool hasLiveOccupants = owner.crew.AllCrew.Any(assignment => assignment.IsValid && assignment.IsNotDead && assignment.IsInVehicle && assignment.VehicleID == vehicleId);
			if (hasLiveOccupants)
			{
				RemoveScavengeableCarRecord(owner.crew, vehicleId);
				return false;
			}

			bool removedFromScavengeable = RemoveScavengeableCarRecord(owner.crew, vehicleId);
			bool rewardAvailable = false;
			bool cleanedPresentation = MultiCrewVehicleHelper.TryCleanupEmptyEnemyVehiclePresentation(owner.crew, vehicleId, "cop-death-cleanup", out rewardAvailable);
			bool destroyed = TryDestroyTrackedCopVehicle(owner, vehicleId, "cop-death-cleanup");
			bool despawned = destroyed || vehicleId.FindEntity() == null;
			if (!despawned && vehicleId.FindEntity() != null)
			{
				try
				{
					global::Game.Game.ctx?.transit?.DespawnCar(vehicleId, false);
				}
				catch (Exception ex)
				{
					Debug.LogWarning("[GameplayTweaks] Cop dead vehicle despawn failed: " + ex.Message);
				}
				despawned = vehicleId.FindEntity() == null;
			}
			ClearCrewPicksForTargets("cop-death-cleanup", peepId, vehicleId);
			VerificationLog("CopVehicleCleanup", $"cop-death-vehicle-cleanup peep={peepId.id} vehicle={vehicleId.id} ownerPid={owner.PID.id} source={source} removedFromScavengeable={removedFromScavengeable} rewardAvailable={rewardAvailable} cleanedPresentation={cleanedPresentation} destroyed={destroyed} despawned={despawned} persisted={(vehicleId.FindEntity() != null)}");
			return removedFromScavengeable || cleanedPresentation || despawned;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryHandleDeadCopVehicleCleanup failed: " + ex.Message);
			return false;
		}
	}

	internal static bool TryDestroyTrackedCopVehicle(PlayerInfo owner, EntityID vehicleId, string source)
	{
		if (owner?.crew == null || !owner.IsJustCop || vehicleId.IsNotValid)
		{
			return false;
		}

		try
		{
			if (vehicleId.FindEntity() == null)
			{
				return false;
			}

			owner.crew.DestroyAndUntrackVehicle(vehicleId, shutdown: false);
			bool destroyed = vehicleId.FindEntity() == null;
			VerificationLog("CopVehicleCleanup", $"cop-vehicle-destroyed vehicle={vehicleId.id} ownerPid={owner.PID.id} source={source} destroyed={destroyed}");
			return destroyed;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryDestroyTrackedCopVehicle failed: " + ex.Message);
			return false;
		}
	}

	internal static bool RemoveScavengeableCarRecord(PlayerCrew crew, EntityID vehicleId)
	{
		if (crew == null || vehicleId.IsNotValid)
		{
			return false;
		}

		try
		{
			FieldInfo crewDataField = typeof(PlayerCrew).GetField("_crewdata", BindingFlags.Instance | BindingFlags.NonPublic);
			object crewData = crewDataField?.GetValue(crew);
			if (crewData == null)
			{
				return false;
			}
			FieldInfo scavengeableField = crewData.GetType().GetField("scavengeableCars", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (!(scavengeableField?.GetValue(crewData) is IList<EntityID> list))
			{
				return false;
			}
			bool removed = false;
			while (list.Remove(vehicleId))
			{
				removed = true;
			}
			return removed;
		}
		catch
		{
			return false;
		}
	}

	internal static void TryApplyImportantWitnessFederalImprisonmentYears(PlayerInfo player, CrewAssignment crew, ref int years)
	{
		if (!crew.IsValid || crew.peepId.IsNotValid)
		{
			return;
		}

		CrewModState state = GetCrewStateOrNull(crew.peepId);
		int extraYears = Mathf.Max(0, state?.ExtraJailYears ?? 0);
		if (extraYears <= 0)
		{
			return;
		}

		int baseYears = Mathf.Max(0, years);
		years = baseYears + extraYears;
		if (state != null)
		{
			state.ExtraJailYears = 0;
			state.TrialDaysRemaining = 0;
			state.DaysInJail = 0;
		}
		VerificationLog("NationalHeat", $"sentence-boost-federal-years-applied peep={crew.peepId.id} player={(player?.PID.id ?? -1)} baseYears={baseYears} extraYears={extraYears} finalYears={years} startImprisonmentPatched=True");
	}

	internal static float GetLoyaltyHappinessPenaltyMultiplier(CrewModState crewState)
	{
		if (crewState == null)
		{
			return 1f;
		}
		float loyalty = Mathf.Clamp01(crewState.LoyaltyValue);
		return Mathf.Lerp(1f, 0.35f, loyalty);
	}

	private static bool HasTrait(Entity peep, string traitId)
	{
		if (peep?.data?.person?.traitIds == null || string.IsNullOrEmpty(traitId))
		{
			return false;
		}
		try
		{
			foreach (Label traitId2 in peep.data.person.traitIds)
			{
				string text = traitId2.ToString();
				if (string.Equals(text, traitId, StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
			}
		}
		catch
		{
		}
		return false;
	}

	internal static float ComputeTraitWeightedLoyaltyCap(Entity peep, PlayerInfo humanPlayer)
	{
		if (peep == null)
		{
			return 1f;
		}
		if (IsHumanBoss(peep, humanPlayer))
		{
			return 1f;
		}
		float num = 0.55f;
		if (HasTrait(peep, "trait-upright")) num += 0.15f;
		if (HasTrait(peep, "trait-organized")) num += 0.12f;
		if (HasTrait(peep, "trait-hardworking")) num += 0.10f;
		if (HasTrait(peep, "trait-forgiving")) num += 0.10f;
		if (HasTrait(peep, "trait-kind")) num += 0.07f;
		if (HasTrait(peep, "trait-compassionate")) num += 0.07f;
		if (HasTrait(peep, "trait-confident")) num += 0.05f;
		if (HasTrait(peep, "trait-religious")) num += 0.04f;
		if (HasTrait(peep, "trait-strong")) num += 0.03f;
		if (HasTrait(peep, "trait-immoral")) num -= 0.16f;
		if (HasTrait(peep, "trait-careless")) num -= 0.12f;
		if (HasTrait(peep, "trait-lazy")) num -= 0.11f;
		if (HasTrait(peep, "trait-cruel")) num -= 0.10f;
		if (HasTrait(peep, "trait-unkind")) num -= 0.08f;
		if (HasTrait(peep, "trait-irritable")) num -= 0.08f;
		if (HasTrait(peep, "trait-vindictive")) num -= 0.07f;
		if (HasTrait(peep, "trait-loner")) num -= 0.06f;
		if (HasTrait(peep, "trait-nervous")) num -= 0.05f;
		if (HasTrait(peep, "trait-aggressive")) num -= 0.05f;
		if (IsCaptainCrewMember(peep))
		{
			num += 0.04f;
		}
		return Mathf.Clamp(num, 0.1f, 1f);
	}

	internal static float ComputeTraitSnitchWeight(Entity peep)
	{
		if (peep == null)
		{
			return 0f;
		}
		float num = 0.08f;
		if (HasTrait(peep, "trait-talkative")) num += 0.20f;
		if (HasTrait(peep, "trait-vindictive")) num += 0.14f;
		if (HasTrait(peep, "trait-curious")) num += 0.12f;
		if (HasTrait(peep, "trait-nervous")) num += 0.12f;
		if (HasTrait(peep, "trait-irritable")) num += 0.10f;
		if (HasTrait(peep, "trait-connected")) num += 0.08f;
		if (HasTrait(peep, "trait-immoral")) num += 0.08f;
		if (HasTrait(peep, "trait-lazy")) num += 0.06f;
		if (HasTrait(peep, "trait-careless")) num += 0.06f;
		if (HasTrait(peep, "trait-quiet")) num -= 0.16f;
		if (HasTrait(peep, "trait-upright")) num -= 0.12f;
		if (HasTrait(peep, "trait-forgiving")) num -= 0.08f;
		if (HasTrait(peep, "trait-hardworking")) num -= 0.06f;
		if (HasTrait(peep, "trait-confident")) num -= 0.05f;
		if (HasTrait(peep, "trait-compassionate")) num -= 0.05f;
		if (HasTrait(peep, "trait-kind")) num -= 0.04f;
		return Mathf.Clamp(num, 0f, 0.95f);
	}

	internal static int CountPositiveLoyaltyTraits(Entity peep)
	{
		if (peep == null)
