	internal static int TrySpendDirtyCashFromStorage(PlayerInfo humanPlayer, int amount)
	{
		if (humanPlayer?.territory == null || amount <= 0)
		{
			return 0;
		}
		int num = 0;
		try
		{
			EntityID safehouse = humanPlayer.territory.Safehouse;
			if (!safehouse.IsNotValid)
			{
				Entity entity = EntityIDExtensions.FindEntity(safehouse);
				if (entity != null)
				{
					int num2 = RemoveDirtyCash(entity, amount);
					if (num2 > 0)
					{
						num += num2;
						amount -= num2;
					}
				}
			}
			if (amount <= 0)
			{
				return num;
			}
			FieldInfo fieldInfo = humanPlayer.territory.GetType().GetField("_buildings", BindingFlags.Instance | BindingFlags.NonPublic)
				?? humanPlayer.territory.GetType().GetField("buildings", BindingFlags.Instance | BindingFlags.NonPublic);
			PropertyInfo propertyInfo = humanPlayer.territory.GetType().GetProperty("OwnedBuildings", BindingFlags.Instance | BindingFlags.Public)
				?? humanPlayer.territory.GetType().GetProperty("Buildings", BindingFlags.Instance | BindingFlags.Public);
			object obj = fieldInfo?.GetValue(humanPlayer.territory) ?? propertyInfo?.GetValue(humanPlayer.territory);
			if (!(obj is IEnumerable<EntityID> enumerable))
			{
				return num;
			}
			foreach (EntityID item in enumerable)
			{
				if (amount <= 0)
				{
					break;
				}
				if (item.IsNotValid || item == safehouse)
				{
					continue;
				}
				Entity entity2 = EntityIDExtensions.FindEntity(item);
				if (entity2 == null)
				{
					continue;
				}
				int num3 = RemoveDirtyCash(entity2, amount);
				if (num3 > 0)
				{
					num += num3;
					amount -= num3;
				}
			}
		}
		catch
		{
		}
		return num;
	}

	private static bool TrySpendCombinedCash(PlayerInfo humanPlayer, int amount, out int cleanSpent, out int dirtySpent)
	{
		cleanSpent = 0;
		dirtySpent = 0;
		if (humanPlayer == null || amount <= 0)
		{
			return false;
		}
		int playerCleanCash = GetPlayerCleanCash();
		int totalDirtyCash = ShouldDeferDirtyCashRuntime() ? 0 : GetTotalDirtyCash();
		if (playerCleanCash + totalDirtyCash < amount)
		{
			return false;
		}
		cleanSpent = Math.Min(playerCleanCash, amount);
		if (cleanSpent > 0)
		{
			try
			{
				humanPlayer.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(-cleanSpent)), (MoneyReason)1);
			}
			catch
			{
				cleanSpent = 0;
				return false;
			}
		}
		int num = amount - cleanSpent;
		if (num > 0 && !ShouldDeferDirtyCashRuntime())
		{
			dirtySpent = TrySpendDirtyCashFromStorage(humanPlayer, num);
		}
		return cleanSpent + dirtySpent >= amount;
	}

	internal static void ProcessCrewFamilyTurn(Entity peep, CrewModState state, PlayerInfo player, SimTime now)
	{
		if (peep?.data?.person == null || state == null)
		{
			return;
		}

		RelationshipList relationships = G.GetRels()?.GetListOrNull(peep.Id);
		bool hasSpouse = relationships != null && relationships.HasSpouse();
		if (hasSpouse && state.LookingForSpouse)
		{
			ResetSpouseSearchState(state);
		}
		else if (!hasSpouse && state.LookingForSpouse)
		{
			ProcessSpouseSearchTurn(peep, state, player, now);
		}

		if (state.AwaitingChildBirth)
		{
			int count = peep.data.person.futurekids.Count;
			if (count < state.LastFutureKidsCount)
			{
				state.AwaitingChildBirth = false;
				VerificationLog("Family", $"birth-complete peep={peep.Id.id} previousFutureKids={state.LastFutureKidsCount} currentFutureKids={count}");
			}
			state.LastFutureKidsCount = count;
		}
	}

	internal static int CalculateRecurringOddJobActionCost(Entity peep)
	{
		int actionsRemaining = peep?.components?.agent?.ActionsRemaining ?? 0;
		return actionsRemaining <= 0 ? 0 : Mathf.Max(1, (actionsRemaining + 1) / 2);
	}

	internal static int CalculateRecurringOddJobPay(Entity peep, CrewModState state, bool isBoss)
	{
		if (isBoss)
		{
			return (ODD_JOB_REGULAR_MIN_PAY + ODD_JOB_REGULAR_MAX_PAY);
		}
		int streetLevel = Mathf.Clamp(state?.StreetCreditLevel ?? 0, 0, 4);
		int pay = ODD_JOB_REGULAR_MIN_PAY + streetLevel * 5;
		if (state != null && state.IsUnderboss)
		{
			return Mathf.Clamp(Mathf.RoundToInt(pay * 1.5f), Mathf.RoundToInt(ODD_JOB_REGULAR_MIN_PAY * 1.5f), Mathf.RoundToInt(ODD_JOB_REGULAR_MAX_PAY * 1.5f));
		}
		return Mathf.Clamp(pay, ODD_JOB_REGULAR_MIN_PAY, ODD_JOB_REGULAR_MAX_PAY);
	}

	internal static string GetRecurringOddJobPayRangeText(bool isBoss, bool isUnderboss)
	{
		if (isBoss)
		{
			return $"${ODD_JOB_REGULAR_MIN_PAY * 2}-${ODD_JOB_REGULAR_MAX_PAY * 2}";
		}
		if (isUnderboss)
		{
			return $"${Mathf.RoundToInt(ODD_JOB_REGULAR_MIN_PAY * 1.5f)}-${Mathf.RoundToInt(ODD_JOB_REGULAR_MAX_PAY * 1.5f)}";
		}
		return $"${ODD_JOB_REGULAR_MIN_PAY}-${ODD_JOB_REGULAR_MAX_PAY}";
	}

	private static int RollRecurringOddJobPay(CrewModState state, bool isBoss)
	{
		int basePay = SharedRng.Next(ODD_JOB_REGULAR_MIN_PAY / 5, ODD_JOB_REGULAR_MAX_PAY / 5 + 1) * 5;
		if (isBoss)
		{
			return basePay * 2;
		}
		if (state != null && state.IsUnderboss)
		{
			return Mathf.RoundToInt(basePay * 1.5f);
		}
		return basePay;
	}

	internal static int GetRecurringOddJobDaysUntilAvailable(CrewModState state, SimTime now)
	{
		if (state == null || state.LastOddJobDay < 0)
		{
			return 0;
		}
		NormalizeOddJobCooldownState(state, now, "availability", EntityID.INVALID);
		int elapsed = now.days - state.LastOddJobDay;
		return Mathf.Max(0, ODD_JOB_COOLDOWN_DAYS - elapsed);
	}

	internal static bool NormalizeOddJobCooldownState(CrewModState state, SimTime now, string source, EntityID peepId)
	{
		if (state == null || state.LastOddJobDay < 0 || state.LastOddJobDay <= now.days)
		{
			return false;
		}

		int oldLastDay = state.LastOddJobDay;
		state.LastOddJobDay = now.days - ODD_JOB_COOLDOWN_DAYS;
		VerificationLog(
			"OddJob",
			$"cooldown-clamped peep={(peepId.IsValid ? peepId.id.ToString() : "-1")} oldLastDay={oldLastDay} nowDay={now.days} newLastDay={state.LastOddJobDay} source={source}");
		return true;
	}

	private static Entity ResolveRecurringOddJobPayContainer(PlayerInfo player, Entity peep)
	{
		if (player == null)
		{
			return null;
		}
		try
		{
			CrewAssignment crew = player.crew?.GetCrewForPeep(peep.Id) ?? CrewAssignment.EMPTY;
			if (crew.IsValid && crew.IsInVehicle && crew.VehicleID.IsValid)
			{
				Entity vehicle = crew.GetVehicle();
				if (vehicle != null)
				{
					return vehicle;
				}
			}
		}
		catch
		{
		}
		try
		{
			return player.territory.Safehouse.FindEntity();
		}
		catch
		{
			return null;
		}
	}

	internal static bool TryProcessRecurringOddJob(Entity peep, CrewModState state, PlayerInfo player, SimTime now, string source)
	{
		if (peep?.data?.person == null || state == null || player == null || !(EnableCrewOddJobs?.Value ?? true) || !state.OddJobsEnabled)
		{
			return false;
		}
		if (!player.PID.IsHumanPlayer)
		{
			return false;
		}
		if (!peep.data.person.IsAlive || IsCrewCurrentlyJailed(peep.Id) || state.OnVacation || state.VacationPending || state.OnHideout || state.HideoutPending)
		{
			return false;
		}
		if (GetRecurringOddJobDaysUntilAvailable(state, now) > 0)
		{
			return false;
		}
		int actionCost = CalculateRecurringOddJobActionCost(peep);
		if (actionCost <= 0)
		{
			VerificationLog("OddJob", $"skipped peep={peep.Id.id} reason=no-actions source={source}");
			return false;
		}
		CrewCost cost = CrewCost.OnlyActions(actionCost);
		if (peep.components?.agent == null || !peep.components.agent.CanPay(cost))
		{
			VerificationLog("OddJob", $"skipped peep={peep.Id.id} reason=cannot-pay actions={actionCost} source={source}");
			return false;
		}
		bool isBoss = IsHumanBoss(peep, player);
		int pay = RollRecurringOddJobPay(state, isBoss);
		Entity container = ResolveRecurringOddJobPayContainer(player, peep);
		if (container == null)
		{
			VerificationLog("OddJob", $"skipped peep={peep.Id.id} reason=no-container pay={pay} actions={actionCost} source={source}");
			return false;
		}
		try
		{
			peep.components.agent.DoPay(cost, "weekly-odd-job");
			player.finances.DoChangeMoney(container, new Price((Fixnum)pay), MoneyReason.Other, new EntityID?(peep.Id));
			state.LastOddJobDay = now.days;
			state.TotalOddJobEarnings += pay;
			string name = peep.data.person.ShortName ?? "Crew";
			LogGrapevine($"CREW: {name} worked an odd job and brought in ${pay}.");
			VerificationLog("OddJob", $"paid peep={peep.Id.id} boss={isBoss} underboss={state.IsUnderboss} pay={pay} actions={actionCost} total={state.TotalOddJobEarnings} container={container.Id.id} source={source}");
			return true;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryProcessRecurringOddJob failed: " + ex.Message);
			VerificationLog("OddJob", $"failed peep={peep.Id.id} pay={pay} actions={actionCost} error={ex.GetType().Name} source={source}");
			return false;
		}
	}

	internal static bool TryStartSpouseSearch(Entity peep, CrewModState state)
	{
		if (peep?.data?.person == null || state == null)
		{
			return false;
		}

		RelationshipList relationships = G.GetRels()?.GetListOrNull(peep.Id);
		if ((relationships != null && relationships.HasSpouse()) || state.LookingForSpouse)
		{
			return false;
		}

		SimTime now = G.GetNow();
		state.LookingForSpouse = true;
		state.SpouseSearchStartDay = now.days;
		state.NextSpouseSearchDay = now.days + SPOUSE_SEARCH_INTERVAL_DAYS;
		state.SpouseSearchResolveNotBeforeDay = now.days + RollSpouseSearchResolveDelayDays();
		state.LastSpouseDatingSpend = 0;
		state.SpouseSearchTotalSpend = 0;
		LogGrapevine($"CREW: {peep.data.person.FullName} started looking for a spouse.");
		VerificationLog("Family", $"spouse-search-start peep={peep.Id.id} day={now.days} resolveNotBefore={state.SpouseSearchResolveNotBeforeDay}");
		return true;
	}

	private static void ProcessSpouseSearchTurn(Entity peep, CrewModState state, PlayerInfo player, SimTime now)
	{
		if (peep?.data?.person == null || state == null || !state.LookingForSpouse)
		{
			return;
		}

		int nextCheckDay = state.NextSpouseSearchDay >= 0
			? state.NextSpouseSearchDay
			: now.days + SPOUSE_SEARCH_INTERVAL_DAYS;
		if (now.days < nextCheckDay)
		{
			return;
		}

		int spendTarget = RollSpouseDateSpend();
		int actualSpend = 0;
		if (player != null && player.PID.IsHumanPlayer && spendTarget > 0)
		{
			int availableCash = GetPlayerCleanCash() + (ShouldDeferDirtyCashRuntime() ? 0 : GetTotalDirtyCash());
			actualSpend = Math.Min(spendTarget, Math.Max(0, availableCash));
			if (actualSpend > 0 && !TrySpendCombinedCash(player, actualSpend, out _, out _))
			{
				actualSpend = 0;
			}
		}
		state.LastSpouseDatingSpend = actualSpend;
		state.SpouseSearchTotalSpend += actualSpend;
		state.NextSpouseSearchDay = now.days + SPOUSE_SEARCH_INTERVAL_DAYS;

		PeopleTracker peopleGen = G.GetPeopleGen();
		Entity candidate = peopleGen?.FindRandoToMarry(peep);
		if (candidate != null && IsForbiddenSpouseCandidate(peep, candidate, G.GetRels(), out string rejectionReason))
		{
			VerificationLog("Family", $"spouse-search-candidate-rejected peep={peep.Id.id} candidate={candidate.Id.id} reason={rejectionReason}");
			candidate = null;
		}
		int searchStartDay = state.SpouseSearchStartDay >= 0 ? state.SpouseSearchStartDay : now.days;
		int weeksSearching = Math.Max(1, ((now.days - searchStartDay) / SPOUSE_SEARCH_INTERVAL_DAYS) + 1);
		bool readyToResolve = state.SpouseSearchResolveNotBeforeDay >= 0 && now.days >= state.SpouseSearchResolveNotBeforeDay;
		float successChance = readyToResolve
			? Mathf.Clamp(0.18f + weeksSearching * 0.015f, 0.18f, 0.72f)
			: 0f;

		if (candidate != null && readyToResolve && SharedRng.NextDouble() < successChance)
		{
			int totalDatingSpend = state.SpouseSearchTotalSpend;
			peopleGen.ForceMarry(peep, candidate);
			ResetSpouseSearchState(state);
			LogGrapevine($"CREW: {peep.data.person.FullName} found a spouse and is now going steady.");
			if (player != null && player.PID.IsHumanPlayer)
			{
				CrewRelationshipHandlerPatch.ShowSpouseFoundAlert(peep, totalDatingSpend);
			}
			VerificationLog("Family", $"spouse-search-success peep={peep.Id.id} spouse={candidate.Id.id} weeks={weeksSearching} spend={totalDatingSpend} day={now.days} chance={successChance:0.000}");
			return;
		}

		VerificationLog("Family", $"spouse-search-weekly peep={peep.Id.id} day={now.days} spend={actualSpend} totalSpend={state.SpouseSearchTotalSpend} ready={readyToResolve} candidate={(candidate?.Id.id ?? 0UL)} chance={successChance:0.000} nextCheck={state.NextSpouseSearchDay}");
	}

	private static void ResetSpouseSearchState(CrewModState state)
	{
		if (state == null)
		{
			return;
		}

		state.LookingForSpouse = false;
		state.SpouseSearchStartDay = -1;
		state.NextSpouseSearchDay = -1;
		state.SpouseSearchResolveNotBeforeDay = -1;
		state.LastSpouseDatingSpend = 0;
		state.SpouseSearchTotalSpend = 0;
	}

	private static int RollSpouseSearchResolveDelayDays()
	{
		double roll = SharedRng.NextDouble();
		if (roll < 0.55)
		{
			return SharedRng.Next(84, 177);
		}
		if (roll < 0.9)
		{
			return SharedRng.Next(177, 421);
		}
		return SharedRng.Next(421, 731);
	}

	private static int RollSpouseDateSpend()
	{
		return SharedRng.Next(5, SPOUSE_DATE_SPEND_MAX + 1);
	}

	internal static int RollPregnancyDurationDays()
	{
		return SharedRng.Next(PREGNANCY_MIN_DAYS, PREGNANCY_MAX_DAYS + 1);
	}

	private static float ComputeHideoutReturnDetectionChance(CrewModState state)
	{
		int num = (state != null) ? Mathf.Max(0, state.HideoutMissedPayments) : 0;
		return Mathf.Clamp(HIDEOUT_NOTICE_BASE_CHANCE + (float)num * HIDEOUT_NOTICE_MISS_STEP, 0f, HIDEOUT_NOTICE_MAX_CHANCE);
	}

	private static void ProcessHideoutUpkeep(Entity peep, CrewModState state, PlayerInfo player, SimTime now)
	{
		if (peep == null || state == null || player == null || !state.OnHideout)
		{
			return;
		}
		if (state.HideoutLastUpkeepDay < 0)
		{
			state.HideoutLastUpkeepDay = now.days;
			return;
		}
		if (now.days - state.HideoutLastUpkeepDay < HIDEOUT_UPKEEP_INTERVAL_DAYS)
		{
			return;
		}
		int cleanSpent;
		int dirtySpent;
		bool flag = TrySpendCombinedCash(player, HIDEOUT_UPKEEP_COST, out cleanSpent, out dirtySpent);
		state.HideoutLastUpkeepDay = now.days;
		if (flag)
		{
			state.HideoutForcedReturn = false;
			VerificationLog("Hideout", $"upkeep charged peep={peep.Id.id} clean={cleanSpent} dirty={dirtySpent} total={cleanSpent + dirtySpent} misses={state.HideoutMissedPayments}");
			return;
		}
		state.HideoutMissedPayments = Mathf.Max(0, state.HideoutMissedPayments + 1);
		state.HideoutForcedReturn = true;
		if (state.HideoutReturns.days > now.days + 1 || state.HideoutReturns.days <= now.days)
		{
			state.HideoutReturns = now.IncrementDays(1);
		}
		VerificationLog("Hideout", $"upkeep failed forcedReturn peep={peep.Id.id} misses={state.HideoutMissedPayments} nextReturnDay={state.HideoutReturns.days}");
	}

	internal static bool QualifiesForFullLoyaltyCap(Entity peep)
	{
		if (peep == null)
		{
			return false;
		}
		if (HasTrait(peep, "trait-immoral") || HasTrait(peep, "trait-cruel") || HasTrait(peep, "trait-vindictive"))
		{
			return false;
		}
		return CountPositiveLoyaltyTraits(peep) >= 3;
	}

	internal static void EnsureLoyaltyInitialized(Entity peep, CrewModState state, PlayerInfo humanPlayer)
	{
		if (state == null)
		{
			return;
		}
		bool flag = IsHumanBoss(peep, humanPlayer);
		if (flag)
		{
			state.LoyaltyCap = 1f;
			state.LoyaltyValue = 1f;
			state.LoyaltyCapInitialized = true;
			state.SnitchWeight = 0f;
			state.SnitchWeightInitialized = true;
			return;
		}
		float num = ComputeTraitWeightedLoyaltyCap(peep, humanPlayer);
		bool flag2 = QualifiesForFullLoyaltyCap(peep);
		if (flag2)
		{
			num = 1f;
		}
		if (!state.LoyaltyCapInitialized)
		{
			if (state.LoyaltyValue <= 0f)
			{
				state.LoyaltyCap = num;
				state.LoyaltyValue = state.LoyaltyCap;
			}
			else
			{
				state.LoyaltyCap = Mathf.Clamp(Mathf.Max(state.LoyaltyValue, num), 0.1f, 1f);
				state.LoyaltyValue = Mathf.Clamp(state.LoyaltyValue, 0f, state.LoyaltyCap);
			}
			state.LoyaltyCapInitialized = true;
			EnsureVerifyStats().LoyaltyCapInitCount++;
			VerificationLog("Loyalty", $"Cap initialized peep={peep?.Id.id} cap={state.LoyaltyCap:0.000} loyalty={state.LoyaltyValue:0.000}");
			if (flag2)
			{
				VerificationLog("Loyalty", $"Full cap qualified peep={peep?.Id.id} positives={CountPositiveLoyaltyTraits(peep)}");
			}
		}
		else
		{
			float loyaltyCap = state.LoyaltyCap;
			state.LoyaltyCap = Mathf.Clamp(state.LoyaltyCap, 0.1f, 1f);
			if (flag2 && state.LoyaltyCap < 1f)
			{
				state.LoyaltyCap = 1f;
			}
			state.LoyaltyValue = Mathf.Clamp(state.LoyaltyValue, 0f, state.LoyaltyCap);
			if (flag2 && loyaltyCap < 0.999f && state.LoyaltyCap >= 0.999f)
			{
				VerificationLog("Loyalty", $"Full cap qualified peep={peep?.Id.id} positives={CountPositiveLoyaltyTraits(peep)}");
			}
		}
		if (!state.SnitchWeightInitialized)
		{
			state.SnitchWeight = ComputeTraitSnitchWeight(peep);
			state.SnitchWeightInitialized = true;
		}
	}

	internal static bool TryRecoverLoyaltyTowardCap(Entity peep, CrewModState state, PlayerInfo humanPlayer, string source, float minimumGain, float missingFraction)
	{
		if (state == null)
		{
			return false;
		}
		EnsureLoyaltyInitialized(peep, state, humanPlayer);
		float loyaltyCap = Mathf.Clamp(state.LoyaltyCap, 0f, 1f);
		float before = Mathf.Clamp(state.LoyaltyValue, 0f, loyaltyCap);
		float missing = Mathf.Max(0f, loyaltyCap - before);
		if (missing <= 0.0001f)
		{
			return false;
		}
		float gain = Mathf.Max(minimumGain, missingFraction * missing);
		float after = Mathf.Clamp(before + gain, 0f, loyaltyCap);
		if (after <= before + 0.0001f)
		{
			return false;
		}
		state.LoyaltyValue = after;
		VerificationStats verifyStats = EnsureVerifyStats();
		switch (source)
		{
		case "gift":
			verifyStats.GiftLoyaltyGainEvents++;
			break;
		case "peptalk":
			verifyStats.PepTalkLoyaltyGainEvents++;
			break;
		case "vacation":
			verifyStats.VacationLoyaltyGainEvents++;
			break;
		}
		VerificationLog("Loyalty", $"recovery source={source} peep={peep?.Id.id} before={before:0.000} after={after:0.000} cap={loyaltyCap:0.000}");
		return true;
	}

	private static void ResetLoyaltyTurnSummary()
	{
		_loyaltyTurnSummaryDay = int.MinValue;
		_loyaltyTurnSummaryTotal = 0;
		_loyaltyTurnSummaryHighHappiness = 0;
		_loyaltyTurnSummaryHold = 0;
		_loyaltyTurnSummaryDecay = 0;
		_loyaltyTurnSummaryNearDefection = 0;
		_loyaltyTurnSummaryZeroReady = 0;
		_loyaltyTurnSummaryMinHappiness = 1f;
		_loyaltyTurnSummaryMinLoyalty = 1f;
		_loyaltyTurnSummaryMaxDecay = 0f;
		_loyaltyTurnSummaryMaxDecayPeepId = -1L;
		_loyaltyTurnSummaryLowestPeepId = -1L;
		_loyaltyTurnSummaryLowestOwnerId = -1;
		_loyaltyTurnSummaryLowestOwnerHuman = false;
	}

	private static void FlushLoyaltyTurnSummary(string source)
	{
		if (_loyaltyTurnSummaryDay != int.MinValue && _loyaltyTurnSummaryTotal > 0)
		{
				VerificationLog(
				"Loyalty",
				$"turn-summary day={_loyaltyTurnSummaryDay} total={_loyaltyTurnSummaryTotal} high={_loyaltyTurnSummaryHighHappiness} hold={_loyaltyTurnSummaryHold} decay={_loyaltyTurnSummaryDecay} nearDefection={_loyaltyTurnSummaryNearDefection} zeroReady={_loyaltyTurnSummaryZeroReady} minHappiness={_loyaltyTurnSummaryMinHappiness:0.000} minLoyalty={_loyaltyTurnSummaryMinLoyalty:0.000} lowestPeep={_loyaltyTurnSummaryLowestPeepId} lowestOwner={_loyaltyTurnSummaryLowestOwnerId} lowestOwnerHuman={_loyaltyTurnSummaryLowestOwnerHuman} maxDecay={_loyaltyTurnSummaryMaxDecay:0.000} maxDecayPeep={_loyaltyTurnSummaryMaxDecayPeepId} source={source}");
		}
		ResetLoyaltyTurnSummary();
	}

	private static void RecordLoyaltyTurnSummary(Entity peep, SimTime now, PlayerInfo owner, float happiness, float loyalty, string result, float decay, int streak)
	{
		int day = now.days;
		if (_loyaltyTurnSummaryDay != int.MinValue && _loyaltyTurnSummaryDay != day)
		{
			FlushLoyaltyTurnSummary("day-change");
		}
		if (_loyaltyTurnSummaryDay == int.MinValue)
		{
			_loyaltyTurnSummaryDay = day;
		}

		_loyaltyTurnSummaryTotal++;
		if (string.Equals(result, "high-happiness-no-decay", StringComparison.Ordinal))
		{
			_loyaltyTurnSummaryHighHappiness++;
		}
		else if (string.Equals(result, "decay", StringComparison.Ordinal))
		{
			_loyaltyTurnSummaryDecay++;
		}
		else
		{
			_loyaltyTurnSummaryHold++;
		}
		if (loyalty <= 0.15f)
		{
			_loyaltyTurnSummaryNearDefection++;
		}
		if (loyalty <= 0f)
		{
			_loyaltyTurnSummaryZeroReady++;
		}

		if (happiness < _loyaltyTurnSummaryMinHappiness || loyalty < _loyaltyTurnSummaryMinLoyalty)
		{
			_loyaltyTurnSummaryMinHappiness = Mathf.Min(_loyaltyTurnSummaryMinHappiness, happiness);
			_loyaltyTurnSummaryMinLoyalty = Mathf.Min(_loyaltyTurnSummaryMinLoyalty, loyalty);
			_loyaltyTurnSummaryLowestPeepId = peep != null && !peep.Id.IsNotValid ? unchecked((long)peep.Id.id) : -1L;
			_loyaltyTurnSummaryLowestOwnerId = owner?.PID.id ?? -1;
			_loyaltyTurnSummaryLowestOwnerHuman = owner?.PID.IsHumanPlayer == true;
		}
		if (decay > _loyaltyTurnSummaryMaxDecay)
		{
			_loyaltyTurnSummaryMaxDecay = decay;
			_loyaltyTurnSummaryMaxDecayPeepId = peep != null && !peep.Id.IsNotValid ? unchecked((long)peep.Id.id) : -1L;
		}
	}

	internal static void ApplyLoyaltyTurnUpdate(Entity peep, CrewModState state, PlayerInfo humanPlayer, SimTime now)
	{
		if (state == null)
		{
			return;
		}
		EnsureLoyaltyInitialized(peep, state, humanPlayer);
		if (IsHumanBoss(peep, humanPlayer))
		{
			VerificationStats verificationStats = EnsureVerifyStats();
			verificationStats.BossLoyaltyChecks++;
			if (state.LoyaltyValue < 0.999f || state.LoyaltyCap < 0.999f)
			{
				verificationStats.BossLoyaltyViolations++;
			}
			state.LoyaltyValue = 1f;
			state.LoyaltyCap = 1f;
			state.LowHappinessStreak = 0;
			return;
		}
		float num = state.LoyaltyValue;
		float happiness = Mathf.Clamp01(state.HappinessValue);
		float happyThreshold = ModConstants.MOOD_THRESHOLDS[0];
		string result = "hold";
		float num2 = 0f;
		if (happiness >= happyThreshold)
		{
			state.LowHappinessStreak = 0;
			result = "high-happiness-no-decay";
		}
		else if (happiness < 0.35f)
		{
			state.LowHappinessStreak++;
			result = "decay";
			num2 += 0.004f;
			if (happiness <= 0.25f)
			{
				num2 += 0.01f;
			}
			if (state.LowHappinessStreak >= 6)
			{
				num2 += 0.012f;
			}
		}
		else
		{
			state.LowHappinessStreak = Math.Max(0, state.LowHappinessStreak - 1);
		}
		state.LoyaltyValue = Mathf.Clamp(state.LoyaltyValue - num2, 0f, state.LoyaltyCap);
		if (Mathf.Abs(state.LoyaltyValue - num) >= 0.001f && num2 > 0f)
		{
			EnsureVerifyStats().LoyaltyDecayEvents++;
		}
		CrewRelationshipHandlerPatch.TryQueueLowHappinessPrompt(peep, state, humanPlayer, now);
		RecordLoyaltyTurnSummary(peep, now, humanPlayer, happiness, state.LoyaltyValue, result, num2, state.LowHappinessStreak);
	}

	private static Entity GetHumanBossPeep(PlayerInfo humanPlayer)
	{
		if (humanPlayer?.crew == null)
		{
			return null;
		}
		try
		{
			CrewAssignment crewForIndex = humanPlayer.crew.GetCrewForIndex(0);
			if (!crewForIndex.IsValid)
			{
				return null;
			}
			return crewForIndex.GetPeep();
		}
		catch
		{
			return null;
		}
	}

