	internal static void RunAIGangSnitchMeeting(PlayerInfo gang, SimTime now)
	{
		if (gang == null || gang.crew == null || gang.crew.IsCrewDefeated || gang.crew.LivingCrewCount <= 0)
		{
			return;
		}
		List<Entity> exposed = TryRevealSnitchesFromGangMeetingForGang(gang, logGrapevine: false);
		if (exposed == null || exposed.Count == 0)
		{
			return;
		}
		foreach (Entity peep in exposed)
		{
			if (peep == null)
			{
				continue;
			}
			CrewModState state = GetOrCreateCrewState(peep.Id);
			if (state == null)
			{
				continue;
			}
			TryExecuteSnitchDisappear(gang, peep, state, now, logGrapevine: false);
		}
	}

	/// <summary>Core threaten-witness logic for any gang (no UI). Returns true if attempt was made.</summary>
	internal static bool TryThreatenWitnessForPeep(PlayerInfo gang, Entity peep, CrewModState state, SimTime now)
	{
		if (gang == null || peep == null || state == null)
		{
			return false;
		}
		EnsureMurderWitnessRecordsForScalar(peep.Id, state, "ai-threat-check");
		int murderWitnesses = GetNonFederalMurderWitnessCount(state);
		int activeMurderRecords = CountActiveMurderWitnessRecords(state);
		if (activeMurderRecords > 0)
		{
			VerificationLog("MurderWitness", $"ai-murder-witness-action-deferred gang={gang.PID.id} peep={peep.Id.id} murderWitnesses={murderWitnesses} activeRecords={activeMurderRecords} reason=phase6-human-flow-only");
			return false;
		}
		if (GetThreatenableWitnessCount(state) <= 0)
		{
			return false;
		}
		float successChance = 0.5f;
		if (SharedRng.NextDouble() < (double)successChance)
		{
			state.WitnessCount--;
			state.WitnessThreatenedSuccessfully = true;
			if (state.WitnessCount <= state.FederalWitnessCount)
			{
				state.WitnessCount = Mathf.Max(0, state.FederalWitnessCount);
				state.HasWitness = state.FederalWitnessCount > 0;
			}
			if (state.WitnessCount <= 0 && state.FederalWitnessCount <= 0)
			{
				state.FedsIncoming = false;
				state.FedArrivalCountdown = 0;
			}
			Debug.Log($"[GameplayTweaks] AI threaten witness success gang={gang.PID.id} peep={peep.Id.id} witnessesLeft={state.WitnessCount}");
		}
		else
		{
			state.ExtraJailYears += SharedRng.Next(1, 4);
			SetLocalHeatProgress(state, Mathf.Clamp01(state.LocalHeatProgress + 0.15f), now.days, refreshDecayAnchor: true);
			Debug.Log($"[GameplayTweaks] AI threaten witness failed gang={gang.PID.id} peep={peep.Id.id} extraYears={state.ExtraJailYears}");
		}
		return true;
	}

	/// <summary>Spend judge bribe cost from gang and set JudgeBribeActive for the given state. Returns true if paid.</summary>
	internal static bool TryBribeJudgeForBoss(PlayerInfo gang, CrewModState bossState)
	{
		if (gang == null || bossState == null || bossState.JudgeBribeActive)
		{
			return false;
		}
		int cost = GetBribeCost(bossState.LocalHeatLevel) * 2;
		if (cost <= 0)
		{
			return false;
		}
		int clean = GetGangCleanCash(gang);
		if (clean < cost)
		{
			return false;
		}
		try
		{
			gang.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(-cost)), (MoneyReason)1);
			bossState.JudgeBribeActive = true;
			Debug.Log($"[GameplayTweaks] AI judge bribe paid gang={gang.PID.id} cost={cost}");
			return true;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryBribeJudgeForBoss failed: " + ex.Message);
			return false;
		}
	}

	/// <summary>AI-only: pay 10k and set per-gang mayor bribe expiry. Returns true if paid.</summary>
	internal static bool TryBribeMayorForGang(PlayerInfo gang, SimTime now)
	{
		if (gang == null || gang.PID.IsHumanPlayer)
		{
			return false;
		}
		const int mayorBribeCost = 10000;
		if (GetAiGangMayorBribeActive(gang.PID.id, now))
		{
			return false;
		}
		int clean = GetGangCleanCash(gang);
		if (clean < mayorBribeCost)
		{
			return false;
		}
		try
		{
			gang.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(-mayorBribeCost)), (MoneyReason)1);
			if (SaveData.AiGangMayorBribeExpireDayByGang == null)
			{
				SaveData.AiGangMayorBribeExpireDayByGang = new Dictionary<int, int>();
			}
			SaveData.AiGangMayorBribeExpireDayByGang[gang.PID.id] = now.days + 180;
			Debug.Log($"[GameplayTweaks] AI mayor bribe paid gang={gang.PID.id} expires day={now.days + 180}");
			return true;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryBribeMayorForGang failed: " + ex.Message);
			return false;
		}
	}

	internal static Entity FindRaidTargetBuilding(PlayerInfo humanPlayer)
	{
		if (humanPlayer?.territory == null)
		{
			return null;
		}
		List<Entity> list = new List<Entity>();
		try
		{
			EntityID safehouse = humanPlayer.territory.Safehouse;
			FieldInfo fieldInfo = humanPlayer.territory.GetType().GetField("_buildings", BindingFlags.Instance | BindingFlags.NonPublic) ?? humanPlayer.territory.GetType().GetField("buildings", BindingFlags.Instance | BindingFlags.NonPublic);
			PropertyInfo propertyInfo = humanPlayer.territory.GetType().GetProperty("OwnedBuildings", BindingFlags.Instance | BindingFlags.Public) ?? humanPlayer.territory.GetType().GetProperty("Buildings", BindingFlags.Instance | BindingFlags.Public);
			object obj = fieldInfo?.GetValue(humanPlayer.territory) ?? propertyInfo?.GetValue(humanPlayer.territory);
			if (obj is IEnumerable<EntityID> enumerable)
			{
				foreach (EntityID item in enumerable)
				{
					if (item.IsNotValid || item == safehouse)
					{
						continue;
					}
					Entity val = EntityIDExtensions.FindEntity(item);
					if (val != null)
					{
						list.Add(val);
					}
				}
			}
			if (list.Count > 0)
			{
				return list[SharedRng.Next(list.Count)];
			}
			if (!safehouse.IsNotValid)
			{
				return EntityIDExtensions.FindEntity(safehouse);
			}
		}
		catch
		{
		}
		return null;
	}

	internal static Entity FindManagerOrFallbackArrestee(PlayerInfo humanPlayer, Entity raidBuilding)
	{
		if (humanPlayer == null)
		{
			return null;
		}
		try
		{
			if (raidBuilding != null)
			{
				var (ownerpid, manager) = ModulesUtil.GetManagerOrNull(raidBuilding);
				if (manager != null && IsCrewCurrentlyJailed(manager.Id))
				{
					VerificationLog("Compat", $"manager-blocked reason=jailed building={raidBuilding.Id.id} manager={manager.Id.id} source=raid");
				}
				else if (manager != null && ownerpid == humanPlayer.PID && IsEntityAtRaidLocation(humanPlayer, manager, raidBuilding))
				{
					return manager;
				}
			}
		}
		catch
		{
		}
		try
		{
			Entity boss = GetHumanBossPeep(humanPlayer);
			List<Entity> list = humanPlayer.crew.GetLiving()
				.Where(c => c.IsValid)
				.Select(c => c.GetPeep())
				.Where(p => p != null
					&& (boss == null || p.Id != boss.Id)
					&& humanPlayer.crew.IsOnBoard(p.Id)
					&& IsEntityAtRaidLocation(humanPlayer, p, raidBuilding))
				.ToList();
			if (list.Count > 0)
			{
				return list[SharedRng.Next(list.Count)];
			}
			VerificationLog("SnitchCase", $"raid fallback none-local target={(raidBuilding != null ? raidBuilding.Id.id.ToString() : "none")}");
		}
		catch
		{
		}
		return null;
	}

	private static bool IsEntityAtRaidLocation(PlayerInfo player, Entity peep, Entity raidBuilding)
	{
		if (player?.crew == null || peep == null || raidBuilding == null)
		{
			return false;
		}
		try
		{
			if (!TryGetEntityBoardNodeId(raidBuilding, out NodeID raidNode))
			{
				return false;
			}
			CrewAssignment crewForPeep = player.crew.GetCrewForPeep(peep.Id);
			if (crewForPeep.IsValid)
			{
				return PrecinctAdvisorRaidPatch.IsCrewAssignmentPhysicallyAtNode(player, crewForPeep, raidNode);
			}
			NodeID peepNode = peep.data?.agent?.nid ?? NodeID.INVALID;
			if (peepNode.IsNotValid && peep.components?.agent != null)
			{
				Node node = peep.components.agent.GetNode();
				peepNode = node?.id ?? NodeID.INVALID;
			}
			return peepNode.IsValid && peepNode == raidNode;
		}
		catch
		{
			return false;
		}
	}

	private static bool TryGetEntityBoardNodeId(Entity entity, out NodeID nodeId)
	{
		nodeId = NodeID.INVALID;
		if (entity?.components?.board == null)
		{
			return false;
		}
		try
		{
			object board = entity.components.board;
			if (board == null)
			{
				return false;
			}
			MethodInfo methodInfo = board.GetType().GetMethod("GetNodeID", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (methodInfo == null)
			{
				return false;
			}
			nodeId = (NodeID)methodInfo.Invoke(board, null);
			return nodeId.IsValid;
		}
		catch
		{
			nodeId = NodeID.INVALID;
			return false;
		}
	}

	internal static bool ApplyBossStreetCreditFromDisappear(PlayerInfo player, float gain = 0.1f)
	{
		if (player?.crew == null || gain <= 0f)
		{
			return false;
		}
		try
		{
			CrewAssignment crewForIndex = player.crew.GetCrewForIndex(0);
			if (!crewForIndex.IsValid)
			{
				return false;
			}
			Entity peep = crewForIndex.GetPeep();
			if (peep == null)
			{
				return false;
			}
			CrewModState orCreateCrewState = GetOrCreateCrewState(peep.Id);
			if (orCreateCrewState == null)
			{
				return false;
			}
			orCreateCrewState.StreetCreditProgress = Mathf.Max(0f, orCreateCrewState.StreetCreditProgress) + gain;
			ResolveStreetCreditProgressLevelUps(orCreateCrewState, player, peep.Id, "disappear");
			return true;
		}
		catch
		{
			return false;
		}
	}

	internal static bool TryExecuteSnitchDisappear(PlayerInfo player, Entity peep, CrewModState state, SimTime now, bool logGrapevine = true)
	{
		if (player == null || state == null || peep == null)
		{
			return false;
		}
		if (!state.SnitchDisappearPending)
		{
			return false;
		}
		if (state.SnitchDisappearDueDay > now.days)
		{
			return false;
		}
		bool supportRemoved = false;
		bool wasAlive = peep.data?.person != null && peep.data.person.IsAlive;
		bool killed = false;
		try
		{
			if (wasAlive)
			{
				MethodInfo method = ((object)player.crew).GetType().GetMethod("ProcessCrewMemberDeath", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				if (method != null)
				{
					method.Invoke(player.crew, new object[1] { peep });
					killed = true;
					VerificationLog("DeathAttribution", $"source=snitch peep={peep.Id.id}");
					RecordDeathSource(peep.Id, "snitch");
				}
			}
		}
		catch (Exception ex)
		{
			Debug.LogError("[GameplayTweaks] Snitch disappear death failed: " + ex.Message);
		}
		try
		{
			player.crew.RemoveSupportPayment(peep.Id);
			supportRemoved = true;
		}
		catch
		{
		}
		state.SnitchDisappearPending = false;
		state.SnitchDisappearDueDay = -1;
		state.SnitchExposed = false;
		bool bossCreditApplied = ApplyBossStreetCreditFromDisappear(player, 0.1f);
		string text = peep.data?.person?.FullName ?? ("Crew " + peep.Id.id);
		if (logGrapevine)
		{
			LogGrapevine("CREW: " + text + " disappeared without a trace.");
		}
		VerificationLog("SnitchDisappear", $"executed peep={peep.Id.id} killed={killed} supportRemoved={supportRemoved} bossCreditGain=0.10 bossCreditApplied={bossCreditApplied}");
		return killed;
	}

	internal static void TriggerSnitchFederalRaid(PlayerInfo humanPlayer, SimTime now)
	{
		if (humanPlayer == null)
		{
			return;
		}
		Entity raidTarget = FindRaidTargetBuilding(humanPlayer);
		Entity managerOrFallback = FindManagerOrFallbackArrestee(humanPlayer, raidTarget);
		Entity humanBossPeep = GetHumanBossPeep(humanPlayer);
		bool flag = false;
		bool flag2 = false;
		try
		{
			if (managerOrFallback != null && !managerOrFallback.Id.IsNotValid)
			{
				if (IsEntityAtRaidLocation(humanPlayer, managerOrFallback, raidTarget))
				{
					flag = JailSystem.ArrestCrew(humanPlayer, managerOrFallback);
				}
				else
				{
					VerificationLog("SnitchCase", $"raid-arrest-skip peep={managerOrFallback.Id.id} reason=not-local");
				}
			}
		}
		catch
		{
		}
		try
		{
			if (humanBossPeep != null && !humanBossPeep.Id.IsNotValid)
			{
				if (IsEntityAtRaidLocation(humanPlayer, humanBossPeep, raidTarget))
				{
					flag2 = JailSystem.ArrestCrew(humanPlayer, humanBossPeep);
				}
				else
				{
					VerificationLog("SnitchCase", $"raid-arrest-skip peep={humanBossPeep.Id.id} reason=not-local");
				}
			}
		}
		catch
		{
		}
		string text = raidTarget?.ToString() ?? ((raidTarget != null) ? ("building-" + raidTarget.Id.id) : "safehouse");
		string text2 = managerOrFallback?.data?.person?.FullName ?? "no manager";
		string text3 = humanBossPeep?.data?.person?.FullName ?? "boss";
		LogGrapevine("FEDS: Federal case hit 100%. " + text + " was raided.");
		VerificationLog("SnitchCase", $"Raid triggered target={text} manager={text2} managerArrested={flag} boss={text3} bossArrested={flag2}");
		EnsureVerifyStats().SnitchRaidTriggers++;
		SaveData.SnitchCaseProgress = 0f;
		SaveData.LastSnitchRaidDay = now.days;
		SaveData.NextSnitchCollectionDay = now.days + SNITCH_COLLECTION_TURNS;
	}

	internal static void ProcessSnitchCaseTurn(PlayerInfo humanPlayer, SimTime now)
	{
		if (humanPlayer?.crew == null || !EnableCrewStats.Value)
		{
			return;
		}
		if (SaveData.NextSnitchCollectionDay < 0)
		{
			SaveData.NextSnitchCollectionDay = now.days + SNITCH_COLLECTION_TURNS;
		}
		if (now.days < SaveData.NextSnitchCollectionDay)
		{
			return;
		}
		long totalStartTicks = System.Diagnostics.Stopwatch.GetTimestamp();
		EnsureVerifyStats().SnitchIntakeRuns++;
		long humanStartTicks = System.Diagnostics.Stopwatch.GetTimestamp();
		RunSnitchIntakeForGang(humanPlayer, now, affectGlobalCase: true);
		long humanMs = GetElapsedMillisecondsSince(humanStartTicks);
		QueueDeferredAiSnitchIntake(now);
		SaveData.NextSnitchCollectionDay = now.days + SNITCH_COLLECTION_TURNS;
		long totalMs = GetElapsedMillisecondsSince(totalStartTicks);
		if (totalMs >= 20L || humanMs >= 20L || _pendingAiSnitchIntakeGangIds.Count > 0)
		{
			int turn = Game.Game.ctx?.clock?.CurrentTurn ?? -1;
			Debug.Log($"[PERF][SnitchCaseTurn] ms={totalMs} humanMs={humanMs} queuedAiGangs={_pendingAiSnitchIntakeGangIds.Count} nextCollectionDay={SaveData.NextSnitchCollectionDay} day={now.days} turn={turn}");
		}
	}

	private static void QueueDeferredAiSnitchIntake(SimTime now)
	{
		_pendingAiSnitchIntakeGangIds.Clear();
		_pendingAiSnitchIntakeCursor = 0;
		_pendingAiSnitchIntakeInputDeferrals = 0;
		_pendingAiSnitchIntakeMouseDeferrals = 0;
		foreach (PlayerInfo gang in G.GetAllPlayers())
		{
			if (gang == null || gang.PID.IsHumanPlayer || !gang.IsJustGang || gang.crew == null || gang.crew.IsCrewDefeated)
			{
				continue;
			}
			_pendingAiSnitchIntakeGangIds.Add(gang.PID.id);
		}
		if (_pendingAiSnitchIntakeGangIds.Count == 0)
		{
			ClearDeferredAiSnitchIntake();
			return;
		}
		_pendingAiSnitchIntakeQueued = true;
		_pendingAiSnitchIntakeDay = now.days;
		_pendingAiSnitchIntakeEarliestFrame = Time.frameCount + AI_SNITCH_INTAKE_INITIAL_GRACE_FRAMES;
		_pendingAiSnitchIntakeStartedTicks = System.Diagnostics.Stopwatch.GetTimestamp();
		int turn = Game.Game.ctx?.clock?.CurrentTurn ?? -1;
		Debug.Log($"[PERF][AiSnitchIntakeDeferred] queued gangs={_pendingAiSnitchIntakeGangIds.Count} day={now.days} turn={turn} earliestFrame={_pendingAiSnitchIntakeEarliestFrame}");
		ScheduleDeferredAiSnitchIntakeBatch();
	}

	private static void ScheduleDeferredAiSnitchIntakeBatch()
	{
		if (!_pendingAiSnitchIntakeQueued)
		{
			return;
		}
		try
		{
			global::Game.TimerUtil.RunNextFrame(RunDeferredAiSnitchIntakeBatch);
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Deferred AI snitch intake scheduling failed: " + ex.Message);
			RunDeferredAiSnitchIntakeBatch();
		}
	}

	private static void RunDeferredAiSnitchIntakeBatch()
	{
		try
		{
			if (!_pendingAiSnitchIntakeQueued || _pendingAiSnitchIntakeGangIds.Count == 0)
			{
				ClearDeferredAiSnitchIntake();
				return;
			}
			if (global::Game.Game.ctx == null || !global::Game.Game.ctx.IsInteractive)
			{
				ClearDeferredAiSnitchIntake();
				return;
			}
			PlayerID currentPlayer = global::Game.Game.ctx.clock.CurrentPlayer;
			int frame = Time.frameCount;
			if (frame < _pendingAiSnitchIntakeEarliestFrame)
			{
				_pendingAiSnitchIntakeInputDeferrals++;
				ScheduleDeferredAiSnitchIntakeBatch();
				return;
			}
			if (Input.GetMouseButton(0) && _pendingAiSnitchIntakeMouseDeferrals < AI_SNITCH_INTAKE_MOUSE_DEFERRAL_LIMIT)
			{
				_pendingAiSnitchIntakeInputDeferrals++;
				_pendingAiSnitchIntakeMouseDeferrals++;
				ScheduleDeferredAiSnitchIntakeBatch();
				return;
			}
			SimTime now = G.GetNow();
			long startTicks = System.Diagnostics.Stopwatch.GetTimestamp();
			int processed = 0;
			while (_pendingAiSnitchIntakeCursor < _pendingAiSnitchIntakeGangIds.Count)
			{
				int gangId = _pendingAiSnitchIntakeGangIds[_pendingAiSnitchIntakeCursor++];
				PlayerInfo gang = G.FindPlayerById(gangId);
				if (gang != null && !gang.PID.IsHumanPlayer && gang.IsJustGang && gang.crew != null && !gang.crew.IsCrewDefeated)
				{
					RunSnitchIntakeForGang(gang, now, affectGlobalCase: false);
					processed++;
				}
				if (processed >= AI_SNITCH_INTAKE_GANGS_PER_FRAME || (processed > 0 && GetElapsedMillisecondsSince(startTicks) >= AI_SNITCH_INTAKE_BUDGET_MS))
				{
					break;
				}
			}
			long elapsedMs = GetElapsedMillisecondsSince(startTicks);
			int remaining = Math.Max(0, _pendingAiSnitchIntakeGangIds.Count - _pendingAiSnitchIntakeCursor);
			if (elapsedMs >= 10L || remaining == 0)
			{
				Debug.Log($"[PERF][AiSnitchIntakeDeferred] batch ms={elapsedMs} processedGangs={processed} remaining={remaining} cursor={_pendingAiSnitchIntakeCursor}/{_pendingAiSnitchIntakeGangIds.Count} scheduledDay={_pendingAiSnitchIntakeDay} currentDay={now.days} frame={frame}");
			}
			if (remaining > 0)
			{
				ScheduleDeferredAiSnitchIntakeBatch();
				return;
			}
			long wallMs = GetElapsedMillisecondsSince(_pendingAiSnitchIntakeStartedTicks);
			int scheduledDay = _pendingAiSnitchIntakeDay;
			int deferrals = _pendingAiSnitchIntakeInputDeferrals;
			int mouseDeferrals = _pendingAiSnitchIntakeMouseDeferrals;
			int currentPid = currentPlayer.IsValid ? currentPlayer.id : -1;
			bool currentHuman = currentPlayer.IsHumanPlayer;
			int total = _pendingAiSnitchIntakeGangIds.Count;
			ClearDeferredAiSnitchIntake();
			Debug.Log($"[PERF][AiSnitchIntakeDeferred] complete wallMs={wallMs} gangs={total} scheduledDay={scheduledDay} currentDay={now.days} currentPid={currentPid} currentHuman={currentHuman} deferrals={deferrals} mouseDeferrals={mouseDeferrals}");
		}
		catch (Exception ex)
		{
			ClearDeferredAiSnitchIntake();
			Debug.LogError("[GameplayTweaks] Deferred AI snitch intake failed: " + ex);
		}
	}

	private static void ClearDeferredAiSnitchIntake()
	{
		_pendingAiSnitchIntakeQueued = false;
		_pendingAiSnitchIntakeGangIds.Clear();
		_pendingAiSnitchIntakeDay = -1;
		_pendingAiSnitchIntakeCursor = 0;
		_pendingAiSnitchIntakeEarliestFrame = -1;
		_pendingAiSnitchIntakeStartedTicks = 0L;
		_pendingAiSnitchIntakeInputDeferrals = 0;
		_pendingAiSnitchIntakeMouseDeferrals = 0;
	}

	private static long GetElapsedMillisecondsSince(long startTicks)
	{
		return (System.Diagnostics.Stopwatch.GetTimestamp() - startTicks) * 1000L / System.Diagnostics.Stopwatch.Frequency;
	}

	internal static void RunSnitchIntakeForGang(PlayerInfo gang, SimTime now, bool affectGlobalCase)
	{
		if (gang?.crew == null || !EnableCrewStats.Value)
		{
			return;
		}
		EntityID bossPeepId = default(EntityID);
		try
		{
			CrewAssignment bossAssignment = gang.crew.GetCrewForIndex(0);
			if (bossAssignment.IsValid && !bossAssignment.peepId.IsNotValid)
			{
				bossPeepId = bossAssignment.peepId;
			}
		}
		catch
		{
		}
		int leaks = 0;
		int leakScore = 0;
		foreach (CrewAssignment item in gang.crew.GetLiving().ToList())
		{
			if (!item.IsValid)
			{
				continue;
			}
			Entity peep = item.GetPeep();
			if (peep == null)
			{
				continue;
			}
			if (!bossPeepId.IsNotValid && peep.Id == bossPeepId)
			{
				continue;
			}
			CrewModState orCreateCrewState = GetOrCreateCrewState(peep.Id);
			if (orCreateCrewState == null)
			{
				continue;
			}
			EnsureLoyaltyInitialized(peep, orCreateCrewState, gang);
			bool alreadyTurnedSnitch = orCreateCrewState.SnitchLeakCount > 0 || orCreateCrewState.SnitchExposed;
			if (!alreadyTurnedSnitch && orCreateCrewState.LoyaltyValue >= 0.1f)
			{
				if (gang.PID.IsHumanPlayer)
				{
					VerificationLog("SnitchCase", $"Turn blocked peep={peep.Id.id} loyalty={orCreateCrewState.LoyaltyValue:0.000} threshold=0.100");
				}
				continue;
			}
			float num = Mathf.Clamp(orCreateCrewState.SnitchWeight + Mathf.Max(0f, 0.4f - orCreateCrewState.HappinessValue) * 0.35f + Mathf.Max(0f, 0.4f - orCreateCrewState.LoyaltyValue) * 0.35f, 0f, 0.95f);
			float num2 = Mathf.Clamp(num * SNITCH_EFFECTIVE_CHANCE_SCALE, 0f, SNITCH_EFFECTIVE_CHANCE_MAX);
			if (SharedRng.NextDouble() <= (double)num2)
			{
				int num3 = SharedRng.Next(0, 21);
				leaks++;
				leakScore += num3;
				orCreateCrewState.SnitchLeakCount++;
				orCreateCrewState.LastSnitchLeakDay = now.days;
				EnsureVerifyStats().SnitchLeakEvents++;
				if (gang.PID.IsHumanPlayer)
				{
					VerificationLog("SnitchCase", $"Leak collected peep={peep.Id.id} rawChance={num:0.000} effectiveChance={num2:0.000} cap={SNITCH_EFFECTIVE_CHANCE_MAX:0.000} delta={num3}");
				}
			}
		}
		if (!affectGlobalCase || leakScore <= 0)
		{
			return;
		}
		SaveData.SnitchCaseProgress = Mathf.Clamp(SaveData.SnitchCaseProgress + leakScore, 0f, 100f);
		VerificationLog("SnitchCase", $"Intake processed day={now.days} leaks={leaks} added={leakScore} progress={SaveData.SnitchCaseProgress:0.0}");
		if (SaveData.SnitchCaseProgress >= 100f)
		{
			TriggerSnitchFederalRaid(gang, now);
		}
	}

	internal static List<Entity> TryRevealSnitchesFromGangMeetingForGang(PlayerInfo gang, bool logGrapevine)
	{
		List<Entity> list = new List<Entity>();
		if (gang?.crew == null)
		{
			return list;
		}
		Entity humanBossPeep = GetHumanBossPeep(gang);
		List<Entity> list2 = new List<Entity>();
		foreach (CrewAssignment item in gang.crew.GetLiving().ToList())
		{
			if (!item.IsValid)
			{
				continue;
			}
			Entity peep = item.GetPeep();
			if (peep == null || (humanBossPeep != null && peep.Id == humanBossPeep.Id))
			{
				continue;
			}
			list2.Add(peep);
		}
		float num = 0f;
		int num2 = 0;
		foreach (Entity item2 in list2)
		{
			CrewModState orCreateCrewState = GetOrCreateCrewState(item2.Id);
			if (orCreateCrewState == null)
			{
				continue;
			}
			EnsureLoyaltyInitialized(item2, orCreateCrewState, gang);
			num += Mathf.Clamp01(orCreateCrewState.LoyaltyValue);
			num2++;
		}
		float num3 = (num2 > 0) ? (num / (float)num2) : 0.5f;
		float num4 = Mathf.Clamp(0.08f + num3 * 0.52f, 0.08f, 0.6f);
		foreach (Entity item3 in list2)
		{
			CrewModState orCreateCrewState2 = GetOrCreateCrewState(item3.Id);
			if (orCreateCrewState2 == null || orCreateCrewState2.SnitchExposed || orCreateCrewState2.SnitchLeakCount <= 0)
			{
				continue;
			}
			if (SharedRng.NextDouble() > (double)num4)
			{
				continue;
			}
			orCreateCrewState2.SnitchExposed = true;
			list.Add(item3);
			if (logGrapevine)
			{
				string fullName = item3.data?.person?.FullName ?? $"Crew {item3.Id.id}";
				LogGrapevine("SNITCH: " + fullName + " was exposed during a gang meeting.");
			}
			VerificationLog("SnitchReveal", $"exposed peep={item3.Id.id} chance={num4:0.000} leaks={orCreateCrewState2.SnitchLeakCount}");
		}
		return list;
	}

	internal static List<Entity> TryRevealSnitchesFromGangMeeting(PlayerInfo humanPlayer)
	{
		return TryRevealSnitchesFromGangMeetingForGang(humanPlayer, logGrapevine: true);
	}

	internal static void ApplyRetainerUpkeep(Entity peep, CrewModState state, SimTime now)
	{
		if (peep == null || state == null || !state.LawyerRetainerConfirmed)
		{
			return;
		}
		if (!(state.InJail || JailSystem.IsInJail(peep.Id)))
		{
			return;
		}
		if (state.LastRetainerDeductDay == now.days)
		{
			return;
		}
		int num = ((state.LawyerRetainer >= 20000) ? 1000 : 500);
		if (num <= 0 || state.LawyerRetainer <= 0)
		{
			state.LastRetainerDeductDay = now.days;
			return;
		}
		int lawyerRetainer = state.LawyerRetainer;
		state.LawyerRetainer = Mathf.Max(0, state.LawyerRetainer - num);
		if (state.LawyerRetainer <= 0)
		{
			state.LawyerRetainerConfirmed = false;
		}
		state.LastRetainerDeductDay = now.days;
		EnsureVerifyStats().RetainerUpkeepTicks++;
		VerificationLog("Retainer", $"Upkeep peep={peep.Id.id} before={lawyerRetainer} after={state.LawyerRetainer} deduct={num}");
	}

	internal static void TryProcessRetainerTrialAssistPrefix(object record)
	{
		if (record == null)
		{
			return;
		}
		try
		{
			FieldInfo field = record.GetType().GetField("peepId", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			FieldInfo field2 = record.GetType().GetField("paidOff", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (field == null || field2 == null)
			{
				return;
			}
			object value = field.GetValue(record);
			if (!(value is EntityID peepId) || peepId.IsNotValid)
			{
				return;
			}
			CrewModState crewStateOrNull = GetCrewStateOrNull(peepId);
			if (crewStateOrNull == null || !crewStateOrNull.LawyerRetainerConfirmed || crewStateOrNull.LawyerRetainer <= 20000)
			{
				return;
			}
			bool flag = SharedRng.NextDouble() < 0.6;
			VerificationStats verificationStats = EnsureVerifyStats();
			verificationStats.RetainerTrialAssistRolls++;
			if (flag)
			{
				verificationStats.RetainerTrialAssistWins++;
			}
			VerificationLog("Retainer", $"Trial assist peep={peepId.id} retainer={crewStateOrNull.LawyerRetainer} confirmed={crewStateOrNull.LawyerRetainerConfirmed} win={flag}");
			if (flag)
			{
				field2.SetValue(record, true);
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Retainer trial assist failed: " + ex.Message);
		}
	}

	private static string GetFederalCaseUiLabel()
	{
		int num = (SaveData.NextSnitchCollectionDay < 0) ? -1 : Mathf.Max(0, SaveData.NextSnitchCollectionDay - G.GetNow().days);
		string text = (num < 0) ? "--" : (num + "d");
		return $"Federal Case: {Mathf.Clamp(SaveData.SnitchCaseProgress, 0f, 100f):0}% | Next Intake: {text}";
	}

	private static string GetStateCaseUiLabel(CrewModState state)
	{
		if (state == null || !state.MurderCaseActive)
		{
			return "State Case: None";
		}
		int ageDays = GetMurderCaseAgeDays(state, G.GetNow().days);
		int minDays = GetMurderCaseMinimumBuildDays(state);
		return $"State Case: {Mathf.Clamp(state.MurderCaseProgress, 0f, 100f):0}% | Trial Window: {ageDays}/{minDays}d";
	}

	internal static bool IsHumanBoss(Entity peep, PlayerInfo humanPlayer)
	{
		if (peep == null || humanPlayer == null || humanPlayer.crew == null)
		{
			return false;
		}
		try
		{
			CrewAssignment crewForIndex = humanPlayer.crew.GetCrewForIndex(0);
			return crewForIndex.IsValid && crewForIndex.peepId == peep.Id;
		}
		catch
		{
			return false;
		}
	}

	internal static bool IsHumanBossOrUnderboss(Entity peep, PlayerInfo humanPlayer)
	{
		if (IsHumanBoss(peep, humanPlayer))
		{
			return true;
		}

		if (peep == null || humanPlayer?.crew == null)
		{
			return false;
		}

		try
		{
			CrewAssignment crewForPeep = humanPlayer.crew.GetCrewForPeep(peep.Id);
			if (!crewForPeep.IsValid)
			{
				return false;
			}

			CrewModState crewStateOrNull = GetCrewStateOrNull(peep.Id);
			if (crewStateOrNull?.IsUnderboss == true)
			{
				return true;
			}

			string crewRoleName = peep.data?.agent?.xp?.crewRole.ToString();
			return !string.IsNullOrEmpty(crewRoleName) && crewRoleName.IndexOf("underboss", StringComparison.OrdinalIgnoreCase) >= 0;
		}
		catch
		{
			return false;
		}
	}

