	internal static bool IsCaptainCrewMember(Entity peep)
	{
		if (peep?.data?.agent == null)
		{
			return false;
		}
		try
		{
			XP xp = peep.data.agent.xp;
			if (xp != null && xp.crewRole != Label.NULL)
			{
				string text = xp.crewRole.ToString();
				if (!string.IsNullOrEmpty(text) && text.IndexOf("captain", StringComparison.OrdinalIgnoreCase) >= 0)
				{
					return true;
				}
			}
			TagList traitIds = peep.data.person?.traitIds;
			if (traitIds != null)
			{
				foreach (Label trait in traitIds)
				{
					string text2 = trait.ToString();
					if (!string.IsNullOrEmpty(text2) && text2.IndexOf("captain", StringComparison.OrdinalIgnoreCase) >= 0)
					{
						return true;
					}
				}
			}
		}
		catch
		{
		}
		return false;
	}

	internal static string GetGangDisplayName(int gangId)
	{
		PlayerInfo playerInfo = G.FindPlayerById(gangId);
		return playerInfo?.social?.PlayerGroupName ?? ("Gang#" + gangId);
	}

	internal static EntityID GetCrewPeepForPlayer(PlayerInfo player, Entity fallback = null)
	{
		if (fallback != null && IsUsableRelationshipBuffCrewPeep(fallback.Id))
		{
			return fallback.Id;
		}
		if (player?.social != null && IsUsableRelationshipBuffCrewPeep(player.social.PlayerPeepId))
		{
			return player.social.PlayerPeepId;
		}
		if (player?.crew != null)
		{
			try
			{
				CrewAssignment boss = player.crew.GetCrewForIndex(0);
				if (boss.IsValid && IsUsableRelationshipBuffCrewPeep(boss.peepId))
				{
					return boss.peepId;
				}
			}
			catch
			{
			}
			try
			{
				CrewAssignment crewAssignment = player.crew.AllCrew.FirstOrDefault((CrewAssignment item) => item.IsValid && item.peepId.IsValid && item.IsNotDead && IsUsableRelationshipBuffCrewPeep(item.peepId));
				if (crewAssignment.IsValid)
				{
					return crewAssignment.peepId;
				}
			}
			catch
			{
			}
		}
		return EntityID.INVALID;
	}

	internal static bool AddDirectedRelationshipBuff(PlayerInfo source, PlayerInfo target, string buffId, EntityID crewPeep = default(EntityID), bool logSuccess = true)
	{
		if (source == null || target == null || source.social == null || target.social == null || string.IsNullOrEmpty(buffId))
		{
			Debug.LogWarning("[GameplayTweaks][Buff] Skipped directed buff apply due to invalid args.");
			return false;
		}
		string sourceName = source.social?.PlayerGroupName ?? ("Gang#" + source.PID.id);
		string targetName = target.social?.PlayerGroupName ?? ("Gang#" + target.PID.id);
		try
		{
			Relationship relationshipFromPlayerTo;
			if (!TryGetRelationshipFromPlayerTo(source, target, createIfMissing: true, out relationshipFromPlayerTo) || relationshipFromPlayerTo == null)
			{
				Debug.LogWarning($"[GameplayTweaks][Buff] Missing relationship object: {sourceName} -> {targetName} | buff={buffId}");
				return false;
			}
			Label label = new Label(buffId);
			EntityID entityID = ResolveRelationshipBuffCrewPeep(source, target, crewPeep);
			bool flag = relationshipFromPlayerTo.AddBuff(label, entityID);
			bool flag2 = relationshipFromPlayerTo.HasBuff(label);
			if (!flag2)
			{
				EntityID crewPeepForPlayer = GetCrewPeepForPlayer(target);
				if (!crewPeepForPlayer.IsNotValid && crewPeepForPlayer != entityID)
				{
					relationshipFromPlayerTo.AddBuff(label, crewPeepForPlayer);
					flag2 = relationshipFromPlayerTo.HasBuff(label);
					entityID = crewPeepForPlayer;
				}
			}
			if (relationshipFromPlayerTo == null)
			{
				return false;
			}
			if (flag2 && ShouldPersistGangRelationshipBuff(buffId))
			{
				UpsertPersistentGangRelationshipBuffRecordFromLive(source, target, buffId, relationshipFromPlayerTo, entityID, enforceMinimumDuration: true);
			}
			if (logSuccess)
			{
				Debug.Log($"[GameplayTweaks][Buff] Applied: {sourceName} -> {targetName} | buff={buffId} | applied={flag2} | refreshed={flag} | peep={entityID.id}");
			}
			return flag2;
		}
		catch (Exception ex)
		{
			Debug.LogWarning($"[GameplayTweaks][Buff] Failed: {sourceName} -> {targetName} | buff={buffId} | {ex.Message}");
			return false;
		}
	}

	internal static void AddMutualRelationshipBuff(PlayerInfo a, PlayerInfo b, string buffId, EntityID aCrewPeep = default(EntityID), EntityID bCrewPeep = default(EntityID), bool logSuccess = true)
	{
		if (a == null || b == null || a.PID.id == b.PID.id || string.IsNullOrEmpty(buffId))
		{
			return;
		}
		AddDirectedRelationshipBuff(a, b, buffId, aCrewPeep, logSuccess);
		AddDirectedRelationshipBuff(b, a, buffId, bCrewPeep, logSuccess);
	}

	private static bool EnsureCustomRelationshipBuffDefinitions()
	{
		return EnsureRelationshipBuffDefinition("relbuff-pact-trade", "relbuff-pact-support-intro")
			&& EnsureWarStanceViolationRelationshipBuffDefinition();
	}

	private static bool EnsureWarStanceViolationRelationshipBuffDefinition()
	{
		const string buffId = "relbuff-war-stance-violated";
		if (!EnsureRelationshipBuffDefinition(buffId, "relbuff-gang-injury")
			|| !TryGetRelationshipBuffSettings(out BuffSettings settings))
		{
			return false;
		}
		BuffConfig config = FindRelationshipBuffDefinitionSafe(settings, new Label(buffId));
		if (config == null)
		{
			return false;
		}
		config.locdesc = "relbuff.goons.wrong-foot";
		config.delta = CloneModValueOrDefault(null, -10);
		config.dayz = CloneModValueOrDefault(null, 180);
		config.type = BuffDeferralType.Normal;
		ResetBuffSettingsCache(settings, buffId);
		return true;
	}

	private static bool TryGetRelationshipBuffSettings(out BuffSettings settings)
	{
		settings = null;
		try
		{
			settings = BuffStack.GetSettings();
			return settings?.definitions != null;
		}
		catch
		{
			return false;
		}
	}

	private static bool HasRelationshipBuffDefinition(string buffId)
	{
		if (string.IsNullOrWhiteSpace(buffId))
		{
			return false;
		}

		try
		{
			return TryGetRelationshipBuffSettings(out BuffSettings settings)
				&& FindRelationshipBuffDefinitionSafe(settings, new Label(buffId)) != null;
		}
		catch
		{
			return false;
		}
	}

	private static BuffConfig FindRelationshipBuffDefinitionSafe(BuffSettings settings, Label id)
	{
		if (settings?.definitions == null || !id.IsSet)
		{
			return null;
		}

		foreach (BuffConfig config in settings.definitions)
		{
			if (config != null && config.id == id)
			{
				return config;
			}
		}

		return null;
	}

	private static bool EnsureRelationshipBuffDefinition(string buffId, string templateBuffId)
	{
		if (string.IsNullOrWhiteSpace(buffId))
		{
			return false;
		}

		try
		{
			if (!TryGetRelationshipBuffSettings(out BuffSettings settings))
			{
				return false;
			}

			Label requestedId = new Label(buffId);
			if (FindRelationshipBuffDefinitionSafe(settings, requestedId) != null)
			{
				return true;
			}

			BuffConfig template = null;
			if (!string.IsNullOrWhiteSpace(templateBuffId))
			{
				template = FindRelationshipBuffDefinitionSafe(settings, new Label(templateBuffId));
			}

			if (template == null)
			{
				template = FindRelationshipBuffDefinitionSafe(settings, new Label("relbuff-gangs-leisure-buff"))
					?? FindRelationshipBuffDefinitionSafe(settings, new Label("relbuff-pact-support-cash"));
			}

			BuffConfig injected = CreateFallbackRelationshipBuffConfig(requestedId, template);
			settings.definitions.Add(injected);
			ResetBuffSettingsCache(settings, buffId);
			Debug.Log($"[GameplayTweaks][Buff] Injected fallback buff id={buffId} template={(template != null ? template.id.ToString() : "local-default")}");
			return true;
		}
		catch (Exception ex)
		{
			Debug.LogWarning($"[GameplayTweaks][Buff] Failed to inject custom buff id={buffId}: {ex.GetType().Name}: {ex.Message}");
			return false;
		}
	}

	private static BuffConfig CreateFallbackRelationshipBuffConfig(Label requestedId, BuffConfig template)
	{
		BuffConfig config = new BuffConfig
		{
			id = requestedId,
			locdesc = !string.IsNullOrWhiteSpace(template?.locdesc) ? template.locdesc : "relbuff.gangs.leisure-buff.on-finish",
			delta = CloneModValueOrDefault(template?.delta, 15),
			dayz = CloneModValueOrDefault(template?.dayz, 180),
			priority = template?.priority ?? 0,
			cancels = CopyLabelListSafe(template?.cancels),
			type = template?.type ?? BuffDeferralType.Normal
		};

		if (config.type != BuffDeferralType.Normal && config.delta == null)
		{
			config.delta = CloneModValueOrDefault(null, 15);
		}

		return config;
	}

	private static ModValue CloneModValueOrDefault(ModValue source, int defaultValue)
	{
		try
		{
			if (source != null)
			{
				return new ModValue
				{
					value = source.value,
					mods = source.mods
				};
			}
		}
		catch
		{
		}

		return new ModValue
		{
			value = (Fixnum)defaultValue
		};
	}

	private static List<Label> CopyLabelListSafe(List<Label> source)
	{
		if (source == null || source.Count == 0)
		{
			return null;
		}

		List<Label> copy = new List<Label>(source.Count);
		foreach (Label label in source)
		{
			if (label.IsSet)
			{
				copy.Add(label);
			}
		}

		return copy.Count > 0 ? copy : null;
	}

	private static void ResetBuffSettingsCache(BuffSettings settings, string buffId)
	{
		try
		{
			AccessTools.Field(typeof(BuffSettings), "_buffCache")?.SetValue(settings, null);
		}
		catch (Exception ex)
		{
			Debug.LogWarning($"[GameplayTweaks][Buff] Injected fallback buff id={buffId} but failed to reset cache: {ex.GetType().Name}: {ex.Message}");
		}
	}

	internal static bool RemoveDirectedRelationshipBuff(PlayerInfo source, PlayerInfo target, string buffId)
	{
		if (source == null || target == null || source.social == null || target.social == null || string.IsNullOrEmpty(buffId))
		{
			return false;
		}
		try
		{
			bool removed = RemoveDirectedRelationshipBuffLive(source, target, buffId);
			if (ShouldPersistGangRelationshipBuff(buffId))
			{
				RemovePersistentGangRelationshipBuffRecord(source.PID.id, target.PID.id, buffId);
			}
			return removed;
		}
		catch
		{
			return false;
		}
	}

	internal static void ReconcilePersistentGangRelationshipBuffs(string sourceTag, bool force = false)
	{
		int days;
		try
		{
			days = G.GetNow().days;
		}
		catch
		{
			days = -1;
		}
		if (!force && days >= 0 && _lastGangRelationshipBuffReconcileDay == days)
		{
			return;
		}
		try
		{
			EnsureSaveDataDefaults();
			if (SaveData?.GangRelationshipBuffs == null)
			{
				return;
			}
			if (!IsPersistentGangRelationshipBuffWorldReady(days))
			{
				if (SaveData.GangRelationshipBuffs.Count > 0)
				{
					Debug.Log($"[GameplayTweaks][Buff] Deferred persistent gang buff reconcile source={sourceTag} records={SaveData.GangRelationshipBuffs.Count} day={days} reason=world-not-ready");
				}
				return;
			}
			_lastGangRelationshipBuffReconcileDay = days;
			SnapshotPersistentGangRelationshipBuffsFromLiveRelations();
			DeduplicatePersistentGangRelationshipBuffLedger();
			if (SaveData.GangRelationshipBuffs.Count == 0)
			{
				return;
			}
			int num = 0;
			int num2 = 0;
			int num4 = 0;
			int num5 = 0;
			int num6 = 0;
			for (int num3 = SaveData.GangRelationshipBuffs.Count - 1; num3 >= 0; num3--)
			{
				GangRelationshipBuffState gangRelationshipBuffState = SaveData.GangRelationshipBuffs[num3];
				if (gangRelationshipBuffState == null || !ShouldPersistGangRelationshipBuff(gangRelationshipBuffState.BuffId) || gangRelationshipBuffState.SourcePid < 0 || gangRelationshipBuffState.TargetPid < 0 || gangRelationshipBuffState.SourcePid == gangRelationshipBuffState.TargetPid)
				{
					SaveData.GangRelationshipBuffs.RemoveAt(num3);
					num2++;
					num4++;
					continue;
				}
				PlayerInfo playerById = G.FindPlayerById(gangRelationshipBuffState.SourcePid);
				PlayerInfo playerById2 = G.FindPlayerById(gangRelationshipBuffState.TargetPid);
				if (playerById == null || playerById2 == null || playerById.social == null || playerById2.social == null)
				{
					num6++;
					continue;
				}
				if (IsPersistentGangRelationshipBuffExpired(gangRelationshipBuffState, days))
				{
					RemoveDirectedRelationshipBuffLive(playerById, playerById2, gangRelationshipBuffState.BuffId);
					SaveData.GangRelationshipBuffs.RemoveAt(num3);
					num2++;
					num5++;
					continue;
				}
				if (RestorePersistentGangRelationshipBuffState(playerById, playerById2, gangRelationshipBuffState))
				{
					num++;
				}
			}
			if (num > 0 || num2 > 0 || num6 > 0)
			{
				Debug.Log($"[GameplayTweaks][Buff] Reconciled persistent gang buffs source={sourceTag} refreshed={num} pruned={num2} invalid={num4} expired={num5} missingPlayers={num6} day={days}");
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning($"[GameplayTweaks][Buff] Persistent gang buff reconcile failed source={sourceTag}: {ex.Message}");
		}
	}

	private static bool IsPersistentGangRelationshipBuffWorldReady(int days)
	{
		if (days <= 0)
		{
			return false;
		}
		try
		{
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			if (humanPlayer == null || humanPlayer.social == null)
			{
				return false;
			}
			int num = 0;
			foreach (PlayerInfo allPlayer in G.GetAllPlayers())
			{
				if (allPlayer?.social == null)
				{
					continue;
				}
				num++;
				if (num >= 2)
				{
					return true;
				}
			}
		}
		catch
		{
		}
		return false;
	}

	private static bool TryGetRelationshipFromPlayerTo(PlayerInfo source, PlayerInfo target, bool createIfMissing, out Relationship relationship)
	{
		relationship = null;
		if (source == null || target == null || source.social == null || target.social == null)
		{
			return false;
		}
		try
		{
			if (createIfMissing)
			{
				source.social.FindOrMakeRelationshipsWith(target.PID);
			}
			relationship = source.social.GetRelationshipFromPlayerTo(target.PID);
			return relationship != null;
		}
		catch
		{
			relationship = null;
			return false;
		}
	}

	private static int GetDirectedGangRelationshipScore(PlayerInfo source, PlayerInfo target)
	{
		try
		{
			Relationship relationship;
			if (!TryGetRelationshipFromPlayerTo(source, target, createIfMissing: false, out relationship) || relationship == null)
			{
				return 0;
			}
			return Mathf.Clamp(ReadFixnum(relationship.Evaluate().current), -100, 100);
		}
		catch
		{
			return 0;
		}
	}

	private static float GetDirectedGangRelationshipHostility(PlayerInfo source, PlayerInfo target, out int relationshipScore, out bool hostileBuff, out bool severeBuff)
	{
		relationshipScore = GetDirectedGangRelationshipScore(source, target);
		float hostility = Mathf.Clamp01((-relationshipScore) / 80f);
		hostileBuff = HasAnyRelationshipBuff(source, target, _retaliationRelationshipHostileBuffIds);
		severeBuff = HasAnyRelationshipBuff(source, target, _retaliationRelationshipSevereBuffIds);
		if (hostileBuff)
		{
			hostility = Mathf.Max(hostility, 0.55f);
		}
		if (severeBuff)
		{
			hostility = Mathf.Max(hostility, 0.75f);
		}
		return Mathf.Clamp01(hostility);
	}

	private static float GetRelationshipAdjustedWarHeat(GangOpsChannel channel, PlayerInfo attacker, PlayerInfo defender, float warHeat, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool hostileBuff)
	{
		relationshipScore = 0;
		relationshipHostility = 0f;
		relationshipHeatBonus = 0f;
		hostileBuff = false;
		float rawHeat = Mathf.Clamp(warHeat, 0f, 100f);
		if (attacker == null || defender == null || attacker.PID.id == defender.PID.id)
		{
			return rawHeat;
		}
		relationshipHostility = GetDirectedGangRelationshipHostility(attacker, defender, out relationshipScore, out hostileBuff, out bool severeBuff);
		if (relationshipHostility <= 0f)
		{
			return rawHeat;
		}
		float revengeThreshold = Mathf.Max(1f, GetEffectiveWarHeatThresholdForRevenge(channel));
		relationshipHeatBonus = Mathf.Clamp(relationshipHostility * revengeThreshold * RETALIATION_RELATIONSHIP_HEAT_SCALE, 0f, RETALIATION_RELATIONSHIP_HEAT_BONUS_CAP);
		if (severeBuff)
		{
			relationshipHeatBonus = Mathf.Max(relationshipHeatBonus, Mathf.Min(RETALIATION_RELATIONSHIP_HEAT_BONUS_CAP, revengeThreshold * 0.7f));
		}
		return Mathf.Clamp(rawHeat + relationshipHeatBonus, 0f, 100f);
	}

	private static void ApplyHumanCrewKillRelationshipBuff(PlayerInfo victimGang, PlayerInfo humanPlayer, GangOpsChannel channel, string reason)
	{
		if (victimGang == null || humanPlayer == null || victimGang.PID.id == humanPlayer.PID.id)
		{
			return;
		}
		const string crewKillBuffId = "relbuff-gang-injury";
		EntityID victimBossPeep = GetCrewPeepForPlayer(victimGang);
		EntityID humanBossPeep = GetCrewPeepForPlayer(humanPlayer);
		bool victimToHuman = AddDirectedRelationshipBuff(victimGang, humanPlayer, crewKillBuffId, victimBossPeep, logSuccess: false);
		bool humanToVictim = AddDirectedRelationshipBuff(humanPlayer, victimGang, crewKillBuffId, humanBossPeep, logSuccess: false);
		VerificationLog("GangBossBuffs", $"crew-death-relationship-buff victimGang={victimGang.PID.id} human={humanPlayer.PID.id} buff={crewKillBuffId} victimBossPeep={victimBossPeep.id} humanBossPeep={humanBossPeep.id} victimToHuman={victimToHuman} humanToVictim={humanToVictim} channel={GetGangOpsChannelTag(channel)} reason={reason}");
	}

	private static bool IsUsableRelationshipBuffCrewPeep(EntityID peepId)
	{
		if (peepId.IsNotValid)
		{
			return false;
		}
		try
		{
			Entity entity = peepId.FindEntity();
			return entity?.data?.person != null && entity.data.person.IsAlive;
		}
		catch
		{
			return false;
		}
	}

	private static EntityID ResolveRelationshipBuffCrewPeep(PlayerInfo source, PlayerInfo target, EntityID requestedCrewPeep)
	{
		if (IsUsableRelationshipBuffCrewPeep(requestedCrewPeep))
		{
			return requestedCrewPeep;
		}
		EntityID crewPeepForPlayer = GetCrewPeepForPlayer(source);
		if (!crewPeepForPlayer.IsNotValid)
		{
			return crewPeepForPlayer;
		}
		if (target != null)
		{
			EntityID crewPeepForPlayer2 = GetCrewPeepForPlayer(target);
			if (!crewPeepForPlayer2.IsNotValid)
			{
				return crewPeepForPlayer2;
			}
		}
		return EntityID.INVALID;
	}

	private static BuffState FindRelationshipBuffState(Relationship relationship, string buffId)
	{
		if (relationship?.buffs?.states == null || string.IsNullOrEmpty(buffId))
		{
			return null;
		}
		Label label = new Label(buffId);
		foreach (BuffState state in relationship.buffs.states)
		{
			if (state != null && state.id == label)
			{
				return state;
			}
		}
		return null;
	}

	private static bool ShouldPersistGangRelationshipBuff(string buffId)
	{
		return !string.IsNullOrEmpty(buffId) && _persistentGangRelationshipBuffIds.Contains(buffId);
	}

	private static int ApplyPersistentGangRelationshipBuffMinimumExpireDay(string buffId, int absoluteExpireDay)
	{
		if (absoluteExpireDay < 0)
		{
			return absoluteExpireDay;
		}
		int num = GetPersistentGangRelationshipBuffMinimumDays(buffId);
		if (num <= 0)
		{
			return absoluteExpireDay;
		}
		int days;
		try
		{
			days = G.GetNow().days;
		}
		catch
		{
			days = -1;
		}
		if (days <= 0)
		{
			return absoluteExpireDay;
		}
		return Math.Max(absoluteExpireDay, days + num);
	}

	private static int GetPersistentGangRelationshipBuffMinimumDays(string buffId)
	{
		if (ContainsStringOrdinalIgnoreCase(_retaliationRelationshipSevereBuffIds, buffId))
		{
			return PERSISTENT_SEVERE_RELBUFF_MIN_DAYS;
		}
		if (ContainsStringOrdinalIgnoreCase(_retaliationRelationshipHostileBuffIds, buffId))
		{
			return PERSISTENT_HOSTILE_RELBUFF_MIN_DAYS;
		}
		return 0;
	}

	private static bool ContainsStringOrdinalIgnoreCase(string[] values, string value)
	{
		if (values == null || string.IsNullOrEmpty(value))
		{
			return false;
		}
		for (int i = 0; i < values.Length; i++)
		{
			if (string.Equals(values[i], value, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
		}
		return false;
	}

	private static string GetPersistentGangRelationshipBuffKey(int sourcePid, int targetPid, string buffId)
	{
		return sourcePid + ">" + targetPid + ":" + (buffId ?? string.Empty).ToLowerInvariant();
	}

	private static int FindPersistentGangRelationshipBuffRecordIndex(int sourcePid, int targetPid, string buffId)
	{
		if (SaveData?.GangRelationshipBuffs == null)
		{
			return -1;
		}
		for (int i = 0; i < SaveData.GangRelationshipBuffs.Count; i++)
		{
			GangRelationshipBuffState gangRelationshipBuffState = SaveData.GangRelationshipBuffs[i];
			if (gangRelationshipBuffState != null && gangRelationshipBuffState.SourcePid == sourcePid && gangRelationshipBuffState.TargetPid == targetPid && string.Equals(gangRelationshipBuffState.BuffId, buffId, StringComparison.OrdinalIgnoreCase))
			{
				return i;
			}
		}
		return -1;
	}

	private static void UpsertPersistentGangRelationshipBuffRecordFromLive(PlayerInfo source, PlayerInfo target, string buffId, Relationship relationshipFromPlayerTo, EntityID fallbackCrewPeep, bool enforceMinimumDuration = false)
	{
		if (source == null || target == null || !ShouldPersistGangRelationshipBuff(buffId))
		{
			return;
		}
		EnsureSaveDataDefaults();
		if (SaveData?.GangRelationshipBuffs == null)
		{
			return;
		}
		BuffState relationshipBuffState = FindRelationshipBuffState(relationshipFromPlayerTo, buffId);
		if (relationshipBuffState == null)
		{
			return;
		}
		int persistentGangRelationshipBuffRecordIndex = FindPersistentGangRelationshipBuffRecordIndex(source.PID.id, target.PID.id, buffId);
		GangRelationshipBuffState gangRelationshipBuffState = ((persistentGangRelationshipBuffRecordIndex >= 0) ? SaveData.GangRelationshipBuffs[persistentGangRelationshipBuffRecordIndex] : null);
		int previousExpireDay = (gangRelationshipBuffState != null) ? gangRelationshipBuffState.AbsoluteExpireDay : int.MinValue;
		if (gangRelationshipBuffState == null)
		{
			gangRelationshipBuffState = new GangRelationshipBuffState();
			SaveData.GangRelationshipBuffs.Add(gangRelationshipBuffState);
		}
		gangRelationshipBuffState.SourcePid = source.PID.id;
		gangRelationshipBuffState.TargetPid = target.PID.id;
		gangRelationshipBuffState.BuffId = buffId;
		EntityID entityID = ResolveRelationshipBuffCrewPeep(source, target, (!relationshipBuffState.crewpeep.IsNotValid) ? relationshipBuffState.crewpeep : fallbackCrewPeep);
		gangRelationshipBuffState.CrewPeepId = (entityID.IsNotValid ? 0L : ((long)entityID.id));
		int absoluteExpireDay = (relationshipBuffState.expires.NeverHappens ? -1 : relationshipBuffState.expires.days);
		int persistentExpireDay = absoluteExpireDay;
		if (previousExpireDay == -1)
		{
			persistentExpireDay = -1;
		}
		else if (persistentExpireDay >= 0 && previousExpireDay > persistentExpireDay)
		{
			persistentExpireDay = previousExpireDay;
		}
		if (enforceMinimumDuration)
		{
			persistentExpireDay = ApplyPersistentGangRelationshipBuffMinimumExpireDay(buffId, persistentExpireDay);
		}
		gangRelationshipBuffState.AbsoluteExpireDay = persistentExpireDay;
		if (persistentExpireDay >= 0 && (relationshipBuffState.expires.NeverHappens || relationshipBuffState.expires.days != persistentExpireDay))
		{
			relationshipBuffState.expires = new SimTime(persistentExpireDay);
			MarkRelationshipBuffStateChanged();
		}
	}

	private static void RemovePersistentGangRelationshipBuffRecord(int sourcePid, int targetPid, string buffId)
	{
		if (SaveData?.GangRelationshipBuffs == null)
		{
			return;
		}
		for (int num = SaveData.GangRelationshipBuffs.Count - 1; num >= 0; num--)
		{
			GangRelationshipBuffState gangRelationshipBuffState = SaveData.GangRelationshipBuffs[num];
			if (gangRelationshipBuffState != null && gangRelationshipBuffState.SourcePid == sourcePid && gangRelationshipBuffState.TargetPid == targetPid && string.Equals(gangRelationshipBuffState.BuffId, buffId, StringComparison.OrdinalIgnoreCase))
			{
				SaveData.GangRelationshipBuffs.RemoveAt(num);
			}
		}
	}

	private static void SnapshotPersistentGangRelationshipBuffsFromLiveRelations()
	{
		if (SaveData?.GangRelationshipBuffs == null)
		{
			return;
		}
		foreach (PlayerInfo allPlayer in G.GetAllPlayers())
		{
			if (allPlayer?.social == null)
			{
				continue;
			}
			foreach (PlayerInfo allPlayer2 in G.GetAllPlayers())
			{
				if (allPlayer2 == null || allPlayer2.PID.id == allPlayer.PID.id || allPlayer2.social == null)
				{
					continue;
				}
				Relationship relationshipFromPlayerTo = allPlayer.social.GetRelationshipFromPlayerTo(allPlayer2.PID);
				if (relationshipFromPlayerTo?.buffs?.states == null || relationshipFromPlayerTo.buffs.states.Count == 0)
				{
					continue;
				}
				foreach (BuffState state in relationshipFromPlayerTo.buffs.states)
				{
					if (state == null)
					{
						continue;
					}
					string text = state.id.ToString();
					if (!ShouldPersistGangRelationshipBuff(text))
					{
						continue;
					}
					try
					{
						if (state.IsExpired(relationshipFromPlayerTo.MakeModQuery(state.crewpeep)))
						{
							continue;
						}
					}
					catch
					{
					}
					UpsertPersistentGangRelationshipBuffRecordFromLive(allPlayer, allPlayer2, text, relationshipFromPlayerTo, state.crewpeep);
				}
			}
		}
	}

	private static void DeduplicatePersistentGangRelationshipBuffLedger()
	{
		if (SaveData?.GangRelationshipBuffs == null)
		{
			return;
		}
		HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		for (int num = SaveData.GangRelationshipBuffs.Count - 1; num >= 0; num--)
		{
			GangRelationshipBuffState gangRelationshipBuffState = SaveData.GangRelationshipBuffs[num];
			if (gangRelationshipBuffState == null || string.IsNullOrWhiteSpace(gangRelationshipBuffState.BuffId))
			{
				SaveData.GangRelationshipBuffs.RemoveAt(num);
				continue;
			}
			string persistentGangRelationshipBuffKey = GetPersistentGangRelationshipBuffKey(gangRelationshipBuffState.SourcePid, gangRelationshipBuffState.TargetPid, gangRelationshipBuffState.BuffId);
			if (!hashSet.Add(persistentGangRelationshipBuffKey))
			{
				SaveData.GangRelationshipBuffs.RemoveAt(num);
			}
		}
	}

	private static bool IsPersistentGangRelationshipBuffExpired(GangRelationshipBuffState state, int nowDay)
	{
		return state != null && state.AbsoluteExpireDay >= 0 && nowDay >= 0 && nowDay >= state.AbsoluteExpireDay;
	}

	private static bool RemoveDirectedRelationshipBuffLive(PlayerInfo source, PlayerInfo target, string buffId)
	{
		Relationship relationshipFromPlayerTo;
		if (!TryGetRelationshipFromPlayerTo(source, target, createIfMissing: false, out relationshipFromPlayerTo) || relationshipFromPlayerTo == null)
		{
			return false;
		}
		return relationshipFromPlayerTo.RemoveBuff(new Label(buffId));
	}

	private static void SortRelationshipBuffStates(Relationship relationship)
	{
		if (relationship?.buffs?.states == null)
		{
			return;
		}
		relationship.buffs.states.Sort((BuffState a, BuffState b) => (a?.priority ?? int.MinValue) - (b?.priority ?? int.MinValue));
	}

	private static void MarkRelationshipBuffStateChanged()
	{
		try
		{
			global::Game.Game.ctx?.events?.EnqueueOnce(SessionEventType.SomeEntityRelationshipChanged);
		}
		catch
		{
		}
	}

	private static bool RestorePersistentGangRelationshipBuffState(PlayerInfo source, PlayerInfo target, GangRelationshipBuffState state)
	{
		if (source == null || target == null || state == null || string.IsNullOrWhiteSpace(state.BuffId))
		{
			return false;
		}
		Relationship relationshipFromPlayerTo;
		if (!TryGetRelationshipFromPlayerTo(source, target, createIfMissing: true, out relationshipFromPlayerTo) || relationshipFromPlayerTo == null)
		{
			return false;
		}
		if (relationshipFromPlayerTo.buffs == null)
		{
			relationshipFromPlayerTo.buffs = new BuffStack();
		}
		EntityID entityID = ((state.CrewPeepId > 0L) ? EntityID.FromID((ulong)state.CrewPeepId) : EntityID.INVALID);
		EntityID entityID2 = ResolveRelationshipBuffCrewPeep(source, target, entityID);
		BuffState relationshipBuffState = FindRelationshipBuffState(relationshipFromPlayerTo, state.BuffId);
		if (relationshipBuffState == null)
		{
			BuffConfig config = BuffStack.GetSettings().GetConfig(new Label(state.BuffId));
			if (config == null)
			{
				return false;
			}
			BuffState buffState = BuffState.Make(config, relationshipFromPlayerTo.MakeModQuery(entityID2), entityID2);
			buffState.expires = ((state.AbsoluteExpireDay >= 0) ? new SimTime(state.AbsoluteExpireDay) : SimTime.MAX_DATE);
			relationshipFromPlayerTo.buffs.states.Add(buffState);
			SortRelationshipBuffStates(relationshipFromPlayerTo);
			MarkRelationshipBuffStateChanged();
			state.CrewPeepId = (entityID2.IsNotValid ? 0L : ((long)entityID2.id));
			return true;
		}
		bool flag = false;
		if (state.AbsoluteExpireDay >= 0)
		{
			if (relationshipBuffState.expires.NeverHappens || relationshipBuffState.expires.days != state.AbsoluteExpireDay)
			{
				relationshipBuffState.expires = new SimTime(state.AbsoluteExpireDay);
				flag = true;
			}
		}
		else if (!relationshipBuffState.expires.NeverHappens)
		{
			relationshipBuffState.expires = SimTime.MAX_DATE;
			flag = true;
		}
		if (entityID2.IsNotValid)
		{
			if (!relationshipBuffState.crewpeep.IsNotValid)
			{
				relationshipBuffState.crewpeep = EntityID.INVALID;
				flag = true;
			}
		}
		else if (relationshipBuffState.crewpeep != entityID2)
		{
			relationshipBuffState.crewpeep = entityID2;
			flag = true;
		}
		if (flag)
		{
			SortRelationshipBuffStates(relationshipFromPlayerTo);
			MarkRelationshipBuffStateChanged();
		}
		state.CrewPeepId = (entityID2.IsNotValid ? 0L : ((long)entityID2.id));
		return flag;
	}

	internal static bool RelationshipHasBuff(PlayerInfo source, PlayerInfo target, string buffId)
	{
		if (source == null || target == null || source.social == null || target.social == null || string.IsNullOrEmpty(buffId))
		{
			return false;
		}
		try
		{
			source.social.FindOrMakeRelationshipsWith(target.PID);
			Relationship relationshipFromPlayerTo = source.social.GetRelationshipFromPlayerTo(target.PID);
			if (relationshipFromPlayerTo == null)
			{
				return false;
			}
			return relationshipFromPlayerTo.HasBuff(new Label(buffId));
		}
		catch
		{
			return false;
		}
	}

	internal static bool HasAnyRelationshipBuff(PlayerInfo source, PlayerInfo target, IEnumerable<string> buffIds)
	{
		if (buffIds == null)
		{
			return false;
		}
		foreach (string buffId in buffIds)
		{
			if (RelationshipHasBuff(source, target, buffId))
			{
				return true;
			}
		}
		return false;
	}

	internal static HashSet<string> GetRelationshipBuffIds(PlayerInfo source, PlayerInfo target)
	{
		HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		if (source == null || target == null || source.social == null || target.social == null)
		{
			return hashSet;
		}
		try
		{
			source.social.FindOrMakeRelationshipsWith(target.PID);
			Relationship relationshipFromPlayerTo = source.social.GetRelationshipFromPlayerTo(target.PID);
			if (relationshipFromPlayerTo == null)
			{
				return hashSet;
			}
			foreach (string item in DEBUG_RELBUFF_IDS)
			{
				try
				{
					if (relationshipFromPlayerTo.HasBuff(new Label(item)))
					{
						hashSet.Add(item);
					}
				}
				catch
				{
				}
			}
			Type type = relationshipFromPlayerTo.GetType();
			BindingFlags bindingFlags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
			foreach (FieldInfo item2 in type.GetFields(bindingFlags))
			{
				if (item2 == null)
				{
					continue;
				}
				object value = item2.GetValue(relationshipFromPlayerTo);
				TryCollectBuffIdsFromObject(value, hashSet);
			}
			foreach (PropertyInfo item3 in type.GetProperties(bindingFlags))
			{
				if (item3 == null || item3.GetIndexParameters().Length != 0)
				{
					continue;
				}
				object value2 = null;
				try
				{
					value2 = item3.GetValue(relationshipFromPlayerTo);
				}
				catch
				{
				}
				TryCollectBuffIdsFromObject(value2, hashSet);
			}
		}
		catch
		{
		}
		return hashSet;
	}

	private static void TryCollectBuffIdsFromObject(object obj, HashSet<string> output)
	{
		if (obj == null || output == null)
		{
			return;
		}
		if (obj is Label label)
		{
			string text = label.ToString();
			if (!string.IsNullOrEmpty(text) && text.IndexOf("relbuff-", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				output.Add(text);
			}
			return;
		}
		if (obj is string text2)
		{
			if (!string.IsNullOrEmpty(text2) && text2.IndexOf("relbuff-", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				output.Add(text2);
			}
			return;
		}
		if (obj is IDictionary dictionary)
		{
			foreach (DictionaryEntry item in dictionary)
			{
				TryCollectBuffIdsFromObject(item.Key, output);
				TryCollectBuffIdsFromObject(item.Value, output);
			}
			return;
		}
		if (obj is IEnumerable enumerable && !(obj is string))
		{
			foreach (object item2 in enumerable)
			{
				TryCollectBuffIdsFromObject(item2, output);
			}
			return;
		}
		Type type = obj.GetType();
		string text3 = type.Name ?? string.Empty;
		if (text3.IndexOf("Buff", StringComparison.OrdinalIgnoreCase) < 0)
		{
			return;
		}
		BindingFlags bindingFlags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
		foreach (PropertyInfo item3 in type.GetProperties(bindingFlags))
		{
			if (item3 == null || item3.GetIndexParameters().Length != 0)
			{
				continue;
			}
			object obj2 = null;
			try
			{
				obj2 = item3.GetValue(obj);
			}
			catch
			{
			}
			TryCollectBuffIdsFromObject(obj2, output);
		}
		foreach (FieldInfo item4 in type.GetFields(bindingFlags))
		{
			if (item4 == null)
			{
				continue;
			}
			object value = item4.GetValue(obj);
			TryCollectBuffIdsFromObject(value, output);
		}
	}

	internal static void TryLogHumanGangRelationBuffSummary(int gangId, string sourceTag)
	{
		try
		{
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			PlayerInfo playerById = G.FindPlayerById(gangId);
			if (humanPlayer == null || playerById == null || humanPlayer.PID.id == playerById.PID.id)
			{
				return;
			}
			HashSet<string> relationshipBuffIds = GetRelationshipBuffIds(playerById, humanPlayer);
			HashSet<string> relationshipBuffIds2 = GetRelationshipBuffIds(humanPlayer, playerById);
			string text = (relationshipBuffIds.Count > 0) ? string.Join(",", relationshipBuffIds.OrderBy((string x) => x)) : "none";
			string text2 = (relationshipBuffIds2.Count > 0) ? string.Join(",", relationshipBuffIds2.OrderBy((string x) => x)) : "none";
			VerificationLog("GangBossBuffs", $"source={sourceTag} gang={gangId} gang->human={text} human->gang={text2}");
		}
		catch
		{
		}
	}

	private static bool IsAliveGangPlayer(PlayerInfo player)
	{
		return player != null && player.IsJustGang && player.crew != null && !player.crew.IsCrewDefeated && player.territory != null && !player.territory.IsSafehouseVanquished;
	}

	private static bool IsGangOpsRetaliationTargetEligible(PlayerInfo player)
	{
		if (IsAliveGangPlayer(player))
		{
			return true;
		}
		return player != null && player.PID.IsHumanPlayer && player.crew != null && !player.crew.IsCrewDefeated;
	}

	internal static int ReconcileRaidedGangSafehouseTerritory(string sourceTag)
	{
		int scanned = 0;
		int cleared = 0;
		int staleCleared = 0;
		int failed = 0;
		foreach (PlayerInfo player in G.GetAllPlayers())
		{
			if (player == null || player.PID.IsHumanPlayer || !player.IsJustGang || player.territory == null)
			{
				continue;
			}
			scanned++;
			int controlledBefore = SafeCountControlledBuildings(player);
			try
			{
				if (player.territory.IsSafehouseReadyToClear && player.territory.Safehouse.IsValid)
				{
					EntityID safehouse = player.territory.Safehouse;
					SafehouseUtils.ClearSafehouseAndTerritory(player, safehouse);
					ClearGangOpsStateForPlayer(player.PID.id, "raided-safehouse");
					MarkCrewPickAggroDirty(player.PID, "raided-safehouse");
					cleared++;
					VerificationLog("Territory", $"raided-safehouse-reconcile source={sourceTag} pid={player.PID.id} safehouse={safehouse.id} controlledBefore={controlledBefore} controlledAfter={SafeCountControlledBuildings(player)}");
					continue;
				}
				if (player.territory.IsSafehouseVanquished && controlledBefore > 0 && TryForceRemoveBuildingsAndTerritoryOnDefeat(player))
				{
					ClearGangOpsStateForPlayer(player.PID.id, "vanquished-safehouse");
					MarkCrewPickAggroDirty(player.PID, "vanquished-safehouse");
					staleCleared++;
					VerificationLog("Territory", $"stale-vanquished-territory-reconcile source={sourceTag} pid={player.PID.id} controlledBefore={controlledBefore} controlledAfter={SafeCountControlledBuildings(player)}");
				}
			}
			catch (Exception ex)
			{
				failed++;
				VerificationLog("Territory", $"raided-safehouse-reconcile-failed source={sourceTag} pid={player.PID.id} controlledBefore={controlledBefore} reason={ex.GetType().Name}:{ex.Message}");
			}
		}
		if (cleared > 0 || staleCleared > 0 || failed > 0)
		{
			FlushCrewPickAggroRefreshes("safehouse-territory-reconcile");
			TerritoryColorPatch.RefreshAllTerritoryColors();
			VerificationLog("Territory", $"raided-safehouse-reconcile-summary source={sourceTag} scanned={scanned} cleared={cleared} staleCleared={staleCleared} failed={failed}");
		}
		return cleared + staleCleared;
	}

	internal static int ReconcileLowRespectTerritoryOwnership(string sourceTag, bool refreshColors = true)
	{
		int cleared = 0;
		int failed = 0;
		List<Node> allNodes = null;
		try
		{
			allNodes = global::Game.Game.ctx?.board?.nodes?.GetAllNodesUnsafe();
		}
		catch
		{
		}
		if (allNodes == null || allNodes.Count == 0)
		{
			return 0;
		}

		global::Game.Services.RespectSettings settings = global::Game.Game.serv?.globals?.settings?.people?.social?.respect;
		if (settings == null)
		{
			return 0;
		}

		HashSet<PlayerID> affectedPlayers = new HashSet<PlayerID>();
		for (int i = 0; i < allNodes.Count; i++)
		{
			Node node = allNodes[i];
			PlayerID owner = node?.owner.Get() ?? PlayerID.INVALID;
			if (node == null || owner.IsNotValid || owner.IsHumanPlayer)
			{
				continue;
			}

			try
			{
				Respect respect = node.respect?.GetOrNull(owner);
				Fixnum currentRespect = respect?.current ?? Fixnum.ZERO;
				Fixnum lossThreshold = settings.lossThreshold.Evaluate(owner);
				if (currentRespect > lossThreshold)
				{
					continue;
				}
				if (IsProtectedTerritorySupportNodeForOwner(node, owner))
				{
					continue;
				}

				PlayerTerritory.ClearNodeOwner(node, owner, PlayerID.INVALID);
				affectedPlayers.Add(owner);
				cleared++;
				if (cleared <= 24)
				{
					VerificationLog("Territory", $"low-respect-owner-cleared source={sourceTag} node={node.id} owner={owner.id} respect={currentRespect} lossThreshold={lossThreshold}");
				}
			}
			catch (Exception ex)
			{
				failed++;
				if (failed <= 8)
				{
					VerificationLog("Territory", $"low-respect-owner-clear-failed source={sourceTag} node={node?.id} owner={owner.id} reason={ex.GetType().Name}:{ex.Message}");
				}
			}
		}

		if (affectedPlayers.Count > 0)
		{
			if (refreshColors)
			{
				TerritoryColorPatch.RefreshAllTerritoryColors();
			}
			VerificationLog("Territory", $"low-respect-owner-clear-summary source={sourceTag} thresholdSource=evaluated-loss cleared={cleared} failed={failed}");
		}
		return cleared;
	}

	private static bool IsProtectedTerritorySupportNodeForOwner(Node node, PlayerID owner)
	{
		if (node == null || owner.IsNotValid)
		{
			return false;
		}

		PlayerInfo ownerPlayer = owner.FindPlayer();
		if (ownerPlayer?.territory == null)
		{
			return false;
		}

		try
		{
			if (ownerPlayer.territory.IsSafehouseVanquished)
			{
				return false;
			}
		}
		catch
		{
		}

		try
		{
			Node headquartersNode = ownerPlayer.territory.GetHeadquartersNode(ignoreWarnings: true);
			if (headquartersNode?.id == node.id)
			{
				return true;
			}
		}
		catch
		{
		}

		try
		{
			if (ownerPlayer.outposts?.GetOutpostAtNode(node).IsValid == true)
			{
				return true;
			}
		}
		catch
		{
		}

		return false;
	}

	private static Fixnum GetDisplayedTerritoryRespect(Respect respect)
	{
		if (respect == null)
		{
			return Fixnum.ZERO;
		}

		return respect.goal > respect.current ? respect.goal : respect.current;
	}

	private static bool TryDetermineProtectedTerritorySupportOwner(Node node, out PlayerID supportedOwner)
	{
		supportedOwner = PlayerID.INVALID;
		if (node?.respect?.data == null || node.respect.data.Count == 0)
		{
			return false;
		}

		Fixnum bestRespect = Fixnum.ZERO;
		PlayerID lastOwner = node.owner?.lastpid ?? PlayerID.INVALID;
		for (int i = 0; i < node.respect.data.Count; i++)
		{
			Respect respect = node.respect.data[i];
			if (respect == null || respect.pid.IsNotValid || !IsProtectedTerritorySupportNodeForOwner(node, respect.pid))
			{
				continue;
			}

			Fixnum displayedRespect = GetDisplayedTerritoryRespect(respect);
			if (displayedRespect <= Fixnum.ZERO)
			{
				continue;
			}

			if (supportedOwner.IsNotValid
				|| displayedRespect > bestRespect
				|| (displayedRespect == bestRespect && respect.pid == lastOwner)
				|| (displayedRespect == bestRespect && supportedOwner != lastOwner && respect.pid.IsHumanPlayer)
				|| (displayedRespect == bestRespect && supportedOwner != lastOwner && !supportedOwner.IsHumanPlayer && respect.pid.id < supportedOwner.id))
			{
				supportedOwner = respect.pid;
				bestRespect = displayedRespect;
			}
		}

		return supportedOwner.IsValid;
	}

	internal static int EnsureHumanSafehouseTerritoryColorOwner(string sourceTag, bool refreshColors = true)
	{
		try
		{
			PlayerInfo humanPlayer = G.GetHumanPlayer();
			PlayerID humanPid = humanPlayer?.PID ?? PlayerID.INVALID;
			if (humanPlayer?.territory == null || humanPid.IsNotValid)
			{
				return 0;
			}

			Node safehouseNode = TryResolveHumanSafehouseNode(humanPlayer, out Node resolvedSafehouseNode)
				? resolvedSafehouseNode
				: humanPlayer.territory.GetHeadquartersNode();
			if (safehouseNode == null)
			{
				return 0;
			}

			PlayerID currentOwner = safehouseNode.owner.Get();
			if (currentOwner == humanPid)
			{
				return 0;
			}
			if (currentOwner.IsValid && !currentOwner.IsHumanPlayer)
			{
				return 0;
			}
			if (!HasHumanSafehouseTerritorySignal(safehouseNode, humanPid))
			{
				return 0;
			}

			if (currentOwner.IsValid)
			{
				PlayerTerritory.ClearNodeOwner(safehouseNode, currentOwner, humanPid);
			}
			PlayerTerritory.SetNodeOwner(safehouseNode, humanPid);
			if (refreshColors)
			{
				TerritoryColorPatch.RefreshAllTerritoryColors();
			}
			VerificationLog("Territory", $"human-safehouse-owner-ensured source={sourceTag} node={safehouseNode.id} pid={humanPid.id}");
			return 1;
		}
		catch (Exception ex)
		{
			VerificationLog("Territory", $"human-safehouse-owner-ensure-failed source={sourceTag} reason={ex.GetType().Name}:{ex.Message}");
			return 0;
		}
	}

	private static bool HasHumanSafehouseTerritorySignal(Node node, PlayerID humanPid)
	{
		if (node == null || humanPid.IsNotValid)
		{
			return false;
		}

		Respect respect = node.respect?.GetOrNull(humanPid);
		if (respect == null)
		{
			return true;
		}

		return respect.current > Fixnum.ZERO
			|| respect.goal > Fixnum.ZERO
			|| respect.fromSafehouse > Fixnum.ZERO;
	}

	private static int SafeCountControlledBuildings(PlayerInfo player)
	{
		try
		{
			return player?.territory?.CountControlledBuildings() ?? 0;
		}
		catch
		{
			return 0;
		}
	}

	private static bool TryForceRemoveBuildingsAndTerritoryOnDefeat(PlayerInfo player)
	{
		try
		{
			MethodInfo method = player?.territory?.GetType().GetMethod("RemoveBuildingsAndTerritoryOnDefeat", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (method == null)
			{
				return false;
			}
			method.Invoke(player.territory, null);
			return true;
		}
		catch
		{
			return false;
		}
	}

	private static bool TryGetActivePactForGang(int gangId, out AlliancePact pact)
	{
		if (gangId < 0)
		{
			pact = null;
			return false;
		}
		return _activePactByGangId.TryGetValue(gangId, out pact);
	}

	private static List<int> BuildDistinctPactGangIds(AlliancePact pact)
	{
		List<int> list = new List<int>();
		if (pact == null)
		{
			return list;
		}
		if (pact.LeaderGangId >= 0)
		{
			list.Add(pact.LeaderGangId);
		}
		if (pact.MemberIds != null)
		{
			for (int i = 0; i < pact.MemberIds.Count; i++)
			{
				int item = pact.MemberIds[i];
				if (item >= 0 && !list.Contains(item))
				{
					list.Add(item);
				}
			}
		}
		return list;
	}

	private static List<int> GetDistinctPactGangIds(AlliancePact pact)
	{
		if (pact == null)
		{
			return new List<int>();
		}
		if (pact.LeaderGangId >= 0 && _activePactGangIdsByLeaderId.TryGetValue(pact.LeaderGangId, out List<int> value))
		{
			return value;
		}
		return BuildDistinctPactGangIds(pact);
	}

	private static bool IsGangInActivePact(int gangId)
	{
		return TryGetActivePactForGang(gangId, out AlliancePact _);
	}

	private static GangOpsChannel ResolveGangOpsChannelForGang(int gangId)
	{
		return IsGangInActivePact(gangId) ? GangOpsChannel.Pact : GangOpsChannel.Independent;
	}

	private static GangOpsChannel ResolveGangOpsChannelForPair(int attackerPid, int defenderPid)
	{
		if (attackerPid >= 0)
		{
			return ResolveGangOpsChannelForGang(attackerPid);
		}

		return ResolveGangOpsChannelForGang(defenderPid);
	}

	private static bool IsGangEligibleForChannel(PlayerInfo gang, GangOpsChannel channel)
	{
		if (!IsAliveGangPlayer(gang) || gang.PID.IsHumanPlayer)
		{
			return false;
		}
		bool flag = IsGangInActivePact(gang.PID.id);
		if (channel == GangOpsChannel.Pact)
		{
			return flag;
		}
		return !flag;
	}

	private static List<int> GetEligibleGangIdsForChannel(GangOpsChannel channel)
	{
		List<int> list = new List<int>();
		foreach (PlayerInfo allPlayer in G.GetAllPlayers())
		{
			if (IsGangEligibleForChannel(allPlayer, channel))
			{
				list.Add(allPlayer.PID.id);
			}
		}
		return list;
	}

	internal static float GetWarHeat(GangOpsChannel channel, int attackerPid, int defenderPid)
	{
		Dictionary<string, WarHeatEntry> warHeatStore = GetWarHeatStore(channel);
		if (warHeatStore.TryGetValue(MakeGangPairKey(attackerPid, defenderPid), out WarHeatEntry value) && value != null)
		{
			return Mathf.Clamp(value.Heat, 0f, 100f);
		}
		return 0f;
	}

	internal static float GetWarHeat(int attackerPid, int defenderPid)
	{
		return GetUniversalDirectionalWarHeat(attackerPid, defenderPid);
	}

	internal static void AddWarHeat(GangOpsChannel channel, int attackerPid, int defenderPid, float amount, string reason)
	{
		if (attackerPid < 0 || defenderPid < 0 || attackerPid == defenderPid || amount <= 0f)
		{
			return;
		}
		Dictionary<string, WarHeatEntry> warHeatStore = GetWarHeatStore(channel);
		string key = MakeGangPairKey(attackerPid, defenderPid);
		if (!warHeatStore.TryGetValue(key, out WarHeatEntry value) || value == null)
		{
			value = new WarHeatEntry
			{
				AttackerPid = attackerPid,
				DefenderPid = defenderPid,
				Heat = 0f
			};
			warHeatStore[key] = value;
		}
		float heat = value.Heat;
		value.Heat = Mathf.Clamp(value.Heat + amount, 0f, 100f);
		value.LastUpdatedDay = G.GetNow().days;
		VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.WarHeat", $"a={attackerPid} b={defenderPid} before={heat:0.0} after={value.Heat:0.0} reason={reason}");
	}

	internal static void AddWarHeat(int attackerPid, int defenderPid, float amount, string reason)
	{
		AddWarHeat(ResolveWarHeatWriteChannel(attackerPid, defenderPid), attackerPid, defenderPid, amount, reason);
	}

	private static float GetUniversalDirectionalWarHeat(int attackerPid, int defenderPid)
	{
		if (attackerPid < 0 || defenderPid < 0 || attackerPid == defenderPid)
		{
			return 0f;
		}
		return Mathf.Max(
			GetWarHeat(GangOpsChannel.Pact, attackerPid, defenderPid),
			GetWarHeat(GangOpsChannel.Independent, attackerPid, defenderPid));
	}

	private static GangOpsChannel ResolveWarHeatWriteChannel(int attackerPid, int defenderPid)
	{
		float pactHeat = GetWarHeat(GangOpsChannel.Pact, attackerPid, defenderPid);
		float independentHeat = GetWarHeat(GangOpsChannel.Independent, attackerPid, defenderPid);
		if (pactHeat > 0.001f || independentHeat > 0.001f)
		{
			return pactHeat >= independentHeat ? GangOpsChannel.Pact : GangOpsChannel.Independent;
		}
		return ResolveGangOpsChannelForPair(attackerPid, defenderPid);
	}

	private static void QueueRevengeIfEligible(GangOpsChannel channel, int retaliationGangId, int targetGangId, long targetCrewPeepId, int nowDay, string reason)
	{
		PactOpsSettings pactOpsSettings = EnsureGangOpsSettings(channel);
		if (!pactOpsSettings.RevengeEnabled)
		{
			return;
		}
		if (retaliationGangId < 0 || targetGangId < 0 || retaliationGangId == targetGangId)
		{
			return;
		}
		PlayerInfo playerInfo = G.FindPlayerById(retaliationGangId);
		if (!IsGangEligibleForChannel(playerInfo, channel))
		{
			return;
		}
		string key = MakeGangPairKey(retaliationGangId, targetGangId);
		Dictionary<string, RevengeEntry> revengeStore = GetRevengeStore(channel);
		if (revengeStore.TryGetValue(key, out RevengeEntry value) && value != null && !value.Executed && value.DueDay >= nowDay)
		{
			return;
		}
		RevengeEntry revengeEntry = new RevengeEntry
		{
			AttackerPid = retaliationGangId,
			DefenderPid = targetGangId,
			TargetCrewPeepId = targetCrewPeepId,
			DueDay = nowDay + pactOpsSettings.RevengeDelayDays,
			Executed = false,
			SourceReason = reason
		};
		revengeStore[key] = revengeEntry;
		VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"First hit recorded for {key}, retaliation in {pactOpsSettings.RevengeDelayDays} days reason={reason}");
	}

	private static bool MarkQueuedRevengeSatisfied(GangOpsChannel channel, int retaliationGangId, int targetGangId, string reason)
	{
		if (retaliationGangId < 0 || targetGangId < 0 || retaliationGangId == targetGangId)
		{
			return false;
		}
		string key = MakeGangPairKey(retaliationGangId, targetGangId);
		Dictionary<string, RevengeEntry> revengeStore = GetRevengeStore(channel);
		if (!revengeStore.TryGetValue(key, out RevengeEntry value) || value == null || value.Executed)
		{
			return false;
		}
		value.Executed = true;
		VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Queued revenge satisfied by immediate response attacker={retaliationGangId} defender={targetGangId} dueDay={value.DueDay} reason={reason}");
		return true;
	}

	private sealed class GangRetaliationOpportunity
	{
		internal GangOpsChannel Channel;

		internal PlayerInfo Attacker;

		internal PlayerInfo Defender;

		internal float WarHeat;

		internal float EffectiveWarHeat;

		internal int RelationshipScore;

		internal float RelationshipHostility;

		internal float RelationshipHeatBonus;

		internal bool RelationshipHostileBuff;

		internal GangRetaliationAction Action = GangRetaliationAction.StandDown;

		internal int Score;

		internal string Reason = "none";

		internal bool Severe;

		internal bool HasCloseTarget;

		internal bool HasImportantBusinessTarget;

		internal bool CanCallPactSupport;

		internal bool CanTakeTerritory;

		internal bool CanHitCrew;

		internal bool ViolentAllowed;
	}

	private static void LogRobberyMeetingPreludeDryRun(
		GangRetaliationOpportunity opportunity,
		string sourceTag,
		int attackerPower,
		int defenderPower,
		bool directAggro,
		bool attackerStronger,
		bool attackerCanOverrun,
		bool aggressiveBoss,
		bool robberySource,
		float revengeThreshold,
		float coordThreshold)
	{
		PlayerInfo attacker = opportunity?.Attacker;
		PlayerInfo defender = opportunity?.Defender;
		if (attacker?.PID.IsNotAnyPlayer != false || defender?.PID.IsHumanPlayer != true)
		{
			return;
		}
		int nowDay = G.GetNow().days;
		string key = GetGangOpsChannelTag(opportunity.Channel) + ":" + MakeGangPairKey(attacker.PID.id, defender.PID.id);
		if (_robberyMeetingDryRunLastDayByPair.TryGetValue(key, out int lastDay) && nowDay >= lastDay && nowDay - lastDay < ROBBERY_MEETING_DRYRUN_LOG_COOLDOWN_DAYS)
		{
			return;
		}
		_robberyMeetingDryRunLastDayByPair[key] = nowDay;

		bool realConvoActive = TryGetActiveConvoInitiative(attacker, out NodeID convoMeetingPoint, out string convoTopic, out bool convoNeedsPeep);
		bool eligible = false;
		string reason = "not-hostile-enough";
		if (robberySource)
		{
			reason = "active-robbery-source";
		}
		else if (realConvoActive)
		{
			reason = "real-convo-active";
		}
		else if (opportunity.RelationshipHostility >= 0.55f && opportunity.EffectiveWarHeat >= revengeThreshold * 0.45f)
		{
			eligible = true;
			reason = "hostile-relation";
		}
		else if (directAggro && opportunity.EffectiveWarHeat >= revengeThreshold * 0.4f)
		{
			eligible = true;
			reason = "direct-aggro";
		}
		else if (attackerCanOverrun && aggressiveBoss && opportunity.EffectiveWarHeat >= revengeThreshold * 0.35f)
		{
			eligible = true;
			reason = "stronger-bluff";
		}
		else if (attackerStronger && opportunity.RelationshipHostileBuff && opportunity.EffectiveWarHeat >= revengeThreshold * 0.3f)
		{
			eligible = true;
			reason = "hostile-buff-bluff";
		}

		VerificationLog("GangOps.RobberyMeeting", $"robbery-meeting-dryrun attacker={attacker.PID.id} defender={defender.PID.id} eligible={eligible} reason={reason} heat={opportunity.WarHeat:0.0} effectiveHeat={opportunity.EffectiveWarHeat:0.0} revengeThreshold={revengeThreshold:0.0} coordThreshold={coordThreshold:0.0} relScore={opportunity.RelationshipScore} relHostility={opportunity.RelationshipHostility:0.00} hostileBuff={opportunity.RelationshipHostileBuff} directAggro={directAggro} attackerPower={attackerPower} defenderPower={defenderPower} attackerStronger={attackerStronger} attackerCanOverrun={attackerCanOverrun} aggressiveBoss={aggressiveBoss} action={opportunity.Action} score={opportunity.Score} source={sourceTag} convoActive={realConvoActive} convoTopic={convoTopic} convoMeetingNode={convoMeetingPoint} convoNeedsPeep={convoNeedsPeep}");
	}

	private static GangRetaliationOpportunity ScoreGangRetaliationOpportunity(GangOpsChannel channel, PlayerInfo attacker, PlayerInfo defender, EntityID preferredTargetPeepId, string sourceTag, float warHeat)
	{
		float clampedWarHeat = Mathf.Clamp(warHeat, 0f, 100f);
		float effectiveWarHeat = GetRelationshipAdjustedWarHeat(channel, attacker, defender, clampedWarHeat, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool relationshipHostileBuff);
		GangRetaliationOpportunity opportunity = new GangRetaliationOpportunity
		{
			Channel = channel,
			Attacker = attacker,
			Defender = defender,
			WarHeat = clampedWarHeat,
			EffectiveWarHeat = effectiveWarHeat,
			RelationshipScore = relationshipScore,
			RelationshipHostility = relationshipHostility,
			RelationshipHeatBonus = relationshipHeatBonus,
			RelationshipHostileBuff = relationshipHostileBuff
		};
		if (!IsGangEligibleForChannel(attacker, channel) || !IsGangOpsRetaliationTargetEligible(defender))
		{
			opportunity.Reason = "ineligible";
			LogGangRetaliationScore(opportunity);
			return opportunity;
		}
		if (ArePlayersProtectedByPactAlliance(attacker, defender))
		{
			opportunity.Reason = "alliance";
			LogGangRetaliationScore(opportunity);
			return opportunity;
		}
		if (HasMutualTruce(attacker, defender))
		{
			opportunity.Reason = "truce";
			LogGangRetaliationScore(opportunity);
			return opportunity;
		}

		PactOpsSettings settings = EnsureGangOpsSettings(channel);
		int overallAggro = Mathf.Clamp(settings?.OverallAggroPercent ?? 100, 10, 300);
		int frontAggro = Mathf.Clamp(settings?.FrontClosureAggressionPercent ?? 100, 10, 300);
		int territoryAggro = Mathf.Clamp(settings?.TerritoryTakeoverAggressionPercent ?? 100, 10, 300);
		float revengeThreshold = Mathf.Max(1f, GetEffectiveWarHeatThresholdForRevenge(channel));
		float coordThreshold = Mathf.Max(1f, GetEffectiveWarHeatThresholdForCoordAttack(channel));
		float heatRatio = Mathf.Clamp01(opportunity.EffectiveWarHeat / revengeThreshold);
		bool aggressivePersonality = IsAiPersonalityAggressive(attacker);
		bool peacefulPersonality = IsAiPersonalityPeaceful(attacker);
		bool expansionistPersonality = IsAiPersonalityExpansionist(attacker);
		bool isolationistPersonality = IsAiPersonalityIsolationist(attacker);
		bool aggressiveBoss = HasGangBossAnyTraitForRetaliation(attacker, "trait-aggressive", "trait-confident", "trait-bold") || aggressivePersonality;
		bool cautiousBoss = HasGangBossAnyTraitForRetaliation(attacker, "trait-cautious", "trait-nervous", "trait-upright", "trait-religious");
		bool severeSource = IsSevereRetaliationSource(sourceTag);
		bool defenderIsHuman = defender?.PID.IsHumanPlayer == true;
		bool aiVsAiPressure = IsAiVsAiGangPressure(attacker, defender);
		bool severeHumanSource = IsSevereHumanRetaliationSource(sourceTag);
		bool preferredTargetMakesSevere = preferredTargetPeepId.IsValid && !defenderIsHuman;
		bool bossOrKillEvent = severeSource && !defenderIsHuman || severeHumanSource || preferredTargetMakesSevere;
		int attackerPower = CalculateGangPower(attacker);
		int defenderPower = CalculateGangPower(defender);
		bool weakAttacker = attackerPower + 15 < defenderPower;
		bool attackerStronger = attackerPower >= defenderPower + 15;
		bool attackerCanOverrun = attackerPower >= defenderPower + 45 || attackerPower >= Mathf.RoundToInt(defenderPower * 1.35f);
		bool directAggro = IsAggroWithoutTruceEitherWay(attacker, defender);
		bool robberySource = IsRobberyRetaliationSource(sourceTag);
		bool robberyRefusalRareAttack = ShouldAllowRareRobberyRefusalAttack(attacker, defender, sourceTag, opportunity.EffectiveWarHeat, coordThreshold);
		bool frontPowerAllowed = IsAiVsAiFrontClosurePowerAllowed(attacker, defender, attackerPower, defenderPower, out string frontPowerReason);
		if (!frontPowerAllowed)
		{
			VerificationLog("GangOps.FrontMovement", $"front-power-blocked attacker={attacker?.PID.id ?? 0} defender={defender?.PID.id ?? 0} attackerPower={attackerPower} defenderPower={defenderPower} reason={frontPowerReason} source={sourceTag}");
		}
		bool hasFrontOrBackroomTarget = frontPowerAllowed && TryFindRetaliationFrontOrBackroomTarget(attacker, defender, null, out _, out _, out _);
		Entity warHeatClosureTarget = null;
		bool hasGenericClosureTarget = frontPowerAllowed && TryFindRetaliationClosureTarget(attacker, defender, out warHeatClosureTarget, out _);
		bool hasImportantBusinessTarget = hasGenericClosureTarget && TryValidateRetaliationImportantShopTarget(warHeatClosureTarget, out _, out _);
		bool hasCloseTarget = hasFrontOrBackroomTarget || hasImportantBusinessTarget || hasGenericClosureTarget;
		bool canTakeTerritory = ShouldAllowGangTerritoryExpansion() && GetOwnedBuildings(attacker).Count > 0;
		bool relationshipRevengePressure = opportunity.RelationshipHostility >= 0.45f && opportunity.EffectiveWarHeat >= revengeThreshold * 0.6f;
		bool relationshipViolentPressure = opportunity.RelationshipHostility >= 0.55f && (directAggro || opportunity.EffectiveWarHeat >= revengeThreshold * 0.75f);
		bool canHitHumanCrew = !defenderIsHuman || severeHumanSource || opportunity.EffectiveWarHeat >= coordThreshold || relationshipViolentPressure;
		bool violentAllowed = bossOrKillEvent
			|| (directAggro && opportunity.EffectiveWarHeat >= revengeThreshold)
			|| opportunity.EffectiveWarHeat >= coordThreshold * 1.35f
			|| relationshipViolentPressure
			|| (attackerCanOverrun && aggressiveBoss && opportunity.EffectiveWarHeat >= revengeThreshold * 0.8f && territoryAggro >= 90);
		if (weakAttacker && !bossOrKillEvent && !relationshipRevengePressure && opportunity.EffectiveWarHeat < coordThreshold * 1.6f)
		{
			violentAllowed = false;
		}
		if (robberyRefusalRareAttack)
		{
			violentAllowed = true;
		}
		else if (robberySource && !bossOrKillEvent && (hasCloseTarget || canTakeTerritory))
		{
			violentAllowed = false;
		}
		bool canHitCrew = violentAllowed && attacker.crew?.LivingCrewCount > 0 && defender.crew != null && !defender.crew.IsCrewDefeated && canHitHumanCrew;
		bool canCallPactSupport = channel == GangOpsChannel.Pact && HasAvailablePactRetaliationSupport(attacker, defender);
		opportunity.Severe = bossOrKillEvent || opportunity.EffectiveWarHeat >= coordThreshold || (channel == GangOpsChannel.Independent && opportunity.EffectiveWarHeat >= revengeThreshold * 1.5f) || opportunity.RelationshipHostility >= 0.75f;
		opportunity.HasCloseTarget = hasCloseTarget;
		opportunity.HasImportantBusinessTarget = hasImportantBusinessTarget;
		opportunity.CanCallPactSupport = canCallPactSupport;
		opportunity.CanTakeTerritory = canTakeTerritory;
		opportunity.CanHitCrew = canHitCrew;
		opportunity.ViolentAllowed = violentAllowed;

		if (opportunity.EffectiveWarHeat < revengeThreshold * 0.4f && !opportunity.Severe && !directAggro && opportunity.RelationshipHostility < 0.45f)
		{
			opportunity.Action = GangRetaliationAction.StandDown;
			opportunity.Score = 10;
			opportunity.Reason = "heat-low";
			LogGangRetaliationScore(opportunity);
			return opportunity;
		}

		int closePowerModifier = aiVsAiPressure
			? (attackerCanOverrun ? 24 : (attackerStronger ? 14 : (weakAttacker ? -24 : 4)))
			: (weakAttacker ? 12 : 0);
		int territoryPowerModifier = aiVsAiPressure
			? (attackerCanOverrun ? 18 : (attackerStronger ? 8 : (weakAttacker ? -30 : 0)))
			: ((weakAttacker ? 8 : 0) + (attackerCanOverrun ? 12 : 0));
		int relationshipClosureBonus = Mathf.RoundToInt(opportunity.RelationshipHostility * 14f);
		int relationshipAttackBonus = Mathf.RoundToInt(opportunity.RelationshipHostility * 34f) + (opportunity.RelationshipHostileBuff ? 8 : 0);
		int closeScore = hasCloseTarget
			? 55 + Mathf.RoundToInt(heatRatio * 25f) + frontAggro / 7 + (overallAggro < 125 ? 18 : 0) + (cautiousBoss ? 10 : 0) + (expansionistPersonality ? 16 : 0) - (peacefulPersonality ? 12 : 0) - (isolationistPersonality ? 16 : 0) + closePowerModifier + (!violentAllowed ? 18 : 0) + (robberySource ? (attackerStronger ? 22 : 14) : 0) + relationshipClosureBonus
			: -1;
		float importantBusinessHeatThreshold = Mathf.Max(revengeThreshold, coordThreshold * 0.75f);
		int importantBusinessScore = hasImportantBusinessTarget && !robberySource && opportunity.EffectiveWarHeat >= importantBusinessHeatThreshold
			? 58 + Mathf.RoundToInt(heatRatio * 28f) + overallAggro / 7 + frontAggro / 10 + (opportunity.EffectiveWarHeat >= coordThreshold ? 10 : 0) + (aggressivePersonality ? 10 : 0) + (expansionistPersonality ? 4 : 0) - (peacefulPersonality ? 12 : 0) - (isolationistPersonality ? 8 : 0) + closePowerModifier + (!violentAllowed ? 10 : 0) + relationshipClosureBonus
			: -1;
		int hitScore = canHitCrew
			? 14 + Mathf.RoundToInt(heatRatio * 20f) + overallAggro / 10 + (bossOrKillEvent ? 26 : 0) + (directAggro ? 12 : 0) + (attackerCanOverrun ? 18 : 0) + (aggressiveBoss ? 6 : 0) + (robberyRefusalRareAttack ? 70 : 0) + relationshipAttackBonus - (weakAttacker && !relationshipRevengePressure ? 30 : 0) - (robberySource ? (robberyRefusalRareAttack ? 10 : 65) : 0)
			: -1;
		int territoryScore = canTakeTerritory
			? 28 + territoryAggro / 6 + (channel == GangOpsChannel.Independent ? 14 : 0) + (!hasCloseTarget ? 12 : 0) + (expansionistPersonality ? 16 : 0) - (peacefulPersonality ? 6 : 0) - (isolationistPersonality ? 18 : 0) + territoryPowerModifier + (!violentAllowed ? 10 : 0) + (robberySource ? (attackerStronger ? 22 : 10) : 0)
			: -1;
		int supportScore = canCallPactSupport && opportunity.Severe
			? 40 + Mathf.RoundToInt(heatRatio * 24f) + (weakAttacker ? 16 : 0) + (bossOrKillEvent ? 18 : 0) + (!violentAllowed ? 12 : 0)
			: -1;

		if (supportScore >= 0 && supportScore >= hitScore && supportScore >= closeScore && supportScore >= importantBusinessScore && supportScore >= territoryScore)
		{
			opportunity.Action = GangRetaliationAction.CallPactSupport;
			opportunity.Score = supportScore;
			opportunity.Reason = bossOrKillEvent ? "severe-pact-support" : "high-heat-pact-support";
		}
		else if (importantBusinessScore >= 0 && importantBusinessScore >= closeScore && importantBusinessScore >= hitScore && importantBusinessScore >= territoryScore)
		{
			opportunity.Action = GangRetaliationAction.AttackBuilding;
			opportunity.Score = importantBusinessScore;
			opportunity.Reason = "warheat-important-business";
		}
		else if (closeScore >= 0 && closeScore >= hitScore && closeScore >= territoryScore)
		{
			opportunity.Action = GangRetaliationAction.CloseFront;
			opportunity.Score = closeScore;
			opportunity.Reason = robberySource ? "robbery-business-pressure" : (overallAggro < 125 ? "protect-income" : "close-front");
		}
		else if (hitScore >= 0 && hitScore >= territoryScore)
		{
			opportunity.Action = GangRetaliationAction.HitCrew;
			opportunity.Score = hitScore;
			opportunity.Reason = robberyRefusalRareAttack ? "robbery-refusal-rare-attack" : (opportunity.Severe ? "severe-violence" : (aggressiveBoss ? "aggressive-boss" : "crew-hit"));
		}
		else if (territoryScore >= 0)
		{
			opportunity.Action = GangRetaliationAction.TakeTerritory;
			opportunity.Score = territoryScore;
			opportunity.Reason = robberySource ? "robbery-territory-pressure" : (channel == GangOpsChannel.Independent ? "independent-pressure" : "territory-pressure");
		}
		else
		{
			opportunity.Action = GangRetaliationAction.StandDown;
			opportunity.Score = 0;
			opportunity.Reason = "no-action";
		}

		LogRobberyMeetingPreludeDryRun(opportunity, sourceTag, attackerPower, defenderPower, directAggro, attackerStronger, attackerCanOverrun, aggressiveBoss, robberySource, revengeThreshold, coordThreshold);
		LogGangRetaliationScore(opportunity);
		return opportunity;
	}

	internal static bool ShouldAllowBaseCoordinatedAttack(PlayerInfo attacker, PlayerInfo defender, out string reason)
	{
		reason = "none";
		if (!IsAliveGangPlayer(attacker) || !IsGangOpsRetaliationTargetEligible(defender) || attacker.PID.id == defender.PID.id)
		{
			reason = "ineligible";
			return false;
		}
		if (ArePlayersProtectedByPactAlliance(attacker, defender))
		{
			reason = "alliance";
			return false;
		}
		if (HasMutualTruce(attacker, defender))
		{
			reason = "truce";
			return false;
		}

		GangOpsChannel channel = ResolveGangOpsChannelForGang(attacker.PID.id);
		float warHeat = GetWarHeat(channel, attacker.PID.id, defender.PID.id);
		float effectiveWarHeat = GetRelationshipAdjustedWarHeat(channel, attacker, defender, warHeat, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool relationshipHostileBuff);
		float revengeThreshold = Mathf.Max(1f, GetEffectiveWarHeatThresholdForRevenge(channel));
		float coordThreshold = Mathf.Max(1f, GetEffectiveWarHeatThresholdForCoordAttack(channel));
		bool directAggro = IsAggroWithoutTruceEitherWay(attacker, defender);
		int attackerPower = CalculateGangPower(attacker);
		int defenderPower = CalculateGangPower(defender);
		bool attackerCanOverrun = attackerPower >= defenderPower + 60 || attackerPower >= Mathf.RoundToInt(defenderPower * 1.5f);
		bool aggressiveBoss = HasGangBossAnyTraitForRetaliation(attacker, "trait-aggressive", "trait-confident", "trait-bold");

		if (effectiveWarHeat >= coordThreshold * 1.2f)
		{
			reason = "warheat-coord";
			return true;
		}
		if (directAggro && effectiveWarHeat >= revengeThreshold * 0.85f)
		{
			reason = "existing-aggro";
			return true;
		}
		if (relationshipHostility >= 0.45f && effectiveWarHeat >= revengeThreshold * 0.6f)
		{
			reason = $"hostile-relation relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff}";
			return true;
		}
		if (attackerCanOverrun && aggressiveBoss && effectiveWarHeat >= revengeThreshold * 0.8f && GetOwnedBuildings(defender).Count > 0)
		{
			reason = "overrun-smaller-gang";
			return true;
		}

		reason = $"nonviolent-options-preferred heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff} power={attackerPower}:{defenderPower}";
		return false;
	}

	private static bool IsSevereRetaliationSource(string sourceTag)
	{
		if (string.IsNullOrEmpty(sourceTag))
		{
			return false;
		}
		return sourceTag.IndexOf("boss", StringComparison.OrdinalIgnoreCase) >= 0
			|| sourceTag.IndexOf("kill", StringComparison.OrdinalIgnoreCase) >= 0
			|| sourceTag.IndexOf("leader", StringComparison.OrdinalIgnoreCase) >= 0
			|| sourceTag.IndexOf("threshold", StringComparison.OrdinalIgnoreCase) >= 0;
	}

	private static bool IsSevereHumanRetaliationSource(string sourceTag)
	{
		if (string.IsNullOrEmpty(sourceTag))
		{
			return false;
		}
		return sourceTag.IndexOf("boss", StringComparison.OrdinalIgnoreCase) >= 0
			|| sourceTag.IndexOf("kill", StringComparison.OrdinalIgnoreCase) >= 0
			|| sourceTag.IndexOf("leader", StringComparison.OrdinalIgnoreCase) >= 0;
	}

	private static bool IsRobberyRetaliationSource(string sourceTag)
	{
		return !string.IsNullOrEmpty(sourceTag)
			&& sourceTag.IndexOf("robbery", StringComparison.OrdinalIgnoreCase) >= 0;
	}

	private static bool ShouldAllowRareRobberyRefusalAttack(PlayerInfo attacker, PlayerInfo defender, string sourceTag, float warHeat, float coordThreshold)
	{
		if (!IsRobberyRetaliationSource(sourceTag) || string.IsNullOrEmpty(sourceTag) || sourceTag.IndexOf("refused", StringComparison.OrdinalIgnoreCase) < 0)
		{
			return false;
		}
		if (attacker?.crew == null || attacker.crew.LivingCrewCount <= 0 || defender?.crew == null || defender.crew.IsCrewDefeated)
		{
			return false;
		}
		int chance = 12;
		if (warHeat >= coordThreshold)
		{
			chance += 6;
		}
		if (IsAggroWithoutTruceEitherWay(attacker, defender))
		{
			chance += 4;
		}
		chance = Mathf.Clamp(chance, 0, 25);
		unchecked
		{
			int hash = G.GetNow().days;
			hash = hash * 397 ^ (attacker?.PID.id ?? 0);
			hash = hash * 397 ^ (defender?.PID.id ?? 0);
			for (int i = 0; i < sourceTag.Length; i++)
			{
				hash = hash * 31 + sourceTag[i];
			}
			int roll = (hash & 0x7fffffff) % 100;
			return roll < chance;
		}
	}

	private static bool HasAiPersonalityAspect(PlayerInfo player, params string[] aspectIds)
	{
		if (player?.ai?.Data == null || aspectIds == null || aspectIds.Length == 0)
		{
			return false;
		}
		try
		{
			if (DoesAiPersonalityLabelMatch(player.ai.Data.personality, aspectIds))
			{
				return true;
			}
			if (player.ai.Data.aspects != null)
			{
				foreach (Label aspect in player.ai.Data.aspects)
				{
					if (DoesAiPersonalityLabelMatch(aspect, aspectIds))
					{
						return true;
					}
				}
			}
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.Personality", $"personality-read-failed player={player?.PID.id ?? -1} reason={ex.GetType().Name}:{ex.Message}");
		}
		return false;
	}

	private static bool IsAiPersonalityPeaceful(PlayerInfo player)
	{
		return HasAiPersonalityAspect(player, "peaceful", "aspect-peaceful", "personality-peaceful");
	}

	private static bool IsAiPersonalityAggressive(PlayerInfo player)
	{
		return HasAiPersonalityAspect(player, "aggressive", "aspect-aggressive", "personality-aggressive");
	}

	private static bool IsAiPersonalityExpansionist(PlayerInfo player)
	{
		return HasAiPersonalityAspect(player, "expansionist", "aspect-expansionist", "personality-expansionist");
	}

	private static bool IsAiPersonalityIsolationist(PlayerInfo player)
	{
		return HasAiPersonalityAspect(player, "isolationist", "aspect-isolationist", "personality-isolationist");
	}

	private static bool DoesAiPersonalityLabelMatch(Label label, string[] ids)
	{
		if (label.IsNotSet)
		{
			return false;
		}
		string normalized = NormalizeAiPersonalityLabel(label.ToString());
		if (string.IsNullOrEmpty(normalized))
		{
			return false;
		}
		for (int i = 0; i < ids.Length; i++)
		{
			string candidate = NormalizeAiPersonalityLabel(ids[i]);
			if (!string.IsNullOrEmpty(candidate) && string.Equals(normalized, candidate, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
		}
		return false;
	}

	private static string NormalizeAiPersonalityLabel(string value)
	{
		if (string.IsNullOrWhiteSpace(value))
		{
			return string.Empty;
		}
		string text = value.Trim().ToLowerInvariant();
		if (text.StartsWith("aspect-", StringComparison.Ordinal))
		{
			text = text.Substring("aspect-".Length);
		}
		if (text.StartsWith("personality-", StringComparison.Ordinal))
		{
			text = text.Substring("personality-".Length);
		}
		if (text.StartsWith("ai-", StringComparison.Ordinal))
		{
			text = text.Substring("ai-".Length);
		}
		return text;
	}

	private static bool HasGangBossAnyTraitForRetaliation(PlayerInfo gang, params string[] traitIds)
	{
		if (gang == null || traitIds == null || traitIds.Length == 0)
		{
			return false;
		}
		EntityID bossPeepId = GetCrewPeepForPlayer(gang);
		Entity boss = bossPeepId.IsValid ? bossPeepId.FindEntity() : null;
		if (boss == null)
		{
			return false;
		}
		for (int i = 0; i < traitIds.Length; i++)
		{
			if (HasTrait(boss, traitIds[i]))
			{
				return true;
			}
		}
		return false;
	}

	private static void LogGangRetaliationScore(GangRetaliationOpportunity opportunity)
	{
		if (opportunity == null)
		{
			return;
		}
		int attackerPid = opportunity.Attacker?.PID.id ?? -1;
		int defenderPid = opportunity.Defender?.PID.id ?? -1;
		VerificationLog("GangOps.RetaliationScore", $"attacker={attackerPid} defender={defenderPid} channel={GetGangOpsChannelTag(opportunity.Channel)} heat={opportunity.WarHeat:0.0} effectiveHeat={opportunity.EffectiveWarHeat:0.0} relScore={opportunity.RelationshipScore} relHostility={opportunity.RelationshipHostility:0.00} relHeatBonus={opportunity.RelationshipHeatBonus:0.0} relHostileBuff={opportunity.RelationshipHostileBuff} action={opportunity.Action} score={opportunity.Score} reason={opportunity.Reason} close={opportunity.HasCloseTarget} importantBusiness={opportunity.HasImportantBusinessTarget} support={opportunity.CanCallPactSupport} territory={opportunity.CanTakeTerritory} hitCrew={opportunity.CanHitCrew} violentAllowed={opportunity.ViolentAllowed} severe={opportunity.Severe}");
	}

	private static bool HasAvailablePactRetaliationSupport(PlayerInfo attacker, PlayerInfo defender)
	{
		if (!TryGetActivePactForGang(attacker?.PID.id ?? -1, out AlliancePact pact) || pact == null)
		{
			return false;
		}
		return GetDistinctPactGangIds(pact)
			.Select(id => G.FindPlayerById(id))
			.Any(member => member != null
				&& member.PID.id != attacker.PID.id
				&& member.PID.id != defender.PID.id
				&& IsGangEligibleForChannel(member, GangOpsChannel.Pact)
				&& !ArePlayersProtectedByPactAlliance(member, defender)
				&& !HasMutualTruce(member, defender));
	}

	private static bool TryCallPactRetaliationSupport(PlayerInfo attacker, PlayerInfo defender, EntityID preferredTargetPeepId, string sourceTag, out int dispatchedCount)
	{
		dispatchedCount = 0;
		if (!TryGetActivePactForGang(attacker?.PID.id ?? -1, out AlliancePact pact) || pact == null)
		{
			return false;
		}
		int supporters = 0;
		int approachSupporters = 0;
		foreach (PlayerInfo member in GetDistinctPactGangIds(pact)
			.Select(id => G.FindPlayerById(id))
			.Where(member => member != null
				&& member.PID.id != attacker.PID.id
				&& member.PID.id != defender.PID.id
				&& IsGangEligibleForChannel(member, GangOpsChannel.Pact)
				&& !ArePlayersProtectedByPactAlliance(member, defender)
				&& !HasMutualTruce(member, defender))
			.OrderByDescending(member => CalculateGangPower(member))
			.Take(2))
		{
			ActivateWarBetweenPlayers(member, defender);
			AddWarHeat(GangOpsChannel.Pact, member.PID.id, defender.PID.id, Mathf.Max(10f, EnsureGangOpsSettings(GangOpsChannel.Pact).WarHeatAttackGain * 0.5f), "pact-support-retaliation");
			if (TryDispatchRuntimeGangAttack(member, defender, 1, sourceTag + "-pact-support", preferredTargetPeepId, out int supportDispatched, out int supportApproached))
			{
				dispatchedCount += supportDispatched;
			}
			approachSupporters += supportApproached;
			supporters++;
		}
		if (supporters > 0)
		{
			VerificationLog("GangOps.RetaliationScore", $"pact-support attacker={attacker.PID.id} defender={defender.PID.id} pact={pact.PactId} supporters={supporters} dispatched={dispatchedCount} approached={approachSupporters} source={sourceTag}");
		}
		return dispatchedCount > 0;
	}

	private static void TryTriggerImmediateThresholdRetaliation(GangOpsChannel channel, int retaliationGangId, int targetGangId, float priorHeat, float currentHeat, long targetCrewPeepId, string reason)
	{
		float warHeatThresholdForRevenge = GetEffectiveWarHeatThresholdForRevenge(channel);
		PlayerInfo playerInfo = G.FindPlayerById(retaliationGangId);
		PlayerInfo playerInfo2 = G.FindPlayerById(targetGangId);
		float priorEffectiveHeat = GetRelationshipAdjustedWarHeat(channel, playerInfo, playerInfo2, priorHeat, out _, out _, out _, out _);
		float currentEffectiveHeat = GetRelationshipAdjustedWarHeat(channel, playerInfo, playerInfo2, currentHeat, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool relationshipHostileBuff);
		if (priorEffectiveHeat >= warHeatThresholdForRevenge || currentEffectiveHeat < warHeatThresholdForRevenge)
		{
			return;
		}
		if (!IsGangEligibleForChannel(playerInfo, channel) || !IsGangOpsRetaliationTargetEligible(playerInfo2))
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Immediate threshold retaliation skipped attacker={retaliationGangId} defender={targetGangId} reason=ineligible before={priorHeat:0.0} after={currentHeat:0.0} beforeEffective={priorEffectiveHeat:0.0} afterEffective={currentEffectiveHeat:0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff}");
			return;
		}
		if (ArePlayersProtectedByPactAlliance(playerInfo, playerInfo2))
		{
			ClearWarBetweenPlayers(playerInfo, playerInfo2);
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Immediate threshold retaliation skipped attacker={retaliationGangId} defender={targetGangId} reason=alliance before={priorHeat:0.0} after={currentHeat:0.0} beforeEffective={priorEffectiveHeat:0.0} afterEffective={currentEffectiveHeat:0.0}");
			return;
		}
		if (HasMutualTruce(playerInfo, playerInfo2))
		{
			ClearWarBetweenPlayers(playerInfo, playerInfo2);
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Immediate threshold retaliation skipped attacker={retaliationGangId} defender={targetGangId} reason=truce before={priorHeat:0.0} after={currentHeat:0.0} beforeEffective={priorEffectiveHeat:0.0} afterEffective={currentEffectiveHeat:0.0}");
			return;
		}
		EntityID preferredTargetPeepId = EntityID.INVALID;
		if (targetCrewPeepId > 0)
		{
			preferredTargetPeepId = EntityID.FromID((ulong)targetCrewPeepId);
		}
		ActivateWarBetweenPlayers(playerInfo, playerInfo2);
		bool actionTaken = TryExecuteRetaliationResponse(channel, playerInfo, playerInfo2, preferredTargetPeepId, $"{GetGangOpsChannelTag(channel)}-threshold-immediate-{reason}", currentHeat, out int dispatchedCount, out string actionSummary);
		if (actionTaken)
		{
			MarkQueuedRevengeSatisfied(channel, retaliationGangId, targetGangId, "threshold-immediate");
		}
		VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Immediate threshold retaliation attacker={retaliationGangId} defender={targetGangId} action={actionSummary} crews={dispatchedCount} taken={actionTaken} reason={reason} before={priorHeat:0.0} after={currentHeat:0.0} beforeEffective={priorEffectiveHeat:0.0} afterEffective={currentEffectiveHeat:0.0} threshold={warHeatThresholdForRevenge:0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff}");
	}

	internal static void RegisterGangOpsHostileEvent(int attackerPid, int defenderPid, bool lethal, long attackerCrewPeepId)
	{
		if (!EnableAIAlliances.Value)
		{
			return;
		}
		if (attackerPid < 0 || defenderPid < 0 || attackerPid == defenderPid)
		{
			return;
		}
		PlayerInfo playerInfo = G.FindPlayerById(attackerPid);
		PlayerInfo playerInfo2 = G.FindPlayerById(defenderPid);
		bool attackerIsAiGang = IsAliveGangPlayer(playerInfo) && !playerInfo.PID.IsHumanPlayer;
		bool defenderIsAiGang = IsAliveGangPlayer(playerInfo2) && !playerInfo2.PID.IsHumanPlayer;
		bool attackerIsHuman = playerInfo?.PID.IsHumanPlayer == true;
		if (!attackerIsAiGang && !(attackerIsHuman && defenderIsAiGang))
		{
			return;
		}
		if (ArePlayersProtectedByPactAlliance(playerInfo, playerInfo2))
		{
			ClearWarBetweenPlayers(playerInfo, playerInfo2);
			VerificationLog("GangOps.Route", $"hostile-skipped-alliance attacker={attackerPid} defender={defenderPid} lethal={lethal}");
			return;
		}
		if (HasMutualTruce(playerInfo, playerInfo2))
		{
			ClearWarBetweenPlayers(playerInfo, playerInfo2);
			VerificationLog("GangOps.Route", $"hostile-skipped-truce attacker={attackerPid} defender={defenderPid} lethal={lethal}");
			return;
		}
		GangOpsChannel gangOpsChannel = ResolveGangOpsChannelForGang(attackerIsAiGang ? attackerPid : defenderPid);
		VerificationLog("GangOps.Route", $"attacker={attackerPid} defender={defenderPid} channel={GetGangOpsChannelTag(gangOpsChannel)} lethal={lethal} mode={(attackerIsHuman ? "human-attack-retaliation" : "ai-attack")}");
		if (!IsGangOpsEnabled(gangOpsChannel))
		{
			return;
		}
		PactOpsSettings pactOpsSettings = EnsureGangOpsSettings(gangOpsChannel);
		float amount = lethal ? pactOpsSettings.WarHeatKillGain : pactOpsSettings.WarHeatAttackGain;
		int heatAttackerPid = attackerIsAiGang ? attackerPid : defenderPid;
		int heatDefenderPid = attackerIsAiGang ? defenderPid : attackerPid;
		float warHeat = GetWarHeat(gangOpsChannel, heatAttackerPid, heatDefenderPid);
		AddWarHeat(gangOpsChannel, heatAttackerPid, heatDefenderPid, amount, lethal ? (attackerIsHuman ? "human-crew-killed" : "crew-killed") : (attackerIsHuman ? "human-attack" : "attack"));
		if (lethal && attackerIsHuman && defenderIsAiGang)
		{
			ApplyHumanCrewKillRelationshipBuff(playerInfo2, playerInfo, gangOpsChannel, "human-crew-killed");
		}
		float warHeat2 = GetWarHeat(gangOpsChannel, heatAttackerPid, heatDefenderPid);
		if (attackerIsHuman && defenderIsAiGang)
		{
			QueueRevengeIfEligible(gangOpsChannel, defenderPid, attackerPid, attackerCrewPeepId, G.GetNow().days, lethal ? "human-kill-first-hit" : "human-attack-first-hit");
		}
		if (defenderIsAiGang)
		{
			GangOpsChannel gangOpsChannel2 = attackerIsAiGang ? ResolveGangOpsChannelForGang(defenderPid) : gangOpsChannel;
			int retaliationGangId = attackerIsAiGang ? defenderPid : defenderPid;
			int targetGangId = attackerIsAiGang ? attackerPid : attackerPid;
			string text = lethal ? (attackerIsHuman ? "human-kill-threshold" : "kill-threshold") : (attackerIsHuman ? "human-attack-threshold" : "attack-threshold");
			PlayerInfo retaliationGang = G.FindPlayerById(retaliationGangId);
			PlayerInfo targetGang = G.FindPlayerById(targetGangId);
			float effectiveHeatAfter = GetRelationshipAdjustedWarHeat(gangOpsChannel2, retaliationGang, targetGang, warHeat2, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool relationshipHostileBuff);
			float threshold = GetEffectiveWarHeatThresholdForRevenge(gangOpsChannel2);
			if (effectiveHeatAfter >= threshold)
			{
				QueueRevengeIfEligible(gangOpsChannel2, retaliationGangId, targetGangId, attackerCrewPeepId, G.GetNow().days, text);
				TryTriggerImmediateThresholdRetaliation(gangOpsChannel2, retaliationGangId, targetGangId, warHeat, warHeat2, attackerCrewPeepId, text);
			}
			else if (relationshipHostility >= 0.35f)
			{
				VerificationLog($"GangOps.{GetGangOpsChannelTag(gangOpsChannel2)}.Revenge", $"Immediate relationship retaliation below threshold attacker={retaliationGangId} defender={targetGangId} reason={text} heat={warHeat2:0.0} effectiveHeat={effectiveHeatAfter:0.0} threshold={threshold:0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff}");
			}
		}
	}

	internal static void RegisterPactHostileEvent(int attackerPid, int defenderPid, bool lethal, long attackerCrewPeepId)
	{
		if (!EnableAIAlliances.Value || !IsPactOpsEnabled())
		{
			return;
		}
		if (attackerPid < 0 || defenderPid < 0 || attackerPid == defenderPid)
		{
			return;
		}
		PlayerInfo attacker = G.FindPlayerById(attackerPid);
		PlayerInfo defender = G.FindPlayerById(defenderPid);
		if (ArePlayersProtectedByPactAlliance(attacker, defender))
		{
			ClearWarBetweenPlayers(attacker, defender);
			VerificationLog("GangOps.Pact.Route", $"hostile-skipped-alliance attacker={attackerPid} defender={defenderPid} lethal={lethal}");
			return;
		}
		if (HasMutualTruce(attacker, defender))
		{
			ClearWarBetweenPlayers(attacker, defender);
			VerificationLog("GangOps.Pact.Route", $"hostile-skipped-truce attacker={attackerPid} defender={defenderPid} lethal={lethal}");
			return;
		}
		PactOpsSettings pactOpsSettings = EnsurePactOpsSettings();
		float amount = lethal ? pactOpsSettings.WarHeatKillGain : pactOpsSettings.WarHeatAttackGain;
		AddWarHeat(GangOpsChannel.Pact, attackerPid, defenderPid, amount, lethal ? "crew-killed" : "attack");
		float warHeat = GetWarHeat(GangOpsChannel.Pact, attackerPid, defenderPid);
		PlayerInfo retaliationGang = G.FindPlayerById(defenderPid);
		PlayerInfo targetGang = G.FindPlayerById(attackerPid);
		float effectiveWarHeat = GetRelationshipAdjustedWarHeat(GangOpsChannel.Pact, retaliationGang, targetGang, warHeat, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool relationshipHostileBuff);
		if (effectiveWarHeat >= GetEffectiveWarHeatThresholdForRevenge(GangOpsChannel.Pact))
		{
			QueueRevengeIfEligible(GangOpsChannel.Pact, defenderPid, attackerPid, attackerCrewPeepId, G.GetNow().days, lethal ? "kill-threshold" : "attack-threshold");
		}
		else if (relationshipHostility >= 0.35f)
		{
			VerificationLog("GangOps.Pact.Revenge", $"Pact retaliation below threshold attacker={defenderPid} defender={attackerPid} heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} threshold={GetEffectiveWarHeatThresholdForRevenge(GangOpsChannel.Pact):0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff}");
		}
	}

	internal static void DecayWarHeat(GangOpsChannel channel, int nowDay)
	{
		if (!EnableAIAlliances.Value || !IsGangOpsEnabled(channel))
		{
			return;
		}
		if (_lastGangOpsWarHeatDecayDay.TryGetValue(channel, out int value2) && value2 >= 0 && nowDay - value2 < PACTOPS_WARHEAT_DECAY_INTERVAL_DAYS)
		{
			return;
		}
		PactOpsSettings pactOpsSettings = EnsureGangOpsSettings(channel);
		float num = Mathf.Max(0f, pactOpsSettings.WarHeatDecayPerWeek);
		Dictionary<string, WarHeatEntry> warHeatStore = GetWarHeatStore(channel);
		if (warHeatStore.Count == 0 || num <= 0f)
		{
			_lastGangOpsWarHeatDecayDay[channel] = nowDay;
			return;
		}
		List<string> list = new List<string>();
		foreach (KeyValuePair<string, WarHeatEntry> item in warHeatStore)
		{
			WarHeatEntry value = item.Value;
			if (value == null)
			{
				list.Add(item.Key);
				continue;
			}
			value.Heat = Mathf.Clamp(value.Heat - num, 0f, 100f);
			value.LastUpdatedDay = nowDay;
			if (value.Heat <= 0.001f)
			{
				list.Add(item.Key);
			}
		}
		for (int i = 0; i < list.Count; i++)
		{
			warHeatStore.Remove(list[i]);
		}
		_lastGangOpsWarHeatDecayDay[channel] = nowDay;
		VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.WarHeat", $"decay day={nowDay} amount={num:0.0} entries={warHeatStore.Count}");
	}

	internal static void DecayWarHeat(int nowDay)
	{
		DecayWarHeat(GangOpsChannel.Pact, nowDay);
	}

	private static bool IsRuntimeGangAttackCrewAvailable(PlayerInfo owner, CrewAssignment crew)
	{
		if (!IsRuntimeGangCrewBaseAvailable(owner, crew))
		{
			return false;
		}
		if (TurnUpdatePatch.IsCrewReservedForPendingAiHumanRobberyMeeting(owner, crew))
		{
			VerificationLog("PactRetaliation", $"runtime-attack-skip-robbery-meeting attacker={owner.PID.id} peep={crew.peepId.id} vehicle={(crew.VehicleID.IsValid ? crew.VehicleID.id : 0UL)}");
			return false;
		}
		if (crew.IsInVehicle
			&& crew.VehicleID.IsValid
			&& !MultiCrewVehicleHelper.IsDriver(owner.crew, crew))
		{
			VerificationLog("PactRetaliation", $"runtime-attack-skip-non-driver attacker={owner.PID.id} peep={crew.peepId.id} vehicle={crew.VehicleID.id}");
			return false;
		}
		return true;
	}

	private static bool IsRuntimeGangCrewBaseAvailable(PlayerInfo owner, CrewAssignment crew)
	{
		if (owner?.crew == null || !crew.IsValid || !crew.peepId.IsValid)
		{
			return false;
		}
		if (IsCrewHiddenOrHideoutPending(crew.peepId) || JailSystem.IsInJail(crew.peepId) || !owner.crew.IsOnBoard(crew.peepId))
		{
			return false;
		}
		Entity peep = crew.GetPeep();
		return peep?.data?.person != null && peep.data.person.IsAlive;
	}

	private static bool TryResolveRuntimeFrontActionCrew(PlayerInfo owner, CrewAssignment candidate, out CrewAssignment actionCrew, out string reason)
	{
		actionCrew = CrewAssignment.EMPTY;
		reason = "invalid";
		if (!IsRuntimeGangCrewBaseAvailable(owner, candidate))
		{
			reason = "base-unavailable";
			return false;
		}
		if (!candidate.IsInVehicle || !candidate.VehicleID.IsValid)
		{
			actionCrew = candidate;
			reason = "on-foot";
			return true;
		}
		if (MultiCrewVehicleHelper.IsDriver(owner.crew, candidate))
		{
			actionCrew = candidate;
			reason = "driver";
			return true;
		}

		EntityID driverPeepId = MultiCrewVehicleHelper.GetDriverPeepId(owner.crew, candidate.VehicleID);
		CrewAssignment driverCrew = driverPeepId.IsValid ? owner.crew.GetCrewForPeep(driverPeepId) : CrewAssignment.EMPTY;
		if (driverCrew.IsValid
			&& driverCrew.VehicleID == candidate.VehicleID
			&& IsRuntimeGangCrewBaseAvailable(owner, driverCrew))
		{
			actionCrew = driverCrew;
			reason = "passenger-promoted-to-driver";
			return true;
		}

		reason = "no-live-driver";
		return false;
	}

	private static Entity TryResolveRuntimeGangAttackTarget(PlayerInfo defender, EntityID preferredPeepId)
	{
		if (defender?.crew == null || preferredPeepId.IsNotValid || IsCrewHiddenOrHideoutPending(preferredPeepId) || JailSystem.IsInJail(preferredPeepId) || !defender.crew.IsOnBoard(preferredPeepId))
		{
			return null;
		}
		try
		{
			Entity peep = preferredPeepId.FindEntity();
			if (peep?.data?.person != null && peep.data.person.IsAlive)
			{
				return peep;
			}
		}
		catch
		{
		}
		return null;
	}

	private static Entity FindRuntimeGangAttackTarget(PlayerInfo defender, EntityID preferredPeepId)
	{
		if (defender?.crew == null)
		{
			return null;
		}
		Entity entity = TryResolveRuntimeGangAttackTarget(defender, preferredPeepId);
		if (entity != null)
		{
			return entity;
		}

		try
		{
			EntityID bossPeepId = defender.social != null ? defender.social.PlayerPeepId : EntityID.INVALID;
			Entity boss = bossPeepId.IsValid ? bossPeepId.FindEntity() : null;
			if (boss?.data?.person != null && boss.data.person.IsAlive && !JailSystem.IsInJail(boss.Id) && !IsCrewHiddenOrHideoutPending(boss.Id) && defender.crew.IsOnBoard(boss.Id))
			{
				return boss;
			}
		}
		catch
		{
		}

		return defender.crew.GetLiving()
			.Where(item => IsRuntimeGangAttackCrewAvailable(defender, item))
			.Select(item => item.GetPeep())
			.FirstOrDefault(peep => peep?.data?.person != null && peep.data.person.IsAlive);
	}

	private const float RuntimeGangAttackRetreatHealthFraction = 0.35f;

	private const int RuntimeGangAttackApproachRetryDelayDays = 8;

	private static int GetRuntimeGangAttackApproachRetryDueDay(int nowDay)
	{
		return nowDay + RuntimeGangAttackApproachRetryDelayDays;
	}

	private static bool ShouldRuntimeGangAttackerRetreat(PlayerInfo owner, CrewAssignment crew, out float healthFraction)
	{
		healthFraction = 1f;
		if (owner?.crew == null || !crew.IsValid || !crew.peepId.IsValid)
		{
			return false;
		}
		try
		{
			Entity peep = crew.GetPeep();
			if (peep?.components?.agent == null || !peep.components.agent.HasHealthPointsLeft)
			{
				return false;
			}
			healthFraction = peep.components.agent.CurrentHealthAsFraction;
			return peep.components.agent.IsWounded && healthFraction <= RuntimeGangAttackRetreatHealthFraction;
		}
		catch
		{
			healthFraction = 1f;
			return false;
		}
	}

	private static bool TryResolveRuntimeGangRecoveryNode(PlayerInfo owner, out Node node)
	{
		node = null;
		if (owner?.territory == null)
		{
			return false;
		}
		try
		{
			EntityID recoveryBuildingId = owner.territory.Safehouse.IsValid
				? owner.territory.Safehouse
				: owner.territory.Station;
			Entity recoveryBuilding = recoveryBuildingId.IsValid ? recoveryBuildingId.FindEntity() : null;
			NodeID nodeId = recoveryBuilding?.data?.board?.bead.nodeId ?? NodeID.INVALID;
			if (nodeId.IsValid)
			{
				node = nodeId.FindNode();
				return node != null;
			}

			node = owner.territory.GetHeadquartersNode(ignoreWarnings: true);
			return node != null;
		}
		catch
		{
			node = null;
			return false;
		}
	}

	private static bool TryQueueRuntimeGangRetreat(PlayerInfo owner, CrewAssignment crew, string sourceTag, float healthFraction)
	{
		if (owner?.commands == null || !crew.IsValid || !crew.peepId.IsValid || !TryResolveRuntimeGangRecoveryNode(owner, out Node recoveryNode) || recoveryNode?.id.IsValid != true)
		{
			return false;
		}
		try
		{
			Entity peep = crew.GetPeep();
			NodeID currentNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
			owner.commands.FlushQueue(crew.peepId, cancelActive: true);
			CommandHeal heal = new CommandHeal(owner.PID, crew.peepId);
			if (currentNodeId.IsValid && currentNodeId == recoveryNode.id)
			{
				owner.commands.AddCommandImmediate(heal);
			}
			else
			{
				owner.commands.AddCommandImmediate(new CommandGoto(owner.PID, crew.peepId, recoveryNode), heal);
			}
			VerificationLog("PactRetaliation", $"runtime-retreat attacker={owner.PID.id} peep={crew.peepId.id} health={healthFraction:0.00} recoveryNode={recoveryNode.id} source={sourceTag}");
			return true;
		}
		catch (Exception ex)
		{
			Debug.LogWarning($"[GameplayTweaks] Runtime gang retreat failed attacker={owner.PID.id} peep={crew.peepId.id} source={sourceTag}: {ex.Message}");
			return false;
		}
	}

	private static bool TryResolveRuntimeGangAttackTargetNode(PlayerInfo defender, Entity targetPeep, out Node targetNode, out string source)
	{
		targetNode = null;
		source = "none";
		if (targetPeep?.data?.agent == null)
		{
			return false;
		}
		try
		{
			if (defender?.PID.IsHumanPlayer == true)
			{
				CrewAssignment targetCrew = defender.crew.GetCrewForPeep(targetPeep.Id);
				if (targetCrew.IsValid
					&& targetCrew.IsInVehicle
					&& targetCrew.VehicleID.IsValid
					&& MultiCrewVehicleHelper.TryGetHumanVehicleCombatTargetNodeId(targetCrew.VehicleID, out NodeID routeNodeId, out source)
					&& routeNodeId.IsValid)
				{
					targetNode = routeNodeId.FindNode();
					if (targetNode != null)
					{
						return true;
					}
				}
			}

			NodeID liveNodeId = targetPeep.data.agent.nid;
			if (liveNodeId.IsValid)
			{
				targetNode = liveNodeId.FindNode();
				source = "live-agent";
				return targetNode != null;
			}
		}
		catch
		{
			targetNode = null;
			source = "none";
		}
		return false;
	}

	private enum RuntimeGangAttackQueueResult
	{
		None,
		Approach,
		Attack
	}

	private static RuntimeGangAttackQueueResult TryQueueRuntimeGangAttack(PlayerInfo attacker, PlayerInfo defender, CrewAssignment crew, Entity targetPeep, Node targetNode, string targetNodeSource, string sourceTag)
	{
		if (attacker?.commands == null || !crew.IsValid || !crew.peepId.IsValid || targetPeep == null || targetNode?.id.IsValid != true)
		{
			return RuntimeGangAttackQueueResult.None;
		}
		try
		{
			Entity peep = crew.GetPeep();
			NodeID currentNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
			CommandAttack attack = new CommandAttack(attacker.PID, crew.peepId, targetPeep.Id);
			if (currentNodeId.IsValid && currentNodeId == targetNode.id)
			{
				attacker.commands.FlushQueue(crew.peepId, cancelActive: true);
				attacker.commands.AddCommandImmediate(attack);
				VerificationLog("PactRetaliation", $"runtime-attack-queued attacker={attacker.PID.id} defender={defender?.PID.id ?? -1} peep={crew.peepId.id} target={targetPeep.Id.id} targetNode={targetNode.id} targetSource={targetNodeSource} source={sourceTag} mode=attack-now");
				return RuntimeGangAttackQueueResult.Attack;
			}
			else if (TryBuildRuntimeSameTurnRoute(attacker.PID, peep, targetNode, out PathData path, out string routeReason))
			{
				attacker.commands.FlushQueue(crew.peepId, cancelActive: true);
				attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, crew.peepId, targetNode), attack);
				VerificationLog("PactRetaliation", $"runtime-attack-queued attacker={attacker.PID.id} defender={defender?.PID.id ?? -1} peep={crew.peepId.id} target={targetPeep.Id.id} targetNode={targetNode.id} targetSource={targetNodeSource} source={sourceTag} mode=goto-attack-now reason={routeReason} cost={path.cost}");
				return RuntimeGangAttackQueueResult.Attack;
			}
			else if (TryBuildRuntimeApproachRoute(attacker.PID, peep, targetNode, out PathData approachPath, out string approachReason))
			{
				attacker.commands.FlushQueue(crew.peepId, cancelActive: true);
				attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, crew.peepId, targetNode));
				VerificationLog("PactRetaliation", $"runtime-attack-approach-queued attacker={attacker.PID.id} defender={defender?.PID.id ?? -1} peep={crew.peepId.id} target={targetPeep.Id.id} targetNode={targetNode.id} targetSource={targetNodeSource} source={sourceTag} mode=goto-only reason={approachReason} cost={approachPath.cost}");
				return RuntimeGangAttackQueueResult.Approach;
			}
			else
			{
				VerificationLog("PactRetaliation", $"runtime-attack-not-queued attacker={attacker.PID.id} defender={defender?.PID.id ?? -1} peep={crew.peepId.id} target={targetPeep.Id.id} targetNode={targetNode.id} targetSource={targetNodeSource} source={sourceTag} reason={routeReason}");
				return RuntimeGangAttackQueueResult.None;
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning($"[GameplayTweaks] Runtime gang attack queue failed attacker={attacker.PID.id} defender={defender?.PID.id ?? -1} peep={crew.peepId.id} source={sourceTag}: {ex.Message}");
			return RuntimeGangAttackQueueResult.None;
		}
	}

	private static bool TryBuildRuntimeApproachRoute(PlayerID pid, Entity peep, Node targetNode, out PathData path, out string reason)
	{
		path = null;
		reason = "none";
		try
		{
			if (peep?.components?.agent == null || targetNode == null || !targetNode.id.IsValid)
			{
				reason = "missing-route-context";
				return false;
			}

			int movesRemaining = peep.components.agent.MovesRemaining;
			if (movesRemaining <= 0)
			{
				reason = "no-moves";
				return false;
			}

			path = CommandGoto.MakePath(pid, peep, targetNode, new Fixnum(movesRemaining));
			if (path == null || path.world == null || path.world.Count <= 1 || path.nodes == null || path.nodes.Count == 0)
			{
				reason = $"no-path-within-moves moves={movesRemaining}";
				return false;
			}

			NodeID lastNodeId = path.nodes.LastOrDefault()?.node?.id ?? NodeID.INVALID;
			if (!lastNodeId.IsValid || path.cost <= 0)
			{
				reason = $"no-approach-progress moves={movesRemaining} cost={path.cost} lastNode={lastNodeId}";
				return false;
			}

			reason = $"approach-only moves={movesRemaining} cost={path.cost} lastNode={lastNodeId}";
			return true;
		}
		catch (Exception ex)
		{
			reason = "approach-check-failed-" + ex.GetType().Name;
			return false;
		}
	}

	private static bool TryBuildRuntimeFrontApproachRoute(PlayerID pid, Entity peep, Node targetNode, out PathData path, out string reason)
	{
		if (TryBuildRuntimeApproachRoute(pid, peep, targetNode, out path, out reason))
		{
			return true;
		}
		try
		{
			if (peep?.components?.agent == null || targetNode == null || !targetNode.id.IsValid)
			{
				reason = "missing-route-context";
				return false;
			}
			var points = peep.components.agent.GetMovesAndActionsPerTurn();
			int nextMoves = Mathf.Max(peep.components.agent.MovesRemaining, points.moves);
			if (nextMoves <= 0)
			{
				reason = "no-next-turn-moves";
				return false;
			}
			path = CommandGoto.MakePath(pid, peep, targetNode, new Fixnum(nextMoves));
			if (path == null || path.world == null || path.world.Count <= 1 || path.nodes == null || path.nodes.Count == 0)
			{
				reason = $"no-path-next-turn moves={nextMoves}";
				return false;
			}
			NodeID lastNodeId = path.nodes.LastOrDefault()?.node?.id ?? NodeID.INVALID;
			if (!lastNodeId.IsValid || path.cost <= 0)
			{
				reason = $"no-next-turn-approach-progress moves={nextMoves} cost={path.cost} lastNode={lastNodeId}";
				return false;
			}
			reason = $"next-turn-approach moves={nextMoves} cost={path.cost} lastNode={lastNodeId}";
			return true;
		}
		catch (Exception ex)
		{
			reason = "next-turn-approach-check-failed-" + ex.GetType().Name;
			path = null;
			return false;
		}
	}

	private static bool TryBuildRuntimeFrontReachableNextRoute(PlayerID pid, Entity peep, Node targetNode, out PathData path, out string reason)
	{
		path = null;
		reason = "none";
		try
		{
			if (peep?.components?.agent == null || targetNode == null || !targetNode.id.IsValid)
			{
				reason = "missing-route-context";
				return false;
			}
			var points = peep.components.agent.GetMovesAndActionsPerTurn();
			int nextMoves = Mathf.Max(peep.components.agent.MovesRemaining, points.moves);
			if (nextMoves <= 0)
			{
				reason = "no-next-turn-moves";
				return false;
			}
			path = CommandGoto.MakePath(pid, peep, targetNode, new Fixnum(nextMoves));
			if (path == null || path.world == null || path.world.Count <= 1 || path.nodes == null || path.nodes.Count == 0)
			{
				reason = $"no-path-next-turn moves={nextMoves}";
				return false;
			}
			NodeID lastNodeId = path.nodes.LastOrDefault()?.node?.id ?? NodeID.INVALID;
			if (lastNodeId == targetNode.id && path.cost <= nextMoves)
			{
				reason = $"reachable-next-turn moves={nextMoves} cost={path.cost} lastNode={lastNodeId}";
				return true;
			}
			reason = $"not-reachable-next-turn moves={nextMoves} cost={path.cost} lastNode={lastNodeId}";
			return false;
		}
		catch (Exception ex)
		{
			reason = "reachable-next-turn-check-failed-" + ex.GetType().Name;
			path = null;
			return false;
		}
	}

	private static Node ResolveFrontRouteCommandNode(Node finalTargetNode, PathData path, bool allowSegmentTarget, out NodeID routeNodeId, out string routeGoalMode)
	{
		routeNodeId = finalTargetNode?.id ?? NodeID.INVALID;
		routeGoalMode = "target";
		if (!allowSegmentTarget || finalTargetNode?.id.IsValid != true || path?.nodes == null || path.nodes.Count == 0)
		{
			return finalTargetNode;
		}
		Node segmentNode = path.nodes.LastOrDefault()?.node;
		if (segmentNode?.id.IsValid == true && segmentNode.id != finalTargetNode.id)
		{
			routeNodeId = segmentNode.id;
			routeGoalMode = "approach-segment";
			return segmentNode;
		}
		return finalTargetNode;
	}

	private static void MarkPendingRetaliationRouteTarget(PendingRetaliationFrontTicker entry, NodeID routeNodeId, NodeID finalTargetNodeId, NodeID issuedFromNodeId)
	{
		if (entry == null)
		{
			return;
		}
		entry.DelayedRouteTargetNodeId = routeNodeId;
		entry.DelayedFinalRouteIssuedFromNodeId = routeNodeId.IsValid
			&& finalTargetNodeId.IsValid
			&& routeNodeId == finalTargetNodeId
			&& issuedFromNodeId.IsValid
			? issuedFromNodeId
			: NodeID.INVALID;
	}

	private static bool HasPendingRetaliationFinalRouteProgress(PendingRetaliationFrontTicker entry, NodeID currentNodeId, NodeID finalTargetNodeId)
	{
		return entry != null
			&& currentNodeId.IsValid
			&& finalTargetNodeId.IsValid
			&& entry.DelayedFinalRouteIssuedFromNodeId.IsValid
			&& entry.DelayedRouteTargetNodeId == finalTargetNodeId
			&& currentNodeId != entry.DelayedFinalRouteIssuedFromNodeId;
	}

	private static bool ShouldAllowDelayedHumanFrontSegmentTarget(PendingRetaliationFrontTicker entry)
	{
		return entry == null
			|| (!entry.DelayedFinalApproachGraceGranted
				&& !entry.DelayedTerminalReassignmentGranted
				&& entry.DelayedRouteRequeueCount < RETALIATION_FRONT_DELAYED_ACTION_SEGMENT_TARGET_MAX_REQUEUES);
	}

	private static bool ShouldCommitDelayedHumanFrontRoute(PendingRetaliationFrontTicker entry, int waitedDays)
	{
		return entry != null
			&& entry.DefenderPid.IsHumanPlayer
			&& string.Equals(GetPendingRetaliationTargetKind(entry), "outpost", StringComparison.Ordinal)
			&& (entry.DelayedRouteRequeueCount >= RETALIATION_FRONT_DELAYED_ACTION_HUMAN_ROUTE_COMMIT_REQUEUES
				|| waitedDays >= RETALIATION_FRONT_DELAYED_ACTION_HUMAN_ROUTE_COMMIT_DAYS);
	}

	private static bool IsActivePendingHumanOutpostFront(PendingRetaliationFrontTicker entry, PlayerID defenderPid)
	{
		if (entry == null || !defenderPid.IsHumanPlayer || entry.DefenderPid != defenderPid || entry.BuildingId.IsNotValid)
		{
			return false;
		}
		if (entry.DelayedPhysicalActionAbandoned || IsPendingRetaliationForcedBusinessClosureMode(entry.Mode))
		{
			return false;
		}
		if (!string.Equals(GetPendingRetaliationTargetKind(entry), "outpost", StringComparison.Ordinal))
		{
			return false;
		}
		Entity building = entry.BuildingId.FindEntity();
		return building?.data?.building != null && building.data.building.outpost == defenderPid;
	}

	private static bool IsActivePendingHumanRetaliationAction(PendingRetaliationFrontTicker entry, PlayerID defenderPid)
	{
		if (entry == null || !defenderPid.IsHumanPlayer || entry.DefenderPid != defenderPid || entry.BuildingId.IsNotValid || entry.DelayedPhysicalActionAbandoned)
		{
			return false;
		}
		Entity building = entry.BuildingId.FindEntity();
		if (building?.data?.building == null)
		{
			return false;
		}
		if (IsPendingRetaliationForcedBusinessClosureMode(entry.Mode))
		{
			return true;
		}
		return string.Equals(GetPendingRetaliationTargetKind(entry), "outpost", StringComparison.Ordinal)
			&& building.data.building.outpost == defenderPid;
	}

	private static string GetPendingRetaliationActionKind(PendingRetaliationFrontTicker entry)
	{
		if (entry == null)
		{
			return "unknown";
		}
		if (IsPendingRetaliationForcedBusinessClosureMode(entry.Mode))
		{
			return "business-closure";
		}
		return GetPendingRetaliationTargetKind(entry);
	}

	private static bool IsCrewAssignedToOtherPendingRetaliationAction(PlayerID attackerPid, EntityID crewPeepId, EntityID allowedBuildingId, out PendingRetaliationFrontTicker pending)
	{
		pending = null;
		if (attackerPid.IsNotAnyPlayer || crewPeepId.IsNotValid)
		{
			return false;
		}
		foreach (PendingRetaliationFrontTicker entry in _pendingRetaliationFrontTickersByBuilding.Values)
		{
			if (entry == null || entry.AttackerPid != attackerPid || entry.CrewPeepId != crewPeepId || entry.DelayedPhysicalActionAbandoned || entry.BuildingId.IsNotValid)
			{
				continue;
			}
			if (allowedBuildingId.IsValid && entry.BuildingId == allowedBuildingId)
			{
				continue;
			}
			pending = entry;
			return true;
		}
		return false;
	}

	private static HashSet<ulong> GetOccupiedRetaliationVehicleIds(PlayerInfo attacker)
	{
		HashSet<ulong> occupiedVehicleIds = new HashSet<ulong>();
		if (attacker?.crew == null)
		{
			return occupiedVehicleIds;
		}
		try
		{
			foreach (CrewAssignment crew in attacker.crew.GetLiving())
			{
				if (!crew.IsValid
					|| !crew.IsInVehicle
					|| crew.VehicleID.IsNotValid
					|| crew.VehicleID.FindEntity() == null
					|| MultiCrewVehicleHelper.IsAmbientTrafficVehicle(crew.VehicleID))
				{
					continue;
				}
				occupiedVehicleIds.Add(crew.VehicleID.id);
			}
		}
		catch
		{
		}
		return occupiedVehicleIds;
	}

	private static int GetPendingRetaliationActionUsage(PlayerInfo attacker, out HashSet<ulong> reservedVehicleIds)
	{
		reservedVehicleIds = new HashSet<ulong>();
		if (attacker?.crew == null || attacker.PID.IsNotAnyPlayer)
		{
			return 0;
		}
		int pendingActionCount = 0;
		try
		{
			foreach (PendingRetaliationFrontTicker entry in _pendingRetaliationFrontTickersByBuilding.Values)
			{
				if (entry == null
					|| entry.AttackerPid != attacker.PID
					|| entry.BuildingId.IsNotValid
					|| entry.DelayedPhysicalActionAbandoned
					|| entry.BuildingId.FindEntity() == null)
				{
					continue;
				}
				pendingActionCount++;
				CrewAssignment pendingCrew = attacker.crew.GetCrewForPeep(entry.CrewPeepId);
				if (pendingCrew.IsValid && pendingCrew.IsInVehicle && pendingCrew.VehicleID.IsValid)
				{
					reservedVehicleIds.Add(pendingCrew.VehicleID.id);
				}
			}
			pendingActionCount += TurnUpdatePatch.AddPendingAiHumanRobberyMeetingReservations(attacker, reservedVehicleIds);
		}
		catch
		{
		}
		return pendingActionCount;
	}

	private static bool TryGetActiveConvoInitiative(PlayerInfo owner, out NodeID meetingPoint, out string topic, out bool needsPeep)
	{
		meetingPoint = NodeID.INVALID;
		topic = "none";
		needsPeep = false;
		try
		{
			ConvoInitiative initiative = owner?.ai?.social?.GetConvoInitiativeUnsafe();
			if (initiative == null || !initiative.IsValid || initiative.IsExpired)
			{
				return false;
			}
			meetingPoint = initiative.meetingPoint;
			topic = initiative.topic.ToString();
			needsPeep = initiative.NeedToSendPeep();
			return true;
		}
		catch
		{
			return false;
		}
	}

	private static int GetRetaliationConvoInitiativeVehicleReserve(PlayerInfo attacker, out NodeID meetingPoint, out string topic, out bool needsPeep)
	{
		if (TryGetActiveConvoInitiative(attacker, out meetingPoint, out topic, out needsPeep))
		{
			return RETALIATION_CONVO_INITIATIVE_VEHICLE_RESERVE;
		}
		return 0;
	}

	private static bool HasActiveConvoMeetingCommand(PlayerInfo owner, EntityID peepId, out string commandTag)
	{
		commandTag = "none";
		if (owner?.commands == null || peepId.IsNotValid)
		{
			return false;
		}
		try
		{
			foreach (Command command in owner.commands.EnumerateCommands(peepId))
			{
				if (command == null)
				{
					continue;
				}
				string typeName = command.GetType().Name;
				if (command.type == CommandType.WaitAtMeetingPoint
					|| typeName.IndexOf("WaitAtMeetingPoint", StringComparison.OrdinalIgnoreCase) >= 0)
				{
					commandTag = string.IsNullOrEmpty(typeName) ? command.type.ToString() : typeName;
					return true;
				}
			}
		}
		catch
		{
		}
		return false;
	}

	private static bool IsRetaliationConvoInitiativeCrewReserved(PlayerInfo attacker, CrewAssignment crew, out string reason, out NodeID meetingPoint, out string topic, out bool needsPeep)
	{
		reason = "none";
		meetingPoint = NodeID.INVALID;
		topic = "none";
		needsPeep = false;
		if (!crew.IsValid || crew.peepId.IsNotValid)
		{
			return false;
		}
		if (!TryGetActiveConvoInitiative(attacker, out meetingPoint, out topic, out needsPeep))
		{
			return false;
		}
		if (HasActiveConvoMeetingCommand(attacker, crew.peepId, out string commandTag))
		{
			reason = "meeting-command:" + commandTag;
			return true;
		}
		if (needsPeep && attacker?.commands?.PeepHasTask(crew.peepId) == true)
		{
			reason = "busy-while-convo-unsent";
			return true;
		}
		return false;
	}

	private static int GetRetaliationActionCapacity(PlayerInfo attacker, out int occupiedVehicleCount, out int pendingActionCount, out HashSet<ulong> reservedVehicleIds)
	{
		HashSet<ulong> occupiedVehicleIds = GetOccupiedRetaliationVehicleIds(attacker);
		occupiedVehicleCount = occupiedVehicleIds.Count;
		pendingActionCount = GetPendingRetaliationActionUsage(attacker, out reservedVehicleIds);
		int convoReserve = GetRetaliationConvoInitiativeVehicleReserve(attacker, out _, out _, out _);
		return Mathf.Max(0, occupiedVehicleCount - RETALIATION_NORMAL_DUTY_VEHICLE_RESERVE - convoReserve);
	}

	private static bool IsRetaliationVehicleAvailableForNewAction(PlayerInfo attacker, EntityID vehicleId, ISet<ulong> reservedVehicleIds)
	{
		if (attacker?.crew == null
			|| vehicleId.IsNotValid
			|| vehicleId.FindEntity() == null
			|| MultiCrewVehicleHelper.IsAmbientTrafficVehicle(vehicleId)
			|| (reservedVehicleIds != null && reservedVehicleIds.Contains(vehicleId.id)))
		{
			return false;
		}
		return true;
	}

	private static int GetRetaliationVehicleActiveTaskCount(PlayerInfo attacker, EntityID vehicleId)
	{
		if (attacker?.crew == null || attacker.commands == null || vehicleId.IsNotValid)
		{
			return 0;
		}
		int taskCount = 0;
		try
		{
			foreach (CrewAssignment occupant in attacker.crew.GetLiving())
			{
				if (occupant.IsValid
					&& occupant.IsInVehicle
					&& occupant.VehicleID == vehicleId
					&& attacker.commands.PeepHasTask(occupant.peepId))
				{
					taskCount++;
				}
			}
		}
		catch
		{
		}
		return taskCount;
	}

	private static bool TryFindActivePendingHumanRetaliationAction(PlayerInfo defender, out PendingRetaliationFrontTicker pending)
	{
		pending = null;
		if (defender?.PID.IsHumanPlayer != true)
		{
			return false;
		}
		pending = _pendingRetaliationFrontTickersByBuilding.Values
			.Where(entry => IsActivePendingHumanRetaliationAction(entry, defender.PID))
			.OrderBy(entry => entry.QueuedDay)
			.ThenBy(entry => entry.BuildingId.id)
			.FirstOrDefault();
		return pending != null;
	}

	private static bool TryBlockNewHumanFrontTargetForExistingPending(PlayerInfo attacker, PlayerInfo defender, Entity requestedBuilding, string targetKind, string sourceTag, out string actionSummary)
	{
		actionSummary = "front-action:none";
		if (!string.Equals(targetKind, "outpost", StringComparison.Ordinal) || defender?.PID.IsHumanPlayer != true)
		{
			return false;
		}
		int capacity = GetRetaliationActionCapacity(attacker, out int occupiedVehicles, out int pendingActions, out _);
		if (pendingActions < capacity)
		{
			return false;
		}
		actionSummary = $"front-capacity-blocked:{pendingActions}/{capacity}";
		VerificationLog("GangOps.FrontMovement", $"front-capacity-blocked attacker={attacker?.PID.id ?? 0} defender={defender.PID.id} requestedBuilding={requestedBuilding?.Id.id ?? 0UL} requestedTargetNode={requestedBuilding?.data?.board?.bead.nodeId ?? NodeID.INVALID} pendingActions={pendingActions} capacity={capacity} occupiedVehicles={occupiedVehicles} normalDutyReserve={RETALIATION_NORMAL_DUTY_VEHICLE_RESERVE} source={sourceTag}");
		return true;
	}

	private static bool TryResolvePendingRetaliationOutpostClosureByRouteCommitment(PendingRetaliationFrontTicker entry, PlayerInfo attacker, PlayerInfo defender, CrewAssignment crew, Entity building, Node targetNode, NodeID currentNodeId, string currentNodeSource, int waitedDays, string sourceTag)
	{
		if (!ShouldCommitDelayedHumanFrontRoute(entry, waitedDays))
		{
			return false;
		}
		try
		{
			if (targetNode?.id.IsValid != true)
			{
				return false;
			}
			Entity peep = crew.GetPeep();
			NodeID peepNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
			if (currentNodeId == targetNode.id || peepNodeId == targetNode.id)
			{
				return TryResolvePendingRetaliationOutpostClosureAtTarget(entry, attacker, defender, crew, building, targetNode.id, currentNodeId == targetNode.id ? currentNodeSource : "route-commitment-agent-at-target", sourceTag, "route-commitment-outpost-steal", "route-commitment-rival-blocking");
			}
			bool continuingFinalApproach = entry.DelayedFinalRouteIssuedFromNodeId.IsValid
				&& entry.DelayedRouteTargetNodeId == targetNode.id;
			bool madeFinalApproachProgress = HasPendingRetaliationFinalRouteProgress(entry, currentNodeId, targetNode.id);
			if (madeFinalApproachProgress)
			{
				entry.DelayedFinalApproachProgressObserved = true;
			}
			bool stalledFinalApproach = continuingFinalApproach
				&& currentNodeId.IsValid
				&& currentNodeId == entry.DelayedFinalRouteIssuedFromNodeId;
			bool routeLimitReached = entry.DelayedRouteRequeueCount >= RETALIATION_FRONT_DELAYED_ACTION_HUMAN_MAX_REQUEUES
				&& !madeFinalApproachProgress;
			bool waitLimitReached = waitedDays >= RETALIATION_FRONT_DELAYED_ACTION_MOVING_GIVE_UP_DAYS;
			if ((routeLimitReached || waitLimitReached)
				&& waitLimitReached
				&& !routeLimitReached
				&& !entry.DelayedFinalApproachGraceGranted
				&& TryBuildRuntimeFrontReachableNextRoute(attacker.PID, peep, targetNode, out PathData gracePath, out string graceReason))
			{
				if (attacker?.commands != null && entry.CrewPeepId.IsValid)
				{
					attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
					attacker.commands.AddCommand(new CommandGoto(attacker.PID, entry.CrewPeepId, targetNode));
				}
				entry.Mode = "front-steal-route-commitment-final-approach-grace";
				entry.DelayedRouteTargetNodeId = targetNode.id;
				entry.DelayedRouteLastIssuedDay = G.GetNow().days;
				entry.DelayedFinalRouteIssuedFromNodeId = currentNodeId;
				entry.DelayedRouteRequeueCount++;
				entry.DelayedFinalApproachGraceGranted = true;
				VerificationLog("GangOps.FrontMovement", $"front-route-commitment-final-approach-grace attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} requeues={entry.DelayedRouteRequeueCount} route={graceReason} cost={gracePath.cost} graceTurns=1 source={sourceTag}");
				return true;
			}
			if (routeLimitReached
				&& !waitLimitReached
				&& !entry.DelayedFinalApproachGraceGranted
				&& TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, targetNode, out PathData routeLimitPath, out string routeLimitReason))
			{
				if (attacker?.commands != null && entry.CrewPeepId.IsValid)
				{
					attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
					attacker.commands.AddCommand(new CommandGoto(attacker.PID, entry.CrewPeepId, targetNode));
				}
				int oldRequeues = entry.DelayedRouteRequeueCount;
				entry.Mode = "front-steal-route-commitment-requeue-limit-grace";
				entry.DelayedRouteTargetNodeId = targetNode.id;
				entry.DelayedRouteLastIssuedDay = G.GetNow().days;
				entry.DelayedFinalRouteIssuedFromNodeId = currentNodeId;
				entry.DelayedRouteRequeueCount = Mathf.Min(entry.DelayedRouteRequeueCount, RETALIATION_FRONT_DELAYED_ACTION_HUMAN_ROUTE_COMMIT_REQUEUES);
				entry.DelayedNoProgressChecks = 0;
				entry.DelayedFinalApproachGraceGranted = true;
				VerificationLog("GangOps.FrontMovement", $"front-route-commitment-requeue-limit-grace attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} oldRequeues={oldRequeues} requeues={entry.DelayedRouteRequeueCount} maxRequeues={RETALIATION_FRONT_DELAYED_ACTION_HUMAN_MAX_REQUEUES} maxWaitDays={RETALIATION_FRONT_DELAYED_ACTION_MOVING_GIVE_UP_DAYS} route={routeLimitReason} cost={routeLimitPath.cost} source={sourceTag}");
				return true;
			}
			if (routeLimitReached || waitLimitReached)
			{
				return false;
			}
			int nowDay = G.GetNow().days;
			bool finalRouteStillQueued = entry.DelayedRouteTargetNodeId == targetNode.id
				&& entry.DelayedRouteLastIssuedDay != int.MinValue
				&& nowDay - entry.DelayedRouteLastIssuedDay < RETALIATION_FRONT_DELAYED_ACTION_REQUEUE_COOLDOWN_DAYS
				&& IsPendingRetaliationFrontActionStillQueued(entry, building);
			if (finalRouteStillQueued)
			{
				return true;
			}
			if (attacker?.commands != null && entry.CrewPeepId.IsValid)
			{
				bool competingTaskCleared = attacker.commands.PeepHasTask(entry.CrewPeepId);
				if (competingTaskCleared)
				{
					attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
				}
				attacker.commands.AddCommand(new CommandGoto(attacker.PID, entry.CrewPeepId, targetNode));
				entry.Mode = "front-steal-route-commitment-final-approach";
				entry.DelayedRouteTargetNodeId = targetNode.id;
				entry.DelayedRouteLastIssuedDay = nowDay;
				entry.DelayedFinalRouteIssuedFromNodeId = currentNodeId;
				bool retryIncremented = !madeFinalApproachProgress;
				if (retryIncremented)
				{
					entry.DelayedRouteRequeueCount++;
				}
				if (madeFinalApproachProgress)
				{
					entry.DelayedNoProgressChecks = 0;
				}
				VerificationLog("GangOps.FrontMovement", $"front-route-commitment-final-approach attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} requeues={entry.DelayedRouteRequeueCount} progressed={madeFinalApproachProgress} stalled={stalledFinalApproach} retryIncremented={retryIncremented} competingTaskCleared={competingTaskCleared} commitRequeues={RETALIATION_FRONT_DELAYED_ACTION_HUMAN_ROUTE_COMMIT_REQUEUES} commitDays={RETALIATION_FRONT_DELAYED_ACTION_HUMAN_ROUTE_COMMIT_DAYS} source={sourceTag}");
				return true;
			}
			return false;
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontMovement", $"front-route-commitment-failed attacker={entry?.AttackerPid.id ?? 0} defender={entry?.DefenderPid.id ?? 0} peep={entry?.CrewPeepId.id ?? 0UL} building={entry?.BuildingId.id ?? 0UL} currentNode={currentNodeId} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static bool TryBuildRuntimeSameTurnRoute(PlayerID pid, Entity peep, Node targetNode, out PathData path, out string reason)
	{
		path = null;
		reason = "none";
		try
		{
			if (peep?.components?.agent == null || targetNode == null || !targetNode.id.IsValid)
			{
				reason = "missing-route-context";
				return false;
			}

			int movesRemaining = peep.components.agent.MovesRemaining;
			if (movesRemaining <= 0)
			{
				reason = "no-moves";
				return false;
			}

			path = CommandGoto.MakePath(pid, peep, targetNode, new Fixnum(movesRemaining));
			if (path == null || path.world == null || path.world.Count <= 1 || path.nodes == null || path.nodes.Count == 0)
			{
				reason = $"no-path-within-moves moves={movesRemaining}";
				return false;
			}

			NodeID lastNodeId = path.nodes.LastOrDefault()?.node?.id ?? NodeID.INVALID;
			if (lastNodeId == targetNode.id && path.cost <= movesRemaining)
			{
				reason = $"reachable moves={movesRemaining}";
				return true;
			}

			reason = $"insufficient-moves moves={movesRemaining} cost={path.cost} lastNode={lastNodeId}";
			return false;
		}
		catch (Exception ex)
		{
			reason = "route-check-failed-" + ex.GetType().Name;
			return false;
		}
	}

	private static List<CrewAssignment> FindRuntimeGangAttackers(PlayerInfo attacker, int desiredCrewCount, ISet<ulong> excludedPeepIds = null, IEnumerable<CrewAssignment> availableCrew = null)
	{
		if (attacker?.crew == null || desiredCrewCount <= 0)
		{
			return new List<CrewAssignment>();
		}

		return (availableCrew ?? attacker.crew.GetLiving().Where(item => IsRuntimeGangAttackCrewAvailable(attacker, item)))
			.Where(item => excludedPeepIds == null || !excludedPeepIds.Contains(item.peepId.id))
			.Where(item => !ShouldRuntimeGangAttackerRetreat(attacker, item, out _))
			.OrderByDescending(item => item.IsInVehicle)
			.Take(Mathf.Max(1, desiredCrewCount))
			.ToList();
	}

	private sealed class RuntimeFrontActionCrewCandidate
	{
		public CrewAssignment Crew;
		public NodeID NodeId = NodeID.INVALID;
		public string NodeSource = "none";
		public float Distance = float.MaxValue;
		public bool HasNode;
		public bool IsBoss;
		public int ExistingVehicleTaskCount;
		public bool RecentFrontActorUse;
		public string RecentFrontActorUseReason = string.Empty;
	}

	private static bool IsRuntimeFrontActionBoss(PlayerInfo owner, Entity peep)
	{
		if (owner?.social == null || peep == null || peep.Id.IsNotValid)
		{
			return false;
		}
		try
		{
			return owner.social.PlayerPeepId.IsValid && owner.social.PlayerPeepId == peep.Id;
		}
		catch
		{
			return false;
		}
	}

	private static bool TryResolveRuntimeFrontActionCrewNodeQuiet(CrewAssignment crew, Entity peep, out NodeID nodeId, out string nodeSource)
	{
		nodeId = NodeID.INVALID;
		nodeSource = "none";
		try
		{
			if (crew.IsValid && crew.IsInVehicle && crew.VehicleID.IsValid)
			{
				if (MultiCrewVehicleHelper.TryGetStrictPhysicalVehicleNode(crew.VehicleID, out Node vehicleNode, out string vehicleSource)
					&& vehicleNode?.id.IsValid == true)
				{
					nodeId = vehicleNode.id;
					nodeSource = "vehicle-physical-" + (vehicleSource ?? "strict");
					return true;
				}
				NodeID fallbackAgentNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
				if (fallbackAgentNodeId.IsValid)
				{
					nodeId = fallbackAgentNodeId;
					nodeSource = "agent-physical-vehicle-fallback";
					return true;
				}
				return false;
			}

			nodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
			nodeSource = nodeId.IsValid ? "agent-physical" : "none";
			return nodeId.IsValid;
		}
		catch
		{
			nodeId = NodeID.INVALID;
			nodeSource = "none";
			return false;
		}
	}

	private static bool IsRetaliationFrontActorUseReason(string reason)
	{
		return string.Equals(reason, "front-completed", StringComparison.Ordinal)
			|| string.Equals(reason, "command-finished", StringComparison.Ordinal)
			|| string.Equals(reason, "business-closure-completed", StringComparison.Ordinal)
			|| string.Equals(reason, "business-closure-command-finished", StringComparison.Ordinal)
			|| string.Equals(reason, "front-defended", StringComparison.Ordinal)
			|| string.Equals(reason, "attacker-gave-up-too-far", StringComparison.Ordinal);
	}

	private static void PruneExpiredRecentRetaliationFrontActorUses(int nowDay)
	{
		if (_recentRetaliationFrontActorUseByPeep.Count != 0)
		{
			foreach (ulong key in _recentRetaliationFrontActorUseByPeep
				.Where(item => item.Value == null || item.Value.UntilDay < nowDay)
				.Select(item => item.Key)
				.ToList())
			{
				_recentRetaliationFrontActorUseByPeep.Remove(key);
			}
		}
		if (_recentRetaliationFrontActorUseByVehicle.Count != 0)
		{
			foreach (ulong key in _recentRetaliationFrontActorUseByVehicle
				.Where(item => item.Value == null || item.Value.UntilDay < nowDay)
				.Select(item => item.Key)
				.ToList())
			{
				_recentRetaliationFrontActorUseByVehicle.Remove(key);
			}
		}
	}

	private static bool TryGetRecentRetaliationFrontActorUsePenalty(PlayerID attackerPid, CrewAssignment crew, int nowDay, out string reason)
	{
		reason = string.Empty;
		if (attackerPid.IsNotAnyPlayer || !crew.IsValid || crew.peepId.IsNotValid)
		{
			return false;
		}
		PruneExpiredRecentRetaliationFrontActorUses(nowDay);
		RecentRetaliationFrontActorUse actorUse = null;
		if (_recentRetaliationFrontActorUseByPeep.TryGetValue(crew.peepId.id, out RecentRetaliationFrontActorUse peepUse)
			&& peepUse != null
			&& peepUse.AttackerPid == attackerPid.id
			&& peepUse.UntilDay >= nowDay)
		{
			actorUse = peepUse;
		}
		if (actorUse == null
			&& crew.VehicleID.IsValid
			&& _recentRetaliationFrontActorUseByVehicle.TryGetValue(crew.VehicleID.id, out RecentRetaliationFrontActorUse vehicleUse)
			&& vehicleUse != null
			&& vehicleUse.AttackerPid == attackerPid.id
			&& vehicleUse.UntilDay >= nowDay)
		{
			actorUse = vehicleUse;
		}
		if (actorUse == null)
		{
			return false;
		}
		reason = $"{actorUse.Reason ?? "front-action"}:building={actorUse.BuildingId}:until={actorUse.UntilDay}";
		return true;
	}

	private static void MarkRecentRetaliationFrontActorUse(PendingRetaliationFrontTicker entry, string reason, string sourceTag)
	{
		if (entry == null || entry.AttackerPid.IsNotAnyPlayer || entry.CrewPeepId.IsNotValid || !IsRetaliationFrontActorUseReason(reason))
		{
			return;
		}
		try
		{
			int nowDay = G.GetNow().days;
			PruneExpiredRecentRetaliationFrontActorUses(nowDay);
			EntityID vehicleId = EntityID.INVALID;
			try
			{
				PlayerInfo attacker = entry.AttackerPid.FindPlayer();
				CrewAssignment crew = attacker?.crew?.GetCrewForPeep(entry.CrewPeepId) ?? default(CrewAssignment);
				if (crew.IsValid && crew.VehicleID.IsValid)
				{
					vehicleId = crew.VehicleID;
				}
			}
			catch
			{
			}

			RecentRetaliationFrontActorUse actorUse = new RecentRetaliationFrontActorUse
			{
				AttackerPid = entry.AttackerPid.id,
				PeepId = entry.CrewPeepId.id,
				VehicleId = vehicleId.IsValid ? vehicleId.id : 0UL,
				BuildingId = entry.BuildingId.id,
				CreatedDay = nowDay,
				UntilDay = nowDay + RETALIATION_FRONT_ACTOR_REUSE_PENALTY_DAYS,
				Reason = reason ?? "front-action",
				Source = sourceTag
			};
			_recentRetaliationFrontActorUseByPeep[actorUse.PeepId] = actorUse;
			if (actorUse.VehicleId != 0UL)
			{
				_recentRetaliationFrontActorUseByVehicle[actorUse.VehicleId] = actorUse;
			}
			VerificationLog("GangOps.FrontMovement", $"front-actor-reuse-penalty attacker={actorUse.AttackerPid} peep={actorUse.PeepId} vehicle={actorUse.VehicleId} building={actorUse.BuildingId} reason={actorUse.Reason} untilDay={actorUse.UntilDay} duration={RETALIATION_FRONT_ACTOR_REUSE_PENALTY_DAYS} source={sourceTag}");
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontMovement", $"front-actor-reuse-penalty-failed attacker={entry.AttackerPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} reason={reason} error={ex.GetType().Name}:{ex.Message} source={sourceTag}");
		}
	}

	private static CrewAssignment FindRuntimeFrontActionCrew(PlayerInfo attacker, Entity targetBuilding, Node targetNode, string sourceTag, string context, float maxDistance, out bool blockedByDistance, bool allowCapacityOverflow = false)
	{
		blockedByDistance = false;
		if (attacker?.crew == null || targetNode?.id.IsValid != true)
		{
			return default(CrewAssignment);
		}
		int actionCapacity = GetRetaliationActionCapacity(attacker, out int occupiedVehicles, out int pendingActions, out HashSet<ulong> reservedVehicleIds);
		int convoReserve = GetRetaliationConvoInitiativeVehicleReserve(attacker, out NodeID convoMeetingPoint, out string convoTopic, out bool convoNeedsPeep);
		if (pendingActions >= actionCapacity && !allowCapacityOverflow)
		{
			VerificationLog("GangOps.FrontMovement", $"front-crew-selection-capacity-blocked attacker={attacker.PID.id} building={targetBuilding?.Id.id ?? 0UL} targetNode={targetNode.id} pendingActions={pendingActions} capacity={actionCapacity} occupiedVehicles={occupiedVehicles} normalDutyReserve={RETALIATION_NORMAL_DUTY_VEHICLE_RESERVE} convoReserve={convoReserve} convoTopic={convoTopic} convoMeetingNode={convoMeetingPoint} convoNeedsPeep={convoNeedsPeep} capacityOverflowAllowed={allowCapacityOverflow} context={context} source={sourceTag}");
			return default(CrewAssignment);
		}

		int nowDay = G.GetNow().days;
		List<RuntimeFrontActionCrewCandidate> candidates = new List<RuntimeFrontActionCrewCandidate>();
		HashSet<ulong> seenActionCrew = new HashSet<ulong>();
		foreach (CrewAssignment rawCrew in attacker.crew.GetLiving())
		{
			if (!TryResolveRuntimeFrontActionCrew(attacker, rawCrew, out CrewAssignment crew, out _))
			{
				continue;
			}
			if (!crew.IsInVehicle
				|| crew.VehicleID.IsNotValid
				|| !IsRetaliationVehicleAvailableForNewAction(attacker, crew.VehicleID, reservedVehicleIds))
			{
				continue;
			}
			if (!seenActionCrew.Add(crew.peepId.id))
			{
				continue;
			}
			EntityID allowedBuildingId = targetBuilding?.Id ?? EntityID.INVALID;
			if (IsCrewAssignedToOtherPendingRetaliationAction(attacker.PID, crew.peepId, allowedBuildingId, out PendingRetaliationFrontTicker busyPending))
			{
				VerificationLog("GangOps.FrontMovement", $"front-crew-busy-pending-action attacker={attacker.PID.id} peep={crew.peepId.id} busyBuilding={busyPending.BuildingId.id} busyKind={GetPendingRetaliationActionKind(busyPending)} requestedBuilding={targetBuilding?.Id.id ?? 0UL} context={context} source={sourceTag}");
				continue;
			}
			if (ShouldRuntimeGangAttackerRetreat(attacker, crew, out _))
			{
				continue;
			}
			Entity peep = crew.GetPeep();
			if (peep?.data?.person == null || !peep.data.person.IsAlive)
			{
				continue;
			}
			if (IsRetaliationConvoInitiativeCrewReserved(attacker, crew, out string convoReserveReason, out NodeID reservedMeetingPoint, out string reservedTopic, out bool reservedNeedsPeep))
			{
				VerificationLog("GangOps.FrontMovement", $"front-crew-skip-convo-initiative attacker={attacker.PID.id} peep={crew.peepId.id} vehicle={(crew.VehicleID.IsValid ? crew.VehicleID.id : 0UL)} building={targetBuilding?.Id.id ?? 0UL} targetNode={targetNode.id} reason={convoReserveReason} convoTopic={reservedTopic} convoMeetingNode={reservedMeetingPoint} convoNeedsPeep={reservedNeedsPeep} context={context} source={sourceTag}");
				continue;
			}

			RuntimeFrontActionCrewCandidate candidate = new RuntimeFrontActionCrewCandidate
			{
				Crew = crew,
				IsBoss = IsRuntimeFrontActionBoss(attacker, peep),
				ExistingVehicleTaskCount = GetRetaliationVehicleActiveTaskCount(attacker, crew.VehicleID),
				RecentFrontActorUse = TryGetRecentRetaliationFrontActorUsePenalty(attacker.PID, crew, nowDay, out string recentUseReason),
				RecentFrontActorUseReason = recentUseReason ?? string.Empty
			};
			if (TryResolveRuntimeFrontActionCrewNodeQuiet(crew, peep, out NodeID currentNodeId, out string currentNodeSource)
				&& currentNodeId.IsValid)
			{
				Node currentNode = currentNodeId.FindNode();
				if (currentNode?.id.IsValid == true)
				{
					candidate.NodeId = currentNodeId;
					candidate.NodeSource = currentNodeSource;
					candidate.Distance = (targetNode.pos - currentNode.pos).Magnitude;
					candidate.HasNode = true;
				}
			}
			candidates.Add(candidate);
		}

		List<RuntimeFrontActionCrewCandidate> eligibleCandidates = candidates
			.Where(item => item.HasNode && (maxDistance <= 0f || item.Distance <= maxDistance))
			.ToList();
		if (eligibleCandidates.Count == 0 && maxDistance <= 0f)
		{
			eligibleCandidates = candidates.ToList();
		}
		List<RuntimeFrontActionCrewCandidate> eligibleNonBossCandidates = eligibleCandidates
			.Where(item => !item.IsBoss)
			.ToList();
		List<RuntimeFrontActionCrewCandidate> freshNonBossCandidates = eligibleNonBossCandidates
			.Where(item => !item.RecentFrontActorUse)
			.ToList();
		List<RuntimeFrontActionCrewCandidate> freshEligibleCandidates = eligibleCandidates
			.Where(item => !item.RecentFrontActorUse)
			.ToList();
		IEnumerable<RuntimeFrontActionCrewCandidate> selectionPool = freshNonBossCandidates.Count > 0
			? freshNonBossCandidates
			: (freshEligibleCandidates.Count > 0
				? freshEligibleCandidates
				: (eligibleNonBossCandidates.Count > 0 ? eligibleNonBossCandidates : eligibleCandidates));
		RuntimeFrontActionCrewCandidate selected = selectionPool
			.OrderBy(item => item.RecentFrontActorUse ? 1 : 0)
			.ThenBy(item => item.ExistingVehicleTaskCount)
			.ThenBy(item => item.HasNode ? 0 : 1)
			.ThenBy(item => item.Distance)
			.ThenByDescending(item => item.Crew.IsInVehicle)
			.ThenBy(item => item.Crew.peepId.id)
			.FirstOrDefault();
		if (selected == null && maxDistance > 0f && candidates.Count > 0)
		{
			blockedByDistance = true;
			RuntimeFrontActionCrewCandidate nearest = candidates
				.OrderBy(item => item.HasNode ? 0 : 1)
				.ThenBy(item => item.Distance)
				.ThenBy(item => item.IsBoss ? 1 : 0)
				.ThenBy(item => item.Crew.peepId.id)
				.FirstOrDefault();
			VerificationLog("GangOps.FrontMovement", $"front-crew-selection-too-far attacker={attacker.PID.id} peep={nearest?.Crew.peepId.id ?? 0UL} boss={nearest?.IsBoss ?? false} vehicle={(nearest != null && nearest.Crew.VehicleID.IsValid ? nearest.Crew.VehicleID.id : 0UL)} building={targetBuilding?.Id.id ?? 0UL} targetNode={targetNode.id} currentNode={nearest?.NodeId ?? NodeID.INVALID} nodeSource={nearest?.NodeSource ?? "none"} distance={(nearest?.HasNode == true ? nearest.Distance : -1f):0.0} maxDistance={maxDistance:0.0} candidates={candidates.Count} eligible={eligibleCandidates.Count} nonBossEligible={eligibleNonBossCandidates.Count} pendingActions={pendingActions} capacity={actionCapacity} capacityOverflowAllowed={allowCapacityOverflow} context={context} source={sourceTag}");
			return default(CrewAssignment);
		}
		if (selected == null || !selected.Crew.IsValid)
		{
			VerificationLog("GangOps.FrontMovement", $"front-crew-selection-unavailable attacker={attacker.PID.id} building={targetBuilding?.Id.id ?? 0UL} targetNode={targetNode.id} candidates={candidates.Count} eligible={eligibleCandidates.Count} nonBossEligible={eligibleNonBossCandidates.Count} pendingActions={pendingActions} capacity={actionCapacity} capacityOverflowAllowed={allowCapacityOverflow} context={context} source={sourceTag}");
			return default(CrewAssignment);
		}
		VerificationLog("GangOps.FrontMovement", $"front-crew-selected attacker={attacker.PID.id} peep={selected.Crew.peepId.id} boss={selected.IsBoss} vehicle={(selected.Crew.VehicleID.IsValid ? selected.Crew.VehicleID.id : 0UL)} building={targetBuilding?.Id.id ?? 0UL} targetNode={targetNode.id} currentNode={selected.NodeId} nodeSource={selected.NodeSource} distance={(selected.HasNode ? selected.Distance : -1f):0.0} candidates={candidates.Count} eligible={eligibleCandidates.Count} nonBossEligible={eligibleNonBossCandidates.Count} existingVehicleTasks={selected.ExistingVehicleTaskCount} recentUse={selected.RecentFrontActorUse} recentUseReason={(string.IsNullOrEmpty(selected.RecentFrontActorUseReason) ? "none" : selected.RecentFrontActorUseReason)} pendingActions={pendingActions} capacity={actionCapacity} capacityOverflowUsed={(allowCapacityOverflow && pendingActions >= actionCapacity)} occupiedVehicles={occupiedVehicles} normalDutyReserve={RETALIATION_NORMAL_DUTY_VEHICLE_RESERVE} convoReserve={convoReserve} convoTopic={convoTopic} convoMeetingNode={convoMeetingPoint} convoNeedsPeep={convoNeedsPeep} selection={(selected.IsBoss ? "boss-fallback" : "non-boss-preferred")} context={context} source={sourceTag}");
		return selected.Crew;
	}

	private static bool TryDispatchRuntimeGangAttack(PlayerInfo attacker, PlayerInfo defender, int desiredCrewCount, string sourceTag, EntityID preferredTargetPeepId, out int dispatchedCount, out int approachCount)
	{
		dispatchedCount = 0;
		approachCount = 0;
		if (!IsAliveGangPlayer(attacker) || defender?.crew == null)
		{
			return false;
		}
		if (defender.PID.IsHumanPlayer
			&& TurnUpdatePatch.HasActiveAiHumanRobberyResponseForHuman(defender)
			&& !((sourceTag ?? string.Empty).StartsWith("ai-human-robbery-refused", StringComparison.Ordinal)))
		{
			VerificationLog("PactRetaliation", $"runtime-dispatch-blocked-ai-robbery-response attacker={attacker.PID.id} defender={defender.PID.id} source={sourceTag}");
			return false;
		}
		if (ArePlayersProtectedByPactAlliance(attacker, defender))
		{
			ClearWarBetweenPlayers(attacker, defender);
			VerificationLog("PactAlliance", $"runtime-dispatch-blocked-alliance attacker={attacker.PID.id} defender={defender.PID.id} source={sourceTag}");
			return false;
		}
		if (HasMutualTruce(attacker, defender))
		{
			ClearWarBetweenPlayers(attacker, defender);
			VerificationLog("PactRetaliation", $"runtime-dispatch-blocked-truce attacker={attacker.PID.id} defender={defender.PID.id} source={sourceTag}");
			return false;
		}
		if (HasRuntimeGangAttackDispatchToday(attacker, defender, out string previousSource))
		{
			VerificationLog("PactRetaliation", $"runtime-dispatch-blocked-same-day attacker={attacker.PID.id} defender={defender.PID.id} previousSource={previousSource} source={sourceTag}");
			return false;
		}
		if (HasRuntimeGangAttackApproachToday(attacker, defender, out string previousApproachSource))
		{
			VerificationLog("PactRetaliation", $"runtime-dispatch-blocked-same-day-approach attacker={attacker.PID.id} defender={defender.PID.id} previousSource={previousApproachSource} source={sourceTag}");
			return false;
		}

		Entity targetPeep = FindRuntimeGangAttackTarget(defender, preferredTargetPeepId);
		if (targetPeep == null || !targetPeep.Id.IsValid)
		{
			return false;
		}

		if (!TryResolveRuntimeGangAttackTargetNode(defender, targetPeep, out Node targetNode, out string targetNodeSource))
		{
			VerificationLog("PactRetaliation", $"runtime-dispatch-blocked-no-target-node attacker={attacker.PID.id} defender={defender.PID.id} target={targetPeep.Id.id} source={sourceTag}");
			return false;
		}

		List<CrewAssignment> availableAttackCrew = attacker.crew.GetLiving()
			.Where(item => IsRuntimeGangAttackCrewAvailable(attacker, item))
			.ToList();
		HashSet<ulong> retreatingCrewIds = new HashSet<ulong>();
		foreach (CrewAssignment crew in availableAttackCrew)
		{
			if (ShouldRuntimeGangAttackerRetreat(attacker, crew, out float healthFraction))
			{
				retreatingCrewIds.Add(crew.peepId.id);
				if (!TryQueueRuntimeGangRetreat(attacker, crew, sourceTag, healthFraction))
				{
					VerificationLog("PactRetaliation", $"runtime-retreat-unavailable attacker={attacker.PID.id} peep={crew.peepId.id} health={healthFraction:0.00} source={sourceTag}");
				}
			}
		}

		List<CrewAssignment> attackers = FindRuntimeGangAttackers(attacker, desiredCrewCount, retreatingCrewIds, availableAttackCrew);
		foreach (CrewAssignment crew in attackers)
		{
			Entity peep = crew.GetPeep();
			if (peep?.data?.agent == null)
			{
				continue;
			}

			RuntimeGangAttackQueueResult queueResult = TryQueueRuntimeGangAttack(attacker, defender, crew, targetPeep, targetNode, targetNodeSource, sourceTag);
			if (queueResult == RuntimeGangAttackQueueResult.Attack)
			{
				dispatchedCount++;
			}
			else if (queueResult == RuntimeGangAttackQueueResult.Approach)
			{
				approachCount++;
			}
		}

		if (dispatchedCount > 0)
		{
			MarkRuntimeGangAttackDispatchToday(attacker, defender, sourceTag);
			VerificationLog("PactRetaliation", $"runtime-dispatch attacker={attacker.PID.id} defender={defender.PID.id} crews={dispatchedCount} approachCrews={approachCount} target={targetPeep.Id.id} source={sourceTag}");
			TryShowGangAttackTicker(attacker, defender, targetPeep, sourceTag);
		}
		else if (approachCount > 0)
		{
			MarkRuntimeGangAttackApproachToday(attacker, defender, sourceTag);
			VerificationLog("PactRetaliation", $"runtime-approach attacker={attacker.PID.id} defender={defender.PID.id} crews={approachCount} target={targetPeep.Id.id} source={sourceTag} result=no-attack-yet");
		}
		return dispatchedCount > 0;
	}

	private static bool TryDispatchRuntimeGangAttack(PlayerInfo attacker, PlayerInfo defender, int desiredCrewCount, string sourceTag, EntityID preferredTargetPeepId, out int dispatchedCount)
	{
		return TryDispatchRuntimeGangAttack(attacker, defender, desiredCrewCount, sourceTag, preferredTargetPeepId, out dispatchedCount, out _);
	}

	private static bool TryDispatchRuntimeGangAttack(PlayerInfo attacker, PlayerInfo defender, int desiredCrewCount, string sourceTag, out int dispatchedCount)
	{
		return TryDispatchRuntimeGangAttack(attacker, defender, desiredCrewCount, sourceTag, EntityID.INVALID, out dispatchedCount);
	}

	private static bool TryTriggerRobberyFailureRetaliation(GangOpsChannel channel, PlayerInfo attacker, PlayerInfo defender, int desiredCrewCount, string sourceTag, EntityID preferredTargetPeepId, out int dispatchedCount, out string actionSummary)
	{
		dispatchedCount = 0;
		actionSummary = "none";
		if (!IsAliveGangPlayer(attacker) || defender?.crew == null)
		{
			return false;
		}
		float warHeat = GetWarHeat(channel, attacker.PID.id, defender.PID.id);
		float forcedHeat = Mathf.Max(warHeat, GetEffectiveWarHeatThresholdForRevenge(channel));
		if (TryExecuteRetaliationResponse(channel, attacker, defender, preferredTargetPeepId, sourceTag + "-response", forcedHeat, out dispatchedCount, out actionSummary))
		{
			return true;
		}

		if (IsRobberyRetaliationSource(sourceTag) && TryForceCloseRobberyRetaliationImportantBusiness(channel, attacker, defender, sourceTag + "-business-fallback", out actionSummary))
		{
			return true;
		}

		if (TryDispatchRuntimeGangAttack(attacker, defender, desiredCrewCount, sourceTag + "-attack-fallback", preferredTargetPeepId, out dispatchedCount))
		{
			actionSummary = $"attack:{dispatchedCount}";
			return true;
		}

		bool queued = QueueImmediateRevengeIfEligible(channel, attacker.PID.id, defender.PID.id, preferredTargetPeepId.IsValid ? (long)preferredTargetPeepId.id : 0L, G.GetNow().days, sourceTag + "-queued");
		actionSummary = queued ? "queued-immediate" : "none";
		return queued;
	}

	private static bool QueueImmediateRevengeIfEligible(GangOpsChannel channel, int retaliationGangId, int targetGangId, long targetCrewPeepId, int nowDay, string reason)
	{
		PactOpsSettings pactOpsSettings = EnsureGangOpsSettings(channel);
		if (!pactOpsSettings.RevengeEnabled || retaliationGangId < 0 || targetGangId < 0 || retaliationGangId == targetGangId)
		{
			return false;
		}
		PlayerInfo playerInfo = G.FindPlayerById(retaliationGangId);
		if (!IsGangEligibleForChannel(playerInfo, channel))
		{
			return false;
		}
		string key = MakeGangPairKey(retaliationGangId, targetGangId);
		Dictionary<string, RevengeEntry> revengeStore = GetRevengeStore(channel);
		revengeStore[key] = new RevengeEntry
		{
			AttackerPid = retaliationGangId,
			DefenderPid = targetGangId,
			TargetCrewPeepId = targetCrewPeepId,
			DueDay = nowDay,
			Executed = false,
			SourceReason = reason
		};
		VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Immediate revenge queued for {key} dueDay={nowDay} reason={reason}");
		return true;
	}

	private static bool IsForcedRobberyRefusalAttackRevenge(RevengeEntry entry)
	{
		return entry != null
			&& !string.IsNullOrEmpty(entry.SourceReason)
			&& entry.SourceReason.IndexOf("ai-human-robbery-refused", StringComparison.OrdinalIgnoreCase) >= 0
			&& (entry.SourceReason.IndexOf("attack-next-turn", StringComparison.OrdinalIgnoreCase) >= 0
				|| entry.SourceReason.IndexOf("attack-delayed", StringComparison.OrdinalIgnoreCase) >= 0);
	}

	private static int ExecuteDueRevengeEntries(GangOpsChannel channel, SimTime now)
	{
		if (!EnableAIAlliances.Value || !IsGangOpsEnabled(channel))
		{
			return 0;
		}
		Dictionary<string, RevengeEntry> revengeStore = GetRevengeStore(channel);
		if (revengeStore.Count == 0)
		{
			return 0;
		}
		int num = 0;
		foreach (KeyValuePair<string, RevengeEntry> item in revengeStore.ToList())
		{
			RevengeEntry value = item.Value;
			if (value == null || value.Executed || value.DueDay > now.days)
			{
				continue;
			}
			PlayerInfo playerInfo = G.FindPlayerById(value.AttackerPid);
			PlayerInfo playerInfo2 = G.FindPlayerById(value.DefenderPid);
			if (!IsGangEligibleForChannel(playerInfo, channel) || !IsGangOpsRetaliationTargetEligible(playerInfo2))
			{
				value.Executed = true;
				continue;
			}
			EntityID preferredTargetPeepId = EntityID.INVALID;
			if (value.TargetCrewPeepId > 0)
			{
				preferredTargetPeepId = EntityID.FromID((ulong)value.TargetCrewPeepId);
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Targeting actual attacker crew at peep={value.TargetCrewPeepId}");
			}
			if (ArePlayersProtectedByPactAlliance(playerInfo, playerInfo2))
			{
				ClearWarBetweenPlayers(playerInfo, playerInfo2);
				value.Executed = true;
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Skipped due revenge because alliance protects pair attacker={value.AttackerPid} defender={value.DefenderPid}");
				continue;
			}
			if (HasMutualTruce(playerInfo, playerInfo2))
			{
				ClearWarBetweenPlayers(playerInfo, playerInfo2);
				value.Executed = true;
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Skipped due revenge because truce exists attacker={value.AttackerPid} defender={value.DefenderPid}");
				continue;
			}
			ActivateWarBetweenPlayers(playerInfo, playerInfo2);
			float warHeat = GetWarHeat(channel, value.AttackerPid, value.DefenderPid);
			string revengeSource = string.IsNullOrEmpty(value.SourceReason) ? $"{GetGangOpsChannelTag(channel)}-revenge" : value.SourceReason;
			bool actionTaken;
			int dispatchedCount;
			string actionSummary;
			if (IsForcedRobberyRefusalAttackRevenge(value))
			{
				bool attackQueued = TryDispatchRuntimeGangAttack(playerInfo, playerInfo2, 3, revengeSource, preferredTargetPeepId, out dispatchedCount, out int approachCount);
				actionTaken = attackQueued;
				actionSummary = attackQueued ? $"attack:{dispatchedCount}" : (approachCount > 0 ? $"approach:{approachCount}" : "attack-unavailable");
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Forced robbery refusal attack resolved attacker={value.AttackerPid} defender={value.DefenderPid} action={actionSummary} source={revengeSource}");
			}
			else
			{
				actionTaken = TryExecuteRetaliationResponse(channel, playerInfo, playerInfo2, preferredTargetPeepId, $"{GetGangOpsChannelTag(channel)}-revenge", warHeat, out dispatchedCount, out actionSummary);
			}
			if (actionTaken)
			{
				value.Executed = true;
				num++;
			}
			else if (!string.IsNullOrEmpty(actionSummary) && actionSummary.StartsWith("approach:", StringComparison.Ordinal))
			{
				value.DueDay = GetRuntimeGangAttackApproachRetryDueDay(now.days);
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Approach-only retaliation delayed attacker={value.AttackerPid} defender={value.DefenderPid} nextDueDay={value.DueDay} delayDays={RuntimeGangAttackApproachRetryDelayDays}");
			}
			else if (string.Equals(actionSummary, "attack-unavailable", StringComparison.Ordinal))
			{
				value.DueDay = GetRuntimeGangAttackApproachRetryDueDay(now.days);
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Unavailable retaliation delayed attacker={value.AttackerPid} defender={value.DefenderPid} nextDueDay={value.DueDay} delayDays={RuntimeGangAttackApproachRetryDelayDays}");
			}
			else
			{
				value.Executed = true;
				num++;
			}
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Executed retaliation action={actionSummary} taken={actionTaken} crews={dispatchedCount} attacker={value.AttackerPid} defender={value.DefenderPid} heat={warHeat:0.0}");
			if (actionTaken)
			{
				LogGrapevine(actionSummary.StartsWith("forced-close", StringComparison.Ordinal)
					? $"WAR: {GetGangDisplayName(value.AttackerPid)} retaliates by closing a front tied to {GetGangDisplayName(value.DefenderPid)}."
					: $"WAR: {GetGangDisplayName(value.AttackerPid)} retaliates against {GetGangDisplayName(value.DefenderPid)}.");
			}
		}
		return num;
	}

	private static bool TryExecuteRetaliationResponse(GangOpsChannel channel, PlayerInfo attacker, PlayerInfo defender, EntityID preferredTargetPeepId, string sourceTag, float warHeat, out int dispatchedCount, out string actionSummary)
	{
		dispatchedCount = 0;
		actionSummary = "none";
		bool attemptedCrewDispatch = false;
		GangRetaliationOpportunity opportunity = ScoreGangRetaliationOpportunity(channel, attacker, defender, preferredTargetPeepId, sourceTag, warHeat);
		switch (opportunity.Action)
		{
			case GangRetaliationAction.CallPactSupport:
				if (TryCallPactRetaliationSupport(attacker, defender, preferredTargetPeepId, sourceTag, out dispatchedCount))
				{
					actionSummary = $"pact-support:{dispatchedCount}";
					return true;
				}
				if (opportunity.CanHitCrew)
				{
					attemptedCrewDispatch = true;
					bool attackQueued = TryDispatchRuntimeGangAttack(attacker, defender, 2, sourceTag, preferredTargetPeepId, out dispatchedCount, out int approachCount);
					if (attackQueued)
					{
						actionSummary = $"attack:{dispatchedCount}";
						return true;
					}
					if (approachCount > 0)
					{
						actionSummary = $"approach:{approachCount}";
						return false;
					}
				}
				break;
			case GangRetaliationAction.CloseFront:
				if (IsRobberyRetaliationSource(sourceTag)
					? TryForceCloseRobberyRetaliationImportantBusiness(channel, attacker, defender, sourceTag, out actionSummary)
					: TryForceCloseRetaliationBusiness(channel, attacker, defender, sourceTag, out actionSummary))
				{
					TryLogAiFrontClosureGrapevine(attacker, defender, actionSummary, sourceTag);
					return true;
				}
				if (opportunity.CanHitCrew)
				{
					attemptedCrewDispatch = true;
					bool attackQueued = TryDispatchRuntimeGangAttack(attacker, defender, 2, sourceTag, preferredTargetPeepId, out dispatchedCount, out int approachCount);
					if (attackQueued)
					{
						actionSummary = $"attack:{dispatchedCount}";
						return true;
					}
					if (approachCount > 0)
					{
						actionSummary = $"approach:{approachCount}";
						return false;
					}
				}
				break;
			case GangRetaliationAction.AttackBuilding:
				if (TryForceCloseWarHeatRetaliationImportantBusiness(channel, attacker, defender, sourceTag, out actionSummary))
				{
					TryLogAiFrontClosureGrapevine(attacker, defender, actionSummary, sourceTag);
					return true;
				}
				if (TryForceCloseRetaliationBusiness(channel, attacker, defender, sourceTag, out actionSummary))
				{
					TryLogAiFrontClosureGrapevine(attacker, defender, actionSummary, sourceTag);
					return true;
				}
				break;
			case GangRetaliationAction.TakeTerritory:
				if (IsRobberyRetaliationSource(sourceTag)
					? TryForceCloseRobberyRetaliationImportantBusiness(channel, attacker, defender, sourceTag, out actionSummary)
					: TryForceCloseRetaliationBusiness(channel, attacker, defender, sourceTag, out actionSummary))
				{
					TryLogAiFrontClosureGrapevine(attacker, defender, actionSummary, sourceTag);
					return true;
				}
				if (IsRobberyRetaliationSource(sourceTag))
				{
					break;
				}
				if (TryRunRetaliationTerritoryPressure(channel, attacker, sourceTag, out int territoryActions))
				{
					actionSummary = $"territory:{territoryActions}";
					return true;
				}
				break;
			case GangRetaliationAction.HitCrew:
				if (opportunity.CanHitCrew)
				{
					attemptedCrewDispatch = true;
					bool attackQueued = TryDispatchRuntimeGangAttack(attacker, defender, opportunity.Severe ? 3 : 2, sourceTag, preferredTargetPeepId, out dispatchedCount, out int approachCount);
					if (attackQueued)
					{
						actionSummary = $"attack:{dispatchedCount}";
						return true;
					}
					if (approachCount > 0)
					{
						actionSummary = $"approach:{approachCount}";
						return false;
					}
				}
				if (IsRobberyRetaliationSource(sourceTag)
					? TryForceCloseRobberyRetaliationImportantBusiness(channel, attacker, defender, sourceTag, out actionSummary)
					: TryForceCloseRetaliationBusiness(channel, attacker, defender, sourceTag, out actionSummary))
				{
					TryLogAiFrontClosureGrapevine(attacker, defender, actionSummary, sourceTag);
					return true;
				}
				break;
		}
		if (opportunity.Action != GangRetaliationAction.StandDown
			&& !IsRobberyRetaliationSource(sourceTag)
			&& TryRunRetaliationTerritoryPressure(channel, attacker, sourceTag + "-fallback", out int fallbackTerritoryActions))
		{
			actionSummary = $"territory:{fallbackTerritoryActions}";
			return true;
		}
		if (attemptedCrewDispatch)
		{
			actionSummary = "attack-unavailable";
			return false;
		}
		actionSummary = "none";
		return false;
	}

	private static bool TryRunRetaliationTerritoryPressure(GangOpsChannel channel, PlayerInfo attacker, string sourceTag, out int territoryActions)
	{
		territoryActions = 0;
		if (!IsGangEligibleForChannel(attacker, channel) || !ShouldAllowGangTerritoryExpansion())
		{
			return false;
		}
		try
		{
			territoryActions = DirtyCashEconomyCompatibilityPatch.TryRunAiOutpostTerritoryExpansionPass(channel, sourceTag + "-retaliation-territory", new int[1] { attacker.PID.id });
			if (territoryActions > 0)
			{
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Territory pressure retaliation attacker={attacker.PID.id} actions={territoryActions} source={sourceTag}");
				return true;
			}
		}
		catch (Exception ex)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Territory pressure failed attacker={attacker.PID.id} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
		}
		return false;
	}

	private static bool TryForceCloseRetaliationBusiness(GangOpsChannel channel, PlayerInfo attacker, PlayerInfo defender, string sourceTag, out string actionSummary)
	{
		actionSummary = "forced-close:none";
		if (!IsAliveGangPlayer(attacker) || !IsGangOpsRetaliationTargetEligible(defender) || attacker.territory == null)
		{
			return false;
		}
		if (ArePlayersProtectedByPactAlliance(attacker, defender) || HasMutualTruce(attacker, defender))
		{
			return false;
		}
		EntityID actorPeepId = GetCrewPeepForPlayer(attacker);
		if (actorPeepId.IsNotValid)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Forced closure unavailable attacker={attacker.PID.id} defender={defender.PID.id} reason=no-actor source={sourceTag}");
			return false;
		}
		if (TryExecuteRetaliationFrontOrBackroomAction(channel, attacker, defender, actorPeepId, sourceTag, out actionSummary))
		{
			return true;
		}
		if (!TryFindRetaliationClosureTarget(attacker, defender, out Entity targetBuilding, out string reason))
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Forced closure unavailable attacker={attacker.PID.id} defender={defender.PID.id} reason={reason} source={sourceTag}");
			return false;
		}
		try
		{
			if (TryQueuePhysicalRetaliationBusinessForceClose(channel, attacker, defender, targetBuilding, sourceTag, out actionSummary))
			{
				return true;
			}
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Forced closure unavailable attacker={attacker.PID.id} defender={defender.PID.id} building={targetBuilding.Id.id} reason=no-physical-business-route source={sourceTag}");
			return false;
		}
		catch (Exception ex)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Forced closure failed attacker={attacker.PID.id} defender={defender.PID.id} building={targetBuilding?.Id.id ?? 0UL} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static bool TryForceCloseWarHeatRetaliationImportantBusiness(GangOpsChannel channel, PlayerInfo attacker, PlayerInfo defender, string sourceTag, out string actionSummary)
	{
		actionSummary = "forced-close-warheat-important:none";
		if (!IsAliveGangPlayer(attacker) || !IsGangOpsRetaliationTargetEligible(defender) || attacker.territory == null)
		{
			return false;
		}
		if (ArePlayersProtectedByPactAlliance(attacker, defender) || HasMutualTruce(attacker, defender))
		{
			return false;
		}
		if (defender.PID.IsHumanPlayer)
		{
			int capacity = GetRetaliationActionCapacity(attacker, out int occupiedVehicles, out int pendingActions, out _);
			if (pendingActions >= capacity)
			{
				actionSummary = $"forced-close-warheat-important-capacity-blocked:{pendingActions}/{capacity}";
				VerificationLog("GangOps.FrontMovement", $"business-capacity-blocked attacker={attacker.PID.id} defender={defender.PID.id} pendingActions={pendingActions} capacity={capacity} occupiedVehicles={occupiedVehicles} normalDutyReserve={RETALIATION_NORMAL_DUTY_VEHICLE_RESERVE} source={sourceTag}");
				return true;
			}
		}
		bool foundClosureTarget = TryFindRetaliationClosureTarget(attacker, defender, out Entity targetBuilding, out string reason);
		string importantShopReason = "not-evaluated";
		if (!foundClosureTarget
			|| !TryValidateRetaliationImportantShopTarget(targetBuilding, out _, out importantShopReason))
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"War-heat important business closure unavailable attacker={attacker.PID.id} defender={defender.PID.id} reason={reason}+{importantShopReason} source={sourceTag}");
			return false;
		}
		try
		{
			if (TryQueuePhysicalRetaliationBusinessForceClose(channel, attacker, defender, targetBuilding, sourceTag + "-warheat-business", out string queuedSummary))
			{
				actionSummary = "forced-close-warheat-important-" + queuedSummary;
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"War-heat important business closure queued attacker={attacker.PID.id} defender={defender.PID.id} building={targetBuilding.Id.id} action={actionSummary} source={sourceTag}");
				return true;
			}
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"War-heat important business closure unavailable attacker={attacker.PID.id} defender={defender.PID.id} building={targetBuilding.Id.id} reason=no-physical-business-route source={sourceTag}");
			return false;
		}
		catch (Exception ex)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"War-heat important business closure failed attacker={attacker.PID.id} defender={defender.PID.id} building={targetBuilding?.Id.id ?? 0UL} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

