	private static bool TryExecuteRetaliationFrontOrBackroomAction(GangOpsChannel channel, PlayerInfo attacker, PlayerInfo defender, EntityID actorPeepId, string sourceTag, out string actionSummary)
	{
		actionSummary = "front-action:none";
		if (!TryFindRetaliationFrontOrBackroomTarget(attacker, defender, null, out Entity targetBuilding, out string targetKind, out string reason))
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Front/backroom retaliation unavailable attacker={attacker?.PID.id ?? 0} defender={defender?.PID.id ?? 0} reason={reason} source={sourceTag}");
			return false;
		}
		if (TryBlockNewHumanFrontTargetForExistingPending(attacker, defender, targetBuilding, targetKind, sourceTag, out actionSummary))
		{
			return true;
		}
		try
		{
			if (TryQueuePhysicalRetaliationFrontOrBusinessAction(channel, attacker, defender, targetBuilding, targetKind, sourceTag, out actionSummary))
			{
				return true;
			}
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Front/backroom retaliation unavailable attacker={attacker.PID.id} defender={defender.PID.id} building={targetBuilding.Id.id} kind={targetKind} reason=no-physical-crew-route actor={actorPeepId.id} source={sourceTag}");
			return false;
		}
		catch (Exception ex)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Front/backroom retaliation failed attacker={attacker.PID.id} defender={defender.PID.id} building={targetBuilding?.Id.id ?? 0UL} kind={targetKind} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static bool TryQueuePhysicalRetaliationFrontOrBusinessAction(GangOpsChannel channel, PlayerInfo attacker, PlayerInfo defender, Entity targetBuilding, string targetKind, string sourceTag, out string actionSummary)
	{
		actionSummary = "physical-front:none";
		if (attacker?.commands == null || targetBuilding?.components?.board == null)
		{
			return false;
		}
		NodeID targetNodeId = targetBuilding.data?.board?.bead.nodeId ?? NodeID.INVALID;
		Node targetNode = targetNodeId.IsValid ? targetNodeId.FindNode() : null;
		if (targetNode?.id.IsValid != true)
		{
			return false;
		}
		if (TryBlockNewHumanFrontTargetForExistingPending(attacker, defender, targetBuilding, targetKind, sourceTag, out actionSummary))
		{
			return true;
		}

		float maxCrewDistance = defender?.PID.IsHumanPlayer == true ? AI_VS_HUMAN_FRONT_ACTION_MAX_CREW_DISTANCE : -1f;
		CrewAssignment crew = FindRuntimeFrontActionCrew(attacker, targetBuilding, targetNode, sourceTag, "front-action", maxCrewDistance, out bool blockedByDistance);
		if (!crew.IsValid || crew.peepId.IsNotValid)
		{
			if (blockedByDistance && defender?.PID.IsHumanPlayer == true)
			{
				BlockRetaliationFrontRetry(attacker.PID, defender.PID, targetBuilding.Id, EntityID.INVALID, "crew-too-far", sourceTag, RETALIATION_FRONT_TOO_FAR_RETRY_BLOCK_DAYS);
			}
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical front action unavailable attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} building={targetBuilding.Id.id} kind={targetKind} reason=no-available-crew source={sourceTag}");
			return false;
		}

		try
		{
			Entity peep = crew.GetPeep();
			TryResolveRuntimeCrewPhysicalNode(attacker, crew, peep, out NodeID currentNodeId, out string currentNodeSource, sourceTag, "front-action");
			Command actionCommand;
			string actionMode;
			if (string.Equals(targetKind, "outpost", StringComparison.Ordinal))
			{
				OutpostID outpostId = new OutpostID(targetBuilding);
				if (defender?.outposts?.GetOutpostEntryUnsafe(outpostId) == null)
				{
					VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical front action unavailable attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} building={targetBuilding.Id.id} kind={targetKind} reason=outpost-entry-missing source={sourceTag}");
					return false;
				}
				actionCommand = new AICommandAtOutpost(attacker.PID, crew.peepId, targetBuilding.Id, "maybe-steal");
				actionMode = "front-steal";
			}
			else
			{
				actionCommand = new AICommandAttackBuilding(attacker.PID, crew.peepId, targetBuilding.Id, defender?.PID ?? PlayerID.System, "gangbiz");
				actionMode = HasRetaliationBackroomModule(targetBuilding) ? "backroom-attack" : "front-building-attack";
			}

			attacker.commands.FlushQueue(crew.peepId, cancelActive: true);
			if (currentNodeId.IsValid && currentNodeId == targetNode.id)
			{
				if (ShouldDelayHumanRetaliationFrontAction(defender, sourceTag))
				{
					actionSummary = $"{actionMode}-travel-queued:{targetBuilding.Id.id}";
					ShowPendingRetaliationFrontTicker(attacker, defender, targetBuilding, crew.peepId, targetNode.id, actionMode + "-delayed-at-target", sourceTag);
					MarkPendingRetaliationFrontDelayedPhysicalAction(targetBuilding.Id, targetKind, G.GetNow().days + 1, "already-at-target");
					VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical front action delayed attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} targetNode={targetNode.id} currentNode={currentNodeId} currentSource={currentNodeSource} kind={targetKind} mode={actionMode}-delayed-at-target notBeforeDay={G.GetNow().days + 1} source={sourceTag}");
					return true;
				}
				attacker.commands.AddCommandImmediate(actionCommand);
				actionSummary = $"{actionMode}-queued:{targetBuilding.Id.id}";
				ShowPendingRetaliationFrontTicker(attacker, defender, targetBuilding, crew.peepId, targetNode.id, actionMode + "-now", sourceTag);
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical front action queued attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} targetNode={targetNode.id} currentNode={currentNodeId} currentSource={currentNodeSource} kind={targetKind} mode={actionMode}-now source={sourceTag}");
				return true;
			}

			bool delayHumanFrontAction = ShouldDelayHumanRetaliationFrontAction(defender, sourceTag);
			bool acceptedLongHumanFrontRoute = false;
			bool approachReady = delayHumanFrontAction
				? TryBuildRuntimeFrontReachableNextRoute(attacker.PID, peep, targetNode, out PathData approachPath, out string approachReason)
				: TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, targetNode, out approachPath, out approachReason);
			if (!approachReady
				&& delayHumanFrontAction
				&& TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, targetNode, out PathData longApproachPath, out string longApproachReason))
			{
				approachReady = true;
				acceptedLongHumanFrontRoute = true;
				approachPath = longApproachPath;
				approachReason = "multi-turn-human-front-route " + longApproachReason;
				VerificationLog("GangOps.FrontMovement", $"front-route-long-accepted attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} targetNode={targetNode.id} currentNode={currentNodeId} currentSource={currentNodeSource} kind={targetKind} route={longApproachReason} cost={(longApproachPath != null ? longApproachPath.cost.ToString() : "0")} source={sourceTag}");
			}
			if (!approachReady)
			{
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical front action unavailable attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} targetNode={targetNode.id} currentNode={currentNodeId} currentSource={currentNodeSource} kind={targetKind} reason=no-approach-route detail={approachReason} source={sourceTag}");
				if (TryQueueRetaliationBusinessFallbackAfterFrontRouteFailure(channel, attacker, defender, crew, peep, targetBuilding, currentNodeId, currentNodeSource, sourceTag, out actionSummary))
				{
					return true;
				}
				if (delayHumanFrontAction)
				{
					BlockRetaliationFrontRetry(attacker.PID, defender.PID, targetBuilding.Id, crew.peepId, "front-route-too-long", sourceTag, RETALIATION_FRONT_TOO_FAR_RETRY_BLOCK_DAYS);
				}
				return false;
			}
			NodeID routeCommandNodeId = targetNode.id;
			string routeGoalMode = "target";
			if (delayHumanFrontAction)
			{
				Node routeCommandNode = ResolveFrontRouteCommandNode(targetNode, approachPath, allowSegmentTarget: true, out routeCommandNodeId, out routeGoalMode);
				if (routeCommandNode?.id.IsValid != true)
				{
					routeCommandNode = targetNode;
					routeCommandNodeId = targetNode.id;
					routeGoalMode = "target-fallback";
				}
				attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, crew.peepId, routeCommandNode));
				if (routeCommandNodeId.IsValid && routeCommandNodeId != targetNode.id)
				{
					VerificationLog("GangOps.FrontMovement", $"front-route-segment-queued attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} routeTargetNode={routeCommandNodeId} finalTargetNode={targetNode.id} routeGoal={routeGoalMode} route={approachReason} cost={approachPath.cost} source={sourceTag}");
				}
			}
			else
			{
				attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, crew.peepId, targetNode), actionCommand);
			}
			actionSummary = $"{actionMode}-travel-queued:{targetBuilding.Id.id}";
			ShowPendingRetaliationFrontTicker(attacker, defender, targetBuilding, crew.peepId, targetNode.id, "goto-" + actionMode, sourceTag);
			if (delayHumanFrontAction)
			{
				MarkPendingRetaliationFrontDelayedPhysicalAction(targetBuilding.Id, targetKind, G.GetNow().days + 1, "travel-first");
				if (_pendingRetaliationFrontTickersByBuilding.TryGetValue(targetBuilding.Id.id, out PendingRetaliationFrontTicker pendingRouteEntry) && pendingRouteEntry != null)
				{
					MarkPendingRetaliationRouteTarget(pendingRouteEntry, routeCommandNodeId, targetNode.id, currentNodeId);
				}
				if (acceptedLongHumanFrontRoute)
				{
					MarkPendingRetaliationFrontDelayedMultiTurnRoute(targetBuilding.Id, "front-route-long-accepted");
				}
			}
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical front action queued attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} targetNode={targetNode.id} currentNode={currentNodeId} currentSource={currentNodeSource} kind={targetKind} mode=goto-{actionMode}{(delayHumanFrontAction ? "-delayed" : string.Empty)} routeTargetNode={(delayHumanFrontAction ? routeCommandNodeId : targetNode.id)} routeGoal={(delayHumanFrontAction ? routeGoalMode : "target")} route={approachReason} cost={approachPath.cost} source={sourceTag}");
			return true;
		}
		catch (Exception ex)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical front action queue failed attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} kind={targetKind} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static bool TryQueueRetaliationBusinessFallbackAfterFrontRouteFailure(GangOpsChannel channel, PlayerInfo attacker, PlayerInfo defender, CrewAssignment crew, Entity peep, Entity failedFrontBuilding, NodeID currentNodeId, string currentNodeSource, string sourceTag, out string actionSummary)
	{
		actionSummary = "business-fallback:none";
		if (attacker?.commands == null || defender == null || !crew.IsValid || crew.peepId.IsNotValid || peep == null)
		{
			return false;
		}
		if (!TryFindRouteFailedRetaliationBusinessFallback(attacker, defender, crew, peep, failedFrontBuilding, currentNodeId, out Entity fallbackBuilding, out Node fallbackNode, out PathData fallbackPath, out string targetReason, out string routeReason))
		{
			VerificationLog("GangOps.FrontMovement", $"front-route-fallback-business-unavailable attacker={attacker.PID.id} defender={defender.PID.id} peep={crew.peepId.id} failedBuilding={failedFrontBuilding?.Id.id ?? 0UL} currentNode={currentNodeId} reason={targetReason} source={sourceTag}");
			return false;
		}

		try
		{
			AICommandAttackBuilding forceClose = new AICommandAttackBuilding(attacker.PID, crew.peepId, fallbackBuilding.Id, defender.PID, "npcbiz");
			attacker.commands.FlushQueue(crew.peepId, cancelActive: true);
			if (currentNodeId.IsValid && fallbackNode?.id.IsValid == true && currentNodeId == fallbackNode.id)
			{
				attacker.commands.AddCommandImmediate(forceClose);
				actionSummary = $"business-fallback-close-queued:{fallbackBuilding.Id.id}";
				TrackPendingRetaliationForcedBusinessClosure(attacker, defender, fallbackBuilding, crew.peepId, fallbackNode.id, "business-fallback-close-now", sourceTag, NodeID.INVALID);
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"front-route-fallback-business-queued attacker={attacker.PID.id} defender={defender.PID.id} peep={crew.peepId.id} failedBuilding={failedFrontBuilding?.Id.id ?? 0UL} building={fallbackBuilding.Id.id} targetNode={fallbackNode.id} currentNode={currentNodeId} currentSource={currentNodeSource} mode=force-close-business-now reason={targetReason} source={sourceTag}");
				return true;
			}

			attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, crew.peepId, fallbackNode), forceClose);
			actionSummary = $"business-fallback-close-travel-queued:{fallbackBuilding.Id.id}";
			TrackPendingRetaliationForcedBusinessClosure(attacker, defender, fallbackBuilding, crew.peepId, fallbackNode.id, "goto-business-fallback-close", sourceTag, currentNodeId);
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"front-route-fallback-business-queued attacker={attacker.PID.id} defender={defender.PID.id} peep={crew.peepId.id} failedBuilding={failedFrontBuilding?.Id.id ?? 0UL} building={fallbackBuilding.Id.id} targetNode={fallbackNode.id} currentNode={currentNodeId} currentSource={currentNodeSource} mode=goto-force-close-business route={routeReason} cost={(fallbackPath != null ? fallbackPath.cost.ToString() : "0")} reason={targetReason} source={sourceTag}");
			return true;
		}
		catch (Exception ex)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"front-route-fallback-business-failed attacker={attacker.PID.id} defender={defender.PID.id} peep={crew.peepId.id} failedBuilding={failedFrontBuilding?.Id.id ?? 0UL} building={fallbackBuilding?.Id.id ?? 0UL} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static bool TryFindRouteFailedRetaliationBusinessFallback(PlayerInfo attacker, PlayerInfo defender, CrewAssignment crew, Entity peep, Entity failedFrontBuilding, NodeID currentNodeId, out Entity targetBuilding, out Node targetNode, out PathData targetPath, out string reason, out string routeReason)
	{
		targetBuilding = null;
		targetNode = null;
		targetPath = null;
		reason = "none";
		routeReason = "none";
		if (!IsAliveGangPlayer(attacker) || defender == null || peep == null)
		{
			reason = "ineligible";
			return false;
		}

		List<Node> nodes = new List<Node>();
		HashSet<NodeID> seenNodes = new HashSet<NodeID>();
		Node currentNode = currentNodeId.IsValid ? currentNodeId.FindNode() : null;
		NodeID failedFrontNodeId = failedFrontBuilding?.data?.board?.bead.nodeId ?? NodeID.INVALID;
		Node failedFrontNode = failedFrontNodeId.IsValid ? failedFrontNodeId.FindNode() : null;
		AddForcedClosureSearchNodes(failedFrontNode, AI_FORCED_CLOSURE_HQ_SEARCH_RADIUS, nodes, seenNodes);
		AddForcedClosureSearchNodes(currentNode, AI_FORCED_CLOSURE_FRONT_SEARCH_RADIUS, nodes, seenNodes);
		try
		{
			AddForcedClosureSearchNodes(defender.territory?.GetHeadquartersNode(ignoreWarnings: true), AI_FORCED_CLOSURE_HQ_SEARCH_RADIUS, nodes, seenNodes);
		}
		catch
		{
		}
		foreach (Entity building in GetOwnedBuildings(defender).Take(18))
		{
			NodeID nodeId = building?.data?.board?.bead.nodeId ?? NodeID.INVALID;
			AddForcedClosureSearchNodes(nodeId.IsValid ? nodeId.FindNode() : null, AI_FORCED_CLOSURE_FRONT_SEARCH_RADIUS, nodes, seenNodes);
		}

		if (nodes.Count == 0)
		{
			reason = "no-search-nodes";
			return false;
		}

		int scanned = 0;
		int candidateCount = 0;
		int routeBlocked = 0;
		int locked = 0;
		int skippedFront = 0;
		int wrongTerritory = 0;
		int bestPriority = int.MaxValue;
		Fixnum bestCost = new Fixnum(int.MaxValue);
		HashSet<ulong> seenBuildings = new HashSet<ulong>();
		foreach (Node node in nodes)
		{
			if (node == null)
			{
				continue;
			}
			IEnumerable<EntityID> interestingIds = node.interesting ?? Enumerable.Empty<EntityID>();
			foreach (EntityID entityId in (node.contained ?? Enumerable.Empty<EntityID>()).Concat(interestingIds))
			{
				Entity entity = entityId.FindEntity();
				Entity building = ResolveBusinessFallbackBuilding(entity);
				if (building?.components?.building == null || !seenBuildings.Add(building.Id.id))
				{
					continue;
				}
				scanned++;
				if (!IsRouteFailedRetaliationBusinessFallbackCandidate(attacker, defender, building, failedFrontBuilding, out int priority, out string candidateReason, out bool blockedByLock, out bool blockedAsFront, out bool blockedByTerritory))
				{
					if (blockedByLock)
					{
						locked++;
					}
					if (blockedAsFront)
					{
						skippedFront++;
					}
					if (blockedByTerritory)
					{
						wrongTerritory++;
					}
					continue;
				}
				candidateCount++;
				NodeID buildingNodeId = building.data?.board?.bead.nodeId ?? NodeID.INVALID;
				Node buildingNode = buildingNodeId.IsValid ? buildingNodeId.FindNode() : null;
				if (buildingNode?.id.IsValid != true)
				{
					continue;
				}
				bool routeReady = TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, buildingNode, out PathData path, out string pathReason);
				if (!routeReady)
				{
					routeBlocked++;
					continue;
				}
				Fixnum cost = path?.cost ?? Fixnum.ZERO;
				if (targetBuilding == null
					|| priority < bestPriority
					|| (priority == bestPriority && cost < bestCost)
					|| (priority == bestPriority && cost == bestCost && building.Id.id < targetBuilding.Id.id))
				{
					targetBuilding = building;
					targetNode = buildingNode;
					targetPath = path;
					bestPriority = priority;
					bestCost = cost;
					reason = candidateReason;
					routeReason = pathReason;
				}
			}
		}

		if (targetBuilding == null)
		{
			reason = $"no-reachable-business-fallback scanned={scanned} candidates={candidateCount} routeBlocked={routeBlocked} locked={locked} skippedFront={skippedFront} wrongTerritory={wrongTerritory}";
			return false;
		}
		return true;
	}

	private static Entity ResolveBusinessFallbackBuilding(Entity entity)
	{
		if (entity == null)
		{
			return null;
		}
		Entity bizEntity = BuildingUtil.FindBizForBuilding(entity);
		Entity building = bizEntity != null ? BuildingUtil.FindBuildingForBiz(bizEntity) : null;
		return building ?? (entity.components?.building != null ? entity : null);
	}

	private static bool TryValidateRetaliationImportantShopTarget(Entity building, out Entity bizEntity, out string reason)
	{
		bizEntity = null;
		reason = "none";
		if (building?.components?.building == null)
		{
			reason = "invalid-building";
			return false;
		}

		BuildingComponent.BuildingTypeFlags buildingType;
		try
		{
			buildingType = building.components.building.GetBuildingType();
		}
		catch (Exception ex)
		{
			reason = "building-type-failed-" + ex.GetType().Name;
			return false;
		}
		if (buildingType != BuildingComponent.BuildingTypeFlags.Business)
		{
			reason = "not-shop-building-type-" + buildingType.ToString().Replace(", ", "+").Replace(" ", string.Empty);
			return false;
		}

		bizEntity = BuildingUtil.FindBizForBuilding(building);
		if (bizEntity?.components?.biz == null)
		{
			reason = "no-biz";
			return false;
		}

		Entity linkedBuilding = BuildingUtil.FindBuildingForBiz(bizEntity);
		if (linkedBuilding == null || linkedBuilding.Id != building.Id)
		{
			reason = "biz-building-mismatch";
			return false;
		}

		try
		{
			string buildingName = BuildingUtil.FindBuildingName(building);
			string buildingIcon = BuildingUtil.FindBuildingIcon(building);
			if (string.IsNullOrWhiteSpace(buildingName) || string.IsNullOrWhiteSpace(buildingIcon))
			{
				reason = "missing-shop-ui";
				return false;
			}
		}
		catch (Exception ex)
		{
			reason = "shop-ui-failed-" + ex.GetType().Name;
			return false;
		}

		try
		{
			BuildingData buildingData = building.data?.building;
			if (buildingData == null)
			{
				reason = "missing-building-data";
				return false;
			}
			if (!buildingData.interesting)
			{
				reason = "not-interesting-shop";
				return false;
			}
			if (buildingData.suppressPick)
			{
				reason = "shop-pick-suppressed";
				return false;
			}

			NodeID buildingNodeId = building.data?.board?.bead.nodeId ?? NodeID.INVALID;
			Node buildingNode = buildingNodeId.IsValid ? buildingNodeId.FindNode() : null;
			if (buildingNode == null)
			{
				reason = "missing-shop-node";
				return false;
			}
			if (buildingNode.contained == null || !buildingNode.contained.Contains(building.Id))
			{
				reason = "shop-not-contained-on-node";
				return false;
			}
			if (buildingNode.interesting == null || !buildingNode.interesting.Contains(building.Id))
			{
				reason = "shop-not-node-interesting";
				return false;
			}
			if (!building.components.building.CanBeScopedOutByPlayer(PlayerID.HumanPlayer)
				&& !building.components.building.IsInteractableByPlayer(PlayerID.HumanPlayer))
			{
				reason = "shop-not-map-interactable";
				return false;
			}

			Entity owner = BuildingUtil.FindOwnerForBiz(bizEntity);
			if (owner?.data?.person == null)
			{
				reason = "missing-shop-owner";
				return false;
			}
		}
		catch (Exception ex)
		{
			reason = "shop-map-visibility-failed-" + ex.GetType().Name;
			return false;
		}

		try
		{
			List<NodeID> accessNodeIds = HumanBuySellVehiclePhysicalGatePatch.FindShopAccessNodeIds(building);
			if (accessNodeIds == null || !accessNodeIds.Any(nodeId => nodeId.IsValid))
			{
				reason = "no-shop-access-node";
				return false;
			}
		}
		catch (Exception ex)
		{
			reason = "shop-access-failed-" + ex.GetType().Name;
			return false;
		}

		reason = "valid-shop";
		return true;
	}

	private static bool IsRouteFailedRetaliationBusinessFallbackCandidate(PlayerInfo attacker, PlayerInfo defender, Entity building, Entity failedFrontBuilding, out int priority, out string reason, out bool blockedByLock, out bool blockedAsFront, out bool blockedByTerritory)
	{
		priority = int.MaxValue;
		reason = "none";
		blockedByLock = false;
		blockedAsFront = false;
		blockedByTerritory = false;
		if (attacker == null || defender == null || building?.components?.building == null)
		{
			reason = "invalid";
			return false;
		}
		if (failedFrontBuilding != null && building.Id == failedFrontBuilding.Id)
		{
			blockedAsFront = true;
			reason = "failed-front";
			return false;
		}
		if (IsRetaliationFrontAlreadyPending(defender, building, out _, out _))
		{
			reason = "pending-retaliation-action";
			return false;
		}
		if (building.components.building.IsSafehouse
			|| building.components.building.IsOutpost
			|| building.data?.building?.controlled?.Get().IsAnyPlayer == true)
		{
			blockedAsFront = true;
			reason = "front-or-owned-building";
			return false;
		}
		if (!TryValidateRetaliationImportantShopTarget(building, out Entity bizEntity, out string shopReason))
		{
			reason = shopReason;
			return false;
		}
		BizComponent biz = bizEntity.components.biz;
		NodeID buildingNodeId = building.data?.board?.bead.nodeId ?? NodeID.INVALID;
		Node buildingNode = buildingNodeId.IsValid ? buildingNodeId.FindNode() : null;
		PlayerID nodeOwner = buildingNode?.owner?.Get() ?? PlayerID.INVALID;
		if (nodeOwner == attacker.PID)
		{
			blockedByTerritory = true;
			reason = "attacker-territory";
			return false;
		}

		BizComponent.TradeRestrictions restrictions = biz.FindTradeRestrictions(attacker.PID);
		if (!IsForcedClosureRestrictionAllowedForRetaliation(restrictions, defender.PID, out reason))
		{
			blockedByLock = true;
			return false;
		}

		bool hasDefenderTrade = biz.HasAnyTradeHistory(defender.PID);
		bool defenderLocked = IsTradeRestrictedByDefender(restrictions, defender.PID);
		bool targetTerritory = nodeOwner == defender.PID || defenderLocked || hasDefenderTrade;
		if (!targetTerritory)
		{
			blockedByTerritory = true;
			reason = "not-defender-target";
			return false;
		}

		bool interesting = IsBusinessFallbackInterestingTarget(bizEntity, building, buildingNode);
		if (!hasDefenderTrade && !interesting)
		{
			reason = "not-important-shop";
			return false;
		}
		priority = hasDefenderTrade ? 0 : (defenderLocked ? 1 : 2);
		reason = hasDefenderTrade ? "defender-trade-history" : (defenderLocked ? "defender-locked-interesting-shop" : "defender-interesting-shop");
		return true;
	}

	private static bool IsTradeRestrictedByDefender(BizComponent.TradeRestrictions restrictions, PlayerID defenderPid)
	{
		if (!defenderPid.IsAnyPlayer)
		{
			return false;
		}
		return (restrictions.IsTerritoryLocked && restrictions.territoryLock == defenderPid)
			|| (restrictions.IsTiedHouseLocked && restrictions.tiedHouseLock == defenderPid);
	}

	private static bool IsBusinessFallbackInterestingTarget(Entity bizEntity, Entity building, Node buildingNode)
	{
		if (bizEntity?.components?.biz == null || building?.components?.building == null)
		{
			return false;
		}
		try
		{
			if (bizEntity.components.biz.HasInterestingModules() || HasInterestingModuleConfig(bizEntity))
			{
				return true;
			}
			return buildingNode?.interesting?.Contains(building.Id) == true
				|| buildingNode?.interesting?.Contains(bizEntity.Id) == true
				|| building.components.building.IsInteresting;
		}
		catch
		{
			return false;
		}
	}

	private static bool HasInterestingModuleConfig(Entity bizEntity)
	{
		try
		{
			foreach (Label module in bizEntity?.data?.biz?.modules ?? Enumerable.Empty<Label>())
			{
				IModuleConfig config = ModulesUtil.FindModuleDef(module);
				if (config == null)
				{
					continue;
				}
				PropertyInfo property = config.GetType().GetProperty("interesting", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				FieldInfo field = config.GetType().GetField("interesting", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				object value = property?.GetValue(config) ?? field?.GetValue(config);
				if (value is bool interesting && interesting)
				{
					return true;
				}
			}
		}
		catch
		{
		}
		return false;
	}

	private static bool TryResolveRuntimeCrewPhysicalNode(PlayerInfo player, CrewAssignment crew, Entity peep, out NodeID currentNodeId, out string currentNodeSource, string sourceTag, string context)
	{
		currentNodeId = NodeID.INVALID;
		currentNodeSource = "none";
		try
		{
			if (crew.IsValid && crew.IsInVehicle && crew.VehicleID.IsValid)
			{
				if (MultiCrewVehicleHelper.TryGetStrictPhysicalVehicleNode(crew.VehicleID, out Node vehicleNode, out string vehicleSource)
					&& vehicleNode?.id.IsValid == true)
				{
					currentNodeId = vehicleNode.id;
					currentNodeSource = "vehicle-physical-" + (vehicleSource ?? "strict");
					return true;
				}
				NodeID peepNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
				if (peepNodeId.IsValid)
				{
					currentNodeId = peepNodeId;
					currentNodeSource = "agent-physical-vehicle-fallback";
					VerificationLog("GangOps.FrontMovement", $"crew-physical-node-fallback player={player?.PID.id ?? 0} peep={crew.peepId.id} vehicle={crew.VehicleID.id} peepNode={peepNodeId} context={context} trigger={sourceTag}");
					return true;
				}
				VerificationLog("GangOps.FrontMovement", $"crew-physical-node-unavailable player={player?.PID.id ?? 0} peep={crew.peepId.id} vehicle={crew.VehicleID.id} peepNode={peepNodeId} context={context} trigger={sourceTag}");
				return false;
			}

			currentNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
			currentNodeSource = currentNodeId.IsValid ? "agent-physical" : "none";
			return currentNodeId.IsValid;
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontMovement", $"crew-physical-node-failed player={player?.PID.id ?? 0} peep={crew.peepId.id} vehicle={crew.VehicleID.id} context={context} reason={ex.GetType().Name}:{ex.Message} trigger={sourceTag}");
			return false;
		}
	}

	private static bool ShouldDelayHumanRetaliationFrontAction(PlayerInfo defender, string sourceTag)
	{
		return defender?.PID.IsHumanPlayer == true && !string.Equals(sourceTag, "vanilla-read-callback", StringComparison.Ordinal);
	}

	private static void MarkPendingRetaliationFrontDelayedPhysicalAction(EntityID buildingId, string targetKind, int notBeforeDay, string reason)
	{
		if (buildingId.IsNotValid)
		{
			return;
		}
		if (_pendingRetaliationFrontTickersByBuilding.TryGetValue(buildingId.id, out PendingRetaliationFrontTicker entry) && entry != null)
		{
			entry.DelayedPhysicalActionRequired = true;
			entry.DelayedPhysicalActionQueued = false;
			entry.DelayedPhysicalActionNotBeforeDay = notBeforeDay;
			entry.DelayedTargetKind = string.IsNullOrEmpty(targetKind) ? "outpost" : targetKind;
			entry.DelayedRouteLastIssuedDay = G.GetNow().days;
			entry.DelayedLastObservedNodeId = NodeID.INVALID;
			entry.DelayedRouteTargetNodeId = NodeID.INVALID;
			entry.DelayedFinalRouteIssuedFromNodeId = NodeID.INVALID;
			entry.DelayedNoProgressChecks = 0;
			entry.DelayedRouteRequeueCount = 0;
			VerificationLog("GangOps.FrontMovement", $"front-delayed-action-marked attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={buildingId.id} kind={entry.DelayedTargetKind} notBeforeDay={notBeforeDay} reason={reason}");
		}
	}

	private static void MarkPendingRetaliationFrontDelayedMultiTurnRoute(EntityID buildingId, string reason)
	{
		if (buildingId.IsNotValid)
		{
			return;
		}
		if (_pendingRetaliationFrontTickersByBuilding.TryGetValue(buildingId.id, out PendingRetaliationFrontTicker entry) && entry != null)
		{
			entry.DelayedMultiTurnHumanFrontRoute = true;
			VerificationLog("GangOps.FrontMovement", $"front-delayed-multiturn-marked attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={buildingId.id} reason={reason}");
		}
	}

	private static bool TryResolveRuntimeCrewCurrentNode(PlayerInfo player, CrewAssignment crew, Entity peep, out NodeID currentNodeId, out string currentNodeSource, bool syncVehicleCrew, string sourceTag, string context)
	{
		currentNodeId = NodeID.INVALID;
		currentNodeSource = "none";
		try
		{
			NodeID agentNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
			if (crew.IsValid && crew.IsInVehicle && crew.VehicleID.IsValid)
			{
				if (MultiCrewVehicleHelper.TryGetVehicleLiveAuthorityNodeId(crew.VehicleID, out NodeID liveVehicleNodeId, out string liveSource) && liveVehicleNodeId.IsValid)
				{
					currentNodeId = liveVehicleNodeId;
					currentNodeSource = "vehicle-" + (liveSource ?? "live");
				}
				else if (MultiCrewVehicleHelper.TryGetAuthoritativeVehicleNodeId(crew.VehicleID, out NodeID vehicleNodeId, out string authoritySource) && vehicleNodeId.IsValid)
				{
					currentNodeId = vehicleNodeId;
					currentNodeSource = "vehicle-" + (authoritySource ?? "authority");
				}
				if (currentNodeId.IsValid)
				{
					if (syncVehicleCrew && agentNodeId.IsValid && agentNodeId != currentNodeId)
					{
						bool synced = player?.crew != null
							? MultiCrewVehicleHelper.TrySyncVehicleOccupantsToNode(player.crew, crew.VehicleID, currentNodeId, "gangops-" + (context ?? "action"), syncVehicle: true)
							: false;
						if (!synced && peep != null)
						{
							global::Game.Game.ctx?.transit?.SetAgentAtNode(currentNodeId, peep);
							synced = true;
						}
						VerificationLog("GangOps.FrontMovement", $"crew-node-authority-synced player={player?.PID.id ?? 0} peep={crew.peepId.id} vehicle={crew.VehicleID.id} agentNode={agentNodeId} vehicleNode={currentNodeId} source={currentNodeSource} synced={synced} context={context} trigger={sourceTag}");
					}
					return true;
				}
			}
			currentNodeId = agentNodeId;
			currentNodeSource = agentNodeId.IsValid ? "agent" : "none";
			return currentNodeId.IsValid;
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontMovement", $"crew-node-resolve-failed player={player?.PID.id ?? 0} peep={crew.peepId.id} vehicle={crew.VehicleID.id} context={context} reason={ex.GetType().Name}:{ex.Message} trigger={sourceTag}");
			return false;
		}
	}

	private static class PlayerAIWillStealTickerPatch
	{
		private static readonly FieldInfo PlayerField = AccessTools.Field(typeof(PlayerSubmanager), "_player");

		public static void ApplyPatch(Harmony harmony)
		{
			try
			{
				MethodInfo method = typeof(PlayerAI).GetMethod("ReadCallback", BindingFlags.Instance | BindingFlags.Public, null, new[] { typeof(string), typeof(EntityID) }, null);
				if (method == null)
				{
					Debug.LogWarning("[GameplayTweaks] PlayerAI.ReadCallback not found for named front closure ticker");
					return;
				}
				harmony.Patch(method, prefix: new HarmonyMethod(typeof(PlayerAIWillStealTickerPatch), nameof(ReadCallbackPrefix)));
				VerificationLog("GangOps.FrontTicker", "hooked PlayerAI.ReadCallback will-steal named ticker");
			}
			catch (Exception ex)
			{
				Debug.LogWarning("[GameplayTweaks] PlayerAIWillStealTickerPatch failed: " + ex.Message);
			}
		}

		private static bool ReadCallbackPrefix(PlayerAI __instance, string message, EntityID building)
		{
			if (!string.Equals(message, "will-steal", StringComparison.Ordinal))
			{
				return true;
			}
			try
			{
				Entity targetBuilding = building.FindEntity();
				if (targetBuilding?.data?.building == null || !targetBuilding.data.building.outpost.IsHumanPlayer)
				{
					return false;
				}
				PlayerInfo attacker = PlayerField?.GetValue(__instance) as PlayerInfo;
				PlayerInfo defender = targetBuilding.data.building.outpost.FindPlayer();
				if (attacker == null || defender == null)
				{
					return true;
				}
				VerificationLog("GangOps.FrontTicker", $"vanilla-will-steal-pass-through attacker={attacker.PID.id} defender={defender.PID.id} building={building.id} result=base-ticker-only");
				return true;
			}
			catch (Exception ex)
			{
				VerificationLog("GangOps.FrontTicker", $"vanilla-will-steal-prefix-failed building={building.id} reason={ex.GetType().Name}:{ex.Message}");
				return true;
			}
		}
	}

	private static void ShowPendingRetaliationFrontTicker(PlayerInfo attacker, PlayerInfo defender, Entity targetBuilding, EntityID crewPeepId, NodeID targetNodeId, string mode, string sourceTag)
	{
		if (attacker == null || defender == null || targetBuilding == null || targetBuilding.Id.IsNotValid)
		{
			return;
		}
		if (!IsRetaliationOutpostFront(defender, targetBuilding))
		{
			return;
		}
		try
		{
			ulong key = targetBuilding.Id.id;
			bool showImmediateTicker = ShouldShowRetaliationFrontTickerImmediately(defender, mode, sourceTag);
			if (_pendingRetaliationFrontTickersByBuilding.TryGetValue(key, out PendingRetaliationFrontTicker existing)
				&& existing != null
				&& existing.DefenderPid == defender.PID
				&& existing.AttackerPid != attacker.PID
				&& defender.PID.IsHumanPlayer)
			{
				VerificationLog("GangOps.FrontTicker", $"retained-existing attacker={attacker.PID.id} defender={defender.PID.id} existingAttacker={existing.AttackerPid.id} existingPeep={existing.CrewPeepId.id} building={targetBuilding.Id.id} mode={mode} existingMode={existing.Mode} source={sourceTag}");
				return;
			}
			if (!showImmediateTicker
				&& defender.PID.IsHumanPlayer
				&& existing?.Ticker != null)
			{
				VerificationLog("GangOps.FrontTicker", $"retained-existing-visible attacker={attacker.PID.id} defender={defender.PID.id} existingAttacker={existing.AttackerPid.id} existingPeep={existing.CrewPeepId.id} building={targetBuilding.Id.id} mode={mode} existingMode={existing.Mode} source={sourceTag}");
				return;
			}
			ClearPendingRetaliationFrontTicker(key, "replace", sourceTag);
			TickerData ticker = null;
			if (defender.PID.IsHumanPlayer && showImmediateTicker)
			{
				ticker = CreateRetaliationFrontWarningTicker(attacker, targetBuilding, sourceTag);
				if (ticker != null)
				{
					var tickerBar = global::Game.Game.ctx?.hud?.tickers;
					if (tickerBar != null)
					{
						tickerBar.AddTicker(ticker);
					}
					else
					{
						ticker = null;
						VerificationLog("GangOps.FrontTicker", $"warning-deferred attacker={attacker.PID.id} defender={defender.PID.id} peep={crewPeepId.id} building={targetBuilding.Id.id} reason=hud-ticker-unavailable source={sourceTag}");
					}
				}
			}
			_pendingRetaliationFrontTickersByBuilding[key] = new PendingRetaliationFrontTicker
			{
				BuildingId = targetBuilding.Id,
				CrewPeepId = crewPeepId,
				AttackerPid = attacker.PID,
				DefenderPid = defender.PID,
				TargetNodeId = targetNodeId,
				Ticker = ticker,
				QueuedDay = G.GetNow().days,
				Mode = mode ?? string.Empty,
				Source = sourceTag ?? string.Empty
			};
			string uiMode = ticker != null ? "shown" : (defender.PID.IsHumanPlayer ? (showImmediateTicker ? "deferred-hud-unavailable" : "deferred-human-end-turn") : "hidden-ai-vs-ai");
			VerificationLog("GangOps.FrontTicker", $"{(ticker != null ? "shown" : "tracked")} attacker={attacker.PID.id} defender={defender.PID.id} peep={crewPeepId.id} building={targetBuilding.Id.id} node={targetNodeId} mode={mode} ui={uiMode} source={sourceTag}");
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontTicker", $"show-failed attacker={attacker.PID.id} defender={defender.PID.id} building={targetBuilding?.Id.id ?? 0UL} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
		}
	}

	private static void TrackPendingRetaliationForcedBusinessClosure(PlayerInfo attacker, PlayerInfo defender, Entity targetBuilding, EntityID crewPeepId, NodeID targetNodeId, string mode, string sourceTag, NodeID routeIssuedFromNodeId)
	{
		if (attacker == null || targetBuilding == null || targetBuilding.Id.IsNotValid || crewPeepId.IsNotValid)
		{
			return;
		}
		try
		{
			ulong key = targetBuilding.Id.id;
			ClearPendingRetaliationFrontTicker(key, "replace", sourceTag);
			_pendingRetaliationFrontTickersByBuilding[key] = new PendingRetaliationFrontTicker
			{
				BuildingId = targetBuilding.Id,
				CrewPeepId = crewPeepId,
				AttackerPid = attacker.PID,
				DefenderPid = defender?.PID ?? PlayerID.System,
				TargetNodeId = targetNodeId,
				DelayedRouteTargetNodeId = routeIssuedFromNodeId.IsValid ? targetNodeId : NodeID.INVALID,
				DelayedFinalRouteIssuedFromNodeId = routeIssuedFromNodeId.IsValid ? routeIssuedFromNodeId : NodeID.INVALID,
				DelayedRouteLastIssuedDay = routeIssuedFromNodeId.IsValid ? G.GetNow().days : int.MinValue,
				DelayedLastObservedNodeId = routeIssuedFromNodeId.IsValid ? routeIssuedFromNodeId : NodeID.INVALID,
				Ticker = null,
				QueuedDay = G.GetNow().days,
				Mode = mode ?? "forced-business-close",
				Source = sourceTag ?? string.Empty
			};
			VerificationLog("GangOps.FrontTicker", $"tracked-business-closure attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crewPeepId.id} building={targetBuilding.Id.id} node={targetNodeId} mode={mode} ui=hidden-business-closure source={sourceTag}");
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontTicker", $"track-business-closure-failed attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} building={targetBuilding?.Id.id ?? 0UL} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
		}
	}

	private static bool ShouldShowRetaliationFrontTickerImmediately(PlayerInfo defender, string mode, string sourceTag)
	{
		if (defender?.PID.IsHumanPlayer != true)
		{
			return false;
		}
		if (IsModQueuedHumanFrontClosureMode(mode, sourceTag))
		{
			return true;
		}
		if (!IsHumanTurnStartFrontTickerFlushSource(sourceTag))
		{
			return false;
		}
		if (IsVanillaWillStealTickerMode(mode) || string.Equals(sourceTag, "vanilla-read-callback", StringComparison.Ordinal))
		{
			return true;
		}
		return IsModQueuedHumanFrontClosureMode(mode, sourceTag);
	}

	private static bool IsHumanTurnStartFrontTickerFlushSource(string sourceTag)
	{
		return !string.IsNullOrWhiteSpace(sourceTag)
			&& sourceTag.StartsWith("human-turn-start-front", StringComparison.Ordinal);
	}

	private static bool IsModQueuedHumanFrontClosureMode(string mode, string sourceTag)
	{
		if (string.Equals(sourceTag, "vanilla-read-callback", StringComparison.Ordinal)
			|| (!IsHumanTurnStartFrontTickerFlushSource(sourceTag) && IsVanillaWillStealTickerMode(mode)))
		{
			return false;
		}
		return !string.IsNullOrEmpty(mode) && mode.IndexOf("front-steal", StringComparison.Ordinal) >= 0;
	}

	private static TickerData CreateRetaliationFrontWarningTicker(PlayerInfo attacker, Entity targetBuilding, string sourceTag = null)
	{
		if (attacker == null || targetBuilding == null || targetBuilding.Id.IsNotValid)
		{
			return null;
		}
		bool robberySource = IsRobberyRetaliationSource(sourceTag);
		string baseMessage = Loc.Get("ui.tickers.outpost.will-steal");
		string attackerName = attacker.social?.FindPlayerGroupNameColorized();
		if (string.IsNullOrWhiteSpace(attackerName))
		{
			attackerName = attacker.social?.PlayerGroupName ?? ("Gang#" + attacker.PID.id.ToString(CultureInfo.InvariantCulture));
		}
		string message;
		if (robberySource)
		{
			message = string.IsNullOrWhiteSpace(attackerName)
				? "COORDINATED PRESSURE: An enemy outfit is moving against this front after the robbery refusal."
				: "COORDINATED PRESSURE: " + attackerName + " is moving against this front after the robbery refusal.";
		}
		else
		{
			message = string.IsNullOrWhiteSpace(attackerName)
				? baseMessage
				: baseMessage + "\n" + attackerName + " is moving to close this front.";
		}
		return new TickerData
		{
			type = TickerType.TextPopup,
			icon = robberySource ? TickerIcon.GANG_ATTACK : TickerIcon.WILL_STEAL,
			title = robberySource ? TickerTitle.GANG_ATTACK : TickerTitle.DEFAULT,
			message = message,
			target = targetBuilding.Id,
			date = G.GetNow(),
			persisted = TickerPersistType.Persist
		};
	}

	private static bool TryShowRetaliationBusinessClosureCompletedNotice(PendingRetaliationFrontTicker entry, Entity building, PlayerID forcedClosedBy, string sourceTag)
	{
		if (entry == null || building == null || building.Id.IsNotValid)
		{
			return false;
		}
		try
		{
			PlayerInfo defender = entry.DefenderPid.IsAnyPlayer ? entry.DefenderPid.FindPlayer() : null;
			if (defender?.PID.IsHumanPlayer != true)
			{
				return false;
			}
			string attackerName = entry.AttackerPid.IsAnyPlayer
				? GetGangDisplayName(entry.AttackerPid.id)
				: "An enemy outfit";
			bool robberySource = IsRobberyRetaliationSource(entry.Source) || IsRobberyRetaliationSource(sourceTag);
			string message = robberySource
				? $"COORDINATED PRESSURE: {attackerName} followed through after the robbery refusal and forced an important shop to close."
				: $"WAR: {attackerName} forced one of your important shops to close.";
			message = CrewRelationshipHandlerPatch.SanitizeUiGlyphText(message, aggressive: true).Trim();
			if (string.IsNullOrWhiteSpace(message))
			{
				return false;
			}
			LogGrapevine(message);
			bool tickerShown = false;
			if (global::Game.Game.ctx?.hud?.tickers != null)
			{
				TickerIcon icon = robberySource ? TickerIcon.GANG_ATTACK : TickerIcon.WILL_STEAL;
				TickerTitle title = robberySource ? TickerTitle.GANG_ATTACK : TickerTitle.DEFAULT;
				global::Game.Game.ctx.hud.tickers.AddTextTicker(icon, title, message, building.Id, TickerPersistType.Persist);
				tickerShown = true;
			}
			VerificationLog("GangOps.FrontTicker", $"notice phase=business-closure-completed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} building={entry.BuildingId.id} forcedClosedBy={forcedClosedBy.id} robberySource={robberySource} tickerShown={tickerShown} source={sourceTag} result=shown");
			return true;
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontTicker", $"notice-failed phase=business-closure-completed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} building={entry.BuildingId.id} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static void ShowDeferredHumanRetaliationFrontTickersOnTurnStart(PlayerInfo humanPlayer, string sourceTag)
	{
		try
		{
			if (humanPlayer == null || _pendingRetaliationFrontTickersByBuilding.Count == 0)
			{
				return;
			}
			int nowDay = G.GetNow().days;
			int shown = 0;
			foreach (PendingRetaliationFrontTicker entry in _pendingRetaliationFrontTickersByBuilding.Values.ToList())
			{
				if (entry == null || entry.DefenderPid != humanPlayer.PID || entry.Ticker != null || entry.QueuedDay >= nowDay)
				{
					continue;
				}
				Entity building = entry.BuildingId.IsValid ? entry.BuildingId.FindEntity() : null;
				PlayerInfo attacker = entry.AttackerPid.IsAnyPlayer ? entry.AttackerPid.FindPlayer() : null;
				if (building?.data?.building == null || building.data.building.outpost != humanPlayer.PID || attacker == null)
				{
					continue;
				}
				if (!IsVanillaWillStealTickerMode(entry.Mode) && !IsModQueuedHumanFrontClosureMode(entry.Mode, "human-turn-start-front"))
				{
					continue;
				}
				TickerData ticker = CreateRetaliationFrontWarningTicker(attacker, building, entry.Source);
				if (ticker == null)
				{
					continue;
				}
				var tickerBar = global::Game.Game.ctx?.hud?.tickers;
				if (tickerBar == null)
				{
					VerificationLog("GangOps.FrontTicker", $"deferred-retry-wait attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} day={nowDay} reason=hud-ticker-unavailable source={sourceTag}");
					continue;
				}
				tickerBar.AddTicker(ticker);
				entry.Ticker = ticker;
				shown++;
				VerificationLog("GangOps.FrontTicker", $"shown-deferred attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} queuedDay={entry.QueuedDay} day={nowDay} mode={entry.Mode} source={sourceTag}");
			}
			if (shown > 0)
			{
				VerificationLog("GangOps.FrontTicker", $"deferred-turn-start-flush shown={shown} day={nowDay} source={sourceTag}");
			}
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontTicker", $"deferred-turn-start-flush-failed reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
		}
	}

	private static void CleanupPendingRetaliationFrontTickersOnTurnStart(string sourceTag)
	{
		try
		{
			int pendingCount = _pendingRetaliationFrontTickersByBuilding.Count;
			int nowDay = G.GetNow().days;
			bool shouldLog = pendingCount > 0
				|| _lastFrontTurnStartCleanupLogDay == int.MinValue
				|| nowDay - _lastFrontTurnStartCleanupLogDay >= 28;
			if (shouldLog)
			{
				_lastFrontTurnStartCleanupLogDay = nowDay;
				VerificationLog("GangOps.FrontTicker", $"front-cleanup-turn-start pending={pendingCount} day={nowDay} source={sourceTag}");
			}
			CleanupPendingRetaliationFrontTickers(sourceTag);
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontTicker", $"front-cleanup-turn-start-failed reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
		}
	}

	private static void CleanupPendingRetaliationFrontTickers(string sourceTag)
	{
		if (_pendingRetaliationFrontTickersByBuilding.Count == 0)
		{
			return;
		}
		List<ulong> keys = _pendingRetaliationFrontTickersByBuilding.Keys.ToList();
		foreach (ulong key in keys)
		{
			try
			{
				if (!_pendingRetaliationFrontTickersByBuilding.TryGetValue(key, out PendingRetaliationFrontTicker entry) || entry == null)
				{
					continue;
				}
				if (entry.BuildingId.IsNotValid)
				{
					ClearPendingRetaliationFrontTicker(key, "invalid-building", sourceTag);
					continue;
				}
				Entity building = entry.BuildingId.FindEntity();
				if (building == null)
				{
					ClearPendingRetaliationFrontTicker(key, "missing-building", sourceTag);
					continue;
				}
				if (IsPendingRetaliationForcedBusinessClosureMode(entry.Mode))
				{
					if (TryGetRetaliationBusinessForcedClosedBy(building, entry.AttackerPid, out PlayerID forcedClosedBy))
					{
						VerificationLog("GangOps.FrontMovement", $"business-closure-completed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} forcedClosedBy={forcedClosedBy.id} mode={entry.Mode} source={sourceTag}");
						ApplyRetaliationBusinessClosureWarHeat(entry, forcedClosedBy, sourceTag);
						TryShowRetaliationBusinessClosureCompletedNotice(entry, building, forcedClosedBy, sourceTag);
						ClearPendingRetaliationFrontTicker(key, "business-closure-completed", sourceTag);
						continue;
					}
					if (!IsPendingRetaliationFrontActionStillQueued(entry, building))
					{
						if (TryRecoverPendingRetaliationBusinessClosure(entry, building, sourceTag))
						{
							continue;
						}
						ClearPendingRetaliationFrontTicker(key, "business-closure-command-finished", sourceTag);
					}
					continue;
				}
				if (building.data?.building?.outpost != entry.DefenderPid)
				{
					int currentOwnerPid = building.data?.building != null ? building.data.building.outpost.id : 0;
					VerificationLog("GangOps.FrontMovement", $"front-closure-completed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentOwner={currentOwnerPid} reason=owner-changed-before-cleanup source={sourceTag}");
					ClearPendingRetaliationFrontTicker(key, "front-completed", sourceTag);
					continue;
				}
				if (entry.CrewPeepId.IsNotValid && IsVanillaWillStealTickerMode(entry.Mode))
				{
					VerificationLog("GangOps.FrontTicker", $"vanilla-passive-warning-cleared attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} building={entry.BuildingId.id} reason=no-physical-crew source={sourceTag}");
					ClearPendingRetaliationFrontTicker(key, "vanilla-passive-warning", sourceTag);
					continue;
				}
				if (entry.DelayedPhysicalActionRequired && !entry.DelayedPhysicalActionQueued)
				{
					bool delayedActionStillPending = TryQueueDelayedRetaliationFrontPhysicalAction(entry, building, sourceTag);
					if (entry.DelayedPhysicalActionQueued)
					{
						continue;
					}
					if (entry.DelayedPhysicalActionAbandoned)
					{
						int abandonedMaxDays = entry.DefenderPid.IsHumanPlayer
							? RETALIATION_FRONT_DELAYED_ACTION_MOVING_GIVE_UP_DAYS + ((entry.DelayedFinalApproachGraceGranted || entry.DelayedFinalApproachProgressObserved || entry.DelayedTerminalReassignmentGranted) ? RETALIATION_FRONT_DELAYED_ACTION_FINAL_GRACE_DAYS : 0)
							: RETALIATION_FRONT_DELAYED_ACTION_GIVE_UP_DAYS;
						VerificationLog("GangOps.FrontMovement", $"front-delayed-action-give-up attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} waitedDays={Mathf.Max(0, G.GetNow().days - entry.QueuedDay)} maxDays={abandonedMaxDays} reason={entry.DelayedPhysicalActionAbandonedReason ?? "abandoned"} source={sourceTag}");
						ClearPendingRetaliationFrontTicker(key, "attacker-gave-up-too-far", sourceTag);
						continue;
					}
					if (delayedActionStillPending)
					{
						if (HasDelayedRetaliationFrontActionTimedOut(entry, building, out int waitedDays, out int maxDays, out string timeoutReason))
						{
							VerificationLog("GangOps.FrontMovement", $"front-delayed-action-give-up attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} waitedDays={waitedDays} maxDays={maxDays} reason={timeoutReason} source={sourceTag}");
							ClearPendingRetaliationFrontTicker(key, "attacker-gave-up-too-far", sourceTag);
						}
						continue;
					}
					if (G.GetNow().days < entry.DelayedPhysicalActionNotBeforeDay || IsPendingRetaliationFrontActionStillQueued(entry, building))
					{
						continue;
					}
					if (HasDelayedRetaliationFrontActionTimedOut(entry, building, out int finalWaitedDays, out int finalMaxDays, out string finalTimeoutReason))
					{
						VerificationLog("GangOps.FrontMovement", $"front-delayed-action-give-up attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} waitedDays={finalWaitedDays} maxDays={finalMaxDays} reason={finalTimeoutReason} source={sourceTag}");
						ClearPendingRetaliationFrontTicker(key, "attacker-gave-up-too-far", sourceTag);
						continue;
					}
				}
				if (!IsPendingRetaliationFrontActionStillQueued(entry, building))
				{
					if (TryRecoverPendingRetaliationFrontTravel(entry, building, sourceTag))
					{
						continue;
					}
					ClearPendingRetaliationFrontTicker(key, "command-finished", sourceTag);
				}
			}
			catch (Exception ex)
			{
				_pendingRetaliationFrontTickersByBuilding.Remove(key);
				VerificationLog("GangOps.FrontTicker", $"cleanup-entry-failed building={key} remaining={_pendingRetaliationFrontTickersByBuilding.Count} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			}
		}
	}

	private static string MakeRetaliationFrontRetryKey(PlayerID attackerPid, PlayerID defenderPid, EntityID buildingId)
	{
		return attackerPid.id.ToString(CultureInfo.InvariantCulture)
			+ ":"
			+ defenderPid.id.ToString(CultureInfo.InvariantCulture)
			+ ":"
			+ buildingId.id.ToString(CultureInfo.InvariantCulture);
	}

	private static string MakeRetaliationFrontPairRetryKey(PlayerID attackerPid, PlayerID defenderPid)
	{
		return attackerPid.id.ToString(CultureInfo.InvariantCulture)
			+ ":"
			+ defenderPid.id.ToString(CultureInfo.InvariantCulture);
	}

	private static bool IsRetaliationFrontRetryBlocked(PlayerInfo attacker, PlayerInfo defender, Entity building, out int untilDay)
	{
		untilDay = int.MinValue;
		if (attacker == null || defender == null || building == null || building.Id.IsNotValid)
		{
			return false;
		}
		int today = G.GetNow().days;
		string pairKey = MakeRetaliationFrontPairRetryKey(attacker.PID, defender.PID);
		if (_retaliationFrontPairRetryBlockedUntilDayByKey.TryGetValue(pairKey, out int pairUntilDay))
		{
			if (pairUntilDay > today)
			{
				untilDay = pairUntilDay;
				return true;
			}
			_retaliationFrontPairRetryBlockedUntilDayByKey.Remove(pairKey);
		}
		string key = MakeRetaliationFrontRetryKey(attacker.PID, defender.PID, building.Id);
		if (!_retaliationFrontRetryBlockedUntilDayByKey.TryGetValue(key, out untilDay))
		{
			return false;
		}
		if (untilDay > today)
		{
			return true;
		}
		_retaliationFrontRetryBlockedUntilDayByKey.Remove(key);
		return false;
	}

	private static void BlockRetaliationFrontRetry(PlayerID attackerPid, PlayerID defenderPid, EntityID buildingId, EntityID crewPeepId, string reason, string sourceTag, int cooldownDays, string pacingDetails = null)
	{
		if (attackerPid.IsNotAnyPlayer || defenderPid.IsNotAnyPlayer || buildingId.IsNotValid)
		{
			return;
		}
		int untilDay = G.GetNow().days + Mathf.Max(1, cooldownDays);
		string key = MakeRetaliationFrontRetryKey(attackerPid, defenderPid, buildingId);
		string pairKey = MakeRetaliationFrontPairRetryKey(attackerPid, defenderPid);
		_retaliationFrontRetryBlockedUntilDayByKey[key] = untilDay;
		_retaliationFrontPairRetryBlockedUntilDayByKey[pairKey] = untilDay;
		VerificationLog("GangOps.FrontMovement", $"front-retry-cooldown attacker={attackerPid.id} defender={defenderPid.id} peep={(crewPeepId.IsValid ? crewPeepId.id : 0UL)} building={buildingId.id} untilDay={untilDay} cooldownDays={Mathf.Max(1, cooldownDays)} scope=building-and-pair reason={reason} source={sourceTag}{(string.IsNullOrWhiteSpace(pacingDetails) ? string.Empty : " " + pacingDetails)}");
	}

	private static void BlockRetaliationFrontRetry(PendingRetaliationFrontTicker entry, string reason, string sourceTag)
	{
		if (entry == null)
		{
			return;
		}
		int cooldownDays = GetWarHeatBasedFrontPressureCooldownDays(entry.AttackerPid, entry.DefenderPid, out string pacingDetails);
		BlockRetaliationFrontRetry(entry.AttackerPid, entry.DefenderPid, entry.BuildingId, entry.CrewPeepId, reason, sourceTag, cooldownDays, pacingDetails);
	}

	private static int GetWarHeatBasedFrontPressureCooldownDays(PlayerID attackerPid, PlayerID defenderPid, out string pacingDetails)
	{
		pacingDetails = "pacing=neutral-fallback";
		if (attackerPid.IsNotAnyPlayer || defenderPid.IsNotAnyPlayer)
		{
			return 35;
		}
		try
		{
			GangOpsChannel channel = ResolveGangOpsChannelForPair(attackerPid.id, defenderPid.id);
			PactOpsSettings settings = EnsureGangOpsSettings(channel);
			int configuredBaseDays = Mathf.Clamp(settings?.CoordinatedAttackCooldownDays ?? 16, 1, 180);
			int lowHeatDays = Mathf.Clamp(configuredBaseDays * 2, 28, 42);
			int highHeatDays = Mathf.Clamp(configuredBaseDays, 14, 28);
			float warHeat = GetWarHeat(channel, attackerPid.id, defenderPid.id);
			float revengeThreshold = Mathf.Max(1f, GetEffectiveWarHeatThresholdForRevenge(channel));
			PlayerInfo attacker = attackerPid.FindPlayer();
			PlayerInfo defender = defenderPid.FindPlayer();
			float effectiveWarHeat = GetRelationshipAdjustedWarHeat(channel, attacker, defender, warHeat, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool relationshipHostileBuff);
			float heatRatio = Mathf.Clamp01(effectiveWarHeat / revengeThreshold);
			bool peaceful = IsAiPersonalityPeaceful(attacker);
			bool isolationist = IsAiPersonalityIsolationist(attacker);
			bool aggressive = IsAiPersonalityAggressive(attacker);
			bool expansionist = IsAiPersonalityExpansionist(attacker);
			int cooldownDays = Mathf.RoundToInt(Mathf.Lerp(lowHeatDays, highHeatDays, heatRatio));
			cooldownDays += peaceful ? 14 : 0;
			cooldownDays += isolationist ? 7 : 0;
			cooldownDays -= aggressive ? 4 : 0;
			cooldownDays -= expansionist ? 7 : 0;
			cooldownDays -= relationshipHostility >= 0.55f ? 6 : (relationshipHostility >= 0.35f ? 3 : 0);
			cooldownDays = Mathf.Clamp(cooldownDays, RETALIATION_FRONT_RETRY_MIN_DAYS, RETALIATION_FRONT_RETRY_MAX_DAYS);
			pacingDetails = $"pacing=warheat heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} threshold={revengeThreshold:0.0} heatRatio={heatRatio:0.00} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff} peaceful={peaceful} isolationist={isolationist} aggressive={aggressive} expansionist={expansionist}";
			return cooldownDays;
		}
		catch (Exception ex)
		{
			pacingDetails = $"pacing=neutral-fallback reason={ex.GetType().Name}";
			return 35;
		}
	}

	private static bool IsVanillaWillStealTickerMode(string mode)
	{
		return string.Equals(mode, "vanilla-will-steal", StringComparison.Ordinal);
	}

	private static bool HasDelayedRetaliationFrontActionTimedOut(PendingRetaliationFrontTicker entry, Entity building, out int waitedDays, out int maxDays, out string reason)
	{
		waitedDays = 0;
		maxDays = RETALIATION_FRONT_DELAYED_ACTION_GIVE_UP_DAYS;
		reason = "not-moving";
		if (entry == null || !entry.DelayedPhysicalActionRequired || entry.DelayedPhysicalActionQueued)
		{
			return false;
		}
		waitedDays = Mathf.Max(0, G.GetNow().days - entry.QueuedDay);
		if (entry.DefenderPid.IsHumanPlayer)
		{
			bool extendedFinalWindow = entry.DelayedFinalApproachGraceGranted
				|| entry.DelayedFinalApproachProgressObserved
				|| entry.DelayedTerminalReassignmentGranted;
			maxDays = RETALIATION_FRONT_DELAYED_ACTION_MOVING_GIVE_UP_DAYS
				+ (extendedFinalWindow ? RETALIATION_FRONT_DELAYED_ACTION_FINAL_GRACE_DAYS : 0);
			reason = entry.DelayedMultiTurnHumanFrontRoute ? "human-multiturn-front-commitment" : "human-front-commitment";
		}
		bool recentlyIssuedRoute = entry.DelayedRouteLastIssuedDay != int.MinValue
			&& G.GetNow().days - entry.DelayedRouteLastIssuedDay <= RETALIATION_FRONT_DELAYED_ACTION_REQUEUE_COOLDOWN_DAYS;
		if (recentlyIssuedRoute)
		{
			if (!entry.DefenderPid.IsHumanPlayer)
			{
				maxDays = RETALIATION_FRONT_DELAYED_ACTION_MOVING_GIVE_UP_DAYS;
			}
			reason = "route-recently-issued";
			return false;
		}
		if (IsPendingRetaliationFrontActionStillQueued(entry, building))
		{
			if (!entry.DefenderPid.IsHumanPlayer)
			{
				maxDays = RETALIATION_FRONT_DELAYED_ACTION_MOVING_GIVE_UP_DAYS;
			}
			reason = "still-traveling";
		}
		return waitedDays >= maxDays;
	}

	private static bool TryReassignLostPendingRetaliationFrontAction(PendingRetaliationFrontTicker entry, PlayerInfo attacker, PlayerInfo defender, Entity building, Node targetNode, string sourceTag, float maxCrewDistance = AI_VS_HUMAN_FRONT_ACTION_MAX_CREW_DISTANCE, bool allowCapacityOverflow = false, bool forceTargetRoute = false)
	{
		if (entry == null || attacker?.commands == null || attacker.crew == null || defender?.PID.IsHumanPlayer != true || building == null || targetNode?.id.IsValid != true)
		{
			return false;
		}
		CrewAssignment replacement = FindRuntimeFrontActionCrew(attacker, building, targetNode, sourceTag, "front-lost-node-reassign", maxCrewDistance, out bool blockedByDistance, allowCapacityOverflow);
		if (!replacement.IsValid || replacement.peepId.IsNotValid || replacement.peepId == entry.CrewPeepId)
		{
			VerificationLog("GangOps.FrontMovement", $"front-delayed-action-reassign-unavailable attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} oldPeep={entry.CrewPeepId.id} building={entry.BuildingId.id} targetNode={targetNode.id} blockedByDistance={blockedByDistance} maxDistance={maxCrewDistance:0.0} capacityOverflowAllowed={allowCapacityOverflow} source={sourceTag}");
			return false;
		}
		Entity replacementPeep = replacement.GetPeep();
		if (replacementPeep?.data?.agent == null || replacementPeep.data.person == null || !replacementPeep.data.person.IsAlive)
		{
			VerificationLog("GangOps.FrontMovement", $"front-delayed-action-reassign-unavailable attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} oldPeep={entry.CrewPeepId.id} newPeep={replacement.peepId.id} building={entry.BuildingId.id} targetNode={targetNode.id} reason=replacement-invalid source={sourceTag}");
			return false;
		}
		TryResolveRuntimeCrewPhysicalNode(attacker, replacement, replacementPeep, out NodeID replacementNodeId, out string replacementNodeSource, sourceTag, "front-lost-node-reassign");
		if (!TryBuildRuntimeFrontApproachRoute(attacker.PID, replacementPeep, targetNode, out PathData replacementPath, out string replacementRouteReason))
		{
			VerificationLog("GangOps.FrontMovement", $"front-delayed-action-reassign-route-unavailable attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} oldPeep={entry.CrewPeepId.id} newPeep={replacement.peepId.id} building={entry.BuildingId.id} currentNode={replacementNodeId} currentSource={replacementNodeSource} targetNode={targetNode.id} reason={replacementRouteReason} source={sourceTag}");
			return false;
		}

		EntityID oldPeepId = entry.CrewPeepId;
		if (oldPeepId.IsValid)
		{
			attacker.commands.FlushQueue(oldPeepId, cancelActive: true);
		}
		attacker.commands.FlushQueue(replacement.peepId, cancelActive: true);
		Node replacementRouteNode = ResolveFrontRouteCommandNode(targetNode, replacementPath, allowSegmentTarget: !forceTargetRoute, out NodeID replacementRouteNodeId, out string replacementRouteGoal);
		if (replacementRouteNode?.id.IsValid != true)
		{
			replacementRouteNode = targetNode;
			replacementRouteNodeId = targetNode.id;
			replacementRouteGoal = "target-fallback";
		}
		attacker.commands.AddCommand(new CommandGoto(attacker.PID, replacement.peepId, replacementRouteNode));
		entry.CrewPeepId = replacement.peepId;
		entry.TargetNodeId = targetNode.id;
		MarkPendingRetaliationRouteTarget(entry, replacementRouteNodeId, targetNode.id, replacementNodeId);
		entry.DelayedPhysicalActionQueued = false;
		entry.DelayedPhysicalActionRequired = true;
		entry.DelayedPhysicalActionNotBeforeDay = G.GetNow().days + 1;
		entry.DelayedRouteLastIssuedDay = G.GetNow().days;
		entry.DelayedRouteRequeueCount = 1;
		entry.DelayedNoProgressChecks = 0;
		entry.DelayedLastObservedNodeId = replacementNodeId;
		entry.DelayedPhysicalActionAbandoned = false;
		entry.DelayedPhysicalActionAbandonedReason = null;
		VerificationLog("GangOps.FrontMovement", $"front-delayed-action-reassigned-lost-node attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} oldPeep={oldPeepId.id} newPeep={replacement.peepId.id} building={entry.BuildingId.id} currentNode={replacementNodeId} currentSource={replacementNodeSource} targetNode={targetNode.id} routeTargetNode={replacementRouteNodeId} routeGoal={replacementRouteGoal} forceTargetRoute={forceTargetRoute} route={replacementRouteReason} cost={(replacementPath != null ? replacementPath.cost.ToString() : "0")} capacityOverflowAllowed={allowCapacityOverflow} source={sourceTag}");
		return true;
	}

	private static void PruneExpiredHumanFrontDefenseCombatSuppressions(int nowDay)
	{
		if (_humanFrontDefenseCombatSuppressionsByPair.Count == 0)
		{
			return;
		}
		foreach (string key in _humanFrontDefenseCombatSuppressionsByPair
			.Where(pair => pair.Value == null || pair.Value.UntilDay < nowDay)
			.Select(pair => pair.Key)
			.ToList())
		{
			_humanFrontDefenseCombatSuppressionsByPair.Remove(key);
		}
	}

	private static void RegisterHumanFrontDefenseCombatSuppression(PendingRetaliationFrontTicker entry, PlayerInfo defender, CrewAssignment frontCloserCrew, IEnumerable<EntityID> blockers, Entity building, NodeID currentNodeId, string sourceTag)
	{
		if (entry == null || entry.AttackerPid.IsNotAnyPlayer || entry.DefenderPid.IsHumanPlayer != true || entry.DefenderPid != defender?.PID)
		{
			return;
		}
		try
		{
			int nowDay = G.GetNow().days;
			PruneExpiredHumanFrontDefenseCombatSuppressions(nowDay);
			ulong defenderVehicleId = 0UL;
			string blockerIds = string.Empty;
			if (blockers != null)
			{
				List<EntityID> blockerList = blockers.Where(blockerId => blockerId.IsValid).ToList();
				blockerIds = string.Join(",", blockerList.Select(blockerId => blockerId.id.ToString(CultureInfo.InvariantCulture)));
				if (defender?.crew != null)
				{
					foreach (EntityID blockerId in blockerList)
					{
						CrewAssignment blockerCrew = defender.crew.GetCrewForPeep(blockerId);
						if (blockerCrew.IsValid && blockerCrew.VehicleID.IsValid)
						{
							defenderVehicleId = blockerCrew.VehicleID.id;
							break;
						}
					}
				}
			}
			HumanFrontDefenseCombatSuppression suppression = new HumanFrontDefenseCombatSuppression
			{
				AttackerPid = entry.AttackerPid.id,
				DefenderPid = entry.DefenderPid.id,
				CreatedDay = nowDay,
				UntilDay = nowDay + HUMAN_FRONT_DEFENSE_COMBAT_SUPPRESSION_DAYS,
				BuildingId = building?.Id.id ?? entry.BuildingId.id,
				FrontCloserPeepId = entry.CrewPeepId.IsValid ? entry.CrewPeepId.id : (frontCloserCrew.IsValid ? frontCloserCrew.peepId.id : 0UL),
				FrontCloserVehicleId = frontCloserCrew.IsValid && frontCloserCrew.VehicleID.IsValid ? frontCloserCrew.VehicleID.id : 0UL,
				DefenderVehicleId = defenderVehicleId,
				BlockerIds = blockerIds,
				Source = sourceTag ?? string.Empty
			};
			_humanFrontDefenseCombatSuppressionsByPair[MakeGangPairKey(suppression.AttackerPid, suppression.DefenderPid)] = suppression;
			VerificationLog("VehicleGroupCombat.AI", $"front-defense-suppression-registered attacker={suppression.AttackerPid} defender={suppression.DefenderPid} peep={suppression.FrontCloserPeepId} attackerVehicle={suppression.FrontCloserVehicleId} defenderVehicle={suppression.DefenderVehicleId} building={suppression.BuildingId} node={currentNodeId} untilDay={suppression.UntilDay} blockers={suppression.BlockerIds} source={sourceTag}");
		}
		catch (Exception ex)
		{
			VerificationLog("VehicleGroupCombat.AI", $"front-defense-suppression-register-failed attacker={entry?.AttackerPid.id ?? 0} defender={entry?.DefenderPid.id ?? 0} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
		}
	}

	internal static bool ShouldSuppressIncomingAiCombatAfterRecentHumanFrontDefense(PlayerID attackerPid, PlayerID targetPid, EntityID attackerVehicleId, EntityID targetVehicleId, out string reason)
	{
		reason = null;
		if (attackerPid.IsNotAnyPlayer || targetPid.IsHumanPlayer != true)
		{
			return false;
		}
		try
		{
			PlayerID currentPlayer = global::Game.Game.ctx?.clock?.CurrentPlayer ?? PlayerID.INVALID;
			if (!currentPlayer.IsHumanPlayer)
			{
				return false;
			}
			int nowDay = G.GetNow().days;
			PruneExpiredHumanFrontDefenseCombatSuppressions(nowDay);
			string key = MakeGangPairKey(attackerPid.id, targetPid.id);
			if (!_humanFrontDefenseCombatSuppressionsByPair.TryGetValue(key, out HumanFrontDefenseCombatSuppression suppression) || suppression == null)
			{
				return false;
			}
			if (suppression.UntilDay < nowDay)
			{
				_humanFrontDefenseCombatSuppressionsByPair.Remove(key);
				return false;
			}
			bool sameFrontCloserVehicle = suppression.FrontCloserVehicleId != 0UL
				&& attackerVehicleId.IsValid
				&& suppression.FrontCloserVehicleId == attackerVehicleId.id;
			bool sameDefenderVehicle = suppression.DefenderVehicleId != 0UL
				&& targetVehicleId.IsValid
				&& suppression.DefenderVehicleId == targetVehicleId.id;
			if (!sameFrontCloserVehicle && !sameDefenderVehicle)
			{
				return false;
			}
			reason = $"front-defense-human-turn-cooldown untilDay={suppression.UntilDay} createdDay={suppression.CreatedDay} currentPlayer={currentPlayer.id} frontCloser={suppression.FrontCloserPeepId} frontCloserVehicle={suppression.FrontCloserVehicleId} defenderVehicle={suppression.DefenderVehicleId} attackerVehicle={attackerVehicleId.id} targetVehicle={targetVehicleId.id} building={suppression.BuildingId} sameFrontCloserVehicle={sameFrontCloserVehicle} sameDefenderVehicle={sameDefenderVehicle}";
			return true;
		}
		catch (Exception ex)
		{
			VerificationLog("VehicleGroupCombat.AI", $"front-defense-suppression-check-failed attacker={attackerPid.id} defender={targetPid.id} reason={ex.GetType().Name}:{ex.Message}");
			return false;
		}
	}

	internal static bool ShouldSuppressIncomingAiCombatDuringPendingHumanRetaliationRoute(PlayerID attackerPid, PlayerID targetPid, EntityID attackerPeepId, EntityID attackerVehicleId, EntityID targetVehicleId, out string reason)
	{
		reason = null;
		if (attackerPid.IsNotAnyPlayer || targetPid.IsHumanPlayer != true)
		{
			return false;
		}
		try
		{
			PlayerID currentPlayer = global::Game.Game.ctx?.clock?.CurrentPlayer ?? PlayerID.INVALID;
			if (!currentPlayer.IsHumanPlayer)
			{
				return false;
			}
			foreach (PendingRetaliationFrontTicker entry in _pendingRetaliationFrontTickersByBuilding.Values.ToList())
			{
				if (entry == null
					|| entry.AttackerPid != attackerPid
					|| entry.DefenderPid != targetPid
					|| entry.CrewPeepId.IsNotValid
					|| entry.DelayedPhysicalActionAbandoned)
				{
					continue;
				}
				bool pendingFrontClosure = string.Equals(GetPendingRetaliationTargetKind(entry), "outpost", StringComparison.Ordinal)
					|| IsPendingRetaliationGotoFrontMode(entry.Mode);
				bool pendingBusinessClosure = IsPendingRetaliationForcedBusinessClosureMode(entry.Mode);
				if (!pendingFrontClosure && !pendingBusinessClosure)
				{
					continue;
				}
				PlayerInfo attacker = attackerPid.FindPlayer();
				CrewAssignment routeCrew = attacker?.crew != null ? attacker.crew.GetCrewForPeep(entry.CrewPeepId) : CrewAssignment.EMPTY;
				bool samePeep = attackerPeepId.IsValid && attackerPeepId == entry.CrewPeepId;
				bool sameVehicle = attackerVehicleId.IsValid && routeCrew.IsValid && routeCrew.VehicleID == attackerVehicleId;
				if (!samePeep && !sameVehicle)
				{
					continue;
				}
				string actionKind = pendingBusinessClosure ? "business-closure" : "front-closure";
				reason = $"pending-retaliation-route-human-turn kind={actionKind} building={entry.BuildingId.id} peep={entry.CrewPeepId.id} mode={entry.Mode} currentPlayer={currentPlayer.id} targetNode={entry.TargetNodeId} routeNode={entry.DelayedRouteTargetNodeId} routeIssuedDay={entry.DelayedRouteLastIssuedDay} attackerVehicle={attackerVehicleId.id} targetVehicle={targetVehicleId.id}";
				return true;
			}
		}
		catch (Exception ex)
		{
			VerificationLog("VehicleGroupCombat.AI", $"pending-route-suppression-check-failed attacker={attackerPid.id} defender={targetPid.id} peep={attackerPeepId.id} vehicle={attackerVehicleId.id} reason={ex.GetType().Name}:{ex.Message}");
		}
		return false;
	}

	private static bool TryTriggerHumanFrontDefenseAggroAttack(PendingRetaliationFrontTicker entry, PlayerInfo attacker, PlayerInfo defender, CrewAssignment frontCloserCrew, Entity building, NodeID currentNodeId, string sourceTag)
	{
		if (entry == null || defender?.PID.IsHumanPlayer != true || attacker?.ai?.attack == null || !frontCloserCrew.IsValid || frontCloserCrew.peepId.IsNotValid)
		{
			return false;
		}
		try
		{
			Node attackNode = currentNodeId.IsValid ? currentNodeId.FindNode() : null;
			if (attackNode?.id.IsValid != true)
			{
				NodeID buildingNodeId = building?.data?.board?.bead.nodeId ?? NodeID.INVALID;
				attackNode = buildingNodeId.IsValid ? buildingNodeId.FindNode() : null;
			}
			if (attackNode?.id.IsValid != true)
			{
				VerificationLog("GangOps.FrontMovement", $"front-defended-aggro-skip attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} reason=no-node source={sourceTag}");
				return false;
			}

			AttackAdvisor attackAdvisor = attacker.ai.attack;
			Entity target = attackAdvisor.FindFirstAggroTargetAt(attackNode, attackNode);
			if (target == null || target.Id.IsNotValid || !attackAdvisor.CanAttackForAggro(target))
			{
				VerificationLog("GangOps.FrontMovement", $"front-defended-aggro-skip attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} node={attackNode.id} reason=no-aggro-target source={sourceTag}");
				return false;
			}

			PlayerInfo targetPlayer = target.data?.agent?.pid.IsAnyPlayer == true ? target.data.agent.pid.FindPlayer() : null;
			CrewAssignment targetCrew = targetPlayer?.crew != null ? targetPlayer.crew.GetCrewForPeep(target.Id) : CrewAssignment.EMPTY;
			if (!targetCrew.IsValid || targetCrew.peepId.IsNotValid)
			{
				VerificationLog("GangOps.FrontMovement", $"front-defended-aggro-skip attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} node={attackNode.id} target={target.Id.id} reason=invalid-target-crew source={sourceTag}");
				return false;
			}

			CombatManager combat = global::Game.Game.ctx?.simman?.combat;
			if (combat == null)
			{
				VerificationLog("GangOps.FrontMovement", $"front-defended-aggro-skip attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} node={attackNode.id} target={target.Id.id} reason=no-combat-manager source={sourceTag}");
				return false;
			}

			bool previousBypass = _frontDefenseAggroCombatBypassActive;
			_frontDefenseAggroCombatBypassActive = true;
			try
			{
				combat.PerformAICombat(frontCloserCrew, targetCrew);
			}
			finally
			{
				_frontDefenseAggroCombatBypassActive = previousBypass;
			}
			VerificationLog("GangOps.FrontMovement", $"front-defended-aggro-attack attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={frontCloserCrew.peepId.id} vehicle={(frontCloserCrew.VehicleID.IsValid ? frontCloserCrew.VehicleID.id : 0UL)} building={entry.BuildingId.id} node={attackNode.id} targetPeep={targetCrew.peepId.id} targetVehicle={(targetCrew.VehicleID.IsValid ? targetCrew.VehicleID.id : 0UL)} source={sourceTag}");
			return true;
		}
		catch (Exception ex)
		{
			_frontDefenseAggroCombatBypassActive = false;
			VerificationLog("GangOps.FrontMovement", $"front-defended-aggro-failed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static bool TryResolvePendingRetaliationOutpostClosureAtTarget(PendingRetaliationFrontTicker entry, PlayerInfo attacker, PlayerInfo defender, CrewAssignment crew, Entity building, NodeID currentNodeId, string currentNodeSource, string sourceTag, string completionReason = "arrival-direct-outpost-steal", string defendedReason = "rival-blocking")
	{
		if (entry == null || attacker == null || defender?.outposts == null || !crew.IsValid || crew.peepId.IsNotValid || building?.data?.building == null || building.components?.building == null)
		{
			return false;
		}
		if (!string.Equals(GetPendingRetaliationTargetKind(entry), "outpost", StringComparison.Ordinal))
		{
			return false;
		}
		try
		{
			OutpostID outpostId = new OutpostID(building);
			if (building.data.building.outpost != defender.PID || defender.outposts.GetOutpostEntryUnsafe(outpostId) == null)
			{
				entry.Mode = "front-steal-direct-already-resolved";
				VerificationLog("GangOps.FrontMovement", $"front-closure-completed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} reason=outpost-entry-already-missing source={sourceTag}");
				ClearPendingRetaliationFrontTicker(building.Id.id, "front-completed", sourceTag);
				return true;
			}

			BuildingAndBusinessData buildingData = BuildingUtil.FindDataForBuilding(building);
			if (buildingData.building == null)
			{
				VerificationLog("GangOps.FrontMovement", $"front-closure-direct-failed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} reason=no-building-data source={sourceTag}");
				return false;
			}

			VisitState visitState = new VisitState(CrewAssignment.EMPTY, buildingData, G.GetNow(), attacker.PID);
			List<EntityID> blockers = BoardUtil.RivalBlocking(visitState);
			if (blockers != null && blockers.Count != 0)
			{
				foreach (EntityID blockerId in blockers)
				{
					try
					{
						blockerId.FindEntity()?.components?.agent?.IncrementStat(CrewStats.FrontsProtected, 1);
					}
					catch
					{
					}
				}
				entry.Mode = "front-steal-direct-defended";
				string blockerList = string.Join(",", blockers.Select(blockerId => blockerId.id.ToString(CultureInfo.InvariantCulture)));
				VerificationLog("GangOps.FrontMovement", $"front-defended attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} blockers={blockers.Count} blockerIds={blockerList} reason={defendedReason} source={sourceTag}");
				RegisterHumanFrontDefenseCombatSuppression(entry, defender, crew, blockers, building, currentNodeId, sourceTag);
				TryTriggerHumanFrontDefenseAggroAttack(entry, attacker, defender, crew, building, currentNodeId, sourceTag);
				ClearPendingRetaliationFrontTicker(building.Id.id, "front-defended", sourceTag);
				return true;
			}

			defender.outposts.RemoveOutpost(outpostId, PlayerOutposts.RemovalReason.Stolen, attacker.PID, crew.peepId, removeMeAsNodeOwner: true);
			bool stillOwned = building.data?.building?.outpost == defender.PID && defender.outposts.GetOutpostEntryUnsafe(outpostId) != null;
			if (!stillOwned)
			{
				entry.Mode = "front-steal-direct-completed";
				VerificationLog("GangOps.FrontMovement", $"front-closure-completed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} reason={completionReason} source={sourceTag}");
				ClearPendingRetaliationFrontTicker(building.Id.id, "front-completed", sourceTag);
				return true;
			}

			VerificationLog("GangOps.FrontMovement", $"front-closure-direct-failed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} reason=outpost-still-owned source={sourceTag}");
			return false;
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontMovement", $"front-closure-direct-failed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static bool TryQueueDelayedRetaliationFrontPhysicalAction(PendingRetaliationFrontTicker entry, Entity building, string sourceTag)
	{
		if (entry == null || !entry.DelayedPhysicalActionRequired || entry.DelayedPhysicalActionQueued)
		{
			return false;
		}
		int nowDay = G.GetNow().days;
		if (nowDay < entry.DelayedPhysicalActionNotBeforeDay)
		{
			return true;
		}
		PlayerInfo attacker = entry.AttackerPid.FindPlayer();
		PlayerInfo defender = entry.DefenderPid.FindPlayer();
		if (attacker?.commands == null || attacker.crew == null || defender == null || building?.components?.building == null)
		{
			return false;
		}
		NodeID targetNodeId = entry.TargetNodeId.IsValid ? entry.TargetNodeId : (building.data?.board?.bead.nodeId ?? NodeID.INVALID);
		Node targetNode = targetNodeId.IsValid ? targetNodeId.FindNode() : null;
		if (targetNode?.id.IsValid != true)
		{
			return false;
		}
		CrewAssignment crew = attacker.crew.GetCrewForPeep(entry.CrewPeepId);
		if (!crew.IsValid || crew.peepId.IsNotValid)
		{
			if (TryReassignLostPendingRetaliationFrontAction(entry, attacker, defender, building, targetNode, sourceTag))
			{
				return true;
			}
			VerificationLog("GangOps.FrontMovement", $"front-delayed-action-wait attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} reason=no-crew source={sourceTag}");
			return false;
		}
		Entity peep = crew.GetPeep();
		TryResolveRuntimeCrewPhysicalNode(attacker, crew, peep, out NodeID currentNodeId, out string currentNodeSource, sourceTag, "front-delayed-action");
		if (!currentNodeId.IsValid || currentNodeId != targetNode.id)
		{
			NodeID peepNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
			if (peepNodeId.IsValid && peepNodeId == targetNode.id)
			{
				currentNodeId = peepNodeId;
				currentNodeSource = string.IsNullOrEmpty(currentNodeSource) || string.Equals(currentNodeSource, "none", StringComparison.Ordinal)
					? "agent-at-front-after-travel"
					: currentNodeSource + ":agent-at-front-after-travel";
				VerificationLog("GangOps.FrontMovement", $"front-delayed-action-agent-fallback attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} targetNode={targetNode.id} source={sourceTag}");
			}
			else
			{
				bool defenderIsHuman = defender?.PID.IsHumanPlayer == true;
				if (currentNodeId.IsValid)
				{
					if (entry.DelayedLastObservedNodeId.IsValid && entry.DelayedLastObservedNodeId == currentNodeId)
					{
						entry.DelayedNoProgressChecks++;
					}
					else
					{
						entry.DelayedLastObservedNodeId = currentNodeId;
						entry.DelayedNoProgressChecks = 0;
					}
				}
				int waitedDays = Mathf.Max(0, nowDay - entry.QueuedDay);
				bool longHumanFrontRoute = defenderIsHuman;
				int maxNoProgressChecks = longHumanFrontRoute ? int.MaxValue : 2;
				int maxRouteRequeues = longHumanFrontRoute ? RETALIATION_FRONT_DELAYED_ACTION_HUMAN_MAX_REQUEUES : 2;
				if (TryResolvePendingRetaliationOutpostClosureByRouteCommitment(entry, attacker, defender, crew, building, targetNode, currentNodeId, currentNodeSource, waitedDays, sourceTag))
				{
					return true;
				}
				bool extendedFinalWindow = entry.DelayedFinalApproachGraceGranted
					|| entry.DelayedFinalApproachProgressObserved
					|| entry.DelayedTerminalReassignmentGranted;
				int maxWaitDays = longHumanFrontRoute
					? RETALIATION_FRONT_DELAYED_ACTION_MOVING_GIVE_UP_DAYS + (extendedFinalWindow ? RETALIATION_FRONT_DELAYED_ACTION_FINAL_GRACE_DAYS : 0)
					: RETALIATION_FRONT_DELAYED_ACTION_GIVE_UP_DAYS;
				bool humanRouteLimitReached = defenderIsHuman && entry.DelayedRouteRequeueCount >= maxRouteRequeues;
				bool humanWaitLimitReached = defenderIsHuman && waitedDays >= maxWaitDays;
				bool lostPhysicalNodeAtLimit = defenderIsHuman && !currentNodeId.IsValid && !peepNodeId.IsValid && (humanRouteLimitReached || humanWaitLimitReached);
				if ((humanRouteLimitReached || humanWaitLimitReached)
					&& !entry.DelayedFinalApproachGraceGranted
					&& TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, targetNode, out PathData limitGracePath, out string limitGraceReason))
				{
					attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
					Node limitGraceRouteNode = ResolveFrontRouteCommandNode(targetNode, limitGracePath, allowSegmentTarget: false, out NodeID limitGraceRouteNodeId, out string limitGraceRouteGoal);
					if (limitGraceRouteNode?.id.IsValid != true)
					{
						limitGraceRouteNode = targetNode;
						limitGraceRouteNodeId = targetNode.id;
						limitGraceRouteGoal = "target-fallback";
					}
					attacker.commands.AddCommand(new CommandGoto(attacker.PID, entry.CrewPeepId, limitGraceRouteNode));
					int oldRequeues = entry.DelayedRouteRequeueCount;
					MarkPendingRetaliationRouteTarget(entry, limitGraceRouteNodeId, targetNode.id, currentNodeId);
					entry.Mode = humanWaitLimitReached ? "front-delayed-action-wait-limit-grace" : "front-delayed-action-requeue-limit-grace";
					entry.DelayedRouteLastIssuedDay = nowDay;
					entry.DelayedRouteRequeueCount = Mathf.Min(entry.DelayedRouteRequeueCount, RETALIATION_FRONT_DELAYED_ACTION_HUMAN_ROUTE_COMMIT_REQUEUES);
					entry.DelayedNoProgressChecks = 0;
					entry.DelayedLastObservedNodeId = currentNodeId;
					entry.DelayedFinalApproachGraceGranted = true;
					VerificationLog("GangOps.FrontMovement", $"front-delayed-action-limit-grace attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} routeTargetNode={limitGraceRouteNodeId} routeGoal={limitGraceRouteGoal} waitedDays={waitedDays} oldRequeues={oldRequeues} requeues={entry.DelayedRouteRequeueCount} maxRequeues={maxRouteRequeues} maxWaitDays={maxWaitDays} graceDays={RETALIATION_FRONT_DELAYED_ACTION_FINAL_GRACE_DAYS} reason={(humanWaitLimitReached ? "wait-limit" : "requeue-limit")} route={limitGraceReason} cost={limitGracePath.cost} source={sourceTag}");
					return true;
				}
				bool terminalReassignmentAvailable = humanWaitLimitReached && !entry.DelayedTerminalReassignmentGranted;
				float reassignmentMaxCrewDistance = terminalReassignmentAvailable
					? AI_VS_HUMAN_FRONT_ACTION_TERMINAL_REASSIGN_MAX_CREW_DISTANCE
					: AI_VS_HUMAN_FRONT_ACTION_MAX_CREW_DISTANCE;
				if ((terminalReassignmentAvailable || lostPhysicalNodeAtLimit)
					&& TryReassignLostPendingRetaliationFrontAction(entry, attacker, defender, building, targetNode, sourceTag, reassignmentMaxCrewDistance, allowCapacityOverflow: terminalReassignmentAvailable, forceTargetRoute: terminalReassignmentAvailable))
				{
					if (humanWaitLimitReached)
					{
						entry.DelayedTerminalReassignmentGranted = true;
						entry.QueuedDay = nowDay - RETALIATION_FRONT_DELAYED_ACTION_MOVING_GIVE_UP_DAYS;
						if (TryBuildRuntimeFrontApproachRoute(attacker.PID, entry.CrewPeepId.FindEntity(), targetNode, out PathData terminalPath, out string terminalReason))
						{
							attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
							Node terminalRouteNode = ResolveFrontRouteCommandNode(targetNode, terminalPath, allowSegmentTarget: false, out NodeID terminalRouteNodeId, out string terminalRouteGoal);
							if (terminalRouteNode?.id.IsValid != true)
							{
								terminalRouteNode = targetNode;
								terminalRouteNodeId = targetNode.id;
								terminalRouteGoal = "target-fallback";
							}
							attacker.commands.AddCommand(new CommandGoto(attacker.PID, entry.CrewPeepId, terminalRouteNode));
							MarkPendingRetaliationRouteTarget(entry, terminalRouteNodeId, targetNode.id, entry.DelayedLastObservedNodeId);
							entry.DelayedRouteLastIssuedDay = nowDay;
							VerificationLog("GangOps.FrontMovement", $"front-delayed-action-terminal-target-route attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} targetNode={targetNode.id} routeTargetNode={terminalRouteNodeId} routeGoal={terminalRouteGoal} route={terminalReason} cost={(terminalPath != null ? terminalPath.cost.ToString() : "0")} source={sourceTag}");
						}
					}
					VerificationLog("GangOps.FrontMovement", $"front-delayed-action-limit-reassigned attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} requeues={entry.DelayedRouteRequeueCount} maxRequeues={maxRouteRequeues} maxWaitDays={maxWaitDays} maxCrewDistance={reassignmentMaxCrewDistance:0.0} capacityOverflowAllowed={terminalReassignmentAvailable} terminalWindowDays={(humanWaitLimitReached ? RETALIATION_FRONT_DELAYED_ACTION_FINAL_GRACE_DAYS : 0)} reason={(humanWaitLimitReached ? (lostPhysicalNodeAtLimit ? "wait-limit-lost-node" : "wait-limit-stalled-actor") : "requeue-limit-lost-node")} source={sourceTag}");
					return true;
				}
				bool humanRequeueAbandonReached = humanRouteLimitReached && !entry.DelayedFinalApproachGraceGranted;
				bool humanAbandonReached = defenderIsHuman
					&& (entry.DelayedNoProgressChecks >= maxNoProgressChecks || humanRequeueAbandonReached || waitedDays >= maxWaitDays);
				if (humanAbandonReached)
				{
					attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
					entry.DelayedPhysicalActionAbandoned = true;
					entry.DelayedPhysicalActionAbandonedReason = entry.DelayedNoProgressChecks >= maxNoProgressChecks ? "human-front-route-stalled" : (humanRequeueAbandonReached ? "human-front-route-requeue-limit" : "human-front-route-timeout");
					VerificationLog("GangOps.FrontMovement", $"front-delayed-action-abandoned attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} noProgressChecks={entry.DelayedNoProgressChecks} requeues={entry.DelayedRouteRequeueCount} maxNoProgress={maxNoProgressChecks} maxRequeues={maxRouteRequeues} maxWaitDays={maxWaitDays} multiTurn={entry.DelayedMultiTurnHumanFrontRoute} longHuman={longHumanFrontRoute} reason={entry.DelayedPhysicalActionAbandonedReason} source={sourceTag}");
					return false;
				}
				VerificationLog("GangOps.FrontMovement", $"front-delayed-action-wait attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} reason=not-physically-at-front source={sourceTag}");
				bool routeReissueCooldownActive = entry.DelayedRouteLastIssuedDay != int.MinValue
					&& nowDay - entry.DelayedRouteLastIssuedDay < RETALIATION_FRONT_DELAYED_ACTION_REQUEUE_COOLDOWN_DAYS;
				bool actionStillQueued = IsPendingRetaliationFrontActionStillQueued(entry, building);
				if (actionStillQueued)
				{
					if (!longHumanFrontRoute || entry.DelayedNoProgressChecks < 3 || routeReissueCooldownActive)
					{
						return true;
					}
					if (entry.DelayedRouteRequeueCount >= maxRouteRequeues)
					{
						return true;
					}
					if (TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, targetNode, out PathData stalledRetryPath, out string stalledRetryReason))
					{
						int stalledNoProgressChecks = entry.DelayedNoProgressChecks;
						attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
						Node stalledRouteNode = ResolveFrontRouteCommandNode(targetNode, stalledRetryPath, allowSegmentTarget: defenderIsHuman && ShouldAllowDelayedHumanFrontSegmentTarget(entry), out NodeID stalledRouteNodeId, out string stalledRouteGoal);
						if (stalledRouteNode?.id.IsValid != true)
						{
							stalledRouteNode = targetNode;
							stalledRouteNodeId = targetNode.id;
							stalledRouteGoal = "target-fallback";
						}
						attacker.commands.AddCommand(new CommandGoto(attacker.PID, entry.CrewPeepId, stalledRouteNode));
						MarkPendingRetaliationRouteTarget(entry, stalledRouteNodeId, targetNode.id, currentNodeId);
						entry.DelayedRouteLastIssuedDay = nowDay;
						entry.DelayedRouteRequeueCount++;
						entry.DelayedNoProgressChecks = 0;
						entry.DelayedLastObservedNodeId = currentNodeId;
						VerificationLog("GangOps.FrontMovement", $"front-delayed-action-reissued-stalled-human attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} targetNode={targetNode.id} routeTargetNode={stalledRouteNodeId} routeGoal={stalledRouteGoal} route={stalledRetryReason} cost={stalledRetryPath.cost} cooldownDays={RETALIATION_FRONT_DELAYED_ACTION_REQUEUE_COOLDOWN_DAYS} requeues={entry.DelayedRouteRequeueCount} noProgressChecks={stalledNoProgressChecks} multiTurn={entry.DelayedMultiTurnHumanFrontRoute} source={sourceTag}");
						return true;
					}
					VerificationLog("GangOps.FrontMovement", $"front-delayed-action-stalled-route-unavailable attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} targetNode={targetNode.id} reason={stalledRetryReason} noProgressChecks={entry.DelayedNoProgressChecks} requeues={entry.DelayedRouteRequeueCount} source={sourceTag}");
					return true;
				}
				if (routeReissueCooldownActive)
				{
					return true;
				}
				bool routeReady = TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, targetNode, out PathData retryPath, out string retryReason);
				if (routeReady)
				{
					Node retryRouteNode = ResolveFrontRouteCommandNode(targetNode, retryPath, allowSegmentTarget: defenderIsHuman && ShouldAllowDelayedHumanFrontSegmentTarget(entry), out NodeID retryRouteNodeId, out string retryRouteGoal);
					if (retryRouteNode?.id.IsValid != true)
					{
						retryRouteNode = targetNode;
						retryRouteNodeId = targetNode.id;
						retryRouteGoal = "target-fallback";
					}
					attacker.commands.AddCommand(new CommandGoto(attacker.PID, entry.CrewPeepId, retryRouteNode));
					MarkPendingRetaliationRouteTarget(entry, retryRouteNodeId, targetNode.id, currentNodeId);
					entry.DelayedRouteLastIssuedDay = nowDay;
					entry.DelayedRouteRequeueCount++;
					VerificationLog("GangOps.FrontMovement", $"front-delayed-action-requeued attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} targetNode={targetNode.id} routeTargetNode={retryRouteNodeId} routeGoal={retryRouteGoal} route={retryReason} cost={retryPath.cost} cooldownDays={RETALIATION_FRONT_DELAYED_ACTION_REQUEUE_COOLDOWN_DAYS} requeues={entry.DelayedRouteRequeueCount} source={sourceTag}");
					return true;
				}
				if (defenderIsHuman)
				{
					bool lostPhysicalNode = !currentNodeId.IsValid && !peepNodeId.IsValid;
					if (lostPhysicalNode && TryReassignLostPendingRetaliationFrontAction(entry, attacker, defender, building, targetNode, sourceTag))
					{
						return true;
					}
					if (lostPhysicalNode && waitedDays >= RETALIATION_FRONT_DELAYED_ACTION_LOST_NODE_GIVE_UP_DAYS)
					{
						attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
						entry.DelayedPhysicalActionAbandoned = true;
						entry.DelayedPhysicalActionAbandonedReason = "human-front-route-lost-node";
						VerificationLog("GangOps.FrontMovement", $"front-delayed-action-abandoned attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} noProgressChecks={entry.DelayedNoProgressChecks} requeues={entry.DelayedRouteRequeueCount} maxNoProgress={maxNoProgressChecks} maxRequeues={maxRouteRequeues} maxWaitDays={maxWaitDays} lostNodeMaxDays={RETALIATION_FRONT_DELAYED_ACTION_LOST_NODE_GIVE_UP_DAYS} multiTurn={entry.DelayedMultiTurnHumanFrontRoute} longHuman={longHumanFrontRoute} routeReason={retryReason} reason={entry.DelayedPhysicalActionAbandonedReason} source={sourceTag}");
						return false;
					}
					VerificationLog("GangOps.FrontMovement", $"front-delayed-action-route-unavailable-wait attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} targetNode={targetNode.id} reason={retryReason} waitedDays={waitedDays} requeues={entry.DelayedRouteRequeueCount} maxRequeues={maxRouteRequeues} maxWaitDays={maxWaitDays} lostNodeMaxDays={(lostPhysicalNode ? RETALIATION_FRONT_DELAYED_ACTION_LOST_NODE_GIVE_UP_DAYS : 0)} source={sourceTag}");
					return true;
				}
				VerificationLog("GangOps.FrontMovement", $"front-delayed-action-route-lost attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} targetNode={targetNode.id} reason={retryReason} source={sourceTag}");
				return false;
			}
		}
		Command actionCommand;
		string targetKind = string.IsNullOrEmpty(entry.DelayedTargetKind) ? "outpost" : entry.DelayedTargetKind;
		string actionMode;
		if (string.Equals(targetKind, "outpost", StringComparison.Ordinal))
		{
			if (TryResolvePendingRetaliationOutpostClosureAtTarget(entry, attacker, defender, crew, building, currentNodeId, currentNodeSource, sourceTag))
			{
				return true;
			}
			OutpostID outpostId = new OutpostID(building);
			if (defender.outposts?.GetOutpostEntryUnsafe(outpostId) == null)
			{
				VerificationLog("GangOps.FrontMovement", $"front-delayed-action-cancel attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} reason=outpost-entry-missing source={sourceTag}");
				return false;
			}
			actionCommand = new AICommandAtOutpost(attacker.PID, entry.CrewPeepId, building.Id, "maybe-steal");
			actionMode = "front-steal";
		}
		else
		{
			actionCommand = new AICommandAttackBuilding(attacker.PID, entry.CrewPeepId, building.Id, defender.PID, "gangbiz");
			actionMode = HasRetaliationBackroomModule(building) ? "backroom-attack" : "front-building-attack";
		}
		attacker.commands.AddCommandImmediate(actionCommand);
		entry.DelayedPhysicalActionQueued = true;
		entry.Mode = actionMode + "-delayed-queued";
		VerificationLog("GangOps.FrontMovement", $"front-delayed-action-queued attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} mode={entry.Mode} source={sourceTag}");
		return false;
	}

	private static bool IsPendingRetaliationFrontActionStillQueued(PendingRetaliationFrontTicker entry, Entity building)
	{
		if (entry == null || entry.CrewPeepId.IsNotValid || entry.AttackerPid.IsNotAnyPlayer)
		{
			return false;
		}
		PlayerInfo attacker = entry.AttackerPid.FindPlayer();
		if (attacker?.commands == null)
		{
			return false;
		}
		try
		{
			foreach (Command command in attacker.commands.EnumerateCommands(entry.CrewPeepId))
			{
				if (command == null)
				{
					continue;
				}
				if (command is AICommandAtOutpost atOutpost && atOutpost.buildingId == entry.BuildingId)
				{
					return true;
				}
				if (command is AICommandAttackBuilding attackBuilding && attackBuilding.buildingId == entry.BuildingId)
				{
					return true;
				}
				if (command is CommandGoto goTo)
				{
					NodeID targetNodeId = entry.TargetNodeId.IsValid ? entry.TargetNodeId : (building?.data?.board?.bead.nodeId ?? NodeID.INVALID);
					if (targetNodeId.IsValid && goTo.goalID == targetNodeId)
					{
						return true;
					}
					if (entry.DelayedRouteTargetNodeId.IsValid && goTo.goalID == entry.DelayedRouteTargetNodeId)
					{
						return true;
					}
				}
			}
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontMovement", $"pending-action-scan-failed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} mode={entry.Mode} reason={ex.GetType().Name}:{ex.Message}");
		}
		return false;
	}

	private static bool TryGetRetaliationBusinessForcedClosedBy(Entity building, PlayerID attackerPid, out PlayerID forcedClosedBy)
	{
		forcedClosedBy = PlayerID.INVALID;
		if (building == null || attackerPid.IsNotAnyPlayer)
		{
			return false;
		}
		try
		{
			Entity bizEntity = BuildingUtil.FindBizForBuilding(building);
			BizComponent biz = bizEntity?.components?.biz;
			if (biz == null)
			{
				return false;
			}
			BizComponent.TradeRestrictions restrictions = biz.FindTradeRestrictions(attackerPid);
			forcedClosedBy = restrictions.forcedClosedBy;
			return restrictions.IsForcedClosed;
		}
		catch
		{
			return false;
		}
	}

	private static void ApplyRetaliationBusinessClosureWarHeat(PendingRetaliationFrontTicker entry, PlayerID forcedClosedBy, string sourceTag)
	{
		if (entry == null
			|| entry.AttackerPid.IsNotAnyPlayer
			|| entry.DefenderPid.IsNotAnyPlayer)
		{
			return;
		}
		int closerPid = forcedClosedBy.IsAnyPlayer ? forcedClosedBy.id : entry.AttackerPid.id;
		int offendedPid = entry.DefenderPid.id;
		if (closerPid < 0 || offendedPid < 0 || closerPid == offendedPid)
		{
			return;
		}

		float directionalHeatBefore = GetWarHeat(offendedPid, closerPid);
		WarStanceSnapshot pairBefore = ResolveWarStanceSnapshot(offendedPid, closerPid);
		AddWarHeat(offendedPid, closerPid, RETALIATION_BUSINESS_CLOSURE_WAR_HEAT_GAIN, "front-closure");
		float directionalHeatAfter = GetWarHeat(offendedPid, closerPid);
		WarStanceSnapshot pairAfter = ResolveWarStanceSnapshot(offendedPid, closerPid);
		VerificationLog(
			"WarStance",
			$"[WarStance][FrontClosureHeat] source={sourceTag} attackerPid={entry.AttackerPid.id} defenderPid={entry.DefenderPid.id} closerPid={closerPid} offendedPid={offendedPid} building={entry.BuildingId.id} peep={entry.CrewPeepId.id} heat=+{RETALIATION_BUSINESS_CLOSURE_WAR_HEAT_GAIN:0.0} direction=offended-to-closer directionalHeatBefore={directionalHeatBefore:0.0} directionalHeatAfter={directionalHeatAfter:0.0} effectiveHeatBefore={pairBefore.EffectiveHeat:0.0} effectiveHeatAfter={pairAfter.EffectiveHeat:0.0} stanceBefore={FormatWarWeaponStance(pairBefore.Stance)} stanceAfter={FormatWarWeaponStance(pairAfter.Stance)}");
	}

	private static bool TryExecuteRetaliationBusinessClosureNow(PlayerInfo attacker, PlayerID defenderPid, EntityID crewPeepId, Entity peep, Entity building, bool allowNoAttackCostAfterWait, string sourceTag, out string reason)
	{
		reason = "none";
		if (attacker?.territory == null || attacker.PID.IsNotAnyPlayer || defenderPid.IsNotAnyPlayer || crewPeepId.IsNotValid || peep == null || building?.components?.building == null)
		{
			reason = "invalid-state";
			return false;
		}
		try
		{
			object combat = global::Game.Game.ctx?.simman?.combat;
			if (combat == null)
			{
				reason = "missing-combat";
				return false;
			}
			bool paidAttackCost = false;
			if (!global::Game.Game.ctx.simman.combat.CanPayAttackCost(peep))
			{
				if (!allowNoAttackCostAfterWait)
				{
					reason = "no-attack-cost";
					return false;
				}
				reason = "forced-closed-after-no-attack-cost-wait";
			}
			else
			{
				if (_combatDoPayAttackCostMethod == null)
				{
					_combatDoPayAttackCostMethod = typeof(CombatManager).GetMethod("DoPayAttackCost", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, new[] { typeof(Entity) }, null);
				}
				if (_combatDoPayAttackCostMethod == null)
				{
					reason = "missing-pay-method";
					return false;
				}
				_combatDoPayAttackCostMethod.Invoke(combat, new object[] { peep });
				paidAttackCost = true;
			}
			attacker.territory.ForceCloseBusiness(building, defenderPid, crewPeepId);
			TurnPerformanceDiagnosticsPatch.InvalidateCanBuySellAvailabilityCache(building, defenderPid, sourceTag + "-forced-close");
			if (TryGetRetaliationBusinessForcedClosedBy(building, attacker.PID, out PlayerID forcedClosedBy))
			{
				TurnPerformanceDiagnosticsPatch.InvalidateCanBuySellAvailabilityCache(building, PlayerID.HumanPlayer, sourceTag + "-forced-close-human");
				reason = paidAttackCost ? $"forced-closed-by:{forcedClosedBy.id}" : $"forced-closed-after-no-attack-cost-wait:{forcedClosedBy.id}";
				return true;
			}
			reason = "force-close-not-marked";
			return false;
		}
		catch (Exception ex)
		{
			Exception root = ex is TargetInvocationException && ex.InnerException != null ? ex.InnerException : ex;
			if (TryGetRetaliationBusinessForcedClosedBy(building, attacker.PID, out PlayerID forcedClosedAfterException))
			{
				TurnPerformanceDiagnosticsPatch.InvalidateCanBuySellAvailabilityCache(building, defenderPid, sourceTag + "-forced-close-exception");
				TurnPerformanceDiagnosticsPatch.InvalidateCanBuySellAvailabilityCache(building, PlayerID.HumanPlayer, sourceTag + "-forced-close-exception-human");
				reason = $"forced-closed-after-exception:{forcedClosedAfterException.id}:{root.GetType().Name}";
				return true;
			}
			reason = root.GetType().Name + ":" + root.Message;
			VerificationLog("GangOps.FrontMovement", $"business-closure-direct-failed attacker={attacker.PID.id} defender={defenderPid.id} peep={crewPeepId.id} building={building.Id.id} reason={reason} source={sourceTag}");
			return false;
		}
	}

	private static bool TryRecoverPendingRetaliationBusinessClosure(PendingRetaliationFrontTicker entry, Entity building, string sourceTag)
	{
		if (entry == null || building == null || !IsPendingRetaliationForcedBusinessClosureMode(entry.Mode) || entry.CrewPeepId.IsNotValid || entry.AttackerPid.IsNotAnyPlayer)
		{
			return false;
		}
		try
		{
			PlayerInfo attacker = entry.AttackerPid.FindPlayer();
			PlayerInfo defender = entry.DefenderPid.IsAnyPlayer ? entry.DefenderPid.FindPlayer() : null;
			if (attacker?.commands == null || attacker.crew == null || building?.data?.building == null)
			{
				return false;
			}
			NodeID targetNodeId = entry.TargetNodeId.IsValid ? entry.TargetNodeId : (building.data?.board?.bead.nodeId ?? NodeID.INVALID);
			Node targetNode = targetNodeId.IsValid ? targetNodeId.FindNode() : null;
			if (targetNode?.id.IsValid != true)
			{
				return false;
			}
			CrewAssignment crew = attacker.crew.GetCrewForPeep(entry.CrewPeepId);
			if (!crew.IsValid || crew.peepId.IsNotValid || crew.IsDead)
			{
				EntityID oldPeepId = entry.CrewPeepId;
				int priorRouteRequeueCount = entry.DelayedRouteRequeueCount;
				if (!entry.DelayedBusinessActorReassignmentGranted
					&& TryReassignLostPendingRetaliationFrontAction(entry, attacker, defender, building, targetNode, sourceTag))
				{
					entry.DelayedBusinessActorReassignmentGranted = true;
					entry.DelayedRouteRequeueCount = Mathf.Max(priorRouteRequeueCount, entry.DelayedRouteRequeueCount);
					VerificationLog("GangOps.FrontMovement", $"business-closure-actor-reassigned attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} oldPeep={oldPeepId.id} newPeep={entry.CrewPeepId.id} building={entry.BuildingId.id} targetNode={targetNode.id} waitedDays={Mathf.Max(0, G.GetNow().days - entry.QueuedDay)} requeues={entry.DelayedRouteRequeueCount} progressObserved={entry.DelayedFinalApproachProgressObserved} reason=missing-or-dead-actor source={sourceTag}");
					return true;
				}
				VerificationLog("GangOps.FrontMovement", $"business-closure-actor-reassign-unavailable attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} oldPeep={oldPeepId.id} building={entry.BuildingId.id} targetNode={targetNode.id} alreadyGranted={entry.DelayedBusinessActorReassignmentGranted} reason=missing-or-dead-actor source={sourceTag}");
				return false;
			}
			Entity peep = crew.GetPeep();
			TryResolveRuntimeCrewPhysicalNode(attacker, crew, peep, out NodeID currentNodeId, out string currentNodeSource, sourceTag, "business-closure-recover");
			NodeID peepNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
			int nowDay = G.GetNow().days;
			if (currentNodeId.IsValid && currentNodeId == targetNode.id || peepNodeId.IsValid && peepNodeId == targetNode.id)
			{
				if (string.Equals(entry.Mode, "business-closure-waiting-attack-cost", StringComparison.Ordinal)
					&& entry.DelayedRouteLastIssuedDay == nowDay)
				{
					return true;
				}
				PlayerID defenderPid = entry.DefenderPid.IsAnyPlayer ? entry.DefenderPid : PlayerID.System;
				bool waitedAtTargetForAttackCost = string.Equals(entry.Mode, "business-closure-waiting-attack-cost", StringComparison.Ordinal)
					&& entry.DelayedRouteLastIssuedDay != int.MinValue
					&& nowDay > entry.DelayedRouteLastIssuedDay;
				if (TryExecuteRetaliationBusinessClosureNow(attacker, defenderPid, entry.CrewPeepId, peep, building, waitedAtTargetForAttackCost, sourceTag, out string directReason))
				{
					entry.Mode = "business-closure-direct-completed";
					VerificationLog("GangOps.FrontMovement", $"business-closure-direct-completed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} reason={directReason} source={sourceTag}");
					return true;
				}
				if (string.Equals(directReason, "no-attack-cost", StringComparison.Ordinal))
				{
					bool alreadyWaitingAtTarget = string.Equals(entry.Mode, "business-closure-waiting-attack-cost", StringComparison.Ordinal)
						&& entry.DelayedRouteLastIssuedDay != int.MinValue;
					if (!alreadyWaitingAtTarget)
					{
						entry.Mode = "business-closure-waiting-attack-cost";
						entry.DelayedRouteLastIssuedDay = nowDay;
						VerificationLog("GangOps.FrontMovement", $"business-closure-wait-at-target attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} reason=no-attack-cost-arrived waitDay={nowDay} queuedDay={entry.QueuedDay} source={sourceTag}");
						return true;
					}
					int waitedAtTargetDays = Mathf.Max(0, nowDay - entry.DelayedRouteLastIssuedDay);
					int maxNoAttackCostWaitDays = defender?.PID.IsHumanPlayer == true ? RETALIATION_BUSINESS_CLOSURE_HUMAN_GIVE_UP_DAYS : RETALIATION_FRONT_DELAYED_ACTION_GIVE_UP_DAYS;
					if (waitedAtTargetDays >= maxNoAttackCostWaitDays)
					{
						VerificationLog("GangOps.FrontMovement", $"business-closure-give-up attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedAtTargetDays} maxWaitDays={maxNoAttackCostWaitDays} requeues={entry.DelayedRouteRequeueCount} reason=no-attack-cost-timeout source={sourceTag}");
						return false;
					}
					entry.Mode = "business-closure-waiting-attack-cost";
					entry.DelayedRouteLastIssuedDay = nowDay;
					VerificationLog("GangOps.FrontMovement", $"business-closure-wait-at-target attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} reason=no-attack-cost waitDay={nowDay} source={sourceTag}");
					return true;
				}
				attacker.commands.AddCommandImmediate(new AICommandAttackBuilding(attacker.PID, entry.CrewPeepId, building.Id, defenderPid, "npcbiz"));
				entry.Mode = "business-closure-recovered-queued";
				VerificationLog("GangOps.FrontMovement", $"business-closure-recovered-action attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} mode={entry.Mode} directReason={directReason} source={sourceTag}");
				return true;
			}
			int waitedDays = Mathf.Max(0, nowDay - entry.QueuedDay);
			bool defenderIsHuman = defender?.PID.IsHumanPlayer == true;
			bool robberyBusinessClosure = IsRobberyRetaliationSource(entry.Source) || IsRobberyRetaliationSource(sourceTag);
			int maxRouteRequeues = defenderIsHuman || robberyBusinessClosure ? RETALIATION_BUSINESS_CLOSURE_HUMAN_MAX_REQUEUES : 3;
			int maxWaitDays = defenderIsHuman || robberyBusinessClosure ? RETALIATION_BUSINESS_CLOSURE_HUMAN_GIVE_UP_DAYS : RETALIATION_FRONT_DELAYED_ACTION_GIVE_UP_DAYS;
			bool madeFinalApproachProgress = HasPendingRetaliationFinalRouteProgress(entry, currentNodeId, targetNode.id);
			if (madeFinalApproachProgress)
			{
				entry.DelayedFinalApproachProgressObserved = true;
				entry.DelayedNoProgressChecks = 0;
			}
			bool finalApproachProgressObserved = madeFinalApproachProgress
				|| entry.DelayedFinalApproachProgressObserved
				|| entry.DelayedFinalApproachGraceGranted;
			int effectiveMaxWaitDays = finalApproachProgressObserved
				? RETALIATION_BUSINESS_CLOSURE_PROGRESS_GIVE_UP_DAYS
				: maxWaitDays;
			if (finalApproachProgressObserved && effectiveMaxWaitDays > maxWaitDays && waitedDays >= maxWaitDays)
			{
				VerificationLog("GangOps.FrontMovement", $"business-closure-progress-wait-extended attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} maxWaitDays={effectiveMaxWaitDays} baseMaxWaitDays={maxWaitDays} requeues={entry.DelayedRouteRequeueCount} maxRequeues={maxRouteRequeues} progressed={madeFinalApproachProgress} progressObserved={finalApproachProgressObserved} graceGranted={entry.DelayedFinalApproachGraceGranted} source={sourceTag}");
			}
			bool routeLimitReached = entry.DelayedRouteRequeueCount >= maxRouteRequeues
				&& !finalApproachProgressObserved;
			bool waitLimitReached = waitedDays >= effectiveMaxWaitDays;
			bool routeReissueCooldownActive = entry.DelayedRouteLastIssuedDay != int.MinValue
				&& nowDay - entry.DelayedRouteLastIssuedDay < RETALIATION_FRONT_DELAYED_ACTION_REQUEUE_COOLDOWN_DAYS;
			if (routeReissueCooldownActive)
			{
				VerificationLog("GangOps.FrontMovement", $"business-closure-recover-wait attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} reason=route-recently-issued lastIssuedDay={entry.DelayedRouteLastIssuedDay} maxWaitDays={effectiveMaxWaitDays} baseMaxWaitDays={maxWaitDays} maxRequeues={maxRouteRequeues} source={sourceTag}");
				return true;
			}
			if ((routeLimitReached || waitLimitReached)
				&& waitLimitReached
				&& !routeLimitReached
				&& !entry.DelayedFinalApproachGraceGranted
				&& TryBuildRuntimeFrontReachableNextRoute(attacker.PID, peep, targetNode, out PathData gracePath, out string graceReason))
			{
				PlayerID graceDefenderPid = entry.DefenderPid.IsAnyPlayer ? entry.DefenderPid : PlayerID.System;
				AICommandAttackBuilding graceForceClose = new AICommandAttackBuilding(attacker.PID, entry.CrewPeepId, building.Id, graceDefenderPid, "npcbiz");
				attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
				attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, entry.CrewPeepId, targetNode), graceForceClose);
				entry.Mode = "business-closure-route-commitment-final-approach-grace";
				entry.DelayedRouteTargetNodeId = targetNode.id;
				entry.DelayedRouteLastIssuedDay = nowDay;
				entry.DelayedFinalRouteIssuedFromNodeId = currentNodeId;
				entry.DelayedLastObservedNodeId = currentNodeId;
				entry.DelayedRouteRequeueCount++;
				entry.DelayedFinalApproachGraceGranted = true;
				entry.DelayedFinalApproachProgressObserved = true;
				VerificationLog("GangOps.FrontMovement", $"business-closure-route-commitment-final-approach-grace attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} requeues={entry.DelayedRouteRequeueCount} route={graceReason} cost={gracePath.cost} graceTurns=1 source={sourceTag}");
				return true;
			}
			if (waitLimitReached
				&& !routeLimitReached
				&& finalApproachProgressObserved
				&& !entry.DelayedTerminalReassignmentGranted)
			{
				if (TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, targetNode, out PathData terminalPath, out string terminalReason))
				{
					PlayerID terminalDefenderPid = entry.DefenderPid.IsAnyPlayer ? entry.DefenderPid : PlayerID.System;
					AICommandAttackBuilding terminalForceClose = new AICommandAttackBuilding(attacker.PID, entry.CrewPeepId, building.Id, terminalDefenderPid, "npcbiz");
					attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
					attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, entry.CrewPeepId, targetNode), terminalForceClose);
					entry.Mode = "business-closure-terminal-target-route";
					MarkPendingRetaliationRouteTarget(entry, targetNode.id, targetNode.id, currentNodeId);
					entry.DelayedRouteLastIssuedDay = nowDay;
					entry.DelayedLastObservedNodeId = currentNodeId;
					entry.DelayedFinalApproachGraceGranted = true;
					entry.DelayedFinalApproachProgressObserved = true;
					entry.DelayedTerminalReassignmentGranted = true;
					entry.QueuedDay = nowDay - Mathf.Max(0, RETALIATION_BUSINESS_CLOSURE_PROGRESS_GIVE_UP_DAYS - RETALIATION_FRONT_DELAYED_ACTION_FINAL_GRACE_DAYS);
					VerificationLog("GangOps.FrontMovement", $"business-closure-terminal-target-route attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} maxWaitDays={effectiveMaxWaitDays} baseMaxWaitDays={maxWaitDays} terminalWindowDays={RETALIATION_FRONT_DELAYED_ACTION_FINAL_GRACE_DAYS} route={terminalReason} cost={(terminalPath != null ? terminalPath.cost.ToString() : "0")} source={sourceTag}");
					return true;
				}
				VerificationLog("GangOps.FrontMovement", $"business-closure-terminal-route-unavailable attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} maxWaitDays={effectiveMaxWaitDays} baseMaxWaitDays={maxWaitDays} reason={terminalReason} source={sourceTag}");
			}
			if (routeLimitReached || waitLimitReached)
			{
				VerificationLog("GangOps.FrontMovement", $"business-closure-give-up attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} maxWaitDays={effectiveMaxWaitDays} baseMaxWaitDays={maxWaitDays} requeues={entry.DelayedRouteRequeueCount} maxRequeues={maxRouteRequeues} progressed={madeFinalApproachProgress} progressObserved={finalApproachProgressObserved} reason={(entry.DelayedRouteRequeueCount >= maxRouteRequeues && !finalApproachProgressObserved ? "requeue-limit" : "timeout")} source={sourceTag}");
				return false;
			}
			if (robberyBusinessClosure
				&& (entry.DelayedRouteRequeueCount >= RETALIATION_ROBBERY_BUSINESS_CLOSURE_FORCE_REQUEUES || waitedDays >= RETALIATION_ROBBERY_BUSINESS_CLOSURE_FORCE_DAYS))
			{
				PlayerID defenderPid = entry.DefenderPid.IsAnyPlayer ? entry.DefenderPid : PlayerID.System;
				AICommandAttackBuilding forceClose = new AICommandAttackBuilding(attacker.PID, entry.CrewPeepId, building.Id, defenderPid, "npcbiz");
				attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
				attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, entry.CrewPeepId, targetNode), forceClose);
				entry.Mode = "business-closure-route-commitment-final-approach";
				MarkPendingRetaliationRouteTarget(entry, targetNode.id, targetNode.id, currentNodeId);
				entry.DelayedRouteLastIssuedDay = nowDay;
				bool retryIncremented = !finalApproachProgressObserved;
				if (retryIncremented)
				{
					entry.DelayedRouteRequeueCount++;
				}
				VerificationLog("GangOps.FrontMovement", $"business-closure-route-commitment-final-approach attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} waitedDays={waitedDays} requeues={entry.DelayedRouteRequeueCount} progressed={madeFinalApproachProgress} progressObserved={finalApproachProgressObserved} retryIncremented={retryIncremented} source={sourceTag}");
				return true;
			}
			bool routeReady = TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, targetNode, out PathData retryPath, out string retryReason);
			if (routeReady)
			{
				PlayerID defenderPid = entry.DefenderPid.IsAnyPlayer ? entry.DefenderPid : PlayerID.System;
				AICommandAttackBuilding forceClose = new AICommandAttackBuilding(attacker.PID, entry.CrewPeepId, building.Id, defenderPid, "npcbiz");
				attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
				attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, entry.CrewPeepId, targetNode), forceClose);
				entry.Mode = "goto-forced-business-close";
				MarkPendingRetaliationRouteTarget(entry, targetNode.id, targetNode.id, currentNodeId);
				entry.DelayedRouteLastIssuedDay = nowDay;
				bool retryIncremented = !finalApproachProgressObserved;
				if (retryIncremented)
				{
					entry.DelayedRouteRequeueCount++;
				}
				VerificationLog("GangOps.FrontMovement", $"business-closure-requeued attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} mode=goto-force-close route={retryReason} cost={retryPath.cost} requeues={entry.DelayedRouteRequeueCount} maxRequeues={maxRouteRequeues} progressed={madeFinalApproachProgress} progressObserved={finalApproachProgressObserved} retryIncremented={retryIncremented} source={sourceTag}");
				return true;
			}
			if (defenderIsHuman)
			{
				VerificationLog("GangOps.FrontMovement", $"business-closure-route-unavailable-wait attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} reason={retryReason} waitedDays={waitedDays} maxWaitDays={maxWaitDays} requeues={entry.DelayedRouteRequeueCount} maxRequeues={maxRouteRequeues} source={sourceTag}");
				return true;
			}
			VerificationLog("GangOps.FrontMovement", $"business-closure-recover-failed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} reason={retryReason} source={sourceTag}");
			return false;
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontMovement", $"business-closure-recover-error attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static bool TryRecoverPendingRetaliationFrontTravel(PendingRetaliationFrontTicker entry, Entity building, string sourceTag)
	{
		if (entry == null || building == null || !IsPendingRetaliationGotoFrontMode(entry.Mode) || entry.CrewPeepId.IsNotValid || entry.AttackerPid.IsNotAnyPlayer)
		{
			return false;
		}
		try
		{
			PlayerInfo attacker = entry.AttackerPid.FindPlayer();
			PlayerInfo defender = entry.DefenderPid.FindPlayer();
			if (attacker?.commands == null || attacker.crew == null || defender == null || building?.data?.building == null)
			{
				return false;
			}
			if (building.data.building.outpost != entry.DefenderPid)
			{
				return false;
			}
			CrewAssignment crew = attacker.crew.GetCrewForPeep(entry.CrewPeepId);
			if (!crew.IsValid || crew.peepId.IsNotValid || crew.IsDead)
			{
				return false;
			}
			Entity peep = crew.GetPeep();
			NodeID targetNodeId = entry.TargetNodeId.IsValid ? entry.TargetNodeId : (building.data?.board?.bead.nodeId ?? NodeID.INVALID);
			Node targetNode = targetNodeId.IsValid ? targetNodeId.FindNode() : null;
			if (targetNode?.id.IsValid != true)
			{
				return false;
			}
			TryResolveRuntimeCrewPhysicalNode(attacker, crew, peep, out NodeID currentNodeId, out string currentNodeSource, sourceTag, "front-travel-recover");
			NodeID peepNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
			if (currentNodeId.IsValid && currentNodeId == targetNode.id || peepNodeId.IsValid && peepNodeId == targetNode.id)
			{
				if (string.Equals(GetPendingRetaliationTargetKind(entry), "outpost", StringComparison.Ordinal))
				{
					if (TryResolvePendingRetaliationOutpostClosureAtTarget(entry, attacker, defender, crew, building, currentNodeId, currentNodeSource, sourceTag))
					{
						return true;
					}
					OutpostID outpostId = new OutpostID(building);
					if (defender.outposts?.GetOutpostEntryUnsafe(outpostId) == null)
					{
						return false;
					}
					attacker.commands.AddCommandImmediate(new AICommandAtOutpost(attacker.PID, entry.CrewPeepId, building.Id, "maybe-steal"));
					entry.Mode = "front-steal-recovered-queued";
				}
				else
				{
					attacker.commands.AddCommandImmediate(new AICommandAttackBuilding(attacker.PID, entry.CrewPeepId, building.Id, defender.PID, "gangbiz"));
					entry.Mode = HasRetaliationBackroomModule(building) ? "backroom-attack-recovered-queued" : "front-building-attack-recovered-queued";
				}
				VerificationLog("GangOps.FrontMovement", $"front-travel-recovered-action attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} mode={entry.Mode} source={sourceTag}");
				return true;
			}
			int nowDay = G.GetNow().days;
			int waitedDays = Mathf.Max(0, nowDay - entry.QueuedDay);
			if (TryResolvePendingRetaliationOutpostClosureByRouteCommitment(entry, attacker, defender, crew, building, targetNode, currentNodeId, currentNodeSource, waitedDays, sourceTag))
			{
				return true;
			}
			if (entry.DelayedRouteLastIssuedDay != int.MinValue
				&& nowDay - entry.DelayedRouteLastIssuedDay < RETALIATION_FRONT_DELAYED_ACTION_REQUEUE_COOLDOWN_DAYS)
			{
				VerificationLog("GangOps.FrontMovement", $"front-travel-recover-wait attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} reason=route-recently-issued lastIssuedDay={entry.DelayedRouteLastIssuedDay} source={sourceTag}");
				return true;
			}
			if (defender.PID.IsHumanPlayer == true && entry.DelayedRouteRequeueCount >= RETALIATION_FRONT_DELAYED_ACTION_HUMAN_MAX_REQUEUES)
			{
				VerificationLog("GangOps.FrontMovement", $"front-travel-recover-human-requeue-limit attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} requeues={entry.DelayedRouteRequeueCount} maxRequeues={RETALIATION_FRONT_DELAYED_ACTION_HUMAN_MAX_REQUEUES} source={sourceTag}");
				return false;
			}
			if (TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, targetNode, out PathData retryPath, out string retryReason))
			{
				bool defenderIsHuman = defender.PID.IsHumanPlayer == true;
				Node retryRouteNode = ResolveFrontRouteCommandNode(targetNode, retryPath, allowSegmentTarget: defenderIsHuman && ShouldAllowDelayedHumanFrontSegmentTarget(entry), out NodeID retryRouteNodeId, out string retryRouteGoal);
				if (retryRouteNode?.id.IsValid != true)
				{
					retryRouteNode = targetNode;
					retryRouteNodeId = targetNode.id;
					retryRouteGoal = "target-fallback";
				}
				attacker.commands.AddCommand(new CommandGoto(attacker.PID, entry.CrewPeepId, retryRouteNode));
				MarkPendingRetaliationRouteTarget(entry, retryRouteNodeId, targetNode.id, currentNodeId);
				entry.DelayedRouteLastIssuedDay = nowDay;
				entry.DelayedRouteRequeueCount++;
				VerificationLog("GangOps.FrontMovement", $"front-travel-requeued attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} routeTargetNode={retryRouteNodeId} routeGoal={retryRouteGoal} route={retryReason} cost={retryPath.cost} requeues={entry.DelayedRouteRequeueCount} source={sourceTag}");
				return true;
			}
			VerificationLog("GangOps.FrontMovement", $"front-travel-recover-failed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} peepNode={peepNodeId} targetNode={targetNode.id} reason={retryReason} source={sourceTag}");
			return false;
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontMovement", $"front-travel-recover-error attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static bool IsPendingRetaliationGotoFrontMode(string mode)
	{
		return !string.IsNullOrEmpty(mode)
			&& mode.StartsWith("goto-", StringComparison.Ordinal)
			&& (mode.IndexOf("front-steal", StringComparison.OrdinalIgnoreCase) >= 0
				|| mode.IndexOf("building-attack", StringComparison.OrdinalIgnoreCase) >= 0
				|| mode.IndexOf("backroom-attack", StringComparison.OrdinalIgnoreCase) >= 0);
	}

	private static bool IsPendingRetaliationForcedBusinessClosureMode(string mode)
	{
		return !string.IsNullOrEmpty(mode)
			&& (mode.IndexOf("business-fallback-close", StringComparison.OrdinalIgnoreCase) >= 0
				|| mode.IndexOf("forced-business-close", StringComparison.OrdinalIgnoreCase) >= 0
				|| mode.IndexOf("business-closure", StringComparison.OrdinalIgnoreCase) >= 0);
	}

	private static string GetPendingRetaliationTargetKind(PendingRetaliationFrontTicker entry)
	{
		if (entry == null)
		{
			return "outpost";
		}
		if (!string.IsNullOrEmpty(entry.DelayedTargetKind))
		{
			return entry.DelayedTargetKind;
		}
		string mode = entry.Mode ?? string.Empty;
		return mode.IndexOf("front-steal", StringComparison.OrdinalIgnoreCase) >= 0 ? "outpost" : "building";
	}

	private static void ClearAllPendingRetaliationFrontTickers(string sourceTag)
	{
		if (_pendingRetaliationFrontTickersByBuilding.Count == 0)
		{
			return;
		}
		foreach (ulong key in _pendingRetaliationFrontTickersByBuilding.Keys.ToList())
		{
			ClearPendingRetaliationFrontTicker(key, "clear-all", sourceTag);
		}
	}

	private static void ClearPendingRetaliationFrontTicker(ulong key, string reason, string sourceTag)
	{
		try
		{
			if (!_pendingRetaliationFrontTickersByBuilding.TryGetValue(key, out PendingRetaliationFrontTicker entry))
			{
				return;
			}
			bool shouldMoveAway = entry != null
				&& (string.Equals(reason, "front-completed", StringComparison.Ordinal)
					|| string.Equals(reason, "command-finished", StringComparison.Ordinal)
					|| string.Equals(reason, "business-closure-completed", StringComparison.Ordinal)
					|| string.Equals(reason, "business-closure-command-finished", StringComparison.Ordinal)
					|| string.Equals(reason, "front-defended", StringComparison.Ordinal));
			if (entry != null && IsRetaliationFrontActorUseReason(reason))
			{
				BlockRetaliationFrontRetry(entry, reason, sourceTag);
				MarkRecentRetaliationFrontActorUse(entry, reason, sourceTag);
			}
			if (shouldMoveAway)
			{
				TryQueuePostRetaliationFrontMovement(entry, reason, sourceTag);
			}
			if (entry?.Ticker != null)
			{
				RemovePendingRetaliationFrontTickerFromHud(entry.Ticker);
			}
			TryShowRetaliationFrontDefenseResult(entry, reason, sourceTag);
			_pendingRetaliationFrontTickersByBuilding.Remove(key);
			VerificationLog("GangOps.FrontTicker", $"removed building={key} attacker={entry?.AttackerPid.id ?? 0} defender={entry?.DefenderPid.id ?? 0} peep={entry?.CrewPeepId.id ?? 0UL} reason={reason} mode={entry?.Mode} source={sourceTag}");
		}
		catch (Exception ex)
		{
			_pendingRetaliationFrontTickersByBuilding.Remove(key);
			VerificationLog("GangOps.FrontTicker", $"remove-failed building={key} reason={reason} error={ex.GetType().Name}:{ex.Message} source={sourceTag}");
		}
	}

	private static bool IsRetaliationFrontDefenseResultReason(string reason)
	{
		return string.Equals(reason, "command-finished", StringComparison.Ordinal)
			|| string.Equals(reason, "front-defended", StringComparison.Ordinal);
	}

	private static void TryShowRetaliationFrontDefenseResult(PendingRetaliationFrontTicker entry, string reason, string sourceTag)
	{
		if (entry == null || entry.DefenderPid.IsHumanPlayer != true || !IsRetaliationFrontDefenseResultReason(reason))
		{
			return;
		}
		try
		{
			Entity building = entry.BuildingId.IsValid ? entry.BuildingId.FindEntity() : null;
			if (building?.data?.building == null || building.data.building.outpost != entry.DefenderPid)
			{
				return;
			}
			PlayerInfo defender = entry.DefenderPid.IsAnyPlayer ? entry.DefenderPid.FindPlayer() : null;
			if (string.Equals(reason, "command-finished", StringComparison.Ordinal)
				&& !IsRetaliationFrontProtectedByHumanPhysicalPresence(defender, building, out EntityID protectorPeepId, out EntityID protectorVehicleId, out NodeID protectorNodeId, out string protectionReason))
			{
				VerificationLog("GangOps.FrontTicker", $"defense-result-suppressed-no-protector attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} reason={reason} source={sourceTag}");
				return;
			}
			string attackerName = GetGangDisplayName(entry.AttackerPid.id);
			global::Game.Game.ctx?.hud?.tickers?.AddTextTicker(
				TickerIcon.OUTPOST_START,
				TickerTitle.DEFAULT,
				Loc.Get("ui.tickers.outpost.steal-protected"));
			LogGrapevine($"TURF: Your outfit held a front against {attackerName}.");
			VerificationLog("GangOps.FrontTicker", $"defense-result-shown attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} reason={reason} style=vanilla-outpost-protected source={sourceTag}");
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontTicker", $"defense-result-failed attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} building={entry.BuildingId.id} reason={reason} error={ex.GetType().Name}:{ex.Message} source={sourceTag}");
		}
	}

	private static bool TryQueuePostRetaliationFrontMovement(PendingRetaliationFrontTicker entry, string reason, string sourceTag)
	{
		if (entry == null || entry.CrewPeepId.IsNotValid || entry.AttackerPid.IsNotAnyPlayer)
		{
			return false;
		}
		try
		{
			PlayerInfo attacker = entry.AttackerPid.FindPlayer();
			if (attacker?.commands == null || attacker.crew == null || attacker.territory == null)
			{
				return false;
			}
			CrewAssignment crew = attacker.crew.GetCrewForPeep(entry.CrewPeepId);
			if (!crew.IsValid || crew.IsDead)
			{
				return false;
			}
			if (IsCrewAssignedToOtherPendingRetaliationAction(entry.AttackerPid, entry.CrewPeepId, entry.BuildingId, out PendingRetaliationFrontTicker otherPending))
			{
				VerificationLog("GangOps.FrontMovement", $"post-front-return-skip attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} otherBuilding={otherPending.BuildingId.id} otherKind={GetPendingRetaliationActionKind(otherPending)} reason=crew-has-other-pending-action clearReason={reason} source={sourceTag}");
				return false;
			}
			Entity peep = crew.GetPeep();
			if (peep?.data?.agent == null)
			{
				return false;
			}
			Node headquartersNode = null;
			try
			{
				headquartersNode = attacker.territory.GetHeadquartersNode(ignoreWarnings: true);
			}
			catch
			{
			}
			if (headquartersNode?.id.IsValid != true)
			{
				return false;
			}
			TryResolveRuntimeCrewCurrentNode(attacker, crew, peep, out NodeID currentNodeId, out string currentNodeSource, syncVehicleCrew: true, sourceTag, "post-front-return");
			NodeID visibleAgentNodeId = peep.data?.agent?.nid ?? NodeID.INVALID;
			bool visibleAwayFromHome = visibleAgentNodeId.IsValid && visibleAgentNodeId != headquartersNode.id;
			if (currentNodeId.IsValid && currentNodeId == headquartersNode.id && !visibleAwayFromHome)
			{
				VerificationLog("GangOps.FrontMovement", $"post-front-return-skip attacker={entry.AttackerPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} node={currentNodeId} reason=already-home clearReason={reason} source={sourceTag}");
				return false;
			}
			if (visibleAwayFromHome && currentNodeId.IsValid && currentNodeId == headquartersNode.id)
			{
				currentNodeSource = (currentNodeSource ?? "unknown") + ":visible-agent-away";
				currentNodeId = visibleAgentNodeId;
			}
			attacker.commands.FlushQueue(entry.CrewPeepId, cancelActive: true);
			attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, entry.CrewPeepId, headquartersNode));
			VerificationLog("GangOps.FrontMovement", $"post-front-return-queued attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} currentNode={currentNodeId} currentSource={currentNodeSource} homeNode={headquartersNode.id} clearReason={reason} source={sourceTag}");
			return true;
		}
		catch (Exception ex)
		{
			VerificationLog("GangOps.FrontMovement", $"post-front-return-failed attacker={entry.AttackerPid.id} peep={entry.CrewPeepId.id} building={entry.BuildingId.id} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static void RemovePendingRetaliationFrontTickerFromHud(TickerData ticker)
	{
		if (ticker == null)
		{
			return;
		}
		object tickerBar = global::Game.Game.ctx?.hud?.tickers;
		if (tickerBar == null)
		{
			return;
		}
		try
		{
			global::Game.Game.ctx?.hud?.tickers?.RemoveTicker(ticker);
		}
		catch
		{
		}
		try
		{
			FieldInfo startupField = tickerBar.GetType().GetField("_startupTickers", BindingFlags.Instance | BindingFlags.NonPublic);
			if (startupField?.GetValue(tickerBar) is List<TickerData> startupTickers)
			{
				startupTickers.Remove(ticker);
			}
		}
		catch
		{
		}
	}

	private static bool TryQueuePhysicalRetaliationBusinessForceClose(GangOpsChannel channel, PlayerInfo attacker, PlayerInfo defender, Entity targetBuilding, string sourceTag, out string actionSummary)
	{
		actionSummary = "forced-close:none";
		if (attacker?.commands == null || targetBuilding?.components?.board == null)
		{
			return false;
		}
		NodeID targetNodeId = targetBuilding.data?.board?.bead.nodeId ?? NodeID.INVALID;
		Node targetNode = targetNodeId.IsValid ? targetNodeId.FindNode() : null;
		if (targetNode?.id.IsValid != true)
		{
			return false;
		}
		if (defender?.PID.IsHumanPlayer == true
			&& IsRetaliationFrontAlreadyPending(defender, targetBuilding, out PlayerID pendingAttackerPid, out string pendingMode))
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical front action unavailable attacker={attacker.PID.id} defender={defender.PID.id} building={targetBuilding.Id.id} reason=front-already-pending pendingAttacker={pendingAttackerPid.id} pendingMode={pendingMode} source={sourceTag}");
			return false;
		}
		if (defender?.PID.IsHumanPlayer == true
			&& IsRetaliationFrontRetryBlocked(attacker, defender, targetBuilding, out int blockedUntilDay))
		{
			VerificationLog("GangOps.FrontMovement", $"forced-business-retry-blocked attacker={attacker.PID.id} defender={defender.PID.id} building={targetBuilding.Id.id} untilDay={blockedUntilDay} source={sourceTag}");
			return false;
		}
		float maxCrewDistance = defender?.PID.IsHumanPlayer == true ? AI_VS_HUMAN_FRONT_ACTION_MAX_CREW_DISTANCE : -1f;
		CrewAssignment crew = FindRuntimeFrontActionCrew(attacker, targetBuilding, targetNode, sourceTag, "forced-close", maxCrewDistance, out bool blockedByDistance);
		if (!crew.IsValid || crew.peepId.IsNotValid)
		{
			if (blockedByDistance && defender?.PID.IsHumanPlayer == true)
			{
				BlockRetaliationFrontRetry(attacker.PID, defender.PID, targetBuilding.Id, EntityID.INVALID, "crew-too-far", sourceTag, RETALIATION_FRONT_TOO_FAR_RETRY_BLOCK_DAYS);
			}
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical forced closure unavailable attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} building={targetBuilding.Id.id} reason=no-available-crew source={sourceTag}");
			return false;
		}
		try
		{
			Entity peep = crew.GetPeep();
			TryResolveRuntimeCrewCurrentNode(attacker, crew, peep, out NodeID currentNodeId, out string currentNodeSource, syncVehicleCrew: true, sourceTag, "forced-close");
			AICommandAttackBuilding forceClose = new AICommandAttackBuilding(attacker.PID, crew.peepId, targetBuilding.Id, defender?.PID ?? PlayerID.System, "npcbiz");
			attacker.commands.FlushQueue(crew.peepId, cancelActive: true);
			if (currentNodeId.IsValid && currentNodeId == targetNode.id)
			{
				attacker.commands.AddCommandImmediate(forceClose);
				actionSummary = $"forced-close-queued:{targetBuilding.Id.id}";
				TrackPendingRetaliationForcedBusinessClosure(attacker, defender, targetBuilding, crew.peepId, targetNode.id, "forced-business-close-now", sourceTag, NodeID.INVALID);
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical forced closure queued attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} targetNode={targetNode.id} currentNode={currentNodeId} currentSource={currentNodeSource} mode=force-close-now source={sourceTag}");
				return true;
			}

			if (!TryBuildRuntimeFrontApproachRoute(attacker.PID, peep, targetNode, out PathData approachPath, out string approachReason))
			{
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical forced closure unavailable attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} targetNode={targetNode.id} currentNode={currentNodeId} currentSource={currentNodeSource} reason=no-approach-route detail={approachReason} source={sourceTag}");
				return false;
			}
			attacker.commands.AddCommandImmediate(new CommandGoto(attacker.PID, crew.peepId, targetNode), forceClose);
			actionSummary = $"forced-close-travel-queued:{targetBuilding.Id.id}";
			TrackPendingRetaliationForcedBusinessClosure(attacker, defender, targetBuilding, crew.peepId, targetNode.id, "goto-forced-business-close", sourceTag, currentNodeId);
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical forced closure queued attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} targetNode={targetNode.id} currentNode={currentNodeId} currentSource={currentNodeSource} mode=goto-force-close route={approachReason} cost={approachPath.cost} source={sourceTag}");
			return true;
		}
		catch (Exception ex)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.Revenge", $"Physical forced closure queue failed attacker={attacker.PID.id} defender={defender?.PID.id ?? 0} peep={crew.peepId.id} building={targetBuilding.Id.id} reason={ex.GetType().Name}:{ex.Message} source={sourceTag}");
			return false;
		}
	}

	private static bool TryFindRetaliationFrontOrBackroomTarget(PlayerInfo attacker, PlayerInfo defender, Entity anchorBuilding, out Entity targetBuilding, out string targetKind, out string reason)
	{
		targetBuilding = null;
		targetKind = "none";
		reason = "none";
		if (!IsAliveGangPlayer(attacker) || !IsGangOpsRetaliationTargetEligible(defender))
		{
			reason = "front-target-ineligible";
			return false;
		}

		int controlledCount = 0;
		int outpostCount = 0;
		int candidateCount = 0;
		int bestPriority = int.MaxValue;
		float bestDistance = float.MaxValue;
		HashSet<ulong> seen = new HashSet<ulong>();
		TryConsiderRetaliationFrontCandidate(anchorBuilding, "anchor", attacker, defender, anchorBuilding, ref targetBuilding, ref targetKind, ref bestPriority, ref bestDistance, ref candidateCount, seen);

		try
		{
			foreach (OutpostEntry entry in defender.outposts?.GetOutpostEntriesUnsafe() ?? Enumerable.Empty<OutpostEntry>())
			{
				Entity building = entry?.outpostId.FindBuilding();
				outpostCount++;
				TryConsiderRetaliationFrontCandidate(building, "outpost", attacker, defender, anchorBuilding, ref targetBuilding, ref targetKind, ref bestPriority, ref bestDistance, ref candidateCount, seen);
			}
		}
		catch
		{
		}

		foreach (Entity building in GetOwnedBuildings(defender))
		{
			controlledCount++;
			TryConsiderRetaliationFrontCandidate(building, "controlled", attacker, defender, anchorBuilding, ref targetBuilding, ref targetKind, ref bestPriority, ref bestDistance, ref candidateCount, seen);
		}

		if (targetBuilding != null)
		{
			reason = targetKind;
			return true;
		}
		reason = $"no-front-or-backroom-target controlled={controlledCount} outposts={outpostCount} candidates={candidateCount}";
		return false;
	}

	private static void TryConsiderRetaliationFrontCandidate(Entity building, string sourceKind, PlayerInfo attacker, PlayerInfo defender, Entity anchorBuilding, ref Entity bestBuilding, ref string bestKind, ref int bestPriority, ref float bestDistance, ref int candidateCount, HashSet<ulong> seen)
	{
		if (building?.components?.building == null || building.components.building.IsSafehouse || seen == null || !seen.Add(building.Id.id))
		{
			return;
		}
		string candidateKind = null;
		int priority = int.MaxValue;
		if (IsRetaliationOutpostFront(defender, building))
		{
			candidateKind = "outpost";
			priority = 0;
		}
		else if (IsRetaliationControlledFront(defender, building))
		{
			bool hasBackroom = HasRetaliationBackroomModule(building);
			candidateKind = hasBackroom ? "backroom" : "controlled";
			priority = hasBackroom ? 1 : 2;
		}
		else if (string.Equals(sourceKind, "anchor", StringComparison.Ordinal) && IsRetaliationClosureCandidate(attacker, defender, building))
		{
			candidateKind = "closure";
			priority = 3;
		}
		if (candidateKind == null)
		{
			return;
		}
		if (!IsRetaliationFrontLocalEnough(attacker, defender, building, out float localDistance, out float maxLocalDistance, out string localReason))
		{
			LogRetaliationFrontLocalBlocked(attacker, defender, building, candidateKind, sourceKind, localDistance, maxLocalDistance, localReason);
			return;
		}
		if (IsRetaliationFrontRetryBlocked(attacker, defender, building, out int blockedUntilDay))
		{
			VerificationLog("GangOps.FrontMovement", $"front-retry-blocked attacker={attacker?.PID.id ?? 0} defender={defender?.PID.id ?? 0} building={building.Id.id} untilDay={blockedUntilDay} kind={candidateKind} source={sourceKind}");
			return;
		}
		if (IsRetaliationFrontAlreadyPending(defender, building, out PlayerID pendingAttackerPid, out string pendingMode))
		{
			VerificationLog("GangOps.FrontMovement", $"front-pending-blocked attacker={attacker?.PID.id ?? 0} defender={defender?.PID.id ?? 0} building={building.Id.id} pendingAttacker={pendingAttackerPid.id} pendingMode={pendingMode} kind={candidateKind} source={sourceKind}");
			return;
		}
		if (IsRetaliationFrontProtectedByHumanRoute(defender, building, out EntityID protectorPeepId, out EntityID protectorVehicleId, out NodeID protectorNodeId, out string protectionReason))
		{
			VerificationLog("GangOps.FrontMovement", $"front-route-protected attacker={attacker?.PID.id ?? 0} defender={defender?.PID.id ?? 0} building={building.Id.id} node={protectorNodeId} peep={protectorPeepId.id} vehicle={protectorVehicleId.id} kind={candidateKind} reason={protectionReason} source={sourceKind}");
			if (defender?.PID.IsHumanPlayer == true)
			{
				if (IsRetaliationFrontProtectedByHumanPhysicalPresence(defender, building, out EntityID physicalProtectorPeepId, out _, out _, out string physicalProtectionReason))
				{
					ClearProtectedHumanRetaliationFrontTicker(attacker, defender, building, physicalProtectorPeepId, physicalProtectionReason, sourceKind);
				}
				else
				{
					VerificationLog("GangOps.FrontTicker", $"front-defense-route-only-no-clear attacker={attacker?.PID.id ?? 0} defender={defender.PID.id} building={building.Id.id} routeProtector={protectorPeepId.id} routeReason={protectionReason} source={sourceKind}");
				}
			}
			return;
		}
		if (defender?.PID.IsHumanPlayer == true && !HasRuntimeFrontActionCrewWithinDistance(attacker, building, AI_VS_HUMAN_FRONT_ACTION_MAX_CREW_DISTANCE, out float nearestCrewDistance, out EntityID nearestCrewPeepId, out NodeID nearestCrewNodeId))
		{
			VerificationLog("GangOps.FrontMovement", $"front-target-crew-too-far attacker={attacker?.PID.id ?? 0} defender={defender?.PID.id ?? 0} building={building.Id.id} node={building.data?.board?.bead.nodeId ?? NodeID.INVALID} nearestPeep={nearestCrewPeepId.id} nearestNode={nearestCrewNodeId} distance={nearestCrewDistance:0.0} maxDistance={AI_VS_HUMAN_FRONT_ACTION_MAX_CREW_DISTANCE:0.0} kind={candidateKind} source={sourceKind}");
			return;
		}
		candidateCount++;
		float distance = IsAiVsAiGangPressure(attacker, defender) ? localDistance : GetRetaliationTargetDistance(building, anchorBuilding);
		if (bestBuilding == null || priority < bestPriority || (priority == bestPriority && distance < bestDistance) || (priority == bestPriority && Mathf.Approximately(distance, bestDistance) && building.Id.id < bestBuilding.Id.id))
		{
			bestBuilding = building;
			bestKind = candidateKind;
			bestPriority = priority;
			bestDistance = distance;
		}
	}

	private static void ClearProtectedHumanRetaliationFrontTicker(PlayerInfo attacker, PlayerInfo defender, Entity building, EntityID protectorPeepId, string protectionReason, string sourceTag)
	{
		if (defender?.PID.IsHumanPlayer != true || building == null || building.Id.IsNotValid)
		{
			return;
		}
		if (!_pendingRetaliationFrontTickersByBuilding.TryGetValue(building.Id.id, out PendingRetaliationFrontTicker entry) || entry == null || entry.DefenderPid != defender.PID)
		{
			return;
		}
		if (attacker != null && entry.AttackerPid.IsAnyPlayer && entry.AttackerPid != attacker.PID)
		{
			return;
		}
		if (entry.CrewPeepId.IsNotValid && IsVanillaWillStealTickerMode(entry.Mode))
		{
			VerificationLog("GangOps.FrontTicker", $"vanilla-passive-warning-cleared attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} building={building.Id.id} protector={protectorPeepId.id} reason={protectionReason ?? "protected"} source={sourceTag}");
			ClearPendingRetaliationFrontTicker(building.Id.id, "vanilla-passive-warning", sourceTag);
			return;
		}
		VerificationLog("GangOps.FrontTicker", $"front-defense-protected-clear attacker={entry.AttackerPid.id} defender={entry.DefenderPid.id} building={building.Id.id} protector={protectorPeepId.id} reason={protectionReason ?? "protected"} source={sourceTag}");
		CrewAssignment frontCloserCrew = attacker?.crew != null && entry.CrewPeepId.IsValid ? attacker.crew.GetCrewForPeep(entry.CrewPeepId) : CrewAssignment.EMPTY;
		RegisterHumanFrontDefenseCombatSuppression(entry, defender, frontCloserCrew, new[] { protectorPeepId }, building, building.data?.board?.bead.nodeId ?? NodeID.INVALID, sourceTag);
		ClearPendingRetaliationFrontTicker(building.Id.id, "front-defended", sourceTag);
	}

	private static bool HasRuntimeFrontActionCrewWithinDistance(PlayerInfo attacker, Entity targetBuilding, float maxDistance, out float nearestDistance, out EntityID nearestPeepId, out NodeID nearestNodeId)
	{
		nearestDistance = float.MaxValue;
		nearestPeepId = EntityID.INVALID;
		nearestNodeId = NodeID.INVALID;
		if (attacker?.crew == null || targetBuilding?.data?.board == null || maxDistance <= 0f)
		{
			return false;
		}
		NodeID targetNodeId = targetBuilding.data.board.bead.nodeId;
		Node targetNode = targetNodeId.IsValid ? targetNodeId.FindNode() : null;
		if (targetNode?.id.IsValid != true)
		{
			return false;
		}
		HashSet<ulong> seenActionCrew = new HashSet<ulong>();
		foreach (CrewAssignment rawCrew in attacker.crew.GetLiving())
		{
			if (!TryResolveRuntimeFrontActionCrew(attacker, rawCrew, out CrewAssignment crew, out _))
			{
				continue;
			}
			if (!seenActionCrew.Add(crew.peepId.id))
			{
				continue;
			}
			if (ShouldRuntimeGangAttackerRetreat(attacker, crew, out _))
			{
				continue;
			}
			Entity peep = crew.GetPeep();
			if (peep?.data?.person == null || !peep.data.person.IsAlive)
			{
				continue;
			}
			if (!TryResolveRuntimeFrontActionCrewNodeQuiet(crew, peep, out NodeID currentNodeId, out _) || currentNodeId.IsNotValid)
			{
				continue;
			}
			Node currentNode = currentNodeId.FindNode();
			if (currentNode?.id.IsValid != true)
			{
				continue;
			}
			float distance = (targetNode.pos - currentNode.pos).Magnitude;
			if (distance < nearestDistance)
			{
				nearestDistance = distance;
				nearestPeepId = crew.peepId;
				nearestNodeId = currentNodeId;
			}
			if (distance <= maxDistance)
			{
				return true;
			}
		}
		if (float.IsPositiveInfinity(nearestDistance) || nearestDistance == float.MaxValue)
		{
			nearestDistance = -1f;
		}
		return false;
	}

	private static bool IsRetaliationFrontProtectedByHumanRoute(PlayerInfo defender, Entity building, out EntityID protectorPeepId, out EntityID protectorVehicleId, out NodeID protectorNodeId, out string reason)
	{
		protectorPeepId = EntityID.INVALID;
		protectorVehicleId = EntityID.INVALID;
		protectorNodeId = NodeID.INVALID;
		reason = "none";
		if (defender?.PID.IsHumanPlayer != true || defender.crew == null || building?.data?.board == null)
		{
			return false;
		}
		NodeID targetNodeId = building.data.board.bead.nodeId;
		Node targetNode = targetNodeId.IsValid ? targetNodeId.FindNode() : null;
		if (targetNode?.id.IsValid != true)
		{
			return false;
		}
		foreach (CrewAssignment crew in defender.crew.GetLiving().ToList())
		{
			if (!crew.IsValid || crew.IsDead || crew.peepId.IsNotValid)
			{
				continue;
			}
			Entity peep = crew.GetPeep();
			if (peep?.components?.agent == null || peep.components.agent.HasHealthPointsLeft != true)
			{
				continue;
			}
			NodeID peepNodeId = peep.data?.agent?.nid ?? NodeID.INVALID;
			if (peepNodeId.IsValid && peepNodeId == targetNodeId)
			{
				protectorPeepId = crew.peepId;
				protectorVehicleId = crew.VehicleID;
				protectorNodeId = targetNodeId;
				reason = "crew-at-front";
				return true;
			}
			if (!crew.IsInVehicle || !crew.VehicleID.IsValid)
			{
				continue;
			}
			if (!MultiCrewVehicleHelper.TryGetPendingHumanVehicleTravel(crew.VehicleID, out EntityID routePeepId, out NodeID expectedNodeId, out NodeID goalNodeId))
			{
				continue;
			}
			bool routeActive = MultiCrewVehicleHelper.IsHumanVehicleTravelActive(crew.VehicleID)
				|| MultiCrewVehicleHelper.HasQueuedHumanVehiclePendingResume(crew.VehicleID)
				|| expectedNodeId.IsValid;
			if (!routeActive)
			{
				continue;
			}
			if (expectedNodeId.IsValid && expectedNodeId == targetNodeId)
			{
				protectorPeepId = routePeepId.IsValid ? routePeepId : crew.peepId;
				protectorVehicleId = crew.VehicleID;
				protectorNodeId = targetNodeId;
				reason = "route-expected-next-segment";
				return true;
			}
			if (goalNodeId.IsValid && goalNodeId == targetNodeId && CanHumanCrewReachNodeOnNextMovementRefill(defender.PID, peep, targetNode, out int nextMoves, out Fixnum routeCost, out string routeReason))
			{
				protectorPeepId = routePeepId.IsValid ? routePeepId : crew.peepId;
				protectorVehicleId = crew.VehicleID;
				protectorNodeId = targetNodeId;
				reason = $"route-goal-reachable-next-turn moves={nextMoves} cost={routeCost} detail={routeReason}";
				return true;
			}
		}
		return false;
	}

	private static bool IsRetaliationFrontProtectedByHumanPhysicalPresence(PlayerInfo defender, Entity building, out EntityID protectorPeepId, out EntityID protectorVehicleId, out NodeID protectorNodeId, out string reason)
	{
		protectorPeepId = EntityID.INVALID;
		protectorVehicleId = EntityID.INVALID;
		protectorNodeId = NodeID.INVALID;
		reason = "none";
		if (defender?.PID.IsHumanPlayer != true || defender.crew == null || building?.data?.board == null)
		{
			return false;
		}
		NodeID targetNodeId = building.data.board.bead.nodeId;
		if (targetNodeId.IsNotValid)
		{
			return false;
		}
		foreach (CrewAssignment crew in defender.crew.GetLiving().ToList())
		{
			if (!crew.IsValid || crew.IsDead || crew.peepId.IsNotValid)
			{
				continue;
			}
			Entity peep = crew.GetPeep();
			if (peep?.components?.agent == null || peep.components.agent.HasHealthPointsLeft != true)
			{
				continue;
			}
			NodeID peepNodeId = peep.data?.agent?.nid ?? NodeID.INVALID;
			if (peepNodeId.IsValid && peepNodeId == targetNodeId)
			{
				protectorPeepId = crew.peepId;
				protectorVehicleId = crew.VehicleID;
				protectorNodeId = targetNodeId;
				reason = "crew-at-front";
				return true;
			}
		}
		return false;
	}

	private static bool CanHumanCrewReachNodeOnNextMovementRefill(PlayerID pid, Entity peep, Node targetNode, out int nextMoves, out Fixnum routeCost, out string reason)
	{
		nextMoves = 0;
		routeCost = Fixnum.ZERO;
		reason = "none";
		try
		{
			if (peep?.components?.agent == null || targetNode == null || !targetNode.id.IsValid)
			{
				reason = "missing-route-context";
				return false;
			}
			var points = peep.components.agent.GetMovesAndActionsPerTurn();
			nextMoves = Mathf.Max(peep.components.agent.MovesRemaining, points.moves);
			if (nextMoves <= 0)
			{
				reason = "no-next-turn-moves";
				return false;
			}
			PathData path = CommandGoto.MakePath(pid, peep, targetNode, new Fixnum(nextMoves));
			if (path == null || path.nodes == null || path.nodes.Count == 0)
			{
				reason = "no-path";
				return false;
			}
			NodeID lastNodeId = path.nodes.LastOrDefault()?.node?.id ?? NodeID.INVALID;
			routeCost = path.cost;
			if (lastNodeId == targetNode.id && path.cost <= nextMoves)
			{
				reason = "reachable";
				return true;
			}
			reason = $"insufficient-moves lastNode={lastNodeId}";
			return false;
		}
		catch (Exception ex)
		{
			reason = "route-check-failed-" + ex.GetType().Name;
			return false;
		}
	}

	private static bool IsRetaliationFrontAlreadyPending(PlayerInfo defender, Entity building, out PlayerID pendingAttackerPid, out string pendingMode)
	{
		pendingAttackerPid = PlayerID.INVALID;
		pendingMode = string.Empty;
		if (defender == null || building == null || building.Id.IsNotValid)
		{
			return false;
		}
		if (!_pendingRetaliationFrontTickersByBuilding.TryGetValue(building.Id.id, out PendingRetaliationFrontTicker entry) || entry == null)
		{
			return false;
		}
		if (entry.DefenderPid != defender.PID)
		{
			return false;
		}
		pendingAttackerPid = entry.AttackerPid;
		pendingMode = entry.Mode ?? string.Empty;
		return true;
	}

	private static bool IsRetaliationOutpostFront(PlayerInfo defender, Entity building)
	{
		try
		{
			if (defender?.outposts == null || building?.components?.building == null || building.components.building.IsSafehouse)
			{
				return false;
			}
			OutpostID outpostId = new OutpostID(building);
			return defender.outposts.GetOutpostEntryUnsafe(outpostId) != null && building.data.building.outpost == defender.PID;
		}
		catch
		{
			return false;
		}
	}

	private static bool IsRetaliationControlledFront(PlayerInfo defender, Entity building)
	{
		try
		{
			return defender?.territory != null
				&& building?.components?.building != null
				&& !building.components.building.IsSafehouse
				&& defender.territory.IsControlled(building);
		}
		catch
		{
			return false;
		}
	}

	private static bool HasRetaliationBackroomModule(Entity building)
	{
		try
		{
			return building?.components?.modules != null && building.components.modules.HasBackroomModules();
		}
		catch
		{
			return false;
		}
	}

	private static float GetRetaliationTargetDistance(Entity building, Entity anchorBuilding)
	{
		try
		{
			if (building?.data?.board == null || anchorBuilding?.data?.board == null)
			{
				return 0f;
			}
			return (building.data.board.worldpos - anchorBuilding.data.board.worldpos).Magnitude;
		}
		catch
		{
			return 0f;
		}
	}

	private static bool IsAiVsAiGangPressure(PlayerInfo attacker, PlayerInfo defender)
	{
		return attacker?.PID.IsHumanPlayer == false && defender?.PID.IsHumanPlayer == false;
	}

	private static bool IsAiVsAiFrontClosurePowerAllowed(PlayerInfo attacker, PlayerInfo defender, int attackerPower, int defenderPower, out string reason)
	{
		reason = "allowed";
		if (!IsAiVsAiGangPressure(attacker, defender))
		{
			return true;
		}
		if (attackerPower + 25 < defenderPower)
		{
			reason = "defender-materially-larger";
			return false;
		}
		return true;
	}

	private static float GetAiVsAiFrontStealMaxLocalDistance(int attackerPower, int defenderPower)
	{
		if (attackerPower >= defenderPower + 45 || attackerPower >= Mathf.RoundToInt(defenderPower * 1.35f))
		{
			return AI_VS_AI_FRONT_STEAL_OVERRUN_MAX_LOCAL_DISTANCE;
		}
		if (attackerPower >= defenderPower + 15)
		{
			return AI_VS_AI_FRONT_STEAL_STRONG_MAX_LOCAL_DISTANCE;
		}
		return AI_VS_AI_FRONT_STEAL_NEUTRAL_MAX_LOCAL_DISTANCE;
	}

	private static bool TryGetNearestAttackerRetaliationAnchorDistance(PlayerInfo attacker, Entity targetBuilding, out float bestDistance)
	{
		bestDistance = float.MaxValue;
		if (attacker == null || targetBuilding?.data?.board == null)
		{
			return false;
		}
		bool found = false;
		try
		{
			Node headquartersNode = attacker.territory?.GetHeadquartersNode(ignoreWarnings: true);
			if (headquartersNode != null)
			{
				bestDistance = (targetBuilding.data.board.worldpos - headquartersNode.pos).Magnitude;
				found = true;
			}
		}
		catch
		{
		}
		foreach (Entity building in GetOwnedBuildings(attacker).Take(24))
		{
			try
			{
				if (building?.data?.board == null)
				{
					continue;
				}
				float distance = (targetBuilding.data.board.worldpos - building.data.board.worldpos).Magnitude;
				if (!found || distance < bestDistance)
				{
					bestDistance = distance;
					found = true;
				}
			}
			catch
			{
			}
		}
		return found;
	}

	private static bool IsRetaliationFrontLocalEnough(PlayerInfo attacker, PlayerInfo defender, Entity targetBuilding, out float distance, out float maxDistance, out string reason)
	{
		distance = 0f;
		maxDistance = 0f;
		reason = "not-ai-vs-ai";
		if (!IsAiVsAiGangPressure(attacker, defender))
		{
			return true;
		}
		int attackerPower = CalculateGangPower(attacker);
		int defenderPower = CalculateGangPower(defender);
		if (!IsAiVsAiFrontClosurePowerAllowed(attacker, defender, attackerPower, defenderPower, out reason))
		{
			return false;
		}
		maxDistance = GetAiVsAiFrontStealMaxLocalDistance(attackerPower, defenderPower);
		if (!TryGetNearestAttackerRetaliationAnchorDistance(attacker, targetBuilding, out distance))
		{
			reason = "no-attacker-local-anchor";
			return false;
		}
		if (distance > maxDistance)
		{
			reason = "too-far";
			return false;
		}
		reason = "local";
		return true;
	}

	private static void LogRetaliationFrontLocalBlocked(PlayerInfo attacker, PlayerInfo defender, Entity building, string kind, string sourceKind, float distance, float maxDistance, string reason)
	{
		VerificationLog("GangOps.FrontMovement", $"front-local-blocked attacker={attacker?.PID.id ?? 0} defender={defender?.PID.id ?? 0} building={building?.Id.id ?? 0UL} distance={distance:0.0} max={maxDistance:0.0} kind={kind ?? "unknown"} reason={reason ?? "unknown"} source={sourceKind ?? "unknown"}");
	}

	private static void TryLogAiFrontClosureGrapevine(PlayerInfo attacker, PlayerInfo defender, string actionSummary, string sourceTag)
	{
		if (!IsAiVsAiGangPressure(attacker, defender) || string.IsNullOrEmpty(actionSummary) || IsRobberyRetaliationSource(sourceTag))
		{
			return;
		}
		if (!actionSummary.StartsWith("front-steal", StringComparison.Ordinal)
			&& !actionSummary.StartsWith("front-building-attack", StringComparison.Ordinal)
			&& !actionSummary.StartsWith("backroom-attack", StringComparison.Ordinal)
			&& !actionSummary.StartsWith("forced-close", StringComparison.Ordinal))
		{
			return;
		}
		int nowDay = GetGrapevineLogDay();
		string key = $"{attacker.PID.id}:{defender.PID.id}";
		if (nowDay >= 0 && _aiFrontClosureGrapevineLastDayByPair.TryGetValue(key, out int lastDay) && nowDay - lastDay < AI_FRONT_CLOSURE_GRAPEVINE_COOLDOWN_DAYS)
		{
			VerificationLog("Grapevine", $"ai-front-closure-suppressed attacker={attacker.PID.id} defender={defender.PID.id} lastDay={lastDay} day={nowDay} action={actionSummary} source={sourceTag}");
			return;
		}
		if (nowDay >= 0)
		{
			_aiFrontClosureGrapevineLastDayByPair[key] = nowDay;
		}
		int attackerPower = CalculateGangPower(attacker);
		int defenderPower = CalculateGangPower(defender);
		string attackerName = GetGangDisplayName(attacker.PID.id);
		string defenderName = GetGangDisplayName(defender.PID.id);
		string pressureText = attackerPower >= defenderPower + 45 || attackerPower >= Mathf.RoundToInt(defenderPower * 1.35f)
			? "pressed its size advantage against"
			: (attackerPower >= defenderPower + 15 ? "leaned into nearby turf held by" : "made a local move against");
		string targetText = actionSummary.StartsWith("backroom-attack", StringComparison.Ordinal)
			? "a back room"
			: "a front";
		LogGrapevine($"TURF: {attackerName} {pressureText} {defenderName}, targeting {targetText}.");
		VerificationLog("Grapevine", $"ai-front-closure-posted attacker={attacker.PID.id} defender={defender.PID.id} attackerPower={attackerPower} defenderPower={defenderPower} action={actionSummary} source={sourceTag}");
	}

	private static bool TryFindRetaliationClosureTarget(PlayerInfo attacker, PlayerInfo defender, out Entity targetBuilding, out string reason)
	{
		targetBuilding = null;
		reason = "none";
		if (TryFindAiForcedClosureTradeTarget(attacker, defender, out targetBuilding, out reason))
		{
			return true;
		}

		string tradeTargetReason = reason;
		List<Entity> ownedBuildings = GetOwnedBuildings(defender);
		if (ownedBuildings.Count == 0)
		{
			reason = string.IsNullOrEmpty(tradeTargetReason) || string.Equals(tradeTargetReason, "none", StringComparison.Ordinal)
				? "no-owned-buildings"
				: tradeTargetReason + "+no-owned-buildings";
			return false;
		}
		int candidateCount = 0;
		int localBlockedCount = 0;
		float bestLocalDistance = float.MaxValue;
		foreach (Entity building in ownedBuildings.OrderBy(building => building.Id.id))
		{
			if (!IsRetaliationClosureCandidate(attacker, defender, building))
			{
				continue;
			}
			candidateCount++;
			if (!IsRetaliationFrontLocalEnough(attacker, defender, building, out float localDistance, out float maxLocalDistance, out string localReason))
			{
				localBlockedCount++;
				LogRetaliationFrontLocalBlocked(attacker, defender, building, "closure", "closure-fallback", localDistance, maxLocalDistance, localReason);
				continue;
			}
			if (defender?.PID.IsHumanPlayer == true && !HasRuntimeFrontActionCrewWithinDistance(attacker, building, AI_VS_HUMAN_FRONT_ACTION_MAX_CREW_DISTANCE, out float nearestCrewDistance, out EntityID nearestCrewPeepId, out NodeID nearestCrewNodeId))
			{
				VerificationLog("GangOps.FrontMovement", $"front-target-crew-too-far attacker={attacker?.PID.id ?? 0} defender={defender?.PID.id ?? 0} building={building.Id.id} node={building.data?.board?.bead.nodeId ?? NodeID.INVALID} nearestPeep={nearestCrewPeepId.id} nearestNode={nearestCrewNodeId} distance={nearestCrewDistance:0.0} maxDistance={AI_VS_HUMAN_FRONT_ACTION_MAX_CREW_DISTANCE:0.0} kind=closure source=closure-fallback");
				continue;
			}
			if (targetBuilding == null || localDistance < bestLocalDistance || (Mathf.Approximately(localDistance, bestLocalDistance) && building.Id.id < targetBuilding.Id.id))
			{
				targetBuilding = building;
				bestLocalDistance = localDistance;
			}
		}
		if (targetBuilding == null)
		{
			reason = string.IsNullOrEmpty(tradeTargetReason) || string.Equals(tradeTargetReason, "none", StringComparison.Ordinal)
				? $"no-closeable-business candidates={candidateCount} localBlocked={localBlockedCount}"
				: $"{tradeTargetReason}+no-closeable-business candidates={candidateCount} localBlocked={localBlockedCount}";
			return false;
		}
		return true;
	}

	private static bool TryFindRobberyRetaliationImportantBusinessTarget(PlayerInfo attacker, PlayerInfo defender, out Entity targetBuilding, out string reason)
	{
		targetBuilding = null;
		reason = "none";
		if (!IsAliveGangPlayer(attacker) || defender == null || attacker.territory == null)
		{
			reason = "robbery-business-target-ineligible";
			return false;
		}
		if (TryFindRobberyTradeHistoryImportantBusinessTarget(attacker, defender, out targetBuilding, out reason))
		{
			return true;
		}
		if (TryFindAiForcedClosureTradeTarget(attacker, defender, out targetBuilding, out reason)
			&& IsRouteFailedRetaliationBusinessFallbackCandidate(attacker, defender, targetBuilding, null, out _, out string tradeCandidateReason, out _, out _, out _))
		{
			reason = tradeCandidateReason;
			return true;
		}
		targetBuilding = null;

		try
		{
			List<Node> nodes = new List<Node>();
			HashSet<NodeID> seenNodes = new HashSet<NodeID>();
			try
			{
				AddForcedClosureSearchNodes(attacker.territory.GetHeadquartersNode(ignoreWarnings: true), AI_FORCED_CLOSURE_HQ_SEARCH_RADIUS, nodes, seenNodes);
			}
			catch
			{
			}
			try
			{
				AddForcedClosureSearchNodes(defender.territory?.GetHeadquartersNode(ignoreWarnings: true), AI_FORCED_CLOSURE_HQ_SEARCH_RADIUS, nodes, seenNodes);
			}
			catch
			{
			}
			foreach (Entity building in GetOwnedBuildings(attacker).Take(12))
			{
				NodeID nodeId = building?.data?.board?.bead.nodeId ?? NodeID.INVALID;
				AddForcedClosureSearchNodes(nodeId.IsValid ? nodeId.FindNode() : null, AI_FORCED_CLOSURE_FRONT_SEARCH_RADIUS, nodes, seenNodes);
			}
			foreach (Entity building in GetOwnedBuildings(defender).Take(18))
			{
				NodeID nodeId = building?.data?.board?.bead.nodeId ?? NodeID.INVALID;
				AddForcedClosureSearchNodes(nodeId.IsValid ? nodeId.FindNode() : null, AI_FORCED_CLOSURE_FRONT_SEARCH_RADIUS, nodes, seenNodes);
			}
			if (nodes.Count == 0)
			{
				reason = "no-robbery-business-search-nodes";
				return false;
			}

			int scanned = 0;
			int candidateCount = 0;
			int locked = 0;
			int skippedFront = 0;
			int wrongTerritory = 0;
			int bestPriority = int.MaxValue;
			float bestDistance = float.MaxValue;
			HashSet<ulong> seenBuildings = new HashSet<ulong>();
			foreach (Node node in nodes)
			{
				if (node == null)
				{
					continue;
				}
				IEnumerable<EntityID> interestingIds = node.interesting ?? Enumerable.Empty<EntityID>();
				foreach (EntityID entityId in (node.contained ?? Enumerable.Empty<EntityID>()).Concat(interestingIds))
				{
					Entity entity = entityId.FindEntity();
					Entity building = ResolveBusinessFallbackBuilding(entity);
					if (building?.components?.building == null || !seenBuildings.Add(building.Id.id))
					{
						continue;
					}
					scanned++;
					if (!IsRouteFailedRetaliationBusinessFallbackCandidate(attacker, defender, building, null, out int priority, out string candidateReason, out bool blockedByLock, out bool blockedAsFront, out bool blockedByTerritory))
					{
						if (blockedByLock)
						{
							locked++;
						}
						if (blockedAsFront)
						{
							skippedFront++;
						}
						if (blockedByTerritory)
						{
							wrongTerritory++;
						}
						continue;
					}
					candidateCount++;
					float distance = 0f;
					try
					{
						NodeID buildingNodeId = building.data?.board?.bead.nodeId ?? NodeID.INVALID;
						Node buildingNode = buildingNodeId.IsValid ? buildingNodeId.FindNode() : null;
						Node attackerHq = attacker.territory.GetHeadquartersNode(ignoreWarnings: true);
						if (buildingNode != null && attackerHq != null)
						{
							distance = (buildingNode.pos - attackerHq.pos).Magnitude;
						}
					}
					catch
					{
					}
					if (targetBuilding == null
						|| priority < bestPriority
						|| (priority == bestPriority && distance < bestDistance)
						|| (priority == bestPriority && Mathf.Approximately(distance, bestDistance) && building.Id.id < targetBuilding.Id.id))
					{
						targetBuilding = building;
						bestPriority = priority;
						bestDistance = distance;
						reason = candidateReason;
					}
				}
			}

			if (targetBuilding == null)
			{
				reason = $"no-robbery-important-business scanned={scanned} candidates={candidateCount} locked={locked} skippedFront={skippedFront} wrongTerritory={wrongTerritory}";
				return false;
			}
			return true;
		}
		catch (Exception ex)
		{
			reason = "robbery-important-business-scan-failed-" + ex.GetType().Name;
			return false;
		}
	}

	private static bool TryFindRobberyTradeHistoryImportantBusinessTarget(PlayerInfo attacker, PlayerInfo defender, out Entity targetBuilding, out string reason)
	{
		targetBuilding = null;
		reason = "none";
		if (!IsAliveGangPlayer(attacker) || defender == null || !defender.PID.IsAnyPlayer || attacker.territory == null || global::Game.Game.ctx?.board?.nodes == null)
		{
			reason = "robbery-trade-history-ineligible";
			return false;
		}
		try
		{
			Node attackerHq = null;
			try
			{
				attackerHq = attacker.territory.GetHeadquartersNode(ignoreWarnings: true);
			}
			catch
			{
			}

			int scanned = 0;
			int tradeHistoryCount = 0;
			int skippedFront = 0;
			int ownTerritory = 0;
			int locked = 0;
			int invalidShop = 0;
			float bestDistance = float.MaxValue;
			HashSet<ulong> seenBuildings = new HashSet<ulong>();
			foreach (Node node in global::Game.Game.ctx.board.nodes.GetAllNodesUnsafe())
			{
				if (node?.interesting == null || node.interesting.Count == 0)
				{
					continue;
				}
				foreach (EntityID interestingId in node.interesting)
				{
					Entity interesting = interestingId.FindEntity();
					Entity bizEntity = BuildingUtil.FindBizForBuilding(interesting);
					BizComponent biz = bizEntity?.components?.biz;
					if (biz == null)
					{
						continue;
					}
					scanned++;
					if (!biz.HasAnyTradeHistory(defender.PID))
					{
						continue;
					}
					tradeHistoryCount++;
					Entity building = BuildingUtil.FindBuildingForBiz(bizEntity) ?? ResolveBusinessFallbackBuilding(interesting);
					if (building?.components?.building == null || !seenBuildings.Add(building.Id.id))
					{
						continue;
					}
					if (IsRetaliationFrontAlreadyPending(defender, building, out _, out _))
					{
						continue;
					}
					if (!TryValidateRetaliationImportantShopTarget(building, out Entity validatedBizEntity, out _))
					{
						invalidShop++;
						continue;
					}
					bizEntity = validatedBizEntity;
					biz = bizEntity.components.biz;
					if (building.components.building.IsSafehouse
						|| building.components.building.IsOutpost
						|| building.data?.building?.controlled?.Get().IsAnyPlayer == true)
					{
						skippedFront++;
						continue;
					}
					PlayerID nodeOwner = node.owner?.Get() ?? PlayerID.INVALID;
					if (nodeOwner == attacker.PID)
					{
						ownTerritory++;
						continue;
					}
					BizComponent.TradeRestrictions restrictions = biz.FindTradeRestrictions(attacker.PID);
					if (!IsForcedClosureRestrictionAllowedForRetaliation(restrictions, defender.PID, out _))
					{
						locked++;
						continue;
					}

					float distance = 0f;
					try
					{
						distance = attackerHq != null ? (building.data.board.worldpos - attackerHq.pos).Magnitude : 0f;
					}
					catch
					{
					}
					if (targetBuilding == null || distance < bestDistance || (Mathf.Approximately(distance, bestDistance) && building.Id.id < targetBuilding.Id.id))
					{
						targetBuilding = building;
						bestDistance = distance;
					}
				}
			}
			if (targetBuilding == null)
			{
				reason = $"no-robbery-trade-history-business scanned={scanned} tradeHistory={tradeHistoryCount} skippedFront={skippedFront} ownTerritory={ownTerritory} locked={locked} invalidShop={invalidShop}";
				return false;
			}
			reason = "robbery-trade-history-anywhere";
			return true;
		}
		catch (Exception ex)
		{
			reason = "robbery-trade-history-scan-failed-" + ex.GetType().Name;
			return false;
		}
	}

	private static bool TryFindAiForcedClosureTradeTarget(PlayerInfo attacker, PlayerInfo defender, out Entity targetBuilding, out string reason)
	{
		targetBuilding = null;
		reason = "none";
		if (!IsAliveGangPlayer(attacker) || defender == null || attacker.territory == null)
		{
			reason = "trade-target-ineligible";
			return false;
		}
		try
		{
			List<Node> nodes = new List<Node>();
			HashSet<NodeID> seenNodes = new HashSet<NodeID>();
			Node headquartersNode = null;
			try
			{
				headquartersNode = attacker.territory.GetHeadquartersNode(ignoreWarnings: true);
			}
			catch
			{
			}
			AddForcedClosureSearchNodes(headquartersNode, AI_FORCED_CLOSURE_HQ_SEARCH_RADIUS, nodes, seenNodes);
			foreach (Entity building in GetOwnedBuildings(attacker).Take(12))
			{
				NodeID buildingNodeId = building?.data?.board?.bead.nodeId ?? NodeID.INVALID;
				Node buildingNode = buildingNodeId.IsValid ? buildingNodeId.FindNode() : null;
				AddForcedClosureSearchNodes(buildingNode, AI_FORCED_CLOSURE_FRONT_SEARCH_RADIUS, nodes, seenNodes);
			}

			if (nodes.Count == 0)
			{
				reason = "no-forced-closure-search-nodes";
				return false;
			}

			float bestDistance = float.MaxValue;
			int tradeHistoryCount = 0;
			int lockedCount = 0;
			int defenderLockCount = 0;
			int forcedClosedCount = 0;
			int invalidShopCount = 0;
			HashSet<ulong> seenBuildings = new HashSet<ulong>();
			foreach (Node node in nodes)
			{
				if (node?.interesting == null)
				{
					continue;
				}
				foreach (EntityID interestingId in node.interesting)
				{
					Entity interesting = interestingId.FindEntity();
					Entity bizEntity = BuildingUtil.FindBizForBuilding(interesting);
					BizComponent biz = bizEntity?.components?.biz;
					if (biz == null || !biz.HasAnyTradeHistory(defender.PID))
					{
						continue;
					}
					tradeHistoryCount++;
					BizComponent.TradeRestrictions restrictions = biz.FindTradeRestrictions(attacker.PID);
					if (!IsForcedClosureRestrictionAllowedForRetaliation(restrictions, defender.PID, out string lockReason))
					{
						lockedCount++;
						if (restrictions.IsForcedClosed)
						{
							forcedClosedCount++;
						}
						continue;
					}
					if (restrictions.IsTerritoryLocked || restrictions.IsTiedHouseLocked)
					{
						defenderLockCount++;
					}

					Entity building = BuildingUtil.FindBuildingForBiz(bizEntity) ?? interesting;
					if (building?.components?.building == null || building.components.building.IsSafehouse || !seenBuildings.Add(building.Id.id))
					{
						continue;
					}
					if (IsRetaliationFrontAlreadyPending(defender, building, out _, out _))
					{
						continue;
					}
					if (!TryValidateRetaliationImportantShopTarget(building, out Entity validatedBizEntity, out _))
					{
						invalidShopCount++;
						continue;
					}
					bizEntity = validatedBizEntity;
					biz = bizEntity.components.biz;

					if (!IsRetaliationFrontLocalEnough(attacker, defender, building, out float localDistance, out float maxLocalDistance, out string localReason))
					{
						LogRetaliationFrontLocalBlocked(attacker, defender, building, "forced-closure", "ai-forced-closure", localDistance, maxLocalDistance, localReason);
						continue;
					}
					if (defender?.PID.IsHumanPlayer == true && !HasRuntimeFrontActionCrewWithinDistance(attacker, building, AI_VS_HUMAN_FRONT_ACTION_MAX_CREW_DISTANCE, out float nearestCrewDistance, out EntityID nearestCrewPeepId, out NodeID nearestCrewNodeId))
					{
						VerificationLog("GangOps.FrontMovement", $"front-target-crew-too-far attacker={attacker?.PID.id ?? 0} defender={defender?.PID.id ?? 0} building={building.Id.id} node={building.data?.board?.bead.nodeId ?? NodeID.INVALID} nearestPeep={nearestCrewPeepId.id} nearestNode={nearestCrewNodeId} distance={nearestCrewDistance:0.0} maxDistance={AI_VS_HUMAN_FRONT_ACTION_MAX_CREW_DISTANCE:0.0} kind=forced-closure source=ai-forced-closure");
						continue;
					}

					float distance = localDistance;
					try
					{
						if (!IsAiVsAiGangPressure(attacker, defender))
						{
							distance = headquartersNode != null ? (building.data.board.worldpos - headquartersNode.pos).Magnitude : 0f;
						}
					}
					catch
					{
					}
					if (targetBuilding == null || distance < bestDistance || (Mathf.Approximately(distance, bestDistance) && building.Id.id < targetBuilding.Id.id))
					{
						targetBuilding = building;
						bestDistance = distance;
					}
				}
			}

			if (targetBuilding == null)
			{
				reason = tradeHistoryCount > 0
					? $"no-ai-forced-closure-target locked={lockedCount} defenderLocks={defenderLockCount} forcedClosed={forcedClosedCount} tradeHistory={tradeHistoryCount} invalidShop={invalidShopCount}"
					: "no-ai-forced-closure-trade-history";
				return false;
			}

			reason = defenderLockCount > 0 ? "ai-forced-closure-defender-lock" : "ai-forced-closure-trade-history";
			return true;
		}
		catch (Exception ex)
		{
			reason = "ai-forced-closure-scan-failed-" + ex.GetType().Name;
			return false;
		}
	}

	private static void AddForcedClosureSearchNodes(Node center, float radius, List<Node> nodes, HashSet<NodeID> seenNodes)
	{
		if (center == null || !center.id.IsValid || nodes == null || seenNodes == null || global::Game.Game.ctx?.board?.nodes == null)
		{
			return;
		}
		try
		{
			foreach (Node node in global::Game.Game.ctx.board.nodes.FindAndSortNodesInRadius(center.pos, radius, sort: false))
			{
				if (node != null && node.id.IsValid && seenNodes.Add(node.id))
				{
					nodes.Add(node);
				}
			}
		}
		catch
		{
		}
	}

	private static bool IsForcedClosureRestrictionAllowedForRetaliation(BizComponent.TradeRestrictions restrictions, PlayerID defenderPid, out string reason)
	{
		reason = "unlocked";
		if (restrictions.IsForcedClosed)
		{
			reason = "already-forced-closed";
			return false;
		}
		bool territoryLockedByDefender = restrictions.IsTerritoryLocked && restrictions.territoryLock == defenderPid;
		bool tiedLockedByDefender = restrictions.IsTiedHouseLocked && restrictions.tiedHouseLock == defenderPid;
		if (territoryLockedByDefender || tiedLockedByDefender)
		{
			reason = territoryLockedByDefender && tiedLockedByDefender
				? "defender-territory-and-tied-lock"
				: (territoryLockedByDefender ? "defender-territory-lock" : "defender-tied-lock");
			return true;
		}
		if (restrictions.IsLocked)
		{
			reason = restrictions.IsTerritoryLocked
				? "third-party-territory-lock"
				: (restrictions.IsTiedHouseLocked ? "third-party-tied-lock" : "locked");
			return false;
		}
		return true;
	}

	private static bool IsRetaliationClosureCandidate(PlayerInfo attacker, PlayerInfo defender, Entity building)
	{
		if (attacker == null || defender == null || building == null)
		{
			return false;
		}
		try
		{
			if (building.components?.building == null || building.components.building.IsSafehouse)
			{
				return false;
			}
			if (IsRetaliationFrontAlreadyPending(defender, building, out _, out _))
			{
				return false;
			}
			Entity bizEntity = BuildingUtil.FindBizForBuilding(building);
			if (bizEntity?.components?.biz == null)
			{
				return false;
			}
			BizComponent.TradeRestrictions restrictions = bizEntity.components.biz.FindTradeRestrictions(attacker.PID);
			return IsForcedClosureRestrictionAllowedForRetaliation(restrictions, defender.PID, out _);
		}
		catch
		{
			return false;
		}
	}

	private static List<Entity> GetOwnedBuildings(PlayerInfo player)
	{
		List<Entity> list = new List<Entity>();
		if (player?.territory == null)
		{
			return list;
		}
		try
		{
			Type territoryType = player.territory.GetType();
			const BindingFlags flags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
			object obj = territoryType.GetMethod("GetAllControlledBuildingsUnsafe", flags)?.Invoke(player.territory, null);
			if (obj == null)
			{
				FieldInfo fieldInfo = territoryType.GetField("_buildings", flags) ?? territoryType.GetField("buildings", flags);
				PropertyInfo propertyInfo = territoryType.GetProperty("OwnedBuildings", flags) ?? territoryType.GetProperty("Buildings", flags);
				obj = fieldInfo?.GetValue(player.territory) ?? propertyInfo?.GetValue(player.territory);
			}
			if (!(obj is IEnumerable<EntityID> enumerable))
			{
				return list;
			}
			HashSet<ulong> seen = new HashSet<ulong>();
			foreach (EntityID item in enumerable)
			{
				if (!item.IsNotValid && seen.Add(item.id))
				{
					Entity val = EntityIDExtensions.FindEntity(item);
					if (val != null)
					{
						list.Add(val);
					}
				}
			}
		}
		catch
		{
		}
		return list;
	}

	private static bool IsOutpostBuilding(Entity building)
	{
		if (building == null)
		{
			return false;
		}
		string text = building.ToString() ?? string.Empty;
		if (text.IndexOf("outpost", StringComparison.OrdinalIgnoreCase) >= 0)
		{
			return true;
		}
		try
		{
			string text2 = building.data?.building?.ToString() ?? string.Empty;
			if (text2.IndexOf("outpost", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				return true;
			}
		}
		catch
		{
		}
		return false;
	}

	private static int RunAutoProtectPass(GangOpsChannel channel, int nowDay)
	{
		return RunAutoProtectPass(channel, nowDay, GetEligibleGangIdsForChannel(channel));
	}

	private static int RunAutoProtectPass(GangOpsChannel channel, int nowDay, List<int> eligibleGangIds)
	{
		if (!EnableAIAlliances.Value || !IsGangOpsEnabled(channel))
		{
			return 0;
		}
		PactOpsSettings pactOpsSettings = EnsureGangOpsSettings(channel);
		if (!pactOpsSettings.AutoProtectEnabled)
		{
			return 0;
		}
		Dictionary<int, int> autoProtectDayStore = GetAutoProtectDayStore(channel);
		int protectedGangCount = 0;
		int protectedNodeCount = 0;
		int supportResetCount = 0;
		int ownershipActionCount = 0;
		int quietProtectedGangCount = 0;
		foreach (int item in eligibleGangIds)
		{
			PlayerInfo playerInfo = G.FindPlayerById(item);
			if (!IsAliveGangPlayer(playerInfo) || playerInfo.PID.IsHumanPlayer)
			{
				continue;
			}
			if (autoProtectDayStore.TryGetValue(item, out int value) && nowDay - value < pactOpsSettings.AutoProtectIntervalDays)
			{
				continue;
			}
			int ownershipActions = DirtyCashEconomyCompatibilityPatch.TryRunGangOpsAutoProtectPass(
				channel,
				playerInfo,
				pactOpsSettings.AutoProtectRange,
				$"auto-protect-day-{nowDay}",
				out int outpostCount,
				out int targetNodeCount,
				out int supportResets,
				out int advisorDeferred);
			if (outpostCount <= 0)
			{
				continue;
			}

			autoProtectDayStore[item] = nowDay;
			protectedGangCount++;
			protectedNodeCount += targetNodeCount;
			supportResetCount += supportResets;
			ownershipActionCount += ownershipActions;
			if (supportResets > 0 || ownershipActions > 0 || advisorDeferred > 0)
			{
				List<Entity> ownedBuildings = GetOwnedBuildings(playerInfo);
				int businessCount = 0;
				for (int buildingIndex = 0; buildingIndex < ownedBuildings.Count; buildingIndex++)
				{
					if (!IsOutpostBuilding(ownedBuildings[buildingIndex]))
					{
						businessCount++;
					}
				}
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.AutoProtect", $"Gang {item} advisor-preserved fronts={outpostCount} businesses={businessCount} nodes={targetNodeCount} advisorDeferred={advisorDeferred} supportResets={supportResets} ownershipActions={ownershipActions} requestedRange={pactOpsSettings.AutoProtectRange}");
			}
			else
			{
				quietProtectedGangCount++;
			}
		}
		if (protectedGangCount > 0)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.AutoProtect", $"summary gangs={protectedGangCount} quiet={quietProtectedGangCount} nodes={protectedNodeCount} supportResets={supportResetCount} ownershipActions={ownershipActionCount} intervalDays={pactOpsSettings.AutoProtectIntervalDays}");
		}
		return protectedGangCount;
	}

	private static PlayerInfo PickCoordinatedAttackTarget(PlayerInfo attacker, HashSet<int> alliedGangIds, Dictionary<string, WarHeatEntry> warHeatStore)
	{
		if (!IsAliveGangPlayer(attacker))
		{
			return null;
		}
		GangOpsChannel channel = ResolveGangOpsChannelForGang(attacker.PID.id);
		PlayerInfo playerInfo = null;
		float num = 0f;
		foreach (KeyValuePair<string, WarHeatEntry> item in warHeatStore)
		{
			WarHeatEntry value = item.Value;
			if (value == null || value.AttackerPid != attacker.PID.id)
			{
				continue;
			}
			if (alliedGangIds.Contains(value.DefenderPid))
			{
				continue;
			}
			PlayerInfo playerInfo2 = G.FindPlayerById(value.DefenderPid);
			float effectiveHeat = GetRelationshipAdjustedWarHeat(channel, attacker, playerInfo2, value.Heat, out _, out _, out _, out _);
			if (effectiveHeat <= num)
			{
				continue;
			}
			if (playerInfo2 != null && playerInfo2.crew != null && !playerInfo2.crew.IsCrewDefeated && !ArePlayersProtectedByPactAlliance(attacker, playerInfo2) && !HasMutualTruce(attacker, playerInfo2))
			{
				playerInfo = playerInfo2;
				num = effectiveHeat;
			}
		}
		if (playerInfo != null)
		{
			return playerInfo;
		}
		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (humanPlayer != null && !alliedGangIds.Contains(humanPlayer.PID.id) && !ArePlayersProtectedByPactAlliance(attacker, humanPlayer) && !HasMutualTruce(attacker, humanPlayer))
		{
			return humanPlayer;
		}
		return G.GetAllPlayers().FirstOrDefault((PlayerInfo p) => IsAliveGangPlayer(p) && p.PID.id != attacker.PID.id && !alliedGangIds.Contains(p.PID.id) && !ArePlayersProtectedByPactAlliance(attacker, p) && !HasMutualTruce(attacker, p));
	}

	private static bool ShouldBootstrapIndependentCoordAttack(PlayerInfo attacker, PlayerInfo defender, float warHeat, out string reason)
	{
		reason = "none";
		if (!ShouldAllowGangTerritoryExpansion())
		{
			reason = "gang-expand-disabled";
			return false;
		}
		if (!IsAliveGangPlayer(attacker) || !IsAliveGangPlayer(defender))
		{
			reason = "missing-gang";
			return false;
		}
		bool defenderIsHuman = defender?.PID.IsHumanPlayer == true;
		if (IsGangInActivePact(attacker.PID.id) || (IsGangInActivePact(defender.PID.id) && !defenderIsHuman))
		{
			reason = "not-independent";
			return false;
		}
		if (GetOwnedBuildings(attacker).Count <= 0 || GetOwnedBuildings(defender).Count <= 0)
		{
			reason = "no-territory";
			return false;
		}
		float effectiveWarHeat = GetRelationshipAdjustedWarHeat(GangOpsChannel.Independent, attacker, defender, warHeat, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool relationshipHostileBuff);
		if (effectiveWarHeat >= GetEffectiveWarHeatThresholdForRevenge(GangOpsChannel.Independent))
		{
			reason = $"warheat-revenge-threshold heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff}";
			return true;
		}
		if (IsAggroWithoutTruceEitherWay(attacker, defender))
		{
			reason = "existing-aggro";
			return true;
		}
		reason = "no-bootstrap-signal";
		return false;
	}

	private static bool TryRunIndependentHumanFrontPressure(PlayerInfo attacker, HashSet<int> alliedGangIds, int days, PactOpsSettings settings, Dictionary<int, int> coordAttackDayStore, string sourceTag, out string actionSummary)
	{
		actionSummary = "none";
		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (!IsAliveGangPlayer(attacker)
			|| !IsGangOpsRetaliationTargetEligible(humanPlayer)
			|| attacker.PID.IsHumanPlayer
			|| alliedGangIds == null
			|| alliedGangIds.Contains(humanPlayer.PID.id)
			|| ArePlayersProtectedByPactAlliance(attacker, humanPlayer)
			|| HasMutualTruce(attacker, humanPlayer))
		{
			return false;
		}

		float warHeat = GetWarHeat(GangOpsChannel.Independent, attacker.PID.id, humanPlayer.PID.id);
		float effectiveWarHeat = GetRelationshipAdjustedWarHeat(GangOpsChannel.Independent, attacker, humanPlayer, warHeat, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool relationshipHostileBuff);
		float revengeThreshold = Mathf.Max(1f, GetEffectiveWarHeatThresholdForRevenge(GangOpsChannel.Independent));
		int cooldownKey = MakeIndependentHumanPressureDayKey(attacker.PID.id);
		int cooldownDays = GetWarHeatBasedFrontPressureCooldownDays(attacker.PID, humanPlayer.PID, out string cooldownPacing);
		if (coordAttackDayStore != null
			&& coordAttackDayStore.TryGetValue(cooldownKey, out int lastDay)
			&& days - lastDay < cooldownDays)
		{
			return false;
		}

		bool directAggro = IsAggroWithoutTruceEitherWay(attacker, humanPlayer);
		if (HasBlockingPendingHumanRetaliationFrontPressure(humanPlayer.PID, attacker.PID, out int pendingHumanFrontPressureCount, out int usedActionSlots, out int actionCapacity, out int occupiedVehicles))
		{
			VerificationLog("GangOps.Independent.CoordAttack", $"Human pressure skipped attacker={attacker.PID.id} defender={humanPlayer.PID.id} reason=retaliation-vehicle-capacity pendingHuman={pendingHumanFrontPressureCount} usedSlots={usedActionSlots} capacity={actionCapacity} occupiedVehicles={occupiedVehicles} normalDutyReserve={RETALIATION_NORMAL_DUTY_VEHICLE_RESERVE} source={sourceTag}");
			return false;
		}
		bool peacefulPersonality = IsAiPersonalityPeaceful(attacker);
		bool isolationistPersonality = IsAiPersonalityIsolationist(attacker);
		bool aggressivePersonality = IsAiPersonalityAggressive(attacker);
		bool expansionistPersonality = IsAiPersonalityExpansionist(attacker);
		float personalityHeatMultiplier = 1f;
		personalityHeatMultiplier *= peacefulPersonality ? 1.35f : 1f;
		personalityHeatMultiplier *= isolationistPersonality ? 1.2f : 1f;
		personalityHeatMultiplier *= aggressivePersonality ? 0.85f : 1f;
		personalityHeatMultiplier *= expansionistPersonality ? 0.8f : 1f;
		float minimumPressureHeat = Mathf.Max(6f, Mathf.Max(INDEPENDENT_HUMAN_FRONT_PRESSURE_MIN_HEAT_FLOOR, revengeThreshold * INDEPENDENT_HUMAN_FRONT_PRESSURE_MIN_HEAT_RATIO) * personalityHeatMultiplier);
		if (effectiveWarHeat < minimumPressureHeat)
		{
			VerificationLog("GangOps.Independent.CoordAttack", $"Human pressure skipped attacker={attacker.PID.id} defender={humanPlayer.PID.id} reason=heat-below-orderly-threshold heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} minHeat={minimumPressureHeat:0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff} peaceful={peacefulPersonality} isolationist={isolationistPersonality} aggressive={aggressivePersonality} expansionist={expansionistPersonality} source={sourceTag}");
			return false;
		}
		bool hasHumanFrontTarget = TryFindRetaliationFrontOrBackroomTarget(attacker, humanPlayer, null, out _, out _, out _)
			|| TryFindRetaliationClosureTarget(attacker, humanPlayer, out _, out _);
		if (!hasHumanFrontTarget
			&& effectiveWarHeat < Mathf.Max(4f, revengeThreshold * 0.25f))
		{
			return false;
		}

		float pressureHeat = Mathf.Max(warHeat, directAggro ? revengeThreshold * 0.65f : revengeThreshold * 0.45f);
		ActivateWarBetweenPlayers(attacker, humanPlayer);
		if (!TryExecuteRetaliationResponse(GangOpsChannel.Independent, attacker, humanPlayer, EntityID.INVALID, $"Independent-{sourceTag}-human-front-pressure", pressureHeat, out int dispatchedCount, out actionSummary))
		{
			return false;
		}

		if (coordAttackDayStore != null)
		{
			coordAttackDayStore[cooldownKey] = days;
		}
		VerificationLog("GangOps.Independent.CoordAttack", $"Human pressure scored attacker={attacker.PID.id} defender={humanPlayer.PID.id} action={actionSummary} crews={dispatchedCount} heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} pressureHeat={pressureHeat:0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff} cooldownDays={cooldownDays} {cooldownPacing} source={sourceTag}");
		return true;
	}

	private static int MakeIndependentHumanPressureDayKey(int attackerPid)
	{
		return -1000000 - Mathf.Abs(attackerPid);
	}

	private static bool HasBlockingPendingHumanRetaliationFrontPressure(PlayerID humanPid, PlayerID candidateAttackerPid, out int pendingCount, out int usedActionSlots, out int actionCapacity, out int occupiedVehicleCount)
	{
		pendingCount = 0;
		usedActionSlots = 0;
		actionCapacity = 0;
		occupiedVehicleCount = 0;
		PlayerInfo attacker = candidateAttackerPid.IsAnyPlayer ? G.FindPlayerById(candidateAttackerPid.id) : null;
		if (!humanPid.IsHumanPlayer || !IsAliveGangPlayer(attacker))
		{
			return true;
		}
		actionCapacity = GetRetaliationActionCapacity(attacker, out occupiedVehicleCount, out usedActionSlots, out _);
		try
		{
			foreach (PendingRetaliationFrontTicker entry in _pendingRetaliationFrontTickersByBuilding.Values)
			{
				if (entry == null
					|| entry.DefenderPid != humanPid
					|| entry.DelayedPhysicalActionAbandoned)
				{
					continue;
				}
				pendingCount++;
			}
		}
		catch
		{
		}
		return usedActionSlots >= actionCapacity;
	}

	internal static int TriggerCoordinatedAttacksNow(GangOpsChannel channel, string sourceTag, bool autoMode)
	{
		return TriggerCoordinatedAttacksNow(channel, sourceTag, autoMode, GetEligibleGangIdsForChannel(channel));
	}

	internal static int TriggerCoordinatedAttacksNow(GangOpsChannel channel, string sourceTag, bool autoMode, List<int> eligibleGangIds)
	{
		if (!EnableAIAlliances.Value || !IsGangOpsEnabled(channel))
		{
			return 0;
		}
		PactOpsSettings pactOpsSettings = EnsureGangOpsSettings(channel);
		int days = G.GetNow().days;
		Dictionary<string, WarHeatEntry> warHeatStore = GetWarHeatStore(channel);
		if (autoMode && warHeatStore.Count == 0)
		{
			return 0;
		}
		Dictionary<int, int> coordAttackDayStore = GetCoordAttackDayStore(channel);
		int num = 0;
		int humanPressureActionsThisPass = 0;
		foreach (int item in eligibleGangIds)
		{
			PlayerInfo playerInfo = G.FindPlayerById(item);
			if (!IsAliveGangPlayer(playerInfo) || playerInfo.PID.IsHumanPlayer)
			{
				continue;
			}
			HashSet<int> hashSet = new HashSet<int> { playerInfo.PID.id };
			if (channel == GangOpsChannel.Pact && TryGetActivePactForGang(item, out AlliancePact pact) && pact != null)
			{
				hashSet = new HashSet<int>(GetDistinctPactGangIds(pact));
			}
			bool coordOnCooldown = coordAttackDayStore.TryGetValue(item, out int value) && days - value < pactOpsSettings.CoordinatedAttackCooldownDays;
			if (autoMode
				&& channel == GangOpsChannel.Independent
				&& humanPressureActionsThisPass < INDEPENDENT_HUMAN_FRONT_PRESSURE_MAX_PER_AUTO_PASS
				&& TryRunIndependentHumanFrontPressure(playerInfo, hashSet, days, pactOpsSettings, coordAttackDayStore, sourceTag, out string humanPressureAction))
			{
				humanPressureActionsThisPass++;
				num++;
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Human front pressure attacker={playerInfo.PID.id} action={humanPressureAction} source={sourceTag}");
				continue;
			}
			if (coordOnCooldown)
			{
				continue;
			}
			PlayerInfo playerInfo2 = PickCoordinatedAttackTarget(playerInfo, hashSet, warHeatStore);
			if (playerInfo2 == null || playerInfo2.PID.id == playerInfo.PID.id || hashSet.Contains(playerInfo2.PID.id))
			{
				continue;
			}
			if (ArePlayersProtectedByPactAlliance(playerInfo, playerInfo2))
			{
				ClearWarBetweenPlayers(playerInfo, playerInfo2);
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Skipped coordinated attack due alliance attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} source={sourceTag}");
				continue;
			}
			if (HasMutualTruce(playerInfo, playerInfo2))
			{
				ClearWarBetweenPlayers(playerInfo, playerInfo2);
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Skipped coordinated attack due truce attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} source={sourceTag}");
				continue;
			}
			float warHeat = GetWarHeat(channel, playerInfo.PID.id, playerInfo2.PID.id);
			float effectiveWarHeat = GetRelationshipAdjustedWarHeat(channel, playerInfo, playerInfo2, warHeat, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool relationshipHostileBuff);
			if (autoMode && effectiveWarHeat < GetEffectiveWarHeatThresholdForCoordAttack(channel))
			{
				if (channel != GangOpsChannel.Independent || !ShouldBootstrapIndependentCoordAttack(playerInfo, playerInfo2, warHeat, out string bootstrapReason))
				{
					continue;
				}
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Bootstrap coordinated attack attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff} reason={bootstrapReason} source={sourceTag}");
			}
			if (autoMode && effectiveWarHeat > 0f)
			{
				ActivateWarBetweenPlayers(playerInfo, playerInfo2);
				if (TryExecuteRetaliationResponse(channel, playerInfo, playerInfo2, EntityID.INVALID, $"{GetGangOpsChannelTag(channel)}-{sourceTag}-coord-retaliation", warHeat, out int retaliationDispatched, out string retaliationAction))
				{
					coordAttackDayStore[item] = days;
					num++;
					VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Retaliation scored coordinated response attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} action={retaliationAction} crews={retaliationDispatched} heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff} source={sourceTag}");
					continue;
				}
				if (!string.IsNullOrEmpty(retaliationAction) && retaliationAction.StartsWith("approach:", StringComparison.Ordinal))
				{
					VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Retaliation approached coordinated response attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} action={retaliationAction} heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} source={sourceTag}");
					continue;
				}
				if (string.Equals(retaliationAction, "attack-unavailable", StringComparison.Ordinal))
				{
					VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Retaliation attack unavailable attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} source={sourceTag}");
					continue;
				}
			}
			if (autoMode && !ShouldAllowBaseCoordinatedAttack(playerInfo, playerInfo2, out string coordGateReason))
			{
				if (TryForceCloseRetaliationBusiness(channel, playerInfo, playerInfo2, $"{GetGangOpsChannelTag(channel)}-{sourceTag}-coord-gated", out string closureAction))
				{
					coordAttackDayStore[item] = days;
					num++;
					VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Coordinated attack converted to closure attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} action={closureAction} heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} reason={coordGateReason} source={sourceTag}");
					continue;
				}
				if (TryRunRetaliationTerritoryPressure(channel, playerInfo, $"{GetGangOpsChannelTag(channel)}-{sourceTag}-coord-gated", out int territoryActions))
				{
					coordAttackDayStore[item] = days;
					num++;
					VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Coordinated attack converted to territory pressure attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} actions={territoryActions} heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} reason={coordGateReason} source={sourceTag}");
					continue;
				}
				VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Skipped forced coordinated attack attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} heat={warHeat:0.0} effectiveHeat={effectiveWarHeat:0.0} reason={coordGateReason} source={sourceTag}");
				continue;
			}
			int num2 = Mathf.Clamp(playerInfo.crew.LivingCrewCount, 1, 12);
			int num3 = Mathf.Clamp(SharedRng.Next(pactOpsSettings.CoordinatedAttackMinCrew, pactOpsSettings.CoordinatedAttackMaxCrew + 1), 1, num2);
			ActivateWarBetweenPlayers(playerInfo, playerInfo2);
			bool runtimeDispatched = TryDispatchRuntimeGangAttack(playerInfo, playerInfo2, num3, $"{GetGangOpsChannelTag(channel)}-{sourceTag}", EntityID.INVALID, out int dispatchedCount, out int approachCount);
			if (!runtimeDispatched)
			{
				if (approachCount > 0)
				{
					VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Runtime dispatch approached attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} requested={num3} approachCrews={approachCount} source={sourceTag}");
				}
				else
				{
					VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Runtime dispatch unavailable attacker={playerInfo.PID.id} defender={playerInfo2.PID.id} requested={num3} source={sourceTag}");
				}
				continue;
			}
			coordAttackDayStore[item] = days;
			num++;
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Forced coordinated attack: [PID_{playerInfo.PID.id}] -> [PID_{playerInfo2.PID.id}], requested={num3}, crews={dispatchedCount}, approachCrews={approachCount}, source={sourceTag}, heat={warHeat:0.0}, effectiveHeat={effectiveWarHeat:0.0}, relScore={relationshipScore}, relHostility={relationshipHostility:0.00}, relHeatBonus={relationshipHeatBonus:0.0}, hostileBuff={relationshipHostileBuff}");
		}
		if (num > 0)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}.CoordAttack", $"Triggered {num} coordinated attacks source={sourceTag}");
		}
		return num;
	}

	internal static int TriggerCoordinatedAttacksNow(string sourceTag, bool autoMode)
	{
		return TriggerCoordinatedAttacksNow(GangOpsChannel.Pact, sourceTag, autoMode);
	}

	internal static void RunGangOpsTurn(GangOpsChannel channel, PlayerInfo humanPlayer, SimTime now)
	{
		if (!EnableAIAlliances.Value || !IsGangOpsEnabled(channel))
		{
			return;
		}
		RefreshPactCache();
		List<int> eligibleGangIdsForChannel = GetEligibleGangIdsForChannel(channel);
		if (eligibleGangIdsForChannel.Count == 0)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}", $"turn day={now.days} activeGangs=0 warHeat={GetWarHeatStore(channel).Count} pendingRevenge={GetRevengeStore(channel).Count((KeyValuePair<string, RevengeEntry> kv) => kv.Value != null && !kv.Value.Executed)} protect=0 coordAuto=0 skipped=no-eligible-gangs");
			return;
		}
		System.Diagnostics.Stopwatch stopwatch = System.Diagnostics.Stopwatch.StartNew();
		long phaseStartMs = stopwatch.ElapsedMilliseconds;
		int num = ExecuteDueRevengeEntries(channel, now);
		long revengeMs = stopwatch.ElapsedMilliseconds - phaseStartMs;
		phaseStartMs = stopwatch.ElapsedMilliseconds;
		int num2 = RunAutoProtectPass(channel, now.days, eligibleGangIdsForChannel);
		long protectMs = stopwatch.ElapsedMilliseconds - phaseStartMs;
		phaseStartMs = stopwatch.ElapsedMilliseconds;
		int num3 = RunGangOpsHirePressurePass(channel, now.days, eligibleGangIdsForChannel);
		long hirePressureMs = stopwatch.ElapsedMilliseconds - phaseStartMs;
		PactOpsSettings pactOpsSettings = EnsureGangOpsSettings(channel);
		int num4 = 0;
		long coordMs = 0L;
		if (pactOpsSettings.CoordinatedAttackAutoEnabled)
		{
			phaseStartMs = stopwatch.ElapsedMilliseconds;
			num4 = TriggerCoordinatedAttacksNow(channel, "auto", autoMode: true, eligibleGangIdsForChannel);
			coordMs = stopwatch.ElapsedMilliseconds - phaseStartMs;
		}
		phaseStartMs = stopwatch.ElapsedMilliseconds;
		int num5 = DirtyCashEconomyCompatibilityPatch.TryRunAiOutpostTerritoryExpansionPass(channel, $"turn-{GetGangOpsChannelTag(channel).ToLowerInvariant()}", eligibleGangIdsForChannel);
		long territoryExpandMs = stopwatch.ElapsedMilliseconds - phaseStartMs;
		phaseStartMs = stopwatch.ElapsedMilliseconds;
		DecayWarHeat(channel, now.days);
		long decayMs = stopwatch.ElapsedMilliseconds - phaseStartMs;
		phaseStartMs = stopwatch.ElapsedMilliseconds;
		int num6 = ReconcileGangOpsAggroForWarmWarHeat(channel, now.days);
		long aggroMs = stopwatch.ElapsedMilliseconds - phaseStartMs;
		stopwatch.Stop();
		int count = GetWarHeatStore(channel).Count;
		int num7 = GetRevengeStore(channel).Count((KeyValuePair<string, RevengeEntry> kv) => kv.Value != null && !kv.Value.Executed);
		if (stopwatch.ElapsedMilliseconds >= 40L)
		{
			VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}", $"turn-perf day={now.days} ms={stopwatch.ElapsedMilliseconds} revengeMs={revengeMs} protectMs={protectMs} hirePressureMs={hirePressureMs} coordMs={coordMs} territoryExpandMs={territoryExpandMs} decayMs={decayMs} aggroMs={aggroMs}");
		}
		VerificationLog($"GangOps.{GetGangOpsChannelTag(channel)}", $"turn day={now.days} activeGangs={eligibleGangIdsForChannel.Count} warHeat={count} pendingRevenge={num7} revengeExec={num} protect={num2} hirePressure={num3} coordAuto={num4} territoryExpand={num5} aggroRestored={num6}");
	}

	internal static void RunPactOpsTurn(PlayerInfo humanPlayer, SimTime now)
	{
		RunGangOpsTurn(GangOpsChannel.Pact, humanPlayer, now);
	}

	internal static bool IsAggroWithoutTruceOneWay(PlayerInfo owner, PlayerID targetPid)
	{
		try
		{
			object combat = owner?.ai?.combat;
			if (combat == null)
			{
				return false;
			}
			MethodInfo methodInfo = combat.GetType().GetMethod("IsAggroWithoutTruce", BindingFlags.Instance | BindingFlags.Public);
			if (methodInfo == null)
			{
				return false;
			}
			return (bool)methodInfo.Invoke(combat, new object[1] { targetPid });
		}
		catch
		{
			return false;
		}
	}

	internal static bool IsAggroWithoutTruceEitherWay(PlayerInfo a, PlayerInfo b)
	{
		if (a == null || b == null)
		{
			return false;
		}
		if (IsAggroWithoutTruceOneWay(a, b.PID))
		{
			return true;
		}
		return IsAggroWithoutTruceOneWay(b, a.PID);
	}

	internal static (bool isAggro, bool hasTruce) GetAggroAndTruceOneWay(PlayerInfo owner, PlayerID targetPid)
	{
		try
		{
			object combat = owner?.ai?.combat;
			if (combat == null)
			{
				return (isAggro: false, hasTruce: false);
			}
			MethodInfo methodInfo = combat.GetType().GetMethod("GetAggroAndTruce", BindingFlags.Instance | BindingFlags.Public);
			if (methodInfo == null)
			{
				return (isAggro: false, hasTruce: false);
			}
			object result = methodInfo.Invoke(combat, new object[1] { targetPid });
			if (result == null)
			{
				return (isAggro: false, hasTruce: false);
			}
			Type tupleType = result.GetType();
			bool isAggro = false;
			bool hasTruce = false;
			PropertyInfo item1Prop = tupleType.GetProperty("Item1");
			PropertyInfo item2Prop = tupleType.GetProperty("Item2");
			if (item1Prop != null && item2Prop != null)
			{
				object item1 = item1Prop.GetValue(result);
				object item2 = item2Prop.GetValue(result);
				if (item1 is bool b1)
				{
					isAggro = b1;
				}
				if (item2 is bool b2)
				{
					hasTruce = b2;
				}
				return (isAggro, hasTruce);
			}
			FieldInfo item1Field = tupleType.GetField("Item1") ?? tupleType.GetField("isAggro");
			FieldInfo item2Field = tupleType.GetField("Item2") ?? tupleType.GetField("hasTruce");
			if (item1Field != null)
			{
				object item1Obj = item1Field.GetValue(result);
				if (item1Obj is bool b3)
				{
					isAggro = b3;
				}
			}
			if (item2Field != null)
			{
				object item2Obj = item2Field.GetValue(result);
				if (item2Obj is bool b4)
				{
					hasTruce = b4;
				}
			}
			return (isAggro, hasTruce);
		}
		catch
		{
			return (isAggro: false, hasTruce: false);
		}
	}

	internal static bool HasMutualTruce(PlayerInfo a, PlayerInfo b)
	{
		if (a == null || b == null)
		{
			return false;
		}
		var (_, hasTruceA) = GetAggroAndTruceOneWay(a, b.PID);
		var (_, hasTruceB) = GetAggroAndTruceOneWay(b, a.PID);
		return hasTruceA || hasTruceB;
	}

	private static void TryShowGangAttackTicker(PlayerInfo attacker, PlayerInfo defender, Entity targetPeep, string sourceTag)
	{
		if (attacker == null || defender == null || !defender.PID.IsHumanPlayer)
		{
			return;
		}
		try
		{
			int nowDay = G.GetNow().days;
			if (_seenGangAttackTickerDay != nowDay)
			{
				_seenGangAttackTickerDay = nowDay;
				_seenGangAttackTickerKeys.Clear();
			}
			string key = nowDay.ToString(CultureInfo.InvariantCulture) + ":" + attacker.PID.id.ToString(CultureInfo.InvariantCulture) + ":" + defender.PID.id.ToString(CultureInfo.InvariantCulture) + ":" + (sourceTag ?? string.Empty);
			if (!_seenGangAttackTickerKeys.Add(key))
			{
				return;
			}
			string attackerName = attacker.social?.PlayerGroupName ?? ("Gang#" + attacker.PID.id);
			string message = CrewRelationshipHandlerPatch.SanitizeUiGlyphText("ATTACK: " + attackerName + " sent hitters after your outfit.", aggressive: true).Trim();
			NodeID targetNodeId = targetPeep?.data?.agent?.nid ?? NodeID.INVALID;
			TickerTarget target = targetNodeId.IsValid ? ((TickerTarget)targetNodeId) : default(TickerTarget);
			global::Game.Game.ctx?.hud?.tickers?.AddTextTicker(TickerIcon.GANG_ATTACK, TickerTitle.GANG_ATTACK, message, target, TickerPersistType.Persist);
			VerificationLog("PactRetaliation", $"gang-attack-ticker attacker={attacker.PID.id} defender={defender.PID.id} source={sourceTag} node={targetNodeId}");
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryShowGangAttackTicker: " + ex.Message);
		}
	}

	internal static void ClearWarOneWay(PlayerInfo owner, PlayerID targetPid)
	{
		try
		{
			object combat = owner?.ai?.combat;
			if (combat == null)
			{
				return;
			}
			MethodInfo methodInfo = combat.GetType().GetMethod("RemoveAggroOn", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
			if (methodInfo != null)
			{
				methodInfo.Invoke(combat, new object[1] { targetPid });
			}
		}
		catch
		{
		}
	}

	internal static void ClearWarBetweenPlayers(PlayerInfo a, PlayerInfo b)
	{
		if (a == null || b == null || a.PID.id == b.PID.id)
		{
			return;
		}
		ClearWarOneWay(a, b.PID);
		ClearWarOneWay(b, a.PID);
		MarkCrewPickAggroDirty(a.PID, "clear-war");
		MarkCrewPickAggroDirty(b.PID, "clear-war");
	}

	internal static void FinalizeGangTruceBetweenPlayers(PlayerInfo a, PlayerInfo b, string sourceTag)
	{
		if (a == null || b == null || a.PID.id == b.PID.id)
		{
			return;
		}
		ClearGangOpsWarStoresForPair(a.PID.id, b.PID.id);
		RemoveRetaliationBuffsBetween(a, b, "truce-" + sourceTag);
		MarkCrewPickAggroDirty(a.PID, "truce-" + sourceTag);
		MarkCrewPickAggroDirty(b.PID, "truce-" + sourceTag);
		FlushCrewPickAggroRefreshes("truce-" + sourceTag);
		VerificationLog("GangTruce", $"finalized source={sourceTag} first={a.PID.id} second={b.PID.id}");
	}

	internal static List<GangWarMediationCandidate> BuildGangWarMediationCandidates(PlayerInfo requestGang)
	{
		List<GangWarMediationCandidate> list = new List<GangWarMediationCandidate>();
		if (!IsAliveGangPlayer(requestGang))
		{
			return list;
		}
		PlayerInfo humanPlayer = G.GetHumanPlayer();
		RefreshPactCache();
		foreach (PlayerInfo opponent in G.GetAllPlayers())
		{
			if (!IsAliveGangPlayer(opponent) || opponent.PID.id == requestGang.PID.id || HasMutualTruce(requestGang, opponent))
			{
				continue;
			}
			GangOpsChannel channel = ResolveGangOpsChannelForPair(requestGang.PID.id, opponent.PID.id);
			float warHeat = GetHighestWarHeatForPair(requestGang.PID.id, opponent.PID.id);
			if (!IsAggroWithoutTruceEitherWay(requestGang, opponent) && warHeat <= 0.1f)
			{
				continue;
			}
			GangWarMediationCandidate candidate = new GangWarMediationCandidate
			{
				RequestGang = requestGang,
				OpponentGang = opponent,
				Channel = channel,
				WarHeat = warHeat,
				PlayerPower = CalculateGangPower(humanPlayer),
				RequestGangPower = CalculateGangPower(requestGang),
				OpponentPower = CalculateGangPower(opponent)
			};
			RefreshGangWarMediationCandidatePreview(candidate, 0);
			list.Add(candidate);
		}
		return list.OrderByDescending((GangWarMediationCandidate c) => c.AcceptanceScore)
			.ThenByDescending((GangWarMediationCandidate c) => c.WarHeat)
			.ToList();
	}

	internal static bool TryResolveGangWarMediation(GangWarMediationCandidate candidate, out string message)
	{
		return TryResolveGangWarMediation(candidate, candidate?.OfferCash ?? 0, out message, out _);
	}

	internal static bool TryResolveGangWarMediation(GangWarMediationCandidate candidate, int offerCash, out string message, out bool shouldConsumeConvoAction)
	{
		message = "No active war was found.";
		shouldConsumeConvoAction = false;
		if (candidate?.RequestGang == null || candidate.OpponentGang == null)
		{
			return false;
		}
		PlayerInfo requestGang = candidate.RequestGang;
		PlayerInfo opponentGang = candidate.OpponentGang;
		PlayerInfo humanPlayer = G.GetHumanPlayer();
		if (!IsAliveGangPlayer(requestGang) || !IsAliveGangPlayer(opponentGang))
		{
			message = "One side is no longer active.";
			return false;
		}
		int cooldownRemaining = GetGangWarMediationCooldownRemaining(requestGang.PID.id, opponentGang.PID.id);
		if (cooldownRemaining > 0)
		{
			message = $"Mediation is cooling down for {cooldownRemaining} day(s).";
			candidate.CooldownRemainingDays = cooldownRemaining;
			return false;
		}
		offerCash = ClampGangWarMediationCashOffer(offerCash);
		if (offerCash > 0 && (humanPlayer == null || !humanPlayer.finances.CanChangeMoneyOnSafehouse(new Price((Fixnum)(-offerCash)))))
		{
			message = $"You need ${offerCash} clean cash for that offer.";
			return false;
		}
		if (!IsAggroWithoutTruceEitherWay(requestGang, opponentGang) && GetHighestWarHeatForPair(requestGang.PID.id, opponentGang.PID.id) <= 0.1f)
		{
			message = "That war has already cooled off.";
			return false;
		}
		RefreshGangWarMediationCandidatePreview(candidate, offerCash);
		string requestName = GetGangDisplayName(requestGang.PID.id);
		string opponentName = GetGangDisplayName(opponentGang.PID.id);
		if (!candidate.WouldAccept)
		{
			SetGangWarMediationAttemptDay(requestGang.PID.id, opponentGang.PID.id);
			shouldConsumeConvoAction = true;
			message = $"{requestName} will not stand down yet. Score {candidate.AcceptanceScore}/100. Try again in {GANG_WAR_MEDIATION_COOLDOWN_DAYS} days.";
			VerificationLog("GangWarMediation", $"accepted=False requester={requestGang.PID.id} opponent={opponentGang.PID.id} score={candidate.AcceptanceScore} heat={candidate.WarHeat:0.0} cash={offerCash} cashBonus={candidate.CashAcceptanceBonus} context={candidate.ContextLabel}");
			LogGrapevine($"TALK: {requestName} rejected mediation with {opponentName}.");
			return false;
		}
		if (offerCash > 0)
		{
			humanPlayer.finances.DoChangeMoneyOnSafehouse(new Price((Fixnum)(-offerCash)), (MoneyReason)1);
		}
		SetGangWarMediationAttemptDay(requestGang.PID.id, opponentGang.PID.id);
		shouldConsumeConvoAction = true;
		ClearWarBetweenPlayers(requestGang, opponentGang);
		ClearGangOpsWarStoresForPair(requestGang.PID.id, opponentGang.PID.id);
		RemoveRetaliationBuffsBetween(requestGang, opponentGang, "mediation-accepted");
		AddMutualRelationshipBuff(requestGang, opponentGang, "relbuff-gangs-truce", GetCrewPeepForPlayer(requestGang), GetCrewPeepForPlayer(opponentGang));
		message = offerCash > 0 ? $"War ended between {requestName} and {opponentName}. Paid ${offerCash}." : $"War ended between {requestName} and {opponentName}.";
		VerificationLog("GangWarMediation", $"accepted=True requester={requestGang.PID.id} opponent={opponentGang.PID.id} score={candidate.AcceptanceScore} heat={candidate.WarHeat:0.0} cash={offerCash} cashBonus={candidate.CashAcceptanceBonus} context={candidate.ContextLabel}");
		LogGrapevine(offerCash > 0 ? $"TALK: Your outfit mediated a ${offerCash} truce between {requestName} and {opponentName}." : $"TALK: Your outfit mediated a truce between {requestName} and {opponentName}.");
		return true;
	}

	internal static void RefreshGangWarMediationCandidatePreview(GangWarMediationCandidate candidate, int offerCash)
	{
		if (candidate?.RequestGang == null || candidate.OpponentGang == null)
		{
			return;
		}
		PlayerInfo humanPlayer = G.GetHumanPlayer();
		candidate.OfferCash = ClampGangWarMediationCashOffer(offerCash);
		candidate.Channel = ResolveGangOpsChannelForPair(candidate.RequestGang.PID.id, candidate.OpponentGang.PID.id);
		candidate.WarHeat = GetHighestWarHeatForPair(candidate.RequestGang.PID.id, candidate.OpponentGang.PID.id);
		candidate.PlayerPower = CalculateGangPower(humanPlayer);
		candidate.RequestGangPower = CalculateGangPower(candidate.RequestGang);
		candidate.OpponentPower = CalculateGangPower(candidate.OpponentGang);
		candidate.CooldownRemainingDays = GetGangWarMediationCooldownRemaining(candidate.RequestGang.PID.id, candidate.OpponentGang.PID.id);
		candidate.AcceptanceScore = CalculateGangWarMediationAcceptance(candidate, humanPlayer, out string contextLabel, out string difficultyLabel);
		candidate.ContextLabel = contextLabel;
		candidate.DifficultyLabel = difficultyLabel;
	}

	private static int CalculateGangWarMediationAcceptance(GangWarMediationCandidate candidate, PlayerInfo humanPlayer, out string contextLabel, out string difficultyLabel)
	{
		contextLabel = "Independent war";
		difficultyLabel = "Unlikely";
		if (candidate == null)
		{
			return 0;
		}
		PlayerInfo requestGang = candidate.RequestGang;
		PlayerInfo opponentGang = candidate.OpponentGang;
		int score = 50;
		score += Mathf.RoundToInt(GetSignedGangRelationshipBias(requestGang, humanPlayer) * 25f);
		int strongestWarSide = Math.Max(candidate.RequestGangPower, candidate.OpponentPower);
		score += Mathf.Clamp(Mathf.RoundToInt((candidate.PlayerPower - strongestWarSide) / 6f), -20, 25);
		score -= Mathf.RoundToInt(Mathf.Clamp(candidate.WarHeat * 0.28f, 0f, 30f));
		candidate.CashAcceptanceBonus = CalculateGangWarMediationCashBonus(candidate.OfferCash);
		score += candidate.CashAcceptanceBonus;
		AlliancePact requestPact = GetPactForPlayer(requestGang.PID);
		AlliancePact opponentPact = GetPactForPlayer(opponentGang.PID);
		if (requestPact != null && requestPact.IsActive && opponentPact != null && opponentPact.IsActive)
		{
			if (string.Equals(requestPact.PactId, opponentPact.PactId, StringComparison.Ordinal))
			{
				contextLabel = "Internal pact dispute";
				score -= 4;
			}
			else
			{
				contextLabel = "Inter-pact war";
				score -= 16;
			}
		}
		else if ((requestPact != null && requestPact.IsActive) || (opponentPact != null && opponentPact.IsActive))
		{
			contextLabel = "Pact war";
			score -= 8;
		}
		score = Mathf.Clamp(score, 0, 100);
		if (score >= 75)
		{
			difficultyLabel = "Easy";
		}
		else if (score >= 60)
		{
			difficultyLabel = "Likely";
		}
		else if (score >= 40)
		{
			difficultyLabel = "Hard";
		}
		return score;
	}

	internal static int ClampGangWarMediationCashOffer(int offerCash)
	{
		int clamped = Mathf.Clamp(offerCash, 0, GANG_WAR_MEDIATION_MAX_CASH);
		return (clamped / GANG_WAR_MEDIATION_CASH_STEP) * GANG_WAR_MEDIATION_CASH_STEP;
	}

	private static int CalculateGangWarMediationCashBonus(int offerCash)
	{
		return Mathf.Clamp(ClampGangWarMediationCashOffer(offerCash) / GANG_WAR_MEDIATION_CASH_STEP * 2, 0, 50);
	}

	private static float GetHighestWarHeatForPair(int firstPid, int secondPid)
	{
		return Mathf.Max(
			Mathf.Max(GetWarHeat(GangOpsChannel.Pact, firstPid, secondPid), GetWarHeat(GangOpsChannel.Pact, secondPid, firstPid)),
			Mathf.Max(GetWarHeat(GangOpsChannel.Independent, firstPid, secondPid), GetWarHeat(GangOpsChannel.Independent, secondPid, firstPid)));
	}

	internal static string GetGangWarMediationPairKey(int firstPid, int secondPid)
	{
		return firstPid <= secondPid ? $"{firstPid}:{secondPid}" : $"{secondPid}:{firstPid}";
	}

	private static Dictionary<string, int> GetGangWarMediationCooldownStore()
	{
		if (SaveData == null)
		{
			SaveData = new ModSaveData();
		}
		if (SaveData.GangWarMediationLastAttemptDayByPair == null)
		{
			SaveData.GangWarMediationLastAttemptDayByPair = new Dictionary<string, int>();
		}
		return SaveData.GangWarMediationLastAttemptDayByPair;
	}

	private static int GetGangWarMediationCooldownRemaining(int firstPid, int secondPid)
	{
		Dictionary<string, int> store = GetGangWarMediationCooldownStore();
		if (!store.TryGetValue(GetGangWarMediationPairKey(firstPid, secondPid), out int lastAttemptDay) || lastAttemptDay < 0)
		{
			return 0;
		}
		int elapsed = G.GetNow().days - lastAttemptDay;
		return Math.Max(0, GANG_WAR_MEDIATION_COOLDOWN_DAYS - elapsed);
	}

	private static void SetGangWarMediationAttemptDay(int firstPid, int secondPid)
	{
		GetGangWarMediationCooldownStore()[GetGangWarMediationPairKey(firstPid, secondPid)] = G.GetNow().days;
	}

	internal static void ClearGangOpsWarStoresForPair(int firstPid, int secondPid)
	{
		foreach (GangOpsChannel channel in new[] { GangOpsChannel.Pact, GangOpsChannel.Independent })
		{
			Dictionary<string, WarHeatEntry> warHeat = GetWarHeatStore(channel);
			warHeat.Remove(MakeGangPairKey(firstPid, secondPid));
			warHeat.Remove(MakeGangPairKey(secondPid, firstPid));
			Dictionary<string, RevengeEntry> revenge = GetRevengeStore(channel);
			revenge.Remove(MakeGangPairKey(firstPid, secondPid));
			revenge.Remove(MakeGangPairKey(secondPid, firstPid));
		}
	}

	private static int ClearGangOpsStateForPlayer(int pid, string sourceTag)
	{
		if (pid < 0)
		{
			return 0;
		}
		int removed = 0;
		foreach (GangOpsChannel channel in new[] { GangOpsChannel.Pact, GangOpsChannel.Independent })
		{
			Dictionary<string, WarHeatEntry> warHeat = GetWarHeatStore(channel);
			foreach (string key in warHeat.Where(kv => kv.Value != null && (kv.Value.AttackerPid == pid || kv.Value.DefenderPid == pid)).Select(kv => kv.Key).ToList())
			{
				if (warHeat.Remove(key))
				{
					removed++;
				}
			}
			Dictionary<string, RevengeEntry> revenge = GetRevengeStore(channel);
			foreach (string key in revenge.Where(kv => kv.Value != null && (kv.Value.AttackerPid == pid || kv.Value.DefenderPid == pid)).Select(kv => kv.Key).ToList())
			{
				if (revenge.Remove(key))
				{
					removed++;
				}
			}
			GetAutoProtectDayStore(channel).Remove(pid);
			GetCoordAttackDayStore(channel).Remove(pid);
			GetHireCycleDayStore(channel).Remove(pid);
		}
		if (removed > 0)
		{
			VerificationLog("GangOps", $"cleared-state-for-player pid={pid} removed={removed} source={sourceTag}");
		}
		return removed;
	}

	internal static void ActivateWarOneWay(PlayerInfo owner, PlayerID targetPid)
	{
		try
		{
			if (owner == null || !targetPid.IsValid || targetPid == owner.PID)
			{
				return;
			}
			var (isAggro, hasTruce) = GetAggroAndTruceOneWay(owner, targetPid);
			if (hasTruce || isAggro)
			{
				return;
			}
			object combat = owner?.ai?.combat;
			if (combat == null)
			{
				return;
			}
			MethodInfo method2 = combat.GetType().GetMethod("AddAggroOn", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
			if (method2 != null)
			{
				method2.Invoke(combat, new object[2] { targetPid, (Fixnum)(-120) });
			}
		}
		catch
		{
		}
	}

	internal static void ActivateWarBetweenPlayers(PlayerInfo a, PlayerInfo b)
	{
		if (a == null || b == null || a.PID.id == b.PID.id)
		{
			return;
		}
		if (ArePlayersProtectedByPactAlliance(a, b))
		{
			ClearWarBetweenPlayers(a, b);
			VerificationLog("PactAlliance", $"war blocked by alliance a={a.PID.id} b={b.PID.id}");
			return;
		}
		ActivateWarOneWay(a, b.PID);
		ActivateWarOneWay(b, a.PID);
		MarkCrewPickAggroDirty(a.PID, "activate-war");
		MarkCrewPickAggroDirty(b.PID, "activate-war");
	}

	private static int ReconcileGangOpsAggroForWarmWarHeat(GangOpsChannel channel, int nowDay)
	{
		Dictionary<string, WarHeatEntry> store = GetWarHeatStore(channel);
		if (store == null || store.Count == 0)
		{
			return 0;
		}
		float warmThreshold = Mathf.Max(8f, GetEffectiveWarHeatThresholdForRevenge(channel) * 0.35f);
		int restored = 0;
		int skipped = 0;
		int considered = 0;
		foreach (WarHeatEntry entry in store.Values.ToList())
		{
			if (entry == null || entry.AttackerPid < 0 || entry.DefenderPid < 0 || entry.AttackerPid == entry.DefenderPid)
			{
				continue;
			}
			PlayerInfo attacker = G.FindPlayerById(entry.AttackerPid);
			PlayerInfo defender = G.FindPlayerById(entry.DefenderPid);
			float effectiveHeat = GetRelationshipAdjustedWarHeat(channel, attacker, defender, entry.Heat, out int relationshipScore, out float relationshipHostility, out float relationshipHeatBonus, out bool relationshipHostileBuff);
			if (effectiveHeat < warmThreshold)
			{
				continue;
			}
			considered++;
			if (!IsGangEligibleForChannel(attacker, channel) || !IsGangOpsRetaliationTargetEligible(defender))
			{
				skipped++;
				continue;
			}
			if (ArePlayersProtectedByPactAlliance(attacker, defender))
			{
				skipped++;
				VerificationLog("GangOps.Aggro", $"aggro-skip-alliance channel={GetGangOpsChannelTag(channel)} attacker={entry.AttackerPid} defender={entry.DefenderPid} heat={entry.Heat:0.0} day={nowDay}");
				continue;
			}
			if (HasMutualTruce(attacker, defender))
			{
				skipped++;
				VerificationLog("GangOps.Aggro", $"aggro-skip-truce channel={GetGangOpsChannelTag(channel)} attacker={entry.AttackerPid} defender={entry.DefenderPid} heat={entry.Heat:0.0} day={nowDay}");
				continue;
			}
			bool attackerAggro = IsAggroWithoutTruceOneWay(attacker, defender.PID);
			bool defenderAggro = IsAggroWithoutTruceOneWay(defender, attacker.PID);
			if (attackerAggro && defenderAggro)
			{
				continue;
			}
			if (!attackerAggro)
			{
				ActivateWarOneWay(attacker, defender.PID);
			}
			if (!defenderAggro)
			{
				ActivateWarOneWay(defender, attacker.PID);
			}
			MarkCrewPickAggroDirty(attacker.PID, "warheat-aggro-reconcile");
			MarkCrewPickAggroDirty(defender.PID, "warheat-aggro-reconcile");
			restored++;
			VerificationLog("GangOps.Aggro", $"aggro-restored channel={GetGangOpsChannelTag(channel)} attacker={entry.AttackerPid} defender={entry.DefenderPid} heat={entry.Heat:0.0} effectiveHeat={effectiveHeat:0.0} threshold={warmThreshold:0.0} relScore={relationshipScore} relHostility={relationshipHostility:0.00} relHeatBonus={relationshipHeatBonus:0.0} hostileBuff={relationshipHostileBuff} attackerHadAggro={attackerAggro} defenderHadAggro={defenderAggro} lastUpdatedDay={entry.LastUpdatedDay} day={nowDay}");
		}
		if (restored > 0)
		{
			FlushCrewPickAggroRefreshes("warheat-aggro-reconcile");
		}
		if (considered > 0 && (restored > 0 || skipped > 0))
		{
			VerificationLog("GangOps.Aggro", $"summary channel={GetGangOpsChannelTag(channel)} considered={considered} restored={restored} skipped={skipped} threshold={warmThreshold:0.0} day={nowDay}");
		}
		return restored;
	}

	internal static AlliancePact GetPactForPlayer(PlayerID pid)
	{
		if (SaveData?.Pacts == null)
		{
			return null;
		}
		return SaveData.Pacts.FirstOrDefault((AlliancePact p) => p != null && p.IsMember(pid));
	}

	internal static bool TryGetPactSharedColor(PlayerInfo player, out Color color)
	{
		color = default;
		if (player == null)
		{
			return false;
		}
		AlliancePact pact = GetPactForPlayer(player.PID);
		if (pact == null || !pact.IsActive)
		{
			return false;
		}
		color = pact.SharedColor;
		color.a = 1f;
		return true;
	}

	internal static Color GetEffectivePlayerColor(PlayerInfo player, Color fallback)
	{
		return TryGetPactSharedColor(player, out Color pactColor) ? pactColor : fallback;
	}

	internal static Color GetEffectivePlayerTextColor(PlayerInfo player, float brightness, Color fallback)
	{
		return Color.Lerp(GetEffectivePlayerColor(player, fallback), Color.white, Mathf.Clamp01(brightness));
	}

	internal static AlliancePact GetPactById(string pactId)
	{
		if (string.IsNullOrEmpty(pactId) || SaveData?.Pacts == null)
		{
			return null;
		}
		return SaveData.Pacts.FirstOrDefault((AlliancePact p) => p != null && string.Equals(p.PactId, pactId, StringComparison.Ordinal));
	}

	internal static IEnumerable<InterPactAlliance> GetActiveInterPactAlliances()
	{
		if (SaveData?.PactAlliances == null)
		{
			yield break;
		}
		foreach (InterPactAlliance pactAlliance in SaveData.PactAlliances)
		{
			if (pactAlliance != null && pactAlliance.Active && !string.IsNullOrEmpty(pactAlliance.LeftPactId) && !string.IsNullOrEmpty(pactAlliance.RightPactId))
			{
				yield return pactAlliance;
			}
		}
	}

	internal static List<InterPactAlliance> GetInterPactAlliancesForPact(AlliancePact pact)
	{
		if (pact == null)
		{
			return new List<InterPactAlliance>();
		}
		return GetActiveInterPactAlliances().Where((InterPactAlliance x) => x.Involves(pact.PactId)).ToList();
	}

	internal static List<AlliancePact> GetInterPactAlliancePartners(AlliancePact pact)
	{
		List<AlliancePact> list = new List<AlliancePact>();
		if (pact == null)
		{
			return list;
		}
		foreach (InterPactAlliance interPactAlliance in GetInterPactAlliancesForPact(pact))
		{
			AlliancePact pactById = GetPactById(interPactAlliance.GetOtherPactId(pact.PactId));
			if (pactById != null && pactById.IsActive)
			{
				list.Add(pactById);
			}
		}
		return list.Distinct().ToList();
	}

	internal static bool ArePactsInAlliance(AlliancePact first, AlliancePact second)
	{
		if (first == null || second == null || !first.IsActive || !second.IsActive)
		{
			return false;
		}
		if (string.IsNullOrEmpty(first.PactId) || string.IsNullOrEmpty(second.PactId) || string.Equals(first.PactId, second.PactId, StringComparison.Ordinal))
		{
			return false;
		}
		return GetActiveInterPactAlliances().Any((InterPactAlliance x) => (string.Equals(x.LeftPactId, first.PactId, StringComparison.Ordinal) && string.Equals(x.RightPactId, second.PactId, StringComparison.Ordinal)) || (string.Equals(x.LeftPactId, second.PactId, StringComparison.Ordinal) && string.Equals(x.RightPactId, first.PactId, StringComparison.Ordinal)));
	}

	internal static bool ArePlayersProtectedByPactAlliance(PlayerInfo first, PlayerInfo second)
	{
		if (first == null || second == null || first.PID.id == second.PID.id)
		{
			return false;
		}
		AlliancePact pactForPlayer = GetPactForPlayer(first.PID);
		AlliancePact pactForPlayer2 = GetPactForPlayer(second.PID);
		if (pactForPlayer == null || pactForPlayer2 == null)
		{
			return false;
		}
		if (string.Equals(pactForPlayer.PactId, pactForPlayer2.PactId, StringComparison.Ordinal))
		{
			return true;
		}
		return ArePactsInAlliance(pactForPlayer, pactForPlayer2);
	}

	internal static int GetInterPactAllianceCountForPact(AlliancePact pact)
	{
		return GetInterPactAlliancesForPact(pact).Count;
	}

	internal static float GetEffectivePactEarningRate(AlliancePact pact)
	{
		if (pact == null)
		{
			return 0f;
		}
		float num = pact.EarningRate + (float)GetInterPactAllianceCountForPact(pact) * 0.04f;
		return Mathf.Clamp(num, 0.05f, 0.37f);
	}

	internal static int GetEffectivePactCrewCapacityBonus(AlliancePact pact)
	{
		if (pact == null)
		{
			return 0;
		}
		return Math.Max(0, pact.CrewCapacityBonus + GetInterPactAllianceCountForPact(pact) * 2);
	}

	internal static bool CanPactsFormAlliance(AlliancePact first, AlliancePact second)
	{
		if (first == null || second == null || !first.IsActive || !second.IsActive)
		{
			return false;
		}
		if (string.IsNullOrEmpty(first.PactId) || string.IsNullOrEmpty(second.PactId) || string.Equals(first.PactId, second.PactId, StringComparison.Ordinal))
		{
			return false;
		}
		if (ArePactsInAlliance(first, second))
		{
			return false;
		}
		if (GetInterPactAllianceCountForPact(first) >= 3 || GetInterPactAllianceCountForPact(second) >= 3)
		{
			return false;
		}
		return true;
	}

	internal static bool RemoveGangFromPactMembership(AlliancePact pact, int gangId, string sourceTag)
	{
		if (pact == null || gangId < 0)
		{
			return false;
		}

		bool removedMember = pact.MemberIds != null && pact.MemberIds.Remove(gangId);
		bool removedLeader = pact.LeaderGangId == gangId;
		if (!removedMember && !removedLeader && !(pact.BossHappiness?.ContainsKey(gangId) ?? false) && !(pact.VotePreferences?.ContainsKey(gangId) ?? false))
		{
			return false;
		}

		if (removedLeader)
		{
			int nextLeader = (pact.MemberIds ?? new List<int>()).FirstOrDefault();
			if (nextLeader > 0)
			{
				pact.MemberIds.Remove(nextLeader);
				pact.LeaderGangId = nextLeader;
			}
			else
			{
				pact.LeaderGangId = -1;
			}
		}

		pact.BossHappiness?.Remove(gangId);
		pact.VotePreferences?.Remove(gangId);

		bool removedHuman = G.GetHumanPlayer()?.PID.id == gangId;
		if (removedHuman)
		{
			if (SaveData.PlayerJoinedPactIndex == pact.ColorIndex)
			{
				SaveData.PlayerJoinedPactIndex = -1;
			}
			if (SaveData.PlayerPactId >= 0 && string.Equals(pact.PactId, $"pact_{SaveData.PlayerPactId}", StringComparison.Ordinal))
			{
				SaveData.PlayerPactId = -1;
			}
			SaveData.PlayerPactWarStartDay = -1;
			SaveData.PlayerPactWarTargetId = -1;
		}

		PlayerID removedPid = default;
		removedPid.id = (short)gangId;
		MarkCrewPickAggroDirty(removedPid, sourceTag);
		foreach (int pactGangId in GetPactMemberGangIds(pact))
		{
			PlayerID pactPid = default;
			pactPid.id = (short)pactGangId;
			MarkCrewPickAggroDirty(pactPid, sourceTag);
		}

		RefreshPactCache();
		TerritoryColorPatch.RefreshAllTerritoryColors();
		VerificationLog("Pact", $"membership-removed pact={pact.PactId} gang={gangId} leaderRemoved={removedLeader} nextLeader={pact.LeaderGangId} source={sourceTag}");
		return true;
	}

	internal static int ClampPactVoteChoice(int voteType, bool allowNone)
	{
		if (allowNone && voteType < 0)
		{
			return -1;
		}
		if (voteType < PACT_VOTE_EARNINGS_UP)
		{
			return PACT_VOTE_EARNINGS_UP;
		}
		if (voteType > PACT_VOTE_CREW_STAY)
		{
			return PACT_VOTE_CREW_STAY;
		}
		return voteType;
	}

	internal static string GetPactVoteLabel(int voteType)
	{
		int vote = ClampPactVoteChoice(voteType, allowNone: true);
		switch (vote)
		{
		case PACT_VOTE_EARNINGS_UP:
			return "Increase earnings (+2%)";
		case PACT_VOTE_EARNINGS_DOWN:
			return "Lower earnings (-2%)";
		case PACT_VOTE_CREW_UP:
			return "Expand crew cap (+1)";
		case PACT_VOTE_CREW_STAY:
			return "Hold crew cap";
		default:
			return "No proposal";
		}
	}

	internal static string GetPactVoteShortLabel(int voteType)
	{
		int vote = ClampPactVoteChoice(voteType, allowNone: true);
		switch (vote)
		{
		case PACT_VOTE_EARNINGS_UP:
			return "Earn +2%";
		case PACT_VOTE_EARNINGS_DOWN:
			return "Earn -2%";
		case PACT_VOTE_CREW_UP:
			return "Crew +1";
		case PACT_VOTE_CREW_STAY:
			return "Crew =";
		default:
			return "None";
		}
	}

	internal static int RollPactVotePreference(float happiness, bool isHuman, int playerProposal)
	{
		if (isHuman)
		{
			int preferred = ClampPactVoteChoice(playerProposal, allowNone: true);
			return (preferred >= 0) ? preferred : PACT_VOTE_CREW_STAY;
		}
		float roll = (float)SharedRng.NextDouble();
		if (happiness <= 0.3f)
		{
			if (roll < 0.55f) return PACT_VOTE_EARNINGS_DOWN;
			if (roll < 0.85f) return PACT_VOTE_CREW_STAY;
			return PACT_VOTE_CREW_UP;
		}
		if (happiness >= 0.7f)
		{
			if (roll < 0.5f) return PACT_VOTE_EARNINGS_UP;
			if (roll < 0.8f) return PACT_VOTE_CREW_UP;
			return PACT_VOTE_CREW_STAY;
		}
		if (roll < 0.3f) return PACT_VOTE_EARNINGS_UP;
		if (roll < 0.55f) return PACT_VOTE_EARNINGS_DOWN;
		if (roll < 0.8f) return PACT_VOTE_CREW_UP;
		return PACT_VOTE_CREW_STAY;
	}

	internal static void EnsurePactVotePreferences(AlliancePact pact, IEnumerable<int> memberIds, int humanGangId)
	{
		if (pact == null)
		{
			return;
		}
		if (pact.VotePreferences == null)
		{
			pact.VotePreferences = new Dictionary<int, int>();
		}
		HashSet<int> validIds = new HashSet<int>();
		if (memberIds != null)
		{
			foreach (int memberId in memberIds)
			{
				if (memberId >= 0)
				{
					validIds.Add(memberId);
				}
			}
		}
		foreach (int staleId in pact.VotePreferences.Keys.Where(id => !validIds.Contains(id)).ToList())
		{
			pact.VotePreferences.Remove(staleId);
		}
		foreach (int memberId2 in validIds)
		{
			if (!pact.VotePreferences.ContainsKey(memberId2))
			{
				float happiness = pact.GetBossHappiness(memberId2);
				bool isHuman = memberId2 == humanGangId;
				pact.VotePreferences[memberId2] = RollPactVotePreference(happiness, isHuman, pact.PlayerProposedVote);
			}
			else
			{
				pact.VotePreferences[memberId2] = ClampPactVoteChoice(pact.VotePreferences[memberId2], allowNone: false);
			}
		}
		pact.PlayerProposedVote = ClampPactVoteChoice(pact.PlayerProposedVote, allowNone: true);
	}

	internal static int GetOrAssignPactVotePreference(AlliancePact pact, int gangId, bool isHumanMember, int humanGangId)
	{
		if (pact == null || gangId < 0)
		{
			return PACT_VOTE_EARNINGS_UP;
		}
		if (pact.VotePreferences == null)
		{
			pact.VotePreferences = new Dictionary<int, int>();
		}
		if (!pact.VotePreferences.TryGetValue(gangId, out int vote))
		{
			vote = RollPactVotePreference(pact.GetBossHappiness(gangId), isHumanMember || gangId == humanGangId, pact.PlayerProposedVote);
			pact.VotePreferences[gangId] = vote;
		}
		vote = ClampPactVoteChoice(vote, allowNone: false);
		pact.VotePreferences[gangId] = vote;
		return vote;
	}

	internal static bool ShouldDelayPactVoteResolutionForPrompt(AlliancePact pact, List<int> memberIds, int humanGangId, int nowDay)
	{
		if (pact == null)
		{
			return false;
		}

		List<int> members = (memberIds ?? new List<int>()).Where(id => id >= 0).Distinct().ToList();
		bool humanInPact = humanGangId >= 0 && members.Contains(humanGangId);
		if (pact.PendingVoteCycleDay < 0 || pact.PendingVoteCycleDay < pact.LastVoteDay)
		{
			pact.PendingVoteCycleDay = nowDay;
			pact.VotePromptShown = false;
			pact.VotePromptAnswered = !humanInPact;
			pact.PlayerProposedVote = -1;
		}

		if (!humanInPact)
		{
			return false;
		}

		if (!pact.VotePromptShown)
		{
			pact.VotePromptShown = PactVotePrompt.ShowPrompt(pact);
		}

		return !pact.VotePromptAnswered;
	}

	internal static void CompletePactVoteCycle(AlliancePact pact)
	{
		if (pact == null)
		{
			return;
		}

		pact.PendingVoteCycleDay = -1;
		pact.VotePromptShown = false;
		pact.VotePromptAnswered = false;
		pact.PlayerProposedVote = -1;
	}

	internal static bool TrySwayPactVoteToPlayerChoice(AlliancePact pact, int gangId, float chance)
	{
		if (pact == null || gangId < 0)
		{
			return false;
		}
		int desired = ClampPactVoteChoice(pact.PlayerProposedVote, allowNone: true);
		if (desired < 0)
		{
			return false;
		}
		float clampedChance = Mathf.Clamp01(chance);
		if (SharedRng.NextDouble() > clampedChance)
		{
			return false;
		}
		if (pact.VotePreferences == null)
		{
			pact.VotePreferences = new Dictionary<int, int>();
		}
		pact.VotePreferences[gangId] = desired;
		return true;
	}

	internal static List<int> GetPactMemberGangIds(AlliancePact pact)
	{
		List<int> ids = new List<int>();
		if (pact == null)
		{
			return ids;
		}
		if (pact.LeaderGangId >= 0)
		{
			ids.Add(pact.LeaderGangId);
		}
		if (pact.MemberIds != null)
		{
			ids.AddRange(pact.MemberIds);
		}
		return ids.Distinct().Where(id => id >= 0).ToList();
	}

	private static string GetOrderedPactPairKey(string firstPactId, string secondPactId)
	{
		string text = firstPactId ?? string.Empty;
		string text2 = secondPactId ?? string.Empty;
		return (string.CompareOrdinal(text, text2) <= 0) ? (text + "|" + text2) : (text2 + "|" + text);
	}

	internal static InterPactAlliance FindActiveInterPactAlliance(AlliancePact first, AlliancePact second)
	{
		if (!ArePactsInAlliance(first, second))
		{
			return null;
		}
		string orderedPactPairKey = GetOrderedPactPairKey(first.PactId, second.PactId);
		return GetActiveInterPactAlliances().FirstOrDefault((InterPactAlliance x) => GetOrderedPactPairKey(x.LeftPactId, x.RightPactId) == orderedPactPairKey);
	}

	internal static InterPactAllianceVote FindPendingInterPactAllianceVote(AlliancePact first, AlliancePact second, bool isRemoval)
	{
		if (first == null || second == null || SaveData?.PactAllianceVotes == null)
		{
			return null;
		}
		string orderedPactPairKey = GetOrderedPactPairKey(first.PactId, second.PactId);
		return SaveData.PactAllianceVotes.FirstOrDefault((InterPactAllianceVote x) => x != null && !x.Resolved && x.IsRemoval == isRemoval && GetOrderedPactPairKey(x.SourcePactId, x.TargetPactId) == orderedPactPairKey);
	}

	internal static void NormalizeInterPactAllianceData()
	{
		if (SaveData == null)
		{
			return;
		}
		if (SaveData.PactAlliances == null)
		{
			SaveData.PactAlliances = new List<InterPactAlliance>();
		}
		if (SaveData.PactAllianceVotes == null)
		{
			SaveData.PactAllianceVotes = new List<InterPactAllianceVote>();
		}
		HashSet<string> hashSet = new HashSet<string>(StringComparer.Ordinal);
		if (SaveData.PactAlliances != null)
		{
			for (int num = SaveData.PactAlliances.Count - 1; num >= 0; num--)
			{
				InterPactAlliance interPactAlliance = SaveData.PactAlliances[num];
				AlliancePact pactById = GetPactById(interPactAlliance?.LeftPactId);
				AlliancePact pactById2 = GetPactById(interPactAlliance?.RightPactId);
				string orderedPactPairKey = GetOrderedPactPairKey(interPactAlliance?.LeftPactId, interPactAlliance?.RightPactId);
				if (interPactAlliance == null || !interPactAlliance.Active || pactById == null || pactById2 == null || !pactById.IsActive || !pactById2.IsActive || string.IsNullOrEmpty(orderedPactPairKey) || orderedPactPairKey == "|" || !hashSet.Add(orderedPactPairKey))
				{
					SaveData.PactAlliances.RemoveAt(num);
				}
			}
		}
		if (SaveData.PactAllianceVotes != null)
		{
			for (int num2 = SaveData.PactAllianceVotes.Count - 1; num2 >= 0; num2--)
			{
				InterPactAllianceVote interPactAllianceVote = SaveData.PactAllianceVotes[num2];
				AlliancePact pactById3 = GetPactById(interPactAllianceVote?.SourcePactId);
				AlliancePact pactById4 = GetPactById(interPactAllianceVote?.TargetPactId);
				if (interPactAllianceVote == null || pactById3 == null || pactById4 == null || !pactById3.IsActive || !pactById4.IsActive || string.Equals(pactById3.PactId, pactById4.PactId, StringComparison.Ordinal))
				{
					SaveData.PactAllianceVotes.RemoveAt(num2);
				}
			}
		}
	}

	internal static List<int> GetInterPactAllianceEligibleGangIds(InterPactAllianceVote vote)
	{
		List<int> list = new List<int>();
		if (vote == null)
		{
			return list;
		}
		AlliancePact pactById = GetPactById(vote.SourcePactId);
		AlliancePact pactById2 = GetPactById(vote.TargetPactId);
		if (pactById != null)
		{
			list.AddRange(GetPactMemberGangIds(pactById));
		}
		if (pactById2 != null)
		{
			list.AddRange(GetPactMemberGangIds(pactById2));
		}
		return list.Distinct().Where((int id) => id >= 0).ToList();
	}

	internal static bool TryQueueInterPactAllianceVote(AlliancePact sourcePact, AlliancePact targetPact, bool isRemoval, int proposerGangId, bool initiatedByHuman, out string status)
	{
		status = string.Empty;
		if (sourcePact == null || targetPact == null)
		{
			status = "Missing pact";
			return false;
		}
		NormalizeInterPactAllianceData();
		if (!isRemoval && !CanPactsFormAlliance(sourcePact, targetPact))
		{
			status = "Alliance not available";
			return false;
		}
		if (isRemoval && FindActiveInterPactAlliance(sourcePact, targetPact) == null)
		{
			status = "No alliance to remove";
			return false;
		}
		InterPactAllianceVote pendingInterPactAllianceVote = FindPendingInterPactAllianceVote(sourcePact, targetPact, isRemoval);
		if (pendingInterPactAllianceVote == null)
		{
			pendingInterPactAllianceVote = new InterPactAllianceVote
			{
				VoteId = "pav_" + SaveData.NextPactAllianceVoteId++,
				SourcePactId = sourcePact.PactId ?? string.Empty,
				TargetPactId = targetPact.PactId ?? string.Empty,
				AllianceId = FindActiveInterPactAlliance(sourcePact, targetPact)?.AllianceId ?? string.Empty,
				IsRemoval = isRemoval,
				ProposedDay = G.GetNow().days,
				ProposerGangId = proposerGangId,
				InitiatedByHuman = initiatedByHuman
			};
			SaveData.PactAllianceVotes.Add(pendingInterPactAllianceVote);
			LogGrapevine($"PACT: {(isRemoval ? "Removal vote" : "Alliance vote")} opened between {sourcePact.DisplayName} and {targetPact.DisplayName}.");
		}
		pendingInterPactAllianceVote.VotesByGang[proposerGangId] = true;
		status = isRemoval ? "Removal vote cast." : "Alliance proposal sent.";
		return true;
	}

	internal static bool TryCastInterPactAllianceVote(AlliancePact sourcePact, AlliancePact targetPact, bool isRemoval, int gangId, bool support, bool initiatedByHuman, out string status)
	{
		status = string.Empty;
		if (gangId < 0)
		{
			status = "Missing voter";
			return false;
		}
		if (!TryQueueInterPactAllianceVote(sourcePact, targetPact, isRemoval, gangId, initiatedByHuman, out status))
		{
			return false;
		}
		InterPactAllianceVote pendingInterPactAllianceVote = FindPendingInterPactAllianceVote(sourcePact, targetPact, isRemoval);
		if (pendingInterPactAllianceVote == null)
		{
			status = "Vote not found";
			return false;
		}
		pendingInterPactAllianceVote.VotesByGang[gangId] = support;
		status = support ? "Vote recorded." : "Opposition recorded.";
		return true;
	}

	internal static float EvaluateInterPactAllianceSupport(PlayerInfo voter, AlliancePact ownPact, AlliancePact otherPact, bool isRemoval)
	{
		if (voter == null || ownPact == null || otherPact == null)
		{
			return 0f;
		}
		PlayerInfo playerById = G.FindPlayerById(otherPact.LeaderGangId);
		float interGangRelationshipScore = GetInterGangRelationshipScore(voter, playerById);
		float bossHappiness = ownPact.GetBossHappiness(voter.PID.id);
		float num = interGangRelationshipScore * 0.65f + bossHappiness * 0.35f;
		if (isRemoval)
		{
			num = 1f - num;
			if (playerById != null && (IsAggroWithoutTruceOneWay(voter, playerById.PID) || IsAggroWithoutTruceOneWay(playerById, voter.PID)))
			{
				num += 0.35f;
			}
		}
		return Mathf.Clamp01(num);
	}

	internal static void ApplyPactJoinRelationshipBoost(AlliancePact pact, int joinedGangId, string joinedGangName = null)
	{
		if (pact == null || joinedGangId < 0)
		{
			return;
		}
		List<int> ids = GetPactMemberGangIds(pact);
		PlayerInfo joinedGang = G.FindPlayerById(joinedGangId);
		foreach (int id in ids)
		{
			if (id == joinedGangId)
			{
				pact.SetBossHappiness(id, pact.GetBossHappiness(id) + 0.14f);
			}
			else
			{
				pact.SetBossHappiness(id, pact.GetBossHappiness(id) + 0.08f);
				PlayerInfo otherGang = G.FindPlayerById(id);
				if (joinedGang != null && otherGang != null)
				{
					AddMutualRelationshipBuff(joinedGang, otherGang, "relbuff-pact-joined", GetCrewPeepForPlayer(joinedGang), GetCrewPeepForPlayer(otherGang));
				}
			}
		}
		EnsurePactVotePreferences(pact, ids, G.GetHumanPlayer()?.PID.id ?? -1);
		string name = string.IsNullOrEmpty(joinedGangName) ? GetGangDisplayName(joinedGangId) : joinedGangName;
		LogGrapevine($"PACT: {name} gained trust after joining {pact.DisplayName}.");
	}

	internal static void ApplyPactBossDeathRelationshipPenalty(AlliancePact pact, IEnumerable<int> pactMembers, bool leaderWasKilled, int victimGangId, IEnumerable<PlayerInfo> attackers = null)
	{
		if (pact == null || pactMembers == null)
		{
			return;
		}
		float penalty = leaderWasKilled ? 0.22f : 0.14f;
		string buffId = leaderWasKilled ? "relbuff-pact-leader-killed" : "relbuff-pact-boss-killed";
		List<PlayerInfo> list = ((attackers != null) ? attackers.Where((PlayerInfo a) => a != null && a.crew != null && !a.crew.IsCrewDefeated).Distinct().ToList() : new List<PlayerInfo>());
		foreach (int memberId in pactMembers.Distinct())
		{
			if (memberId < 0 || memberId == victimGangId)
			{
				continue;
			}
			pact.SetBossHappiness(memberId, pact.GetBossHappiness(memberId) - penalty);
			if (list.Count > 0)
			{
				PlayerInfo playerInfo = G.FindPlayerById(memberId);
				if (playerInfo != null)
				{
					foreach (PlayerInfo item in list)
					{
						if (item.PID.id != playerInfo.PID.id)
						{
							bool forward = AddDirectedRelationshipBuff(playerInfo, item, buffId, GetCrewPeepForPlayer(playerInfo));
							bool reverse = AddDirectedRelationshipBuff(item, playerInfo, buffId, GetCrewPeepForPlayer(item));
							VerificationLog("PactRetaliation", $"Penalty buff {buffId} member={playerInfo.PID.id} attacker={item.PID.id} forward={forward} reverse={reverse}");
						}
					}
				}
			}
		}
		string victimName = GetGangDisplayName(victimGangId);
		LogGrapevine($"PACT: {pact.DisplayName} is enraged by the killing of {victimName}.");
	}

	internal static void ApplyPactVoteOutcome(AlliancePact pact, int voteType)
	{
		if (pact == null)
		{
			return;
		}
		switch (ClampPactVoteChoice(voteType, allowNone: false))
		{
		case PACT_VOTE_EARNINGS_UP:
			pact.EarningRate = Mathf.Clamp(pact.EarningRate + 0.02f, 0.05f, 0.25f);
			break;
		case PACT_VOTE_EARNINGS_DOWN:
			pact.EarningRate = Mathf.Clamp(pact.EarningRate - 0.02f, 0.05f, 0.25f);
			break;
		case PACT_VOTE_CREW_UP:
			pact.CrewCapacityBonus = Math.Min(10, pact.CrewCapacityBonus + 1);
			break;
		case PACT_VOTE_CREW_STAY:
			break;
		}
	}

	internal static void ResetPactVotingStats(AlliancePact pact)
	{
		if (pact == null)
		{
			return;
		}
		pact.LastVoteDay = -1;
		pact.LastVoteType = 0;
		pact.EarningRate = 0.05f;
		pact.CrewCapacityBonus = 0;
		CompletePactVoteCycle(pact);
		if (pact.VotePreferences == null)
		{
			pact.VotePreferences = new Dictionary<int, int>();
		}
		pact.VotePreferences.Clear();
		List<int> ids = new List<int>();
		if (pact.LeaderGangId >= 0)
		{
			ids.Add(pact.LeaderGangId);
		}
		ids.AddRange(pact.MemberIds);
		foreach (int id in ids.Distinct())
		{
			pact.SetBossHappiness(id, 1f);
		}
	}

	internal static int GetOrInitPactEpochDay(SimTime now)
	{
		int inferredStart = now.days;
		foreach (AlliancePact pact in SaveData.Pacts)
		{
			if (pact != null && pact.FormedDays > 0)
			{
				inferredStart = Math.Min(inferredStart, pact.FormedDays);
			}
		}
		if (SaveData.PactEpochDay >= 0)
		{
			if (inferredStart < SaveData.PactEpochDay)
			{
				VerificationLog("Pact", $"epoch-repaired old={SaveData.PactEpochDay} inferred={inferredStart} day={now.days} pacts={SaveData.Pacts.Count}");
				SaveData.PactEpochDay = inferredStart;
			}
			return SaveData.PactEpochDay;
		}
		SaveData.PactEpochDay = inferredStart;
		VerificationLog("Pact", $"epoch-initialized day={now.days} epoch={SaveData.PactEpochDay} pacts={SaveData.Pacts.Count}");
		return SaveData.PactEpochDay;
	}

	internal static int GetUnlockedAIPactSlots(SimTime now)
	{
		int elapsed = Math.Max(0, now.days - GetOrInitPactEpochDay(now));
		return Math.Min(AI_PACT_SLOT_COUNT, 1 + elapsed / PACT_UNLOCK_INTERVAL_DAYS);
	}

	internal static int GetPactTotalGangCount(AlliancePact pact)
	{
		if (pact == null)
		{
			return 0;
		}
		HashSet<int> ids = new HashSet<int>();
		if (pact.LeaderGangId >= 0)
		{
			ids.Add(pact.LeaderGangId);
		}
		if (pact.MemberIds != null)
		{
			foreach (int memberId in pact.MemberIds)
			{
				if (memberId >= 0)
				{
					ids.Add(memberId);
				}
			}
		}
		return ids.Count;
	}

	internal static bool IsGangInPact(AlliancePact pact, int gangId)
	{
		if (pact == null || gangId < 0)
		{
			return false;
		}
		if (pact.LeaderGangId == gangId)
		{
			return true;
		}
		return pact.MemberIds != null && pact.MemberIds.Contains(gangId);
	}

	internal static bool IsPactAtMemberCap(AlliancePact pact)
	{
		return GetPactTotalGangCount(pact) >= PACT_MAX_TOTAL_GANGS;
	}

	internal static bool CanGangJoinPact(AlliancePact pact, int gangId)
	{
		if (pact == null || gangId < 0)
		{
			return false;
		}
		return IsGangInPact(pact, gangId) || !IsPactAtMemberCap(pact);
	}

	private static void TrimPactMembershipToCap(AlliancePact pact)
	{
		if (pact == null)
		{
			return;
		}

		List<int> originalMembers = pact.MemberIds ?? new List<int>();
		List<int> keptMembers = new List<int>();
		HashSet<int> retainedIds = new HashSet<int>();
		if (pact.LeaderGangId >= 0)
		{
			retainedIds.Add(pact.LeaderGangId);
		}

		int humanGangId = G.GetHumanPlayer()?.PID.id ?? -1;
		if (humanGangId >= 0
			&& humanGangId != pact.LeaderGangId
			&& originalMembers.Contains(humanGangId)
			&& retainedIds.Count < PACT_MAX_TOTAL_GANGS)
		{
			keptMembers.Add(humanGangId);
			retainedIds.Add(humanGangId);
		}

		foreach (int memberId in originalMembers)
		{
			if (memberId < 0 || memberId == pact.LeaderGangId || retainedIds.Contains(memberId))
			{
				continue;
			}
			if (retainedIds.Count >= PACT_MAX_TOTAL_GANGS)
			{
				break;
			}
			keptMembers.Add(memberId);
			retainedIds.Add(memberId);
		}

		if (retainedIds.Count < GetPactTotalGangCount(pact))
		{
			VerificationLog("Pact", $"trim pact={pact.PactId} color={pact.ColorIndex} kept={retainedIds.Count} cap={PACT_MAX_TOTAL_GANGS}");
		}

		pact.MemberIds = keptMembers;
		pact.BossHappiness = (pact.BossHappiness ?? new Dictionary<int, float>())
			.Where(kv => retainedIds.Contains(kv.Key))
			.ToDictionary(kv => kv.Key, kv => Mathf.Clamp01(kv.Value));
		pact.VotePreferences = (pact.VotePreferences ?? new Dictionary<int, int>())
			.Where(kv => retainedIds.Contains(kv.Key))
			.ToDictionary(kv => kv.Key, kv => ClampPactVoteChoice(kv.Value, allowNone: false));

		if (SaveData.PlayerJoinedPactIndex == pact.ColorIndex
			&& humanGangId >= 0
			&& !retainedIds.Contains(humanGangId))
		{
			SaveData.PlayerJoinedPactIndex = -1;
		}
	}

	private static bool TryCloseDuplicateGroupedCopWitnessEntry(ImportantWitnessEntry entry, EntityID peepId, out string reason)
	{
		reason = "disabled-for-staggered-grouped-arrests";
		return false;
	}

	internal static void NormalizePactSlots()
		{
		HashSet<int> seenSlots = new HashSet<int>();
		for (int i = SaveData.Pacts.Count - 1; i >= 0; i--)
		{
			AlliancePact pact = SaveData.Pacts[i];
			if (pact == null)
			{
				SaveData.Pacts.RemoveAt(i);
				continue;
			}
			if (pact.MemberIds == null)
			{
				pact.MemberIds = new List<int>();
			}
			if (pact.BossHappiness == null)
			{
				pact.BossHappiness = new Dictionary<int, float>();
			}
			if (pact.VotePreferences == null)
			{
				pact.VotePreferences = new Dictionary<int, int>();
			}
			bool isPlayerPact = SaveData.PlayerPactId >= 0 && pact.PactId == $"pact_{SaveData.PlayerPactId}";
			if (isPlayerPact && pact.ColorIndex != PLAYER_PACT_SLOT_INDEX)
			{
				pact.ColorIndex = PLAYER_PACT_SLOT_INDEX;
			}
			if (!isPlayerPact && pact.ColorIndex == PLAYER_PACT_SLOT_INDEX)
			{
				int replacementIndex = -1;
				for (int slot = 0; slot < AI_PACT_SLOT_COUNT; slot++)
				{
					if (!seenSlots.Contains(slot) && SaveData.Pacts.All(other => other == pact || other == null || other.ColorIndex != slot))
					{
						replacementIndex = slot;
						break;
					}
				}
				if (replacementIndex >= 0 && replacementIndex < AI_PACT_SLOT_COUNT)
				{
					pact.ColorIndex = replacementIndex;
				}
				else
				{
					VerificationLog("Pact", $"normalize-removed pact={pact.PactId} leader={pact.LeaderGangId} slot={pact.ColorIndex} reason=no-replacement-slot");
					SaveData.Pacts.RemoveAt(i);
					continue;
				}
			}
			if (pact.ColorIndex >= TOTAL_PACT_SLOT_COUNT || pact.ColorIndex < 0)
			{
				VerificationLog("Pact", $"normalize-removed pact={pact.PactId} leader={pact.LeaderGangId} slot={pact.ColorIndex} reason=invalid-slot");
				SaveData.Pacts.RemoveAt(i);
				continue;
			}
			pact.MemberIds = pact.MemberIds
				.Where(mid => mid >= 0 && mid != pact.LeaderGangId)
				.Distinct()
				.ToList();
			TrimPactMembershipToCap(pact);
			HashSet<int> validIds = new HashSet<int>(pact.MemberIds);
			if (pact.LeaderGangId >= 0)
			{
				validIds.Add(pact.LeaderGangId);
			}
			pact.BossHappiness = pact.BossHappiness
				.Where(kv => validIds.Contains(kv.Key))
				.ToDictionary(kv => kv.Key, kv => Mathf.Clamp01(kv.Value));
			if (pact.VotePreferences == null)
			{
				pact.VotePreferences = new Dictionary<int, int>();
			}
			pact.VotePreferences = pact.VotePreferences
				.Where(kv => validIds.Contains(kv.Key))
				.ToDictionary(kv => kv.Key, kv => ClampPactVoteChoice(kv.Value, allowNone: false));
			pact.PlayerProposedVote = ClampPactVoteChoice(pact.PlayerProposedVote, allowNone: true);
			if (!seenSlots.Add(pact.ColorIndex))
			{
				VerificationLog("Pact", $"normalize-removed pact={pact.PactId} leader={pact.LeaderGangId} slot={pact.ColorIndex} reason=duplicate-slot");
				SaveData.Pacts.RemoveAt(i);
			}
		}
		if ((SaveData.PlayerJoinedPactIndex == 6 || SaveData.PlayerJoinedPactIndex == 4) && SaveData.PlayerPactId >= 0)
		{
			SaveData.PlayerJoinedPactIndex = PLAYER_PACT_SLOT_INDEX;
		}
		if (SaveData.PlayerJoinedPactIndex >= TOTAL_PACT_SLOT_COUNT)
		{
			SaveData.PlayerJoinedPactIndex = -1;
		}
	}

	internal static void LogGrapevine(string msg)
	{
		msg = NormalizeRuntimeLogText(msg, aggressive: true);
		if (string.IsNullOrWhiteSpace(msg))
		{
			return;
		}
		if (SaveData == null)
		{
			SaveData = new ModSaveData();
		}
		if (SaveData.GrapevineEvents == null)
		{
			SaveData.GrapevineEvents = new List<string>();
		}
		if (ShouldSuppressTickerDupes() && !string.IsNullOrEmpty(msg))
		{
			if (msg.StartsWith("WAR:", StringComparison.OrdinalIgnoreCase)
				|| msg.StartsWith("FIGHT:", StringComparison.OrdinalIgnoreCase)
				|| msg.StartsWith("SHOOTOUT:", StringComparison.OrdinalIgnoreCase)
				|| msg.StartsWith("PACT:", StringComparison.OrdinalIgnoreCase)
				|| msg.StartsWith("FRONT:", StringComparison.OrdinalIgnoreCase))
			{
				return;
			}
		}
		SaveData.GrapevineEvents.Insert(0, msg);
		if (SaveData.GrapevineEvents.Count > 50)
		{
			SaveData.GrapevineEvents.RemoveRange(50, SaveData.GrapevineEvents.Count - 50);
		}
		int day = GetGrapevineLogDay();
		if (day >= 0)
		{
			_lastGrapevinePostDay = day;
		}
		_grapevinePostSessionCount++;
		VerificationLog("Grapevine", $"posted day={day} category={GetGrapevineCategoryForLog(msg)} count={SaveData.GrapevineEvents.Count} session={_grapevinePostSessionCount} text=\"{GetGrapevineTextForLog(msg)}\"");
	}

	internal static void TryRunWeeklyGrapevinePulse(SimTime now, string source)
	{
		try
		{
			if (now.days < 0)
			{
				return;
			}
			if (SaveData == null)
			{
				SaveData = new ModSaveData();
			}
			if (SaveData.GrapevineEvents == null)
			{
				SaveData.GrapevineEvents = new List<string>();
			}
			if (_lastGrapevinePostDay == int.MinValue && SaveData.GrapevineEvents.Count > 0)
			{
				_lastGrapevinePostDay = now.days;
				VerificationLog("Grapevine", $"weekly-pulse seeded source={source ?? "unknown"} day={now.days} existing={SaveData.GrapevineEvents.Count}");
				return;
			}
			if (_lastGrapevinePulseDay == now.days)
			{
				return;
			}
			if (_lastGrapevinePostDay != int.MinValue && now.days - _lastGrapevinePostDay < GRAPEVINE_WEEKLY_PULSE_INTERVAL_DAYS)
			{
				return;
			}

			int activeGangs = CountActiveAiGangsForGrapevinePulse();
			int activePacts = SaveData.Pacts?.Count(p => p != null && p.IsActive) ?? 0;
			int heatEntries = (SaveData.PactWarHeat?.Count ?? 0) + (SaveData.IndependentWarHeat?.Count ?? 0);
			int weekNumber = Math.Max(1, now.days / Math.Max(1, GRAPEVINE_WEEKLY_PULSE_INTERVAL_DAYS));
			string heatText = heatEntries > 0
				? $" with {heatEntries} grudges still warm"
				: " without a public war move";
			string pactText = activePacts > 0
				? $"{activePacts} pact{(activePacts == 1 ? "" : "s")} and "
				: string.Empty;
			string msg = $"STREET: Week {weekNumber} stayed quiet. {pactText}{activeGangs} outfits kept watch over their corners{heatText}.";
			int before = SaveData.GrapevineEvents.Count;
			_lastGrapevinePulseDay = now.days;
			LogGrapevine(msg);
			VerificationLog("Grapevine", $"weekly-pulse source={source ?? "unknown"} day={now.days} before={before} after={SaveData.GrapevineEvents.Count} activeGangs={activeGangs} activePacts={activePacts} heat={heatEntries}");
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Weekly grapevine pulse failed: " + ex.Message);
		}
	}

	internal static void ResetGrapevineRuntimeState()
	{
		_lastGrapevinePostDay = int.MinValue;
		_lastGrapevinePulseDay = int.MinValue;
		_grapevinePostSessionCount = 0;
	}

	private static int CountActiveAiGangsForGrapevinePulse()
	{
		try
		{
			return G.GetAllPlayers().Count(gang => gang != null && !gang.PID.IsHumanPlayer && gang.IsJustGang && gang.crew != null && !gang.crew.IsCrewDefeated);
		}
		catch
		{
			return 0;
		}
	}

	private static int GetGrapevineLogDay()
	{
		try
		{
			return G.GetNow().days;
		}
		catch
		{
			return -1;
		}
	}

	private static string GetGrapevineCategoryForLog(string msg)
	{
		if (string.IsNullOrWhiteSpace(msg))
		{
			return "MISC";
		}
		int colon = msg.IndexOf(':');
		if (colon <= 0 || colon > 20)
		{
			return "MISC";
		}
		return msg.Substring(0, colon).Trim().ToUpperInvariant();
	}

	private static string GetGrapevineTextForLog(string msg)
	{
		if (string.IsNullOrEmpty(msg))
		{
			return string.Empty;
		}
		string cleaned = msg.Replace('"', '\'').Replace('\r', ' ').Replace('\n', ' ').Trim();
		return cleaned.Length <= 140 ? cleaned : cleaned.Substring(0, 137) + "...";
	}

	public static string NormalizeRuntimePersonName(string raw)
	{
		string text = NormalizeRuntimeLogText(raw, aggressive: false);
		return string.IsNullOrWhiteSpace(text) ? string.Empty : text;
	}

	public static string NormalizeRuntimeLogText(string raw, bool aggressive)
	{
		if (string.IsNullOrEmpty(raw))
		{
			return string.Empty;
		}

		string text = CrewRelationshipHandlerPatch.SanitizeUiGlyphText(raw, aggressive).Trim();
		if (string.IsNullOrEmpty(text))
		{
			return string.Empty;
		}

		if (!LooksLikeRuntimeMojibake(text))
		{
			return text;
		}

		string repaired = TryRepairRuntimeMojibake(text);
		if (string.IsNullOrWhiteSpace(repaired))
		{
			return text;
		}

		return GetRuntimeMojibakeScore(repaired) < GetRuntimeMojibakeScore(text)
			? repaired.Trim()
			: text;
	}

	private static bool LooksLikeRuntimeMojibake(string value)
	{
		if (string.IsNullOrEmpty(value))
		{
			return false;
		}

		for (int i = 0; i < value.Length; i++)
		{
			switch (value[i])
			{
				case '\u00C3':
				case '\u00C5':
				case '\u00C4':
				case '\u00C6':
				case '\u00D0':
				case '\u00D1':
				case '\u00D8':
				case '\u00DE':
				case '\u00E2':
				case '\u20AC':
				case '\u0153':
				case '\u017D':
				case '\u017E':
				case '\u201A':
				case '\u201E':
				case '\u2020':
				case '\u2021':
				case '\u2030':
				case '\u2039':
				case '\u203A':
				case '\u2122':
				case '\uFFFD':
					return true;
			}
		}

		return false;
	}

	private static string TryRepairRuntimeMojibake(string value)
	{
		try
		{
			byte[] bytes = Encoding.GetEncoding(1252).GetBytes(value);
			string repaired = Encoding.UTF8.GetString(bytes);
			return string.IsNullOrWhiteSpace(repaired) ? value : repaired;
		}
		catch
		{
			return value;
		}
	}

	private static int GetRuntimeMojibakeScore(string value)
	{
		if (string.IsNullOrEmpty(value))
		{
			return 0;
		}

		int score = 0;
		for (int i = 0; i < value.Length; i++)
		{
			char c = value[i];
			if (c == '\uFFFD')
			{
				score += 12;
				continue;
			}

			switch (c)
			{
				case '\u00C3':
				case '\u00C5':
				case '\u00C4':
				case '\u00C6':
				case '\u00D0':
				case '\u00D1':
				case '\u00D8':
				case '\u00DE':
				case '\u00E2':
				case '\u20AC':
				case '\u0153':
				case '\u017D':
				case '\u017E':
				case '\u201A':
				case '\u201E':
				case '\u2020':
				case '\u2021':
				case '\u2030':
				case '\u2039':
				case '\u203A':
				case '\u2122':
					score += 3;
					break;
			}
		}

		return score;
	}

	internal static int GetBribeCost(WantedLevel level)
	{
		return 520 * (1 << (int)level);
	}

	internal static void GrantStreetCredit(PlayerInfo player, int amount)
	{

		try
		{
			EntityID safehouse = player.territory.Safehouse;
			if (safehouse.IsNotValid)
			{
				Debug.LogWarning("[GameplayTweaks] No safehouse found for street credit grant");
				return;
			}
			Entity val = EntityIDExtensions.FindEntity(safehouse);
			if (val == null)
			{
				Debug.LogWarning("[GameplayTweaks] Safehouse entity not found");
				return;
			}
			InventoryModule inventory = ModulesUtil.GetInventory(val);
			if (inventory != null)
			{
				Label val2 = default(Label);
				val2 = new Label("streetcredit");
				int num = inventory.ForceAddResourcesRegardlessOfSpace(val2, amount);
				Debug.Log($"[GameplayTweaks] Granted {num} streetcredit to safehouse (requested: {amount})");
			}
			else
			{
				Debug.LogWarning("[GameplayTweaks] Safehouse inventory not found");
			}
		}
		catch (Exception arg)
		{
			Debug.LogError($"[GameplayTweaks] GrantStreetCredit failed: {arg}");
		}
	}

	internal static int ResolveStreetCreditProgressLevelUps(CrewModState state, PlayerInfo owner, EntityID peepId, string source)
	{
		if (state == null || owner == null)
		{
			return 0;
		}
		float progress = Mathf.Max(0f, state.StreetCreditProgress);
		int levelsGained = 0;
		while (progress >= 0.9999f)
		{
			progress -= 1f;
			state.StreetCreditLevel++;
			GrantStreetCredit(owner, 7);
			levelsGained++;
		}
		state.StreetCreditProgress = Mathf.Clamp01(progress);
		if (levelsGained > 0)
		{
			VerificationLog("StreetCredit", $"level-up source={source} peep={peepId.id} gained={levelsGained} level={state.StreetCreditLevel} progress={state.StreetCreditProgress:0.000}");
		}
		return levelsGained;
	}

	internal static void ApplyJailSmuggleStreetCred(CrewModState state, int soldAmount, PlayerInfo owner, EntityID peepId, string itemKey)
	{
		if (state == null || owner == null || soldAmount <= 0)
		{
			return;
		}

		bool isBooze = CrewRelationshipHandlerPatch.IsBoozeSmuggleItemKey(itemKey);
		float totalGain = GetRandomStreetCreditGain(0.04f, 0.06f);
		float progressBefore = Mathf.Clamp01(state.StreetCreditProgress);

		state.TotalBoozeSoldLifetime += soldAmount;
		state.TotalBoozeSoldStreet += Mathf.RoundToInt(totalGain * 100f);
		state.StreetCreditProgress = Mathf.Max(0f, state.StreetCreditProgress) + totalGain;

		int levelsGained = ResolveStreetCreditProgressLevelUps(state, owner, peepId, "jail-smuggle");
		VerificationLog("StreetCredit", $"source=jail-smuggle peep={peepId.id} item={itemKey} sold={soldAmount} type={(isBooze ? "booze" : "contraband")} gain={totalGain:0.000} progressBefore={progressBefore:0.000} progressAfter={state.StreetCreditProgress:0.000} levels={levelsGained}");
	}

	/// <summary>Apply booze-sold street cred and low heat (no witness). Cred only when lifetime crosses 150, 300, 450...; 40% of one level per cross. Works for all crews (player and AI).</summary>
	internal static void ApplyBoozeSoldForStreetCred(CrewModState state, int soldAmount, PlayerInfo owner, EntityID peepId, SimTime now, bool applyHeat = true)
	{
		if (state == null || owner == null || soldAmount <= 0)
		{
			return;
		}
		state.TotalBoozeSoldLifetime += soldAmount;
		float totalGain = GetRandomStreetCreditGain(0.02f, 0.04f);
		float progressBefore = Mathf.Clamp01(state.StreetCreditProgress);
		state.TotalBoozeSoldStreet += Mathf.RoundToInt(totalGain * 100f);
		float heatBefore = state.LocalHeatProgress;
		if (applyHeat)
		{
			SetLocalHeatProgress(state, Mathf.Clamp01(state.LocalHeatProgress + ModConstants.BOOZE_THRESHOLD_HEAT_BUMP), now.days, refreshDecayAnchor: true);
		}
		state.StreetCreditProgress = Mathf.Max(0f, state.StreetCreditProgress) + totalGain;
		int levelsGained = ResolveStreetCreditProgressLevelUps(state, owner, peepId, "booze-threshold");
		VerificationLog("BoozeSell", $"credit peep={peepId.id} sold={soldAmount} gain={totalGain:0.000} heatApplied={applyHeat} heatBefore={heatBefore:0.000} heatAfter={state.LocalHeatProgress:0.000} progressBefore={progressBefore:0.000} progressAfter={state.StreetCreditProgress:0.000} levels={levelsGained}");
	}

	private static float GetRandomStreetCreditGain(float minInclusive, float maxInclusive)
	{
		if (maxInclusive <= minInclusive)
		{
			return Mathf.Max(0f, minInclusive);
		}

		float t = (float)SharedRng.NextDouble();
		return Mathf.Lerp(minInclusive, maxInclusive, t);
	}

	internal static int GetGangTerritoryCount(PlayerInfo gang)
	{
		if (gang == null)
		{
			return 0;
		}
		try
		{
			PlayerTerritory territory = gang.territory;
			if (territory != null)
			{
				return territory.OwnedNodeCount;
			}
		}
		catch
		{
		}
		return 0;
	}

	internal static int GetGangStreetCredLevel(PlayerInfo gang)
	{
		if (gang == null)
		{
			return 0;
		}
		try
		{
			PlayerCrew crew = gang.crew;
			if (crew == null)
			{
				return 0;
			}
			CrewAssignment crewForIndex = crew.GetCrewForIndex(0);
			if (!crewForIndex.IsValid)
			{
				return 0;
			}
			Entity peep = crewForIndex.GetPeep();
			if (peep == null)
			{
				return 0;
			}
			CrewModState crewStateOrNull = GetCrewStateOrNull(peep.Id);
			if (crewStateOrNull == null)
			{
				return 0;
			}
			return crewStateOrNull.StreetCreditLevel;
		}
		catch
		{
			return 0;
		}
	}

	internal static float CalculateAIPactFoundingScore(PlayerInfo gang)
	{
		if (gang == null)
		{
			return 0f;
		}
		int territory = GetGangTerritoryCount(gang);
		if (territory < AI_PACT_FOUNDER_MIN_TERRITORIES)
		{
			return 0f;
		}
		int power = CalculateGangPower(gang);
		int sc = GetGangStreetCredLevel(gang);
		float streetCredWeight = 6f;
		return power + sc * streetCredWeight;
	}

	internal static float CalculateAIPactPartnerScore(PlayerInfo leader, PlayerInfo partner)
	{
		if (leader == null || partner == null)
		{
			return 0f;
		}
		int power = CalculateGangPower(partner);
		float rel = GetInterGangRelationshipScore(leader, partner);
		float powerWeight = 1f;
		float relWeight = 50f;
		return power * powerWeight + rel * relWeight;
	}

	internal static int GetInterGangRelationshipDisplayScore(PlayerInfo a, PlayerInfo b)
	{
		return Mathf.RoundToInt(GetSignedGangRelationshipBias(a, b) * 100f);
	}

	internal static float GetSignedGangRelationshipBias(PlayerInfo a, PlayerInfo b)
	{
		if (a == null || b == null)
		{
			return 0f;
		}
		if (a.PID.id == b.PID.id)
		{
			return 1f;
		}
		int aId = a.PID.id;
		int bId = b.PID.id;
		float warHeatAB = GetWarHeat(GangOpsChannel.Pact, aId, bId);
		float warHeatBA = GetWarHeat(GangOpsChannel.Pact, bId, aId);
		float warHeat = Mathf.Max(warHeatAB, warHeatBA);
		float num = 0f;
		num -= Mathf.Clamp01(warHeat / 80f) * 0.75f;
		if (IsAggroWithoutTruceOneWay(a, b.PID) || IsAggroWithoutTruceOneWay(b, a.PID))
		{
			num -= 0.2f;
		}
		if (RelationshipHasBuff(a, b, "relbuff-pact-joined") || RelationshipHasBuff(b, a, "relbuff-pact-joined"))
		{
			num += 0.18f;
		}
		if (RelationshipHasBuff(a, b, "relbuff-pact-support-cash") || RelationshipHasBuff(b, a, "relbuff-pact-support-cash"))
		{
			num += 0.1f;
		}
		if (RelationshipHasBuff(a, b, "relbuff-pact-support-intro") || RelationshipHasBuff(b, a, "relbuff-pact-support-intro"))
		{
			num += 0.15f;
		}
		if (RelationshipHasBuff(a, b, "relbuff-pact-trade") || RelationshipHasBuff(b, a, "relbuff-pact-trade"))
		{
			num += 0.12f;
		}
		if (RelationshipHasBuff(a, b, "relbuff-pact-leader-killed") || RelationshipHasBuff(b, a, "relbuff-pact-leader-killed") || RelationshipHasBuff(a, b, "relbuff-pact-boss-killed") || RelationshipHasBuff(b, a, "relbuff-pact-boss-killed"))
		{
			num -= 0.25f;
		}
		if (RelationshipHasBuff(a, b, "relbuff-cop-killed-precinct") || RelationshipHasBuff(b, a, "relbuff-cop-killed-precinct"))
		{
			num -= 0.75f;
		}
		if (RelationshipHasBuff(a, b, "relbuff-cop-killed-citywide") || RelationshipHasBuff(b, a, "relbuff-cop-killed-citywide"))
		{
			num -= 0.5f;
		}
		if (RelationshipHasBuff(a, b, "relbuff-politics-protection") || RelationshipHasBuff(b, a, "relbuff-politics-protection"))
		{
			num += 0.4f;
		}
		if (HasPoliticalFavorRelationship(a, b))
		{
			num += 0.55f;
		}
		return Mathf.Clamp(num, -1f, 1f);
	}

	private static bool HasPoliticalFavorRelationship(PlayerInfo a, PlayerInfo b)
	{
		if (a == null || b == null)
		{
			return false;
		}
		try
		{
			Type copWarSystemType = Type.GetType("CopKilling.CopWarSystem, CopKilling");
			MethodInfo method = copWarSystemType?.GetMethod("HasPoliticalFavorRelationship", BindingFlags.Static | BindingFlags.Public);
			return method != null && method.Invoke(null, new object[2] { a.PID.id, b.PID.id }) is bool flag && flag;
		}
		catch
		{
			return false;
		}
	}

	internal static float GetInterGangRelationshipScore(PlayerInfo a, PlayerInfo b)
	{
		if (a == null || b == null)
		{
			return 0.5f;
		}
		if (a.PID.id == b.PID.id)
		{
			return 1f;
		}
		return Mathf.Clamp01(0.5f + GetSignedGangRelationshipBias(a, b) * 0.5f);
	}

	internal static int CalculateGangPower(PlayerInfo player)
	{
		if (player == null)
		{
			return 0;
		}
		PlayerCrew crew = player.crew;
		if (crew == null)
		{
			return 25;
		}
		int power = 25;
		try
		{
			foreach (CrewAssignment assignment in crew.GetLiving())
			{
				int crewPower = 10;
				Entity peep = assignment.GetPeep();
				try
				{
					AgentComponent agent = peep?.components?.agent;
					if (agent != null && agent.HasHealthPointsLeft)
					{
						crewPower += Mathf.RoundToInt(Mathf.Clamp01(agent.CurrentHealthAsFraction) * 4f);
					}
				}
				catch
				{
				}
				try
				{
					XP xp = peep?.data?.agent?.xp;
					if (xp != null)
					{
						crewPower += Mathf.Clamp(xp.GetLevelupLevel(AI_POWER_LEVELUP_HOODS), 0, 10) * 2;
						crewPower += Mathf.Clamp(xp.GetLevelupLevel(AI_POWER_LEVELUP_HOODSGANG), 0, 10) * 3;
					}
				}
				catch
				{
				}
				power += crewPower;
			}
			return power;
		}
		catch
		{
			return crew.LivingCrewCount * 10 + 25;
		}
	}

	internal static Canvas GetOrCreateOverlayCanvas()
	{

		if ((UnityEngine.Object)(object)_modOverlayCanvas != (UnityEngine.Object)null && (UnityEngine.Object)(object)((Component)_modOverlayCanvas).gameObject != (UnityEngine.Object)null)
		{
			return _modOverlayCanvas;
		}
		GameObject val = new GameObject("ModOverlayCanvas", new Type[3]
		{
			typeof(Canvas),
			typeof(CanvasScaler),
			typeof(GraphicRaycaster)
		});
		UnityEngine.Object.DontDestroyOnLoad((UnityEngine.Object)val);
		_modOverlayCanvas = val.GetComponent<Canvas>();
		_modOverlayCanvas.renderMode = (RenderMode)0;
		_modOverlayCanvas.sortingOrder = 990;
		CanvasScaler component = val.GetComponent<CanvasScaler>();
		component.uiScaleMode = (CanvasScaler.ScaleMode)1;
		component.referenceResolution = new Vector2(1920f, 1080f);
		return _modOverlayCanvas;
	}
