			GameplayTweaksPlugin.DeferHumanFederalArrestTicker(pid, crew.peepId, key, years, source);
			return false;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Deferred federal arrest ticker guard failed: " + ex.Message);
			return true;
		}
	}

