	private static void StartHumanArrestPostfix(PlayerInfo player, CrewAssignment crew)
	{
		try
		{
			if (player == null || !player.PID.IsHumanPlayer || !crew.IsValid)
			{
				return;
			}
			if (GameplayTweaksPlugin.ShouldSuppressVanillaStartHumanArrestForLocalImportantWitness(crew.peepId, out int pendingDay, out int sourceType))
			{
				GameplayTweaksPlugin.VerificationLog("Jail", $"local-important-witness-terminal-closeout peep={crew.peepId.id}{GameplayTweaksPlugin.FormatHumanCrewIndexTag(crew.peepId)} source=start-human-arrest pendingDay={pendingDay} sourceType={sourceType}");
				return;
			}
			if (GameplayTweaksPlugin.WasSafeFederalArrestHandledToday(crew.peepId))
			{
				return;
			}
			bool hasRaidContext = GameplayTweaksPlugin.HasPendingHumanCornerHeatRaidContext();
			if (!hasRaidContext)
			{
				Node federalNode = GameplayTweaksPlugin.TryResolveDirectArrestSnapshotNode(crew.peepId);
				GameplayTweaksPlugin.CloseFederalHumanArrest(crew.peepId, federalNode, "start-human-arrest", "federal-arrest");
				GameplayTweaksPlugin.TryDeferDirectArrestVehicleStateRepairFromSnapshot(crew.peepId, federalNode, "start-human-arrest", "federal-arrest", federalArrestLane: true);
				return;
			}
			Node pendingRaidNode = GameplayTweaksPlugin._pendingHumanCornerHeatPrecinctRaidActive && GameplayTweaksPlugin._pendingHumanCornerHeatRaidNodeId.IsValid
				? GameplayTweaksPlugin._pendingHumanCornerHeatRaidNodeId.FindNode()
				: null;
			if (GameplayTweaksPlugin.IsHumanPrecinctRaidEventConsumed(crew.peepId, pendingRaidNode, "start-human-arrest"))
			{
				return;
			}
			if (!GameplayTweaksPlugin.TryBeginCornerRaidArrestPostfix(crew.peepId, pendingRaidNode, "start-human-arrest"))
			{
				GameplayTweaksPlugin.MarkHumanPrecinctRaidEventConsumed(crew.peepId, pendingRaidNode, "start-human-arrest");
				GameplayTweaksPlugin.TryRepairDirectArrestVehicleStateFromSnapshot(crew.peepId, pendingRaidNode, "start-human-arrest", "already-normalized");
				return;
			}
			Node handledNode = pendingRaidNode;
			bool handledArrest = false;
			if (GameplayTweaksPlugin.TryConsumePendingCornerHeatRaid(player))
			{
				if (GameplayTweaksPlugin.TryRaiseLocalHeatOneTierFromCornerRaid(crew.peepId, out var heatBefore, out var heatAfter, out var progressBefore, out var progressAfter))
				{
					GameplayTweaksPlugin.VerificationLog("CornerHeatRaid", $"arrest peep={crew.peepId.id}{GameplayTweaksPlugin.FormatHumanCrewIndexTag(crew.peepId)} heatBefore={heatBefore} heatAfter={heatAfter} progressBefore={progressBefore:0.00} progressAfter={progressAfter:0.00} witnessAdded=false federalWitnessAdded=false");
					handledArrest = true;
				}
			}
			else if (GameplayTweaksPlugin.TryRaiseLocalHeatFromDirectHumanArrestAtHotNode(player, crew, out var node, out var nodeHeat, out var heatBefore2, out var heatAfter2, out var progressBefore2, out var progressAfter2))
			{
				handledNode = node;
				GameplayTweaksPlugin.VerificationLog("CornerHeatRaid", $"arrest-node peep={crew.peepId.id}{GameplayTweaksPlugin.FormatHumanCrewIndexTag(crew.peepId)} node={node.id} heat={nodeHeat} heatBefore={heatBefore2} heatAfter={heatAfter2} progressBefore={progressBefore2:0.00} progressAfter={progressAfter2:0.00} witnessAdded=false federalWitnessAdded=false");
				handledArrest = true;
			}
			if (handledArrest)
			{
				GameplayTweaksPlugin.MarkHumanPrecinctRaidEventConsumed(crew.peepId, handledNode, "start-human-arrest");
				GameplayTweaksPlugin.RefreshHumanStateAfterDirectArrest(crew.peepId, handledNode, "start-human-arrest");
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Corner heat arrest observer failed: " + ex.Message);
		}
	}

	private static PlayerInfo TryResolveAttackAdvisorPlayer(object advisorInstance)
	{
		if (advisorInstance == null)
		{
			return null;
		}
		try
		{
			FieldInfo fieldInfo = advisorInstance.GetType().GetField("_player", BindingFlags.Instance | BindingFlags.NonPublic) ?? advisorInstance.GetType().GetField("player", BindingFlags.Instance | BindingFlags.NonPublic);
			return fieldInfo?.GetValue(advisorInstance) as PlayerInfo;
		}
		catch
		{
			return null;
		}
	}

	private static PlayerID TryResolveAttackAdvisorPid(object advisorInstance)
	{
		if (advisorInstance == null)
		{
			return PlayerID.INVALID;
		}
		try
		{
			return _attackAdvisorPidField?.GetValue(advisorInstance) is PlayerID playerId ? playerId : PlayerID.INVALID;
		}
		catch
		{
			return PlayerID.INVALID;
		}
	}

	private static bool TryCanRunTryPickCoord(AttackAdvisor advisor, PlayerInfo playerInfo, out AttackAdvisorData data, out AttackAdvisorConfig.CoordinatedAttack def, out Node headquartersNode, out string reason)
	{
		data = null;
		def = null;
		headquartersNode = null;
		reason = "allow";
		if (advisor == null)
		{
			reason = "missing-advisor";
			return false;
		}
		if (playerInfo == null)
		{
			reason = "missing-player";
			return false;
		}
		if (playerInfo.territory == null)
		{
			reason = "missing-territory";
			return false;
		}
		if (!TryResolveHeadquartersNode(playerInfo, out headquartersNode, out reason))
		{
			return false;
		}
		data = _attackAdvisorDataField?.GetValue(advisor) as AttackAdvisorData;
		if (data == null)
		{
			reason = "missing-data";
			return false;
		}
		if (!(_attackAdvisorDefField?.GetValue(advisor) is AttackAdvisorConfig attackConfig))
		{
			reason = "missing-config";
			return false;
		}
		def = attackConfig.coordinatedAttack;
		if (def == null)
		{
			reason = "missing-coord-config";
			return false;
		}
		if (def.maxDistance == null || def.minCrewSize == null || def.maxRel == null || def.checkProbability == null)
		{
			reason = "missing-coord-values";
			return false;
		}
		if (_checkOurPrereqsMethod == null || _canOtherPlayerBeTargetedMethod == null || _checkEnemyPrereqsMethod == null)
		{
			reason = "missing-coord-methods";
			return false;
		}
		return true;
	}

	private static bool TryResolveHeadquartersNode(PlayerInfo playerInfo, out Node headquartersNode, out string reason)
	{
		headquartersNode = null;
		reason = "allow";
		if (playerInfo?.territory == null)
		{
			reason = "missing-territory";
			return false;
		}
		try
		{
			headquartersNode = playerInfo.territory.GetHeadquartersNode();
		}
		catch (Exception ex)
		{
			reason = "hq-throw-" + ex.GetType().Name;
			return false;
		}
		if (headquartersNode == null || !headquartersNode.id.IsValid)
		{
			if (TryResolveFallbackHeadquartersNodeFromControlledBuilding(playerInfo, out headquartersNode))
			{
				reason = "fallback-building-node";
				return true;
			}
			reason = "missing-hq-node";
			return false;
		}
		return true;
	}

	private static bool TryResolveFallbackHeadquartersNodeFromControlledBuilding(PlayerInfo playerInfo, out Node headquartersNode)
	{
		headquartersNode = null;
		List<Entity> controlledBuildings = GetControlledBuildingsSnapshot(playerInfo);
		foreach (Entity building in controlledBuildings)
		{
			NodeID boardNodeId = building?.data?.board?.bead.nodeId ?? NodeID.INVALID;
			if (boardNodeId.IsValid)
			{
				headquartersNode = boardNodeId.FindNode();
				if (headquartersNode != null && headquartersNode.id.IsValid)
				{
					return true;
				}
			}

			WorldPos worldPos = building?.data?.board?.worldpos ?? WorldPos.Zero;
			if (!worldPos.IsZero && global::Game.Game.ctx?.board?.nodes != null)
			{
				headquartersNode = global::Game.Game.ctx.board.nodes.FindNearestNodeAround(worldPos, 5f);
				if (headquartersNode != null && headquartersNode.id.IsValid)
				{
					return true;
				}
			}
		}

		return false;
	}

	private static List<Entity> GetControlledBuildingsSnapshot(PlayerInfo playerInfo)
	{
		List<Entity> list = new List<Entity>();
		foreach (EntityID item in EnumerateControlledBuildingIds(playerInfo))
		{
			Entity entity = item.FindEntity();
			if (entity?.data?.board != null)
			{
				list.Add(entity);
			}
		}
		return list;
	}

	private static IEnumerable<EntityID> EnumerateControlledBuildingIds(PlayerInfo playerInfo)
	{
		if (!TryGetControlledBuildingIds(playerInfo?.territory, out IEnumerable<EntityID> entityIds))
		{
			yield break;
		}

		foreach (EntityID entityId in entityIds)
		{
			if (entityId.IsValid)
			{
				yield return entityId;
			}
		}
	}

	private static bool TryGetControlledBuildingIds(object territory, out IEnumerable<EntityID> entityIds)
	{
		entityIds = null;
		if (territory == null)
		{
			return false;
		}

		ControlledBuildingAccessor controlledBuildingAccessor = GetControlledBuildingAccessor(territory.GetType());
		try
		{
			object value = controlledBuildingAccessor.GetAllControlledBuildingsMethod?.Invoke(territory, null);
			if (value == null)
			{
				value = controlledBuildingAccessor.BuildingsField?.GetValue(territory) ?? controlledBuildingAccessor.BuildingsProperty?.GetValue(territory);
			}
			entityIds = value as IEnumerable<EntityID>;
			return entityIds != null;
		}
		catch
		{
			entityIds = null;
			return false;
		}
	}

	private static ControlledBuildingAccessor GetControlledBuildingAccessor(Type territoryType)
	{
		if (territoryType == null)
		{
			return new ControlledBuildingAccessor(null, null, null);
		}

		if (_controlledBuildingAccessorByTerritoryType.TryGetValue(territoryType, out ControlledBuildingAccessor value))
		{
			return value;
		}

		ControlledBuildingAccessor controlledBuildingAccessor = new ControlledBuildingAccessor(
			territoryType.GetMethod("GetAllControlledBuildingsUnsafe", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic),
			territoryType.GetField("_buildings", BindingFlags.Instance | BindingFlags.NonPublic) ?? territoryType.GetField("buildings", BindingFlags.Instance | BindingFlags.NonPublic),
			territoryType.GetProperty("OwnedBuildings", BindingFlags.Instance | BindingFlags.Public) ?? territoryType.GetProperty("Buildings", BindingFlags.Instance | BindingFlags.Public));
		_controlledBuildingAccessorByTerritoryType[territoryType] = controlledBuildingAccessor;
		return controlledBuildingAccessor;
	}

