	}

	private static int ExtractLocalFixnumAsInt(object fixnum)
	{
		if (fixnum == null)
		{
			return 0;
		}
		try
		{
			return Convert.ToInt32(fixnum);
		}
		catch
		{
		}
		try
		{
			string text = fixnum.ToString();
			if (int.TryParse(text, out int result))
			{
				return result;
			}
			if (float.TryParse(text, out float result2))
			{
				return (int)result2;
			}
		}
		catch
		{
		}
		return 0;
	}

