	private static bool TryCanRunTrySellOutToFeds(PlayerInfo playerInfo, out string reason, out bool suppressLog)
	{
		reason = "allow";
		suppressLog = false;
		if (playerInfo == null)
		{
			reason = "missing-player";
			return false;
		}

		if (playerInfo.territory == null)
		{
			reason = "missing-territory";
			return false;
		}

		Node headquartersNode;
		try
		{
			headquartersNode = playerInfo.territory.GetHeadquartersNode();
		}
		catch (Exception ex)
		{
			reason = "hq-throw-" + ex.GetType().Name;
			return false;
		}

		if (headquartersNode == null)
		{
			reason = "missing-hq-node";
			return false;
		}

		if (CopUtil.FindPrecinctOrNull(headquartersNode) == null)
		{
			reason = "missing-precinct-node";
			return false;
		}

		if (playerInfo.ai?.precinct == null)
		{
			if (GameplayTweaksPlugin.WasMissingFedHintPrecinctSeenToday(playerInfo))
			{
				suppressLog = true;
			}
			else
			{
				GameplayTweaksPlugin.NoteMissingFedHintPrecinct(playerInfo);
			}
			reason = "missing-fed-hint-precinct";
			return false;
		}

		try
		{
			_ = playerInfo.ai.precinct.GetFedHintStatus();
		}
		catch (Exception ex)
		{
			reason = "fed-hint-throw-" + ex.GetType().Name;
			return false;
		}

		return true;
	}

	private static Exception UnwrapInvocationException(Exception ex)
	{
		Exception current = ex;
		while (current is TargetInvocationException targetInvocationException && targetInvocationException.InnerException != null)
		{
			current = targetInvocationException.InnerException;
		}
		return current ?? ex;
	}
}
