	private static Node GetHottestHumanNodeInPrecinct(object precinctAdvisorInstance, PlayerInfo humanPlayer, object precinctId, out int currentHeatValue, out int goalHeatValue, out int candidateCount, out int arrestableCrewCount, out int presentCrewCount, out EntityID manualTargetPeepId, out string reason)
	{
		currentHeatValue = 0;
		goalHeatValue = 0;
		candidateCount = 0;
		arrestableCrewCount = 0;
		presentCrewCount = 0;
		manualTargetPeepId = EntityID.INVALID;
		reason = "no-eligible-candidate";
		if (humanPlayer == null || precinctId == null)
		{
			return null;
		}
		if (IsHumanPaidOffInPrecinct(precinctAdvisorInstance, humanPlayer.PID))
		{
			reason = "precinct-paid-off";
			return null;
		}
		IEnumerable<NodeID> enumerable = (precinctAdvisorInstance as PrecinctAdvisor)?.EnumerateAllBeatNodesInPrecinct();
		if (enumerable == null)
		{
			return null;
		}
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		Node result = null;
		foreach (NodeID item2 in enumerable)
		{
			Node item = item2.FindNode();
			if (item == null || item.HasActiveRaid || !Equals((object)item.precinctId, precinctId))
			{
				continue;
			}
			List<Heat> data = item.heat?.data;
			if (data == null)
			{
				continue;
			}
			foreach (Heat datum in data)
			{
				if (datum == null || !datum.pid.IsHumanPlayer)
				{
					continue;
				}
				PlayerID playerID = item.owner.Get();
				if (playerID.IsAnyPlayer)
				{
					DonationState donationState = GetDonationState(precinctAdvisorInstance, playerID);
					if (donationState == DonationState.PaidOff || donationState == DonationState.WaitingForRefresh)
					{
						flag = true;
						continue;
					}
				}
				if (!TryGetRaidPossibility(item, datum, out bool heatAboveThreshold, out int currentHeat, out int goalHeat, out bool recentlyRaided))
				{
					continue;
				}
				if (recentlyRaided)
				{
					flag2 = true;
					continue;
				}
				if (!heatAboveThreshold)
				{
					flag3 = true;
					continue;
				}
				List<HeatCheck> list = new List<HeatCheck>();
				try
				{
					_checkNodeForRaidsMethod.Invoke(null, new object[3] { precinctAdvisorInstance, item, list });
				}
				catch (Exception ex)
				{
					Debug.LogWarning("[GameplayTweaks] CheckNodeForRaids invoke failed: " + ex.Message);
				}
				foreach (HeatCheck item3 in list)
				{
					if (item3.pid != humanPlayer.PID && !item3.pid.IsHumanPlayer)
					{
						continue;
					}
					candidateCount++;
					int num = GameplayTweaksPlugin.ReadFixnum(item3.val);
					if (result != null)
					{
						if (num < currentHeatValue)
						{
							continue;
						}
						if (num == currentHeatValue && goalHeat < goalHeatValue)
						{
							continue;
						}
						if (num == currentHeatValue && goalHeat == goalHeatValue && string.CompareOrdinal(item.id.ToString(), result.id.ToString()) >= 0)
						{
							continue;
						}
					}
					result = item;
					currentHeatValue = num;
					goalHeatValue = goalHeat;
				}
			}
		}
		if (result == null)
		{
			if (flag)
			{
				reason = "precinct-paid-off";
			}
			else if (flag2)
			{
				reason = "recently-raided";
			}
			else if (flag3)
			{
				reason = "below-threshold";
			}
			return null;
		}
		if (!TryGetHumanCrewPresenceAtNode(result, humanPlayer, out presentCrewCount, out arrestableCrewCount, out manualTargetPeepId))
		{
			presentCrewCount = 0;
			arrestableCrewCount = 0;
			manualTargetPeepId = EntityID.INVALID;
		}
		reason = (presentCrewCount > 0) ? "eligible" : "no-present-crew";
		return result;
	}

	private static bool IsHumanCornerHeatRaidNode(PlayerInfo humanPlayer, object precinctId, Node node, out int heatValue)
	{
		heatValue = 0;
		if (humanPlayer == null || precinctId == null || node == null)
		{
			return false;
		}
		if (node.HasActiveRaid)
		{
			return false;
		}
		object value = node.GetType().GetField("precinctId", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(node);
		if (value == null || !Equals(value, precinctId))
		{
			return false;
		}
		return IsNodeAtHumanRaidThreshold(node, humanPlayer.PID, out heatValue);
	}

	private static bool HasArrestableHumanCrewAtNode(Node node, PlayerInfo humanPlayer, out int crewCount)
