	private static bool TryGetHumanCrewPresenceAtNode(Node node, PlayerInfo humanPlayer, out int presentCrewCount, out int arrestableCrewCount, out EntityID manualTargetPeepId)
	{
		presentCrewCount = 0;
		arrestableCrewCount = 0;
		manualTargetPeepId = EntityID.INVALID;
		if (node == null || humanPlayer?.crew == null)
		{
			return false;
		}
		try
		{
			int onFootLocalCount = 0;
			var localVehicleOccupants = new Dictionary<long, int>();
			var localVehicleNodeIds = new Dictionary<long, NodeID>();
			var evaluatedVehicleIds = new HashSet<long>();
			foreach (CrewAssignment item in humanPlayer.crew.GetLiving())
			{
				if (!item.IsValid || !item.peepId.IsValid)
				{
					continue;
				}
				if (GameplayTweaksPlugin.IsCrewHiddenOrHideoutPending(item.peepId))
				{
					continue;
				}
				CrewModState crewStateOrNull = GameplayTweaksPlugin.GetCrewStateOrNull(item.peepId);
				if ((crewStateOrNull != null && crewStateOrNull.InJail) || GameplayTweaksPlugin.JailSystem.IsInJail(item.peepId) || !humanPlayer.crew.IsOnBoard(item.peepId))
				{
					continue;
				}
				Entity peep = item.GetPeep();
				if (peep == null || CopUtil.IsCop(item.peepId))
				{
					continue;
				}
				if (item.IsInVehicle && item.VehicleID.IsValid)
				{
					long vehicleKey = (long)item.VehicleID.id;
					if (!evaluatedVehicleIds.Contains(vehicleKey))
					{
						evaluatedVehicleIds.Add(vehicleKey);
						if (!MultiCrewVehicleHelper.TryGetAuthoritativeVehicleNodeId(item.VehicleID, out NodeID vehicleNodeId, out _)
							|| vehicleNodeId != node.id)
						{
							GameplayTweaksPlugin.VerificationLog("CornerHeatRaid", $"raid-vehicle-filter vehicle={item.VehicleID.id} counted=false reason=off-corner");
							continue;
						}
						localVehicleNodeIds[vehicleKey] = vehicleNodeId;
						localVehicleOccupants[vehicleKey] = 0;
					}
					if (!localVehicleOccupants.ContainsKey(vehicleKey))
					{
						continue;
					}
					localVehicleOccupants[vehicleKey]++;
					arrestableCrewCount++;
					if (manualTargetPeepId.IsNotValid)
					{
						manualTargetPeepId = item.peepId;
					}
					continue;
				}
				Node node2 = peep.components?.agent?.GetNode();
				if (node2 == null)
				{
					NodeID peepNodeId = peep.data?.agent?.nid ?? NodeID.INVALID;
					node2 = peepNodeId.IsValid ? peepNodeId.FindNode() : null;
				}
				if (node2 == null || node2.id != node.id)
				{
					continue;
				}
				onFootLocalCount++;
				arrestableCrewCount++;
				if (manualTargetPeepId.IsNotValid)
				{
					manualTargetPeepId = item.peepId;
				}
			}
			presentCrewCount = onFootLocalCount + localVehicleOccupants.Count;
			foreach (KeyValuePair<long, int> item2 in localVehicleOccupants)
			{
				NodeID value = localVehicleNodeIds.TryGetValue(item2.Key, out NodeID localNodeId) ? localNodeId : node.id;
				GameplayTweaksPlugin.VerificationLog("CornerHeatRaid", $"raid-locality vehicle={item2.Key} node={value} occupantsLocal={item2.Value}");
			}
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryGetHumanCrewPresenceAtNode failed: " + ex.Message);
		}
		return presentCrewCount > 0;
	}

	internal static bool IsCrewAssignmentPhysicallyAtNode(PlayerInfo player, CrewAssignment crew, NodeID targetNodeId)
	{
		if (player?.crew == null || !crew.IsValid || !crew.peepId.IsValid || !targetNodeId.IsValid)
		{
			return false;
		}
		CrewModState crewStateOrNull = GameplayTweaksPlugin.GetCrewStateOrNull(crew.peepId);
		if ((crewStateOrNull != null && crewStateOrNull.InJail) || GameplayTweaksPlugin.JailSystem.IsInJail(crew.peepId) || !player.crew.IsOnBoard(crew.peepId))
		{
			return false;
		}
		try
		{
			if (crew.IsInVehicle && crew.VehicleID.IsValid)
			{
				return MultiCrewVehicleHelper.TryGetAuthoritativeVehicleNodeId(crew.VehicleID, out NodeID vehicleNodeId, out _) && vehicleNodeId == targetNodeId;
			}
			Entity peep = crew.GetPeep();
			Node peepNode = peep?.components?.agent?.GetNode();
			if (peepNode == null)
			{
				NodeID peepNodeId = peep?.data?.agent?.nid ?? NodeID.INVALID;
				peepNode = peepNodeId.IsValid ? peepNodeId.FindNode() : null;
			}
			return peepNode != null && peepNode.id == targetNodeId;
		}
		catch
		{
			return false;
		}
	}

	internal static bool ShouldAllowPendingCornerHeatRaidArrest(PlayerInfo player, CrewAssignment crew, out string reason)
	{
		reason = "allow";
		if (player == null || !player.PID.IsHumanPlayer || !crew.IsValid || !GameplayTweaksPlugin._pendingHumanCornerHeatPrecinctRaidActive)
		{
			return true;
		}
		if (GameplayTweaksPlugin.IsCrewHiddenOrHideoutPending(crew.peepId))
		{
			reason = "hideout-pending";
			GameplayTweaksPlugin.VerificationLog("CornerHeatRaid", $"raid-skip-hideout-pending peep={crew.peepId.id} source=start-human-arrest");
			return false;
		}
		if (GameplayTweaksPlugin._pendingHumanCornerHeatRaidHumanPid != player.PID.id)
		{
			return true;
		}
		if (GameplayTweaksPlugin._pendingHumanCornerHeatPrecinctRaidDay != G.GetNow().days)
		{
			GameplayTweaksPlugin.ClearPendingHumanCornerHeatPrecinctRaidContext();
			return true;
		}
		if (!GameplayTweaksPlugin._pendingHumanCornerHeatRaidNodeId.IsValid)
		{
			return true;
		}
		if (IsCrewAssignmentPhysicallyAtNode(player, crew, GameplayTweaksPlugin._pendingHumanCornerHeatRaidNodeId))
		{
			return true;
		}
		reason = "not-local";
		return false;
	}

	internal static bool TryGetCrewCurrentNode(CrewAssignment crew, out Node node)
	{
		node = null;
		if (!crew.IsValid)
		{
			return false;
		}
		try
		{
			if (crew.IsInVehicle && crew.VehicleID.IsValid)
			{
				return MultiCrewVehicleHelper.TryGetCrewCommandNode(crew, out node);
			}
			Entity peep = crew.GetPeep();
			node = peep?.components?.agent?.GetNode();
			return node != null;
		}
		catch
		{
			node = null;
			return false;
		}
	}

	internal static bool TryGetNodeHeatForPlayer(Node node, PlayerID pid, out int heatValue)
	{
		heatValue = 0;
		if (node == null)
		{
			return false;
		}
		try
		{
			if (!TryGetRaidPossibility(node, pid, out _, out int currentHeat, out int goalHeat, out _))
			{
				return false;
			}
			heatValue = Math.Max(currentHeat, goalHeat);
			return true;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryGetNodeHeatForPlayer failed: " + ex.Message);
		}
		return false;
	}

	internal static bool IsNodeAtHumanRaidThreshold(Node node, PlayerID pid, out int heatValue)
	{
		heatValue = 0;
		if (!TryGetRaidPossibility(node, pid, out bool heatAboveThreshold, out int currentHeat, out int goalHeat, out _))
		{
			return false;
		}
		heatValue = Math.Max(currentHeat, goalHeat);
		return heatAboveThreshold;
	}

	private static DonationState GetDonationState(object precinctAdvisorInstance, PlayerID payer)
	{
		try
		{
			object value = _hasDonationFromMethod?.Invoke(precinctAdvisorInstance, new object[1] { payer });
			if (value is DonationState donationState)
			{
				return donationState;
			}
		}
		catch
		{
		}
		return DonationState.NotPaidOff;
	}

	private static bool NodeHasHumanHeat(Node node)
	{
		List<Heat> data = node?.heat?.data;
		if (data == null)
		{
			return false;
		}
		foreach (Heat item in data)
		{
			if (item != null && item.pid.IsHumanPlayer)
			{
				return true;
			}
		}
		return false;
	}

	private static bool TryGetRaidPossibility(Node node, PlayerID pid, out bool heatAboveThreshold, out int currentHeat, out int goalHeat, out bool recentlyRaided)
	{
		return TryGetRaidPossibility(node, node?.heat?.GetOrNull(pid), out heatAboveThreshold, out currentHeat, out goalHeat, out recentlyRaided);
	}

	private static bool TryGetRaidPossibility(Node node, Heat nodeHeat, out bool heatAboveThreshold, out int currentHeat, out int goalHeat, out bool recentlyRaided)
	{
		heatAboveThreshold = false;
		currentHeat = 0;
		goalHeat = 0;
		recentlyRaided = false;
		if (node == null || nodeHeat == null)
		{
			return false;
		}
		try
		{
			object value = null;
			if (_calculateRaidPossibilityFromHeatMethod != null)
			{
				value = _calculateRaidPossibilityFromHeatMethod.Invoke(null, new object[2] { node, nodeHeat });
			}
			else if (_calculateRaidPossibilityMethod != null)
			{
				value = _calculateRaidPossibilityMethod.Invoke(null, new object[2] { node, nodeHeat.pid });
			}
			if (value == null)
			{
				return false;
			}
			heatAboveThreshold = Convert.ToBoolean(_raidPossibilityHeatAboveField?.GetValue(value));
			recentlyRaided = Convert.ToBoolean(_raidPossibilityRecentlyRaidedField?.GetValue(value));
			currentHeat = GameplayTweaksPlugin.ReadFixnum(_raidPossibilityCurrentHeatField?.GetValue(value));
			goalHeat = GameplayTweaksPlugin.ReadFixnum(_raidPossibilityGoalHeatField?.GetValue(value));
			return true;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] TryGetRaidPossibility failed: " + ex.Message);
			return false;
		}
	}

	private static bool IsHumanPaidOffInPrecinct(object precinctAdvisorInstance, PlayerID humanPid)
	{
		if (precinctAdvisorInstance == null || _hasDonationFromMethod == null || !humanPid.IsHumanPlayer)
		{
			return false;
		}
		try
		{
			object value = _hasDonationFromMethod.Invoke(precinctAdvisorInstance, new object[1] { humanPid });
			if (value == null)
			{
				return false;
			}
			string text = value.ToString();
			return text == "PaidOff" || text == "WaitingForRefresh";
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] IsHumanPaidOffInPrecinct failed: " + ex.Message);
			return false;
		}
	}

	private static short? TryReadPlayerId(object playerIdObj)
	{
		if (playerIdObj == null)
		{
			return null;
		}
		try
		{
			FieldInfo field = playerIdObj.GetType().GetField("id", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			object value = field?.GetValue(playerIdObj);
			if (value == null)
			{
				return null;
			}
			return Convert.ToInt16(value);
		}
		catch
		{
			return null;
		}
	}
}
internal static class CopDeathVehicleCleanupPatch
{
	private sealed class CopDeathVehicleState
	{
		internal PlayerInfo Owner;

		internal EntityID PeepId = EntityID.INVALID;

		internal EntityID VehicleId = EntityID.INVALID;
	}

	private static readonly FieldInfo _playerField = typeof(PlayerCrew).GetField("_player", BindingFlags.Instance | BindingFlags.NonPublic);

	public static void ApplyPatch(Harmony harmony)
	{
		try
		{
			MethodInfo processDeath = typeof(PlayerCrew).GetMethod("ProcessCrewMemberDeath", BindingFlags.Instance | BindingFlags.NonPublic, null, new[] { typeof(Entity) }, null);
			MethodInfo markScavengeable = typeof(PlayerCrew).GetMethod("MarkPeepsCarAsScavengeable", BindingFlags.Instance | BindingFlags.Public, null, new[] { typeof(EntityID) }, null);
			MethodInfo produceRequests = typeof(GameClock).Assembly
				.GetType("Game.Session.Player.AI.PrecinctAdvisor")
				?.GetMethod("ProduceRequests", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, new[] { typeof(List<AdvisorRequest>) }, null);
			if (processDeath == null || markScavengeable == null)
			{
				Debug.LogWarning("[GameplayTweaks] CopDeathVehicleCleanupPatch methods not found");
				return;
			}
			harmony.Patch(processDeath, prefix: new HarmonyMethod(typeof(CopDeathVehicleCleanupPatch), nameof(ProcessCrewMemberDeathPrefix)), postfix: new HarmonyMethod(typeof(CopDeathVehicleCleanupPatch), nameof(ProcessCrewMemberDeathPostfix)));
			harmony.Patch(markScavengeable, prefix: new HarmonyMethod(typeof(CopDeathVehicleCleanupPatch), nameof(MarkPeepsCarAsScavengeablePrefix)));
			if (produceRequests != null)
			{
				harmony.Patch(produceRequests, prefix: new HarmonyMethod(typeof(CopDeathVehicleCleanupPatch), nameof(ProduceRequestsPrefix)));
			}
			Debug.Log("[GameplayTweaks] Cop death vehicle cleanup patch applied");
		}
		catch (Exception ex)
		{
			Debug.LogError("[GameplayTweaks] CopDeathVehicleCleanupPatch failed: " + ex);
		}
	}

	private static void ProcessCrewMemberDeathPrefix(PlayerCrew __instance, Entity peep, out CopDeathVehicleState __state)
	{
		__state = null;
		try
		{
			PlayerInfo owner = _playerField?.GetValue(__instance) as PlayerInfo;
			if (owner == null || peep == null)
			{
				return;
			}
			__state = new CopDeathVehicleState
			{
				Owner = owner,
				PeepId = peep.Id
			};
			CrewAssignment crew = owner.crew?.GetCrewForPeep(peep.Id) ?? CrewAssignment.EMPTY;
			if (!crew.IsValid || !crew.IsInVehicle || !crew.VehicleID.IsValid)
			{
				return;
			}
			__state.VehicleId = crew.VehicleID;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Cop death vehicle prefix failed: " + ex.Message);
		}
	}

	private static void ProcessCrewMemberDeathPostfix(PlayerCrew __instance, Entity peep, CopDeathVehicleState __state)
	{
		_ = __instance;
		_ = peep;
		try
		{
			if (__state == null || __state.Owner == null)
			{
				return;
			}
			if (__state.Owner.IsJustCop && __state.VehicleId.IsValid)
			{
				GameplayTweaksPlugin.TryHandleDeadCopVehicleCleanup(__state.Owner, __state.PeepId, __state.VehicleId, "death-postfix");
			}
			GameplayTweaksPlugin.DirtyCashEconomyCompatibilityPatch.NotifyGangMemberDeathForTerritoryAudit(__state.Owner, "death-postfix");
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Cop death vehicle postfix failed: " + ex.Message);
		}
	}

	private static bool MarkPeepsCarAsScavengeablePrefix(PlayerCrew __instance, EntityID peep)
	{
		try
		{
			PlayerInfo owner = _playerField?.GetValue(__instance) as PlayerInfo;
			if (owner == null || !owner.IsJustCop || peep.IsNotValid)
			{
				return true;
			}
			CrewAssignment crew = owner.crew?.GetCrewForPeep(peep) ?? CrewAssignment.EMPTY;
			if (!crew.IsValid || !crew.IsInVehicle || !crew.VehicleID.IsValid)
			{
				return true;
			}
			GameplayTweaksPlugin.VerificationLog("CopVehicleCleanup", $"cop-death-scavengeable-suppressed peep={peep.id} vehicle={crew.VehicleID.id} ownerPid={owner.PID.id}");
			return false;
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Cop scavengeable suppression failed: " + ex.Message);
			return true;
		}
	}

	private static void ProduceRequestsPrefix(object __instance)
	{
		try
		{
			PlayerInfo owner = AccessTools.Field(__instance.GetType(), "_player")?.GetValue(__instance) as PlayerInfo;
			GameplayTweaksPlugin.ScrubInvalidScavengeableVehiclesForAllPlayers("produce-requests");
			GameplayTweaksPlugin.ScrubCopScavengeableVehicles(owner, "produce-requests");
			GameplayTweaksPlugin.ReconcileCopPrecinctOfficers(owner, "produce-requests");
		}
		catch (Exception ex)
		{
			Debug.LogWarning("[GameplayTweaks] Cop recovery produce-request scrub failed: " + ex.Message);
		}
	}
}
