	private static void EnsureVehicleCrewIndicator(Transform footerRoot, Transform interactButtonsRoot, Entity currentPeep)
	{
		if ((UnityEngine.Object)(object)footerRoot == (UnityEngine.Object)null || (UnityEngine.Object)(object)interactButtonsRoot == (UnityEngine.Object)null || currentPeep == null)
		{
			return;
		}
		Entity indicatorPeep = ResolveVehicleInspectPeep(currentPeep, out EntityID vehicleId, out string reason);
		if (indicatorPeep == null)
		{
			if (vehicleId.IsValid)
			{
				GameplayTweaksPlugin.VerificationLog("CrewInfoButtons", $"inspect-vehicle-empty vehicle={vehicleId.id} peep={currentPeep.Id.id} reason={reason}");
			}
			return;
		}
		if (!GameplayTweaks.MultiCrewVehicleHelper.TryGetEnemyVehicleCrewIndicator(indicatorPeep, out string indicator, out _))
		{
			return;
		}
		if (indicatorPeep != currentPeep)
		{
			GameplayTweaksPlugin.VerificationLog("CrewInfoButtons", $"inspect-vehicle-normalized vehicle={vehicleId.id} from={currentPeep.Id.id} to={indicatorPeep.Id.id} reason={reason}");
		}

		GameObject gameObject = new GameObject(VehicleCrewInfoName, typeof(RectTransform));
		gameObject.transform.SetParent(footerRoot, false);
		RectTransform component = gameObject.GetComponent<RectTransform>();
		component.anchorMin = new Vector2(0.5f, 1f);
		component.anchorMax = new Vector2(0.5f, 1f);
		component.pivot = new Vector2(0.5f, 1f);
		component.anchoredPosition = new Vector2(0f, -2f);
		component.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, ((RectTransform)interactButtonsRoot).rect.width);
		component.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, 18f);

		TextMeshProUGUI componentInChildren = ((Component)interactButtonsRoot).GetComponentInChildren<TextMeshProUGUI>(includeInactive: true);
		TextMeshProUGUI textMeshProUGUI = gameObject.AddComponent<TextMeshProUGUI>();
		if ((UnityEngine.Object)(object)componentInChildren != (UnityEngine.Object)null)
		{
			textMeshProUGUI.font = componentInChildren.font;
			textMeshProUGUI.fontSharedMaterial = componentInChildren.fontSharedMaterial;
			((Graphic)textMeshProUGUI).color = ((Graphic)componentInChildren).color;
			textMeshProUGUI.enableWordWrapping = false;
		}
		textMeshProUGUI.alignment = TextAlignmentOptions.Center;
		textMeshProUGUI.fontSize = 15f;
		textMeshProUGUI.raycastTarget = false;
		textMeshProUGUI.text = indicator;
	}

	private static Entity ResolveVehicleInspectPeep(Entity currentPeep, out EntityID vehicleId, out string reason)
	{
		vehicleId = EntityID.INVALID;
		reason = "not-vehicle";
		if (currentPeep == null)
