		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			Transform child = componentsInChildren[i];
			if ((UnityEngine.Object)(object)child != (UnityEngine.Object)null && string.Equals(((UnityEngine.Object)child).name, childName, StringComparison.Ordinal))
			{
				list.Add(((Component)child).gameObject);
