	private static GameObject GetFooterButtonByName(Transform root, params string[] childNames)
	{
		if ((UnityEngine.Object)(object)root == (UnityEngine.Object)null || childNames == null || childNames.Length == 0)
		{
			return null;
		}
		for (int i = 0; i < childNames.Length; i++)
		{
			Transform val = root.Find(childNames[i]);
			if ((UnityEngine.Object)(object)val != (UnityEngine.Object)null && (UnityEngine.Object)(object)((Component)val).GetComponent<Button>() != (UnityEngine.Object)null)
			{
				return ((Component)val).gameObject;
			}
		}
		string[] array = childNames.Select((string n) => NormalizeName(n)).ToArray();
		for (int j = 0; j < root.childCount; j++)
		{
			Transform child = root.GetChild(j);
			if ((UnityEngine.Object)(object)child == (UnityEngine.Object)null || (UnityEngine.Object)(object)((Component)child).GetComponent<Button>() == (UnityEngine.Object)null)
			{
				continue;
			}
			string text = NormalizeName(((UnityEngine.Object)child).name);
			for (int k = 0; k < array.Length; k++)
			{
				if (text.Contains(array[k]))
				{
					return ((Component)child).gameObject;
				}
			}
		}
		return null;
	}

	private static string NormalizeName(string value)
	{
		if (string.IsNullOrEmpty(value))
		{
			return string.Empty;
		}
		return value.Replace(" ", string.Empty).Replace("-", string.Empty).Replace("_", string.Empty).Trim().ToLowerInvariant();
	}

	private static string SanitizeUiGlyphText(string raw, bool aggressive)
	{
		if (string.IsNullOrEmpty(raw))
		{
			return string.Empty;
		}
		string text = raw.Replace("\uFFFD", string.Empty);
		if (aggressive || GameplayTweaksPlugin.ExternalCustomIconsDetected)
		{
			text = text.Replace("\u25A1", string.Empty);
		}
		return text;
	}

	private static void SanitizeMissingGlyphsInHierarchy(GameObject root, bool aggressive)
	{
		if ((UnityEngine.Object)(object)root == (UnityEngine.Object)null)
