			}

			string sanitized = SanitizeUiGlyphText(item.text, aggressive);
			if (!string.Equals(sanitized, item.text, StringComparison.Ordinal))
			{
				item.text = sanitized;
			}
		}

		foreach (TMP_Text item2 in root.GetComponentsInChildren<TMP_Text>(true))
		{
			if ((UnityEngine.Object)(object)item2 == (UnityEngine.Object)null)
			{
				continue;
			}

			string sanitized2 = SanitizeUiGlyphText(item2.text, aggressive);
			if (!string.Equals(sanitized2, item2.text, StringComparison.Ordinal))
			{
				item2.text = sanitized2;
			}
		}
	}

	private static void NormalizeFooterButtonSizesAndBounds(Transform footerRoot, Transform interactButtonsRoot, List<GameObject> orderedButtons)
	{
		if ((UnityEngine.Object)(object)footerRoot == (UnityEngine.Object)null || (UnityEngine.Object)(object)interactButtonsRoot == (UnityEngine.Object)null || orderedButtons == null || orderedButtons.Count == 0)
		{
			return;
		}
		HorizontalLayoutGroup component = ((Component)interactButtonsRoot).GetComponent<HorizontalLayoutGroup>() ?? ((Component)interactButtonsRoot).gameObject.AddComponent<HorizontalLayoutGroup>();
		((HorizontalOrVerticalLayoutGroup)component).spacing = 2f;
		((HorizontalOrVerticalLayoutGroup)component).childForceExpandWidth = false;
		((HorizontalOrVerticalLayoutGroup)component).childForceExpandHeight = false;
		((HorizontalOrVerticalLayoutGroup)component).childControlWidth = true;
		((HorizontalOrVerticalLayoutGroup)component).childControlHeight = true;
		component.childAlignment = TextAnchor.MiddleCenter;
		((LayoutGroup)component).padding = new RectOffset(0, 0, 0, 0);
		float num = 6f;
		float num2 = ((RectTransform)interactButtonsRoot).rect.width;
		Rect val3 = default(Rect);
		if (TryGetFirstWorldRectByNames(footerRoot, new string[6] { "PrevCrew", "Prev Crew", "Prev", "ArrowLeft", "LeftArrow", "Back" }, out var rect) && TryGetFirstWorldRectByNames(footerRoot, new string[6] { "NextCrew", "Next Crew", "Next", "ArrowRight", "RightArrow", "Forward" }, out var val) && TryGetFirstWorldRectByNames(footerRoot, new string[3] { "Officer Signature", "Officer", "Signature" }, out var val2))
		{
			float num3 = rect.xMax + num;
			float num4 = Mathf.Min(val.xMin, val2.xMin) - num;
			if (num4 > num3 + 64f)
			{
				num2 = num4 - num3;
				if (TryGetWorldRect(interactButtonsRoot, out val3))
				{
					Vector3 val4 = new Vector3((num3 + num4) * 0.5f, val3.center.y, 0f);
					RectTransform val5 = ((Component)interactButtonsRoot).transform.parent as RectTransform;
					if ((UnityEngine.Object)(object)val5 != (UnityEngine.Object)null)
					{
						Vector2 val6;
						RectTransformUtility.ScreenPointToLocalPointInRectangle(val5, RectTransformUtility.WorldToScreenPoint((Camera)null, val4), (Camera)null, out val6);
						RectTransform val7 = (RectTransform)interactButtonsRoot;
						val7.anchorMin = new Vector2(0.5f, val7.anchorMin.y);
						val7.anchorMax = new Vector2(0.5f, val7.anchorMax.y);
						val7.pivot = new Vector2(0.5f, val7.pivot.y);
						val7.anchoredPosition = new Vector2(val6.x, val7.anchoredPosition.y);
					}
				}
			}
		}
		int count = orderedButtons.Count;
		float num5 = 2f;
		float num6 = Mathf.Floor((num2 - num5 * (float)(count - 1)) / (float)count);
		float num7 = Mathf.Clamp(num6, 24f, 40f);
		float num8 = 26f;
		RectTransform val8 = (RectTransform)interactButtonsRoot;
		val8.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, num7 * (float)count + num5 * (float)(count - 1));
		for (int i = 0; i < orderedButtons.Count; i++)
		{
			GameObject val9 = orderedButtons[i];
			if ((UnityEngine.Object)(object)val9 == (UnityEngine.Object)null)
			{
				continue;
			}
			LayoutElement component2 = val9.GetComponent<LayoutElement>();
			if ((UnityEngine.Object)(object)component2 == (UnityEngine.Object)null)
			{
				component2 = val9.AddComponent<LayoutElement>();
			}
			component2.minWidth = num7;
			component2.preferredWidth = num7;
			component2.flexibleWidth = 0f;
			component2.minHeight = num8;
			component2.preferredHeight = num8;
			RectTransform component3 = val9.GetComponent<RectTransform>();
			if ((UnityEngine.Object)(object)component3 != (UnityEngine.Object)null)
			{
				component3.localScale = Vector3.one;
				component3.anchoredPosition = Vector2.zero;
			}
		}
	}

	private static bool TryGetWorldRect(Transform t, out Rect rect)
	{
		rect = default(Rect);
		if ((UnityEngine.Object)(object)t == (UnityEngine.Object)null)
		{
			return false;
		}
		RectTransform val = t as RectTransform;
		if ((UnityEngine.Object)(object)val == (UnityEngine.Object)null)
		{
			val = ((Component)t).GetComponent<RectTransform>();
		}
		if ((UnityEngine.Object)(object)val == (UnityEngine.Object)null)
		{
			return false;
		}
		Vector3[] array = new Vector3[4];
		val.GetWorldCorners(array);
		rect = Rect.MinMaxRect(array[0].x, array[0].y, array[2].x, array[2].y);
		return true;
	}

	private static bool TryGetFirstWorldRectByNames(Transform root, IEnumerable<string> names, out Rect rect)
	{
		rect = default(Rect);
		if ((UnityEngine.Object)(object)root == (UnityEngine.Object)null || names == null)
		{
			return false;
		}
		foreach (string name in names)
		{
			Transform val = root.Find(name);
			if ((UnityEngine.Object)(object)val != (UnityEngine.Object)null && TryGetWorldRect(val, out rect))
			{
				return true;
			}
		}
		Transform[] componentsInChildren = ((Component)root).GetComponentsInChildren<Transform>(includeInactive: true);
		foreach (Transform val2 in componentsInChildren)
		{
			if ((UnityEngine.Object)(object)val2 == (UnityEngine.Object)null)
			{
				continue;
			}
			string text = NormalizeName(((UnityEngine.Object)val2).name);
			foreach (string name2 in names)
			{
				if (text.Contains(NormalizeName(name2)) && TryGetWorldRect(val2, out rect))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static string LocKeyToSpriteName(string locKey)
	{
		if (string.IsNullOrEmpty(locKey) || !locKey.EndsWith(".icon", StringComparison.OrdinalIgnoreCase))
		{
			return null;
		}
		string baseName = locKey.Substring(0, locKey.Length - 5);
		if (baseName.StartsWith("res.", StringComparison.OrdinalIgnoreCase))
		{
			return baseName.Substring(4);
		}
		return baseName;
	}

	private static string ExtractSpriteNameFromLocText(string locText)
	{
		if (string.IsNullOrEmpty(locText))
		{
			return null;
		}
		const string marker = "name=\"";
		int start = locText.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
		if (start < 0)
		{
			return null;
		}
		start += marker.Length;
		int end = locText.IndexOf('"', start);
		if (end <= start)
		{
			return null;
		}
		return locText.Substring(start, end - start);
	}

