	private static TextMeshProUGUI FindNearestTemplateTmp(Transform buttonRoot, TextMeshProUGUI exclude)
	{
		Transform cursor = buttonRoot;
		while ((UnityEngine.Object)(object)cursor != (UnityEngine.Object)null)
		{
