				TextMeshProUGUI candidate = texts[i];
				if ((UnityEngine.Object)(object)candidate != (UnityEngine.Object)null && (UnityEngine.Object)(object)candidate != (UnityEngine.Object)(object)exclude)
				{
					return candidate;
				}
			}
			cursor = cursor.parent;
		}
		return null;
	}

