	private static Sprite TryGetUISpriteFromAtlas(string spriteName)
	{
		if (string.IsNullOrEmpty(spriteName))
		{
			return null;
		}
		object ctx = G.GetCtx();
		if (ctx == null)
		{
			return null;
		}
		FieldInfo hudField = ctx.GetType().GetField("hud");
		if (hudField == null)
		{
			return null;
		}
		object hud = hudField.GetValue(ctx);
		if (hud == null)
		{
			return null;
		}
		FieldInfo uispritesField = hud.GetType().GetField("uisprites");
		if (uispritesField == null)
		{
			return null;
		}
		object uisprites = uispritesField.GetValue(hud);
		if (uisprites == null)
		{
			return null;
		}
		FieldInfo uiatlasField = uisprites.GetType().GetField("uiatlas");
		if (uiatlasField == null)
		{
			return null;
		}
		object uiatlas = uiatlasField.GetValue(uisprites);
		if (uiatlas == null)
		{
			return null;
		}
		MethodInfo findMethod = uiatlas.GetType().GetMethod("Find", new Type[] { typeof(string) });
		if (findMethod == null)
		{
			return null;
		}
		object result = findMethod.Invoke(uiatlas, new object[] { spriteName });
		return result as Sprite;
	}

	private static Image ResolveButtonIconImage(Transform buttonRoot)
	{
		if ((UnityEngine.Object)(object)buttonRoot == (UnityEngine.Object)null)
		{
			return null;
