			if ((UnityEngine.Object)(object)sprite == (UnityEngine.Object)null && spriteName.IndexOf(".", StringComparison.Ordinal) < 0 && locKey.StartsWith("res.", StringComparison.OrdinalIgnoreCase))
			{
