		}
		if ((UnityEngine.Object)(object)iconImage != (UnityEngine.Object)null && (UnityEngine.Object)(object)sprite != (UnityEngine.Object)null)
		{
			ClearInheritedModButtonVisuals(buttonGo.transform, null, iconImage);
