			buttonIconTextTarget.fontStyle = FontStyle.Bold;
			buttonIconTextTarget.alignment = TextAnchor.MiddleCenter;
			string text3 = locKey + "@" + text2;
			if (!flag && _missingIconLogKeys.Add(text3))
