			}
			return;
		}
		TextMeshProUGUI tmpTarget = ResolveButtonIconTMPTarget(buttonGo.transform);
		if ((UnityEngine.Object)(object)tmpTarget != (UnityEngine.Object)null)
		{
			tmpTarget.text = displayText;
			tmpTarget.fontSize = 11;
			tmpTarget.fontStyle = FontStyles.Bold;
