			}
			if ((UnityEngine.Object)(object)interactButtonsRoot == (UnityEngine.Object)null)
			{
				interactButtonsRoot = FindBestButtonRail(footerRoot);
			}
			if ((UnityEngine.Object)(object)interactButtonsRoot != (UnityEngine.Object)null)
