internal static class PersonNameSanitizerPatch
{
	private static readonly FieldInfo PersonFullNameField = AccessTools.Field(typeof(PersonData), "_fullname");

	private static readonly FieldInfo PersonShortNameField = AccessTools.Field(typeof(PersonData), "_shortname");

	private static string SanitizeRuntimePersonName(string raw)
	{
		if (string.IsNullOrEmpty(raw))
		{
			return string.Empty;
		}

		string text = raw.Replace("\uFFFD", string.Empty).Trim();
		if (string.IsNullOrEmpty(text))
		{
			return string.Empty;
		}

		if (LooksLikeMojibakeName(text))
		{
			string repaired = TryRepairMojibakeName(text);
			if (!string.IsNullOrEmpty(repaired))
			{
				text = repaired;
			}
		}

		return text.Replace("\uFFFD", string.Empty).Trim();
	}

	private static bool LooksLikeMojibakeName(string value)
	{
		if (string.IsNullOrEmpty(value))
		{
			return false;
		}

		for (int i = 0; i < value.Length; i++)
		{
			switch (value[i])
			{
			case 'Ã':
			case 'Å':
			case 'Ä':
			case 'Æ':
			case 'Ð':
			case 'Ñ':
			case 'Ø':
			case 'Þ':
				return true;
			}
		}

		return false;
	}

	private static string TryRepairMojibakeName(string value)
	{
		try
		{
			byte[] bytes = Encoding.GetEncoding(1252).GetBytes(value);
			string text = Encoding.UTF8.GetString(bytes);
			if (string.IsNullOrWhiteSpace(text))
			{
				return value;
			}

			return GetRuntimeNameCorruptionScore(text) < GetRuntimeNameCorruptionScore(value) ? text.Trim() : value;
		}
		catch
		{
			return value;
		}
	}

	private static int GetRuntimeNameCorruptionScore(string value)
	{
		if (string.IsNullOrEmpty(value))
		{
			return 0;
		}

		int num = 0;
		for (int i = 0; i < value.Length; i++)
		{
			char c = value[i];
			if (c == '\uFFFD')
			{
				num += 10;
				continue;
			}

			switch (c)
			{
			case 'Ã':
			case 'Å':
			case 'Ä':
			case 'Æ':
			case 'Ð':
			case 'Ñ':
			case 'Ø':
			case 'Þ':
				num += 3;
				break;
			}
		}

		return num;
	}

