internal static class TraitLocalizationSanitizerPatch
{
	private static string SanitizeUiGlyphText(string raw, bool aggressive)
	{
		if (string.IsNullOrEmpty(raw))
		{
			return string.Empty;
		}

		string text = raw.Replace("\uFFFD", string.Empty);
		if (aggressive || GameplayTweaksPlugin.ExternalCustomIconsDetected)
		{
			text = text.Replace("\u25A1", string.Empty);
		}
		return text;
	}

	private static string SanitizeTraitText(string raw, bool aggressive)
	{
		if (string.IsNullOrEmpty(raw))
		{
			return string.Empty;
		}

		string text = SanitizeUiGlyphText(raw, aggressive);
		if (string.IsNullOrEmpty(text))
		{
			return string.Empty;
		}

		StringBuilder stringBuilder = new StringBuilder(text.Length);
		for (int i = 0; i < text.Length; i++)
		{
			char c = text[i];
			if (char.IsControl(c) && !char.IsWhiteSpace(c))
			{
				continue;
			}
			stringBuilder.Append(c);
		}

		return stringBuilder.ToString().Trim();
	}

