internal static class PersonInfoTextSanitizerPatch
{
	private static string SanitizePersonInfoLinePrefixes(string raw)
	{
		if (string.IsNullOrEmpty(raw))
		{
			return string.Empty;
		}

		string[] lines = raw.Replace("\r\n", "\n").Split('\n');
		for (int i = 0; i < lines.Length; i++)
		{
			string line = lines[i];
			if (string.IsNullOrEmpty(line))
			{
				continue;
			}

			if (line.Length > 0 && line[0] == '\uFFFD')
			{
				lines[i] = line.Substring(1).TrimStart();
				continue;
			}

			if (line.Length > 0 && line[0] == '·')
			{
				lines[i] = line.Substring(1).TrimStart();
			}
		}

		return string.Join("\n", lines);
	}

	[HarmonyPatch(typeof(PersonInfoUtil), "GenerateTraitsList")]
	[HarmonyPostfix]
	private static void GenerateTraitsListPostfix(ref string __result)
	{
		__result = SanitizePersonInfoLinePrefixes(__result);
	}
}
