public class PopupDragHandler : MonoBehaviour
{
	public RectTransform rectTransform;

	private Vector2 _dragOffset;

	private bool _isDragging;

	private bool _suppressDragUntilMouseRelease;

	private void OnEnable()
	{
		_isDragging = false;
		_suppressDragUntilMouseRelease = Input.GetMouseButton(0);
	}

	private void Update()
	{

		if ((UnityEngine.Object)(object)rectTransform == (UnityEngine.Object)null)
		{
			return;
		}
		if (_suppressDragUntilMouseRelease)
		{
			if (!Input.GetMouseButton(0))
			{
				_suppressDragUntilMouseRelease = false;
			}
			return;
		}
		if (_isDragging && !Input.GetMouseButton(0))
		{
			_isDragging = false;
		}
		Vector2 val = default(Vector2);
		if (Input.GetMouseButtonDown(0)
			&& RectTransformUtility.RectangleContainsScreenPoint(rectTransform, (Vector2)Input.mousePosition, (Camera)null)
			&& RectTransformUtility.ScreenPointToLocalPointInRectangle(rectTransform, (Vector2)Input.mousePosition, (Camera)null, out val))
		{
			float y = val.y;
			Rect rect = rectTransform.rect;
			if (y > rect.height / 2f - 40f)
			{
				_isDragging = true;
				_dragOffset = (Vector2)rectTransform.position - (Vector2)Input.mousePosition;
			}
		}
		if (Input.GetMouseButtonUp(0))
		{
			_isDragging = false;
		}
		if (_isDragging)
		{
			rectTransform.position = (Vector3)((Vector2)Input.mousePosition + _dragOffset);
		}
	}
}}
